def _sentence_query_mask(method):
    """Forbid checked query execution while a sentence path is active.

    Permission is model-local and transient. Captured computation must not
    mutate the host flag: the query guard rejects tracing directly, while this
    host wrapper protects compiled calls and eager islands alike. A nested
    boundary therefore cannot widen permission from inside a sentence path.
    """
    @wraps(method)
    def masked(self, *args, **kwargs):
        if torch.compiler.is_compiling():
            return method(self, *args, **kwargs)
        depth = self._query_sentence_depth
        self._query_sentence_depth = depth + 1
        try:
            return method(self, *args, **kwargs)
        finally:
            self._query_sentence_depth = depth
    return masked


def _append_observed_meaning(store, clause, *, trust=0.0, expectation=None, stream=-1):
    """Write the completed field with caller-owned provenance."""
    kind = 'question' if clause.meaning.mode == 'interrogative' else 'observation'
    return store.write_clause(clause, trust=trust, kind=kind, stream=stream,
        evidence=clause.evidence, expectation=expectation)


def _is_external_expectation_observation(discourse):
    """Whether this boundary may create or bind prediction provenance.

    LTM provisioning runs the ordinary parse/write path while deliberately
    suspending the external discourse stream.  Its rows are source material,
    not new observations, so they must neither retain an estimate nor bind an
    occurrence into a caller's prediction context.
    """
    return bool(
        discourse is not None
        and getattr(discourse, "expectation_enabled", False)
        and not getattr(discourse, "_external_observations_suspended", False))


def _boundary_observation_view(language, registry, entries, payloads, depths,
                               *, structured, clauses=None):
    """Return owned meanings plus the appropriate live predictor view.

    Physical STM is newest-first, while a selected grammatical relation owns
    canonical infix roles.  A batch with at least one selected relation is
    normalized to explicit infix roles for structured prediction, including
    its unselected rows; that preserves their old adapter result while keeping
    one batch call and its chronological boundary.  Root-only prediction keeps
    its established physical payload contract.
    """
    meanings, selected = [], []
    entries = tuple(entries or ())
    form = getattr(language, "program_meaning", None)
    for b, payload in enumerate(payloads):
        depth = int(depths[b]) if b < len(depths) else 0
        if payload is None or depth < 1:
            meanings.append(None)
            selected.append(False)
            if clauses is not None:
                clauses.append(None)
            continue
        entry = entries[b] if b < len(entries) else None
        meaning = form(entry, registry) if callable(form) and registry is not None else None
        clause = None
        if entry is not None:
            from ClauseJournal import finish_clause
            clause = finish_clause(language, entry, meaning=meaning,
                depth=depth, registry=registry)
            meaning = clause.meaning
        if clauses is not None:
            clauses.append(clause)
        is_selected = meaning is not None
        if meaning is None:
            meaning = ConceptualMeaning.from_payload(
                payload, depth=depth, layout="stm", mode="unspecified")
        meanings.append(meaning)
        selected.append(is_selected)
    if structured and any(selected):
        return (
            meanings,
            [None if meaning is None else meaning.roles for meaning in meanings],
            [0 if meaning is None else 3 for meaning in meanings],
            "infix",
            [None if meaning is None else meaning.role_mask for meaning in meanings],
        )
    return meanings, payloads, depths, "stm", None


