@dataclass(frozen=True)
class SelectedThoughtResult:
    """One completed ordinary episode for a selected grammatical question.

    ``meaning`` is the final selected grammatical thought, rather than an
    earlier parse carrier.  ``result`` preserves the typed checked boundary
    result that produced its evidence.  The chronological ``ThoughtRecord``
    values remain owned by ``WhatInteractionMemory``; this is only a boundary
    return value, never a second memory or semantic representation.
    """

    meaning: ConceptualMeaning
    evidence: dict
    work: QueryWorkBudget
    records: tuple
    result: ThoughtResult | None = None

    @property
    def support_true(self):
        return float(self.evidence.get("support_true", 0.0))

    @property
    def support_false(self):
        return float(self.evidence.get("support_false", 0.0))

    @property
    def confidence(self):
        return max(self.support_true, self.support_false)

    @property
    def posture(self):
        return ("BOTH" if min(self.support_true, self.support_false) >= .5 else
                "TRUE" if self.support_true >= .5 else
                "FALSE" if self.support_false >= .5 else "UNKNOWN")


def _checkpoint_host_copy(value):
    """Detach a pure-Python checkpoint sidecar from live mutable state.

    Structural dictionaries are intentionally not ``nn.Module`` state, but
    several of them contain tensors (sparse edge values, LBG accumulators,
    promotion evidence).  Copy tensors to CPU so the sidecar is portable and
    recurse through the few container types used by the relation stores.
    """
    if torch.is_tensor(value):
        return value.detach().to("cpu").clone()
    if isinstance(value, dict):
        return {
            copy.deepcopy(k): _checkpoint_host_copy(v)
            for k, v in value.items()
        }
    if isinstance(value, list):
        return [_checkpoint_host_copy(v) for v in value]
    if isinstance(value, tuple):
        return tuple(_checkpoint_host_copy(v) for v in value)
    if isinstance(value, set):
        return {_checkpoint_host_copy(v) for v in value}
    if isinstance(value, frozenset):
        return frozenset(_checkpoint_host_copy(v) for v in value)
    return copy.deepcopy(value)


def _mps_rng_state_or_none():
    """Return the Metal RNG state when this PyTorch build exposes it."""
    get_state = getattr(getattr(torch, "mps", None), "get_rng_state", None)
    if not callable(get_state):
        return None
    try:
        return get_state().detach().to("cpu").clone()
    except (RuntimeError, AttributeError):
        # CPU-only hosts and older macOS runtimes may expose the Python symbol
        # while having no usable MPS generator.
        return None


def _grammar_rows_for_report(rows):
    """Normalize legacy and batched rule selections for text reporting.

    Signal-router selections are normally ``list[list[int]]`` (one rule
    path per batch row), while the serial SS cursor may expose its shared
    path as ``list[int]``.  Reporting must accept both without mistaking
    every rule id in a shared path for an iterable batch row.
    """
    if torch.is_tensor(rows):
        rows = rows.detach().cpu().tolist()
    if rows is None:
        return []
    if isinstance(rows, (int, np.integer)):
        return [[int(rows)]]
    rows = list(rows)
    if not rows:
        return []
    if isinstance(rows[0], (list, tuple)):
        return [list(row) for row in rows]
    return [rows]


def _grammar_row_preview(row, limit=64):
    """Return ``(head, omitted, tail)`` for a bounded rule-path preview."""
    row = list(row)
    limit = max(2, int(limit))
    if len(row) <= limit:
        return row, 0, []
    n_head = limit // 2
    n_tail = limit - n_head
    return row[:n_head], len(row) - limit, row[-n_tail:]


_GRAD_ANCHORS = {}


def _ensure_grad_anchors(device, dtypes=(torch.float32, torch.float16, torch.bfloat16)):
    """Create the zero scalar leaves ``_carries_with_grad`` adds, eagerly
    (a tensor factory with ``requires_grad=True`` cannot be traced inside
    a compiled region; a module-level tensor is lifted as a graph input)."""
    dev = torch.device(device)
    if dev.type == "cuda" and not torch.cuda.is_available():
        return                                  # policy tests fake the device
    for dtype in dtypes:
        key = (dev.type, dtype)                  # one anchor per device type
        if key not in _GRAD_ANCHORS:
            try:
                _GRAD_ANCHORS[key] = torch.zeros(
                    (), dtype=dtype, device=dev, requires_grad=True)
            except (RuntimeError, AssertionError):
                return                          # created lazily on first use


def _reconstruction_while_loop(condition, body, values):
    """Run the same traversal body under the selected execution backend.

    torch.while_loop captures even when the enclosing model is eager, and
    its uncached backward reconstructs a graph on every trial. With compile
    disabled, ordinary autograd can differentiate these short functional
    loops directly. Explicit compiled execution keeps the existing HOP.
    """
    import util
    if torch.compiler.is_compiling() or util.TheCompileBackend != 'none':
        return torch.while_loop(condition, body, values)
    while bool(condition(*values)):
        values = body(*values)
    return values


def _release_loop_checkpoints(roots=()):
    """Drop the per-trip checkpoints of the ``torch.while_loop`` backward
    nodes reachable from ``roots`` (tensors of a brick whose backward and
    optimizer step have run; call at the next brick's entry).  The HOP's
    autograd node keeps its stacked per-trip outputs, initial carries and
    additional inputs as plain attributes of the node, and the node
    outlives the brick (its consumers hold it from the C++ graph), so
    without this every brick's checkpoints stay resident (about 1.4 GiB
    per brick at B = 8, W = 256).  Only nodes in the given graphs are
    touched: another pending graph's loops are left intact."""
    released = 0
    seen = set()
    stack = [t.grad_fn for t in roots if torch.is_tensor(t) and t.grad_fn is not None]
    while stack:
        node = stack.pop()
        if node is None or id(node) in seen:
            continue
        seen.add(id(node))
        if type(node).__name__ == "WhileLoopAutogradOpBackward":
            for name in ("fw_outputs", "carries", "additional_inputs"):
                if getattr(node, name, None) is not None:
                    try:
                        setattr(node, name, None)
                        released += 1
                    except Exception:
                        pass
        for nxt, _ in getattr(node, "next_functions", ()):
            if nxt is not None and id(nxt) not in seen:
                stack.append(nxt)
    return released


def _carries_with_grad(carries):
    """Loop carries with every floating tensor requiring grad.

    ``torch.while_loop``'s autograd (torch 2.14/2.15 nightlies) marks the
    per-trip checkpoints with the *initial* carry's ``requires_grad``, so a
    carry that enters the loop as plain zeros returns a zero gradient from
    every trip: the chain across trips is cut and parameters used in the
    body are credited from the last trip only (closures loaded mid-loop
    get nothing).  Adding a zero scalar leaf that requires grad (a
    per-device anchor created eagerly by ``_ensure_grad_anchors``) to each
    such carry restores the chain; it is a no-op under ``no_grad``.
    Regression: ``test/test_while_loop_gradients.py``.
    """
    if not torch.is_grad_enabled():
        return tuple(carries)
    out = []
    for c in carries:
        if torch.is_tensor(c) and c.is_floating_point() and not c.requires_grad:
            key = (c.device.type, c.dtype)
            anchor = _GRAD_ANCHORS.get(key)
            if anchor is None:
                if torch.compiler.is_compiling():
                    raise RuntimeError(
                        "no grad anchor for %s %s: call _ensure_grad_anchors "
                        "before compiling" % (c.device, c.dtype))
                _ensure_grad_anchors(c.device, (c.dtype,))
                anchor = _GRAD_ANCHORS[key]
            c = c + anchor
        out.append(c)
    return tuple(out)

class ReverseAdapter(nn.Module):
    """Wrap a module so its reverse() method is called via forward().

    Retained for backwards-compat (tests reference it); the live
    BasicModel reverse path no longer uses it -- explicit
    ``module.reverse(x)`` calls inside ``reverse`` do the job.
    """

    def __init__(self, wrapped):
        super().__init__()
        if isinstance(wrapped, nn.Module):
            self.wrapped = wrapped
        else:
            object.__setattr__(self, "_wrapped_nonmodule", wrapped)
            self.wrapped = None

    def forward(self, subspace):
        target = self.wrapped if self.wrapped is not None else self._wrapped_nonmodule
        return target.reverse(subspace)


class StaticPeerPipeline:
    """Legacy static three-stage peer scheduler.

    The scheduler has a fixed W bucket and no data-dependent queue operations:
    stage A produces PS/WS/CSsub for word ``w``; B consumes the completed
    concept at ``w-1`` for CSsym/SS; C runs Language on B's result at ``w-2``.
    Grammar feedback is a timestamped latch and is deliberately exposed to B
    only at ``source + 2``.  Callbacks return values; only their owning stage
    commits its own runtime storage. It remains the compatibility scheduler for
    older configurations and the generic A/B/C ordering tests. The canonical
    aligned model instead uses
    :meth:`TensorPeerWhilePipeline.run_cs_lanes_banked`, with the same A/B/C
    timing named explicitly as CSSub/CSSym/CSLang.
    """
    # W=8 is the legacy grammar/STM-capacity fallback when a config does not
    # declare an independent word capacity. The remaining widths are the
    # explicit serial-word staging capacities. Keeping all of them peer
    # scheduled avoids silently reverting older grammar fixtures to the
    # pre-pipeline PS->CS->WS loop.
    # XOR_grammar retains its six-word capacity. This static schedule needs
    # no power-of-two arithmetic; admit that existing compatibility bucket
    # without padding away words or increasing the model's capacity.
    WIDTHS = (6, 8, 16, 32, 64, 128, 256, 512, 1024)

    def __init__(self, width):
        width = int(width)
        if width not in self.WIDTHS:
            raise ValueError(f"pipeline width must be one of {self.WIDTHS}, got {width}")
        self.width = width

    def run(self, words, stage_a, stage_b, stage_c, *, capture_trace=True):
        if len(words) != self.width:
            raise ValueError("words must be padded to the pipeline's static width")
        a_fifo = [None] * self.width
        b_fifo = [None] * self.width
        grammar_latch = [None] * self.width
        trace = [] if capture_trace else None
        for tick in range(self.width + 2):
            # A is first: B sees only a completed earlier A result, never a
            # same-word partially-mutated CS lane.
            if tick < self.width:
                a_fifo[tick] = stage_a(words[tick], tick)
                if trace is not None:
                    trace.append(("A", tick))
            b_idx = tick - 1
            if 0 <= b_idx < self.width:
                feedback = (grammar_latch[b_idx - 2]
                            if b_idx >= 2 else None)
                b_fifo[b_idx] = stage_b(a_fifo[b_idx], b_idx, feedback)
                # B results are opaque values (including ordinary tuples).
                # Only Language/C produces grammar feedback; interpreting a
                # two-tuple here would silently corrupt a perfectly valid peer
                # representation.
                if trace is not None:
                    trace.append(("B", b_idx))
            c_idx = tick - 2
            if 0 <= c_idx < self.width:
                # Language owns grammar state and produces the feedback plan.
                # C(source) completes on tick source+2, so B(source+2)
                # observes this exact latch on the following tick.  That is
                # the specified two-symbolic-index delay with no hidden
                # mutable queue.
                feedback = stage_c(b_fifo[c_idx], c_idx)
                if feedback is not None:
                    grammar_latch[c_idx] = feedback
                if trace is not None:
                    trace.append(("C", c_idx))
        return trace


class TensorPeerWhilePipeline:
    """Tensor-only dynamic peer schedulers for compiled word loops.

    The generic :meth:`run` and :meth:`run_banked` methods express the legacy
    A/B/C protocol with :func:`torch.while_loop`, carrying only fixed-shape
    tensors:

    * A computes PS/WS/CSsub for word ``w``.
    * B consumes A's result for ``w - 1`` plus the grammar latch.
    * C consumes B's result for ``w - 2`` and produces the next latch.

    The canonical aligned model uses :meth:`run_cs_lanes_banked` instead. It
    overlaps CSSub/PS/WS for word ``w``, CSSym/SS for ``w - 1``, and CSLang for
    ``w - 2``. Within CSSym, ``CS -> SS -> CS`` is a fixed sequential
    recurrence, not a peer edge.

    The runtime trip count is derived on device from ``active_b_w``.  The
    staged slab may therefore have a generous capacity (for example 256 or
    512 words) without executing its inactive tail and without specializing a
    graph on the longest sentence in each batch.  Sentence rows remain
    independently masked; reverse and the optimizer still run only after the
    longest complete sentence in the batch has drained.

    Stage payloads and ``state`` are tuples of tensors with invariant
    metadata.  Callbacks are invoked on warmup/drain ticks too, but the
    scheduler masks their proposed payload/state updates with the scalar stage
    validity.  A callback must additionally use ``row_gate`` for per-sentence
    masking on a live A tick.
    """

    @staticmethod
    def _tensor_tuple(value, label):
        value = tuple(value)
        if not all(torch.is_tensor(item) for item in value):
            raise TypeError(f"{label} must be a tuple containing only tensors")
        return value

    @staticmethod
    def _select(valid, proposed, prior):
        if len(proposed) != len(prior):
            raise RuntimeError("while-loop tensor state arity changed")
        return tuple(
            torch.where(valid, new, old)
            for new, old in zip(proposed, prior)
        )

    @staticmethod
    def active_trip_count(active_b_w):
        """Return the final active column plus one as a device scalar."""
        if active_b_w.dim() != 2 or active_b_w.dtype is not torch.bool:
            raise ValueError("active_b_w must be a [B,W] bool tensor")
        width = int(active_b_w.shape[1])
        positions = torch.arange(
            1, width + 1, dtype=torch.int64, device=active_b_w.device)
        return torch.where(
            active_b_w.any(dim=0), positions,
            torch.zeros_like(positions)).amax()

    def run(self, words_b_w_d, active_b_w, *,
            state, empty_a, empty_b, empty_feedback,
            stage_a, stage_b, stage_c):
        """Run one dynamic, fully drained peer pipeline.

        Callback signatures are::

            a_payload, state = stage_a(
                word_b_1_d, row_gate_b_1, word_index, stage_live, state)
            b_payload, state = stage_b(
                prior_a, feedback, word_index, stage_live, state)
            feedback, state = stage_c(
                prior_b, word_index, stage_live, state)

        All payloads and state values are fixed-arity tuples of tensors.
        ``word_index`` and ``stage_live`` are scalar device tensors.
        """
        if words_b_w_d.dim() != 3:
            raise ValueError("words_b_w_d must be a [B,W,D] tensor")
        if (active_b_w.dim() != 2
                or tuple(active_b_w.shape) != tuple(words_b_w_d.shape[:2])
                or active_b_w.dtype is not torch.bool):
            raise ValueError(
                "active_b_w must be bool with words_b_w_d's [B,W] shape")
        width = int(words_b_w_d.shape[1])
        if width < 1:
            raise ValueError("the staged word capacity must be positive")

        state = self._tensor_tuple(state, "state")
        empty_a = self._tensor_tuple(empty_a, "empty_a")
        empty_b = self._tensor_tuple(empty_b, "empty_b")
        empty_feedback = self._tensor_tuple(
            empty_feedback, "empty_feedback")
        # Higher-order-op functionalization rejects aliases between carried
        # inputs and callback-captured tensors. Give every carry slot its own
        # binding; this is also the explicit working-state allocation required
        # by the inter-space read-only contract.
        #
        # Transport each carry as a flat buffer and restore its public shape
        # only inside the body. MPS can give an incoming gradient for a
        # 1032-wide view a padded row stride of 1056, while the generated
        # reverse body produces a logical contiguous stride of 1032.
        # ``torch.while_loop`` requires carried metadata (including strides)
        # to remain invariant in both directions. A one-dimensional transport
        # has the same stride in either case and does not change values,
        # callback shapes, or gradients.
        a_shapes = tuple(tuple(item.shape) for item in empty_a)
        b_shapes = tuple(tuple(item.shape) for item in empty_b)
        feedback_shapes = tuple(
            tuple(item.shape) for item in empty_feedback)
        state_shapes = tuple(tuple(item.shape) for item in state)

        def _flatten(items):
            return tuple(item.reshape(-1).clone() for item in items)

        state = _flatten(state)
        empty_a = _flatten(empty_a)
        empty_b = _flatten(empty_b)
        empty_feedback = _flatten(empty_feedback)
        trip_count = self.active_trip_count(active_b_w)
        zero = torch.zeros((), dtype=torch.int64, device=words_b_w_d.device)

        n_a = len(empty_a)
        n_b = len(empty_b)
        n_feedback = len(empty_feedback)
        n_state = len(state)

        def _restore(items, shapes):
            return tuple(
                item.reshape(shape) for item, shape in zip(items, shapes))

        def _unpack(flat):
            offset = 0
            a_value = _restore(
                tuple(flat[offset:offset + n_a]), a_shapes)
            offset += n_a
            b_value = _restore(
                tuple(flat[offset:offset + n_b]), b_shapes)
            offset += n_b
            feedback_value = _restore(
                tuple(flat[offset:offset + n_feedback]), feedback_shapes)
            offset += n_feedback
            state_value = _restore(
                tuple(flat[offset:offset + n_state]), state_shapes)
            return a_value, b_value, feedback_value, state_value

        def cond(tick, remaining, *flat):
            del tick, flat
            return remaining > 0

        def body(tick, remaining, *flat):
            prior_a, prior_b, feedback, current_state = _unpack(flat)

            # Express validity from the carried countdown. Keeping the
            # data-derived trip count out of cond_fn's captured inputs avoids
            # a PyTorch 2.12 AOT alias-analysis false positive.
            a_live = remaining > 2
            gather_index = torch.minimum(
                tick, torch.full_like(tick, width - 1)).reshape(1)
            word = torch.index_select(
                words_b_w_d, 1, gather_index)
            row_gate = torch.index_select(
                active_b_w, 1, gather_index) & a_live
            proposed_a, proposed_state = stage_a(
                word, row_gate, tick, a_live, current_state)
            proposed_a = self._tensor_tuple(proposed_a, "A payload")
            proposed_state = self._tensor_tuple(
                proposed_state, "A state")
            next_a = self._select(
                a_live, proposed_a,
                tuple(torch.zeros_like(item) for item in prior_a))
            after_a = self._select(
                a_live, proposed_state, current_state)

            b_index = tick - 1
            b_live = (tick >= 1) & (remaining > 1)
            proposed_b, proposed_state = stage_b(
                prior_a, feedback, b_index, b_live, after_a)
            proposed_b = self._tensor_tuple(proposed_b, "B payload")
            proposed_state = self._tensor_tuple(
                proposed_state, "B state")
            next_b = self._select(
                b_live, proposed_b,
                tuple(torch.zeros_like(item) for item in prior_b))
            after_b = self._select(b_live, proposed_state, after_a)

            c_index = tick - 2
            c_live = tick >= 2
            proposed_feedback, proposed_state = stage_c(
                prior_b, c_index, c_live, after_b)
            proposed_feedback = self._tensor_tuple(
                proposed_feedback, "grammar feedback")
            proposed_state = self._tensor_tuple(
                proposed_state, "C state")
            next_feedback = self._select(
                c_live, proposed_feedback, feedback)
            after_c = self._select(c_live, proposed_state, after_b)

            return (
                tick + 1, remaining - 1,
                *(item.reshape(-1) for item in next_a),
                *(item.reshape(-1) for item in next_b),
                *(item.reshape(-1) for item in next_feedback),
                *(item.reshape(-1) for item in after_c))

        initial = (
            zero, trip_count + 2,
            *empty_a, *empty_b, *empty_feedback, *state)
        result = torch.while_loop(cond, body, _carries_with_grad(initial))
        _tick, _remaining, *flat_result = result
        _a, _b, feedback, final_state = _unpack(tuple(flat_result))
        return final_state, feedback, trip_count

    def run_banked(self, words_b_w_d, active_b_w, *,
                   stm_state, a_state, b_state,
                   empty_a, empty_b, empty_feedback,
                   stage_a, stage_b, stage_c):
        """Run the same drained schedule with state split by its owner.

        Only the one-word A and B age slots are carried between ticks.  The
        mutable runtime state is held in three disjoint banks:

        * ``stm_state`` -- the six CS-owned STM tensors, read by A and updated
          only by the delayed B/CS commit;
        * ``a_state`` -- CSsub plus the PS contribution slab;
        * ``b_state`` -- CSsym, conceptual contributions, objectives,
          prediction, and reconstruction trace.

        Peer callbacks receive only the banks they read.  Codebooks remain
        ordinary captured module tensors and are therefore shared by
        reference across every fixed fold call; no codebook or ``SubSpace`` is
        copied per word.  Callback signatures are::

            a_payload, next_a_state = stage_a(
                word, row_gate, index, live, a_state, stm_state)
            b_payload, next_b_state, next_stm_state = stage_b(
                prior_a, feedback, index, live, b_state, stm_state)
            next_feedback = stage_c(prior_b, index, live)

        The selects following those peer proposals are the sole owner commit
        block.  This avoids presenting AOT with several aliased proposals for
        the complete recurrent state.
        """
        if words_b_w_d.dim() != 3:
            raise ValueError("words_b_w_d must be a [B,W,D] tensor")
        if (active_b_w.dim() != 2
                or tuple(active_b_w.shape) != tuple(words_b_w_d.shape[:2])
                or active_b_w.dtype is not torch.bool):
            raise ValueError(
                "active_b_w must be bool with words_b_w_d's [B,W] shape")
        width = int(words_b_w_d.shape[1])
        if width < 1:
            raise ValueError("the staged word capacity must be positive")

        stm_state = self._tensor_tuple(stm_state, "STM state")
        a_state = self._tensor_tuple(a_state, "A owner state")
        b_state = self._tensor_tuple(b_state, "B owner state")
        empty_a = self._tensor_tuple(empty_a, "empty_a")
        empty_b = self._tensor_tuple(empty_b, "empty_b")
        empty_feedback = self._tensor_tuple(
            empty_feedback, "empty_feedback")

        a_payload_shapes = tuple(tuple(item.shape) for item in empty_a)
        b_payload_shapes = tuple(tuple(item.shape) for item in empty_b)
        feedback_shapes = tuple(
            tuple(item.shape) for item in empty_feedback)
        stm_shapes = tuple(tuple(item.shape) for item in stm_state)
        a_state_shapes = tuple(tuple(item.shape) for item in a_state)
        b_state_shapes = tuple(tuple(item.shape) for item in b_state)

        def _flatten(items):
            return tuple(item.reshape(-1).clone() for item in items)

        empty_a = _flatten(empty_a)
        empty_b = _flatten(empty_b)
        empty_feedback = _flatten(empty_feedback)
        stm_state = _flatten(stm_state)
        a_state = _flatten(a_state)
        b_state = _flatten(b_state)
        trip_count = self.active_trip_count(active_b_w)
        zero = torch.zeros((), dtype=torch.int64, device=words_b_w_d.device)

        n_a_payload = len(empty_a)
        n_b_payload = len(empty_b)
        n_feedback = len(empty_feedback)
        n_stm = len(stm_state)
        n_a_state = len(a_state)
        n_b_state = len(b_state)

        def _restore(items, shapes):
            return tuple(
                item.reshape(shape) for item, shape in zip(items, shapes))

        def _unpack(flat):
            offset = 0
            a_payload = _restore(
                tuple(flat[offset:offset + n_a_payload]),
                a_payload_shapes)
            offset += n_a_payload
            b_payload = _restore(
                tuple(flat[offset:offset + n_b_payload]),
                b_payload_shapes)
            offset += n_b_payload
            feedback = _restore(
                tuple(flat[offset:offset + n_feedback]),
                feedback_shapes)
            offset += n_feedback
            current_stm = _restore(
                tuple(flat[offset:offset + n_stm]), stm_shapes)
            offset += n_stm
            current_a = _restore(
                tuple(flat[offset:offset + n_a_state]), a_state_shapes)
            offset += n_a_state
            current_b = _restore(
                tuple(flat[offset:offset + n_b_state]), b_state_shapes)
            return (
                a_payload, b_payload, feedback,
                current_stm, current_a, current_b)

        def cond(tick, remaining, *flat):
            del tick, flat
            return remaining > 0

        def body(tick, remaining, *flat):
            (prior_a, prior_b, feedback,
             current_stm, current_a, current_b) = _unpack(flat)

            a_live = remaining > 2
            gather_index = torch.minimum(
                tick, torch.full_like(tick, width - 1)).reshape(1)
            word = torch.index_select(
                words_b_w_d, 1, gather_index)
            row_gate = torch.index_select(
                active_b_w, 1, gather_index) & a_live

            proposed_a, proposed_a_state = stage_a(
                word, row_gate, tick, a_live, current_a, current_stm)
            proposed_a = self._tensor_tuple(proposed_a, "A payload")
            proposed_a_state = self._tensor_tuple(
                proposed_a_state, "A owner state")
            next_a = self._select(
                a_live, proposed_a,
                tuple(torch.zeros_like(item) for item in prior_a))
            next_a_state = self._select(
                a_live, proposed_a_state, current_a)

            b_index = tick - 1
            b_live = (tick >= 1) & (remaining > 1)
            proposed_b, proposed_b_state, proposed_stm = stage_b(
                prior_a, feedback, b_index, b_live,
                current_b, current_stm)
            proposed_b = self._tensor_tuple(proposed_b, "B payload")
            proposed_b_state = self._tensor_tuple(
                proposed_b_state, "B owner state")
            proposed_stm = self._tensor_tuple(
                proposed_stm, "STM state")
            next_b = self._select(
                b_live, proposed_b,
                tuple(torch.zeros_like(item) for item in prior_b))
            next_b_state = self._select(
                b_live, proposed_b_state, current_b)
            next_stm = self._select(
                b_live, proposed_stm, current_stm)

            c_index = tick - 2
            c_live = tick >= 2
            proposed_feedback = self._tensor_tuple(
                stage_c(prior_b, c_index, c_live),
                "grammar feedback")
            next_feedback = self._select(
                c_live, proposed_feedback, feedback)

            return (
                tick + 1, remaining - 1,
                *(item.reshape(-1) for item in next_a),
                *(item.reshape(-1) for item in next_b),
                *(item.reshape(-1) for item in next_feedback),
                *(item.reshape(-1) for item in next_stm),
                *(item.reshape(-1) for item in next_a_state),
                *(item.reshape(-1) for item in next_b_state))

        initial = (
            zero, trip_count + 2,
            *empty_a, *empty_b, *empty_feedback,
            *stm_state, *a_state, *b_state)
        result = torch.while_loop(cond, body, _carries_with_grad(initial))
        _tick, _remaining, *flat_result = result
        (_a, _b, feedback,
         final_stm, final_a, final_b) = _unpack(tuple(flat_result))
        return final_stm, final_a, final_b, feedback, trip_count

    def run_percept_concept_banked(
            self, words_b_w_d, active_b_w, *,
            stm_state, percept_state, concept_state,
            empty_percept, empty_feedback,
            stage_percept, stage_concept):
        """Pipeline perceptual word ``w`` against conceptual word ``w-1``.

        PS and WS form the independent perceptual leg.  Its completed tensor
        payload is retained for one tick while the next word begins.  The
        conceptual leg then performs CSsub reduction, the fixed CS->SS order
        loop, word-reference deposit/object resolution, and one Language tree
        step.  Thus the only cross-word overlap is dependency-safe:

        ``{PS(w), WS(w)} || {CS/SS/Language(w-1)}``.

        Language feedback uses two tensor latches, so a plan produced at
        symbolic index ``w`` first reaches the conceptual recurrence at
        ``w+2``.  After the final conceptual word, two masked ticks drain
        those latches without constructing extra words or mutating owner state.
        """
        if words_b_w_d.dim() != 3:
            raise ValueError("words_b_w_d must be a [B,W,D] tensor")
        if (active_b_w.dim() != 2
                or tuple(active_b_w.shape) != tuple(words_b_w_d.shape[:2])
                or active_b_w.dtype is not torch.bool):
            raise ValueError(
                "active_b_w must be bool with words_b_w_d's [B,W] shape")
        width = int(words_b_w_d.shape[1])
        if width < 1:
            raise ValueError("the staged word capacity must be positive")

        stm_state = self._tensor_tuple(stm_state, "STM state")
        percept_state = self._tensor_tuple(
            percept_state, "percept owner state")
        concept_state = self._tensor_tuple(
            concept_state, "concept owner state")
        empty_percept = self._tensor_tuple(
            empty_percept, "empty percept payload")
        empty_feedback = self._tensor_tuple(
            empty_feedback, "empty feedback")

        percept_payload_shapes = tuple(
            tuple(item.shape) for item in empty_percept)
        feedback_shapes = tuple(
            tuple(item.shape) for item in empty_feedback)
        stm_shapes = tuple(tuple(item.shape) for item in stm_state)
        percept_state_shapes = tuple(
            tuple(item.shape) for item in percept_state)
        concept_state_shapes = tuple(
            tuple(item.shape) for item in concept_state)

        def _flatten(items):
            return tuple(item.reshape(-1).clone() for item in items)

        empty_percept = _flatten(empty_percept)
        empty_feedback = _flatten(empty_feedback)
        stm_state = _flatten(stm_state)
        percept_state = _flatten(percept_state)
        concept_state = _flatten(concept_state)
        # ``empty_*`` remain body templates (additional HOP inputs).  Carried
        # initial values must use different storages: AOT functionalization
        # rejects a tensor that appears both as a carried input and as a
        # captured/template input, even when every use is read-only.
        initial_percept = tuple(item.clone() for item in empty_percept)
        initial_young_feedback = tuple(
            item.clone() for item in empty_feedback)
        initial_visible_feedback = tuple(
            item.clone() for item in empty_feedback)
        trip_count = self.active_trip_count(active_b_w)
        zero = torch.zeros((), dtype=torch.int64, device=words_b_w_d.device)

        n_percept_payload = len(empty_percept)
        n_feedback = len(empty_feedback)
        n_stm = len(stm_state)
        n_percept_state = len(percept_state)
        n_concept_state = len(concept_state)

        def _restore(items, shapes):
            return tuple(
                item.reshape(shape) for item, shape in zip(items, shapes))

        def _unpack(flat):
            offset = 0
            prior_percept = _restore(
                tuple(flat[offset:offset + n_percept_payload]),
                percept_payload_shapes)
            offset += n_percept_payload
            young_feedback = _restore(
                tuple(flat[offset:offset + n_feedback]), feedback_shapes)
            offset += n_feedback
            old_feedback = _restore(
                tuple(flat[offset:offset + n_feedback]), feedback_shapes)
            offset += n_feedback
            current_stm = _restore(
                tuple(flat[offset:offset + n_stm]), stm_shapes)
            offset += n_stm
            current_percept = _restore(
                tuple(flat[offset:offset + n_percept_state]),
                percept_state_shapes)
            offset += n_percept_state
            current_concept = _restore(
                tuple(flat[offset:offset + n_concept_state]),
                concept_state_shapes)
            return (
                prior_percept, young_feedback, old_feedback,
                current_stm, current_percept, current_concept)

        def cond(tick, remaining, *flat):
            del tick, flat
            return remaining > 0

        def body(tick, remaining, *flat):
            (prior_percept, young_feedback, visible_feedback,
             current_stm, current_percept,
             current_concept) = _unpack(flat)

            percept_live = remaining > 3
            gather_index = torch.minimum(
                tick, torch.full_like(tick, width - 1)).reshape(1)
            word = torch.index_select(words_b_w_d, 1, gather_index)
            row_gate = (
                torch.index_select(
                    active_b_w, 1, gather_index) & percept_live)
            proposed_percept, proposed_percept_state = stage_percept(
                word, row_gate, tick, percept_live, current_percept)
            proposed_percept = self._tensor_tuple(
                proposed_percept, "percept payload")
            proposed_percept_state = self._tensor_tuple(
                proposed_percept_state, "percept owner state")
            next_percept_payload = self._select(
                percept_live, proposed_percept,
                _restore(empty_percept, percept_payload_shapes))
            next_percept_state = self._select(
                percept_live, proposed_percept_state, current_percept)

            concept_index = tick - 1
            concept_live = torch.logical_and(
                tick >= 1, remaining > 2)
            (proposed_concept, proposed_stm,
             proposed_feedback) = stage_concept(
                prior_percept, visible_feedback,
                concept_index, concept_live,
                current_concept, current_stm)
            proposed_concept = self._tensor_tuple(
                proposed_concept, "concept owner state")
            proposed_stm = self._tensor_tuple(
                proposed_stm, "STM state")
            proposed_feedback = self._tensor_tuple(
                proposed_feedback, "Language feedback")
            next_concept = self._select(
                concept_live, proposed_concept, current_concept)
            next_stm = self._select(
                concept_live, proposed_stm, current_stm)
            produced_feedback = self._select(
                concept_live, proposed_feedback,
                _restore(empty_feedback, feedback_shapes))

            return (
                tick + 1, remaining - 1,
                *(item.reshape(-1) for item in next_percept_payload),
                *(item.reshape(-1) for item in produced_feedback),
                # The second grammar latch is a value transfer, but HOP
                # bodies may not return an input alias.  Materialize the
                # latch hand-off explicitly; it remains a tiny [B,R] copy
                # and is the sole storage transition required for the
                # deterministic w+2 delay.
                *(item.reshape(-1).clone() for item in young_feedback),
                *(item.reshape(-1) for item in next_stm),
                *(item.reshape(-1) for item in next_percept_state),
                *(item.reshape(-1) for item in next_concept))

        initial = (
            zero, trip_count + 3,
            *initial_percept,
            *initial_young_feedback,
            *initial_visible_feedback,
            *stm_state, *percept_state, *concept_state)
        result = torch.while_loop(cond, body, _carries_with_grad(initial))
        _tick, _remaining, *flat_result = result
        (_percept, _young, feedback, final_stm,
         final_percept, final_concept) = _unpack(tuple(flat_result))
        return (
            final_stm, final_percept, final_concept,
            feedback, trip_count)

    def run_cs_lanes_banked(
            self, words_b_w_d, active_b_w, *,
            stm_state, cs_sub_state, cs_sym_state, cs_lang_state,
            empty_cs_sub, empty_cs_sym, empty_feedback,
            stage_cs_sub, stage_cs_sym, stage_cs_lang):
        """Run the canonical ``CSSub -> CSSym -> CSLang`` word pipeline.

        ConceptualSpace nominally owns all three transactions and their state
        banks. Peer Spaces retain their own parameters and return tensor-only
        proposals:

        * ``CSSub(w)`` fans the word to PS/WS and reduces their completed
          subsymbolic ladders.
        * ``CSSym(w-1)`` performs the fixed CS->SS->CS order recurrence.
        * ``CSLang(w-2)`` predicts, deposits/resolves the word reference,
          invokes Language's tree planner, and proposes the CS-owned STM
          commit.

        The CSSub and CSSym payloads are the two ordinary pipeline registers.
        Grammar feedback is a separate one-tick register from CSLang back to
        CSSym. Because CSLang for source word ``w`` executes two pipeline
        stages after CSSub(w), that one physical register makes the feedback
        first visible to ``CSSym(w+2)`` -- exactly two symbolic indices after
        its source. The final masked tick drains that register after the last
        live CSLang transaction.
        """
        if words_b_w_d.dim() != 3:
            raise ValueError("words_b_w_d must be a [B,W,D] tensor")
        if (active_b_w.dim() != 2
                or tuple(active_b_w.shape) != tuple(words_b_w_d.shape[:2])
                or active_b_w.dtype is not torch.bool):
            raise ValueError(
                "active_b_w must be bool with words_b_w_d's [B,W] shape")
        width = int(words_b_w_d.shape[1])
        if width < 1:
            raise ValueError("the staged word capacity must be positive")

        stm_state = self._tensor_tuple(stm_state, "STM state")
        cs_sub_state = self._tensor_tuple(cs_sub_state, "CSSub state")
        cs_sym_state = self._tensor_tuple(cs_sym_state, "CSSym state")
        cs_lang_state = self._tensor_tuple(cs_lang_state, "CSLang state")
        empty_cs_sub = self._tensor_tuple(
            empty_cs_sub, "empty CSSub payload")
        empty_cs_sym = self._tensor_tuple(
            empty_cs_sym, "empty CSSym payload")
        empty_feedback = self._tensor_tuple(
            empty_feedback, "empty CSLang feedback")

        cs_sub_payload_shapes = tuple(
            tuple(item.shape) for item in empty_cs_sub)
        cs_sym_payload_shapes = tuple(
            tuple(item.shape) for item in empty_cs_sym)
        feedback_shapes = tuple(
            tuple(item.shape) for item in empty_feedback)
        stm_shapes = tuple(tuple(item.shape) for item in stm_state)
        cs_sub_state_shapes = tuple(
            tuple(item.shape) for item in cs_sub_state)
        cs_sym_state_shapes = tuple(
            tuple(item.shape) for item in cs_sym_state)
        cs_lang_state_shapes = tuple(
            tuple(item.shape) for item in cs_lang_state)

        def _flatten(items):
            return tuple(item.reshape(-1).clone() for item in items)

        empty_cs_sub = _flatten(empty_cs_sub)
        empty_cs_sym = _flatten(empty_cs_sym)
        empty_feedback = _flatten(empty_feedback)
        stm_state = _flatten(stm_state)
        cs_sub_state = _flatten(cs_sub_state)
        cs_sym_state = _flatten(cs_sym_state)
        cs_lang_state = _flatten(cs_lang_state)
        # Templates are closure inputs to the HOP. Give every carried initial
        # value independent storage so AOT functionalization never sees a
        # template/carry alias.
        initial_cs_sub = tuple(item.clone() for item in empty_cs_sub)
        initial_cs_sym = tuple(item.clone() for item in empty_cs_sym)
        initial_feedback = tuple(item.clone() for item in empty_feedback)
        trip_count = self.active_trip_count(active_b_w)
        zero = torch.zeros(
            (), dtype=torch.int64, device=words_b_w_d.device)

        n_cs_sub_payload = len(empty_cs_sub)
        n_cs_sym_payload = len(empty_cs_sym)
        n_feedback = len(empty_feedback)
        n_stm = len(stm_state)
        n_cs_sub_state = len(cs_sub_state)
        n_cs_sym_state = len(cs_sym_state)
        n_cs_lang_state = len(cs_lang_state)

        def _restore(items, shapes):
            return tuple(
                item.reshape(shape) for item, shape in zip(items, shapes))

        def _unpack(flat):
            offset = 0
            prior_cs_sub = _restore(
                tuple(flat[offset:offset + n_cs_sub_payload]),
                cs_sub_payload_shapes)
            offset += n_cs_sub_payload
            prior_cs_sym = _restore(
                tuple(flat[offset:offset + n_cs_sym_payload]),
                cs_sym_payload_shapes)
            offset += n_cs_sym_payload
            feedback = _restore(
                tuple(flat[offset:offset + n_feedback]), feedback_shapes)
            offset += n_feedback
            current_stm = _restore(
                tuple(flat[offset:offset + n_stm]), stm_shapes)
            offset += n_stm
            current_cs_sub = _restore(
                tuple(flat[offset:offset + n_cs_sub_state]),
                cs_sub_state_shapes)
            offset += n_cs_sub_state
            current_cs_sym = _restore(
                tuple(flat[offset:offset + n_cs_sym_state]),
                cs_sym_state_shapes)
            offset += n_cs_sym_state
            current_cs_lang = _restore(
                tuple(flat[offset:offset + n_cs_lang_state]),
                cs_lang_state_shapes)
            return (
                prior_cs_sub, prior_cs_sym, feedback, current_stm,
                current_cs_sub, current_cs_sym, current_cs_lang)

        def cond(tick, remaining, *flat):
            del tick, flat
            return remaining > 0

        def body(tick, remaining, *flat):
            (prior_cs_sub, prior_cs_sym, feedback, current_stm,
             current_cs_sub, current_cs_sym,
             current_cs_lang) = _unpack(flat)

            cs_sub_live = remaining > 3
            gather_index = torch.minimum(
                tick, torch.full_like(tick, width - 1)).reshape(1)
            word = torch.index_select(words_b_w_d, 1, gather_index)
            row_gate = (
                torch.index_select(
                    active_b_w, 1, gather_index) & cs_sub_live)
            proposed_cs_sub, proposed_cs_sub_state = stage_cs_sub(
                word, row_gate, tick, cs_sub_live, current_cs_sub)
            proposed_cs_sub = self._tensor_tuple(
                proposed_cs_sub, "CSSub payload")
            proposed_cs_sub_state = self._tensor_tuple(
                proposed_cs_sub_state, "CSSub state")
            next_cs_sub_payload = self._select(
                cs_sub_live, proposed_cs_sub,
                _restore(empty_cs_sub, cs_sub_payload_shapes))
            next_cs_sub_state = self._select(
                cs_sub_live, proposed_cs_sub_state, current_cs_sub)

            cs_sym_index = tick - 1
            cs_sym_live = torch.logical_and(
                tick >= 1, remaining > 2)
            proposed_cs_sym, proposed_cs_sym_state = stage_cs_sym(
                prior_cs_sub, feedback, cs_sym_index,
                cs_sym_live, current_cs_sym)
            proposed_cs_sym = self._tensor_tuple(
                proposed_cs_sym, "CSSym payload")
            proposed_cs_sym_state = self._tensor_tuple(
                proposed_cs_sym_state, "CSSym state")
            next_cs_sym_payload = self._select(
                cs_sym_live, proposed_cs_sym,
                _restore(empty_cs_sym, cs_sym_payload_shapes))
            next_cs_sym_state = self._select(
                cs_sym_live, proposed_cs_sym_state, current_cs_sym)

            cs_lang_index = tick - 2
            cs_lang_live = torch.logical_and(
                tick >= 2, remaining > 1)
            (proposed_cs_lang, proposed_stm,
             proposed_feedback) = stage_cs_lang(
                prior_cs_sym, cs_lang_index, cs_lang_live,
                current_cs_lang, current_stm)
            proposed_cs_lang = self._tensor_tuple(
                proposed_cs_lang, "CSLang state")
            proposed_stm = self._tensor_tuple(
                proposed_stm, "STM state")
            proposed_feedback = self._tensor_tuple(
                proposed_feedback, "CSLang feedback")
            next_cs_lang = self._select(
                cs_lang_live, proposed_cs_lang, current_cs_lang)
            next_stm = self._select(
                cs_lang_live, proposed_stm, current_stm)
            next_feedback = self._select(
                cs_lang_live, proposed_feedback,
                _restore(empty_feedback, feedback_shapes))

            return (
                tick + 1, remaining - 1,
                *(item.reshape(-1) for item in next_cs_sub_payload),
                *(item.reshape(-1) for item in next_cs_sym_payload),
                *(item.reshape(-1) for item in next_feedback),
                *(item.reshape(-1) for item in next_stm),
                *(item.reshape(-1) for item in next_cs_sub_state),
                *(item.reshape(-1) for item in next_cs_sym_state),
                *(item.reshape(-1) for item in next_cs_lang))

        # W live CSSub ticks, one CSSym drain, one CSLang drain, and one
        # feedback-register drain. No drain tick is allowed to mutate owner
        # state because all three owner commits are independently masked.
        initial = (
            zero, trip_count + 3,
            *initial_cs_sub, *initial_cs_sym, *initial_feedback,
            *stm_state, *cs_sub_state, *cs_sym_state, *cs_lang_state)
        result = torch.while_loop(cond, body, _carries_with_grad(initial))
        _tick, _remaining, *flat_result = result
        (_cs_sub, _cs_sym, feedback, final_stm,
         final_cs_sub, final_cs_sym,
         final_cs_lang) = _unpack(tuple(flat_result))
        return (
            final_stm, final_cs_sub, final_cs_sym, final_cs_lang,
            feedback, trip_count)

class FunctionalPeerSTM:
    """Pure tensor implementations of the online STM controller.

    The ordinary model methods remain owning-space commit wrappers with
    diagnostics.  These operations contain the numerical update itself and
    return a complete six-tensor STM state, so a peer-pipeline callback can
    execute them inside :func:`torch.while_loop`.
    """

    @staticmethod
    def soft_reset_rows(state, row_gate):
        """Return CS-owned sentence state with selected batch rows cleared.

        This is the tensor, batch-specific form of ``Reset(hard=False)`` used
        at a packed sentence boundary.  Learned/codebook state and discourse
        history are outside this six-tensor owner bank and therefore remain
        untouched.
        """
        (buffer, depth, orders, grammar_orders,
         concept_rows, concept_activations) = state
        B = int(buffer.shape[0])
        gate = row_gate.reshape(B).to(
            device=buffer.device, dtype=torch.bool)
        return (
            torch.where(
                gate.reshape(B, 1, 1), torch.zeros_like(buffer), buffer),
            torch.where(gate, torch.zeros_like(depth), depth),
            torch.where(
                gate.reshape(B, 1),
                torch.full_like(orders, -1), orders),
            torch.where(
                gate.reshape(B, 1),
                torch.full_like(grammar_orders, -1), grammar_orders),
            torch.where(
                gate.reshape(B, 1),
                torch.full_like(concept_rows, -1), concept_rows),
            torch.where(
                gate.reshape(B, 1),
                torch.zeros_like(concept_activations),
                concept_activations),
        )

    @staticmethod
    def predict(state, idea, row_gate, layer, routing=None,
                routing_valid=None):
        """Predict from each row's retained context and return loss totals."""
        buffer, depth, *_metadata = state
        buffer = buffer.detach()
        idea = idea.detach()
        B, capacity = int(buffer.shape[0]), int(buffer.shape[1])
        slots = torch.arange(
            capacity, dtype=depth.dtype, device=depth.device).reshape(
                1, capacity)
        context_len = torch.where(depth >= 2, depth - 1, depth)
        keep = slots < context_len.reshape(B, 1)
        lifted = (
            layer.pi.compute_forward(buffer)
            if hasattr(layer.pi, "compute_forward")
            else layer.pi.forward(buffer))
        folded = (
            lifted * keep.unsqueeze(-1).to(dtype=lifted.dtype)
        ).sum(dim=1)
        prediction = (
            layer.sigma.compute_forward(folded)
            if hasattr(layer.sigma, "compute_forward")
            else layer.sigma.forward(folded))
        if (torch.is_tensor(routing) and routing.dim() == 2
                and int(routing.shape[0]) == B):
            routed_prediction = layer._apply_routing_bias(
                prediction, routing)
            if routing_valid is None:
                prediction = routed_prediction
            else:
                valid = routing_valid.reshape(B, 1).to(
                    device=prediction.device, dtype=torch.bool)
                prediction = torch.where(
                    valid, routed_prediction, prediction)
        has_context = depth > 0
        prediction = torch.where(
            has_context.reshape(B, 1), prediction,
            torch.zeros_like(prediction))
        score_rows = torch.logical_and(
            row_gate.reshape(B).to(device=depth.device, dtype=torch.bool),
            has_context)
        squared = (prediction - idea).square()
        loss_sum = (
            squared
            * score_rows.reshape(B, 1).to(dtype=squared.dtype)
        ).sum(-1)
        loss_weight = (
            score_rows.to(dtype=squared.dtype)
            * float(int(squared.shape[1])))
        return prediction, loss_sum, loss_weight

    @staticmethod
    def resolve_top_reference(
            state, object_idea, object_row, object_order,
            object_activation, row_gate):
        """Replace a newly deposited word reference by its object concept.

        The word push and this replacement are deliberately separate pure
        operations: the former records that the symbolic loop completed a
        word concept; the latter is the automatic referential interpretation
        that Language must see.  Only the newest CS-owned STM slot changes.
        """
        (buffer, depth, orders, grammar_orders,
         concept_rows, concept_activations) = state
        B, _capacity, D = buffer.shape
        if (not torch.is_tensor(object_idea)
                or tuple(object_idea.shape) != (B, D)):
            raise ValueError(
                "object reference replacement expects idea [B,D]")
        gate = row_gate.reshape(B).to(
            device=buffer.device, dtype=torch.bool)
        row = object_row.reshape(B).to(
            device=buffer.device, dtype=torch.long)
        gate = torch.logical_and(gate, row >= 0)
        order = object_order.reshape(B).to(
            device=buffer.device, dtype=torch.long)
        activation = object_activation.reshape(B).to(
            device=buffer.device, dtype=concept_activations.dtype)
        top = torch.where(
            gate.reshape(B, 1), object_idea, buffer[:, 0, :])
        next_buffer = torch.cat((top.unsqueeze(1), buffer[:, 1:, :]), dim=1)
        next_orders = torch.cat((
            torch.where(gate, order, orders[:, 0]).reshape(B, 1),
            orders[:, 1:]), dim=1)
        next_rows = torch.cat((
            torch.where(gate, row, concept_rows[:, 0]).reshape(B, 1),
            concept_rows[:, 1:]), dim=1)
        next_activations = torch.cat((
            torch.where(
                gate, activation, concept_activations[:, 0]).reshape(B, 1),
            concept_activations[:, 1:]), dim=1)
        return (
            next_buffer, depth, next_orders, grammar_orders,
            next_rows, next_activations)

# Per-word stage records deliberately carry tensors, not mutable SubSpace
# carriers.  The next A tick reuses each Space's live carrier in place; a B/C
# consumer must therefore hold the completed tensor surface for its own word
# rather than accidentally reading a later peer's write.
_PeerAResult = namedtuple(
    "_PeerAResult",
    (
        "concept_view", "prior_symbolic_view", "concept_orders",
        "gate_b_1", "commit_b_1",
        "word_concept_row", "word_concept_activation",
        "trace_pre_binary", "trace_post_binary", "trace_unary", "p",
        "out_slot", "active_host",
    ),
)
_PeerBResult = namedtuple(
    "_PeerBResult", ("symbolic_snapshot", "symbol_event", "p"))


class GrammarMergeGlue(nn.Module):
    """Progressive-bottleneck glue for ``useGrammar == 'all'``.

    Average-merge of adjacent pairs along the N axis, halving N per
    stage. Caches pairwise differences (``_merge_diff``) for exact
    reverse. ``is_last=True`` makes the glue a pass-through (deepest
    conceptual stage doesn't halve again).
    """

    def __init__(self, stage_idx: int, initial_n: int, is_last: bool):
        super().__init__()
        self.stage_idx = int(stage_idx)
        self.initial_n = int(initial_n)
        self.is_last = bool(is_last)
        self._merge_diff = None

    def forward(self, subspace):
        if subspace.is_empty():
            return subspace
        if self.is_last:
            return subspace
        x = subspace.materialize()
        left = x[:, 0::2, :]
        right = x[:, 1::2, :]
        self._merge_diff = left - right
        subspace.set_event((left + right) / 2)
        return subspace

    def reverse(self, subspace):
        if subspace.is_empty():
            return subspace
        if self.is_last:
            return subspace
        if getattr(subspace, "carrier_pure", False):
            # An answer-path carrier never consumes the forward-cached
            # reconstruction diff (What spec 5.4); nothing to expand.
            return subspace
        diff = self._merge_diff
        assert diff is not None, (
            "GrammarMergeGlue.reverse called without prior forward")
        y = subspace.materialize()
        left = y + diff / 2
        right = y - diff / 2
        B, N_half, D = left.shape
        expanded = torch.zeros(B, N_half * 2, D, device=y.device, dtype=y.dtype)
        expanded[:, 0::2, :] = left
        expanded[:, 1::2, :] = right
        subspace.set_event(expanded)
        self._merge_diff = None
        return subspace


class _BodyStage(nn.Module):
    """Body-stage record with non-owning Conceptual/Whole Space references.

    Those Spaces are already structurally owned by their model ModuleLists.
    Registering them again in a ModuleDict duplicated every Parameter and
    checkpoint key. Only the optional merge operator is a child here.
    """

    def __init__(self, cs, ws, merge=None):
        super().__init__()
        object.__setattr__(self, '_cs', cs)
        object.__setattr__(self, '_ws', ws)
        if merge is not None:
            self.merge = merge

    def __contains__(self, key):
        return key in ('cs', 'ws') or (
            key == 'merge' and 'merge' in self._modules
        )

    def __getitem__(self, key):
        if key == 'cs':
            return self._cs
        if key == 'ws':
            return self._ws
        if key == 'merge' and 'merge' in self._modules:
            return self._modules['merge']
        raise KeyError(key)


# FlattenKWrapper retired 2026-05-11: K-axis flatten/restore is now
# handled inline by ``BasicModel._flatten_k`` / ``_restore_k`` around
# each stem/body/head boundary in the pipeline methods.

# -- End inlined-from-Pipeline section -------------------------------


class Normalizer:
    """Thin wrapper over TheData's min/max scaling.

    Spaces hold a reference to an instance of this class (set during
    model construction) and call ``self.normalizer.{normalize,denormalize}``
    instead of reaching into the TheData global. Keeps the forward/reverse
    contract free of module-level data coupling.
    """

    def __init__(self, source):
        """Hold the underlying TheData-like object as ``_source``."""
        self._source = source

    def normalize(self, x, which="input"):
        """Forward to ``_source.normalize``; ``which`` selects input/output bounds."""
        return self._source.normalize(x, which=which)

    def denormalize(self, x, which="input"):
        """Forward to ``_source.denormalize``; ``which`` selects input/output bounds."""
        return self._source.denormalize(x, which=which)


# Higher-order-concept shape descriptors (RuleSpec / StepInfo / HoCShape)
# moved to bin/Mereology.py alongside the measure family that consumes
# them (Contiguous / Continuous / Peaceful / Area / Luminosity).


class BaseModel(Mereology, nn.Module):
    """Shared training, plotting, and persistence infrastructure for all models.

    Inherits the contemplative-awareness measure family
    (``Contiguous`` / ``Continuous`` / ``Peaceful`` / ``Area`` /
    ``Luminosity``) and the back-projection machinery (`hoc_shape`,
    `_walk_reverse`, `_derivation_path`, `_leaf_path_trust`, etc.)
    from :class:`Mereology`.  See ``bin/Mereology.py``.
    """
    name           = "BaseModel"
    spaces         = []
    reversible    = False
    plot           = False
    _optimizer     = None
    checkpoint_every_batches = 0
    _training_step_count = 0
    # Trials keep independent runtime records until their losses are compared.
    # A non-recording context read is separate from a training pair: both
    # candidate trials may record privately, but only the winner survives.
    _exploration_trial = False
    # Class-level defaults for ``serial`` / ``concept_order_limit`` so that
    # BasicModel()
    # constructed directly (without going through ``init_config``)
    # still answers both attributes. ``init_config`` overrides these
    # via instance attributes when XML is loaded. ``serial`` selects the
    # per-word grammatical path; ``concept_order_limit`` is an order / loop
    # budget for symbolic processing. The split replaces the retired
    # ``conceptualMode`` serial|parallel enum (2026-06-13).
    word_brackets = False
    concept_order_limit = 0
    reconstruction_basis_limit = 16
    word_expectation_gain = 1.0
    word_expectation_weight = 0.1
    reconstruct_in_loop = False
    # PS/WS concept binding at the serial word boundary. ``mixing`` keeps the
    # historical learned ConceptualCombine path for every existing config;
    # ``aligned`` is an explicit opt-in that preserves locations and consumes
    # the complete non-raw fold ladder from both towers.
    concept_binding = "mixing"
    # Class-level default for ``syntacticOrder`` (doc/specs/orders.md, NEW
    # 2026-06-19): the parse-tree DEPTH cap for the serial grammatical
    # reduction. 0 = unbounded (the reduction runs to its single-S fixpoint;
    # byte-identical). Overridden per instance via init_config when set.
    syntacticOrder = 0
    # Model-level trust in incoming assertions/testimony. It scales
    # per-truth DegreeOfTruth values before they enter TruthLayer/LTM and
    # attenuates persisted STM description trust.
    trust = 1.0
    # Scale applied to the DiscourseSpace contrastive loss. The
    # inter-sentence DiscourseSpace lives on ``self.symbolSpace``
    # (``self.symbolSpace.expectation``) rather than directly on the
    # model. Callers that need it should read through
    # ``symbolSpace``; ``<training><sentenceExpectation>false`` in
    # config leaves ``symbolSpace.expectation`` as ``None``.
    # Class-level defaults for ARMA loss weight + priming scale.
    # Pre-2026-05-14 contrastive sentence-loss knobs retired alongside
    # <maskedPrediction>; the single ARMA MSE replaces the contrastive
    # + predictive cosine pair.
    arma_scale = 0.1
    expectation_gain = 1.0
    # Inter-sentence end-state prediction loss weight (Task 8, plan §9).
    # ``BracketExpectation.consume_inter_loss`` returns a per-sentence-mean
    # MSE which ``runBatch`` weights by this before adding to ``TheError``.
    inter_loss_weight = 0.1
    # The InfoNCE next-idea contrastive term weight + the prediction-trial
    # fraction; both default 0.0 -> the feature is off -> byte-identical.
    inter_contrastive_weight = 0.0
    prediction_trial_ratio = 0.0

    @staticmethod
    def load_config(config_path=None):
        """Load model settings from an XML config file.

        Delegates to XMLConfig._parse_xml().  Returns a dict of dicts;
        missing fields are filled by create_from_config() using model.xml.
        """
        if config_path is None:
            config_path = os.path.join(ProjectPaths.PROJECT_DIR, "model.xml")
        return XMLConfig._parse_xml(config_path)

    @staticmethod
    def _unit_interval(value, default=1.0):
        """Coerce ``value`` into ``[0, 1]``; non-finite/malformed -> default."""
        try:
            out = float(value)
        except (TypeError, ValueError):
            out = float(default)
        if not math.isfinite(out):
            out = float(default)
        return max(0.0, min(1.0, out))

    def _effective_incoming_trust(self, trust):
        """Signed incoming DoT scaled by the model's testimony trust."""
        try:
            raw = float(trust)
        except (TypeError, ValueError):
            raw = 0.0
        if not math.isfinite(raw):
            raw = 0.0
        scale = self._unit_interval(getattr(self, 'trust', 1.0), default=1.0)
        return max(-1.0, min(1.0, raw * scale))

    @staticmethod
    def _resolve_dim(section, prev_dim):
        """Resolve a Space's nDim sentinel: 0 -> inherit ``prev_dim``.

        Shared between BasicModel.create() and BasicModel.create()
        (and any subclass): both pipelines chain dims through
        InputSpace -> PartSpace -> ConceptualSpace ->
        WholeSpace -> OutputSpace, and an unset / zero-sentinel
        nDim means "inherit the upstream Space's content dim".

        Respect-explicit (Task #11, decision (3)): an EXPLICITLY-set
        (non-zero) <nDim> is ALWAYS returned verbatim -- for the endpoint
        space_roles (InputSpace / OutputSpace) this is the contract that the head /
        input width the config author sized is honoured, never overridden by
        the chained ``prev_dim`` or a canonical band-derived width. Only the
        ``0`` sentinel triggers inheritance (and a KeyError -- a section that
        omits <nDim> entirely -- is treated as the inherit sentinel).
        """
        try:
            raw = TheXMLConfig.space(section, "nDim")
        except KeyError:
            return prev_dim
        return prev_dim if raw == 0 else raw

    @staticmethod
    def _obj_size(section):
        """Per-section objectSize: ``nWhere + nWhen`` from canonical_shape.

        Each Space carries its own positional / temporal encoding widths
        (architectural constants, not config options); the muxed event
        tensor's last-axis size is ``nDim + nWhere + nWhen``.
        """
        nw, nn = canonical_shape(section)
        return nw + nn

    @staticmethod
    def _nvec(section, n_out):
        """Resolve a Space's nVectors sentinel: 0 -> ``n_out``.

        Codebook spaces sample with replacement so nVectors can
        differ from active count; ``0`` means "use the active count
        as the codebook size", which is the safe default for
        non-codebook spaces (where the validator enforces
        ``nVectors == nActive``).
        """
        try:
            raw = TheXMLConfig.space(section, "nVectors")
        except KeyError:
            return n_out
        return n_out if raw == 0 else raw

    # -- Order Partitions (Ramsification) -----------------------------
    # Static helpers shared between BasicModel and the per-stage
    # BasicModel pipeline. Pure-functional except for
    # ``_conceptual_width_mode`` which reads TheXMLConfig.

    @staticmethod
    def _order_partitions(symbol_dim, subsymbolic_order):
        """Compute geometric-decay partition boundaries for symbolSum.

        Each conceptual order writes only to its designated slice,
        so the symbolic space becomes self-describing: the position of
        an activation reveals its conceptual order.

        Partition sizes follow geometric decay -- lower (more fundamental)
        orders occupy larger slices:
            order 0: [0,      D//2)       <- 1/2 of symbol_dim
            order 1: [D//2,   3D//4)      <- 1/4
            order 2: [3D//4,  7D//8)      <- 1/8
            ...
            last order: remainder of D
        """
        partitions, start = [], 0
        for t in range(subsymbolic_order):
            if t == subsymbolic_order - 1:
                end = symbol_dim
            else:
                end = start + max(1, symbol_dim // (2 ** (t + 1)))
            partitions.append((start, end))
            start = end
        return partitions

    @staticmethod
    def _activation_order(activation, partitions):
        """Return the order whose partition has the highest energy."""
        # ``.norm()`` returns zero-dim tensors; stack instead of rewrapping
        # via ``torch.tensor([...])`` to avoid the "copy-construct from a
        # tensor" deprecation warning.
        energies = torch.stack(
            [activation[s:e].norm() for s, e in partitions])
        return int(energies.argmax())

    # -- Hierarchical Epistemic Architecture --------------------------

    @staticmethod
    def _level_shapes(n_vectors, dim, subsymbolic_order):
        """Perceptual passes preserve the attended width and content cube."""
        return [(int(n_vectors), int(dim)) for _ in range(subsymbolic_order)]

    @staticmethod
    def from_config(config_path=None, model_type=None, data=None):
        """Factory: create the right model type from XML config.

        Defaults to ``data/xor.xml`` for smoke runs; resolves relative
        paths via ``ModelFactory.resolve_xml``. Returns ``(model, cfg)``
        where ``cfg`` is the parsed dict.
        """
        if config_path is None:
            config_path = os.path.join(ProjectPaths.PROJECT_DIR, "data", "xor.xml")
        resolved_path = ModelFactory.resolve_xml(config_path)
        model = BasicModel()
        cfg = model.create_from_config(resolved_path, model_type=model_type, data=data)
        return model, cfg

    def _resolve_artifact_path(self, relpath):
        """Resolve a relative artifact path against the XML config directory."""
        if relpath is None or relpath == "":
            return relpath
        if os.path.isabs(relpath):
            return relpath
        config_path = getattr(self, "_config_path", None)
        config_dir = os.path.dirname(config_path) if config_path else ProjectPaths.PROJECT_DIR
        return os.path.join(config_dir, relpath)

    def create_from_config(self, config_path=None, model_type=None, data=None):
        """Create the model using settings from an XML config file.

        Initializes ``TheXMLConfig`` from ``config_path`` (overlaying
        ``data/model.xml`` defaults), validates the schema, then walks
        through space construction, optimizer setup, and embedding load.
        Mutates ``self`` extensively; returns the parsed config dict.
        """
        self._config_path = config_path
        self._config_data = data

        defaults_path = os.path.join(ProjectPaths.DATA_DIR, "model.xml")
        init_config(path=config_path, defaults_path=defaults_path)
        cfg = TheXMLConfig.data
        from WordIdentity import resolve_identity_layout
        resolve_identity_layout(cfg)
        self.cfg = cfg

        arch = cfg["architecture"]
        ModelFactory.validate_config(cfg)

        _binding = str(TheXMLConfig.get(
            "architecture.conceptBinding", default="mixing")
        ).strip().lower()
        if _binding not in ("mixing", "aligned"):
            raise ValueError(
                "<architecture><conceptBinding> must be mixing or aligned "
                f"(got {_binding!r}).")
        self.concept_binding = _binding

        _t = TheXMLConfig.training
        _s = TheXMLConfig.space

        # DataLoader prefetch workers. Pulled here so every entry point
        # (ModelFactory.run, BaseModel.from_config, tests) shares the
        # same model.xml-defaulted value. 0 means synchronous in-process
        # batch assembly.
        self._num_workers = int(_t("numWorkers"))

        if model_type is None:
            # The data space_role moved from architecture-level <modelType> into
            # <data> as <dataType> (embedding | numeric) 2026-06-19.
            model_type = TheXMLConfig.data_type()

        # <embeddingPath> retired (2026-05-12): embeddings now ride
        # inside the single .ckpt bundle, not a separate .kv artifact.
        # Global objectSize is the InputSpace's where/when overhead (the muxed
        # event enters at IS); source from canonical_shape, not architecture.* .
        _nWhere, _nWhen = canonical_shape("InputSpace")
        _objectSize = _nWhere + _nWhen
        TheXMLConfig._data.setdefault("architecture", {})["objectSize"] = _objectSize

        # Resolve space output counts with sentinels.
        # nOutput=0 means "same as nInput for this space".
        # nInput=0 means "from data" (InputSpace) or "from previous space" (others).
        # The actual chain derivation happens inside create() using each space's outputShape.
        def _resolve(space, prev):
            raw = _s(space, "nOutput")
            return prev if raw == 0 else raw

        # InputSpace: nOutput=0 is the data-width sentinel. Resolve it here
        # before downstream ``nOutput=0 -> previous`` propagation; passing the
        # literal zero into create() left every default-space count at zero.
        nInput = _s("InputSpace", "nOutput")
        if nInput == 0:
            source_data = data if data is not None else TheData
            try:
                nInput = int(source_data.getInputSize())
            except (AttributeError, IndexError, TypeError, ValueError):
                # Factory-only callers may intentionally omit a populated
                # dataset. Keep the architecture constructible without
                # changing the configured carrier once real data is supplied.
                nInput = 1
            nInput = max(1, nInput)
        nPercepts = _resolve("PartSpace", nInput)
        nConcepts = _resolve("ConceptualSpace", nPercepts)
        nSymbols  = _resolve("WholeSpace",   nConcepts)
        nWords    = nSymbols  # SyntacticSpace removed; kept for API compat
        nOutput   = _resolve("OutputSpace",      nSymbols)

        _nObjects = (
            _s("InputSpace", "nVectors")
            + _s("PartSpace", "nVectors")
            + _s("ConceptualSpace", "nVectors")
            + _s("WholeSpace", "nVectors")
            + _s("OutputSpace", "nVectors")
        )
        TheXMLConfig._data.setdefault("architecture", {})["nObjects"] = _nObjects

        self.create(
            nInput=nInput,
            nPercepts=nPercepts,
            nConcepts=nConcepts,
            nSymbols=nSymbols,
            nWords=nWords,
            nOutput=nOutput,
            bindingDepth=arch["bindingDepth"],
            model_type=model_type,
            data=data,
            reconstruction_scale=_t("reconstructionScale"),
            what_scale=_t("whatScale"),
            where_scale=_t("whereScale"),
            when_scale=_t("whenScale"),
        )

        # IR mask rate: Bernoulli probability that a P-space_role position is
        # replaced by NULL_PERCEPT for masked reconstruction. Default
        # 0.15 (BERT-style).
        _mask_rate = _t("maskRate", 0.15)
        self.mask_rate = float(_mask_rate if _mask_rate is not None else 0.15)
        if not (0.0 <= self.mask_rate <= 1.0):
            raise ValueError(
                f"maskRate must be in [0.0, 1.0], got {self.mask_rate}")

        # serial_mode (AR streaming fast path) retired with
        # <maskedPrediction> 2026-05-14.  Within-sentence training is
        # IR-only; the slide-and-recompute optimisation no longer has
        # a caller.  Keeping the attribute False so legacy reads stay
        # well-defined; remove next release.
        self.serial_mode = False
        if hasattr(self, 'perceptualSpace'):
            self.perceptualSpace.serial_mode = False
        if hasattr(self, 'conceptualSpace'):
            self.conceptualSpace.serial_mode = False
        if getattr(self, 'symbolSpace', None) is not None:
            self.symbolSpace.serial_mode = False

        # Reading mode was resolved before constructing the fixed pipelines.
        for _cs in (getattr(self, "conceptualSpaces", None) or []):
            object.__setattr__(_cs, "_concept_binding", self.concept_binding)
            object.__setattr__(_cs, "_serial", self.word_brackets)
            # Non-registering owner link: ConceptualSpace can request a
            # value-only aligned active-prefix expansion without making the
            # model its nn.Module child (which would create an ownership
            # cycle/state-dict aliases).
            object.__setattr__(_cs, "_model", self)
        _derived = getattr(self._concept_owner().similarity_codebook, 'mereology', None)
        self._readback_percept_width = None if _derived is None else _derived.percept_width
        self._image_form_width = None if _derived is None else _derived.percept_event_width
        store = getattr(self.symbolSpace,"ltm_store",None)
        if store is not None:
            store.image_form_width = store.nDim if _derived is None else _derived.percept_event_width
        for _ws in (getattr(self, "wholeSpaces", None) or []):
            # Same non-owning expansion seam for WholeSpace.insert_whole.
            object.__setattr__(_ws, "_model", self)

        # syntacticOrder (doc/specs/orders.md, NEW 2026-06-19): the parse-tree
        # DEPTH cap for the serial grammatical reduction. 0 (default) =
        # unbounded (the NULL-closing reduce sweep collapses to a single S, exactly
        # as before -- byte-identical). A positive value caps the sweep to that
        # many forced fold levels; the <= word-count bound holds structurally
        # (a reduce micro-step no-ops once a row's depth reaches 1). Inert in
        # parallel mode (no per-sentence parse tree to bound).
        _syn_raw = TheXMLConfig.get(
            "architecture.syntacticOrder", default=None)
        try:
            _syn = int(_syn_raw) if _syn_raw is not None else 0
        except (TypeError, ValueError):
            raise ValueError(
                f"<architecture><syntacticOrder> must be a non-negative "
                f"integer (got {_syn_raw!r}).")
        if _syn < 0:
            raise ValueError(
                f"<architecture><syntacticOrder> must be >= 0 (got {_syn}).")
        self.syntacticOrder = _syn

        # GrammarOpsPass §6c sentence protocol (author sign-off
        # 2026-06-11): in serial mode, every sentence opens with an
        # independent PARALLEL prelude of ``bindingDepth`` pumps
        # (pump zero: EMA on — the word-learning guarantee; intent-only
        # commit — the gist primes both towers via §5 ``set_intent``
        # and nothing enters the workspace), then the serial per-word
        # task runs with the §6d law in its serial partition; the gist
        # re-pumps on preemption only. ``<architecture>
        # <sentenceProtocol>`` — default OFF until the author's cutover
        # (the meronomy pattern: land dark, cut over deliberately).
        # §6c default cutover (2026-06-18, Alec): ON by default in SERIAL mode
        # (``serial == True``) so the whole-sentence gist (the initial
        # subsymbolic-order prelude pass) CONDITIONS each word's parts/wholes —
        # the context the per-word hard mask drops re-enters via the gist/intent.
        # OFF in parallel (the prelude is only invoked from the serial
        # ``_forward_body_per_word``, so parallel never runs it regardless).
        # Explicit ``<sentenceProtocol>`` in the XML overrides either way.
        _sp_default = self.word_brackets
        self.sentence_protocol = bool(TheXMLConfig.get(
            "architecture.sentenceProtocol", default=_sp_default))
        # Eager diagnostic only. It is pre-declared for stable object shape and
        # deliberately not mutated while Dynamo captures the model.
        self._prelude_pumps = 0

        # TransformChooser kind. Mirrors the router-side read in
        # LanguageLayer._wire_signal_router_grammar_ops so the cutover reaches
        # the model-built structured layers too (the STM reducer). Default
        # "anchordot" -> stateless, basin unchanged.
        self.transform_chooser = str(TheXMLConfig.get(
            "architecture.transformChooser", default="anchordot"))
        # Validate even when the selected scorer is stateless. Zero hidden
        # width retains the established grammar-width-derived default.
        from Language import _chooser_size
        self.transform_chooser_hidden = _chooser_size(TheXMLConfig.get(
            "architecture.transformChooserHidden", default=0),
            "transformChooserHidden", minimum=0)
        self.transform_chooser_depth = _chooser_size(TheXMLConfig.get(
            "architecture.transformChooserDepth", default=1),
            "transformChooserDepth")
        self.what_thinking_hidden = _chooser_size(TheXMLConfig.get(
            "architecture.whatThinkingHidden", default=16),
            "whatThinkingHidden")
        self.what_thinking_depth = _chooser_size(TheXMLConfig.get(
            "architecture.whatThinkingDepth", default=1),
            "whatThinkingDepth")

        # MetaSymbol role-participation Category codebook (doc/Language.md
        # "Participation Categories"). Learn a small role-space VQ during
        # perception: pending MetaSymbols accumulate role evidence, then
        # commit to a single category centroid. The structured grammar layers
        # use that role context for every transform chooser.
        self.category_codebook = bool(TheXMLConfig.get(
            "architecture.categoryCodebook", default=True))

        # Legacy/direct LiftLayer adverb helper flag. The live AdverbLayer
        # grammar op force-builds the same zero-init eigenmodifier; this knob
        # only affects ordinary LiftLayer instances and is mirrored here for
        # introspection. Default off -> plain LiftLayer sigma fold unchanged.
        self.adverb_eig_edit = bool(TheXMLConfig.get(
            "architecture.adverbEigEdit", default=False))

        # Mereological order-raising (doc/specs/mereological-order-raising.md).
        # When on, perception's autobind hook builds a meronymic lattice and
        # raises abstraction order as attention requires. The request + the
        # ramsification-table enable happen in _create_per_stage (order-safe:
        # this self.* read runs AFTER spaces are built, so it is introspection-
        # only -- gating reads the live config at build, like categoryCodebook).
        # Default off -> no table, no raising (byte-identical).
        self.mereology_raise = bool(TheXMLConfig.get(
            "architecture.mereologyRaise", default=False))
        # The learned reader belongs to the answer. Its zero gate preserves
        # the initial answer; the keys and all source dictionaries are detached.
        with torch.random.fork_rng(devices=[]):
            self.answer_attention = PrimedSymbolReader()

        # SymbolSpace 3-stream peer bind (2026-06-21 SymbolSpace refactor,
        # Slice B). When on, the CS bind is 3-STREAM: PS (part-percepts), WS
        # (whole-percepts), SS (symbols) -- SymbolSpace becomes the symbol tower
        # with its own codebook + ``forward_symbol`` stream, and WholeSpace goes
        # tall (whole-percepts, not the compact symbol). Default off -> the
        # 2-stream (PS, WS) bind -> BYTE-IDENTICAL. (ConceptualCombine is already
        # n_streams-parametrized, Slice A.)
        # Relevance integration gate (Architecture sec C); default false.
        self.relevance_on = bool(TheXMLConfig.get(
            "architecture.relevance", default=False))
        try:
            self.priming_decay = float(TheXMLConfig.get(
                "architecture.primingDecay", default=0.9))
        except (TypeError, ValueError):
            self.priming_decay = 0.9
        # Energy-dissipating prime diffusion (Alec 2026-07-12): the fraction
        # of a connected row's standing energy that moves to its neighbors
        # per prime event. Live by default; 0 restores pure decay+bump.
        try:
            self.priming_spread = float(TheXMLConfig.get(
                "architecture.primingSpread", default=0.25))
        except (TypeError, ValueError):
            self.priming_spread = 0.25
        # Base grammar-confidence threshold for online STM reduction.  The
        # explicit word-axis controller lowers it with occupancy; legacy
        # serial configs retain their fixed reduce-marginal comparison.

        self.symbol_tower = bool(TheXMLConfig.get(
            "architecture.symbolTower", default=False))

        # <answerSynthesis> (What spec Steps 3-4): answer construction runs
        # resolve -> conceptual synthesis -> perceptual synthesis ->
        # OutputSpace.from_percepts instead of the direct symbol projection.
        # Exposed as a model.xml parameter (live-wiring directive): default
        # false keeps every established path byte-identical until the
        # temporal/supervised curriculum trains the synthesis adapter.
        self.answer_synthesis = bool(TheXMLConfig.get(
            "architecture.answerSynthesis", default=False))
        # <synthesisBindings>: how many perceptual context slots a derivation
        # may NAME as bindings for output synthesis (spec 5.3: context reaches
        # the answer only through named, replayable bindings). 0 = none.
        try:
            self.synthesis_bindings = int(TheXMLConfig.get(
                "architecture.synthesisBindings", default=0) or 0)
        except (TypeError, ValueError):
            self.synthesis_bindings = 0
        # <whatCurriculum> (Step 9): none | present | temporal | full.
        #   present  -> clean present reconstruction + supervised answers;
        #   temporal -> also one-step past/future completion trials;
        #   full     -> also inference trials; temporal distance grows with
        #               <whatCurriculumDistance> (default 1).
        self.what_curriculum = str(TheXMLConfig.get(
            "architecture.whatCurriculum", default="none") or "none").lower()
        try:
            self.what_curriculum_distance = max(1, int(TheXMLConfig.get(
                "architecture.whatCurriculumDistance", default=1) or 1))
        except (TypeError, ValueError):
            self.what_curriculum_distance = 1
        try:
            self.what_curriculum_ratio = float(TheXMLConfig.get(
                "architecture.whatCurriculumRatio", default=0.25) or 0.0)
        except (TypeError, ValueError):
            self.what_curriculum_ratio = 0.25

        # The SymbolSpace-owned interaction memory's episode credit boundary
        # ("slot" = detach
        # at append, the established behaviour; "episode" = slots appended
        # inside begin/end_what_episode stay live until the episode ends).
        self.what_thinking_detach = str(TheXMLConfig.get(
            "architecture.whatThinkingDetach", default="slot") or "slot").lower()
        if self.what_thinking_detach not in ("slot", "episode"):
            raise ValueError(
                "<whatThinkingDetach> must be 'slot' or 'episode', got "
                f"{self.what_thinking_detach!r}")
        # <whatThinkingIterations> / <whatThinkingPressure> (spec 6.2 /
        # 6.4): the episode iteration limit L (1 = today's single what())
        # and the monotone closure-pressure schedule.  Default off.
        try:
            self.what_thinking_iterations = max(1, int(TheXMLConfig.get(
                "architecture.whatThinkingIterations", default=1) or 1))
        except (TypeError, ValueError):
            self.what_thinking_iterations = 1
        self.what_thinking_pressure = str(TheXMLConfig.get(
            "architecture.whatThinkingPressure", default="linear") or "linear").lower()
        if self.what_thinking_pressure not in ("linear", "quadratic", "step"):
            raise ValueError(
                "<whatThinkingPressure> must be linear, quadratic or step, got "
                f"{self.what_thinking_pressure!r}")
        if TheXMLConfig.get("architecture.whatThinkingPrimitives", default=None) is not None:
            raise ValueError(
                "<whatThinkingPrimitives> is retired (Alec 2026-09-09): no "
                "mathematical machinery in the runtime; arithmetic is a "
                "syntax the grammar learns (plus is a transitive verb)")

        # Reconstruction from an idea with the forward derivation erased.
        # When on, reverse() clears the grammar/routing traces built during
        # comprehension, then asks SymbolSpace.generate to infer the reverse
        # rule path from the supplied idea snapshot. This differs from
        # <ideaDecode>, which deliberately skips the chart/router rebuild.
        self.reconstruct_from_idea = bool(TheXMLConfig.get(
            "architecture.reconstructFromIdea", default=False))
        # <branchDiagnosticsEvery> (What spec Step 6): every N training
        # batches, sample gradient norms / cosine of the two primary costs at
        # the conceptual and symbolic branch points before backward.  A read,
        # never an update.  0 (default) disables the sampling.
        try:
            self.branch_diagnostics_every = int(
                TheXMLConfig.training("branchDiagnosticsEvery", 0) or 0)
        except (KeyError, TypeError, ValueError):
            self.branch_diagnostics_every = 0

        # Concept index-read (snap design doc §ontology, Alec 2026-07-15):
        # when on, the serial per-word idea READS THROUGH THE INDEX to the
        # concept's random ``similarity_codebook`` row (signed hypersphere)
        # instead of using only the computed percept-binding event. Percepts
        # are mereological on the bounded unsigned hypercube and contract, so
        # the computed ideas collapse; the concept row is the separable
        # substrate SGNS (step (a)) shapes. Default off -> byte-identical.
        self.concept_index_read = bool(TheXMLConfig.get(
            "architecture.conceptIndexRead", default=False))

        # Explicit reason_about / answer_query work allowance. The default
        # one-unit allowance is bounded; zero disables these public APIs.
        # The deprecated Boolean alias selects ten shared work units.
        _ri = TheXMLConfig.get("architecture.reasoningIterations", default=None)
        if _ri is None:
            self.reasoning_iterations = (
                10 if bool(TheXMLConfig.get("architecture.queryReasoning",
                                            default=False)) else 1)
        else:
            self.reasoning_iterations = max(0, int(_ri))
        # Back-compat: code/tests that gate on the boolean still work.
        self.query_reasoning = self.reasoning_iterations > 0

        # Explicit think_about calls share the normal controller work meter.
        # Zero disables this API; it never attaches a second result to an answer.
        self.thinking_budget = max(0, int(TheXMLConfig.get(
            "architecture.thinkingBudget", default=0) or 0))

        # Serial word-at-a-time object/meta (doc/specs/mereological-order-
        # raising.md "Serial-mode word-at-a-time loop"; Alec 2026-06-17). When
        # on (serial only), the radix stem keeps TWO distinct axes:
        # sentence words (the outer traversal) and the constituent percepts
        # of ONE word (synthesized inside that word's iteration).  Neither
        # axis is the STM: STM remains the bounded, reducing grammatical
        # workspace.  In particular, PartSpace.nOutput is the width of the
        # instantaneous perceptual field, not a raw-character limit, and
        # stmCapacity is not a sentence-length limit.
        self.serial_object_meta = bool(TheXMLConfig.get(
            "architecture.serialObjectMeta", default=False))
        _word_cap = TheXMLConfig.get(
            "architecture.serialWordCapacity", default=None)
        try:
            self.serial_word_capacity = (
                None if _word_cap in (None, "") else max(1, int(_word_cap)))
        except (TypeError, ValueError):
            raise ValueError(
                "<serialWordCapacity> must be a positive integer; got "
                f"{_word_cap!r}")
        _residual_cap = TheXMLConfig.get(
            "architecture.serialResidualPartCapacity", default=16)
        try:
            self.serial_residual_part_capacity = int(_residual_cap)
        except (TypeError, ValueError):
            raise ValueError(
                "<serialResidualPartCapacity> must be an integer >= 3; "
                f"got {_residual_cap!r}")
        if self.serial_residual_part_capacity < 3:
            raise ValueError(
                "<serialResidualPartCapacity> must be >= 3; got "
                f"{self.serial_residual_part_capacity}")
        _bucket_raw = TheXMLConfig.get(
            "architecture.serialWordBuckets", default=None)
        if _bucket_raw in (None, ""):
            self.serial_word_buckets = (
                (int(self.serial_word_capacity),)
                if self.serial_word_capacity is not None else ())
        else:
            try:
                if isinstance(_bucket_raw, (list, tuple)):
                    _bucket_values = [int(v) for v in _bucket_raw]
                else:
                    _bucket_values = [
                        int(v.strip()) for v in str(_bucket_raw).split(",")
                        if v.strip()]
                self.serial_word_buckets = tuple(sorted(set(_bucket_values)))
            except (TypeError, ValueError):
                raise ValueError(
                    "<serialWordBuckets> must be a comma-separated list of "
                    f"positive integers; got {_bucket_raw!r}")
            if (not self.serial_word_buckets
                    or any(v < 1 for v in self.serial_word_buckets)):
                raise ValueError(
                    "<serialWordBuckets> must contain positive integers; "
                    f"got {_bucket_raw!r}")
            if (self.serial_word_capacity is not None
                    and self.serial_word_buckets[-1]
                    != int(self.serial_word_capacity)):
                raise ValueError(
                    "the largest <serialWordBuckets> width must equal "
                    f"<serialWordCapacity> ({self.serial_word_buckets[-1]} "
                    f"!= {self.serial_word_capacity})")

        # Model-level trust in incoming assertions/testimony. Personal
        # experience remains the model's own evidence; third-party words enter
        # TruthLayer/LTM with their supplied DegreeOfTruth multiplied by this
        # scalar; grammar does not grant assertion authority.
        self.trust = self._unit_interval(
            TheXMLConfig.get("architecture.trust", default=1.0),
            default=1.0)

        self.ltm_consolidation = True

        # Stateless server (mirrors WikiOracle's server.stateless; the
        # shipped deployment runs --stateless). Default TRUE: the runtime
        # request-body TruthSet (``store_truths``, ORIGIN_USER rows) is
        # request-scoped, so on every state_dict load the consolidated LTM
        # is revived WITHOUT the user rows (config-provisioned + conversation
        # rows persist) and the TruthLayer view is rematerialized -- see
        # ``SymbolSubSpace._revive_ltm_post_load``. Set false for a stateful
        # deployment where a saved checkpoint's user rows are durable state.
        self.stateless = bool(TheXMLConfig.get(
            "architecture.stateless", default=True))

        # Step 1 (2026-06-10 symbolic-iteration plan): mirror the symbolic
        # order and the independent serial mode onto each WholeSpace. The
        # WS forward dispatches SYMBOLIC ITERATIONS (quantize + parallel leg)
        # from the serial flag -- the SyntacticLayer is attached
        # unconditionally (model.xml default grammar), so layer presence
        # cannot distinguish the legs.
        # Space construction (``self.create`` above) runs before this
        # knob is parsed, hence the post-hoc stamp.
        for _ss in (getattr(self, 'wholeSpaces', None) or []):
            object.__setattr__(_ss, '_symbolic_order', self.concept_order_limit)
            object.__setattr__(_ss, '_serial', self.word_brackets)
            object.__setattr__(_ss, '_priming_decay', self.priming_decay)
            object.__setattr__(_ss, '_priming_spread', self.priming_spread)
            # Canonical priming (Alec 2026-07-12): per-stage WS delegate to
            # the terminal's order-indexed codebook surface.
            _ws_list = list(getattr(self, 'wholeSpaces', None) or [])
            if _ws_list and _ss is not _ws_list[-1]:
                object.__setattr__(_ss, '_priming_canonical_ref',
                                   _ws_list[-1])
        # The ConceptualSpaces need the same stamp so the sparse-coding edge
        # population + scatter (gated on ``_symbolic_order > 0`` and parallel)
        # activate together. A plain host-attribute stamp -- byte-identical.
        # (P2 symbolic-only rework: the _n_ps_codes/_n_ws_codes source-layout
        # stamps retired with the percept families -- a_0 comes from the
        # order-0 snap, not PS/WS presence columns.)
        # <sparseReplace> RETIRED (P3 two-phase forward, decision 10): phase
        # separation makes non-replacement STRUCTURAL -- sparse content never
        # substitutes subsymbolic content; the symbolic phase's outputs feed
        # the SS leg, the head-side losses, and the concept table. The knob
        # parses as an inert deprecation warning.
        if TheXMLConfig.get("architecture.sparseReplace",
                            default=None) is not None:
            warnings.warn(
                "<sparseReplace> is retired (two-phase forward): the "
                "symbolic phase never substitutes the subsymbolic advance; "
                "the knob is ignored.", DeprecationWarning)
        for _cs in (getattr(self, 'conceptualSpaces', None) or []):
            object.__setattr__(_cs, '_symbolic_order', self.concept_order_limit)
            object.__setattr__(_cs, '_serial', self.word_brackets)
            object.__setattr__(_cs, '_priming_decay', self.priming_decay)
            object.__setattr__(_cs, '_priming_spread', self.priming_spread)
            # Priming addresses belong to the grammar's actual concept owner.
            # Unshared serial stages have different native identity maps.
            _cs_list = list(getattr(self, 'conceptualSpaces', None) or [])
            _priming_owner = self._concept_owner() if self.word_brackets else _cs_list[0]
            if _cs_list and _cs is not _priming_owner:
                object.__setattr__(_cs, '_priming_canonical_ref',
                                   _priming_owner)
            # Back-ref to the model so the CS can rebuild the optimizer when its
            # per-order sparse weight Parameters grow (mirrors codebook growth).
            object.__setattr__(_cs, '_model', self)

        # Per-word ground-truth cursor enable. Pre-Stage-1.E this was
        # derived directly from ``useGrammar``; post-Stage-1.E it mirrors
        # ``self.word_brackets``.
        # Kept as a back-ref attribute on InputSpace because
        # ``InputSpace.next_word`` and a handful of late-stage per-word
        # loops still consult it; Stage 3 (signal-router parser cleanup)
        # is the appropriate site
        # to retire the boolean entirely.
        if getattr(self, 'inputSpace', None) is not None:
            self.inputSpace._per_word_enabled = bool(self.word_brackets)
            # serialObjectMeta must reach InputSpace.finalize_stem (it builds the
            # capturable word-index / per-word commit tensors only when on).
            object.__setattr__(self.inputSpace, '_serial_object_meta',
                               bool(self.serial_object_meta))
            if self.word_brackets and self.serial_object_meta:
                # Sentence traversal and grammatical workspace are distinct.
                # New configs state the traversal cap explicitly; the STM
                # fallback preserves older serialObjectMeta fixtures without
                # silently changing their loop length.
                _word_capacity = self.serial_word_capacity
                if _word_capacity is None:
                    _word_capacity = int(getattr(
                        getattr(self, 'conceptualSpace', None),
                        'stm_capacity', 0) or 0)
                if _word_capacity < 1:
                    raise ValueError(
                        "serialObjectMeta requires either a positive "
                        "<serialWordCapacity> or ConceptualSpace "
                        "<stmCapacity> >= 1")
                object.__setattr__(self.inputSpace,
                                   '_serial_word_capacity', _word_capacity)
                object.__setattr__(
                    self.inputSpace, '_serial_word_buckets',
                    tuple(self.serial_word_buckets or (_word_capacity,)))
                _ps = getattr(self, 'perceptualSpace', None)
                if _ps is not None:
                    object.__setattr__(_ps, '_serial_object_meta', True)
                    object.__setattr__(_ps,
                                       '_serial_word_capacity', _word_capacity)
                    object.__setattr__(
                        _ps, '_serial_word_buckets',
                        tuple(self.serial_word_buckets or (_word_capacity,)))

        # DOCTRINE (Task 4, doc/plans/2026-05-29-stm-serial-parallel-modes.md
        # §"Serial mode = attentional filtering"): serial mode **is** the
        # attentional-filtering regime. The former guard here forced
        # ``conceptualSpace.serial_mode = False`` whenever
        # ``serial_mode and conceptualSpace.hasAttention`` on the theory
        # that attention violates the position-locality serial streaming
        # required. That theory is retired: MentalModel.xml runs serial
        # **with** attention by design (attention narrows the per-word
        # pipeline — a focused beam rather than a position-locality
        # violation). The guard is lifted; serial + attention is now the
        # supported, documented, trained regime. (No downgrade is applied.)

        # Per-word router-fire gating knob ``<architecture><routerWireSerial>``
        # (Task 4 / plan §4). Values:
        #   * ``per-word`` — fire ``symbolSpace.compose`` once per word in
        #     the serial per-word loop (the intra-predictor's routing
        #     context); boundary fire OFF.
        #   * ``boundary`` — fire only at the sentence boundary
        #     (``_chart_compose_at_C`` / ``_chart_generate_from_stm``); the
        #     inter-sentence predictor's routing snapshot.
        #   * ``both`` (DEFAULT) — per-word during training so the
        #     intra-predictor sees routing context, AND boundary still
        #     fires for the inter-sentence predictor. Default ``both``
        #     preserves the pre-existing boundary-fire behaviour.
        #   * ``off`` — neither fires.
        # Read with the same accessor idiom as the sibling
        # ``architecture.serial`` knob above (the
        # ``<routerWireSerial>`` element is a direct child of
        # ``<architecture>``, not under ``<training>``).
        _rws_raw = TheXMLConfig.get(
            "architecture.routerWireSerial", default=None)
        _rws = (str(_rws_raw).strip() if _rws_raw is not None else "both")
        if _rws not in ("per-word", "boundary", "both", "off"):
            raise ValueError(
                f"<architecture><routerWireSerial> must be one of "
                f"'per-word', 'boundary', 'both', 'off' (got {_rws_raw!r}).")
        self.router_wire_serial = _rws

        # BracketExpectation ARMA(p, q) loss weight. ``BracketExpectation.observe``
        # returns a per-batch MSE which ``runBatch`` weights by
        # ``arma_scale`` before adding to ``TheError``.  Active only
        # when ``<training><sentenceExpectation>`` is true.
        self.arma_scale = float(
            TheXMLConfig.training("sentenceExpectationArmaScale", 0.0))
        if TheXMLConfig.training("sentencePrimingScale", None) is not None:
            raise ValueError("sentencePrimingScale is retired: compose never reads expectation")
        self.expectation_gain = float(TheXMLConfig.training("expectationGain", 1.0))
        if not math.isfinite(self.expectation_gain) or not 0. <= self.expectation_gain <= 1.:
            raise ValueError("expectationGain must be in [0, 1]")
        # Inter-sentence end-state prediction loss weight (Task 8, plan §9).
        # Mirrors ``arma_scale`` / ``intra_loss_weight``: ``runBatch`` scales
        # the consumed ``L_inter`` by this. Active only when the discourse
        # layer is present (``<training><sentenceExpectation>`` true).
        self.word_expectation_weight = float(TheXMLConfig.training("wordExpectationLossWeight", 0.1))
        self.word_expectation_gain = float(TheXMLConfig.training("wordExpectationArmaScale", 1.0))
        self.inter_loss_weight = float(
            TheXMLConfig.training("sentenceExpectationLossWeight", 0.1))
        self.expectation_policy_weight = float(TheXMLConfig.training("expectationPolicyWeight", 0.))
        self.expectation_query_budget = int(TheXMLConfig.training("expectationQueryBudget", 64))
        if (not math.isfinite(self.expectation_policy_weight) or self.expectation_policy_weight < 0
                or self.expectation_query_budget < 0):
            raise ValueError("expectation policy weight and query budget must be non-negative")
        # InfoNCE next-idea contrastive term weight + temperature (the discourse
        # layer accumulates it; runBatch consumes + weights it). 0.0 -> MSE-only.
        self.inter_contrastive_weight = float(
            TheXMLConfig.training("sentenceExpectationContrastiveWeight", 0.0))
        self.inter_contrastive_temp = float(
            TheXMLConfig.training("interContrastiveTemp", 0.1))
        # Every retained serial grammar reading uses its tied inverse.
        self.reconstruction_scope = self._understanding_reconstruction_scope()
        self.reconstruct_in_loop = self.reconstruction_scope == 'understanding'
        self.answer_record_reader = None
        from AnswerComparison import AnswerComparison
        self.comparison_reader = AnswerComparison() if self.word_brackets else None
        if self.word_brackets and not self.answer_synthesis:
            from SentenceUnderstanding import SentenceRecordReader
            width = int(self.conceptualSpace.muxedSize)
            size = math.prod(self.outputSpace.outputShape)
            self.answer_record_reader = SentenceRecordReader(width, size).to(TheDevice.get())
        self.detached_reverse = False  # diagnostic; no student runtime exists
        self._recon_keep_ideas = self.reconstruct_in_loop
        self._recon_completed = False
        self._reconstruction_product = None
        self.reconstruction_placement = str(
            TheXMLConfig.training("reconstructionPlacement", "graph")).strip().lower()
        if self.reconstruction_placement not in ("graph", "compiled", "eager"):
            raise ValueError("reconstructionPlacement must be graph, compiled or eager")
        self.reconstruction_basis_limit = int(
            TheXMLConfig.training("reconstructionBasisLimit", 16))
        if self.reconstruction_basis_limit < 1:
            raise ValueError("reconstructionBasisLimit must be positive")
        # Slice 3: the answer realisation's generate walk as the second
        # compiled loop (its own state, policy and termination).
        self.output_in_loop = bool(
            TheXMLConfig.training("outputInLoop", False))
        # The global projection is retired. Reject stale configuration rather
        # than silently promising a training policy that no longer exists.
        for retired in ("reconstructionPriority", "outputGradientRatio",
                        "reconstructionLossTolerance", "forwardGrammarWeight"):
            if TheXMLConfig.training(retired, None) is not None:
                raise ValueError(f"{retired} is retired; objectives use separate state paths")
        self.grammar_lesson_weight = float(
            TheXMLConfig.training("grammarLessonWeight", 1.0))
        if not math.isfinite(self.grammar_lesson_weight) or self.grammar_lesson_weight < 0:
            raise ValueError("grammarLessonWeight must be finite and nonnegative")
        _pack_env = os.environ.get("BASIC_PACK_SENTENCES")
        self.pack_sentences = bool(
            TheXMLConfig.training("packSentences", False))
        if _pack_env is not None:
            self.pack_sentences = _pack_env.strip().lower() in (
                "1", "true", "yes", "on")
        # Trial-split predictive training: fraction of training BATCHES run as
        # PURE next-idea prediction (recon terms zeroed). 0.0 -> every trial is
        # reconstruct -> byte-identical.
        self.prediction_trial_ratio = float(
            TheXMLConfig.get("architecture.predictionTrialRatio",
                             default=0.0) or 0.0)

        if "trainEmbedding" in arch and not isinstance(arch["trainEmbedding"], dict):
            te = arch["trainEmbedding"]
        elif "trainEmbeddings" in arch and not isinstance(arch["trainEmbeddings"], dict):
            te = arch["trainEmbeddings"]
        else:
            te = _t("trainEmbedding")
        if te is True:
            te = "BOTH"
        elif te is False or te is None:
            te = "NONE"
        self.train_embedding = te.upper()
        self.optimize_embedding = self.train_embedding not in ("NONE", "CBOW", "SBOW")
        # Stage 7 (doc/plans/2026-05-27-perceptstore-meta-taxonomy-
        # reentrancy.md): radix mode reroutes ``vocabulary`` to the
        # PerceptStore, but the orthographic-API Embedding still lives
        # on ``subspace.what`` (constructed by ``_build_what_basis``).
        # Resolve the Embedding via ``subspace.what`` so the back-ref
        # wiring + optimizer hook reach the right object regardless of
        # chunking mode.
        _emb_legacy = getattr(self.perceptualSpace.subspace, "what", None)
        if not isinstance(_emb_legacy, Embedding):
            _emb_legacy = (self.perceptualSpace.vocabulary
                           if isinstance(self.perceptualSpace.vocabulary,
                                         Embedding)
                           else None)
        if self.optimize_embedding and _emb_legacy is not None:
            emb_params = _emb_legacy.embedding_parameters()
            self.perceptualSpace.params = self.perceptualSpace.params + emb_params
        self.loss.embedding_scale = float(_t("embeddingScale") or 0.1)
        self.loss.conceptual_similarity_scale = float(
            _t("conceptualSimilarityScale", 0.0) or 0.0)
        # §20: codes have one unconstrained gradient owner, reconstruction.
        if float(_t("conceptualContextLearningRate", 0.0) or 0.0) != 0.0:
            raise ValueError("contextual code rotation is retired; conceptualContextLearningRate must be 0")
        # <definitionSparsityScale> (snap contract sec 5, 2026-07-06): lambda
        # for the rank-ordered soft-L0 that keeps concept definitions compact.
        # 0.0 (default) disables the penalty -- byte-identical.
        self.loss.definition_sparsity_scale = float(
            _t("definitionSparsityScale", 0.0) or 0.0)
        if _emb_legacy is not None:
            _emb_legacy.optimize_embedding = self.optimize_embedding
            object.__setattr__(_emb_legacy, "_model", self)

        self.checkpoint_every_batches = int(os.environ.get(
            "BASIC_CHECKPOINT_EVERY_BATCHES",
            _t("checkpointEveryBatches", 0) or 0,
        ))
        self._training_step_count = 0

        # Separate physical capacity from logical occupancy before autoload.
        # Legacy checkpoints have no active_mask key; VectorQuantize's load
        # hook then preserves this configured prefix instead of exposing the
        # entire preallocated reserve. Future masked checkpoints overwrite it
        # with their persisted active prefix.
        self._configure_aligned_active_codebooks()

        _autoload_env = os.environ.get("BASIC_AUTOLOAD")
        _autoload = bool(_t("autoload"))
        if _autoload_env is not None:
            _autoload = _autoload_env.strip().lower() in (
                "1", "true", "yes", "on")
        if _autoload:
            # Load from the same resolved path used by autosave. Previously an
            # empty <weightsPath> loaded "" while saving used the output-dir
            # fallback, so an autosaved run could never resume.
            wpath = self._checkpoint_path()
            # Checkpoint tensors include lazily registered grammar state.
            # Materialize those destination modules before loading an existing
            # file; doing it afterward would silently discard learned keys.
            # WholeSpace property growth is deliberately not prewarmed here:
            # it is independent of ConceptualSpace capacity and must happen at
            # an explicit optimizer/compiled-graph reset boundary.
            if os.path.exists(wpath):
                self._prewarm_checkpoint_shapes()
            # Single-artifact load: state_dict + vocab_extras +
            # bpe_extras all ride in the .ckpt. The separate .kv
            # embedding artifact was retired (2026-05-12).
            # Autoload: fail fast on a stale/mismatched ckpt (the
            # bivector retirement invalidates pre-refactor weights)
            # instead of silently proceeding on fresh init then crashing.
            self.load_weights(wpath, require_match=True)
        self.max_response_length = arch["maxResponseLength"]

        # LTM consolidation FU (Change 3, 2026-06-18): provisioning the
        # unified LTM from the XML <truthSet> now runs the truth texts through
        # the REAL forward pipeline (so the parse yields real encodings + a
        # real NP/VP/NP split), which requires the dataset to be LOADED. At
        # construction time the data is NOT yet loaded, so provisioning is
        # DEFERRED to the first ``runEpoch`` (lazy, guarded by
        # ``self._ltm_provisioned``); see ``runEpoch``. ``provision_ltm()``
        # stays callable explicitly (tests / serve) after data is loaded.
        self._ltm_provisioned = False

        return cfg

    def create(self, **kwargs):
        """Override in subclasses to build model architecture.

        ``BaseModel.create`` is a no-op; ``BasicModel.create`` wires
        the actual space stack.
        """
        pass

    def objective_parameter_groups(self, optimizer):
        """Partition physical optimizer parameters by their sole writer."""
        available = {id(p): p for group in optimizer.param_groups
                     for p in group['params'] if p.requires_grad}
        def parameters(modules):
            return {id(p) for module in modules if isinstance(module, nn.Module)
                    for p in module.parameters() if id(p) in available}
        discourse = getattr(getattr(self, 'symbolSpace', None), 'expectation', None)
        expectation = parameters([
            *(getattr(cs, 'intraSentenceLayer', None) for cs in getattr(self, 'conceptualSpaces', ())),
            getattr(discourse, 'predictor', None), getattr(discourse, '_inter_predictor', None),
            getattr(discourse, 'word_predictor', None)])
        output = parameters([getattr(self, 'outputSpace', None),
            getattr(self, 'answer_attention', None), getattr(self, 'answer_record_reader', None),
            getattr(self, 'comparison_reader', None)])
        synthesis = getattr(self, 'synthesis_parameters', None)
        if synthesis is not None:
            output.update(id(p) for p in synthesis() if id(p) in available)
        # Text readout can register the percept vocabulary as a convenience
        # alias. Registration there does not transfer its training ownership.
        output.difference_update(parameters([
            getattr(getattr(self, 'outputSpace', None), '_vocabulary', None)]))
        if getattr(getattr(self, 'outputSpace', None), 'concept_ids', ()):
            # A named-pole output has no separate numeric head. Its sparse
            # evidence coefficients are the answer's reader, not the codes.
            for cs in getattr(self, 'conceptualSpaces', ()):
                allocator = getattr(cs, '_concept_allocator', None)
                if allocator is not None:
                    values = allocator.layer(0).values
                    if id(values) in available:
                        output.add(id(values))
        if expectation & output:
            raise RuntimeError('expectation and answer share an optimizer parameter')
        language = getattr(self, 'languageSpace', None)
        layer = getattr(getattr(self, 'symbolSpace', None), 'languageLayer', None)
        operation = getattr(layer, 'operation_layer', None)
        compose = parameters([getattr(operation, 'chooser', None)])
        # The anchor scorer is stateless: its operation logits are owned by
        # the containing layer's three anchors. MLP choosers own their weights.
        compose_policy = compose | {id(p) for name in ('stop_anchor', 'reduce_anchor', 'apply_anchor')
                                if (p := getattr(operation, name, None)) is not None
                                and id(p) in available}
        generate = parameters([getattr(language, 'generate_policy', None)])
        decoder = generate | parameters([getattr(op, 'gl', op) for op in
            (*getattr(language, '_generate_binary_ops', ()),
             *getattr(language, '_generate_unary_ops', ()))])
        output.difference_update(decoder)
        reconstruction = set(available) - expectation - output
        if not (compose_policy | generate) <= reconstruction:
            raise RuntimeError('grammar lessons must train their chooser owner only')
        return {name: tuple(available[i] for i in available if i in ids) for name, ids in
                (('reconstruction', reconstruction), ('expectation', expectation), ('output', output),
                 ('compose_lesson', compose), ('generate_lesson', generate))}

    def _adopt_fresh_parameters(self, optimizer):
        """Join lazily enabled readers/predictors before their first backward."""
        fresh = getattr(self, '_fresh_synthesis_params', None)
        if optimizer is None or not fresh:
            return
        present = {id(p) for group in optimizer.param_groups for p in group['params']}
        new = []
        for parameter in fresh:
            if parameter.requires_grad and id(parameter) not in present:
                new.append(parameter)
                present.add(id(parameter))
        if new:
            optimizer.add_param_group({'params': new})
        fresh.clear()

    def ownership_gradient_diagnostics(self, optimizer):
        """Report actual backward writers, including inactive owned parameters."""
        names = {id(p): name for name, p in self.named_parameters()}
        observed = getattr(self, '_objective_gradient_writers', {})
        owners = self.objective_parameter_groups(optimizer)
        rows = []
        for owner in ('reconstruction', 'expectation', 'output'):
            for parameter in owners[owner]:
                writers = sorted(observed.get(id(parameter), ()))
                if writers and writers != [owner]:
                    raise RuntimeError('objective ownership audit failed')
                rows.append(dict(parameter=names.get(id(parameter), '<unregistered>'),
                    owner=owner, writers=writers, elements=parameter.numel()))
        return dict(parameters=rows, conflicts=0,
                    active=sum(bool(row['writers']) for row in rows),
                    inactive=sum(not row['writers'] for row in rows))

    def _sample_gradient_diagnostics(self, objectives, optimizer):
        """Report ownership; the backward independently enforces the partition."""
        import json
        try:
            report = self.ownership_gradient_diagnostics(optimizer)
        except (FloatingPointError, ArithmeticError) as error:
            import warnings
            warnings.warn(f'ownership diagnostic unavailable: {error}', RuntimeWarning)
            return
        self._last_ownership_audit = report
        TheMessage('  [objective-ownership] ' + json.dumps(report, sort_keys=True))

    def _backward_training_loss(self, total_loss, amp_scaler=None, *, optimizer=None):
        """Restrict every registered objective to its own optimizer weights."""
        from ObjectiveOwnership import registry_costs, backward_owned
        sentence = bool(getattr(self, '_sentence_backward', False))
        optimizer = self._sentence_optimizer if sentence else optimizer
        if optimizer is None:
            raise RuntimeError('owned backward requires the live optimizer')
        registry = self._sentence_cost_registry if sentence else self.errors
        reader = getattr(self, '_sentence_reader_costs', None) if sentence else None
        rows = getattr(self, '_sentence_reader_rows', None) if sentence else None
        costs = registry_costs(registry, reader_rows=(
            torch.zeros_like(registry.row_mask) if reader is not None else rows),
            expectation_rows=(torch.zeros_like(registry.row_mask) if reader is not None else None))
        if reader is not None:
            costs.update(reader)
        owners = self.objective_parameter_groups(optimizer)
        scale = 1. if amp_scaler is None else amp_scaler.get_scale()
        if amp_scaler is not None:
            amp_scaler.scale(total_loss)  # initialize the scaler on this device
        writers = self.__dict__.setdefault('_objective_gradient_writers', {})
        backward_owned(costs, owners, scale=scale, audit=writers,
            pullback=getattr(self, '_sentence_pullback', None) if sentence else None)

    def _configure_concept_readout_l1(self, optimizer, *, stage=True):
        """Stage one weak-L1 update and return its detached reporting cost.

        Match the first-stage owner used by _stage_sparse_concept_support;
        shared stage aliases must not multiply either the cost or the update.
        L1 is an intentional sparse-basis tradeoff, not reconstruction or
        output error, and does not enter autograd a second time.
        """
        spaces = list(getattr(self, "conceptualSpaces", None) or ())
        owner = spaces[0] if spaces else getattr(self, "conceptualSpace", None)
        readout = getattr(owner, "concepts_from_percepts", None)
        if readout is None or not readout.l1_lambda:
            return None
        isp = getattr(self, "inputSpace", None)
        rows = getattr(isp, "_ar_word_concept_rows", None)
        roles = getattr(isp, "_ar_percept_reference_roles", None)
        if not torch.is_tensor(rows) or not torch.is_tensor(roles):
            return None  # no live indexed concept readout in this presentation
        sentence = getattr(self, '_open_sentence_slot', None)
        ids = getattr(isp, '_packed_sentence_ids', None)
        if sentence is not None and torch.is_tensor(ids):
            rows = torch.where(ids == sentence, rows, -1)
        batch = readout.l1_batch(rows, roles)
        if batch is None:
            return None
        selected, mask, strength, cost = batch
        self._concept_readout_l1_strength = readout.l1_lambda
        if stage:
            configure_l1_proximal(optimizer, readout.coefficients, selected, mask, strength)
        return cost

    def getOptimizer(self, lr=0.01):
        """Reconstruction uses momentum descent; predictors and readers use Adam.

        Walks ``self.spaces`` collecting params via each space's
        ``getParameters()`` (which excludes alpha-managed params).
        Dedup by tensor ``data_ptr`` so a parameter owned by multiple
        modules is only optimized once.

        When ``trainEmbedding`` is NONE or AR, embedding parameters
        are excluded from the optimizer.
        """
        params = []
        seen = set()
        for s in self.spaces:
            for p in s.getParameters():
                if not bool(getattr(p, "requires_grad", False)):
                    continue
                if p.data_ptr() not in seen:
                    seen.add(p.data_ptr())
                    params.append(p)
        # Reading / global attention (doc/specs/reading-attention.md): the
        # learned attention readouts are model-level nn.Modules (NOT Spaces), so
        # the ``self.spaces`` walk above misses their params -- collect them
        # explicitly (deduped). Absent / gate-off => the attr is None => no
        # extra params => byte-identical optimizer state.
        for _att_name in ("answer_attention", "answer_record_reader", "comparison_reader"):
            _att = getattr(self, _att_name, None)
            if _att is not None:
                for p in _att.parameters():
                    if p.requires_grad and p.data_ptr() not in seen:
                        seen.add(p.data_ptr())
                        params.append(p)
        # Include answer modules already built or restored before this
        # optimizer is created. Later lazy modules still join in runBatch;
        # its identity check keeps the queued parameters from joining twice.
        synthesis_parameters = getattr(self, "synthesis_parameters", None)
        if synthesis_parameters is not None:
            for p in synthesis_parameters():
                if p.requires_grad and p.data_ptr() not in seen:
                    seen.add(p.data_ptr())
                    params.append(p)
        # A4 (2026-06-06 parallel-conceptual-recurrence): the per-stage
        # ConceptualCombine is HELD BY its ConceptualSpace (registered in
        # ``cs.layers`` + ``cs.params`` at build time), so the ``self.spaces``
        # walk above already collects its LDU / butterfly weights -- no
        # separate model-level collection is needed.
        # Identify the perceptual-embedding params and the codebook's
        # sparse-grad preference for the objective owner's sparse optimizer.
        sparse_ptrs = set()
        embedding_ptrs = set()
        if hasattr(self, 'perceptualSpace') and isinstance(
                self.perceptualSpace.vocabulary, Embedding):
            voc = self.perceptualSpace.vocabulary
            # Mark large embedding codebooks for sparse-grad lookup;
            # _lookup_modality reads voc.sparse_grad.
            try:
                voc.use_sparse_grad()
            except Exception:
                pass
            sparse_grad = bool(getattr(voc, 'sparse_grad', False))
            for p in voc.embedding_parameters():
                embedding_ptrs.add(p.data_ptr())
                if sparse_grad:
                    sparse_ptrs.add(p.data_ptr())
        # Exclude embedding params entirely when trainEmbedding is NONE / AR
        if not getattr(self, 'optimize_embedding', False):
            params = [p for p in params if p.data_ptr() not in embedding_ptrs]
            sparse_ptrs.clear()

        # The shared aligned ConceptualSpace dictionary has a stronger memory
        # contract than an ordinary sparse embedding. Stock SparseAdam still
        # allocates TWO full-size dense moments, which would add ~8 GiB for the
        # 1M x 1032 fp32 table. Its lookup surface emits sparse row gradients,
        # so route it to compact-prefix RowLocalSGD. Answer-owned evidence
        # coefficients use the corresponding compact RowLocalAdam.
        row_local_ptrs = set()
        seen_codebooks = set()
        for cs in list(getattr(self, "conceptualSpaces", None) or ()):
            readout = getattr(cs, "concepts_from_percepts", None)
            coefficients = getattr(readout, "coefficients", None)
            if isinstance(coefficients, nn.Parameter) and coefficients.requires_grad:
                row_local_ptrs.add(coefficients.data_ptr())
            cb = getattr(cs, "similarity_codebook", None)
            if cb is None or id(cb) in seen_codebooks:
                continue
            seen_codebooks.add(id(cb))
            W = getattr(cb, "W", None)
            if (bool(getattr(cb, "sparse_lookup_grad", False))
                    and isinstance(W, nn.Parameter) and W.requires_grad):
                row_local_ptrs.add(W.data_ptr())
        if row_local_ptrs & sparse_ptrs:
            raise RuntimeError(
                "a parameter cannot use both ordinary sparse and row-local optimization")

        # Split by objective first, then storage. Reconstruction uses SGD
        # (compact row-local momentum for concepts); readers and predictors
        # use Adam. Compact state follows the admitted concept-row prefix.
        # CUDA-graph capture (the brick body; test_brick_no_sync)
        # requires the optimizer keep its step counter on-device:
        # stock Adam's _multi_tensor_adam does _get_value(step).item()
        # per param otherwise -- one cudaMemcpyDtoH per param per step.
        # capturable=True keeps step on-device. Gated to actual CUDA
        # params (no-op/overhead on CPU/MPS; SparseAdam has no such flag).
        _cap = any(getattr(p, "is_cuda", False) for p in params)
        # Output-head LR scale: the regression readout is ill-conditioned (the
        # class-flipping feature direction is low-variance) and co-adapts with
        # the upstream features during joint training, so a single shared LR
        # leaves it under-converged at the configured epoch budget (XOR sticks
        # near the feature mean ~0.5 despite the features being separable).
        # <OutputSpace><lrScale> puts the OutputSpace params in their own Adam
        # group at lr*scale; default 1.0 => one group, byte-identical.
        try:
            out_lr_scale = float(
                TheXMLConfig.space("OutputSpace", "lrScale", default=1.0))
        except Exception:
            out_lr_scale = 1.0
        output_ptrs = set()
        if out_lr_scale != 1.0 and hasattr(self, "outputSpace"):
            output_ptrs = {p.data_ptr()
                           for p in self.outputSpace.getParameters()}

        def _dense_arg(dense_params):
            """Plain param list (scale==1.0) or two LR-scaled groups (the
            OutputSpace head at lr*scale, the rest at lr)."""
            if not output_ptrs:
                return dense_params
            head = [p for p in dense_params if p.data_ptr() in output_ptrs]
            rest = [p for p in dense_params if p.data_ptr() not in output_ptrs]
            groups = []
            if rest:
                groups.append({"params": rest, "lr": lr})
            if head:
                groups.append({"params": head, "lr": lr * out_lr_scale})
            return groups

        from types import SimpleNamespace
        owners = self.objective_parameter_groups(SimpleNamespace(param_groups=[{'params': params}]))
        reconstruct_ids = {id(p) for p in owners['reconstruction']}
        reconstruction = [p for p in params if id(p) in reconstruct_ids]
        adaptive = [p for p in params if id(p) not in reconstruct_ids]
        optimizers = []
        # Keep Adam first so lazy answer/predictor modules join their owner.
        dense_adaptive = [p for p in adaptive if p.data_ptr() not in sparse_ptrs | row_local_ptrs]
        optimizers.append(Adam(_dense_arg(dense_adaptive) if dense_adaptive else [{'params': []}],
                               lr=lr, capturable=_cap))
        optimizers[-1].objective_owner = 'adaptive'
        row_adaptive = [p for p in adaptive if p.data_ptr() in row_local_ptrs]
        if row_adaptive:
            optimizers.append(RowLocalAdam(row_adaptive, lr=lr, moment_dtype=torch.bfloat16))
        sparse_adaptive = [p for p in adaptive if p.data_ptr() in sparse_ptrs]
        if sparse_adaptive:
            optimizers.append(SparseAdam(sparse_adaptive, lr=lr))
        # Momentum .9 retains the existing first-moment time constant. The
        # learning rate stays configured; there is no variance normalization.
        dense_reconstruction = [p for p in reconstruction if p.data_ptr() not in row_local_ptrs]
        optimizers.append(SGD(dense_reconstruction or [{'params': []}], lr=lr, momentum=.9))
        optimizers[-1].objective_owner = 'reconstruction'
        row_reconstruction = [p for p in reconstruction if p.data_ptr() in row_local_ptrs]
        if row_reconstruction:
            optimizers.append(RowLocalSGD(row_reconstruction, lr=lr, momentum=.9))
        if not optimizers:
            raise RuntimeError("model exposes no trainable optimizer parameters")
        optimizer = MultiOptimizer(optimizers)
        def route_new(parameters):
            grouped = self.objective_parameter_groups(SimpleNamespace(param_groups=[{'params': list(parameters)}]))
            return {'reconstruction': grouped['reconstruction'],
                    'adaptive': grouped['expectation'] + grouped['output']}
        optimizer.route_parameters = route_new
        pending = getattr(self, "_pending_optimizer_state", None)
        if pending is not None:
            saved_manifest = getattr(
                self, "_pending_optimizer_manifest", None)
            legacy_shapes = getattr(
                self, "_pending_legacy_state_shapes", None) or {}
            require_match = bool(getattr(
                self, "_pending_optimizer_require_match", False))
            reset_wholespace = bool(getattr(
                self, "_pending_optimizer_reset_wholespace", False))
            try:
                live_manifest = build_optimizer_param_manifest(
                    optimizer, self.named_parameters())
                if saved_manifest is None:
                    saved_manifest = infer_legacy_optimizer_param_manifest(
                        live_manifest, legacy_shapes, pending)
                remapped = remap_optimizer_state_by_name(
                    pending, saved_manifest, optimizer.state_dict(),
                    live_manifest,
                    reset_wholespace=reset_wholespace,
                    reset_parameters=getattr(self, "_pending_thought_policy_reset", ()),
                    parameter_row_maps=getattr(
                        self, "_pending_generate_policy_rows", None))
                optimizer.load_state_dict(remapped.state)
                self._normalize_optimizer_state_shapes(optimizer)
                TheMessage(
                    f"[{self.name}] {remapped.diagnostics.message()}")
            except ValueError as exc:
                message = (
                    f"[{self.name}] Optimizer checkpoint was not restored: "
                    f"{exc}")
                if require_match:
                    raise ValueError(message) from exc
                TheMessage(message)
            finally:
                self._pending_optimizer_state = None
                self._pending_optimizer_manifest = None
                self._pending_legacy_state_shapes = None
                self._pending_optimizer_reset_wholespace = False
                self._pending_optimizer_require_match = False
                self._pending_generate_policy_rows = None
        # PartSpace may have to install a previously unseen byte before the
        # first codebook gather of a batch. Keep the current optimizer as a
        # non-module boundary context so that eager growth can migrate Adam
        # state and ownership instead of orphaning the old Parameter.
        part_space = getattr(self, "perceptualSpace", None)
        if part_space is not None:
            object.__setattr__(part_space, "_radix_optimizer", optimizer)
        for cs in list(getattr(self, 'conceptualSpaces', ()) or ()):
            allocator = getattr(cs, '_concept_allocator', None)
            if allocator is not None:
                for layer in allocator._layers.values():
                    layer.migrate_part_moments(optimizer)
                    # Definition growth is a boundary mutation. Attach its
                    # current leaves now, before any candidate is appended.
                    for matrix in layer.definition_matrices():
                        matrix._optimizer = optimizer
        return optimizer

    def rebuild_optimizer(self):
        """Rebuild the main optimizer after codebook expansion.

        Reads the learning rate from the existing optimizer's first
        param group and constructs a fresh ``getOptimizer`` over the
        current parameter set, picking up any newly added rows.
        """
        if self._optimizer is None:
            return
        lr = self._optimizer.param_groups[0]['lr']
        self._optimizer = self.getOptimizer(lr=lr)

    def _aligned_inventory_capacity(self):
        """Return the serial-aligned concept-reference capacity, or ``None``.

        ConceptualSpace owns this address space.  Downstream symbols are
        references into it; WholeSpace rows are upstream properties and are a
        separate inventory whose size may differ.
        """
        if not (getattr(self, "concept_binding", None) == "aligned"
                and bool(getattr(self, "word_brackets", False))):
            return None
        n_concepts = int(getattr(self, "nConceptCodes", 0) or 0)
        if n_concepts <= 0:
            raise ValueError(
                "aligned checkpoint migration requires a positive "
                f"ConceptualSpace inventory; got CS={n_concepts}")
        return n_concepts

    def _aligned_capacity_codebooks(self):
        """Return each physical full-capacity concept Codebook once.

        Some ConceptualSpace dictionaries are registered through compatibility
        aliases, so deduplicate by module identity rather than by state-dict
        path.  WholeSpace property codebooks and legacy ``analysis_store``
        modules never participate in concept-capacity activation.
        """
        capacity = self._aligned_inventory_capacity()
        if capacity is None:
            return []
        candidates = []
        for cs in list(getattr(self, "conceptualSpaces", None) or ()):
            candidates.append(getattr(cs, "similarity_codebook", None))
        out = []
        seen = set()
        for cb in candidates:
            if not isinstance(cb, Codebook) or id(cb) in seen:
                continue
            W = cb.getW()
            if (not torch.is_tensor(W) or W.ndim != 2
                    or int(W.shape[0]) != capacity):
                continue
            vq = getattr(cb, "vq", None)
            if vq is None or not hasattr(vq, "set_active_rows"):
                continue
            seen.add(id(cb))
            out.append(cb)
        return out

    @staticmethod
    def _active_prefix_rows(vq):
        """Validate a contiguous nonempty active mask and return its length."""
        mask = getattr(vq, "active_mask", None)
        W = getattr(vq, "codebook", None)
        if (not torch.is_tensor(mask) or mask.dtype != torch.bool
                or not torch.is_tensor(W) or mask.ndim != 1
                or int(mask.shape[0]) != int(W.shape[0])):
            raise RuntimeError(
                "aligned VQ active-mask shape/dtype drift: "
                f"mask={None if not torch.is_tensor(mask) else tuple(mask.shape)}, "
                f"codebook={None if not torch.is_tensor(W) else tuple(W.shape)}")
        n = int(mask.sum().item())
        if n < 1:
            raise RuntimeError("aligned VQ must keep at least one active row")
        if (not bool(mask[:n].all().item())
                or (n < int(mask.shape[0])
                    and bool(mask[n:].any().item()))):
            raise RuntimeError(
                "aligned VQ active rows must be one contiguous prefix")
        cached = int(getattr(vq, "_active_rows_count", n))
        if cached != n:
            raise RuntimeError(
                "aligned VQ active-prefix cache drift: "
                f"mask has {n} rows, cached count is {cached}")
        return n

    def _configure_aligned_active_codebooks(self):
        """Install the configured active prefix before checkpoint autoload.

        Physical ``nVectors`` is the optimizer-owned capacity. Logical growth
        only mutates full-shape bool masks, so W, EMA tensors and Adam ownership
        never change identity or shape. VQ reads the active prefix only, so each
        new power-of-two width causes one compiled-graph specialization.
        """
        capacity = self._aligned_inventory_capacity()
        if capacity is None:
            return None
        cs_active = int(TheXMLConfig.space(
            "ConceptualSpace", "activeVectors", default=capacity) or capacity)
        if not (1 <= cs_active <= capacity):
            raise ValueError(
                "ConceptualSpace.activeVectors must be within physical "
                f"concept capacity: active={cs_active}, capacity={capacity}")
        codebooks = self._aligned_capacity_codebooks()
        if not codebooks:
            raise RuntimeError(
                "ConceptualSpace.activeVectors is configured, but no "
                "full-capacity concept VQ Codebooks were found")
        for cb in codebooks:
            cb.vq.set_active_rows(cs_active)
            # This physical table is optimizer-owned at its final configured
            # capacity. Logical growth reveals rows through the full-shape VQ
            # mask below; it must never replace W and orphan RowLocalAdam or a
            # compiled graph. Perceptual owners freeze their own allocations.
            cb.freeze_capacity("aligned ConceptualSpace codebook")
        self._active_inventory_rows = cs_active
        return cs_active


    def _stage_legacy_discourse_prediction(self, discourse,
                                           *, fullgraph_word_loop=False):
        """Stage the retired ARMA snapshot only for non-sentence-loop paths.

        The canonical complete W-loop has a separate, eager
        pure-composition contract; expectation is compared at the closing.  The
        older ``_predicted_snapshot`` tuple has no consumer in that path.
        Parking ``(None, None)`` on the first sentence and tensors on the
        next one made Dynamo guard on a Python tuple and recompile the entire
        W graph.  Do not stage that obsolete surface for a full sentence loop.

        The compatibility word-cell/eager paths retain the old staging and
        AMP casting behavior because their forward still calls the legacy
        ``BracketExpectation.predict`` shim.
        """
        if discourse is None or fullgraph_word_loop:
            return False
        discourse.stage_prediction()
        # Cast the staged ARMA prediction tuple to the active AMP dtype so a
        # dtype mismatch inside the compatibility compiled forward does not
        # split the graph (doc/plans/2026-05-20-static-per-word-loop-impl.md
        # §2.7).  This remains an eager sentence-boundary operation.
        target_dtype = None
        if _util.MODEL_AMP == "fp16":
            target_dtype = torch.float16
        elif _util.MODEL_AMP == "bf16":
            target_dtype = torch.bfloat16
        staged = getattr(discourse, "_staged_prediction", None)
        if target_dtype is not None and staged is not None:
            pred, conf = staged
            if (pred is not None
                    and torch.is_tensor(pred)
                    and pred.is_floating_point()
                    and pred.dtype != target_dtype):
                pred = pred.to(target_dtype)
            if (conf is not None
                    and torch.is_tensor(conf)
                    and conf.is_floating_point()
                    and conf.dtype != target_dtype):
                conf = conf.to(target_dtype)
            discourse._staged_prediction = (pred, conf)
        return True

    def _ensure_aligned_active_rows(self, required_rows):
        """Reveal a power-of-two prefix across every aligned VQ in place."""
        capacity = self._aligned_inventory_capacity()
        if capacity is None:
            return None
        required = max(1, int(required_rows))
        if required > capacity:
            raise RuntimeError(
                f"aligned codebook physical capacity exhausted: required "
                f"{required} rows, capacity {capacity}; no mask was changed")
        current = int(getattr(self, "_active_inventory_rows", 0) or 0)
        if current < 1:
            counts = {
                self._active_prefix_rows(cb.vq)
                for cb in self._aligned_capacity_codebooks()
            }
            if len(counts) != 1:
                raise RuntimeError(
                    f"aligned VQ active-prefix mismatch: {sorted(counts)}")
            current = counts.pop()
        if required <= current:
            return current
        codebooks = self._aligned_capacity_codebooks()
        counts = {self._active_prefix_rows(cb.vq) for cb in codebooks}
        if counts != {current}:
            raise RuntimeError(
                "aligned VQ active-prefix mismatch before growth: "
                f"model={current}, codebooks={sorted(counts)}; no mask was "
                "changed")
        target = min(capacity, 1 << (required - 1).bit_length())
        target = max(current, target)
        for cb in codebooks:
            cb.vq.set_active_rows(target)
        self._active_inventory_rows = target
        TheMessage(
            f"[{self.name}] Activated aligned codebook prefix "
            f"{current} -> {target} rows (physical capacity {capacity}; "
            f"Parameter/optimizer shapes unchanged; compiled VQ paths "
            f"specialize on the new active width)")
        return target

    def _resync_aligned_active_codebooks(self):
        """Validate loaded masks and cover every restored concept id."""
        if self._aligned_inventory_capacity() is None:
            return None
        codebooks = self._aligned_capacity_codebooks()
        counts = {self._active_prefix_rows(cb.vq) for cb in codebooks}
        if len(counts) != 1:
            raise ValueError(
                f"checkpoint aligned VQ active-prefix mismatch: "
                f"{sorted(counts)}")
        active = counts.pop()
        self._active_inventory_rows = active
        required = 1
        for cs in list(getattr(self, "conceptualSpaces", None) or ()):
            alloc = getattr(cs, "_concept_allocator", None)
            if alloc is None:
                continue
            # next_id is one past every restored stable concept handle.
            required = max(required, int(getattr(alloc, "next_id", 1) or 1))
            for layer in getattr(alloc, "_layers", {}).values():
                tensor_rows = getattr(layer, "_tensor_rows", None) or {}
                if tensor_rows:
                    required = max(
                        required,
                        max(int(v) for v in tensor_rows.values()) + 1)
        return self._ensure_aligned_active_rows(required)

    def _canonicalize_shared_concept_checkpoint_state(self, state,
                                                       model_state):
        """Make every shared CS Codebook alias load stage 0's state.

        Before the aligned/property-basis architecture shared its conceptual
        dictionary, each subsymbolic stage saved an independent W plus VQ/EMA
        tables.  Stage 0 is authoritative during this migration: it owns the
        word autobind and the late conceptual cutover.  Populate every live
        alias from that one source before shape expansion/load_state_dict so a
        legacy divergent checkpoint loads strictly without letting later
        aliases overwrite the shared physical module.
        """
        if not getattr(self, 'concept_binding', None) == 'aligned':
            return 0
        spaces = list(getattr(self, "conceptualSpaces", None) or ())
        if not spaces:
            return 0
        shared = getattr(spaces[0], "similarity_codebook", None)
        if (not isinstance(shared, Codebook)
                or any(getattr(cs, "similarity_codebook", None) is not shared
                       for cs in spaces[1:])):
            return 0

        try:
            named = self.named_modules(remove_duplicate=False)
        except TypeError:  # older torch compatibility
            named = self.named_modules()
        prefixes = [
            name for name, module in named
            if module is shared and name
        ]
        if not prefixes:
            return 0
        preferred = "conceptualSpaces.0.similarity_codebook"
        prefixes.sort(key=lambda name: (
            0 if name == preferred else
            1 if name.startswith("conceptualSpaces.0.") else 2,
            name,
        ))

        replaced = 0
        used_non_stage0 = False
        for suffix in shared.state_dict().keys():
            aliases = [
                f"{prefix}.{suffix}" for prefix in prefixes
                if f"{prefix}.{suffix}" in model_state
            ]
            if not aliases:
                continue
            source_key = next((key for key in aliases if key in state), None)
            if source_key is None:
                continue
            if not source_key.startswith("conceptualSpaces.0."):
                used_non_stage0 = True
            source = state[source_key]
            for key in aliases:
                old = state.get(key)
                if old is not None and old is not source:
                    if (not torch.is_tensor(old) or not torch.is_tensor(source)
                            or int(old.data_ptr()) != int(source.data_ptr())):
                        replaced += 1
                state[key] = source

        if replaced or used_non_stage0:
            fallback = (
                " (stage 0 was absent for at least one tensor; the earliest "
                "available alias was used)" if used_non_stage0 else "")
            warnings.warn(
                "Shared ConceptualSpace checkpoint migration: selected the "
                "stage-0 similarity dictionary as canonical and replaced "
                f"{replaced} divergent stage/alias tensor(s){fallback}.",
                stacklevel=2,
            )
        return replaced

    def _expand_aligned_codebook_checkpoint_state(self, state, model_state):
        """Prefix-load a smaller aligned codebook into a larger build.

        This runs during autoload: the model has its final configured shapes,
        but no optimizer or compiled callable exists yet.  Existing rows keep
        their exact ids and values.  New rows retain their freshly constructed
        initialization (including VQ EMA/norm buffers); Adam's corresponding
        moments are padded separately by
        :meth:`_normalize_optimizer_state_shapes`.

        Only row-aligned state belonging to the ConceptualSpace dictionaries
        or their indexed Sigma readouts is eligible. Readout rows use the
        same stable concept addresses and must expand before autoload's
        shape preflight, not just inside a module load hook. WholeSpace
        property state and legacy ``analysis_store``
        state are intentionally excluded, even when their row counts happen
        to equal the concept capacity.
        """
        capacity = self._aligned_inventory_capacity()
        if capacity is None:
            return 0

        try:
            named = self.named_modules(remove_duplicate=False)
        except TypeError:  # older torch compatibility
            named = self.named_modules()
        eligible = set()
        concept_codebook_ids = {
            id(cb) for cb in self._aligned_capacity_codebooks()
        }
        readout_ids = {
            id(cs.concepts_from_percepts)
            for cs in list(getattr(self, "conceptualSpaces", None) or ())
            if getattr(cs, "concepts_from_percepts", None) is not None
        }
        row_keys = ("W", "vq.cluster_size", "vq.embed_avg",
                    "vq._b_norms_sq", "vq.active_mask")
        for name, module in named:
            if id(module) in readout_ids:
                eligible.add(f"{name}.coefficients" if name else "coefficients")
                continue
            if (not isinstance(module, Codebook)
                    or id(module) not in concept_codebook_ids):
                continue
            W = module.getW()
            if (not torch.is_tensor(W) or W.ndim != 2
                    or int(W.shape[0]) != capacity):
                continue
            prefix = f"{name}." if name else ""
            eligible.update(prefix + suffix for suffix in row_keys)

        # Duplicate registered paths often point at the same live storage.
        # The model was freshly constructed at final capacity, so preserve its
        # initialized tail and copy the learned prefix DIRECTLY into that live
        # storage once.  Point every state-dict alias back at the same detached
        # view.  Cloning a 1M x 512 W and EMA table here would add roughly
        # 4 GiB of avoidable checkpoint-migration peak memory.
        prepared_by_storage = {}
        source_storage_by_target = {}
        expanded = 0
        old_sizes = set()
        for key in sorted(eligible):
            if key not in state or key not in model_state:
                continue
            saved = state[key]
            live = model_state[key]
            if (not torch.is_tensor(saved) or not torch.is_tensor(live)
                    or saved.ndim == 0 or saved.ndim != live.ndim
                    or tuple(saved.shape[1:]) != tuple(live.shape[1:])
                    or int(saved.shape[0]) >= int(live.shape[0])):
                continue
            if int(live.shape[0]) != capacity:
                continue
            storage_key = (
                int(live.data_ptr()), tuple(live.shape), live.dtype,
                live.device.type, live.device.index,
            )
            grown = prepared_by_storage.get(storage_key)
            if grown is None:
                grown = live.detach()
                with torch.no_grad():
                    grown[:saved.shape[0]].copy_(
                        saved.detach().to(device=grown.device,
                                          dtype=grown.dtype))
                prepared_by_storage[storage_key] = grown
                source_storage_by_target[storage_key] = int(saved.data_ptr())
            else:
                # Alias paths must describe the same learned prefix.  A
                # disagreement is checkpoint corruption, not a migration.
                if (int(saved.data_ptr()) !=
                        source_storage_by_target[storage_key]
                        and not torch.equal(
                        grown[:saved.shape[0]],
                        saved.detach().to(device=grown.device,
                                          dtype=grown.dtype))):
                    raise ValueError(
                        f"aligned checkpoint aliases disagree for {key}")
            state[key] = grown
            old_sizes.add(int(saved.shape[0]))
            expanded += 1

        if expanded:
            TheMessage(
                f"[{self.name}] Expanded aligned codebook checkpoint rows "
                f"{sorted(old_sizes)} -> {capacity} across {expanded} state "
                f"keys ({len(prepared_by_storage)} physical tensors); "
                f"learned prefixes copied in place and initialized tails "
                f"preserved")
        return expanded

    def _expand_partspace_codebook_checkpoint_state(self, state, model_state):
        """Prefix-load a smaller radix PS table into a larger initial build.

        Runtime growth happens only at a batch boundary, but construction-time
        capacity increases are safe before optimizer/compiled ownership exists.
        Keep the checkpoint's learned rows exactly and retain the live model's
        initialization for the newly configured tail.
        """
        part_space = getattr(self, "perceptualSpace", None)
        basis = getattr(getattr(part_space, "subspace", None), "what", None)
        store = getattr(part_space, "percept_store", None)
        if (not isinstance(basis, Codebook) or store is None
                or getattr(store, "_basis", None) is not basis):
            return 0
        live_w = basis.getW()
        if not torch.is_tensor(live_w) or live_w.ndim != 2:
            return 0
        capacity = int(live_w.shape[0])

        try:
            named = self.named_modules(remove_duplicate=False)
        except TypeError:
            named = self.named_modules()
        prefixes = [
            f"{name}." if name else ""
            for name, module in named if module is basis
        ]
        if not prefixes:
            return 0
        local_state = basis.state_dict()
        eligible = set()
        for suffix, value in local_state.items():
            if (torch.is_tensor(value) and value.ndim > 0
                    and int(value.shape[0]) == capacity):
                eligible.update(prefix + suffix for prefix in prefixes)

        # As above for CS, the final-capacity live allocation already owns the
        # desired initialized tail.  Prefix-copy in place so migration never
        # clones the entire percept table merely to feed load_state_dict.
        prepared_by_storage = {}
        expanded = 0
        old_sizes = set()
        for key in sorted(eligible):
            if key not in state or key not in model_state:
                continue
            saved = state[key]
            live = model_state[key]
            if (not torch.is_tensor(saved) or not torch.is_tensor(live)
                    or saved.ndim == 0 or saved.ndim != live.ndim
                    or tuple(saved.shape[1:]) != tuple(live.shape[1:])
                    or int(saved.shape[0]) >= int(live.shape[0])
                    or int(live.shape[0]) != capacity):
                continue
            storage_key = (
                int(live.data_ptr()), tuple(live.shape), live.dtype,
                live.device.type, live.device.index,
            )
            grown = prepared_by_storage.get(storage_key)
            if grown is None:
                grown = live.detach()
                with torch.no_grad():
                    grown[:saved.shape[0]].copy_(saved.detach().to(
                        device=grown.device, dtype=grown.dtype))
                prepared_by_storage[storage_key] = grown
            elif not torch.equal(
                    grown[:saved.shape[0]], saved.detach().to(
                        device=grown.device, dtype=grown.dtype)):
                raise ValueError(
                    f"PartSpace checkpoint aliases disagree for {key}")
            state[key] = grown
            old_sizes.add(int(saved.shape[0]))
            expanded += 1
        if expanded:
            TheMessage(
                f"[{self.name}] Expanded PartSpace checkpoint rows "
                f"{sorted(old_sizes)} -> {capacity} across {expanded} "
                "state key(s); learned prefix copied in place and initialized "
                "tail preserved")
        return expanded

    @staticmethod
    def _optimizer_leaves(optimizer):
        """Yield concrete optimizer wrappers from a MultiOptimizer tree."""
        children = getattr(optimizer, "optimizers", None)
        if children is None:
            yield optimizer
            return
        for child in children:
            yield from BaseModel._optimizer_leaves(child)

    def _normalize_optimizer_state_shapes(self, optimizer):
        """Validate or pad loaded row-wise optimizer moments.

        ``Optimizer.load_state_dict`` intentionally maps state by parameter
        order and accepts shape-drifted moment tensors.  The failure otherwise
        appears only on the first Adam step.  Normalize immediately after load:
        preserve the learned prefix, zero every new row, and reject any shape
        change that is not a pure first-axis capacity extension. RowLocalAdam
        is the deliberate exception: its prefix-shaped moments stay compact
        and grow geometrically only when a later sparse gradient touches a new
        row. Expanding them here would recreate the multi-gigabyte state this
        optimizer exists to avoid.
        """
        padded = 0
        for leaf in self._optimizer_leaves(optimizer):
            state_by_param = getattr(leaf, "state", None)
            if state_by_param is None:
                continue
            row_local = bool(getattr(leaf, "row_local_state", False))
            for param, param_state in list(state_by_param.items()):
                if not isinstance(param, nn.Parameter):
                    continue
                target_shape = tuple(param.shape)
                for name, value in list(param_state.items()):
                    if not torch.is_tensor(value) or value.ndim == 0:
                        continue
                    if tuple(value.shape) == target_shape:
                        continue
                    # Adam's step can be a one-element tensor on some torch
                    # versions/backends; it is scalar state, not row state.
                    if str(name) == "step" and value.numel() == 1:
                        continue
                    if (value.ndim != param.ndim
                            or tuple(value.shape[1:]) != target_shape[1:]
                            or int(value.shape[0]) > int(target_shape[0])):
                        raise ValueError(
                            f"optimizer state {name!r} shape "
                            f"{tuple(value.shape)} cannot migrate to parameter "
                            f"shape {target_shape}; only first-axis growth is "
                            f"supported")
                    if row_local:
                        # Valid compact checkpoint state. The optimizer owns
                        # its next-power-of-two growth boundary.
                        continue
                    grown = value.new_zeros(target_shape)
                    grown[:value.shape[0]].copy_(value)
                    param_state[name] = grown
                    padded += 1
        if padded:
            TheMessage(
                f"[{self.name}] Zero-padded {padded} optimizer moment "
                f"tensor(s) for larger configured inventories")
        return padded

    def _checkpoint_path(self, suffix=None):
        """Resolve the configured checkpoint path, optionally adding a suffix.

        ``BASIC_WEIGHTS_PATH`` is an explicit run-local override. Relative
        override paths resolve from the project root (so ``output/foo.ckpt``
        is stable regardless of the XML's directory); XML paths retain their
        historical config-directory semantics when the override is unset.

        Falls back to ``output/<config-stem>.ckpt`` when no ``weightsPath``
        is set in the XML. Config-specific names prevent unrelated BasicModel
        architectures from silently sharing ``output/BasicModel.ckpt``.
        The ``suffix`` is inserted before the extension so emergency /
        autosave variants can coexist with the canonical checkpoint.
        """
        override = os.environ.get("BASIC_WEIGHTS_PATH", "").strip()
        if override:
            expanded = os.path.expanduser(override)
            path = (expanded if os.path.isabs(expanded)
                    else os.path.join(ProjectPaths.PROJECT_DIR, expanded))
            path = os.path.abspath(path)
        else:
            path = TheXMLConfig.get("architecture.weightsPath", None)
            if path:
                path = self._resolve_artifact_path(path)
            else:
                config_path = getattr(self, "_config_path", None)
                stem = (Path(config_path).stem if config_path
                        else str(self.name))
                path = ProjectPaths.output_path(f"{stem}.ckpt")
        if suffix:
            root, ext = os.path.splitext(path)
            path = f"{root}.{suffix}{ext or '.ckpt'}"
        return path

    def save_training_checkpoint(self, reason="checkpoint", suffix=None):
        """Save the model checkpoint (single integrated artifact).

        Resolves the .ckpt path (with optional suffix) and writes the
        full bundle via ``save_weights``: parameters, buffers,
        embeddings, and BPE state. ``reason`` appears in the log only;
        the on-disk filename is unaffected.
        """
        path = self._checkpoint_path(suffix=suffix)
        TheMessage(f"[{self.name}] Saving training checkpoint ({reason})")
        self.save_weights(path)
        return path

    def _maybe_save_periodic_checkpoint(self):
        interval = int(getattr(self, "checkpoint_every_batches", 0) or 0)
        if interval <= 0:
            return
        step = int(getattr(self, "_training_step_count", 0) or 0)
        if step > 0 and step % interval == 0:
            self.save_training_checkpoint(reason=f"batch {step}")

    def _assert_finite_train_state(self, what):
        """Fail at the update site when a parameter or gradient goes non-finite.

        Gated by MODEL_DEBUG (see util.py). The inner checks are ``assert``
        statements so ``python -O`` strips them entirely; MODEL_DEBUG also
        short-circuits the iteration so the per-parameter loop is skipped
        without -O.
        """
        if not _util.MODEL_DEBUG:
            return
        for name, param in self.named_parameters():
            if param is None:
                continue
            pdata = param.detach()
            assert torch.isfinite(pdata).all(), (
                f"Non-finite parameter {name!r} {what}: "
                f"{int((~torch.isfinite(pdata)).sum().item())}/{pdata.numel()} "
                f"entries are nan/inf."
            )
            if param.grad is not None:
                grad = param.grad.detach()
                # ``torch.isfinite`` has no SparseCPU/SparseMPS implementation
                # for a COO tensor. Sparse gradients are finite exactly when
                # their stored values are finite; absent entries are zeros.
                checked_grad = (
                    grad.coalesce().values() if grad.is_sparse else grad)
                assert torch.isfinite(checked_grad).all(), (
                    f"Non-finite gradient for {name!r} {what}: "
                    f"{int((~torch.isfinite(checked_grad)).sum().item())}/"
                    f"{checked_grad.numel()} "
                    f"entries are nan/inf."
                )

    def run(self, numTrials=1, numEpochs=1, batchSize=10, lr=0.001, profile=None):
        """Run multiple independent trials, recreating the model each time.

        Each trial calls create_from_config() to rebuild from scratch so
        results are statistically independent.  If the model was already
        configured by the caller (e.g. manually built models without
        _config_path), trial 0 skips recreation and uses the model as-is.
        """
        acc = np.zeros([numTrials, numEpochs])
        has_config = hasattr(self, '_config_path') and self._config_path is not None
        already_configured = len(list(self.parameters())) > 0
        TheMessage(f"\n\n==== {self.name} ====")
        for trial in range(numTrials):
            TheMessage(f"\nTrial [{trial + 1}/{numTrials}]")
            if has_config and (trial > 0 or not already_configured):
                self.create_from_config(self._config_path, data=self._config_data)
            acc[trial, :] = self.runTrial(
                numEpochs=numEpochs, batchSize=batchSize, lr=lr,
                profile=profile,
            )

        np.savetxt(ProjectPaths.output_path(f"{self.name}.csv"), np.array(acc), delimiter=",")
        return acc

    def paramUpdate(self):
        """Delegate ergodic in-place parameter updates to all spaces.

        Each space's ``paramUpdate`` performs its own annealing /
        renormalization step (e.g. codebook re-projection); not all
        parameter motion is gradient-driven.
        """
        for s in self.spaces:
            s.paramUpdate()
        # A4: each ConceptualCombine is registered in its ``cs.layers``, so the
        # space walk above already cascades ``paramUpdate()`` to it (the dense
        # full/last ergodic path anneals; the butterfly path is a no-op).

    def _advance_codebook_parameter_versions(self):
        """Publish one model-wide parameter epoch after a write barrier.

        Every Space receives the same epoch even when a particular codebook
        had no gradient in this step.  Conservative invalidation is cheap and
        guarantees that a pipeline execution can compare every selected
        carrier against one model-wide ``parameter_version``.
        """
        version = int(getattr(self, '_parameter_epoch', 0)) + 1
        self._parameter_epoch = version
        for space in self.spaces:
            # Compatibility/custom Spaces may still skip Space.__init__.
            # Normal Spaces and SymbolSpace initialize this metadata and
            # advance together at the write barrier.
            if '_codebook_parameter_version' not in vars(space):
                continue
            setter = getattr(space, 'set_codebook_parameter_version', None)
            if callable(setter):
                setter(version)
        return version

    def set_sigma(self, sigma):
        """Propagate exploration meta-parameters to all spaces.

        ``sigma`` controls per-space exploration noise (typically the
        Gaussian sample width in codebook lookup). Spaces that don't
        use exploration may treat this as a no-op.
        """
        for s in self.spaces:
            s.set_sigma(sigma)
        # A4: each ConceptualCombine is registered in its ``cs.layers``, so the
        # space walk above already cascades ``set_sigma()`` to it (no-op on the
        # butterfly path; the dense ergodic path uses it).

    def _get_embedding(self):
        """Return the Embedding instance if this model uses one, else None.

        Stage 7 (doc/plans/2026-05-27-perceptstore-meta-taxonomy-
        reentrancy.md): in radix-mode the ``vocabulary`` property
        returns a PerceptStore, but the orthographic Embedding still
        lives on ``perceptualSpace.subspace.what``; look there first
        so the rest of the orthographic API keeps working in radix mode.
        """
        if not hasattr(self, 'perceptualSpace'):
            return None
        _what = getattr(self.perceptualSpace.subspace, 'what', None)
        if isinstance(_what, Embedding):
            return _what
        _vocab = self.perceptualSpace.vocabulary
        if isinstance(_vocab, Embedding):
            return _vocab
        return None

    # -- Reasoning Methods --------------------------------------------

    def _get_truth_layer(self):
        """Return the TruthLayer if available, else None.

        The TruthLayer now lives on ``SymbolSpace``; when the grammar
        path that builds SymbolSpace is disabled there is no layer.
        """
        return self.symbolSpace.truth_layer if self.symbolSpace is not None else None

    def _get_basis(self):
        """Return the WholeSpace property Basis, if available."""
        ws = getattr(self, 'wholeSpace', None)
        if ws is None:
            return None
        return getattr(getattr(ws, 'subspace', None), 'basis', None)

    @torch.no_grad()
    def _clamp_symbolic_codebook(self):
        """Keep the WholeSpace property codebook inside the [0,1] pair box.

        The compatibility method name is retained for external callers.
        Called after ``optimizer.step()`` when the property basis is monotonic;
        gradient updates can push entries outside the box, so clamp directly
        on the Parameter data before the next forward pass.
        """
        basis = self._get_basis()
        if basis is None or not getattr(basis, 'monotonic', False):
            return
        W = getattr(basis, 'W', None)
        if W is None or not isinstance(W, torch.Tensor):
            return
        W.data.clamp_(0.0, 1.0)





    @torch.no_grad()
    def isConsistent(self):
        """Analyze the TruthSet for internal consistency.

        Folds stored signed truth observations with the catalogue's mean.
        Opposite observations cancel in this diagnostic; the probabilistic
        disjunction is a composition operator, not a cancellation statistic.

        Returns:
            dict with keys: consistent (bool), score (float),
            sites (tensor of dim indices below threshold),
            union_vector (tensor).
        """
        # Phase 1 (bivector retirement): the disjunction fold lives on
        # TruthLayer; this is a thin delegator. The basis presence guard
        # stays here (a model-side concept).
        truth_layer = self._get_truth_layer()
        basis = self._get_basis()
        if truth_layer is None or basis is None:
            return {'consistent': True, 'score': 1.0,
                    'sites': torch.tensor([]), 'union_vector': torch.tensor([])}
        return truth_layer.isConsistent()

    @torch.no_grad()
    def ground(self, activation, threshold=0.6):
        """Find the minimal TruthSet subset that entails the query.

        Uses _activation_order() to filter truths by compatible partition
        when partitions are available.

        Returns:
            dict with keys: grounded (bool), basis (list of indices),
            trace (list), confidence (float in [-1, 1]).
        """
        # Phase 1 (bivector retirement): the entailment search is
        # consolidated onto TruthLayer; this is a thin delegator.
        truth_layer = self._get_truth_layer()
        if truth_layer is None:
            return {'grounded': False, 'basis': [], 'trace': [], 'confidence': 0.0}
        return truth_layer.ground(activation, threshold=threshold, model=self)

    @torch.no_grad()
    def isTrue(self, activation):
        """Ground a proposition and return a scalar DoT in [-1, 1].

        Positive = true, negative = false, zero = unknown.
        """
        result = self.ground(activation)
        return 0.0 if not result['grounded'] else result['confidence']

    @torch.no_grad()
    def extrapolate(self, seed_indices=None, max_new=64, attenuation=0.8):
        """Generalize TruthLayer.derive() to all two-argument grammar methods.

        For each pair of stored truths, apply every eligible two-argument
        grammar method. Accept results that preserve or increase luminosity;
        reject those that decrease it.

        Args:
            seed_indices: optional list of truth indices to use as seeds.
            max_new: maximum number of new truths to derive.
            attenuation: DoT scaling for derived truths.

        Returns:
            dict with 'added' (list of new indices) and
            'rejected' (list of (i, j, rule, delta_lum) tuples).
        """
        # Phase 1 (bivector retirement): pairwise grammar extrapolation
        # is consolidated onto TruthLayer; this is a thin delegator.
        truth_layer = self._get_truth_layer()
        if truth_layer is None:
            return {'added': [], 'rejected': []}
        return truth_layer.extrapolate(
            model=self, seed_indices=seed_indices,
            max_new=max_new, attenuation=attenuation)

    # -- Contemplative Awareness Characterizations ---------------------

    # -- Contemplative Awareness Characterizations ---------------------
    # The measure family (Contiguous / Continuous / Peaceful / Area /
    # Luminosity) and its hoc_shape back-projection machinery have been
    # extracted to bin/Mereology.py.  BaseModel inherits from Mereology
    # (mixin order: Mereology before nn.Module) so the methods remain
    # callable as model.Contiguous() / etc.


    def Done(self):
        """Buddhahood (Non-Meditation / Resonance).

        The perfection of Contiguous, Continuous, and Peaceful: the
        elimination of dissonance.

        Characterisation -- non-meditation / resonance:
          * Dissonance manifests as something to learn -- a non-zero
            gradient signal indicating mismatch between model and world.
          * It is *not* the case that knowing everything is required to
            remove dissonance, because the attempt to know often creates
            dissonance (reification, attachment to views).
          * Done() holds when the error function is relatively small in
            all cases: no region of input space produces a large loss
            spike.  The model has nothing more to learn -- not because it
            knows everything, but because it is at peace with what it
            does not know.

        Computationally, Done() should verify that:
          1. Contiguous() holds (one-pointed awareness),
          2. Continuous() holds (smooth awareness),
          3. Peaceful() holds (balanced feelings),
          4. The max loss across a representative sample is below a
             configured resonance threshold.
        """
        raise NotImplementedError

    def save_weights(self, path=None):
        """Persist all model state to a single .ckpt: parameters, buffers,
        embedding vectors, vocabulary mappings, BPE codebook, optimizer,
        RNG state, counters, corpus manifest, and mid-epoch cursor.

        The integrated-weights architecture: one XML config + one
        checkpoint, no separate .kv embedding artifact. The checkpoint
        carries:

        * ``state_dict``: all nn.Parameter + register_buffer state
          (model weights, embeddings, TruthLayer rows, etc.).
        * ``vocab_extras``: Python-side WordVectors mappings that don't
          fit ``state_dict`` (``index_to_key``, ``counts``, ``total_count``).
        * ``bpe_extras``: ChunkLayer merge table and vocabulary (pure
          Python state — merges list, vocab dict, id_to_bytes mapping,
          counters).
        * ``structural_extras``: the non-Module concept allocator and its
          identity/idempotency registries. Without this sidecar a resumed
          model would re-mint word wholes and concepts even though their
          tensor rows survived.
        """
        if path is None:
            path = os.path.join(ProjectPaths.OUTPUT_DIR, "weights.ckpt")
        os.makedirs(os.path.dirname(path), exist_ok=True)
        optimizer = getattr(self, "_optimizer", None)
        optimizer_manifest = (
            build_optimizer_param_manifest(
                optimizer, self.named_parameters())
            if optimizer is not None else None)
        bundle = {
            "state_dict": dict(self.state_dict()),
            "vocab_extras": self._collect_vocab_extras(),
            "structural_extras": self._collect_structural_extras(),
            "optimizer_state": (
                optimizer.state_dict() if optimizer is not None else None),
            "training_state": {
                "training_step_count": int(getattr(
                    self, "_training_step_count", 0) or 0),
                "fineweb_training_progress": copy.deepcopy(getattr(
                    self, "_fineweb_training_progress", None)),
                "word_observation_serial": int(getattr(self, "_word_observation_serial", 0)),
                "train_batches_seen": int(getattr(
                    self, "_train_batches_seen", 0) or 0),
                "epoch_batches_seen": int(getattr(
                    self, "_epoch_batches_seen", 0) or 0),
                "checkpoint_batch_size": getattr(
                    self, "_checkpoint_batch_size", None),
                "torch_rng_state": torch.get_rng_state(),
                "python_rng_state": random.getstate(),
                "numpy_rng_state": np.random.get_state(),
                "cuda_rng_state_all": (
                    torch.cuda.get_rng_state_all()
                    if torch.cuda.is_available() else None),
                "mps_rng_state": _mps_rng_state_or_none(),
                "data_manifest": getattr(
                    getattr(self, "inputSpace", None), "data", None
                ).source_manifest if getattr(
                    getattr(self, "inputSpace", None), "data", None
                ) is not None else None,
            },
        }
        bundle = stamp_checkpoint_schema(
            bundle, optimizer_param_names=optimizer_manifest)
        util.atomic_torch_save(bundle, path)
        TheMessage(f"[{self.name}] Weights saved to {path}")

    def _collect_vocab_extras(self):
        """Gather lexicon mappings and non-tensor space structure.

        Returns ``None`` only when neither lexicon nor structural/property
        metadata is present.

        In canonical property-basis models, ConceptualSpace owns taxonomy,
        META, and concept identity under ``conceptual_structure``. WholeSpace
        contributes only property tags/provenance under ``whole_properties``.
        Legacy configs retain the old WS envelope until explicitly migrated.
        """
        emb = self._get_embedding()
        whole_space = getattr(self, 'wholeSpace', None)
        concept_space = getattr(self, 'conceptualSpace', None)
        conceptual_extras = (
            concept_space.vocab_extras() if concept_space is not None and hasattr(concept_space, 'vocab_extras') else None)
        whole_extras = whole_space.property_extras() if whole_space is not None else None
        # Canonical abstraction-order provenance for the PS percept
        # codebook (the WS tables ride inside ws_extras). None when there
        # is nothing stamped, so pre-feature blobs stay byte-identical.
        ps_cb = getattr(getattr(getattr(self, 'perceptualSpace', None),
                                'subspace', None), 'what', None)
        ps_rams = (ps_cb.ramsification_extras()
                   if ps_cb is not None
                   and hasattr(ps_cb, 'ramsification_extras') else None)
        # The PS percept store's pure-Python state (trie + inverse table +
        # hash map + fallback hits — the WORD surfaces). Emitted ONLY when a
        # store exists and holds entries, so pre-feature / storeless blobs
        # stay byte-identical (2026-07-13 open-fronts plan, Task A).
        ps_store = getattr(getattr(self, 'perceptualSpace', None),
                           'percept_store', None)
        ps_pstore = (ps_store.vocab_extras()
                     if ps_store is not None
                     and hasattr(ps_store, 'vocab_extras')
                     and len(ps_store) > 0 else None)
        if emb is None or getattr(emb, 'wv', None) is None:
            if (conceptual_extras is None and whole_extras is None
                    and ps_rams is None and ps_pstore is None):
                return None
            # Lexicon-less radix mode: only structural/PS state needs to
            # travel; we still wrap it in the standard envelope so
            # ``_restore_vocab_extras`` finds the keys.
            blob = {
                "index_to_key": [],
                "counts": [],
                "total_count": 0,
            }
            if conceptual_extras is not None:
                blob["conceptual_structure"] = conceptual_extras
            if whole_extras is not None:
                blob["whole_properties"] = whole_extras
            if ps_rams is not None:
                blob["ps_ramsification"] = ps_rams
            if ps_pstore is not None:
                blob["ps_percept_extras"] = ps_pstore
            return blob
        wv = emb.wv
        counts = getattr(wv, 'counts', None)
        if counts is not None and hasattr(counts, 'tolist'):
            counts = counts.tolist()
        blob = {
            "index_to_key": list(getattr(wv, 'index_to_key', []) or []),
            "counts": counts or [],
            "total_count": int(getattr(wv, 'total_count', 0) or 0),
            "physical_capacity": int(emb.lexicon_capacity),
        }
        if conceptual_extras is not None:
            blob["conceptual_structure"] = conceptual_extras
        if whole_extras is not None:
            blob["whole_properties"] = whole_extras
        if ps_rams is not None:
            blob["ps_ramsification"] = ps_rams
        if ps_pstore is not None:
            blob["ps_percept_extras"] = ps_pstore
        return blob


    def _collect_structural_extras(self):
        """Snapshot durable host-side concept, mereology and fact metadata.

        ``ConceptAllocator`` deliberately is not an ``nn.Module``: its ids,
        ordered constituent records, row maps and idempotency dictionaries are
        symbolic structure rather than tensor geometry.  The same is true of
        the word-keyed WholeSpace registries.  They nevertheless form part of
        the learned model; dropping them on reload makes the next observation
        mint duplicate identities.  Keep them in one versioned sidecar.
        Truth-store scope, bindings, references and source text are versioned
        beside that structure; their vectors remain in registered buffers.
        """
        alloc_fields = (
            "placement", "raised", "singletons", "retired", "identity",
            "relate_idx", "word_forms", "reference_orders", "testimony_seen",
            "testimony_current",
        )
        cs_fields = (
            "_autobound_percept_ids", "_recognized_words",
            "_words_concept_id", "_priming_bridge", "_frozen_concepts",
            "_frozen_named",
            "_concept_admission_drops",
            # Fold-ladder plan (contracts 4, 6, 7): utility counts, phrase
            # hits / admissions / rows / gains ride the checkpoint.
            "_cu", "_chunk_hits", "_chunk_admitted", "_chunk_rows",
            "_chunk_utility_gain",
        )
        legacy_ws_fields = ("_standalone_run_bytes",)
        # Schema-2 WholeSpace sidecars contain perceptual analysis state only.
        # LBG accumulators belong to the retired WS concept/META dictionary and
        # must not be serialized beside the fixed property basis.
        property_ws_fields = ("_standalone_run_bytes", "_property_rows_used")

        conceptual = {}
        for i, cs in enumerate(list(
                getattr(self, "conceptualSpaces", None) or ())):
            entry = {}
            alloc = getattr(cs, "_concept_allocator", None)
            if alloc is not None:
                a = {"next_id": int(getattr(alloc, "next_id", 1))}
                for name in alloc_fields:
                    a[name] = _checkpoint_host_copy(getattr(alloc, name))
                layers = {}
                for order, layer in getattr(alloc, "_layers", {}).items():
                    values = getattr(layer, "values", None)
                    layers[int(order)] = {
                        "nInput": int(layer.nInput),
                        "nOutput": int(layer.nOutput),
                        "constituents": _checkpoint_host_copy(
                            getattr(layer, "_constituents", {})),
                        "tensor_rows": _checkpoint_host_copy(
                            getattr(layer, "_tensor_rows", {})),
                        "row_next": _checkpoint_host_copy(
                            getattr(layer, "_row_next", {})),
                        "rows": [int(v) for v in getattr(layer, "_rows", ())],
                        "cols": [int(v) for v in getattr(layer, "_cols", ())],
                        "init_vals": [
                            float(v) for v in getattr(layer, "_init_vals", ())
                        ],
                        "values": (
                            None if values is None
                            else _checkpoint_host_copy(values)),
                        "values_requires_grad": bool(
                            values is not None and values.requires_grad),
                        "parts": layer.parts_extras(),
                    }
                a["layers"] = layers
                entry["allocator"] = a
            attrs = {
                name: _checkpoint_host_copy(getattr(cs, name))
                for name in cs_fields
                if hasattr(cs, name) and getattr(cs, name) is not None
            }
            if attrs:
                entry["attributes"] = attrs
            interpretation = cs.__dict__.get('_interpret_operator')
            if interpretation is not None and interpretation._pending:
                entry['pending_definitions'] = {
                    'words': _checkpoint_host_copy(interpretation._pending),
                    'field': sorted(interpretation._field_pending),
                }
            carrier = getattr(cs, 'subspace', None)
            evidence = getattr(carrier, '_concept_activations', None)
            if torch.is_tensor(evidence):
                if evidence.ndim != 4 or evidence.shape[-1] != 2:
                    raise ValueError('checkpoint knowing requires paired evidence')
                entry['knowing'] = {
                    'evidence': _checkpoint_host_copy(evidence),
                    'thought_occurrence': getattr(carrier, '_thought_occurrence', None),
                    'code_owner': int(getattr(carrier, '_concept_code_owner', i)),
                }
                for name in ('where', 'when', 'ids', 'inventory_rows'):
                    value = getattr(carrier, '_concept_' + name, None)
                    if torch.is_tensor(value):
                        entry['knowing'][name] = _checkpoint_host_copy(value)
            # Perception belongs to the native reader, which can differ from
            # the terminal stage carrying the conceptual knowing.
            perception = getattr(cs, '_percept_field', None)
            if perception is not None:
                entry['perception'] = {name: _checkpoint_host_copy(getattr(perception, name))
                                       for name in perception.__dataclass_fields__}
            if (cs is getattr(self, 'conceptualSpace', None) and hasattr(cs, 'vocab_extras')):
                snapshot = cs.vocab_extras()
                if snapshot is not None:
                    entry["conceptual_structure"] = (
                        _checkpoint_host_copy(snapshot))
            if entry:
                conceptual[int(i)] = entry

        wholes = {}
        for i, ws in enumerate(list(
                getattr(self, "wholeSpaces", None) or ())):
            entry = {}
            if hasattr(ws, 'property_extras'):
                vocab_snapshot = ws.property_extras()
            elif hasattr(ws, "vocab_extras"):
                vocab_snapshot = ws.vocab_extras()
                vocab_snapshot = {
                    key: value for key, value in
                    (vocab_snapshot or {}).items()
                    if (str(key).startswith(("property", "type_"))
                        or str(key) == "ramsification")
                }
            else:
                vocab_snapshot = None
            if vocab_snapshot is not None:
                # In schema 2 this is property metadata/provenance only.
                # Legacy configs retain their broad per-stage WS snapshot.
                entry["vocab_extras"] = _checkpoint_host_copy(vocab_snapshot)
            attrs = {
                name: _checkpoint_host_copy(getattr(ws, name))
                for name in (property_ws_fields)
                if hasattr(ws, name) and getattr(ws, name) is not None
            }
            if attrs:
                entry["attributes"] = attrs
            if entry:
                wholes[int(i)] = entry

        truth_semantics = {
            name: module.semantic_extras()
            for name, module in self.named_modules()
            if isinstance(module, TernaryTruthStore)
        }
        memory = getattr(getattr(self, "symbolSpace", None), "what_memory", None)
        what_history = (memory.thought_extras() if memory is not None
                        and any(memory._what_slots) else None)
        if not conceptual and not wholes and not truth_semantics and what_history is None:
            return None
        return {
            "version": 2,
            "conceptual_spaces": conceptual,
            "whole_properties": wholes,
            "truth_semantics": truth_semantics,
            "what_history": what_history,
        }

    def _restore_allocator_extras(self, cs, saved):
        """Restore one ConceptAllocator without replacing its live aliases."""
        alloc = getattr(cs, "_concept_allocator", None)
        if alloc is None:
            ensure = getattr(cs, "_concept_tables", None)
            if callable(ensure):
                ensure()
            alloc = getattr(cs, "_concept_allocator", None)
        if alloc is None:
            raise ValueError(
                "checkpoint contains ConceptAllocator state, but the live "
                "ConceptualSpace cannot materialize an allocator")

        fields = (
            "placement", "raised", "singletons", "retired", "identity",
            "relate_idx", "word_forms", "reference_orders", "testimony_seen",
            "testimony_current",
        )
        for name in fields:
            if name not in saved:
                continue
            incoming = _checkpoint_host_copy(saved[name])
            current = getattr(alloc, name, None)
            # Preserve dict/set identities because ConceptualSpace exposes
            # aliases to native constituent records.
            if isinstance(current, dict) and isinstance(incoming, dict):
                current.clear()
                current.update(incoming)
            elif isinstance(current, set) and isinstance(incoming, set):
                current.clear()
                current.update(incoming)
            else:
                setattr(alloc, name, incoming)

        next_id = int(saved.get("next_id", 1) or 1)
        known_ids = {0}
        for name in ("placement", "raised", "singletons", "retired",
                     "identity"):
            value = getattr(alloc, name, {})
            known_ids.update(int(v) for v in (
                value.keys() if isinstance(value, dict) else value))
        # A stale counter must never collide with a restored concept. Exact
        # checkpoints already satisfy this; max() is a corruption-safe guard.
        alloc.next_id = max(next_id, max(known_ids) + 1)

        layer_blobs = saved.get("layers") or {}
        if len(layer_blobs) > 1:
            raise ValueError(
                "checkpoint has multiple ConceptAllocator layers; the live "
                "single-store allocator supports exactly one")
        for raw_order, blob in layer_blobs.items():
            order = int(raw_order)
            layer = alloc.layer(order)
            saved_n_input = int(blob.get("nInput", layer.nInput))
            saved_n_output = int(blob.get("nOutput", layer.nOutput))
            if (layer.nOutput < saved_n_output <= int(getattr(cs, 'nVectors', layer.nOutput))
                    and getattr(cs, '_sparse_active', lambda: False)()):
                layer.grow_inventory(saved_n_output)
            live_n_input = int(layer.nInput)
            live_n_output = int(layer.nOutput)
            old_columns = saved_n_input == saved_n_output + 1
            paired_columns = saved_n_input == 2 * (saved_n_output + 1)
            shape_mismatch = saved_n_output != live_n_output
            square_expansion = bool(
                shape_mismatch and self._aligned_inventory_capacity() is not None
                and (old_columns or paired_columns)
                and live_n_input == 2 * (live_n_output + 1)
                and saved_n_output < live_n_output)
            if (shape_mismatch and not square_expansion) or (
                    not old_columns and saved_n_input != live_n_input and not square_expansion):
                raise ValueError('ConceptAllocator store shape mismatch')
            rows = [int(v) for v in blob.get('rows', ())]
            cols = [int(v) for v in blob.get('cols', ())]
            if square_expansion:
                bases = [int(base) for base in (blob.get('row_next') or {}) if int(base) != 0]
                if bases:
                    raise ValueError('ConceptAllocator capacity expansion is unsafe for a partitioned row map')
            values = blob.get('values')
            if values is not None and int(values.numel()) != len(rows):
                raise ValueError('ConceptAllocator sparse values/indices length mismatch')
            if old_columns or square_expansion:
                remapped = []
                for i, col in enumerate(cols):
                    source = col if old_columns else col % (saved_n_output + 1)
                    negative = (values is not None and float(values[i]) < 0) if old_columns else col > saved_n_output
                    source = live_n_output if source == saved_n_output else source
                    remapped.append(source + (live_n_output + 1 if negative else 0))
                cols = remapped
                if old_columns and values is not None:
                    layer._checkpoint_exponent_signs = torch.where(values < 0, -1., 1.)
                    values = values.abs()
            if len(rows) != len(cols) or len(set(zip(rows, cols))) != len(rows):
                raise ValueError(
                    "ConceptAllocator sparse COO checkpoint is malformed")
            if any(r < 0 or r >= int(layer.nOutput) for r in rows) or any(
                    c < 0 or c >= int(layer.nInput) for c in cols):
                raise ValueError(
                    "ConceptAllocator sparse COO checkpoint is out of bounds")
            if values is not None and int(values.numel()) != len(rows):
                raise ValueError(
                    "ConceptAllocator sparse values/indices length mismatch")
            init_vals = [abs(float(v)) for v in blob.get("init_vals", ())]
            if len(init_vals) != len(rows):
                if values is None:
                    raise ValueError(
                        "ConceptAllocator sparse initial-values length mismatch")
                init_vals = [float(v) for v in values.reshape(-1).tolist()]

            layer._constituents = _checkpoint_host_copy(
                blob.get("constituents") or {})
            layer._record_revision = getattr(layer, '_record_revision', 0) + 1
            layer._tensor_rows = _checkpoint_host_copy(
                blob.get("tensor_rows") or {})
            layer._tensor_row_keys = {row: key for key, row in layer._tensor_rows.items()}
            layer._row_next = _checkpoint_host_copy(blob.get("row_next") or {})
            layer._rows = rows
            layer._cols = cols
            layer._init_vals = init_vals
            layer._index = {
                (r, c): i for i, (r, c) in enumerate(zip(rows, cols))
            }
            layer._dev_cache = None
            layer._edge_ids = list(range(len(rows)))
            layer._next_edge_id = len(rows)
            layer._parameter_edge_ids = tuple(layer._edge_ids)
            if values is None:
                layer.values = None
            else:
                target = getattr(layer, "_target_device", None)
                if target is None:
                    target = next(
                        (p.device for p in cs.parameters()), torch.device("cpu"))
                layer.values = nn.Parameter(
                    values.detach().to(target).clone(),
                    requires_grad=bool(blob.get("values_requires_grad", True)),
                )

            layer.load_parts_extras(blob.get("parts"),
                                    old_size=saved_n_output if square_expansion else None)
            if getattr(cs, '_sparse_active', lambda: False)() and any(
                    not cs._order0_inventory_row(r)
                    or not cs._order0_inventory_row(c % (layer.nOutput + 1))
                    for r, c in layer.conjunctive._index):
                raise ValueError('checkpoint pi edges require order-0 field concepts')

        # Migration is deferred until the common store's semantic rows load.
        if saved.get('word_obj_meta') or saved.get('interpretations'):
            object.__setattr__(cs, '_legacy_definition_bindings', saved)
        register = getattr(cs, "_sparse_families", None)
        if callable(register) and layer_blobs:
            register(0)
        object.__setattr__(
            cs, "_csw_registered_count",
            sum(int(m.nnz) for layer in alloc._layers.values() for m in layer.definition_matrices()))

    def _restore_structural_extras(
            self, extras, *, legacy_whole_structure=None):
        """Inverse of :meth:`_collect_structural_extras` (old-safe)."""
        if not isinstance(extras, dict):
            return
        version = int(extras.get("version", 0) or 0)
        if version not in (1, 2):
            raise ValueError(
                f"unsupported structural checkpoint version {version}")

        conceptual_spaces = list(
            getattr(self, "conceptualSpaces", None) or ())
        entries = []
        for raw_i, entry in (extras.get("conceptual_spaces") or {}).items():
            i = int(raw_i)
            if not 0 <= i < len(conceptual_spaces):
                raise ValueError(
                    f"checkpoint ConceptualSpace index {i} is not present")
            entries.append((conceptual_spaces[i], entry))
        # Knowing in one space can name the terminal space's inventory.
        # Restore all identity and row owners before rebuilding any reader.
        for cs, entry in entries:
            alloc_blob = entry.get("allocator")
            if isinstance(alloc_blob, dict):
                self._restore_allocator_extras(cs, alloc_blob)
        for cs, entry in entries:
            pending = entry.get('pending_definitions') or {}
            if pending or hasattr(cs, 'interpret'):
                cs.interpret._pending = _checkpoint_host_copy(pending.get('words', {}))
                cs.interpret._field_pending = set(pending.get('field', ()))
            for name, value in (entry.get("attributes") or {}).items():
                if name in ('_percept_word_concept', '_object_word_concept', '_word_obj_meta'):
                    continue  # replaced by the index over migrated DEF rows
                if name == "_promotion_cache_state":
                    raise ValueError("host promotion candidates require an explicit row-pool migration")
                object.__setattr__(cs, str(name), _checkpoint_host_copy(value))
            knowing = entry.get('knowing')
            if knowing is not None:
                evidence = knowing['evidence']
                if evidence.ndim != 4 or evidence.shape[-1] != 2:
                    raise ValueError('checkpoint knowing requires paired evidence')
                owner = int(knowing['code_owner'])
                if not 0 <= owner < len(conceptual_spaces):
                    raise ValueError('checkpoint knowing code owner is absent')
                codes = conceptual_spaces[owner].similarity_codebook.getW()
                if len(evidence) > len(codes):
                    raise ValueError('checkpoint knowing exceeds concept inventory')
                carrier = cs.subspace
                object.__setattr__(carrier, '_concept_activations', evidence.to(codes).clone())
                # Identity is retained with the evidence, never recovered from
                # this turn's attended slot. Older receipts migrate once here.
                ids = knowing.get('ids')
                rows = knowing.get('inventory_rows')
                owner_space = conceptual_spaces[owner]
                if ids is not None:
                    layer = owner_space._concept_allocator.layer(0)
                    addresses = []
                    for cid in ids.flatten().tolist():
                        address = owner_space._csw_row_of(cid) if cid >= 0 else layer.row_of(('provisional', cid))
                        addresses.append(-1 if address is None else address)
                    rows = torch.tensor(addresses, device=codes.device, dtype=torch.long).reshape(ids.shape)
                elif rows is None:
                    rows = torch.arange(len(evidence), device=codes.device)
                    ids = torch.tensor([owner_space.concept_id_at_row(int(r)) or -1 for r in rows], device=codes.device)
                object.__setattr__(carrier, '_concept_codes', owner_space._field_codes(codes, rows).detach())
                object.__setattr__(carrier, '_concept_ids', ids.to(codes.device).clone())
                object.__setattr__(carrier, '_concept_inventory_rows', rows.to(codes.device).clone())
                object.__setattr__(carrier, '_concept_code_owner', owner)
                object.__setattr__(carrier, '_thought_occurrence', knowing['thought_occurrence'])
                for name in ('where', 'when'):
                    value = knowing.get(name)
                    if torch.is_tensor(value):
                        object.__setattr__(carrier, '_concept_' + name,
                                           value.to(device=codes.device).clone())
            if entry.get('perception') is not None:
                from PerceptField import PerceptField
                device = cs.similarity_codebook.getW().device
                values = {name: value.to(device) if torch.is_tensor(value) else value
                          for name, value in entry['perception'].items()}
                object.__setattr__(cs, '_percept_field', PerceptField(**values))
            conceptual_blob = entry.get("conceptual_structure")
            if (isinstance(conceptual_blob, dict)
                    and hasattr(cs, "load_vocab_extras")):
                cs.load_vocab_extras(conceptual_blob)
            refresh = getattr(cs, "_refresh_frozen_values_hook", None)
            if callable(refresh):
                refresh()

        whole_spaces = list(getattr(self, "wholeSpaces", None) or ())
        whole_entries = extras.get("whole_properties") or {}
        for raw_i, entry in whole_entries.items():
            i = int(raw_i)
            if not 0 <= i < len(whole_spaces):
                raise ValueError(
                    f"checkpoint WholeSpace index {i} is not present")
            ws = whole_spaces[i]
            ws_vocab = entry.get("vocab_extras")
            if isinstance(ws_vocab, dict):
                ws.load_property_extras(ws_vocab)
            cb = getattr(getattr(ws, "subspace", None), "what", None)
            W = cb.getW() if cb is not None and hasattr(cb, "getW") else None
            for name, value in (entry.get("attributes") or {}).items():
                if str(name) not in ("_standalone_run_bytes", "_row_bytes", "_property_rows_used"):
                    continue
                restored = _checkpoint_host_copy(value)
                if str(name) == '_row_bytes':
                    # Old acquired predicates become primitive teaching
                    # examples; their host dictionary is never reinstated.
                    primitive = cb.primitive_properties
                    for row, byte_values in (restored or {}).items():
                        targets = primitive.members.new_zeros(256)
                        targets[[int(b) for b in byte_values]] = 1.
                        primitive.teach(int(row), torch.arange(256), targets)
                    object.__setattr__(ws, "_predicate_byte_lut", None)
                    continue
                elif str(name) == "_property_rows_used":
                    restored = set(int(r) for r in restored)
                pass
                object.__setattr__(ws, str(name), restored)

        if extras.get('whole_spaces') or legacy_whole_structure:
            warnings.warn('Dropping retired WholeSpace word and META structure (§11.4).', UserWarning)

        modules = dict(self.named_modules())
        for name, saved in (extras.get("truth_semantics") or {}).items():
            store = modules.get(name)
            if not isinstance(store, TernaryTruthStore):
                raise ValueError(f"checkpoint truth store {name!r} is not present")
            store.load_semantic_extras(saved)

        from Definitions import migrate_meta_definitions
        for cs in conceptual_spaces:
            legacy = cs.__dict__.pop('_legacy_definition_bindings', None)
            if legacy is not None:
                migrate_meta_definitions(cs, legacy)

        what_history = extras.get("what_history")
        if what_history is not None:
            memory = getattr(getattr(self, "symbolSpace", None), "what_memory", None)
            if memory is None:
                raise ValueError("checkpoint thought history has no interaction memory owner")
            for module in modules.values():
                if isinstance(module, TernaryTruthStore):
                    what_history = module.remap_legacy_references(what_history)
            memory.load_thought_extras(what_history)

        # The state_dict post-hook can only withdraw request authority: this is
        # the first point at which both semantic rows and ordinary thought
        # roots have been restored, so physical stateless pruning is safe.
        finish = getattr(
            getattr(self, "symbolSpace", None), "_finish_ltm_restore", None)
        if callable(finish):
            finish()

    @staticmethod
    def _widen_what_projection_checkpoint_state(state, model_state):
        """Zero-pad a narrower saved ``what_projection.weight`` to the live
        ``WHAT_CONTEXT_DIM``. Only the context (last) axis may grow; any
        other difference is left for the shape-mismatch audit."""
        widened = 0
        for key in list(state.keys()):
            if not key.endswith("what_projection.weight"):
                continue
            live = model_state.get(key)
            saved = state[key]
            if (live is None or not torch.is_tensor(saved)
                    or saved.dim() != 2 or live.dim() != 2
                    or saved.shape[0] != live.shape[0]
                    or saved.shape[1] >= live.shape[1]):
                continue
            padded = torch.zeros(
                live.shape, dtype=saved.dtype, device=saved.device)
            padded[:, :saved.shape[1]] = saved
            state[key] = padded
            widened += 1
        return widened

    def load_weights(self, path=None, strict=False, require_match=False):
        """Load model state from a single .ckpt bundle.

        The new bundle format carries ``state_dict`` plus
        ``vocab_extras`` (WordVectors mappings) and ``bpe_extras``
        (ChunkLayer merges/vocab) — see ``save_weights``. Old
        embedding-stripped .ckpts (state_dict only, no extras) load
        with a warning; the embeddings stay at their construction-time
        random init.

        ``require_match`` (autoload only): when True, a genuine
        architecture mismatch (shape drift / missing keys / fatal
        unexpected keys) raises ``ValueError`` with the actionable
        diagnostic instead of soft-warning and proceeding on fresh
        weights -> later crash. This is the migration-cliff catcher:
        the bivector retirement invalidates pre-refactor checkpoints
        (e.g. data/MM_5M_bivector.ckpt), so autoloading a stale ckpt
        now fails fast. Non-autoload callers keep ``require_match=False``
        (soft-warn) so vocab-grow / benign-stale-key loads still work.
        """
        if path is None:
            path = os.path.join(ProjectPaths.OUTPUT_DIR, "weights.ckpt")
        if not os.path.exists(path):
            TheMessage(f"[{self.name}] No checkpoint at {path}, starting fresh")
            return False
        # Always inspect/migrate on CPU before any tensor reaches the live
        # accelerator. In particular, a schema-1 checkpoint can contain GiB-
        # scale retired WS concept/analysis tables; mapping it to MPS first
        # would defeat the reset migration's peak-memory guarantee. mmap keeps
        # those soon-to-be-discarded storages file-backed while filtering.
        try:
            saved = torch.load(
                path, map_location="cpu", weights_only=False, mmap=True)
        except (TypeError, RuntimeError) as exc:
            # Older torch lacks the keyword; legacy non-zip serialization can
            # expose it but reject mmap. Do not mask unrelated corruption.
            detail = str(exc).lower()
            if not any(token in detail for token in (
                    "mmap", "memory map", "zip", "keyword")):
                raise
            saved = torch.load(
                path, map_location="cpu", weights_only=False)
        migration = migrate_wholespace_checkpoint(
            saved, dict(self.state_dict()))
        saved = migration.checkpoint
        for message in migration.diagnostics.messages():
            TheMessage(f"[{self.name}] {message}")
        legacy_state_shapes = migration.legacy_state_shapes
        reset_wholespace_optimizer = bool(migration.migrated)

        if isinstance(saved, dict) and "state_dict" in saved:
            state = saved["state_dict"]
            vocab_extras = saved.get("vocab_extras")
            structural_extras = saved.get("structural_extras")
            optimizer_state = saved.get("optimizer_state")
            optimizer_manifest = saved.get(OPTIMIZER_PARAM_NAMES_KEY)
            legacy_whole_structure = saved.get(LEGACY_WHOLE_STRUCTURE_KEY)
            training_state = saved.get("training_state") or {}
        else:
            state = saved
            vocab_extras = None
            structural_extras = None
            optimizer_state = None
            optimizer_manifest = None
            legacy_whole_structure = None
            training_state = {}

        if vocab_extras is None and any("wv._vectors" in k for k in state):
            # Bundled with embeddings but no vocab_extras — unusual
            # but tolerated; the wv._vectors will load through state_dict.
            pass
        elif vocab_extras is None:
            TheMessage(
                f"[{self.name}] Legacy checkpoint at {path} has no "
                f"embedding bundle; embeddings stay at random init.")

        # Restore logical lexicon occupancy before the state_dict shape check. Otherwise the wv._vectors row count
        # mismatch (live model is freshly built with a smaller vocab;
        # saved bundle carries the grown vocab) would fail the load.
        if vocab_extras is not None or legacy_whole_structure is not None:
            self._restore_vocab_extras(
                vocab_extras or {},
                legacy_whole_structure=legacy_whole_structure)

        # Answer-path modules (What spec Steps 3-4, 7) are built lazily; a
        # checkpoint that carries them must find them on the fresh model
        # before the audit below classifies their keys as unexpected.
        # (``BaseModel`` stubs without the answer path skip this.)
        _materialize = getattr(self, "_materialize_answer_path_from_checkpoint", None)
        if _materialize is not None:
            # A trained word-walk model may never need the optional synthesis
            # layers. Restore only saved modules, preserving that lazy topology.
            _materialize(state)
        # Output rules are identified by meaning, not their old compose
        # position. Apply the same row migration to weights and Adam moments.
        generate_rows = {}
        for name, module in self.named_modules(remove_duplicate=False):
            # Word admission enables this existing lazy structural prior.
            # A surface-bearing checkpoint must load into an unstaged model,
            # including its learned prior, without a preparatory input pass.
            if name + ".chunk_prior" in state:
                ensure_prior = getattr(type(module), "ensure_chunk_prior", None)
                if ensure_prior is not None:
                    ensure_prior(module)
            migrate = getattr(type(module), "migrate_generate_checkpoint", None)
            if migrate is not None:
                generate_rows.update(migrate(module, state, name + "."))
        self._pending_generate_policy_rows = generate_rows
        # data/BasicModel.ckpt still carries the retired reverse student's
        # twelve parameter keys. Retain this one-way state/optimizer migration;
        # no configuration can instantiate the former training path.
        if getattr(self, "reconstruct_in_loop", False):
            _student = [k for k in state if ".reverse_chooser." in k
                        or k.startswith("reverse_chooser.")]
            if _student:
                for k in _student:
                    state.pop(k)
                TheMessage(
                    f"reconstructInLoop: dropped {len(_student)} detached "
                    "reverse-student keys from the checkpoint (declared "
                    "migration)")
        # Concept values have one owner: the structural sidecar. Older
        # checkpoints also registered copies through the module tree.
        duplicated_parts = [key for key in state if 'concept_parts_layer.' in key]
        if duplicated_parts and not structural_extras:
            raise ValueError('concept part checkpoint requires its structural sidecar')
        for key in duplicated_parts:
            state.pop(key)

        # Pre-check for shape mismatches before attempting to load.
        # This produces an actionable diagnostic instead of a raw PyTorch error.
        model_state = dict(self.state_dict())
        for name in tuple(state):
            renamed=name.replace('.discourse.','.expectation.')
            if renamed != name and renamed in model_state:
                if renamed in state and not torch.equal(state[name],state[renamed]):
                    raise ValueError('checkpoint contains conflicting expectation owners')
                state[renamed]=state.pop(name)

        # The local-role predictor replaces the root-only head. Its owner
        # declares this migration before the checkpoint mismatch audit; all
        # other parameters and optimizer state retain their name-based rules.
        for module_name, module in self.named_modules(remove_duplicate=False):
            migrate = getattr(module, "migrate_expectation_checkpoint", None)
            if callable(migrate):
                migrate(state, module_name + "." if module_name else "")

        # Space-owned carrier-state migration (2026-07-17): durable Basis and
        # Encoding modules moved from ``Space.subspace`` into the Space's
        # authoritative ``_owned_bases`` / ``_owned_encoders`` containers.
        # Rewrite only when the candidate is an exact live key, so unrelated
        # nested SubSpaces (including SymbolSubSpace) retain their own paths.
        _carrier_key_roles = {
            **{
                role: '_owned_bases'
                for role in ('event', 'what', 'where', 'when', 'activation')
            },
            **{
                role: '_owned_encoders'
                for role in (
                    'activeEncoding',
                    'objectEncoding',
                    'whatEncoding',
                    'whereEncoding',
                    'whenEncoding',
                    'wordEncoding',
                )
            },
        }
        _carrier_renamed = 0
        for _old_key in list(state.keys()):
            _percept_token = '.subspace.percept_store.'
            if _percept_token in _old_key:
                _new_key = _old_key.replace(
                    _percept_token, '._percept_store.', 1
                )
                if _new_key in model_state and _old_key not in model_state:
                    state[_new_key] = state.pop(_old_key)
                    _carrier_renamed += 1
                    continue
            for _role, _container in _carrier_key_roles.items():
                _token = f'.subspace.{_role}.'
                if _token not in _old_key:
                    continue
                _new_key = _old_key.replace(
                    _token, f'.{_container}.{_role}.', 1
                )
                if _new_key in model_state and _old_key not in model_state:
                    state[_new_key] = state.pop(_old_key)
                    _carrier_renamed += 1
                break
        # SymbolSpace migration (2026-06-21 refactor, Stage 3): the
        # SymbolSubSpace coordinator moved UNDER the new SymbolSpace container
        # (``m.symbolSpace`` is now a ``SymbolSpace(Space)`` that owns
        # ``.subspace``), so its state_dict keys shifted from
        # ``symbolSpace.*`` to ``symbolSpace.subspace.*``. Rewrite the old
        # keys in place so pre-refactor checkpoints load. One-time bridge; runs
        # before the bivector pass so renamed keys still get bivector-expanded.
        _ss_old = "symbolSpace."
        _ss_new = "symbolSpace.subspace."
        _ss_renamed = 0
        for k in list(state.keys()):
            if (
                not k.startswith(_ss_old)
                or k.startswith(_ss_new)
                or k in model_state
            ):
                continue
            remainder = k[len(_ss_old):]
            candidates = [_ss_new + remainder]
            head = remainder.split('.', 1)[0]
            if head in ('event', 'what', 'where', 'when', 'activation'):
                candidates.insert(
                    0, f"symbolSpace._owned_bases.{remainder}"
                )
            elif head in (
                'activeEncoding', 'objectEncoding', 'whatEncoding',
                'whereEncoding', 'whenEncoding', 'wordEncoding',
            ):
                candidates.insert(
                    0, f"symbolSpace._owned_encoders.{remainder}"
                )
            target = next(
                (candidate for candidate in candidates if candidate in model_state),
                candidates[-1],
            )
            state[target] = state.pop(k)
            _ss_renamed += 1
        if _ss_renamed:
            warnings.warn(
                f"SymbolSpace migration: rewrote {_ss_renamed} symbolSpace.* "
                f"checkpoint keys to symbolSpace.subspace.* (the "
                f"coordinator moved under the new SymbolSpace container).",
                stacklevel=2,
            )

        # Remove pre-ownership duplicate module paths. Terminal aliases,
        # body-stage ModuleDicts, and Space->SymbolSpace back-references used
        # to register the same modules repeatedly. Canonical ModuleLists and
        # ``model.symbolSpace`` are now their sole structural owners.
        _alias_renamed = 0
        _legacy_ws_grammar_dropped = []
        _legacy_ws_category_dropped = []
        _last_cs = len(getattr(self, 'conceptualSpaces', ())) - 1
        _last_ws = len(getattr(self, 'wholeSpaces', ())) - 1
        for _old_key in list(state.keys()):
            _target = None
            _parts = _old_key.split('.')
            if (
                len(_parts) >= 4
                and _parts[0] == 'wholeSpaces'
                and _parts[1].isdigit()
                and _parts[2] == 'conceptualSpace'
            ):
                # Historical WS->CS module registration duplicated the entire
                # concept tree below each WholeSpace. CS is now a non-owning
                # downstream pointer, so retain the learned value only under
                # its canonical ConceptualSpace stage.
                _target = '.'.join(
                    ['conceptualSpaces', _parts[1], *_parts[3:]])
            elif (
                len(_parts) >= 3
                and _parts[0] == 'wholeSpaces'
                and _parts[1].isdigit()
                and _parts[2] in ('_category_vq', '_category_role')
            ):
                _candidate = '.'.join(
                    ['conceptualSpaces', _parts[1], *_parts[2:]])
                if _candidate in model_state:
                    _target = _candidate
                else:
                    _legacy_ws_category_dropped.append(_old_key)
                    del state[_old_key]
                    continue
            elif (_last_cs >= 0
                  and _old_key.startswith('wholeSpace.conceptualSpace.')):
                _target = (
                    f'conceptualSpaces.{_last_cs}.'
                    + _old_key[len('wholeSpace.conceptualSpace.'):])
            elif (_last_cs >= 0 and _old_key.startswith(
                    ('wholeSpace._category_vq.',
                     'wholeSpace._category_role'))):
                _rest = _old_key[len('wholeSpace.'):]
                _candidate = f'conceptualSpaces.{_last_cs}.{_rest}'
                if _candidate in model_state:
                    _target = _candidate
                else:
                    _legacy_ws_category_dropped.append(_old_key)
                    del state[_old_key]
                    continue
            elif (
                len(_parts) >= 5
                and _parts[0] == 'body_stages'
                and _parts[1].isdigit()
                and _parts[2] == 'ws'
                and _parts[3] == 'conceptualSpace'
            ):
                _target = '.'.join(
                    ['conceptualSpaces', _parts[1], *_parts[4:]])
            elif (
                len(_parts) >= 4
                and _parts[0] == 'body_stages'
                and _parts[1].isdigit()
                and _parts[2] == 'ws'
                and _parts[3] in ('_category_vq', '_category_role')
            ):
                _candidate = '.'.join(
                    ['conceptualSpaces', _parts[1], *_parts[3:]])
                if _candidate in model_state:
                    _target = _candidate
                else:
                    _legacy_ws_category_dropped.append(_old_key)
                    del state[_old_key]
                    continue
            elif (
                len(_parts) >= 4 and _parts[0] == 'wholeSpaces' and _parts[1].isdigit() and (_parts[2] == 'syntacticLayer')
            ):
                _rest = '.'.join(_parts[3:])
                _grammar_candidates = (
                    f'symbolSpace.syntacticLayer.{_rest}',
                    f'symbolSpace.subspace.syntacticLayer.{_rest}',
                )
                _target = next((candidate for candidate in _grammar_candidates
                                if candidate in model_state
                                and tuple(model_state[candidate].shape)
                                == tuple(state[_old_key].shape)), None)
                if _target is None:
                    _legacy_ws_grammar_dropped.append(_old_key)
                    del state[_old_key]
                    continue
            elif (_old_key.startswith('wholeSpace.syntacticLayer.') and _last_ws >= 0):
                _rest = _old_key[len('wholeSpace.syntacticLayer.'):]
                _grammar_candidates = (
                    f'symbolSpace.syntacticLayer.{_rest}',
                    f'symbolSpace.subspace.syntacticLayer.{_rest}',
                )
                _target = next((candidate for candidate in _grammar_candidates
                                if candidate in model_state
                                and tuple(model_state[candidate].shape)
                                == tuple(state[_old_key].shape)), None)
                if _target is None:
                    _legacy_ws_grammar_dropped.append(_old_key)
                    del state[_old_key]
                    continue
            elif (
                len(_parts) >= 5 and _parts[0] == 'body_stages' and _parts[1].isdigit() and (_parts[2] == 'ws') and (_parts[3] == 'syntacticLayer')
            ):
                _rest = '.'.join(_parts[4:])
                _grammar_candidates = (
                    f'symbolSpace.syntacticLayer.{_rest}',
                    f'symbolSpace.subspace.syntacticLayer.{_rest}',
                )
                _target = next((candidate for candidate in _grammar_candidates
                                if candidate in model_state
                                and tuple(model_state[candidate].shape)
                                == tuple(state[_old_key].shape)), None)
                if _target is None:
                    _legacy_ws_grammar_dropped.append(_old_key)
                    del state[_old_key]
                    continue
            elif _last_cs >= 0 and _old_key.startswith('conceptualSpace.'):
                _target = (
                    f'conceptualSpaces.{_last_cs}.'
                    + _old_key[len('conceptualSpace.'):]
                )
            elif _last_ws >= 0 and _old_key.startswith('wholeSpace.'):
                _target = (
                    f'wholeSpaces.{_last_ws}.'
                    + _old_key[len('wholeSpace.'):]
                )
            else:
                if (
                    len(_parts) >= 4
                    and _parts[0] == 'body_stages'
                    and _parts[1].isdigit()
                    and _parts[2] in ('cs', 'ws')
                ):
                    _owner = (
                        'conceptualSpaces'
                        if _parts[2] == 'cs'
                        else 'wholeSpaces'
                    )
                    _target = '.'.join(
                        [_owner, _parts[1], *_parts[3:]]
                    )
                else:
                    for _token in ('._model_symbolSpace.', '.symbolSpace.'):
                        if _token in _old_key:
                            _target = 'symbolSpace.' + _old_key.split(
                                _token, 1
                            )[1]
                            break
            if _target is None or _target == _old_key:
                continue
            if _target not in state:
                state[_target] = state[_old_key]
            del state[_old_key]
            _alias_renamed += 1

        # Alias canonicalization may have produced canonical legacy
        # ``*.subspace.<slot>.*`` keys. Apply the ownership rewrite once more.
        for _old_key in list(state.keys()):
            _new_key = None
            _percept_token = '.subspace.percept_store.'
            if _percept_token in _old_key:
                _candidate = _old_key.replace(
                    _percept_token, '._percept_store.', 1
                )
                if _candidate in model_state:
                    _new_key = _candidate
            if _new_key is None:
                for _role, _container in _carrier_key_roles.items():
                    _token = f'.subspace.{_role}.'
                    if _token in _old_key:
                        _candidate = _old_key.replace(
                            _token, f'.{_container}.{_role}.', 1
                        )
                        if _candidate in model_state:
                            _new_key = _candidate
                        break
            if _new_key is not None:
                if _new_key not in state:
                    state[_new_key] = state[_old_key]
                del state[_old_key]
                _carrier_renamed += 1

        # The pre-ownership model also registered the signal router's CS binary
        # reducer twice at the model root.  Both spellings are aliases of the
        # canonical SymbolSpace LanguageLayer reducer; retain a value only at
        # that downstream owner, with exact key/shape validation.
        _stm_reducer_aliases = 0
        for _old_key in list(state.keys()):
            _prefix = next((p for p in (
                "_stm_reducer_module.", "_stm_reducer_cached.")
                if _old_key.startswith(p)), None)
            if _prefix is None:
                continue
            _rest = _old_key[len(_prefix):]
            _target = (
                "symbolSpace.subspace.languageLayer.operation_layer."
                + _rest)
            if _target not in model_state:
                # Unknown reducer state remains present and will fail the strict
                # mismatch audit below.
                continue
            if (_target in state
                    and tuple(state[_target].shape)
                    == tuple(model_state[_target].shape)):
                # A canonical, current-shaped copy is already present.  Some
                # historical root aliases were stale even within the same
                # checkpoint (fewer grammar tools); discard that alias rather
                # than overwriting the authoritative learned table.
                del state[_old_key]
                _stm_reducer_aliases += 1
                continue
            if (tuple(model_state[_target].shape)
                    != tuple(state[_old_key].shape)):
                # No authoritative canonical value and the alias cannot fit:
                # leave it for the strict mismatch audit; never resize grammar
                # semantics by guessing rows/feature columns.
                continue
            if _target not in state:
                state[_target] = state[_old_key]
            del state[_old_key]
            _stm_reducer_aliases += 1
        if _alias_renamed:
            warnings.warn(
                f"Space ownership migration: removed {_alias_renamed} "
                f"duplicate alias checkpoint keys.",
                stacklevel=2,
            )
        if _legacy_ws_grammar_dropped:
            warnings.warn(
                "WholeSpace ownership migration dropped "
                f"{len(_legacy_ws_grammar_dropped)} obsolete syntactic-layer "
                "checkpoint keys that have no exact downstream owner.",
                stacklevel=2,
            )
        if _legacy_ws_category_dropped:
            warnings.warn(
                "WholeSpace ownership migration dropped "
                f"{len(_legacy_ws_category_dropped)} category checkpoint "
                "keys because no exact ConceptualSpace owner was present.",
                stacklevel=2,
            )
        if _carrier_renamed:
            warnings.warn(
                f"Space ownership migration: rewrote {_carrier_renamed} "
                f"legacy Space.subspace Basis/Encoding checkpoint keys.",
                stacklevel=2,
            )
        if _stm_reducer_aliases:
            warnings.warn(
                "Space ownership migration: removed "
                f"{_stm_reducer_aliases} duplicate STM reducer alias "
                "checkpoint keys.",
                stacklevel=2,
            )

        # VQ-backed Codebooks formerly registered one Parameter twice as
        # ``W`` and ``vq._codebook``. The parent Basis now owns W exclusively;
        # retain the VQ value only when an unusually stripped artifact lacks W.
        _vq_aliases = 0
        for _old_key in list(state.keys()):
            if not _old_key.endswith('.vq._codebook'):
                continue
            _owner_key = _old_key[:-len('vq._codebook')] + 'W'
            # A duplicate VQ key has no current entry of its own, so the
            # carrier rewrite above cannot resolve it. Resolve its owner W
            # through the same ownership map before removing the alias.
            if _owner_key not in model_state:
                for _role, _container in _carrier_key_roles.items():
                    _candidate = _owner_key.replace(
                        f'.subspace.{_role}.', f'.{_container}.{_role}.', 1)
                    if _candidate in model_state:
                        _owner_key = _candidate
                        break
            if _owner_key not in model_state:
                continue
            if _owner_key not in state:
                state[_owner_key] = state[_old_key]
            del state[_old_key]
            _vq_aliases += 1
        if _vq_aliases:
            warnings.warn(
                f"Codebook ownership migration: removed {_vq_aliases} "
                f"duplicate VQ Parameter checkpoint keys.",
                stacklevel=2,
            )

        # The live canonical architecture has one physical ConceptualSpace
        # dictionary registered through each stage's compatibility aliases.
        # Resolve old independent stage tables to stage 0 before capacity
        # expansion so every alias receives the same grown tensor.
        self._canonicalize_shared_concept_checkpoint_state(state, model_state)

        # A configured capacity increase is a row-preserving migration, not
        # the historical bivector pole-doubling migration below.  Expand first
        # so (in particular) an exact 2x capacity increase cannot be mistaken
        # for old positive/negative-pole layout.
        self._expand_partspace_codebook_checkpoint_state(state, model_state)
        self._expand_aligned_codebook_checkpoint_state(state, model_state)

        # Bivector migration: pre-bivector checkpoints have a [K, D] symbolic
        # codebook, while the current model expects [2K, D]. Duplicate each
        # row into the positive-pole slot (row 2k), leaving the negative-pole
        # slot (row 2k+1) zero. One-time bridge; no reverse migration.
        # Skip when the saved tensor is empty (saved.shape[0] == 0):
        # ``2 * 0 == 0`` makes the doubling test trivially true and the
        # warning fires for a no-op shape transition.
        for k, saved_v in list(state.items()):
            if k not in model_state:
                continue
            model_v = model_state[k]
            if (saved_v.dim() == 2 and model_v.dim() == 2
                    and saved_v.shape[1] == model_v.shape[1]
                    and saved_v.shape[0] > 0
                    and model_v.shape[0] == 2 * saved_v.shape[0]
                    and "wholeSpace" in k):
                migrated = torch.zeros_like(model_v)
                migrated[0::2] = saved_v
                state[k] = migrated
                warnings.warn(
                    f"Bivector migration: expanded {k} from "
                    f"{list(saved_v.shape)} to {list(model_v.shape)} "
                    f"(positive poles only; negative poles zero).",
                    stacklevel=2,
                )

        # A widened What chooser context (2026-09-08: absolute .where
        # positions joined the target-free context) only adds zero columns
        # to the zero-initialized ``what_projection``; older heads load with
        # the new columns at zero, exactly like a fresh head.
        self._widen_what_projection_checkpoint_state(state, model_state)

        # Only global inverted postings have variable-length checkpoint columns.
        from Layers import TernaryTruthStore
        index_owners = [name for name, module in self.named_modules(remove_duplicate=False)
                        if isinstance(module, TernaryTruthStore)]
        variable_leaf_columns = {name + '.' + column for name in index_owners
            for column in ('posting_codes', 'posting_roles', 'posting_rows',
                           'adjacent_left', 'adjacent_right', 'adjacent_address', 'adjacent_position')}
        retired_leaf_columns = {name + '.' + column for name in index_owners
                                for column in ('leaf_codes', 'leaf_offsets')}
        mismatches = [
            (k, list(state[k].shape), list(model_state[k].shape))
            for k in state if k in model_state
            and state[k].shape != model_state[k].shape
            and not (k in variable_leaf_columns and state[k].ndim == 1
                     and state[k].dtype == model_state[k].dtype)
        ]
        missing = [k for k in model_state if k not in state]
        unexpected = [k for k in state if k not in model_state and k not in retired_leaf_columns]
        fatal_unexpected = unexpected if (strict or require_match) else []
        # Under ``require_match`` (autoload path), tolerate missing-only
        # mismatches: the current architecture may have grown new
        # parameters since the checkpoint was saved (e.g., the S → S
        # identity rule or the rule_predictor head's added rule slot).
        # Those new parameters initialize from their fresh-build random
        # values, which is the right outcome for the autoload migration
        # path. Shape mismatches and unexpected keys remain fatal — those
        # signal a real architecture divergence that needs a regenerated
        # checkpoint or a config correction.
        fatal = bool(mismatches or fatal_unexpected)
        if fatal or missing:
            lines = [f"[{self.name}] Weight file mismatch -- cannot load {path}"
                     if fatal
                     else f"[{self.name}] Weight file partial -- {path}"]
            if mismatches:
                lines.append("  Shape mismatches:")
                for key, saved_shape, model_shape in mismatches[:10]:
                    lines.append(f"    {key:<50s}  saved={saved_shape}  model={model_shape}")
                if len(mismatches) > 10:
                    lines.append(f"    ... and {len(mismatches) - 10} more")
            if missing:
                lines.append(f"  Keys in model but missing from file: {len(missing)} (initialized fresh)")
            if fatal_unexpected:
                lines.append(f"  Keys in file not present in model: {len(fatal_unexpected)}")
                for key in fatal_unexpected[:20]:
                    lines.append(f"    {key}")
                if len(fatal_unexpected) > 20:
                    lines.append(
                        f"    ... and {len(fatal_unexpected) - 20} more")
            if fatal:
                lines.append("  The model config likely changed since this checkpoint was saved.")
                lines.append(f"  To fix: correct the model XML to match the saved weights,")
                lines.append(f"          or delete/move {path} to start fresh.")
                if require_match:
                    raise ValueError("\n".join(lines))
                TheMessage("\n".join(lines))
                return False
            TheMessage("\n".join(lines))

        symbol_owner = getattr(self, "symbolSpace", None)
        previous_defer = getattr(symbol_owner, "_defer_ltm_pruning", False)
        if symbol_owner is not None and structural_extras is not None:
            symbol_owner._defer_ltm_pruning = True
        try:
            self.load_state_dict(state, strict=strict)
        except RuntimeError as e:
            TheMessage(f"[{self.name}] Warning: cannot load {path}: {e}")
            return False
        finally:
            if symbol_owner is not None:
                symbol_owner._defer_ltm_pruning = previous_defer

        if unexpected:
            TheMessage(
                f"[{self.name}] Ignored {len(unexpected)} stale checkpoint "
                f"keys not present in the current model")

        # Restore Python-side WordVectors mappings (index_to_key etc.).
        if vocab_extras is not None or legacy_whole_structure is not None:
            self._restore_vocab_extras(
                vocab_extras or {},
                legacy_whole_structure=legacy_whole_structure)
        # Restore ChunkLayer BPE state (merges, vocab, id_to_bytes).
        # Restore symbolic identity before the optimizer is constructed. The
        # sidecar can materialize the ConceptAllocator's sparse values
        # Parameter; getOptimizer must see that live Parameter (and its saved
        # ordering) before loading optimizer_state.
        if (structural_extras is not None
                or legacy_whole_structure is not None):
            self._restore_structural_extras(
                structural_extras or {"version": 2},
                legacy_whole_structure=legacy_whole_structure)

        # Every aligned VQ must expose the same contiguous prefix after load.
        # This also expands (value-only, power-of-two) if a restored allocator
        # cursor already occupies rows beyond a stale saved mask.
        self._resync_aligned_active_codebooks()

        # Model autoload runs before the optimizer exists, so defer optimizer
        # restoration until getOptimizer(). Name manifests prevent retired WS
        # parameters from shifting Adam moments onto unrelated live tensors.
        self._pending_optimizer_state = optimizer_state
        self._pending_optimizer_manifest = optimizer_manifest
        self._pending_legacy_state_shapes = legacy_state_shapes
        self._pending_optimizer_reset_wholespace = (
            reset_wholespace_optimizer)
        self._pending_optimizer_require_match = bool(require_match)
        self._training_step_count = int(
            training_state.get("training_step_count", 0) or 0)
        from LearningEvaluation import validated_progress
        self._fineweb_training_progress = validated_progress(
            training_state.get("fineweb_training_progress"))
        self._word_observation_serial = int(training_state.get("word_observation_serial", 0))
        self._train_batches_seen = int(
            training_state.get("train_batches_seen", 0) or 0)
        self._epoch_batches_seen = int(
            training_state.get("epoch_batches_seen", 0) or 0)
        self._resume_batches_to_skip = self._epoch_batches_seen
        self._checkpoint_batch_size = training_state.get(
            "checkpoint_batch_size")
        saved_manifest = training_state.get("data_manifest")
        live_manifest = getattr(
            getattr(getattr(self, "inputSpace", None), "data", None),
            "source_manifest", None)
        if (saved_manifest is not None and live_manifest is not None
                and saved_manifest != live_manifest):
            message = (
                f"[{self.name}] Checkpoint data manifest does not match "
                f"the loaded corpus: saved={saved_manifest}, "
                f"live={live_manifest}")
            if require_match:
                raise ValueError(message)
            TheMessage(message)
        if training_state.get("torch_rng_state") is not None:
            torch.set_rng_state(training_state["torch_rng_state"].cpu())
        if training_state.get("python_rng_state") is not None:
            random.setstate(training_state["python_rng_state"])
        if training_state.get("numpy_rng_state") is not None:
            np.random.set_state(training_state["numpy_rng_state"])
        if (torch.cuda.is_available()
                and training_state.get("cuda_rng_state_all") is not None):
            torch.cuda.set_rng_state_all(training_state["cuda_rng_state_all"])
        mps_state = training_state.get("mps_rng_state")
        set_mps_state = getattr(
            getattr(torch, "mps", None), "set_rng_state", None)
        if mps_state is not None and callable(set_mps_state):
            try:
                set_mps_state(mps_state.detach().to("cpu"))
            except (RuntimeError, AttributeError):
                # A checkpoint remains loadable on CPU/non-MPS hosts; the
                # state is applied when the active runtime has a Metal RNG.
                pass

        TheMessage(f"[{self.name}] Weights loaded from {path}")
        return True

    def _restore_vocab_extras(
            self, extras, *, legacy_whole_structure=None):
        """Restore lexicon occupancy within its fixed physical allocation.

        Vector data is copied by the subsequent state_dict load. The live
        Parameter and its optimizer ownership remain unchanged.

        Space-side restores run first, independent of the Embedding: a radix
        envelope may carry them with an empty lexicon. Concept structure
        belongs to ConceptualSpace; WholeSpace receives property metadata.
        Retired WholeSpace word/META sidecars are discarded with a warning.
        """
        whole_space = getattr(self, 'wholeSpace', None)
        concept_space = getattr(self, 'conceptualSpace', None)
        surface_owners = getattr(self, "conceptualSpaces", None) or [concept_space]
        for stage, payload in (extras.get("concept_word_surfaces") or {}).items():
            index = int(stage)
            if not 0 <= index < len(surface_owners):
                raise ValueError(f"word-surface checkpoint has unknown CS stage {stage}")
            # Legacy row-to-spelling caches are superseded by migrated DEF forms.
            if int(payload.get("version", 0)) != 1:
                raise ValueError("unsupported legacy word-surface version")
        conceptual_blob = extras.get("conceptual_structure")
        if (concept_space is not None
                and isinstance(conceptual_blob, dict)
                and hasattr(concept_space, "load_vocab_extras")):
            concept_space.load_vocab_extras(conceptual_blob)
        property_blob = extras.get("whole_properties")
        if whole_space is not None and isinstance(property_blob, dict):
            whole_space.load_property_extras(property_blob)

        if extras.get('ws_taxonomy_extras') or extras.get('well_known_atoms') or legacy_whole_structure:
            warnings.warn('Dropping retired WholeSpace word and META structure (§11.4).', UserWarning)
        # The PS percept store's trie/inverse-table state (the WORD
        # surfaces; absent in pre-feature blobs). Runs pre-state-dict per
        # the envelope contract: load_vocab_extras re-allocates the shared
        # codebook capacity first so the shape pre-check sees matching dims.
        ps_pstore = extras.get("ps_percept_extras")
        if isinstance(ps_pstore, dict):
            part_space = getattr(self, 'perceptualSpace', None)
            store = getattr(part_space, 'percept_store', None)
            if store is not None and hasattr(store, 'load_vocab_extras'):
                store.load_vocab_extras(ps_pstore)
        # Canonical abstraction-order provenance for the PS percept codebook
        # (absent in pre-feature blobs). Restore only after the radix sidecar
        # has grown the physical table, otherwise fold rows in the saved tail
        # would be silently discarded against the smaller XML initial prefix.
        ps_rams = extras.get("ps_ramsification")
        if isinstance(ps_rams, dict):
            ps_cb = getattr(getattr(getattr(self, 'perceptualSpace', None),
                                    'subspace', None), 'what', None)
            if ps_cb is not None and hasattr(ps_cb,
                                             'load_ramsification_extras'):
                ps_cb.load_ramsification_extras(ps_rams)
        emb = self._get_embedding()
        if emb is None or getattr(emb, 'wv', None) is None:
            return
        wv = emb.wv
        keys = list(extras.get("index_to_key") or [])
        if not keys:
            return
        counts = extras.get("counts") or []
        total = int(extras.get("total_count") or 0)
        vocab_size = len(keys)
        capacity = int(emb.lexicon_capacity)
        saved_capacity = int(extras.get("physical_capacity", capacity))
        if saved_capacity != capacity or vocab_size > capacity:
            raise ValueError(f"lexicon checkpoint requires nVectors={saved_capacity}; "
                             f"configured nVectors={capacity}, active rows={vocab_size}")
        # The subsequent state_dict load copies vector values into this same
        # physical Parameter. Restore occupancy without replacing its owner.
        wv.index_to_key = keys
        wv.key_to_index = {k: i for i, k in enumerate(keys)}
        wv.counts = (np.asarray(counts, dtype=np.int64) if counts
                     else np.zeros(vocab_size, dtype=np.int64))
        wv.total_count = np.int64(total)
        if getattr(emb, 'pretrain', None) is not None:
            emb.pretrain.index_to_key = wv.index_to_key
            emb.pretrain.key_to_index = wv.key_to_index
        wv._normed = None


    def _get_sentences(self, split):
        """Return raw sentence strings for a data split.

        All splits store raw strings directly in their input lists.
        Runtime maps to train_input (staged by runtime_batch).
        """
        data = self.inputSpace.data
        if split == "train" or split == "runtime":
            result = data.train_input
        elif split == "test":
            result = data.test_input
        elif split == "validation":
            result = data.validation_input
        else:
            return None
        if result and isinstance(result[0], str):
            return result
        return None

    @staticmethod
    def _bytes_to_text(tensor):
        """Decode a byte tensor (or padded int8 tensor) to a string."""
        if isinstance(tensor, str):
            return tensor
        if tensor.dim() > 1:
            tensor = tensor.squeeze()
        chars = [chr(int(b) & 0xFF) for b in tensor.tolist()]
        return "".join(chars).rstrip("\x00")

    @staticmethod
    def _data_len(items):
        if items is None:
            return 0
        if isinstance(items, torch.Tensor):
            return int(items.shape[0])
        return len(items)

    @staticmethod
    def _slice_data(items, n):
        if items is None:
            return []
        if isinstance(items, torch.Tensor):
            return [items[i] for i in range(min(n, int(items.shape[0])))]
        return list(items[:n])

    @staticmethod
    def _display_value(value):
        if isinstance(value, str):
            return value
        if isinstance(value, torch.Tensor):
            x = value.detach().cpu().squeeze()
            if x.numel() == 1:
                return f"{float(x.reshape(-1)[0]):.4f}"
            vals = x.reshape(-1)
            if vals.numel() <= 8:
                return "[" + ", ".join(f"{float(v):.4f}" for v in vals) + "]"
            return f"shape={tuple(x.shape)}"
        if isinstance(value, (list, tuple)):
            return "[" + ", ".join(BaseModel._display_value(v) for v in value) + "]"
        return str(value)

    def _input_token_count(self, original):
        if not isinstance(original, str):
            return None
        lex = str(getattr(self, 'lexer', 'word') or 'word').lower()
        if lex in ('word', 'words'):
            try:
                # parse(..., lex='words') yields the inter-word space as
                # its own token ('hello world' -> 3 tokens). Filter to
                # non-whitespace so the count matches actual word slots.
                return len([tok for tok, _ in parse(original, lex='words')
                            if tok and tok.strip()])
            except Exception:
                return len(original.split())
        if lex in ('byte', 'bytes'):
            return len(original.encode('utf-8'))
        if lex == 'sentence':
            return 1
        return len(original.split())

    def _reverse_decode_one(self, vec):
        """Stage 8 structural decode of a single terminal CS vector.

        Thin wrapper around :meth:`RadixLayer.reverse` (Task F): the
        canonical body now lives on the PS-side layer that owns the
        inverse table, so BasicModel no longer reaches across PS, WS,
        and the codebook itself. Returns ``b""`` when the radix path
        is not active (no ``percept_store``) or either space is
        unwired.
        """
        ps_space = getattr(self, "perceptualSpace", None)
        if ps_space is None:
            return b""
        ps_store = getattr(ps_space, "percept_store", None)
        if ps_store is None:
            return b""
        ws = getattr(self, "wholeSpace", None)
        return ps_store.reverse(vec, symbolic_space=getattr(self, 'conceptualSpace', None))

    def _decode_reconstructed_inputs(self, recon, originals):
        if not isinstance(recon, torch.Tensor) or recon.numel() == 0:
            return []
        if getattr(self.inputSpace, 'model_type', None) != "embedding":
            return [self._display_value(recon[i]) for i in range(recon.shape[0])]

        # Stage 8 (doc/plans/2026-05-27-perceptstore-meta-taxonomy-
        # reentrancy.md §Stage 8): when the radix path is active the
        # reverse decode is *structural* -- WS nearest match -> META
        # children -> PS percept id -> inverse_table bytes. No
        # nearest-neighbour against PS vectors at the surface step.
        ps_space = getattr(self, "perceptualSpace", None)
        ps_store = (getattr(ps_space, "percept_store", None)
                    if ps_space is not None else None)
        if (ps_store is not None and (not self.word_brackets) and (self.concept_binding == 'aligned')):
            # Native reconstruction has already decoded attributed radix
            # activity. Neither original lengths nor live perception is read.
            return [bytes(row.reshape(-1).to(torch.uint8).tolist()).rstrip(b'\0')
                    .decode('utf8', errors='replace') for row in recon.detach().cpu()]
        if ps_store is not None:
            vectors = recon.detach()
            # Normalise to [B, N, D].
            while vectors.ndim > 3 and 1 in vectors.shape[2:-1]:
                for ax in range(2, vectors.ndim - 1):
                    if vectors.shape[ax] == 1:
                        vectors = vectors.squeeze(ax)
                        break
            if vectors.ndim == 2:
                vectors = vectors.unsqueeze(0)
            batch = int(vectors.shape[0]) if vectors.ndim >= 1 else 0
            n_vec = int(vectors.shape[1]) if vectors.ndim >= 2 else 0
            rendered = []
            for b in range(batch):
                words = []
                for v in range(n_vec):
                    raw = self._reverse_decode_one(vectors[b, v])
                    if not raw:
                        # Preserve the slot with an empty placeholder so
                        # the per-row token-count clip aligns with the
                        # original sentence length; dropping it shortens
                        # the rendered output and misaligns words[:N].
                        words.append("")
                        continue
                    try:
                        words.append(raw.decode("utf-8"))
                    except UnicodeDecodeError:
                        words.append(raw.decode("utf-8", errors="replace"))
                expected = (self._input_token_count(originals[b])
                            if b < len(originals) else None)
                if expected is not None:
                    words = words[:expected]
                rendered.append(" ".join(words))
            return rendered

        # Legacy lexicon / BPE / MPHF path: keep the existing decode.
        emb = getattr(getattr(self.perceptualSpace, 'subspace', None),
                      'what', None)
        if not isinstance(emb, Embedding):
            emb = getattr(self.perceptualSpace, 'vocabulary', None)
        if not isinstance(emb, Embedding):
            return [self._display_value(recon[i]) for i in range(recon.shape[0])]

        vectors = recon.detach()
        try:
            codebook = emb.getW()
            if torch.is_tensor(codebook):
                vectors = vectors.to(codebook.device)
            decoded = emb.decode_reverse_meta(
                vectors, subspace=self.perceptualSpace.subspace)
            word_rows = emb.reconstruct_data(decoded, text=False)
        except Exception:
            try:
                word_rows = self.perceptualSpace.reconstruct_data(text=False)
            except Exception:
                return [self._display_value(recon[i])
                        for i in range(recon.shape[0])]

        rendered = []
        for i, words in enumerate(word_rows):
            # 2026-05-28: filter empties, NUL sentinels, AND
            # whitespace-only tokens. The lexer transmits the inter-
            # word space as its own slot (see ``Embedding._token_stream``
            # appending ``\x00`` after ``parse(lex='words')``), so the
            # per-slot decode for "hello world" yields
            # ['hello', ' ', 'world', '\x00', '\x00', ...]. The display
            # contract is "show non-whitespace word tokens"; spaces and
            # nulls are transmitted but not displayed. Without
            # ``w.strip()`` the prior clip ``words[:expected]`` would
            # consume the space token slot and drop the real second
            # word.
            words = [w for w in words
                     if w not in ("", "\x00") and w.strip()]
            expected = (self._input_token_count(originals[i])
                        if i < len(originals) else None)
            if expected is not None:
                words = words[:expected]
            rendered.append(" ".join(words))
        return rendered

    def _reconstructionReport(self):
        """Run a final eval pass and print input reconstruction per row."""
        data = self.inputSpace.data
        split = "test"
        split_input = getattr(data, f"{split}_input", None)
        split_output = getattr(data, f"{split}_output", None)
        if self._data_len(split_input) == 0:
            split = "train"
            split_input = getattr(data, f"{split}_input", None)
            split_output = getattr(data, f"{split}_output", None)
        n_rows = self._data_len(split_input)
        if n_rows == 0:
            return
        try:
            max_rows = int(os.environ.get("BASIC_RECON_REPORT_MAX", "64"))
        except ValueError:
            max_rows = 64
        if max_rows > 0 and n_rows > max_rows:
            TheMessage(f"=== Input Reconstruction ({split}) ===")
            TheMessage(
                f"  skipped: {n_rows} rows exceeds "
                f"BASIC_RECON_REPORT_MAX={max_rows}; set it to 0 to "
                f"print every row.")
            return

        self.set_sigma(0)
        try:
            _, _, allOut, allIn = self.runEpoch(batchSize=n_rows, split=split)
        finally:
            self.set_sigma(0.5)

        if not isinstance(allIn, torch.Tensor) or allIn.numel() == 0:
            TheMessage(f"=== Input Reconstruction ({split}) ===")
            TheMessage("  (no reconstructed input was produced)")
            return

        n = min(n_rows, int(allIn.shape[0]))
        originals = self._slice_data(split_input, n)
        labels = self._slice_data(split_output, n)
        reconstructed = self._decode_reconstructed_inputs(allIn[:n], originals)

        rows = []
        TheMessage(f"=== Input Reconstruction ({split}) ===")
        for i in range(n):
            original = self._display_value(originals[i])
            recon = reconstructed[i] if i < len(reconstructed) else ""
            label = self._display_value(labels[i]) if i < len(labels) else ""
            pred = ""
            if isinstance(allOut, torch.Tensor) and allOut.numel() > 0:
                pred = self._display_value(allOut[i])
            orig_words = original.replace("\x00", " ").split()
            recon_words = recon.replace("\x00", " ").split()
            match = orig_words == recon_words
            status = "OK" if match else "MISMATCH"
            css = "match" if match else "mismatch"
            TheMessage(
                f"  row[{i}] input={original!r} -> "
                f"reconstructed={recon!r} label={label} "
                f"predicted={pred} {status}")
            rows.append([
                original,
                f'<span class="{css}">{recon}</span>',
                label,
                pred,
                f'<span class="{css}">{"Yes" if match else "No"}</span>',
            ])

        TheReport.add_table(
            f"Input vs Reconstructed ({split})",
            ["Input", "Reconstructed", "Label", "Predicted", "Match"],
            rows)
        self.inputSpace.data.reconstructed_input = reconstructed
        if isinstance(allOut, torch.Tensor):
            self.inputSpace.data.reconstructed_output = [
                allOut[i].detach().cpu() for i in range(min(n, allOut.shape[0]))]


class BasicModel(BaseModel):
    """Core model: assembles Spaces into a forward and (optionally) reverse pipeline.

    The forward pass flows:
        InputSpace -> PartSpace -> ConceptualSpace -> WholeSpace -> OutputSpace

    The reverse pass mirrors it:
        OutputSpace -> WholeSpace -> ConceptualSpace -> PartSpace -> InputSpace

    Higher-order processing (bindingDepth) inserts additional
    Percept/Concept/Symbol cycles between the first WholeSpace and OutputSpace,
    concatenating their symbol outputs before the final projection.

    ``create()`` builds the full space hierarchy.  ``create_from_config()`` is the
    XML-driven factory that reads architecture and training parameters from config,
    then delegates to ``create()``.
    """
    name = "BasicModel"
    # Transient execution permissions; never learned or checkpointed.
    _query_sentence_depth = 0
    _query_ready_rows = None

    def __init__(self, *args, **kwargs):
        super().__init__(*args, **kwargs)
        # Materialize before tracing so the first graph replay cannot add an
        # attribute and invalidate the guard state.
        self._query_sentence_depth = 0
        self._query_ready_rows = None

    def _assert_queries_outside_sentence(self):
        if torch.compiler.is_compiling() or self._query_sentence_depth:
            raise RuntimeError("queries cannot execute inside a sentence path")

    def _assert_query_boundary(self, row):
        self._assert_queries_outside_sentence()
        if self._query_ready_rows is None or row not in self._query_ready_rows:
            raise RuntimeError("query row has no completed boundary permission")

    @contextmanager
    def _query_boundary_scope(self, ready_rows):
        """Open only completed answer rows for one conceptual resolution."""
        self._assert_queries_outside_sentence()
        previous = self._query_ready_rows
        # A nested resolution can narrow existing permission, never widen it.
        allowed = tuple(
            row for row in ready_rows if previous is None or row in previous
        )
        self._query_ready_rows = allowed
        try:
            yield
        finally:
            self._query_ready_rows = previous

    def _thought_grammar_context(self, meaning, *, row, work, continuation):
        """Build the one capability-scoped context for a selected thought.

        This is intentionally the only model-to-thought bridge.  It freezes
        the completed field's occupied contents, reads current priming, and supplies narrow
        readers rather than a model or ``TruthGroundedReasoner`` object.  The
        descriptor-specific facade in :mod:`Queries` narrows those readers
        again immediately before each executor call.
        """
        if not isinstance(meaning, ConceptualMeaning):
            raise TypeError('thought grammar context requires a complete meaning')
        if type(row) is not int or row < 0:
            raise ValueError('thought grammar context requires a non-negative row')
        if not isinstance(work, QueryWorkBudget):
            raise TypeError('thought grammar context requires one QueryWorkBudget')
        self._assert_query_boundary(row)

        def freeze(value):
            if torch.is_tensor(value):
                return value.detach().clone()
            if isinstance(value, tuple):
                return tuple(freeze(item) for item in value)
            if isinstance(value, list):
                return tuple(freeze(item) for item in value)
            if isinstance(value, dict):
                return tuple((key, freeze(item)) for key, item in sorted(value.items()))
            return value

        stream = meaning.roles
        symbol_space = getattr(self, 'symbolSpace', None)
        concept_owner = self._concept_owner()
        primed = concept_owner.priming_weights()
        primed = None if primed is None else primed[row]

        from reasoning import TruthGroundedReasoner
        reasoner = TruthGroundedReasoner(
            model=self, store=getattr(symbol_space, 'ltm_store', None))
        discourse = getattr(symbol_space, 'expectation', None)
        registry = _boundary_registry(self)
        concept_owner = registry.space if registry is not None else self.conceptualSpace
        return ThoughtGrammarContext(
            word_stream=freeze(stream),
            conceptual_space=ThoughtConceptualCapability(
                concept_owner, TruthGroundedReasoner.equal),
            primed_symbols=freeze(primed),
            ltm=ThoughtLTMCapability(
                store=reasoner.reasoning_store,
                equal=TruthGroundedReasoner.equal, tau_id=reasoner.tau_id,
                memory=self._what_memory(), discourse=discourse, row=row,
                primed=((primed.reshape(-1) > 1.).nonzero().reshape(-1).tolist()
                        if torch.is_tensor(primed) else ())),
            taxonomy=ThoughtTaxonomyCapability(concept_owner),
            work=work, continuation=continuation,
            boundary=self._assert_query_boundary, row=row)

    @staticmethod
    def _completed_query_rows(understanding):
        """Read completed field ownership, independent of sentence staging."""
        return tuple(row for row, field in enumerate(understanding.sentence_states)
                     if field is not None and bool(field.meaning.role_mask.any()))

    @staticmethod
    def _selected_thought_context(root, active=None, candidate=None, *, level,
                                  pressure, evidence=None, memory_context=None,
                                  expectation_context=None):
        """Numerical controller input for one selected grammatical action.

        The root request, active context and action candidate each retain
        separate full-width ``[NP1, VP, NP2]`` blocks and masks.  ``active``
        defaults to ``root`` and ``candidate`` to ``active`` only for callers
        migrating from the first boundary adapter.  Native IDs, row numbers,
        occurrence addresses and surface tokens never enter the learned
        vector. Mode, polarity, bindings and scope use bounded categorical
        features, with alpha-renamed references. Visible attended STM/LTM
        values supplement the four actual-evidence scalars; no target enters.
        """
        if active is None:
            active = root
        if candidate is None:
            candidate = active
        meanings = (root, active, candidate)
        if not all(isinstance(meaning, ConceptualMeaning) for meaning in meanings):
            raise TypeError("selected thought context requires ConceptualMeaning values")
        width = int(root.roles.shape[-1])
        if any(int(meaning.roles.shape[-1]) != width for meaning in meanings):
            raise ValueError("selected thought meanings must share one conceptual width")
        if type(level) is not int or level < 0:
            raise ValueError("selected thought level must be a non-negative integer")
        if not math.isfinite(float(pressure)) or pressure < 0:
            raise ValueError("selected thought pressure must be finite and non-negative")

        def payload(meaning):
            roles = (meaning.roles
                     * meaning.role_mask.to(meaning.roles).unsqueeze(-1))
            return torch.cat((roles.reshape(-1), meaning.role_mask.to(
                device=roles.device, dtype=roles.dtype)))

        roles = (payload(root), payload(active), payload(candidate.detached()))
        source = dict(evidence or {})
        supports = []
        for name in ("support_true", "support_false"):
            value = source.get(name, 0.0)
            if torch.is_tensor(value):
                value = value.detach().item()
            value = float(value)
            if not math.isfinite(value) or not 0.0 <= value <= 1.0:
                raise ValueError("selected thought evidence support must be in [0, 1]")
            supports.append(value)
        metadata = torch.tensor(
            (float(level), float(pressure), *supports,
             float(evidence is not None),
             float(bool(source.get("incomplete", ())))),
            device=root.roles.device, dtype=root.roles.dtype)
        from ThoughtFeatures import semantic_metadata, attend_meanings
        semantics = semantic_metadata(meanings)
        if memory_context is None:
            memory_context = (attend_meanings(active, ()),) * 2
        # Policy credit belongs to this chooser. The world it observes is
        # given, including live episode meanings and attended query features.
        if expectation_context is None:
            expectation_context = torch.cat((active.roles.detach().reshape(-1),
                                             active.roles.new_zeros(7)))
        return torch.cat((*roles, metadata, *semantics, *memory_context,
                          expectation_context)).detach()

    def _selected_thought_expectation(self, active, *, row, work=None):
        """Read the closing's conceived roles; this never changes reading attention.

        The active question supplies only its grammatical open-role mask.
        Gain/presence/mask and both paired payloads are detached evidence.
        """
        from QueryWork import QueryWorkExhausted
        mask = active.roles.new_zeros(3)
        registry = _boundary_registry(self)
        if registry is not None:
            signature = registry.signature_for(active)
            question = active
            while (signature.descriptor.continues and work is not None
                   and work.remaining > 0):
                # what holds a question occurrence, not its filler. Follow
                # that checked address on the same meter to read its holes.
                context = self._thought_grammar_context(question, row=row,
                    work=work, continuation=None)
                try:
                    # LTM addresses cost one read. Serial addresses may name
                    # a later record; scan the bounded owner on the same meter.
                    question, _ = context.ltm.resolve_description(
                        question.role_refs[0], row=row,
                        max_records=self._what_memory().capacity, work=work)
                except QueryWorkExhausted:
                    # The controller's ordinary cutoff drains this exhausted
                    # episode; no unmetered read or guessed open role follows.
                    break
                if question.mode != 'interrogative':
                    # Content retrieval also accepts an addressed assertion.
                    # It has no nested executable question whose holes this
                    # expectation context may follow.
                    break
                signature = registry.signature_for(question)
            for role in signature.open_roles:
                mask[registry._slot_for_operand(role)] = 1
        discourse = getattr(getattr(self, "symbolSpace", None), "expectation", None)
        comparison = (discourse.last_expectation_comparison(row)
                      if discourse is not None and discourse.expectation_enabled else None)
        observed = active.roles.detach() if comparison is None else comparison.observed.to(active.roles)
        presence = (active.roles.new_zeros(3) if comparison is None
                    else comparison.estimate.presence_logits.sigmoid().to(active.roles))
        closing = getattr(self, '_closing_images', {}).get(row)
        conceived = observed if closing is None else closing.conceived.to(active.roles)
        return torch.cat((conceived.reshape(-1), presence, mask,
                          active.roles.new_tensor([comparison is not None]))).detach()

    def _selected_thought_chooser(self, meaning, *, device=None, dtype=None):
        """Return the width-owned learned chooser for complete meanings."""
        if not isinstance(meaning, ConceptualMeaning):
            raise TypeError("selected thought chooser requires a ConceptualMeaning")
        width = int(meaning.roles.shape[-1])
        key = str(width)
        table = getattr(self, "selected_thought_choosers", None)
        if table is None:
            table = nn.ModuleDict()
            self.selected_thought_choosers = table
        module = table[key] if key in table else None
        if module is None:
            from Language import SelectedThoughtChooser
            from ThoughtFeatures import context_width
            if device is None:
                device = meaning.roles.device
            if dtype is None:
                dtype = meaning.roles.dtype
            module = SelectedThoughtChooser(
                # Width includes semantic metadata and two bounded memory
                # attention results. Native IDs remain address metadata.
                context_dim=context_width(width),
                hidden=getattr(self, "what_thinking_hidden", 16),
                depth=getattr(self, "what_thinking_depth", 1),
            ).to(device=device, dtype=dtype)
            table[key] = module
            self._collect_fresh_synthesis_modules()
        return module

    def _stage_expectation_queries(self, *, training=None):
        """Optional prior-only thought before the batch's first external input.

        Packed later slots still receive ordinary chronological prediction;
        their optional query phase is empty. No query is run during a packed
        drain, when unseen inputs have already altered the model's staging.
        """
        discourse = getattr(getattr(self, "symbolSpace", None), "expectation", None)
        registry = _boundary_registry(self)
        self._pending_attention_meters = (() if discourse is None else tuple(
            QueryWorkBudget(getattr(self, 'attention_budget', self.expectation_query_budget))
            for _ in discourse._inter_context_occurrences))
        if (getattr(self, "expectation_policy_weight", 0.) <= 0 or discourse is None
                or not discourse.expectation_enabled or discourse._external_observations_suspended
                or getattr(self, "expectation_query_budget", 0) == 0):
            return
        if registry is None:
            raise ValueError("expectationPolicyWeight requires the model's thought catalogue")
        if "arma" not in registry.executable_operation_ids:
            raise ValueError("expectationPolicyWeight requires arma in the model's thought catalogue")
        store = getattr(self.symbolSpace, "ltm_store", None)
        if store is None:
            raise ValueError("expectationPolicyWeight requires ltmConsolidation for owned prior occurrences")
        from dataclasses import replace
        for row, occurrences in enumerate(discourse._inter_context_occurrences):
            if not occurrences or occurrences[-1] is None:
                continue
            index = store._index_occurrences.get(occurrences[-1])
            source = None if index is None else store.meaning_of(index)
            if source is None:
                continue
            operation = registry.operation_spec("arma")
            root = registry._form_candidate(operation, registry.descriptors["arma"],
                {operation.operand_roles[0]: (source.roles.sum(0) / source.role_mask.sum().sqrt(),
                                            occurrences[-1])},
                source=replace(source, mode="interrogative", polarity=True))
            self._anticipating_expectation_row = row
            self._anticipation_training = bool(self.training if training is None else training)
            self._anticipatory_choices = []
            def forecast():
                with self._query_boundary_scope((row,)):
                    result = self.run_selected_thought(root, row=row,
                        work_budget=min(self.expectation_query_budget,
                            self._pending_attention_meters[row].remaining), registry=registry)
                frames = self._what_memory().retrieved_frames(b=row, limit=discourse._inter_chain_window - 1)
                from ReferenceContext import SituationFrame
                reference_frames = tuple(frame for value in frames
                    if (frame := SituationFrame.from_row(value)) is not None)
                discourse.expect_next_meaning(row, frames=tuple(f['meaning'] for f in frames),
                    frame_occurrences=tuple(f['occurrence'] for f in frames), policy=tuple(self._anticipatory_choices), policy_work=result.work.spent,
                    refresh=True, reference_frames=reference_frames)
                return result, discourse._inter_last_meaning[row]
            try:
                if self._anticipation_training and torch.is_grad_enabled():
                    from WalkTrials import forecast_pair
                    pending = forecast_pair(self, root, row=row, run=forecast)
                    discourse._inter_last_meaning[row] = pending
                else:
                    forecast()
                pending = discourse._inter_last_meaning[row]
                # Its winner is not known until the next observation. Reserve
                # the larger prior-only spend so either held walk and the
                # arriving input fit the same allowance; no target selects it.
                spent = max(pending.work, pending.walk.other.work) if pending.walk else pending.work
                self._pending_attention_meters[row].require('anticipation', spent)
            finally:
                self._anticipating_expectation_row = None
                self._anticipatory_choices = []
                self._end_finished_selected_thought_episodes()

    def _expectation_policy_loss(self):
        """Residual REINFORCE with an independent EMA return baseline.

        Replay frozen candidate features through the current single chooser.
        A detached, capped importance ratio accounts for a changed parameter
        version (cap 4); there is no backward through an old policy graph.
        Reward is minus all-role MSE/presence BCE and actual metered work.
        Gain, the object mask and reading attention are outside this estimator.
        """
        discourse = getattr(getattr(self, "symbolSpace", None), "expectation", None)
        if discourse is not None:
            from WalkTrials import observe_comparison
            for row, audit in discourse.consume_expectation_walk_outcomes():
                observe_comparison(self, 'think.anticipation', audit, row=row)
                self._last_anticipation_records = audit['records']
        outcomes = [] if discourse is None else discourse.consume_expectation_policy_outcomes()
        if not outcomes or getattr(self, "expectation_policy_weight", 0.) <= 0:
            return None
        baseline = self.__dict__.get("_expectation_policy_baseline", 0.)
        losses, returns, ratios = [], [], []
        for trajectory, residual_reward, spent in outcomes:
            reward = residual_reward - self.WHAT_STEP_COST * spent
            terms = []
            for width, contexts, concludes, index, old_log_prob in trajectory:
                chooser = self.selected_thought_choosers[str(width)]
                log_prob = chooser.logits(contexts, concludes).log_softmax(0)[index]
                ratio = (log_prob.detach() - old_log_prob).exp().clamp(max=4.)
                terms.append(-ratio * (reward - baseline) * log_prob)
                ratios.append(float(ratio))
            if terms:
                losses.append(torch.stack(terms).mean())
                returns.append(reward)
        if not losses:
            return None
        mean_return = sum(returns) / len(returns)
        self._expectation_policy_baseline = (.9 * baseline + .1 * mean_return
            if "_expectation_policy_baseline" in self.__dict__ else mean_return)
        self._expectation_policy_report = dict(episodes=len(returns), choices=len(ratios),
            mean_return=mean_return, return_variance=sum((r - mean_return) ** 2 for r in returns) / len(returns),
            mean_importance=sum(ratios) / len(ratios))
        return torch.stack(losses).mean()

    def _selected_thought_policy_loss(self, answer_loss, mask=None):
        """REINFORCE credit for hard normal-controller query/finish choices.

        The only scalar reward is the later answer loss, less a small charge
        for actual metered work, including child execution and reads.
        No desired answer or oracle subgoal
        enters the chooser context; hard query results remain nondifferentiable.
        """
        episodes = {}
        for record in self.__dict__.get("_selected_thought_policy_records") or ():
            if len(record) != 4:
                continue  # no credit without a completed episode's actual meter
            row, log_prob, episode, spent = record
            if not (torch.is_tensor(log_prob) and log_prob.requires_grad):
                continue
            if mask is not None and not (
                    0 <= row < mask.numel() and bool(mask.reshape(-1)[row])):
                continue
            episodes.setdefault((row, episode, spent), []).append(log_prob)
        if not episodes:
            return None
        losses, rewards, choices = [], [], 0
        baseline = self.__dict__.get("_selected_thought_policy_baseline")
        for (row, _episode, spent), log_probs in episodes.items():
            if torch.is_tensor(answer_loss):
                values = answer_loss.detach().reshape(-1)
                answer = float(values[0] if values.numel() == 1 else values[row])
            else:
                answer = float(answer_loss or 0.0)
            reward = -answer - self.WHAT_STEP_COST * spent
            advantage = reward - (baseline if baseline is not None else 0.0)
            losses.append(-(advantage * torch.stack(log_probs)).mean())
            rewards.append(reward)
            choices += len(log_probs)
        reward = sum(rewards) / len(rewards)
        self._selected_thought_policy_baseline = (
            reward if baseline is None else 0.9 * baseline + 0.1 * reward)
        loss = torch.stack(losses).mean()
        report = self._what_report_state()
        for key, value in (("credit_sum", float(loss.detach())),
                           ("return_sum", reward), ("batches", 1),
                           ("choices", choices)):
            name = "policy_selected_thought_" + key
            report[name] = report.get(name, 0) + value
        return loss

    def _selected_thought_answer_errors(self, prediction, target, mask, questions, *, surface=False):
        """Row-local, detached answer rewards after the answer has been fixed."""
        if not (self.__dict__.get("_selected_thought_policy_records")
                and bool(getattr(self.inputSpace.data, "has_supervised_outputs", False))):
            return None
        questions = question_batch(questions)
        eligible = torch.tensor([
            question.relation is WhatRelation.SUPERVISED for question in questions],
            device=prediction.device, dtype=torch.bool)
        if mask is not None:
            eligible = eligible & mask.to(eligible).reshape(-1)
        errors = prediction.new_zeros(len(questions))
        with torch.no_grad():
            for row in eligible.nonzero().reshape(-1).tolist():
                pred, gold = prediction[row:row + 1].detach(), target[row:row + 1].detach()
                errors[row] = (self._reverse_event_loss(pred, gold) if surface
                               else self.loss.compute(pred, gold))
        return errors, eligible

    def _selected_thought_memory(self, active, *, row, work):
        """Bounded attended STM/discourse and what-retrieved frames on one meter.

        Ordinary thought history is row-owned. The durable read admits shared
        facts and this row's held occurrence references, never another row's
        observations, estimates or private questions. No global recency reader
        is used (its legacy API ignores the row). A small budget may reserve
        all remaining work for execution and expose an incomplete read.
        """
        from ThoughtFeatures import attend_meanings
        if work is None:
            return (attend_meanings(active, ()),) * 2
        self._assert_query_boundary(row)
        limit = min(4, work.remaining // 16)
        memory = self._what_memory()
        short, long = [], []
        anticipating = getattr(self, "_anticipating_expectation_row", None) == row
        stm = None if anticipating else getattr(getattr(self, "conceptualSpace", None), "stm", None)
        buffer, depth = getattr(stm, "_buffer", None), getattr(stm, "_depth", None)
        if (limit and torch.is_tensor(buffer) and torch.is_tensor(depth)
                and row < len(depth) and buffer.shape[-1] == active.roles.shape[-1]):
            for slot in range(min(limit // 2, int(depth[row]))):
                if not work.consume("context_record"):
                    break
                value = ConceptualMeaning.from_description(buffer[row, slot].detach())
                short.append((value, 0.))
        carrier = getattr(getattr(self, "conceptualSpace", None), "subspace", None)
        knowing = None if anticipating else getattr(carrier, '_concept_activations', None)
        if limit and torch.is_tensor(knowing) and row < knowing.shape[1] and work.consume('context_record'):
            from Queries import _basis
            basis = getattr(carrier, '_concept_codes', None)
            if basis is None:
                basis = _basis(self.conceptualSpace)
            basis = basis.detach()
            if basis.ndim == 3:
                basis = basis[row]
            n = min(len(knowing), len(basis))
            from ConceptEvidence import symbols
            pair = symbols(knowing[:n])[:, row].detach()
            # Serial retrieval receives each pole separately; the parallel
            # field remains a pair even when a signed idea is requested.
            for polarity in range(2):
                weights = pair[:, polarity]
                if bool(weights.any()):
                    idea = (weights[:, None] * basis[:n]).sum(0) / weights.sum().clamp_min(1.)
                    short.append((ConceptualMeaning.from_description(
                        idea if polarity == 0 else -idea), 0.))
        history = memory.thought_window(b=row, limit=limit - len(short)) if limit and not anticipating else ()
        for record in history:
            if not work.consume("context_record"):
                break
            if record.meaning is not None:
                short.append((record.meaning, record.support_true - record.support_false))
        discourse = getattr(getattr(self, "symbolSpace", None), "expectation", None)
        chains = getattr(discourse, "_inter_context", ())
        if limit and row < len(chains):
            for depth, payload, mask in list(chains[row])[-limit:]:
                if not work.consume("context_record"):
                    break
                if payload.shape == active.roles.shape and torch.is_tensor(mask):
                    value = ConceptualMeaning(payload, mask, mode='unspecified')
                else:
                    value = ConceptualMeaning.from_payload(payload, depth=depth, layout='stm')
                short.append((value, 0.))
        frames = memory.retrieved_frames(b=row, limit=limit) if limit else ()
        for frame in frames:
            if not work.consume("context_record"):
                break
            long.append((frame['meaning'], float(frame['trust'])))
        reader = getattr(self, 'answer_attention', None)
        return (attend_meanings(active, short, incomplete=not limit,
                    reader=reader, work=work, space_id=PrimedSymbolReader.SPACE_STM),
                attend_meanings(active, long, incomplete=not limit,
                    reader=reader, work=work, space_id=PrimedSymbolReader.SPACE_LTM))

    def _choose_selected_thought_action(self, root, active, actions, *, row,
                                        level, pressure, evidence=None, work=None):
        """Choose a catalog operation or the non-semantic conclude transition.

        ``actions`` is a tuple of grammar-derived ``ThoughtOperationCandidate``
        instances, plus ``None`` only for conclude.  The operation's complete
        request is the learned candidate representation; its name and catalog
        position remain dispatch metadata outside the policy tensor.
        """
        from Queries import ThoughtOperationCandidate

        actions = tuple(actions)
        if not actions:
            raise ValueError("selected thought action requires a legal candidate")
        if any(action is not None and not isinstance(
                action, ThoughtOperationCandidate) for action in actions):
            raise TypeError("selected thought action must be a grammar candidate or conclude")
        current = active
        memory_context = self._selected_thought_memory(active, row=row, work=work)
        expectation_context = self._selected_thought_expectation(active, row=row, work=work)
        contexts = tuple(self._selected_thought_context(
            root, active,
            (current if action is None else action.request),
            level=level, pressure=pressure, evidence=evidence,
            memory_context=memory_context, expectation_context=expectation_context)
            for action in actions)
        context = torch.stack(contexts)
        chooser = self._selected_thought_chooser(
            current, device=context.device, dtype=context.dtype)
        anticipating = getattr(self, "_anticipating_expectation_row", None) == row
        weight = getattr(self, "expectation_policy_weight" if anticipating else "selected_thought_policy_weight", 0.)
        concludes = tuple(action is None for action in actions)
        from GrammarPreference import operator_is_structural
        registry = _boundary_registry(self)
        structural = tuple(action is None or operator_is_structural(
            registry.descriptors[action.semantic_id]) for action in actions)
        walk=getattr(self,'_thought_walk',None)
        choice={}
        if walk is not None:
            step=len(walk['actions'])
            exploit=walk['exploit']
            if exploit is not None and step<len(exploit):
                if step<walk['departure']:choice['forced']=exploit[step]
                elif step==walk['departure']:choice['excluded']=exploit[step]
        index, log_prob = chooser.choose(context, concludes,structural=structural,
            sample=bool(anticipating and self._anticipation_training and weight>0. and walk is None),**choice)
        if walk is not None:
            walk['actions'].append(index)
            walk['eligible'].append(len(actions)>1)
        if anticipating and weight > 0.:
            # Keep data, not an autograd graph across the arriving input or
            # an optimizer step. Credit replays this same chooser on this view.
            self._anticipatory_choices.append((int(root.roles.shape[-1]),
                context.detach().clone(), concludes, index, float(log_prob.detach())))
        elif float(getattr(self, "selected_thought_policy_weight", 0.0) or 0.0) > 0.0:
            self.__dict__.setdefault("_selected_thought_policy_records", []).append(
                (int(row), log_prob))
        return actions[index]

    def run_selected_thought(self, meaning, *, row=0, work_budget=32,
                             registry=None, work=None, score=None):
        """Run the ordinary controller, comparing complete training trials."""
        self._last_thought_comparison=None
        if score is not None and self.training and torch.is_grad_enabled():
            self._assert_query_boundary(row)
            # Binding a supplied constituent is part of query admission, not
            # a trial effect; both paths read this same owned occurrence.
            if meaning.constituents:
                store=getattr(self.symbolSpace,'ltm_store',None)
                if store is None:raise RuntimeError('selected nested thought requires its occurrence owner')
                meaning=store.bind_constituents(meaning,stream=row)
                if meaning is None:raise RuntimeError('selected nested thought exhausted occurrence capacity')
            from WalkTrials import thought_pair
            return thought_pair(self,meaning,row=row,work_budget=work_budget,
                registry=registry,work=work,score=score)
        return self._run_selected_thought_once(meaning,row=row,work_budget=work_budget,registry=registry,work=work)

    def _run_selected_thought_once(self, meaning, *, row=0, work_budget=32,
                                  registry=None, work=None):
        """Execute one completed grammatical question as an ordinary episode.

        Composition only supplies ``meaning``.  This method is deliberately
        boundary-only: it creates the *one* transient query meter for the
        episode, records each selected operation in the existing interaction
        history, and delegates checked reads/effects to the registered VP.
        A ``what(Q)`` executor receives the same meter and may enter a nested
        ordinary context; it never starts a child budget, a new owner, or a
        second optimizer episode.

        The hard operation sequence is a small safe baseline: execute the
        selected VP and conclude, with ``what(Q)`` supplying its explicit
        subordinate meaning.  Its return value preserves actual support and
        occurrence provenance for the later learned controller/output path;
        it does not turn a question into an accepted fact.
        """
        if not isinstance(meaning, ConceptualMeaning):
            raise TypeError("selected thought requires a complete ConceptualMeaning")
        if meaning.mode != "interrogative":
            raise ValueError("selected thought requires an interrogative meaning")
        if type(row) is not int or row < 0:
            raise ValueError("selected thought row must be a non-negative integer")
        if type(work_budget) is not int or work_budget < 0:
            raise ValueError("selected thought work_budget must be a non-negative integer")
        # This is intentionally before any registry/native/occurrence read.
        self._assert_query_boundary(row)
        registry = registry or _boundary_registry(self)
        if not isinstance(registry, GrammaticalThoughtRegistry):
            raise RuntimeError("selected thought has no installed grammatical thought registry")
        if meaning.constituents:
            store = getattr(getattr(self, "symbolSpace", None), "ltm_store", None)
            if store is None:
                raise RuntimeError("selected nested thought requires its occurrence owner")
            meaning = store.bind_constituents(meaning, stream=row)
            if meaning is None:
                raise RuntimeError("selected nested thought exhausted occurrence capacity")
        # Reject a non-executable VP before opening an episode that could not
        # truthfully be completed.  ``signature_for`` only validates the
        # frozen setup binding; all selected reads below share ``meter``.
        registry.signature_for(meaning)
        memory = self._what_memory()
        if memory is None or not all(hasattr(memory, name) for name in (
                "begin_thought_episode", "commit_thought", "descend_thought",
                "return_thought", "finish_thought", "thought_state",
                "thought_history", "thought_reference")):
            raise RuntimeError("selected thought requires the interaction memory owner")

        policy_start = len(self.__dict__.get("_selected_thought_policy_records") or ())
        meter = QueryWorkBudget(work_budget) if work is None else work
        initial_spend = meter.spent
        root = memory.begin_thought_episode(meaning, b=row, work_budget=meter.remaining)
        episode = root.episode
        recorded_spend = initial_spend

        def reference(record):
            return memory.thought_reference(record, b=row)

        def support(value):
            value = 0.0 if value is None else value
            if torch.is_tensor(value):
                value = value.detach().item()
            value = float(value)
            if not math.isfinite(value) or not 0.0 <= value <= 1.0:
                raise ValueError("selected evidence support must be in [0, 1]")
            return value

        def normalized(result, *, fallback_kind="unverified"):
            """Keep executor evidence explicit without treating it as a fact."""
            checked = result if isinstance(result, ThoughtResult) else None
            if checked is not None:
                result = dict(checked.evidence)
            result = dict(result or {})
            evidence = result.get("evidence")
            if isinstance(evidence, dict):
                source = evidence
            else:
                source = result
            return {
                "support_true": support(source.get("support_true", 0.0)),
                "support_false": support(source.get("support_false", 0.0)),
                "evidence_kind": str(result.get(
                    "evidence_kind", source.get("evidence_kind", fallback_kind))),
                "semantic_id": result.get(
                    "semantic_id", None if checked is None else checked.semantic_id),
                "result_kind": result.get(
                    "result_kind", None if checked is None else checked.result_kind),
                "query_signature": result.get("query_signature"),
                "incomplete": tuple(result.get("incomplete", ()) or ()),
            }, checked

        def refs(current, *extra):
            """Record typed provenance; numeric concept IDs are never features."""
            return tuple(reference for reference in current.role_refs
                         if reference is not None) + tuple(
                             reference for reference in extra if reference is not None)

        def event(kind, current, evidence, *, operation, sources=(), result=None):
            """Commit exactly the meter delta since the preceding record.

            The existing history owner receives the detached typed result from
            an actual checked execution.  Summary evidence remains useful to
            the chooser, but it cannot stand in for a prediction, set, code,
            or subgoal result during replay.
            """
            nonlocal recorded_spend
            state = memory.thought_state(b=row)
            if state is None or state.finished:
                raise RuntimeError("selected thought lost its active episode")
            delta = meter.spent - recorded_spend
            if state.forced:
                # A prior event consumed the final unit and atomically added
                # the cutoff.  Drain events are intentionally query-free and
                # cost zero in the history and meter.
                delta = 0
            elif delta < 1:
                raise RuntimeError("ordinary selected thought event has no charged work")
            keyword = dict(
                b=row,
                work=delta if delta else 1,
                support_true=evidence["support_true"],
                support_false=evidence["support_false"],
                evidence_kind=evidence["evidence_kind"],
                sources=tuple(sources),
            )
            if kind == "thought":
                record = memory.commit_thought(
                    current, operation=operation, result=result, **keyword)
            elif kind == "descend":
                record = memory.descend_thought(current, **keyword)
            elif kind == "return":
                record = memory.return_thought(current, result=result, **keyword)
            elif kind == "finish":
                record = memory.finish_thought(current, result=result, **keyword)
            else:  # pragma: no cover - private controller invariant
                raise AssertionError(f"unknown selected thought event {kind!r}")
            recorded_spend = meter.spent
            return record

        def exhausted(current):
            outcome = {
                "meaning": current,
                "evidence": {
                    "support_true": 0.0,
                    "support_false": 0.0,
                    "evidence_kind": "subgoal",
                    "query_signature": None,
                    "incomplete": ("work_budget",),
                },
                "result": None,
                "record": None,
            }
            state = memory.thought_state(b=row)
            if state is not None and not state.forced and meter.spent > recorded_spend:
                # Context reads can spend the last unit before any executor
                # runs. Record that already-paid work, inducing the ordinary
                # cutoff; the subsequent return/finish drain costs nothing.
                outcome["record"] = event("thought", current, outcome["evidence"],
                    operation="conclude", sources=refs(current))
            return outcome

        def candidates(current, state):
            # Each context's begin/descent record already owns its question.
            # A grammar what alternative refers to that occurrence directly.
            initiating = next(record for record in reversed(memory.thought_history(b=row))
                              if record.episode == episode and record.level == state.level
                              and record.kind in ("begin", "descend"))
            return registry.controller_candidates(
                meaning, state.contexts[-1].meaning, current,
                descriptions=((state.contexts[-1].initial, reference(initiating)),))

        unselected = object()

        def execute(current, *, actions=None, evidence_context=None,
                    action=unselected):
            """Run one selected VP; nested ``what`` uses this same closure.

            The controller chooses an action from the actual root/active/
            candidate schema.  A post-result choice may pass a previously
            formed catalog action after scoring it against actual evidence, so
            a repeated operation is a real, bounded second decision rather
            than an untracked loop.
            """
            nonlocal recorded_spend
            state = memory.thought_state(b=row)
            if state is None or state.forced:
                return exhausted(current)
            if actions is None:
                actions = tuple(candidates(current, state)) + (None,)
            else:
                actions = tuple(actions)
            if action is unselected:
                action = self._choose_selected_thought_action(
                    meaning, state.contexts[-1].meaning, actions, row=row,
                    level=state.level, pressure=state.pressure,
                    evidence=evidence_context, work=meter)
            elif action not in actions:
                raise ValueError("selected thought chose an unavailable action")
            if action is None:
                if not meter.consume("controller"):
                    return exhausted(current)
                evidence = {
                    "support_true": 0.0,
                    "support_false": 0.0,
                    "evidence_kind": "unverified",
                    "query_signature": None,
                    "incomplete": ("controller_finish",),
                }
                record = event("thought", current, evidence, operation="conclude",
                               sources=refs(current))
                return {"meaning": current, "evidence": evidence,
                        "result": None, "record": record}
            selected = action
            current = selected.request
            # Choosing a checked operation is ordinary controller work in
            # addition to the registered VP/read work below.  This is paid
            # before the executor can inspect a native reference or evidence.
            if not meter.consume("controller"):
                return exhausted(current)
            child_result = None
            parent_record = None
            child_return = None

            def schedule_subgoal(child):
                """The checked ``what(Q)`` callback: descend/return in order."""
                nonlocal child_result, parent_record, child_return
                if not isinstance(child, ConceptualMeaning):
                    raise TypeError("what(Q) supplied no complete grammatical subgoal")
                # ``what`` has already paid for its own VP/read/operation.
                parent_record = event(
                    "thought", current,
                    {"support_true": 0.0, "support_false": 0.0,
                     "evidence_kind": "subgoal", "query_signature": "what",
                     "incomplete": ()},
                    operation=selected.semantic_id, sources=refs(current))
                if memory.thought_state(b=row).forced:
                    return None
                if not meter.consume("controller"):
                    return None
                descent = event(
                    "descend", child,
                    {"support_true": 0.0, "support_false": 0.0,
                     "evidence_kind": "subgoal", "query_signature": "what",
                     "incomplete": ()},
                    operation="descend",
                    sources=refs(child, reference(parent_record)))
                child_result = run_context(child)
                child_record = child_result.get("record")
                state_after_child = memory.thought_state(b=row)
                if state_after_child is None:
                    raise RuntimeError("selected child lost its thought history")
                if not state_after_child.forced:
                    if not meter.consume("controller"):
                        return child_result.get("result")
                child_return = event(
                    "return", child_result["meaning"], child_result["evidence"],
                    operation="return",
                    sources=refs(current, reference(descent),
                                 (reference(child_record)
                                  if child_record is not None else None)),
                    result=child_result.get("result"))
                return child_result.get("result")

            try:
                # Each selected request is a completed thought boundary;
                # nested permission remains a narrowing of the parent's row.
                with self._query_boundary_scope((row,)):
                    context = self._thought_grammar_context(
                        current, row=row, work=meter, continuation=schedule_subgoal)
                    raw = registry.execute(current, context)
                    from AccessibleMind import apply_thought_effect
                    apply_thought_effect(self, raw, row=row, work=meter)
            except Exception:
                # Do not leave an active live episode behind if a checked
                # executor rejects malformed runtime evidence.  The original
                # error still propagates; this only preserves owner invariants.
                state = memory.thought_state(b=row)
                if state is not None and not state.forced:
                    memory.cutoff_thought(b=row, reason="query_error")
                state = memory.thought_state(b=row)
                if state is not None and not state.finished:
                    while memory.thought_state(b=row).level:
                        memory.return_thought(current, b=row)
                    memory.finish_thought(current, b=row)
                raise
            evidence, checked = normalized(raw)
            if (parent_record is not None and child_result is None
                    and memory.thought_state(b=row).forced):
                # what already recorded its parent and exhausted the meter
                # before a child could begin. Only the existing finish drain
                # is legal; never append another ordinary thought at cutoff.
                evidence = dict(evidence, incomplete=tuple(dict.fromkeys(
                    (*evidence['incomplete'], 'work_budget'))))
                return {'meaning': current, 'evidence': evidence,
                        'result': checked, 'record': parent_record}
            if child_result is not None:
                # A ``what`` result is the child result, not a new proposition
                # established by the outer question.  The parent return and
                # root finish retain this causal evidence explicitly.
                evidence = dict(child_result["evidence"])
                evidence["query_signature"] = "what"
                if parent_record is None:  # pragma: no cover - callback invariant
                    raise RuntimeError("selected what query omitted its parent record")
                return {"meaning": current, "evidence": evidence,
                        "result": checked, "record": child_return or parent_record}
            record = event("thought", current, evidence,
                           operation=selected.semantic_id,
                           sources=refs(current), result=checked)
            return {"meaning": current, "evidence": evidence,
                    "result": checked, "record": record}

        def run_context(current):
            """Use the same recurrent choice loop at every execution level."""
            outcome = execute(current)
            # A completed result is available to a second hard choice at the
            # same root level.  The safe zero-initialised ordering puts the
            # non-semantic conclusion first after actual evidence exists;
            # exploratory policy sampling may select any newly compatible
            # grammar operation, each charged and recorded on this one owner.
            while outcome["record"] is not None:
                state = memory.thought_state(b=row)
                if state is None or state.forced:
                    break
                actions = (None,) + tuple(candidates(outcome["meaning"], state))
                action = self._choose_selected_thought_action(
                    meaning, state.contexts[-1].meaning, actions,
                    row=row, level=state.level, pressure=state.pressure,
                    evidence=outcome["evidence"], work=meter)
                if action is None:
                    # This is the required concluding ordinary thought before
                    # the separate root-finish transition.  At cutoff only
                    # the bounded finish drain is legal, so do not invent a
                    # same-level event when the charge cannot be reserved.
                    if meter.consume("controller"):
                        conclusion = event(
                            "thought", outcome["meaning"], outcome["evidence"],
                            operation="conclude",
                            sources=refs(
                                outcome["meaning"],
                                reference(outcome["record"])))
                        outcome = dict(outcome, record=conclusion)
                    else:
                        outcome = exhausted(outcome["meaning"])
                    break
                outcome = execute(outcome["meaning"], actions=(action,),
                                  evidence_context=outcome["evidence"],
                                  action=action)
            return outcome

        try:
            outcome = run_context(meaning)
            state = memory.thought_state(b=row)
            if state is None:
                raise RuntimeError("selected thought has no replayable state")
            if not state.forced:
                if not meter.consume("controller"):
                    raise RuntimeError("selected controller could not reserve finish work")
            finish = event("finish", outcome["meaning"], outcome["evidence"],
                           operation="finish",
                           sources=refs(meaning, reference(outcome["record"])
                                        if outcome["record"] is not None else None),
                           result=outcome.get("result"))
        except Exception:
            # ``execute`` already drains checked-executor failures.  For an
            # unexpected controller failure, retain no unfinished episode.
            state = memory.thought_state(b=row)
            if state is not None and not state.finished:
                if not state.forced:
                    memory.cutoff_thought(b=row, reason="controller_error")
                while memory.thought_state(b=row).level:
                    memory.return_thought(meaning, b=row)
                memory.finish_thought(meaning, b=row)
            policy = self.__dict__.get("_selected_thought_policy_records")
            if policy is not None:
                del policy[policy_start:]
            raise
        records = tuple(record for record in memory.thought_history(b=row)
                        if record.episode == episode)
        if not records or records[-1] is not finish:
            raise RuntimeError("selected thought did not finish its owned episode")
        if meter.spent - initial_spend != memory.thought_state(b=row).work_spent:
            raise RuntimeError("selected thought meter and history disagree")
        policy = self.__dict__.get("_selected_thought_policy_records")
        if policy is not None:
            policy[policy_start:] = [
                (item[0], item[1], episode, meter.spent)
                for item in policy[policy_start:]]
        return SelectedThoughtResult(
            outcome["meaning"], dict(outcome["evidence"]), meter, records,
            outcome.get("result"))

    def _run_selected_sentence_thoughts(self, fields, *, work_budget=32, score=None):
        """Execute the typed questions fixed while their readings were open."""
        if type(work_budget) is not int or work_budget < 0:
            raise ValueError('selected sentence work_budget must be a non-negative integer')
        registry = _boundary_registry(self)
        if registry is None:
            return ()
        return tuple((row, self.run_selected_thought(field.query, row=row,
                      work_budget=work_budget, registry=registry,
                      score=(None if score is None else lambda result,row=row:score(row,result)),
                      work=(self._attention_meters[row] if row < len(getattr(self, "_attention_meters", ())) else None)))
                     for row, field in enumerate(fields)
                     if field is not None and field.query is not None)

    def _end_finished_selected_thought_episodes(self):
        """Close detached eval credit for ordinary completed episodes only.

        Training retains the live episode through its one optimizer step and
        uses :meth:`_end_what_episodes` afterward.  A standalone/evaluation
        ``resolveAnswer`` has no such step; leaving its finished owner live
        would block the next completed sentence and retain a stale graph.
        Legacy parity episodes have no :class:`ThoughtState` and are left to
        their existing caller-owned lifecycle.
        """
        memory = self._what_memory()
        if memory is None or not all(hasattr(memory, name) for name in (
                "in_episode", "thought_state", "end_what_episode")):
            return ()
        rows = []
        for row in range(int(getattr(memory, "batch", 0) or 0)):
            if not memory.in_episode(row):
                continue
            state = memory.thought_state(b=row)
            if state is not None and state.finished:
                memory.end_what_episode(row)
                rows.append(row)
        if rows:
            completed = set(rows)
            records = self.__dict__.get("_selected_thought_policy_records") or ()
            self._selected_thought_policy_records = [
                record for record in records if record[0] not in completed]
        return tuple(rows)

    def create_from_config(self, config_path=None, model_type=None, data=None):
        """Delegate XML-driven construction to BaseModel.

        Thin override that exists only to ensure the BasicModel
        instance handles the call (subclass dispatch); the actual
        construction logic lives in ``BaseModel.create_from_config``.
        """
        return super().create_from_config(config_path, model_type=model_type, data=data)

    def create(self, nInput, nPercepts, nConcepts, nSymbols, nWords=16, nOutput=32,
               bindingDepth=1,
               model_type="numeric", data=None,
               reconstruction_scale=0.5, what_scale=0.7, where_scale=0.2, when_scale=0.1):
        """Build the full space hierarchy from architecture parameters.

        Always dispatches to ``_create_per_stage``: per-stage with
        T=bindingDepth is the single construction path. At T=1 it
        reduces to a single ConceptualSpace + WholeSpace stage,
        producing the same observable output as the legacy flat path.

        Args:
            nInput/nPercepts/nConcepts/nSymbols/nOutput: object counts per space.
            nWords: object count for the SyntacticSpace.
            bindingDepth: number of [Percept->Concept->Symbol] cycles.
            model_type: the data space_role -- "embedding" (text/LM) or "numeric"
                (dense slab). Was the architecture-level modelType.
        """
        return self._create_per_stage(
            nInput, nPercepts, nConcepts, nSymbols, nWords=nWords,
            nOutput=nOutput, bindingDepth=bindingDepth,
            model_type=model_type, data=data,
            reconstruction_scale=reconstruction_scale, what_scale=what_scale,
            where_scale=where_scale, when_scale=when_scale)

    def _make_input_space(self, rawInputShape, spaceShape, inputShape, model_type):
        return InputSpace(rawInputShape, spaceShape, inputShape, model_type=model_type)

    def _make_perceptual_space(self, inputShape, spaceShape, outputShape):
        try:
            demuxed = TheXMLConfig.space("InputSpace", "demuxed")
        except KeyError:
            demuxed = False
        if demuxed:
            return ModalSpace(inputShape, spaceShape, outputShape)
        return PartSpace(inputShape, spaceShape, outputShape)

    def build_pipelines(self):
        """Phase 2: assemble stem/body/head pipelines.

        Always dispatches to ``_build_pipelines_per_stage`` (the
        single per-stage construction path).
        """
        return self._build_pipelines_per_stage()

    # -- Per-stage helpers ---------------------------------------------
    # Pair-merge primitives that previously lived here
    # (``_pair_merge`` / ``_pair_unmerge``) were retired 2026-05-14
    # alongside the reverse pipeline; ``GrammarMergeGlue.forward`` and
    # ``.reverse`` (top of file) carry the live merge/unmerge math.


    def _bound_concept_input(self, x):
        """Keep recurrent concept inputs inside ConceptualSpace's logit domain."""
        if getattr(self.conceptualSpace, "nonlinear", False):
            return x.clamp(min=-1 + epsilon, max=1 - epsilon)
        return x

    def _has_word_objects(self):
        """An identified native word enables grammar between its brackets.

        Primitive-only named-pole lessons read the field directly. A TruthSet
        needs completed grammatical rows even with one native concept layer.
        This is a carrier contract, not a selectable traversal schedule.
        """
        if TheXMLConfig.space('OutputSpace','conceptIds',default=''):
            return False
        if self._derive_use_grammar() == 'none':
            return bool(TheXMLConfig.get('architecture.ltmConsolidation',default=False))
        return (int(TheXMLConfig.get('architecture.conceptLayers',default=1)) > 1
                or bool(TheXMLConfig.get('architecture.ltmConsolidation',default=False)))

    def _derive_use_grammar(self):
        """Derive ``useGrammar`` from the configured grammar rules.

        Returns ``"all"`` when the grammar contains any non-default
        rule (anything beyond unary ``pi`` / ``sigma`` substrate
        folds), else ``"none"``. Replaces the retired
        ``<SymbolSpace><useGrammar>`` XML knob — the grammar XML itself
        is now the sole source of truth for whether the chart fires
        and whether per-stage merge glue is wired.
        """
        try:
            from Language import TheGrammar
            TheGrammar._ensure_configured()
            for rule in getattr(TheGrammar, 'rules', []) or []:
                mn = getattr(rule, 'method_name', None)
                arity = int(getattr(rule, 'arity', 1) or 1)
                if mn is None or 'field' in rule.operand_kinds:
                    continue
                if mn in ('pi', 'sigma') and arity == 1:
                    continue
                return "all"
        except Exception:
            pass
        return "none"

    def End(self):
        """Per-batch teardown. Cascades End() to every Space.

        Released after forward + reverse + loss have consumed the cached
        state. Called from runBatch.
        """
        for space in self.spaces:
            if hasattr(space, 'End'):
                space.End()

    def Finish(self, symbols):
        """Project concatenated symbols to task output via OutputSpace.

        Output-range denormalization happens here (not in OutputSpace.forward)
        so the space pipeline stays global-data-free.
        """
        if isinstance(symbols, torch.Tensor):
            self.outputSpace.commit_event(symbols)
            symbols = self.outputSpace.subspace
        # Phase 1.5: ``self.outputs`` was the subsumed back-ref alias
        # name; this Finish-local produce-then-materialize is the only
        # writer/reader, so keep it as a local (no ``self`` attribute,
        # behaviour identical).
        outputs = self.outputSpace.forward(symbols)
        if self.outputSpace.nonlinear_output:
            outputData = outputs.materialize(mode="activation")
        else:
            outputData = outputs.materialize()
        outputData = self.normalizer.denormalize(outputData, which="output")
        if self.plot:
            TheReport.plotActivations(figure=1, symbols=symbols)
        return outputData
    def set_reading(self, desire=True, valence=1.0):
        """READING mode (Architecture sec C, simplified law): desire (or,
        with valence < 0, hate) the frozen hard-coded 'reading' concept;
        while on, each batch's staged word-whole rows are desired too --
        the hard-coded concept -> word-isolating-wholes wiring. The
        surface's seen-decay fades it after set_reading(False)."""
        cs0 = (self.conceptualSpaces[0]
               if getattr(self, 'conceptualSpaces', None) else None)
        if not desire:
            object.__setattr__(self, "_reading_desire", None)
            return None
        v = float(valence)
        object.__setattr__(self, "_reading_desire", v)
        if cs0 is None or not cs0._sparse_active():
            return None
        cid = getattr(self, "_reading_cid", None)
        if cid is None:
            cid = cs0.mint_frozen_concept("reading")
            object.__setattr__(self, "_reading_cid", cid)
        row = cs0._csw_row_of(cid)
        if row is not None:
            cs0.prime_desire(torch.tensor([int(row)]), valence=v)
        return cid

    @torch.no_grad()
    def _assemble_relevance_priority(self, cut_cs, stage, last_cs, settled):
        """The simplified relevance law (Architecture sec C): ONE quadratic
        priming surface per space -- SEEN rows primed by being perceived,
        DESIRED/HATED rows by signed intent. The CS surface projects
        directly onto the pyramid's inventory rows as the ranking score
        (boost - 1: neutral 0, desire positive, hate negative). Pure READ:
        the SEEN/DESIRE writes live in ``_prime_seen_step`` (unconditional,
        both paths, once per batch)."""
        b = cut_cs.priming_weights()
        if b is None:
            return None
        return (b - 1.0).transpose(0, 1)               # [N, 1] signed score

    @torch.no_grad()
    def _prime_seen_step(self):
        """UNCONDITIONAL SEEN priming (Alec 2026-07-12): perception itself
        primes -- once per batch, on both paths, no ``<relevance>`` gate.
        WS: each stage's unity selections (the serial path stamps the
        terminal, the parallel pump stage 0); while READING is desired the
        same rows are desired too (the span -> slot -> row chain IS the
        projection). CS: the pyramid's admitted rows. Consumers stay put
        (the pyramid priority read; the <relevance>-gated reading scope)."""
        _rd = getattr(self, "_reading_desire", None)
        # Canonical-only WS write: rows must index the canonical (terminal)
        # codebook, and the terminal stamps its OWN unity selections on
        # both paths (per-stage on parallel, terminal-only on serial) --
        # the other stages' stamps are private-quantizer rows and dropped.
        _ws_list = getattr(self, "wholeSpaces", None) or []
        ws_c = _ws_list[-1] if len(_ws_list) else None
        if ws_c is not None:
            idx = getattr(ws_c, "_stage0_indices", None)
            if torch.is_tensor(idx):
                ws_c.prime_seen(idx)
                if _rd is not None:
                    ws_c.prime_desire(idx, valence=float(_rd))
        cs0 = self._concept_owner()
        rows = (getattr(cs0, "_cs_level_rows", None)
                if cs0 is not None else None)
        if rows and not getattr(self, '_sentence_priming_written', False):
            packed = torch.cat(rows)
            binding = cs0._field_inventory_rows(packed.device)
            addresses = binding.gather(0, packed) if binding.ndim == 2 else binding[packed]
            cs0.prime_seen(addresses.transpose(0, 1) if addresses.ndim == 2 else addresses[None])
        # CS->PS / CS->WS heat projection (Alec 2026-07-12): the diffused
        # concept heat lands on the word triples' PS pids (primed
        # RECOGNITION) and word-whole WS rows (primed RETRIEVAL -- the
        # surface the reading scope reads). Terminal WS: the relation
        # store's pos->row tables live there (== stage 0 on sO=0 configs).
        if cs0 is not None:
            cs0.project_priming_to_towers(
                getattr(self, "perceptualSpace", None),
                (self.wholeSpaces[-1]
                 if getattr(self, "wholeSpaces", None) else None),
                gain=self.priming_spread)

    def _prime_sentence_symbols(self, sid):
        """Snapshot per-stream seen symbols before either trial is composed."""
        from SentenceUnderstanding import PrimedSymbols
        isp, owner = self.inputSpace, self._concept_owner()
        rows = getattr(isp, '_ar_concept_lookup_rows', None)
        owners = getattr(isp, '_ar_concept_lookup_sentence_ids', None)
        if not torch.is_tensor(rows) or not torch.is_tensor(owners):
            self._sentence_primed_bank = None
            return
        own_rows = torch.where((owners == sid) & (rows >= 0), rows, -1)
        present = isp._packed_sentence_slot_mask[:, sid].bool()
        # Repeated occurrences of one word prime its row once per sentence.
        own_lists = [torch.unique(row[row >= 0]) for row in own_rows]
        own_width = max(1, max(row.numel() for row in own_lists))
        seen = rows.new_full((rows.shape[0], own_width), -1)
        for b, row in enumerate(own_lists):
            seen[b, :row.numel()] = row
        heat = owner.prime_seen(seen, active_rows=present)
        if heat is None:
            raise RuntimeError('a reconstruction bank requires its concept priming surface')
        limit = int(self.reconstruction_basis_limit)
        width = own_width + min(limit, heat.shape[1])
        selected = rows.new_full((rows.shape[0], max(1, width)), -1)
        own = torch.zeros_like(selected, dtype=torch.bool)
        for b, row in enumerate(own_lists):
            count = row.numel()
            selected[b, :count], own[b, :count] = row, True
            scores = heat[b].clone()
            scores[row] = -torch.inf
            scores = scores.masked_fill(scores <= 1, -torch.inf)
            k = min(limit, scores.numel())
            if k:
                values, extra = scores.topk(k, sorted=True)
                selected[b, own_width:own_width+k] = torch.where(torch.isfinite(values), extra, -1)
        valid = selected >= 0
        codes = owner.similarity_codebook.lookup_rows(selected.clamp_min(0)).clone()
        sparse_forms = torch.where(valid[..., None], codes, torch.zeros_like(codes)).detach().clone()
        codes = owner.interpret.binding_atoms(codes)
        codes = torch.where(valid[..., None], codes, torch.zeros_like(codes))
        weights = heat.gather(1, selected.clamp_min(0)).detach().clone()
        weights = torch.where(valid, weights, torch.zeros_like(weights))
        surfaces = [[owner.word_surface_for_row(row) if row >= 0 else None
                     for row in batch] for batch in selected.cpu().tolist()]
        identity = getattr(getattr(self.perceptualSpace, 'percept_store', None), 'identity', None)
        if identity is not None:
            checks = [dict(word=raw.decode('utf8', 'surrogateescape'),
                           error=int(identity.read(sparse_forms[b,j,:identity.width]) != raw))
                      for b,batch in enumerate(surfaces) for j,raw in enumerate(batch) if raw]
            self._last_rung0_identity_audit = dict(identified_words=len(checks),
                errors=sum(item['error'] for item in checks), rows=checks)
            if self._last_rung0_identity_audit['errors']:
                raise RuntimeError('rung-zero reconstruction identity audit failed')
        nbytes = max(1, max(len(value or b'') for batch in surfaces for value in batch)+1)
        data = torch.zeros(*selected.shape, nbytes, dtype=torch.long)
        byte_valid = torch.zeros_like(data, dtype=torch.bool)
        for b, batch in enumerate(surfaces):
            for j, raw in enumerate(batch):
                if raw:
                    data[b, j, :len(raw)] = torch.tensor(list(raw))
                    byte_valid[b, j, :len(raw)] = True
        case_bank = None
        if any(getattr(rule, 'case_head_role', 0) for rule in self.languageSpace._compose_binary_rules):
            from CaseSelection import stage_case_bank
            native = selected.new_tensor([[owner.concept_id_at_row(int(row)) or -1
                                            if row >= 0 else -1 for row in batch]
                                           for batch in selected.detach().cpu().tolist()])
            case_bank = stage_case_bank(owner, native, limit=self.reconstruction_basis_limit)
        self._sentence_primed_bank = PrimedSymbols(selected, codes, weights, own,
            data.to(rows.device), byte_valid.to(rows.device), case_bank,
            getattr(self, '_readback_percept_width', None), sparse_forms if identity is not None else None)
        self._sentence_priming_written = True

    def store_truths(self, entries, *, source_key='user-truths'):
        """Parse externally trusted user assertions through the clause closing."""
        truth_layer = getattr(self.symbolSpace, 'truth_layer', None) if self.symbolSpace is not None else None
        if truth_layer is None:
            return

        # 1. Filter entries with text and trust
        texts, trusts = [], []
        for entry in entries:
            text = entry.get('content', '')
            if not text or not text.strip():
                continue
            trust = entry.get('trust')
            if trust is None:
                continue
            texts.append(text)
            trusts.append(self._effective_incoming_trust(trust))
        if not texts:
            return

        ltm_store = getattr(self.symbolSpace, 'ltm_store', None)
        if ltm_store is None:
            raise RuntimeError('TruthSet ingestion requires the clause row store')
        self._store_truths_into_ltm(ltm_store, truth_layer, texts, trusts, source_key=source_key)

        # 5. Run the consistency report and cache any clarification
        # messages on the model for the serve layer to expose.
        basis = getattr(getattr(self.wholeSpace, 'subspace', None),
                        'basis', None)
        try:
            score, contradictions = truth_layer.consistency(
                basis=basis, return_report=True
            )
        except Exception:
            score, contradictions = None, []
        self._last_truth_score = float(score) if score is not None else None
        self._last_clarifications = (
            truth_layer.suggest_clarifications(basis=basis)
            if contradictions else []
        )
        # Phase 5: terminal paraconsistent assessment for the client
        # (support / conflict / ignorance) -- keeps "contested" (the
        # TruthSet splits on p) distinct from "unknown" (silent on p).
        try:
            self._last_truth_assessment = truth_layer.assess(basis=basis)
        except Exception:
            self._last_truth_assessment = None

    @torch.no_grad()
    def _store_truths_into_ltm(self, store, truth_layer, texts, trusts, *, source_key='user-truths'):
        """``store_truths``' consolidated arm: land the user TruthSet in
        the unified LTM and rebuild the TruthLayer view.

        Ordering: the lazy XML provisioning fires FIRST (mirroring the
        runEpoch trigger) so provisioned rows keep the earliest ticks even
        when the first thing a served model does is ingest a user
        TruthSet. Then previous ``ORIGIN_USER`` rows are compacted out
        (replace-on-resubmit), the texts run through the real forward
        (rows land at the sentence boundary), each landed row gets its effective DoT +
        user origin + source text, and the view is rematerialized."""
        if not getattr(self, '_ltm_provisioned', True):
            self._ltm_provisioned = True
            # Skip provisioning when the store already carries its XML
            # truthSet: ``_ltm_provisioned`` is a transient attribute (not in
            # the state_dict), so a LOADED checkpoint that was provisioned
            # before saving comes back with the flag reset -- re-provisioning
            # would duplicate those rows (they survive a stateless reload).
            already = len(store.rows_of_origin(store.ORIGIN_PROVISIONED)) > 0
            if not already:
                self.provision_ltm()
        memory = getattr(getattr(self, 'symbolSpace', None), 'what_memory', None)
        namespace = store.address_domain
        roots = (memory.retained_ltm_occurrences(namespace)
                 if memory is not None else ())
        from Occurrence import document_digest
        incoming = {(document_digest(('ingestion', source_key, index)), text)
                    for index, text in enumerate(texts)}
        preserve = [int(store.address_keys[row]) for row in range(len(store))
                    if (bytes(store.document_keys[row].tolist()), store.text_of(row)) in incoming]
        store.clear_origin(store.ORIGIN_USER, retained_occurrences=roots, preserve_addresses=preserve)
        self._ltm_ingest_truth_texts(store, texts, trusts=trusts, origin=store.ORIGIN_USER, source_key=source_key)
        truth_layer.sync_from_ltm()

    # -- LTM consolidation: XML TruthSet provisioning ------------------
    @torch.no_grad()
    def provision_ltm(self):
        """Read the configured English assertions through the sentence driver.

        Each text supplies only external trust, origin and source text. Its
        trained grammar selects an idea or relation and the writer preserves
        that actual end state. An untrained chooser is not a provisioning
        mechanism for relation fixtures (§11.5 of the two-truths spec).
        Returns the number of newly appended rows; repeated relation evidence
        can update an existing row without allocating another one.
        """
        if not getattr(self, 'ltm_consolidation', False):
            return 0
        ss = getattr(self, 'symbolSpace', None)
        store = getattr(ss, 'ltm_store', None) if ss is not None else None
        if store is None:
            return 0
        ts = TheXMLConfig.get("architecture.truthSet", default=None)
        if not ts:
            return 0
        entries = ts.get('truth') if isinstance(ts, dict) else None
        if entries is None:
            return 0
        if isinstance(entries, dict):           # singleton un-listed by parser
            entries = [entries]
        # TruthSet supplies plain English and provenance, never grammar.
        texts, trusts = [], []
        for ent in entries:
            if not isinstance(ent, dict):
                continue
            text = ent.get('text') or ent.get('_') or ''
            text = str(text).strip()
            if not text:
                continue
            try:
                trust = self._effective_incoming_trust(
                    ent.get('trust', 0.0) or 0.0)
            except (TypeError, ValueError):
                trust = 0.0
            texts.append(text)
            trusts.append(trust)
        if not texts:
            return 0

        n_before = len(store)
        try:
            self._ltm_ingest_truth_texts(store, texts, trusts=trusts,
                origin=store.ORIGIN_PROVISIONED)
        finally:
            # Provisioning is outside the live interaction. Reading the
            # truths creates temporary what context as well as durable rows.
            memory = self._what_memory()
            if memory is not None:
                memory.Reset(hard=True)
        return max(0, len(store) - n_before)

    def _ltm_ingest_truth_texts(self, store, texts, *, trusts=None, origin=None, source_key='configured-truths'):
        """Understand each external assertion through the ordinary sentence closing.

        Registration writes child clauses without assertion authority. Only
        each text's outer endings receive supplied provenance. The returned row
        ids include deduplicated relations; append ranges are not identities.
        """
        self.eval()
        self.set_sigma(0)
        trusts = [0.] * len(texts) if trusts is None else trusts
        if len(trusts) != len(texts):
            raise ValueError('TruthSet provenance must align with its texts')
        per_text_rows = []
        discourse = getattr(getattr(self, 'symbolSpace', None), 'expectation', None)
        sequence = (discourse.suspend_external_observations()
                    if discourse is not None else nullcontext())
        interaction = self._what_memory()
        if interaction is not None and texts:
            interaction.Reset(hard=True)
        with sequence:
            for source_index, (text, trust) in enumerate(zip(texts, trusts)):
                with store.clause_assertions(trust=trust, origin=origin, text=text) as rows:
                    with torch.no_grad(), self._runtime_batch([text], document_keys=[('ingestion', source_key, source_index)]):
                        from What import What
                        inp = self.inputSpace.prepInput(list(self.data.train_input))
                        self.runBatch(train=False, batchNum=0, batchSize=1, split='runtime',
                            batch_override=(inp, torch.empty(1, 0, device=inp.device)), source_rows=[0],
                            questions=(What.present(0, split='runtime'),))
                    if not rows:
                        raise ValueError('TruthSet input did not produce a selected grammatical closing')
                    per_text_rows.append(tuple(rows))
                for cs in (list(getattr(self, 'conceptualSpaces', []) or [])
                           or [getattr(self, 'conceptualSpace', None)]):
                    if cs is not None and hasattr(cs, 'Reset'):
                        cs.Reset(hard=True)
        return per_text_rows

    def infer(self, text, max_length=None, mode='IR', *, document_key=None):
        """IR-mode infill inference.

        Lexes the input, embeds it, applies ``mask_rate`` random
        masking to the embedded substrate (NULL_PERCEPT replacement),
        runs one forward pass, and decodes the body's prediction at
        each masked position via nearest-neighbor lookup against the
        lexicon.  Returns ``(slot_index, original_token, predicted_token)``
        triples.

        Sentence-level generation (the legacy AR / ARIR chat loop) is
        now provided by ``generate_sentence`` via ``BracketExpectation``
        (ARMA(p, q) over sentence reps).  ``mode`` defaults to ``'IR'``
        and is accepted for back-compat with callers that still pass
        ``mode='IR'``; any other value raises.
        """
        del max_length  # retained for signature back-compat only
        mode = 'IR' if mode is None else mode
        if str(mode).upper() != 'IR':
            raise NotImplementedError(
                f"infer(mode={mode!r}) retired 2026-05-14. Within-sentence "
                "training/inference is IR-only; for sentence-level "
                "generation use BasicModel.generate_sentence (Phase 4)."
            )
        return self._infer_ir(text, document_key=document_key)

    def _infer_ir(self, text, *, document_key=None):
        """IR-mode parallel-infill inference.

        Runs one forward pass under no_grad and reads the body's
        prediction at each masked position straight out of the post-
        body perceptual event (the same target ``runBatch`` uses for
        the IR reconstruction loss).  No reverse pipeline involved.
        """
        self.eval()
        self.set_sigma(0)

        with torch.no_grad(), self._runtime_batch([text], document_keys=None if document_key is None else [document_key]):
            inputTensor = self.inputSpace.prepInput(
                list(self.data.train_input))
            execution = self.forward(inputTensor)
            self._last_understanding = self._capture_understanding(execution)
            forwardInput, _symbols, _predictions, _ = execution
            if forwardInput is None:
                return []
            pred_full = None
            if hasattr(self.perceptualSpace.subspace, 'materialize'):
                pred_full = self.perceptualSpace.subspace.materialize()

        mask_pos = getattr(self, "_ir_mask_positions", None)
        if (mask_pos is None or pred_full is None
                or not bool(mask_pos.any())):
            return []

        # Lex output for the original tokens at each slot. PartSpace
        # owns the codebook (the retired ``_peer_perceptual`` was just a
        # back-ref to it).
        peer = self.perceptualSpace
        codebook = peer.subspace.what
        last_meta = getattr(peer, '_forward_input', None) or {}
        all_tokens = last_meta.get('tokens') or [[]]
        tokens0 = all_tokens[0] if all_tokens else []

        if not hasattr(codebook, 'wv'):
            return []  # Codebook .what: token-infill readout is Embedding-only (5b keeps its mask for training)
        D = codebook.wv.vector_size
        K = pred_full.shape[1]
        indices = mask_pos[0, :K].nonzero(as_tuple=False).squeeze(-1).tolist()
        out = []
        for idx in indices:
            orig = tokens0[idx] if idx < len(tokens0) else ''
            pred_vec = pred_full[0, idx, :D].detach().unsqueeze(0)
            try:
                neighbors = codebook.wv.most_similar(pred_vec, k=1)
                pred = neighbors[0][0] if neighbors else ''
            except Exception:
                pred = ''
            out.append((int(idx), str(orig), str(pred)))
        return out

    @torch.no_grad()
    def generate_sentence(self, seed_text="", max_chars=128):
        """Realise a positive predicted idea through the existing generate walk.

        Supplied text is understood without a prior. The next prediction is
        a generation seed only; generated words are never external observations.
        """
        if seed_text:
            self.eval()
            self.set_sigma(0)
            with self._runtime_batch([seed_text]):
                self.understand(self.inputSpace.prepInput([seed_text]))
                self._end_step()
        discourse = getattr(self.symbolSpace, "expectation", None)
        estimate = (discourse.expect_next_meaning(0, record=False)
                    if discourse is not None and discourse.expectation_enabled else None)
        if estimate is None or max_chars <= 0:
            return []
        idea = (estimate.roles * estimate.presence_logits.sigmoid()[:, None])[None]
        words, lengths, _truncated, _credit = self._compiled_output_walk()(
            self._walk_operand(idea, infix_rows=(True,)), self._walk_budget(),
            False, None, False)
        text = self._generated_word_text(words, lengths)[0]
        return [] if text is None else text[:int(max_chars)].split()

    def _warn_zeroed_channel(self, site, detail):
        """Warn-once per site+config when a loss channel degrades to zero (5b fail-loud)."""
        try:
            cfg = str((TheXMLConfig._sources or ["?"])[-1])
        except Exception:
            cfg = "?"
        seen = getattr(self, "_zeroed_channel_warned", None)
        if seen is None:
            seen = set()
            object.__setattr__(self, "_zeroed_channel_warned", seen)
        key = (site, cfg)
        if key not in seen:
            seen.add(key)
            warnings.warn(f"{site} [config {cfg}]: {detail}", RuntimeWarning)

    def _align_output_pred(self, pred, tgt):
        """Reduce the head pred onto the label shape; None (after warn-once) when irreconcilable."""
        _pred = pred
        while _pred.dim() > tgt.dim():
            _pred = _pred.mean(dim=-1)
        # Equal-dim/unequal-shape (e.g. head [B,4,4] vs labels [B,1,1]): mean-reduce pred over label-singleton axes.
        if (_pred.shape != tgt.shape and _pred.dim() == tgt.dim()
                and all(p == t or t == 1
                        for p, t in zip(_pred.shape, tgt.shape))):
            for d, t in reversed(tuple(enumerate(tgt.shape))):
                if t == 1 and _pred.shape[d] != 1:
                    _pred = _pred.mean(dim=d, keepdim=True)
        # A one-hot / multi-class head emits [B, N, 1] (N output vectors of
        # width 1) while list-label datasets prep their [N] rows to
        # [B, 1, N]: exact transposes with a singleton axis are the same
        # values in the other layout (the math dataset's one-hot answers).
        if (_pred.dim() == 3 and tgt.dim() == 3 and _pred.shape[0] == tgt.shape[0]
                and _pred.shape[1] == tgt.shape[2] and _pred.shape[2] == tgt.shape[1]
                and 1 in (int(_pred.shape[1]), int(_pred.shape[2]))):
            _pred = _pred.transpose(1, 2)
        if _pred.shape == tgt.shape:
            return _pred
        self._warn_zeroed_channel(
            "output_shape_gate",
            f"head pred {tuple(pred.shape)} vs labels {tuple(tgt.shape)} "
            "irreconcilable after reduction; supervised output loss zeroed")
        return None

    def _reverse_event_loss(self, rev_ev, fwd_ev, *, score_when=True,
                            registry=None, name='reconstruction', objective='reconstruction'):
        """lossRev seam (nWhere=0 wiring fix, 2026-07-04): clip to the shared
        [K, D] window, then weight with the INPUT event layout's where/when
        band. ModelLoss's constructor band is canonical_shape("OutputSpace")
        == (0, 0) -- right for lossOut, wrong here: the muxed input event's
        2-dim where band was diluted ~512x inside the what-scaled mean-MSE.
        Per-word reconstruction sets score_when=False: the field's shared
        time is transported, but is not an independent target on every word.
        """
        Kr = min(rev_ev.shape[1], fwd_ev.shape[1])
        Dr = min(rev_ev.shape[-1], fwd_ev.shape[-1])
        sub = getattr(getattr(self, "inputSpace", None), "subspace", None)
        nw = getattr(sub, "nWhere", None)
        nn_ = getattr(sub, "nWhen", None)
        if nw is None or nn_ is None:
            # Fail-loud (5b pattern): an unknowable band must announce itself, never silently take what_scale.
            self._warn_zeroed_channel(
                "lossrev_band_unknown",
                "input event band widths unavailable (no inputSpace."
                "subspace nWhere/nWhen); lossRev treats the whole event "
                "as what")
            nw, nn_ = 0, 0
        elif Dr != rev_ev.shape[-1] or Dr != fwd_ev.shape[-1]:
            # The width clip cuts/misaligns the trailing band; band scales cannot be applied honestly.
            self._warn_zeroed_channel(
                "lossrev_band_clipped",
                f"lossRev width clip (rev {int(rev_ev.shape[-1])} vs fwd "
                f"{int(fwd_ev.shape[-1])}) misaligns the trailing "
                f"where/when band; the clipped event takes what_scale")
            nw, nn_ = 0, 0
        if not score_when:
            Dr -= int(nn_)
            nn_ = 0
        if registry is not None:
            self.loss.register(registry, name, rev_ev[:, :Kr, :Dr], fwd_ev[:, :Kr, :Dr].detach(),
                nWhere=int(nw), nWhen=int(nn_), objective=objective)
        return self.loss.compute(rev_ev[:, :Kr, :Dr],
                                 fwd_ev[:, :Kr, :Dr].detach(),
                                 nWhere=int(nw), nWhen=int(nn_))

    def _masked_event_loss(self, pred, target, mask, *, registry=None):
        """lossIn seam (silent-band wiring fix, 2026-07-04): the masked-LM
        compares PERCEPTUAL events (muxed ``[what|where|when]``,
        canonical_shape("PartSpace") == (2, 2)) -- weight the trailing band
        with the live percept layout, not ModelLoss's constructor (0, 0)
        (the where band was diluted ~512x inside the what-scaled mean).
        """
        K = min(pred.shape[1], target.shape[1], mask.shape[1])
        sub = getattr(getattr(self, "perceptualSpace", None), "subspace", None)
        nw = getattr(sub, "nWhere", None)
        nn_ = getattr(sub, "nWhen", None)
        if nw is None or nn_ is None:
            # Fail-loud (5b pattern): an unknowable band must announce itself, never silently take what_scale.
            self._warn_zeroed_channel(
                "lossin_band_unknown",
                "percept event band widths unavailable (no perceptualSpace."
                "subspace nWhere/nWhen); masked lossIn treats the whole "
                "event as what")
            nw, nn_ = 0, 0
        elif pred.shape[-1] != target.shape[-1]:
            # compute_masked's internal width clip would cut/misalign the trailing band; band scales cannot apply honestly.
            self._warn_zeroed_channel(
                "lossin_band_clipped",
                f"masked lossIn width clip (pred {int(pred.shape[-1])} vs "
                f"target {int(target.shape[-1])}) misaligns the trailing "
                f"where/when band; the clipped event takes what_scale")
            nw, nn_ = 0, 0
        if registry is not None:
            self.loss.register(registry, 'reconstruction', pred[:, :K, :], target[:, :K, :],
                mask=mask[:, :K], nWhere=int(nw), nWhen=int(nn_), objective='reconstruction')
        return self.loss.compute_masked(pred[:, :K, :], target[:, :K, :],
                                        mask[:, :K],
                                        nWhere=int(nw), nWhen=int(nn_))

    def create_ir_mask(self, percept_subspace):
        """Whole-slab IR mask (BERT-style hide-a-token; UNCHANGED).

        This is the **non-grammar / whole-slab** masking, kept
        byte-identical: ``_per_word_enabled=False`` configs
        (model.xml / idempotent.xml) take ``_forward_body``'s whole-slab
        path which calls this once on pass-0's perceptual event, and
        ``runBatch``'s ``compute_masked`` consumes
        ``_ir_pre_mask_input`` / ``_ir_mask_positions`` exactly as
        before. Rework B's gaussian attentional window
        (:meth:`apply_gaussian_window`) + D3 reconstruction loss replace
        THIS only on the per-word grammar path; the whole-slab path is
        untouched (the spec's "whole-slab byte-identical" invariant).

        Replaces embeddings at random positions with NULL_PERCEPT
        (Embedding ``.what``: the learnable NULL row; Codebook ``.what``,
        the radix/meronomy PS, has no NULL row -- the all-zeros MASK
        vector is injected instead, per the Spaces.py MPHF-table note).
        Captures the pre-mask embedded event as the loss target and
        stashes it on ``self`` along with the per-position bool mask so
        the loss path can compute reconstruction error at masked
        positions only. Mask injection edits only the WHAT slice of the
        muxed event so the body still has WHERE/WHEN positional info at
        masked slots. Padding slots (codebook index 0, byte ``\\x00``)
        are excluded so the model isn't asked to "predict" trailing
        zeros.
        """
        self._ir_mask_positions = None
        self._ir_pre_mask_input = None
        if percept_subspace is None:
            return
        if hasattr(percept_subspace, 'is_empty') and percept_subspace.is_empty():
            return
        event_basis = percept_subspace.event
        if event_basis is None:
            return
        # Spec doc/specs/2026-05-21-subspace-slot-architecture.md: per-batch
        # event reads go through ``materialize(mode='event')``, not the
        # ``_active_payload`` shadow on ``.event.getW()``. The result is
        # the same per-batch ``[B, N, D]`` slab pre-migration; post-
        # migration it's reconstructed from prototype + selection.
        event = percept_subspace.materialize(mode="event")
        if event is None or event.dim() != 3:
            return
        codebook = percept_subspace.what
        cb_w = codebook.getW() if hasattr(codebook, 'getW') else None
        if not torch.is_tensor(cb_w) or cb_w.dim() != 2:
            return  # numeric / rowless .what: cannot stage a mask (runBatch warns on the zeroed channel)
        if (not hasattr(codebook, 'null_percept_idx')
                and not torch.is_grad_enabled()):
            return  # 5b Codebook path is train-step-only: no_grad forwards stay inert (HEAD-parity determinism)

        B, K, D = event.shape
        dev = event.device

        # Sample mask positions [B, K] bool.
        rate = float(self.mask_rate)
        if rate <= 0.0 or rate > 1.0:
            return
        mask = torch.bernoulli(
            torch.full((B, K), rate, device=dev)).bool()

        # Exclude padding slots (codebook index 0 == byte \x00 sentinel)
        # — but only where the what-index column is INFORMATIVE.
        # Byte-staged configs (MM_20M / MM_xor) leave ``_index``'s
        # what-index column uniformly 0 even for REAL content, so the
        # unconditional ``what_idx != 0`` exclusion silently zeroed the
        # whole mask — ``compute_masked`` then returned exactly 0.0
        # every batch, the reconstruction objective never engaged, and
        # nothing stopped the body from collapsing content (the
        # flat-0.5-prediction / blank-reconstruction failure,
        # 2026-06-11). When the column is degenerate (all zero), fall
        # back to NULL-CONTENT padding detection (an all-zero ``.what``
        # slice — what a padding slot actually carries). The selection
        # is a tensor ``torch.where`` on a 0-dim flag — on-device,
        # sync-free — and word-staged configs (informative column,
        # e.g. XOR_exact's verified seed basin) keep the index rule
        # byte-identically.
        active = getattr(percept_subspace, '_index', None)
        if (active is not None and active.dim() == 3
                and active.shape[-1] >= 1):
            what_idx = active[:, :K, 0].long()
            if what_idx.shape == mask.shape:
                nWhat_excl = int(cb_w.shape[-1])
                content_mass = event[..., :nWhat_excl].abs().amax(dim=-1)
                idx_informative = what_idx.amax() > 0      # 0-dim, on-device
                keep = torch.where(idx_informative,
                                   what_idx != 0,
                                   content_mass > 0)
                mask = mask & keep
        elif not hasattr(codebook, 'null_percept_idx'):
            # 5b Codebook path (no _index): exclude zero-content pad slots by content mass.
            mask = mask & (
                event[..., :int(cb_w.shape[-1])].abs().amax(dim=-1) > 0)

        # Snapshot pre-mask embedded event as the loss target.
        # Detach so backward through the loss target doesn't double up
        # on the forward graph (we still get gradient through pred via
        # the brick body + reverse pipeline).
        self._ir_pre_mask_input = event.detach().clone()
        self._ir_mask_positions = mask

        # No `if mask.any()` early-out: an all-False boolean-mask write
        # selects zero rows, so the body below is a content-identical
        # no-op when nothing is masked (new_event == event). Running it
        # unconditionally keeps the brick CUDA-graph-capturable -- the
        # data-dependent `bool(mask.any())` skip was a host sync (see
        # doc/BrickHostSyncStatus.md residual C; same shape as the
        # `_snap_content` fix).
        if hasattr(codebook, 'null_percept_idx'):
            null_vec = cb_w[codebook.null_percept_idx]  # [nWhat] learnable NULL row
        else:
            # 5b: Codebook (radix/meronomy PS) has no NULL row -- MASK is the all-zeros vector (Spaces.py MPHF note).
            null_vec = cb_w.new_zeros(cb_w.shape[-1])
        nWhat = int(null_vec.shape[-1])
        # Replace the WHAT slice at masked positions; preserve WHERE/WHEN.
        # Dense `torch.where` instead of boolean-mask assignment
        # ``new_event[mask, :nWhat] = ...``: advanced boolean indexing is
        # data-dependent (the selected-row count must be read to host) ->
        # an implicit cudaMemcpyDtoH that breaks CUDA-graph capture. The
        # where form is static-shape, fully on-device, and bit-identical
        # (same values written; all-False mask -> no-op). [B,K]->[B,K,1]
        # broadcasts over the nWhat channel slice.
        new_event = event.clone()
        m = mask.unsqueeze(-1)
        nv = null_vec.to(new_event.dtype)
        new_event[..., :nWhat] = torch.where(
            m, nv, new_event[..., :nWhat])
        # Spec doc/specs/2026-05-21-subspace-slot-architecture.md Setter
        # API: per-batch event writes flow through ``set_event`` (which
        # routes appropriately for codebook-bearing vs plain-Tensor
        # ``.event`` slots), NOT through ``basis.setW`` directly. The
        # mocked test path provides ``percept_subspace.set_event``; the
        # production path is the same call.
        if hasattr(percept_subspace, "set_event"):
            percept_subspace.set_event(new_event, compute_activation=False)
        else:
            event_basis.setW(new_event)  # legacy fallback for older mocks

    def gaussian_window_word(self, full_seq, center_k):
        """Rework B (1): GAUSSIAN ATTENTIONAL WINDOW over the WHOLE
        percept sequence, centered at the processed word position
        ``center_k``; returns word k's contextual representation
        (``[B, 1, D]``).

        This **replaces wholesale** the prior BERT-style hide-a-token
        ``create_ir_mask`` **on the per-word grammar path**. It is
        **NOT** target-hiding: the word at the gaussian center
        (``center_k``) is preserved (multiplier ~1) and words *far*
        from ``center_k`` are zeroed by the gaussian tail
        (multiplier ->0).

        ``full_seq`` is the COMPLETE per-sentence input percept slab
        ``[B, T, D]`` (``inputSpace._ar_embedded`` -- every word). For
        the processed word at center ``k`` a single gaussian envelope
        over the whole sequence is built:

            w_i = exp(-(i - k)^2 / (2 * sigma^2))   over percept i in T,
            sigma = maskRate * N_percepts            (D1; maskRate=0.15,
                                                      N_percepts == T)

        normalized so the center ``w_k ~= 1``. The gaussian-windowed
        percepts are mapped into conceptual space and **summed** (the
        weighted sum over the whole sequence) so word ``k``'s
        representation carries a *contextual trace* -- the faint
        gaussian-weighted contribution of nearby words (the local
        context IS the embedding signal). Per-word context washes out
        across the whole-sentence D3 reconstruction (overlapping
        gaussians average). The summed contextual word is what the
        per-word loop feeds PS->CS->STM (one concept per word, the
        existing loop structure preserved; only the per-word INPUT now
        carries the gaussian contextual trace instead of a raw slice).

        Pure static tensor ops (a gaussian over a fixed position arange
        + a single weighted sum), no host sync,
        CUDA-graph-capturable -- the bernoulli/where data-dependent
        path is gone. Returns ``full_seq``'s single-slot fallback
        (``full_seq[:, k:k+1, :]``) unchanged when the envelope is
        inapplicable (degenerate rate / shape) so the caller's existing
        per-word slice contract still holds.
        """
        if (full_seq is None or not torch.is_tensor(full_seq)
                or full_seq.dim() != 3):
            return full_seq
        B, T, D = full_seq.shape
        dev = full_seq.device
        k = int(center_k)
        if k < 0:
            k = 0
        if k > T - 1:
            k = T - 1
        rate = float(self.mask_rate)
        if rate <= 0.0 or rate > 1.0 or T <= 0:
            return full_seq[:, k:k + 1, :]
        # sigma = maskRate * N_percepts (D1; N_percepts == T, the whole
        # sentence's percept-sequence length).
        sigma = max(rate * float(T), 1e-3)
        pos = torch.arange(T, device=dev, dtype=full_seq.dtype)  # [T]
        w = torch.exp(-((pos - float(k)) ** 2) / (2.0 * sigma * sigma))
        # Normalize so the center is exactly ~1 (exp(0)==1 already; the
        # explicit divide keeps the contract robust if sigma underflows).
        w = w / w.max().clamp(min=1e-12)                         # [T]
        # Reported-metric side channel only (the D3 trainable loss reads
        # the COMPLETE UNMASKED _ar_embedded directly, NOT these).
        self._ir_mask_positions = (
            (w <= 0.5).view(1, T).expand(B, T).clone())
        self._ir_pre_mask_input = full_seq.detach().clone()
        # The gaussian-windowed percepts SUMMED over the whole sequence
        # -> word k's contextual representation [B, 1, D]. Grad flows
        # (no detach) so the contextual trace shapes upstream params.
        wcol = w.view(1, T, 1).to(full_seq.dtype)
        windowed = full_seq * wcol                                # [B,T,D]
        return windowed.sum(dim=1, keepdim=True)                  # [B,1,D]

    def word_span_window(self, full_seq, center_k, word_idx):
        """Increment 2 (HARD-MASK-TO-WORD-SPAN; doc/specs/mereological-order-
        raising.md "Serial-mode word-at-a-time loop"). The HARD same-word window
        that replaces :meth:`gaussian_window_word` on the serial
        ``serialObjectMeta`` path: returns word ``center_k``'s representation
        ``[B,1,D]`` as the masked SUM over the slots belonging to the SAME word
        as slot ``center_k`` (so PartSpace processes the ACTIVE WORD ONLY — no
        part with a ``.where`` outside the word). Same ``[B,1,D]`` contract as
        the gaussian, so the caller's shape guard accepts it unchanged.

        ``word_idx`` is a ``[B,T]`` long per-slot word index (slots of one word
        share an id). Pure static tensor ops — DtoH-free, CUDA-graph-capturable
        (``k`` is a host-int constant per unrolled loop position; the mask is a
        fixed-shape elementwise compare). When ``word_idx`` is unavailable
        (None / wrong shape — e.g. byte mode has no word grouping), falls back to
        the single slot ``full_seq[:, k:k+1, :]`` (in fused modes the active word
        IS its own slot; the byte fallback degrades safely)."""
        if (full_seq is None or not torch.is_tensor(full_seq)
                or full_seq.dim() != 3):
            return full_seq
        B, T, D = full_seq.shape
        k = int(center_k)
        if k < 0:
            k = 0
        if k > T - 1:
            k = T - 1
        if (word_idx is None or not torch.is_tensor(word_idx)
                or word_idx.dim() != 2 or int(word_idx.shape[0]) != B
                or int(word_idx.shape[1]) != T):
            return full_seq[:, k:k + 1, :]                # single-slot fallback
        center_id = word_idx[:, k:k + 1]                  # [B,1] (static slice)
        same = (word_idx == center_id)                    # [B,T] same-word mask
        mcol = same.to(full_seq.dtype).unsqueeze(-1)      # [B,T,1] hard 0/1
        return (full_seq * mcol).sum(dim=1, keepdim=True)  # [B,1,D] word rep

    def _prewarm_checkpoint_shapes(self):
        """Materialize lazy state whose final tensors ride in checkpoints.

        Materialize the lazy category codebook. A training checkpoint contains its
        final shapes, so they must exist before ``load_state_dict``. Canonical
        WholeSpace properties are not grown here: property growth is
        independent of concept capacity and requires an explicit
        optimizer/compiled-graph reset boundary. This helper is idempotent and
        shared by autoload and compilation pre-warm.
        """
        # Participation-category state is allocated on the first perception
        # forward in a fresh model, but autoload necessarily runs before that
        # forward. At this point SymbolSpace has configured the live grammar,
        # so materialize the requested terminal VQ on the same device as the
        # owning concept/property dictionary. Otherwise its learned
        # prototype/buffer keys in a checkpoint are classified as stale.
        category_owner = getattr(self, "conceptualSpace", None)
        if (category_owner is not None
                and getattr(category_owner,
                            "_category_codebook_requested", False)
                and hasattr(category_owner, "category_codebook_enabled")
                and not category_owner.category_codebook_enabled()
                and hasattr(category_owner, "enable_category_codebook")):
            from Language import TheGrammar
            cb = getattr(category_owner, "similarity_codebook", None)
            if cb is None:
                cb = getattr(getattr(
                    category_owner, "subspace", None), "what", None)
            W = cb.getW() if cb is not None and hasattr(cb, "getW") else None
            device = W.device if torch.is_tensor(W) else None
            category_owner.enable_category_codebook(
                TheGrammar, device=device)

    def _aligned_serial_word_mode(self):
        """Return whether the canonical aligned per-word protocol is live."""
        return bool(
            getattr(self, "word_brackets", False)
            and getattr(getattr(self, "inputSpace", None),
                        "_per_word_enabled", False)
            and getattr(self, "serial_object_meta", False)
            and getattr(self, "concept_binding", "mixing") == "aligned")

    def _aligned_serial_sparse_bank_mode(self):
        """Return whether aligned serial execution needs its sparse bank.

        Stage 0 resolves relation identities while the terminal CS consumes
        them.  The staged atoms are therefore sound only when both stages own
        the same physical codebook Parameter, an invariant of the canonical
        model that is checked here rather than assumed at decode time.
        """
        if not self._aligned_serial_word_mode():
            return False
        spaces = list(getattr(self, "conceptualSpaces", None) or ())
        if not spaces:
            return False
        terminal = getattr(self, "conceptualSpace", None)
        if terminal is None:
            terminal = spaces[-1]
        owner_cb = getattr(spaces[0], "similarity_codebook", None)
        terminal_cb = getattr(terminal, "similarity_codebook", None)
        sparse = any(
            bool(getattr(getattr(space, "similarity_codebook", None),
                         "sparse_lookup_grad", False))
            for space in spaces)
        if sparse and owner_cb is not terminal_cb:
            raise RuntimeError(
                "aligned serial sparse staging requires stage-0 and "
                "terminal ConceptualSpace to share one physical codebook")
        return sparse

    def _enable_fullgraph_perception(self, compile_fn):
        """Compile the native word reads at their tensor-only boundaries."""
        ps, ws = self.perceptualSpace, self.wholeSpace
        object.__setattr__(ps, 'synthesize_word_parts', compile_fn(
            ps.synthesize_word_parts, verbose=True, fullgraph=True))
        object.__setattr__(ws, 'compute_word_property_event', compile_fn(
            ws.compute_word_property_event, verbose=True, fullgraph=True))

    def _configure_lazy_fullgraph_word_loops(self, compile_fn, buckets):
        """Install, but do not lower, one fullgraph sentence loop per capacity.

        The staged word capacity and masked residual-constituent layout are
        static graph shapes. The peer recurrence itself is a tensor
        ``while_loop`` whose device-side trip count is the last live word plus
        one CSSym drain, one CSLang drain, and one grammar-register drain.
        Capturing the complete callable makes all three cross-word stages
        compiler-visible without Python-unrolling W. Lowering is deferred until
        a capacity is first observed. BasicModel uses only W=512, so a run pays
        one specialization while short batches still stop at their real
        length; multiple capacities remain supported for compatibility.

        Separately-defined source functions are deliberate. Dynamo keys
        the Python code object in addition to shapes; a closure factory would
        otherwise turn W=32 into a recompile of the W=16 graph.
        """
        widths = tuple(sorted(set(int(width) for width in buckets)))
        required = (16, 32, 64, 128, 256, 512)
        unsupported = tuple(width for width in widths
                            if width not in required)
        if unsupported:
            raise ValueError(
                "canonical fullgraph word loops support "
                "W=16,32,64,128,256,512; "
                f"got unsupported {list(unsupported)}")

        def _forward_W16(input_data):
            slab = self.inputSpace._ar_embedded_N
            if slab is None or int(slab.shape[1]) != 16:
                raise RuntimeError("fullgraph W=16 loop received a non-W=16 slab")
            # The complete word loop consumes the eager-staged InputSpace
            # slab, never the raw text tensor.  Keeping that variable-width
            # lexer tensor in the compiled callable's signature gave Dynamo a
            # second (unrelated) shape guard after the W loop had lowered.
            return self._forward_with_compiled_sentence_state(None)

        def _forward_W32(input_data):
            slab = self.inputSpace._ar_embedded_N
            if slab is None or int(slab.shape[1]) != 32:
                raise RuntimeError("fullgraph W=32 loop received a non-W=32 slab")
            return self._forward_with_compiled_sentence_state(None)

        def _forward_W64(input_data):
            slab = self.inputSpace._ar_embedded_N
            if slab is None or int(slab.shape[1]) != 64:
                raise RuntimeError("fullgraph W=64 loop received a non-W=64 slab")
            return self._forward_with_compiled_sentence_state(None)

        def _forward_W128(input_data):
            slab = self.inputSpace._ar_embedded_N
            if slab is None or int(slab.shape[1]) != 128:
                raise RuntimeError("fullgraph W=128 loop received a non-W=128 slab")
            return self._forward_with_compiled_sentence_state(None)

        def _forward_W256(input_data):
            slab = self.inputSpace._ar_embedded_N
            if slab is None or int(slab.shape[1]) != 256:
                raise RuntimeError("fullgraph W=256 loop received a non-W=256 slab")
            return self._forward_with_compiled_sentence_state(None)

        def _forward_W512(input_data):
            slab = self.inputSpace._ar_embedded_N
            if slab is None or int(slab.shape[1]) != 512:
                raise RuntimeError(
                    "fullgraph W=512 loop received a non-W=512 slab")
            return self._forward_with_compiled_sentence_state(None)

        object.__setattr__(self, "_compiled_word_step_sources", {
            16: _forward_W16,
            32: _forward_W32,
            64: _forward_W64,
            128: _forward_W128,
            256: _forward_W256,
            512: _forward_W512,
        })
        self._compiled_word_steps = {}
        self._compiled_word_loop_compile = compile_fn
        self._compiled_word_loop_fullgraph = True

    @_sentence_query_mask
    def _forward_with_compiled_sentence_state(self, input_data):
        """Return forward outputs plus tensor state consumed outside the graph.

        PyTorch 2.12 replayed assignments to ``_stm_single_S`` and
        ``_tensor_peer_trip_count`` after a compiled call even though those
        values were otherwise dead graph outputs.  PyTorch 2.14 nightlies can
        legitimately eliminate that attribute-only escape: the tensor
        recurrence completes, but the eager detached-reverse tail then sees
        the pre-call ``None`` values.

        Make the compiler boundary explicit.  The first four entries retain
        :meth:`forward`'s public contract; the final three are small tensors
        produced by the completed sentence recurrence.  ``runBatch`` publishes
        them onto their diagnostic/consumer attributes after the compiled call.
        The fourth state output is a sparse-by-word slab whose nonzero end
        columns hold every packed sentence root.
        """
        external_start = bool(getattr(
            self, "_spaces_started_for_forward", False))
        if not external_start:
            self._start_spaces_for_forward()
        try:
            return self._forward_per_stage(
                input_data, return_sentence_state=True)
        finally:
            self._spaces_started_for_forward = False

    def _publish_compiled_sentence_state(self, result):
        """Publish explicit fullgraph outputs and return the public 4-tuple."""
        if not isinstance(result, (tuple, list)):
            raise RuntimeError(
                "model forward must return a tuple or list of tensors")
        if len(result) == 4:
            if not getattr(self, '_packed_prediction_drained', False):
                self._packed_sentence_roots = None
            return tuple(result)
        # Keep accepting the pre-packing explicit-state contract for small
        # harnesses and external callers that produce no root slab. Canonical
        # packed/fullgraph execution returns the eight-value form below.
        if len(result) == 7:
            public = tuple(result[:4])
            idea, post_depth, trip_count = result[4:]
            if not all(torch.is_tensor(value)
                       for value in (idea, post_depth, trip_count)):
                raise RuntimeError(
                    "compiled sentence state must contain tensor "
                    "(S, post_depth, trip_count) values")
            self._stm_single_S = idea
            self._stm_post_depth = post_depth
            self._packed_sentence_roots = None
            object.__setattr__(self, "_tensor_peer_trip_count", trip_count)
            return public
        if len(result) == 21:
            # Compiled reverse-loops plan, slices 1-2: the traversals'
            # recovered word ideas, idea cost, byte cost, truncation flag,
            # per-sentence byte costs, and the state the traversal reads
            # (references, the sentences' end slots and depths, the final
            # end state), published so a traversal placed after the
            # forward can run from them.
            (recon_ideas, recon_idea_cost, recon_byte_cost, recon_truncated,
             recon_sentence_costs, recon_reference, recon_roots, recon_depth,
             recon_end_slots, recon_end_depth) = result[11:]
            if not all(torch.is_tensor(value) for value in (
                    recon_ideas, recon_idea_cost, recon_byte_cost,
                    recon_truncated, recon_sentence_costs, recon_reference,
                    recon_roots, recon_depth, recon_end_slots, recon_end_depth)):
                raise RuntimeError(
                    "compiled sentence state must contain tensor "
                    "(recon_ideas, recon_idea_cost, recon_byte_cost, "
                    "recon_truncated, recon_sentence_costs, recon_reference, "
                    "recon_roots, recon_depth, recon_end_slots, "
                    "recon_end_depth) values")
            object.__setattr__(self, "_tensor_pushed_ideas", recon_reference)
            object.__setattr__(self, "_tensor_sentence_roots_live", recon_roots)
            object.__setattr__(self, "_tensor_sentence_roots_depth", recon_depth)
            object.__setattr__(self, "_tensor_final_end_slots", recon_end_slots)
            object.__setattr__(self, "_tensor_final_end_depth", recon_end_depth)
            if self._recon_placement() != "graph":
                # placeholders: the traversal runs after the forward from
                # the published references and roots (see ``runBatch``)
                object.__setattr__(self, "_recon_cost", None)
                object.__setattr__(self, "_recon_completed", False)
            else:
                if getattr(self, "_recon_ideas", None) is not recon_ideas:
                    object.__setattr__(self, "_reconstruction_product", None)
                object.__setattr__(self, "_recon_ideas", recon_ideas)
                object.__setattr__(self, "_recon_idea_cost", recon_idea_cost)
                object.__setattr__(self, "_recon_cost", recon_byte_cost)
                object.__setattr__(self, "_recon_truncated", recon_truncated)
                object.__setattr__(self, "_recon_sentence_costs", recon_sentence_costs)
                object.__setattr__(self, "_recon_completed", bool(self.reconstruct_in_loop))
            result = tuple(result[:11])
        if len(result) == 11:
            # Fold-ladder provenance (Phase 2b): the STM whole slab and the
            # chunk proposal slab/count, published to their owners.
            wholes, prop_slab, prop_count = result[8:]
            if not all(torch.is_tensor(value)
                       for value in (wholes, prop_slab, prop_count)):
                raise RuntimeError(
                    "compiled sentence state must contain tensor "
                    "(wholes, proposals, proposal_count) values")
            stm = getattr(self.conceptualSpace, "stm", None)
            if stm is not None:
                stm._wholes = wholes
            owner = self._concept_owner()
            owner._chunk_prop_slab = prop_slab
            owner._chunk_prop_count = prop_count
            result = tuple(result[:8])
        if len(result) != 8:
            raise RuntimeError(
                "compiled sentence forward returned "
                f"{len(result)} values; expected 4 public values or "
                "4 plus (S, post_depth, trip_count[, sentence_roots"
                "[, wholes, proposals, proposal_count"
                "[, recon_ideas, recon_idea_cost, recon_byte_cost, "
                "recon_truncated, recon_sentence_costs, recon_reference, "
                "recon_roots, recon_depth, recon_end_slots, "
                "recon_end_depth]]])")
        public = tuple(result[:4])
        idea, post_depth, trip_count, sentence_roots = result[4:]
        if not all(torch.is_tensor(value)
                   for value in (
                       idea, post_depth, trip_count, sentence_roots)):
            state_types = tuple(
                type(value).__name__
                for value in (
                    idea, post_depth, trip_count, sentence_roots))
            raise RuntimeError(
                "compiled sentence state must contain tensor "
                "(S, post_depth, trip_count, sentence_roots) values; got "
                f"{state_types}")
        self._stm_single_S = idea
        self._stm_post_depth = post_depth
        self._packed_sentence_roots = sentence_roots
        object.__setattr__(self, "_tensor_peer_trip_count", trip_count)
        return public

    def _ensure_lazy_fullgraph_word_loop(self, width):
        """Return the one complete fullgraph loop for the active W bucket."""
        width = int(width)
        steps = self._compiled_word_steps
        compiled = steps.get(width)
        if compiled is not None:
            return compiled
        source = getattr(self, "_compiled_word_step_sources", {}).get(width)
        compile_fn = getattr(self, "_compiled_word_loop_compile", None)
        if source is None or compile_fn is None:
            raise RuntimeError(
                f"no lazy fullgraph word-loop source is configured for W={width}")
        TheMessage(
            "Canonical fullgraph lowering: compiling complete "
            f"W={width} recurrent word loop (one-time cost for this bucket)")
        compiled = compile_fn(source, verbose=True, fullgraph=True)
        steps[width] = compiled
        return compiled

    def _stage_fixed_residual_part_capacity(self):
        """Present one fixed, masked constituent layout to a W-loop graph.

        ``P`` is an input layout extent, not the PS live-field width: PS/WS
        still reduce their raw constituents into their configured eight live
        locations.  It must nevertheless be static in the compiled outer
        loop.  Marking P dynamic let Inductor create a second, delayed
        specialization when a later sentence exposed a different radix
        spelling, defeating the one-fullgraph-per-W contract.

        Every word is padded with a valid masked identity percept to the
        fixed capacity (16 by default).  No real constituent is discarded.
        A word that cannot be represented by that radix/trie layout fails at
        the eager boundary with its actual width, rather than being truncated
        or silently requesting another full W-loop compilation.  Such a
        failure is the explicit signal to improve the trie/compaction policy,
        not to grow a hidden compilation bucket.
        """
        isp = self.inputSpace
        ids = getattr(isp, "_ar_word_part_ids", None)
        mask = getattr(isp, "_ar_word_part_mask", None)
        offsets = getattr(isp, "_ar_word_part_offsets", None)
        if (not torch.is_tensor(ids) or ids.dim() != 3
                or not torch.is_tensor(mask)
                or tuple(mask.shape) != tuple(ids.shape)):
            return None
        if offsets is not None and (not torch.is_tensor(offsets)
                                    or tuple(offsets.shape) != tuple(ids.shape)):
            raise RuntimeError(
                "serial residual-part offsets do not align with part ids")

        raw_width = int(ids.shape[-1])
        capacity = int(os.environ.get(
            "BASICMODEL_MPS_RESIDUAL_PARTS",
            str(getattr(self, "serial_residual_part_capacity", 16))))
        if capacity < 3:
            raise ValueError(
                "BASICMODEL_MPS_RESIDUAL_PARTS must be at least 3; got "
                f"{capacity}")
        if raw_width > capacity:
            raise RuntimeError(
                "a radix word needs "
                f"{raw_width} residual percepts, beyond the fixed "
                f"compiled P={capacity} contract; refusing to truncate it")
        bucket = capacity

        # A valid physical row (zero) is gathered before the false mask
        # removes it.  ``-1`` would alias the final learnable codebook row
        # during the gather and is therefore not a semantic identity.
        pad_width = bucket - raw_width
        pad_shape = tuple(ids.shape[:-1]) + (pad_width,)
        padded_ids = torch.cat((
            ids,
            torch.zeros(pad_shape, dtype=ids.dtype, device=ids.device)),
            dim=-1)
        padded_mask = torch.cat((
            mask,
            torch.zeros(pad_shape, dtype=torch.bool, device=mask.device)),
            dim=-1)
        padded_offsets = None
        if torch.is_tensor(offsets):
            padded_offsets = torch.cat((
                offsets,
                torch.full(pad_shape, -1, dtype=offsets.dtype,
                           device=offsets.device)), dim=-1)
        isp._ar_word_part_ids = padded_ids
        isp._ar_word_part_mask = padded_mask
        isp._ar_word_part_offsets = padded_offsets

        # Keep the eager PartSpace record shape-coherent with the fixed
        # InputSpace presentation.  These fields must use the same physical
        # P as the source ids; otherwise an apparently static word loop gains
        # a hidden shape guard through the PartSpace staging record.
        ps = self.perceptualSpace
        fwd = getattr(ps, "_forward_input", None)
        if isinstance(fwd, dict):
            B, W = (int(ids.shape[0]), int(ids.shape[1]))
            flat_width = W * raw_width
            flat_bucket = W * bucket

            def _pad_flat(name, fill):
                value = fwd.get(name)
                if (not torch.is_tensor(value) or value.dim() < 2
                        or int(value.shape[0]) != B
                        or int(value.shape[1]) != flat_width):
                    return
                view = value.reshape(B, W, raw_width, *value.shape[2:])
                fill_shape = (B, W, pad_width, *value.shape[2:])
                pad = torch.full(
                    fill_shape, fill, dtype=value.dtype, device=value.device)
                fwd[name] = torch.cat((view, pad), dim=2).reshape(
                    B, flat_bucket, *value.shape[2:])

            # ``indices`` is an id tensor and must remain in range; all
            # structural values use their existing masked/padding sentinel.
            _pad_flat("indices", 0)
            _pad_flat("seed_event", 0.0)
            _pad_flat("word_groups", -1)
            _pad_flat("part_spans", 0)
            _pad_flat("percept_where", -1)
            fwd["word_part_indices"] = padded_ids
            fwd["word_part_mask"] = padded_mask
            fwd["word_part_capacity"] = capacity
        return capacity

    def enable_compiled_step(self):
        """Compile the per-batch forward and route runBatch through it.

        O1 fix: ``ModelFactory.run`` used to ``compile(m)`` the whole
        module and then call ``m.run()``, which delegates to the eager
        ``_orig_mod`` -- so the compiled callable was never invoked
        (dynamo traced 0 frames; every "compiled" run was eager).
        Instead we ``torch.compile`` the ``forward`` *callable* and
        invoke that from ``runBatch``; the eager run/runEpoch
        orchestration stays Python (streaming/staging outside the
        compiled region, per the compile-scoped-to-model design).

        Strict gate where the configured forward is host-island-free: the
        recon-then-eliminate program drove that path to **0 graph breaks**
        (``total graph breaks: 0; graphs: 1``). Configurations with an explicit
        eager island relax ``fullgraph`` so the dense regions can still be
        compiled. The canonical aligned serial path remains strict: its sparse
        concept rows are gathered once before the graph, not inside it.
        """
        from util import compile as _compile
        # MPS compiles by default (2026-06-07): torch 2.12's inductor MPS
        # backend traces the per-batch forward fullgraph just like CPU/CUDA
        # (verified ``Model compiled (inductor, ..., fullgraph=True)`` on
        # ``data/MM_20M_legacy.xml``). The old ``BASICMODEL_MPS_COMPILE`` opt-in gate
        # (eager fallback on MPS, from when torch's MPS fake-tensor device
        # propagation was incomplete) is retired -- use ``MODEL_COMPILE=none``
        # (skip) or ``=eager`` (no inductor) to disable/relax compilation on
        # any device.
        # D8 capture-gate (2026-05-19): pre-warm any LAZY-built caches
        # that the captured forward depends on, so Dynamo never traces
        # their build path. ``_stm_reducer`` resolves the already-wired
        # LanguageLayer child and caches that non-owning reference here,
        # eagerly, before the compile wrapper closes over ``self.forward``.
        # Build every lazy, checkpointed shape before capture. Autoload uses
        # the same helper before loading an existing training checkpoint.
        self._prewarm_checkpoint_shapes()
        # Device-coherence sweep before the trace, against the CANONICAL
        # process device (util.TheDevice -- the single source of truth that
        # ``init_device`` keeps in sync with torch's default device). The lazy
        # reducer build (above) and any module minted during ModelFactory's
        # build-on-CPU phase (``init_device("cpu")`` -> build ->
        # ``init_device(target)`` + ``m.to(target)``) can be left on CPU if it
        # was created after the ``m.to``; the
        # compiled forward's fake-tensor propagation then fails loud
        # ("two different devices mps:0, cpu") where eager might limp. The
        # sweep is an idempotent no-op when already coherent. The per-call
        # re-home in ``_stm_reducer`` stays host-only (a ``torch.device``
        # compare is not traceable).
        self.to(str(TheDevice.get()))
        _ensure_grad_anchors(TheDevice.get())      # before any compiled loop
        # The strict gate holds where the forward traces end to end. A
        # FULL-ROUTER grammar (anything beyond the default-only
        # pi/sigma rules) routes through the host-side chart fires
        # (``_chart_compose_at_C`` / ``_chart_generate_from_stm``,
        # ``@torch.compiler.disable``'d: their rule-id bookkeeping is
        # data-dependent ``.item()`` branching dynamo cannot guard on —
        # the ``Eq(u0, 2)`` UserError on MM_xor's per-stage path). A
        # disabled call is itself a graph break, which fullgraph=True
        # turns into a hard error — so full-router configs compile
        # with tolerated breaks. Default-only configs (MM_20M's
        # bypass never reaches the router loops) keep the strict gate.
        _ws = getattr(self, 'symbolSpace', None)
        _full_router = (_ws is not None and not getattr(
            _ws, '_grammar_is_default_only', True))
        # Slice B: the symbol tower's ``forward_symbol`` is a
        # ``@torch.compiler.disable`` eager island (host-side order-raising
        # readout -- data-dependent dict iteration + SubSpace construction). Like
        # full-router grammar, its disabled call is itself a graph break, so it
        # needs fullgraph relaxed too. ``_host_islands`` gates both.
        _symbol_tower = bool(getattr(self, 'symbol_tower', False))
        # The serial fixed-W recurrence, including its Language plan, has a
        # fullgraph-clean grammar route. Full-router state is represented by
        # the static grammar tensors used by that route; only the separate
        # symbol-tower and sparse indexed-codebook modes below are true outer
        # graph islands.
        _serial_per_word = bool(getattr(
            getattr(self, 'inputSpace', None), '_per_word_enabled', False))
        _sparse_codebook_island = any(
            bool(getattr(
                getattr(_cs, "similarity_codebook", None),
                "sparse_lookup_grad", False))
            for _cs in (getattr(self, "conceptualSpaces", None) or ()))
        _staged_sparse_bank = self._aligned_serial_word_mode()
        _peer_pipeline = bool(getattr(self, "_peer_pipeline_enabled", True))
        _aligned_serial_stage_bodies = bool(
            self._aligned_serial_sparse_bank_mode()
            and getattr(_util, "TheCompileBackend", "none") != "none")
        # K=1/K=2 cells contain the legacy monolithic word body and therefore
        # cannot express the cross-word dependency lanes. Peer mode uses the
        # fixed W-loop graph below; its explicit fallback still compiles the
        # independent numerical PS/WS ladders while leaving the scheduler
        # eager.
        _canonical_word_chunk = bool(
            _aligned_serial_stage_bodies and not _peer_pipeline)
        _host_islands = ((_full_router and not _serial_per_word)
                         or _symbol_tower
                         or (_sparse_codebook_island
                             and not _staged_sparse_bank))
        # torch 2.12 inductor-MPS cannot codegen the FULL-ROUTER
        # forward: the generated Metal references undeclared reduction
        # indices ("use of undeclared identifier 'r0_1'" — an upstream
        # backend bug, reproduced on MM_xor 2026-06-11; MM_20M's
        # default-only forward compiles clean on the same device).
        # Until the upstream fix lands those configs run eager on MPS;
        # CUDA / CPU and default-only MPS configs compile as before.
        # MODEL_COMPILE=none stays the manual override everywhere.
        # MPS eager-skip RETIRED (2026-07-07): the "inductor-MPS miscompiles
        # this forward (NaN)" premise was a test-harness artifact (recon_bench
        # _build_model device incoherence), not a compile bug -- the real
        # ModelFactory path compiles fullgraph=True on MPS and runs clean at
        # ~2.6-6x eager once the recompile churn was fixed (symbol-codebook
        # preallocation, Optimizer device-restore spelling, grad-off
        # diagnostics routed eager, prelude-counter/pre-grow warms). The
        # ``MODEL_COMPILE`` policy governs as everywhere else (DEBUG =
        # none/eager to skip the one-time ~6min MPS compile; PRODUCTION =
        # inductor past the amortization break-even). util.compile's MPS
        # block carries the required codegen workarounds (uint16->ushort,
        # max_fusion_unique_io_buffers, assert disables).
        _fullgraph = ENUM_FULLGRAPH and not _host_islands
        if ENUM_FULLGRAPH and _host_islands:
            TheMessage(
                "fullgraph relaxed: host-island config (full-router grammar, "
                "symbolTower forward_symbol, or sparse indexed codebook is "
                "a tolerated graph break)")
        _word_buckets = tuple(
            int(v) for v in getattr(self, "serial_word_buckets", ()) or ())
        self._compiled_word_chunk_step = None
        self._compiled_word_chunk_active = False
        self._compiled_word_chunk_replaying = False
        self._compiled_word_chunk_trace_active = False
        self._compiled_word_chunk_width = 0
        # Diagnostic only. Read once so the production W-loop never performs
        # an environment lookup or constructs a SubSpaceView while captured.
        self._debug_peer_mutation = (
            os.environ.get("BASICMODEL_DEBUG_PEER_MUTATION", "0") == "1")
        self._compiled_word_loop_compile = None
        self._compiled_word_loop_fullgraph = False
        _compiled_device_type = str(TheDevice.get()).split(":", 1)[0]
        _mps_word_boundary = (
            _aligned_serial_stage_bodies
            and _compiled_device_type == "mps")
        _cuda_fullgraph_word_loop_boundary = (
            _aligned_serial_stage_bodies
            and _compiled_device_type == "cuda")
        _mps_word_loop = os.environ.get(
            "BASICMODEL_MPS_WORD_LOOP_FULLGRAPH", "1").strip().lower() not in (
                "0", "false", "no", "off")
        _mps_word_cell = os.environ.get(
            "BASICMODEL_MPS_WORD_FULLGRAPH", "1").strip().lower() not in (
                "0", "false", "no", "off")
        # The outer graph is the compiler-visible realization of the three
        # cross-word stages: CSSub/PS/WS(w), CSSym/SS(w-1), and CSLang(w-2).
        # The tensor higher-order loop also carries the one grammar register
        # and all CS-owned state; its runtime trip count does not become a
        # Python guard. Do not disable that graph merely
        # because peer mode is selected: doing so leaves PS/WS as the only
        # compiled work and makes the stateful conceptual leg pay host dispatch
        # per word. BASICMODEL_MPS_WORD_LOOP_FULLGRAPH=0 remains the explicit
        # diagnostic/backend fallback.
        _peer_outer_host_island = bool(
            _symbol_tower
            or (_sparse_codebook_island and not _staged_sparse_bank))
        if _peer_pipeline and _peer_outer_host_island:
            # Individual fold ladders are still valid fullgraphs, but these
            # genuinely disabled Symbol/sparse islands cannot be swallowed by
            # the strict outer peer graph. Preserve the eager-scheduler
            # fallback only for those configurations.
            _mps_word_loop = False
            _mps_word_cell = False
            _cuda_fullgraph_word_loop_boundary = False
        if ((_mps_word_boundary and _mps_word_loop)
                or _cuda_fullgraph_word_loop_boundary):
            # The primary production boundary: one fullgraph encompasses the
            # dynamic tensor word loop, both dependency legs, and backward.
            # P and the maximum W are fixed masked layouts; only live words
            # execute. It lowers lazily on first use. On Metal the complete
            # backward still has substantially more live inputs than the old
            # one-word cell, so conservative realization/fusion limits keep
            # generated kernels beneath the 31 constant-buffer cap. CUDA
            # keeps its native Inductor/Triton fusion policy and, with a
            # CUDAGraph-bearing compile mode, captures eligible fixed-shape
            # body partitions for replay.
            if _mps_word_boundary:
                os.environ.setdefault("BASICMODEL_MPS_IOBUF", "8")
                os.environ.setdefault("BASICMODEL_MPS_FUSE", "16")
                os.environ.setdefault("BASICMODEL_MPS_REALIZE", "4")
            self._configure_lazy_fullgraph_word_loops(_compile, _word_buckets)
            self._compiled_step = self.forward
            TheMessage(
                "Canonical fullgraph compile: lazy fused tensor word-loop "
                f"lowering on {_compiled_device_type} with fixed capacity "
                "and residual-part axes")
        elif _mps_word_boundary and _mps_word_cell:
            # Fullgraph training kernel for the actual recurrent word tick.
            # The fixed residual-part bucket below removes the old 3..8192
            # symbolic P range, which was the dominant source of the earlier
            # multi-minute compile. K=1 is the safe default; K=2 is a
            # fullgraph packing option for MPS benchmarking once the common
            # residual buckets are warm.
            _mps_chunk_width = int(os.environ.get(
                "BASICMODEL_MPS_WORD_CHUNK", "1"))
            if _mps_chunk_width not in (1, 2):
                raise ValueError(
                    "BASICMODEL_MPS_WORD_CHUNK must be 1 or 2; got "
                    f"{_mps_chunk_width}")
            os.environ.setdefault("BASICMODEL_MPS_IOBUF", "12")
            os.environ.setdefault("BASICMODEL_MPS_FUSE", "32")
            self._compiled_word_steps = {}
            self._compiled_word_chunk_step = _compile(
                (self._aligned_word_chunk1 if _mps_chunk_width == 1
                 else self._aligned_word_chunk2),
                verbose=True, fullgraph=True)
            self._compiled_word_chunk_active = True
            self._compiled_word_chunk_width = _mps_chunk_width
            self._compiled_step = self.forward
            TheMessage(
                "Canonical MPS fullgraph compile: reusable K="
                f"{_mps_chunk_width} word cell with fixed residual-part "
                "buckets")
        elif _mps_word_boundary:
            # Compile native PS synthesis and WS property reads separately.
            # The whole word cell also mutates carriers, performs sparse
            # lookup, and advances STM and grammar state; those boundaries
            # remain eager while the numerical reads use fullgraph capture.
            self._compiled_word_steps = {}
            self._enable_fullgraph_perception(_compile)
            self._compiled_step = self.forward
            TheMessage(
                "Canonical MPS compile: native PS and WS reads "
                "fullgraph=True with eager state adapter")
        elif _canonical_word_chunk:
            # Compile one reusable, fixed K=2 word cell.  The sentence shell
            # remains eager: it stages two-column views, replays this callable,
            # and installs the returned contributions in sentence order.  In
            # particular this avoids asking Inductor to lower four W-unrolled
            # graphs whose compile time scales with 16/32/64/128 words.
            self._compiled_word_steps = {}
            self._compiled_word_chunk_step = _compile(
                self._aligned_word_chunk2, verbose=True, fullgraph=True)
            self._compiled_word_chunk_active = True
            # A non-None sentinel makes runBatch perform the ordinary eager
            # lexical/sparse-bank staging.  The selected outer callable is the
            # bound eager forward; only the two-word cell above is compiled.
            self._compiled_step = self.forward
            TheMessage(
                "Canonical aligned serial compile: reusable K=2 word cell "
                "with eager sentence adapter")
        elif _peer_pipeline and _serial_per_word:
            self._compiled_word_steps = {}
            # CPU's fallback keeps the scheduler eager and compiles the
            # independent numerical bodies. MPS takes the W-loop branch above,
            # where the same fixed FIFO is part of the fullgraph.
            if _aligned_serial_stage_bodies:
                self._enable_fullgraph_perception(_compile)
            self._compiled_step = self.forward
            TheMessage(
                "Peer pipeline: static PS/WS stage bodies compiled separately; "
                "legacy compatibility scheduler remains outside fullgraph "
                "capture")
        elif (_serial_per_word and len(_word_buckets) > 1):
            # Four DISTINCT CODE OBJECTS give Dynamo/Inductor four stable,
            # packed static loop graphs. A closure factory is insufficient:
            # its products share ``__code__``, so Dynamo treats W=32 as a
            # recompile of W=16 even if their function identities/names differ.
            self._compiled_word_steps = {}

            def _forward_W16(input_data):
                slab = self.inputSpace._ar_embedded_N
                if slab is not None and int(slab.shape[1]) != 16:
                    raise RuntimeError(
                        f"compiled W=16 bucket received a W="
                        f"{int(slab.shape[1])} staged slab")
                return self.forward(input_data)

            def _forward_W32(input_data):
                slab = self.inputSpace._ar_embedded_N
                if slab is not None and int(slab.shape[1]) != 32:
                    raise RuntimeError(
                        f"compiled W=32 bucket received a W="
                        f"{int(slab.shape[1])} staged slab")
                return self.forward(input_data)

            def _forward_W64(input_data):
                slab = self.inputSpace._ar_embedded_N
                if slab is not None and int(slab.shape[1]) != 64:
                    raise RuntimeError(
                        f"compiled W=64 bucket received a W="
                        f"{int(slab.shape[1])} staged slab")
                return self.forward(input_data)

            def _forward_W128(input_data):
                slab = self.inputSpace._ar_embedded_N
                if slab is not None and int(slab.shape[1]) != 128:
                    raise RuntimeError(
                        f"compiled W=128 bucket received a W="
                        f"{int(slab.shape[1])} staged slab")
                return self.forward(input_data)

            def _forward_W256(input_data):
                slab = self.inputSpace._ar_embedded_N
                if slab is not None and int(slab.shape[1]) != 256:
                    raise RuntimeError(
                        f"compiled W=256 bucket received a W="
                        f"{int(slab.shape[1])} staged slab")
                return self.forward(input_data)

            def _forward_W512(input_data):
                slab = self.inputSpace._ar_embedded_N
                if slab is not None and int(slab.shape[1]) != 512:
                    raise RuntimeError(
                        f"compiled W=512 bucket received a W="
                        f"{int(slab.shape[1])} staged slab")
                return self.forward(input_data)

            _fixed_sources = {
                16: _forward_W16,
                32: _forward_W32,
                64: _forward_W64,
                128: _forward_W128,
                256: _forward_W256,
                512: _forward_W512,
            }
            unsupported = [
                width for width in _word_buckets
                if width not in _fixed_sources]
            if unsupported:
                raise ValueError(
                    "compiled serialWordBuckets supports exactly widths "
                    f"16,32,64,128,256,512; got unsupported {unsupported}")
            object.__setattr__(
                self, "_compiled_word_step_sources", _fixed_sources)
            for _width in _word_buckets:
                self._compiled_word_steps[int(_width)] = _compile(
                    _fixed_sources[int(_width)], verbose=True,
                    fullgraph=_fullgraph)
            self._compiled_step = self._compiled_word_steps[
                max(_word_buckets)]
        else:
            self._compiled_word_steps = {}
            self._compiled_step = _compile(
                self.forward, verbose=True, fullgraph=_fullgraph)

        _cuda_graph_mode = str(
            getattr(_util, "TheCompileMode", "default"))
        self._brick_compiled = bool(
            _compiled_device_type == "cuda"
            and self._compiled_word_loop_fullgraph
            and _cuda_graph_mode in ("reduce-overhead", "max-autotune"))
        self._brick_cuda_graph_mode = (
            _cuda_graph_mode if self._brick_compiled else None)

    def _start_spaces_for_forward(self):
        self._packed_prediction_drained = False
        for space in self.spaces:
            if hasattr(space, 'Start'):
                space.Start()
        self._spaces_started_for_forward = True

    @_sentence_query_mask
    def forward(self, inputData):
        """Read through the common sentence driver; raw calls never optimize."""
        if not getattr(self, '_sentence_run_active', False) and hasattr(self, 'inputSpace'):
            from Occurrence import stage_sources
            source = getattr(inputData, '_sentence_source', None)
            split, prepared = source if source is not None else ('train', None)
            stage_sources(self, split, prepared, inputData)
            self._advance_when_time()
        seen_books = set()
        for cs in getattr(self, 'conceptualSpaces', ()):
            cb = cs.similarity_codebook
            derived = getattr(cb, 'mereology', None)
            if derived is not None and id(cb) not in seen_books:
                derived.begin_forward()
                seen_books.add(id(cb))
        own_context = self.word_brackets and not getattr(self, '_sentence_run_active', False)
        context = self._sentence_run(training=False) if own_context else nullcontext()
        with context:
            external_start = bool(getattr(self, '_spaces_started_for_forward', False))
            if not external_start:
                self._start_spaces_for_forward()
            try:
                return self._forward_per_stage(inputData)
            finally:
                self._spaces_started_for_forward = False

    def _what_memory(self):
        """Return SymbolSpace's one interaction owner and apply its credit mode."""
        symbol_space = getattr(self, "symbolSpace", None)
        if symbol_space is None:
            return None
        memory = getattr(symbol_space, "what_memory", None)
        mode = getattr(self, "what_thinking_detach", None)
        if memory is not None and mode is not None and hasattr(memory, "detach_mode"):
            if memory.detach_mode != mode:
                memory.detach_mode = mode
        return memory

    @staticmethod
    def _what_execution_parts(execution):
        """Read the established forward tuple without changing its values."""
        if execution is None:
            return None, None, None
        if hasattr(execution, "outputPred"):
            return (getattr(execution, "forwardInput", None),
                    getattr(execution, "symbols", None),
                    getattr(execution, "outputPred", None))
        if isinstance(execution, (tuple, list)) and len(execution) >= 3:
            return execution[0], execution[1], execution[2]
        raise TypeError(
            "Model.what executor must return the established forward tuple "
            "or BatchResult")

    @staticmethod
    def _what_row(value, row, count):
        if (count > 1 and torch.is_tensor(value) and value.dim() > 0
                and value.shape[0] >= count):
            return value[row:row + 1]
        return value

    @staticmethod
    def _what_representation_summary(values, *, device, dtype):
        """Summarize the latest tensor representation without a host sync."""
        value = next((candidate for candidate in reversed(tuple(values))
                      if candidate is not None), None)
        if not torch.is_tensor(value) or value.numel() == 0:
            return torch.zeros(4, device=device, dtype=dtype)
        flat = value.detach().to(device=device, dtype=dtype).reshape(-1)
        return torch.stack((
            flat.mean(),
            flat.abs().mean(),
            flat.square().mean().sqrt(),
            flat.abs().amax(),
        ))

    def _capture_understanding(self, execution):
        """Snapshot the logical products of the forward that just ran.

        What spec Step 1: the live perceptual context (the activated parts
        and wholes), the terminal conceptual state (the same live carrier
        ``_reconstruction_seed`` reads), the symbolic state, and the
        routing/mask handles the inverse needs.  The pre-mask input and any
        dataset answer are deliberately absent: they are scoring targets
        the caller keeps, never carriers.  The established forward tuple is
        attached as the compatibility adapter.
        """
        # what() consumes the compiled result before runBatch's compatibility
        # publication. Attribute-only escapes may have been dropped by Dynamo.
        if isinstance(execution, (tuple, list)) and len(execution) > 4:
            self._publish_compiled_sentence_state(execution)
        _forward_input, symbols, _produced = self._what_execution_parts(
            execution)
        percept_sub = getattr(getattr(self, "perceptualSpace", None),
                              "subspace", None)
        try:
            perceptual = (percept_sub.materialize()
                          if percept_sub is not None
                          and hasattr(percept_sub, "materialize") else None)
        except (RuntimeError, AttributeError, TypeError):
            perceptual = None
        try:
            conceptual = self._reconstruction_seed()
        except (AttributeError, RuntimeError, TypeError):
            conceptual = None
        # Forward-local binding carriers the inverse consumes: the grammar
        # merge glue caches the N-halving difference of each stage and
        # ``GrammarMergeGlue.reverse`` clears it after use, so a second
        # reconstruction of the same understanding would otherwise walk
        # without it.  Held here and reinstalled by ``reconstruct()``.
        merge_diffs = tuple(
            getattr(stage["merge"], "_merge_diff", None)
            if "merge" in stage else None
            for stage in (getattr(self, "body_stages", None) or ()))
        carriers = {
            "ir_mask_positions": getattr(self, "_ir_mask_positions", None),
            "terminal_idea": conceptual,
            "combine_last_cs_sub": getattr(self, "_combine_last_cs_sub", None),
            "merge_diffs": merge_diffs,
        }
        if not self.word_brackets and self.concept_binding == 'aligned':
            live = self._combine_last_cs_sub
            evidence = getattr(live, '_concept_activations', None)
            carriers = {'ir_mask_positions': carriers['ir_mask_positions'], 'field':
                ConceptualField(live._concept_ids, evidence,
                    live._concept_where, live._concept_when,
                    self.conceptualSpaces[0]._percept_field) if evidence is not None else None}
        # The answer path's seed (spec 5.3): on the serial grammar path the
        # resolved input symbol is the grammar's ROOT IDEA (the STM-folded
        # S in the terminal conceptual state), which varies with the
        # sentence; the ``symbols`` tensor there is the symbol-space
        # activation over a codebook with almost no rows at init and is
        # the same for every sentence (test_output_path_supervised).  The
        # parallel path keeps ``symbols``.
        answer_seed = None
        if (bool(getattr(self, "word_brackets", False)) and torch.is_tensor(conceptual)
                and torch.is_tensor(symbols) and conceptual.dim() == 3
                and symbols.dim() == 3 and conceptual.shape[-1] == symbols.shape[-1]):
            answer_seed = conceptual
        sentence_states, sentence_fields = (self._capture_sentence_end_states()
                                             if self.word_brackets else ((), {}))
        input_reconstruction = self._complete_input_reconstruction()
        return Understanding(
            perceptual_context=perceptual,
            conceptual_state=conceptual,
            symbolic_state=symbols,
            reconstruction_carriers=carriers,
            execution=(tuple(execution[:4])
                       if isinstance(execution, (tuple, list)) else execution),
            answer_seed=answer_seed,
            sentence_states=sentence_states,
            sentence_records=tuple(getattr(self, '_sentence_understandings', {}).values()),
            sentence_fields=sentence_fields,
            input_reconstruction=input_reconstruction,
        )

    @_sentence_query_mask
    def _complete_input_reconstruction(self):
        """Own the tied input result before another path can change staging."""
        if not getattr(self, "reconstruct_in_loop", False):
            return None
        cached = getattr(self, "_reconstruction_product", None)
        if cached is not None:
            return cached
        if not getattr(self, "_recon_completed", False):
            S = getattr(self, "_stm_single_S", None)
            reference = getattr(self, "_tensor_pushed_ideas", None)
            roots = getattr(self, "_tensor_sentence_roots_live", None)
            if not all(torch.is_tensor(value) for value in (S, reference, roots)):
                raise RuntimeError("tied reconstruction requires completed sentence state")
            depth = getattr(self, "_tensor_sentence_roots_depth", None)
            end = getattr(self, "_tensor_final_end_slots", None)
            end_depth = getattr(self, "_tensor_final_end_depth", None)
            if not (torch.is_tensor(end) and torch.is_tensor(end_depth)):
                end, end_depth = self._final_end_state(S, getattr(self, "_stm_post_depth", None))
            values = self._compiled_reconstruct()(S, reference, roots, depth, end, end_depth)
            for name, value in zip(("_recon_ideas", "_recon_idea_cost", "_recon_cost",
                                    "_recon_truncated", "_recon_sentence_costs"), values):
                object.__setattr__(self, name, value)
            object.__setattr__(self, "_recon_completed", True)
        ideas = self._recon_ideas
        with self._synthesis_guard():
            identity = getattr(getattr(self.perceptualSpace, 'percept_store', None), 'identity', None)
            if identity is not None and self.word_brackets:
                # The recovered leaves are already numerical directions.
                # A codebook-backed carrier would quantize them a second time.
                carrier = SubSpaceView.snapshot(ideas, owner=self.conceptualSpace)
            else:
                carrier = self.conceptualSpace.subspace.carrier_like()
                carrier.set_event(ideas)
            surface = self._reverse_input_surface(carrier)
            event = surface.materialize() if hasattr(surface, "materialize") else surface
            if not torch.is_tensor(event):
                raise RuntimeError("tied reconstruction produced no input surface")
            event = event.clone()
        result = InputReconstruction(
            ideas, event, self._recon_idea_cost, self._recon_cost,
            self._recon_truncated, self._recon_sentence_costs)
        object.__setattr__(self, "_reconstruction_product", result)
        return result

    def _reverse_input_surface(self, carrier, *, field=None):
        """Realize recovered input ideas through the shared numerical inverse.

        The input's grammar traversal is already complete. No generate policy
        or free chart expansion belongs in this path.
        """
        identity = getattr(getattr(self.perceptualSpace, 'percept_store', None), 'identity', None)
        if identity is not None and self.word_brackets:
            # The grammar inverse has already recovered word leaves. Resolve
            # their directions in the invocation's dictionary, then read each
            # sparse identity through its row; no learned byte inverse remains
            # at rung zero. Neither source bytes nor a saved leaf trace select
            # the spelling.
            ideas = carrier.materialize()
            bank, valid = self._reconstruction_basis_snapshot(ideas)
            forms = self.inputSpace._ar_concept_lookup_atoms
            from SentenceUnderstanding import readback_scores
            scores = torch.stack([readback_scores(ideas[:, w], bank, valid.to(ideas),
                percept_width=identity.width) for w in range(ideas.shape[1])], dim=1)
            score, selected = scores.max(-1)
            known = (score > 1 - 1e-5) & (ideas.norm(dim=-1) > 0)
            surfaces = []
            for b in range(len(ideas)):
                words = [identity.read(forms[b, int(selected[b, w]), :identity.width])
                         for w in range(ideas.shape[1]) if bool(known[b, w])]
                surfaces.append(b' '.join(word for word in words if word is not None))
            width = max(1, max(map(len, surfaces), default=0))
            event = torch.zeros(len(surfaces), 1, width, device=ideas.device, dtype=torch.long)
            for b, raw in enumerate(surfaces):
                event[b, 0, :len(raw)] = torch.tensor(list(raw), device=ideas.device)
            return SubSpaceView.snapshot(event, owner=self.inputSpace)
        carrier = (self._reverse_body(carrier) if field is None else
                   self._reverse_body(carrier, field=field))
        concepts = getattr(carrier, "_concepts_recon", None)
        carrier = self._reverse_perceptual(carrier)
        if concepts is not None and carrier is not None:
            object.__setattr__(carrier, "_concepts_recon", concepts)
        return self.inputSpace.reverse(carrier)

    @_sentence_query_mask
    def _execute_input_sentence(self, input_data, executor=None):
        """Run caller-supplied sentence execution under the same phase mask."""
        return (executor or self.forward)(input_data)

    def understand(self, input_data, *, executor=None):
        """One bottom-up analysis pass returning its ``Understanding``."""
        execution = self._execute_input_sentence(input_data, executor)
        understanding = self._capture_understanding(execution)
        self._last_understanding = understanding
        return understanding

    @_sentence_query_mask
    def reverseReconstruct(self, understanding, *, target=None, train=False, registry=None):
        """Reconstruct the presented input from ``understanding`` (Step 2).

        Named ``reverseReconstruct`` because it is the dual of ``forward()``
        along the input-associated inverse path (``reverseOutput`` is the
        other dual, along the answer path).  The top-down inverse of the
        analysis: terminal conceptual state ->
        inverse conceptual/symbolic path -> inverse perceptual path ->
        ``InputSpace``.  ``Space.reverse()`` keeps its algebraic meaning;
        this orchestrates it and owns the result.  Returns
        ``(reconstructed_event, input_reconstruction)``; the cost is ``None``
        unless ``target`` (the forward input carrier or event) is supplied,
        and the target is used only for scoring, never as a carrier.
        Tied mode consumes the completed Understanding-owned surface. Its
        optional event score is a diagnostic; runBatch trains the owned byte
        objective and does not add this event score a second time. Grammar-free
        paths retain their perceptual inverse below.
        """
        if not isinstance(understanding, Understanding):
            raise TypeError("reconstruct expects an Understanding")
        owned = understanding.input_reconstruction
        if owned is not None:
            # Readiness is explicit: a zero-valued result is still complete.
            event = owned.event.clone()
            target_event = target.materialize() if hasattr(target, "materialize") else target
            score = (self._reverse_event_loss(event, target_event,
                score_when=not (self.word_brackets and getattr(self.inputSpace, '_per_word_enabled', False)),
                registry=registry, name='reconstruction_reverse')
                     if torch.is_tensor(target_event) else None)
            return event, score
        if self.reconstruct_in_loop:
            raise RuntimeError("tied reconstruction requires an owned completed result")
        train = bool(train)
        # Install this understanding's forward-local carriers so the walk is
        # a function of the understanding, not of whichever path ran last.
        merge_diffs = understanding.reconstruction_carriers.get("merge_diffs")
        stages = getattr(self, "body_stages", None) or ()
        if merge_diffs is not None and len(merge_diffs) == len(stages):
            for stage, diff in zip(stages, merge_diffs):
                if "merge" in stage:
                    stage["merge"]._merge_diff = diff
        rev_sub = None
        rev_ev = None
        if rev_ev is None:
            terminal_idea = understanding.conceptual_state
            # Evaluation decode from the idea (``reconstructFromIdea``): the
            # ended sentence is unwound through the recorded derivation
            # with the tied inverses (``_reconstruct_sentences``: the
            # end state's slots, the closing un-folds, one pop per word),
            # and the recovered per-word ideas are the event the reverse
            # chain realises.  The eager trace replay and the exact
            # leaves teacher it replaced are retired (2026-09-13).
            if (terminal_idea is not None and not train
                    and bool(getattr(self, 'reconstruct_from_idea', False))):
                unfolded = self._recovered_word_ideas(terminal_idea[:, 0, :])
                if unfolded is not None:
                    terminal_idea = unfolded   # [B, W, D_c]
            if terminal_idea is not None:
                field = understanding.reconstruction_carriers.get('field')
                if field is None:
                    self.conceptualSpace.commit_event(terminal_idea)
                    rev_sub = self._reverse_input_surface(self.conceptualSpace.subspace)
                else:
                    carrier = self.conceptualSpace.subspace.carrier_like()
                    carrier.set_event(terminal_idea)
                    rev_sub = self._reverse_input_surface(carrier, field=field)
            rev_ev = (rev_sub.materialize()
                      if rev_sub is not None
                      and hasattr(rev_sub, 'materialize')
                      else None)
        cost = None
        if target is not None:
            fwd_ev = (target.materialize()
                      if hasattr(target, 'materialize') else target)
            if (rev_ev is not None and fwd_ev is not None
                    and torch.is_tensor(rev_ev) and torch.is_tensor(fwd_ev)
                    and rev_ev.dim() == fwd_ev.dim() and rev_ev.dim() == 3):
                # Band-aware seam: the input event's where/when widths, not ModelLoss's (0,0) OutputSpace band.
                # Native surface bytes are decoded by activity. Score the
                # continuous native rows produced by that same attribution.
                score_event = getattr(rev_sub, '_reconstruction_percepts', rev_ev)
                cost = self._reverse_event_loss(score_event, fwd_ev,
                    score_when=not (self.word_brackets and getattr(self.inputSpace, '_per_word_enabled', False)),
                registry=registry, name='reconstruction_reverse')
                # Spec section 11: an EXACT, unmasked inverse identity has zero
                # error and therefore no learning signal.  Flag it rather than
                # let a perfect round trip pass as reconstruction learning.
                masked = understanding.reconstruction_carriers.get(
                    "ir_mask_positions") is not None
                identity = bool(float(cost.detach()) == 0.0) and not masked
                self._reconstruction_identity_flag = identity
                if identity:
                    self._warn_zeroed_channel(
                        "reconstruction_identity",
                        "input reconstruction is an exact unmasked identity: "
                        "zero cost carries no learning signal (mask or "
                        "degrade the input to create one)")
        return rev_ev, cost

    def resolveAnswer(self, understanding, question, *, score=None):
        """Prepare an owned answer before any surface realization.

        Question resolution and conceptual thinking belong at this boundary.
        The returned derivation retains the current step's gradients and can
        be realized again without executing another query. Desired answers
        are accepted only by the later scoring path.
        """
        if not isinstance(understanding, Understanding):
            raise TypeError("answer resolution expects an Understanding")
        questions = question_batch(question)
        if not questions:
            raise ValueError("answer resolution requires at least one question")
        if self.reconstruct_in_loop and understanding.input_reconstruction is None:
            raise RuntimeError("query boundary requires completed input reconstruction")
        with self._query_boundary_scope(self._completed_query_rows(understanding)):
            try:
                self._costed_thought_outputs={}
                return self._resolve_answer(understanding, questions, **({} if score is None else {'score':score}))
            finally:
                # A train batch keeps live ordinary records until its sole
                # optimizer step.  Evaluation has no subsequent step, so it
                # closes only completed ordinary episodes before another
                # answer can begin; unfinished failures remain fail-loud.
                if not self.training:
                    self._end_finished_selected_thought_episodes()

    def _resolve_answer(self, understanding, question, *, score=None, selected_thoughts=None):
        """Resolve owned concepts for an answer, before question conditioning.

        The indexed path selects the current or recalled completed field and
        materialises its full-width ideas once. Thinking transforms those ideas;
        no dense symbol event is needed. Future answers remain unresolved until
        a conceptual predictor exists. Topologies without row fields retain
        their established dense-state resolution as a compatibility path.
        """
        questions = question_batch(question)
        first = questions[0] if questions else None
        current_fields = understanding.sentence_states
        symbolic = understanding.symbolic_state
        seed = getattr(understanding, "answer_seed", None)
        if torch.is_tensor(seed):
            symbolic = seed
        if current_fields:
            B = len(current_fields)
        elif torch.is_tensor(symbolic):
            B = int(symbolic.shape[0])
        else:
            raise RuntimeError("cannot resolve an answer without a completed field or symbolic state")
        per_row = [questions[min(b, len(questions) - 1)] for b in range(B)]
        temporal = tuple(q.context_values() for q in questions)
        # Direct ``answer_query`` remains an explicit compatibility API, but a
        # normal answer boundary is grammar-owned.  An unselected field is
        # therefore unresolved here; raw surface text may not choose the
        # legacy controller behind the grammatical trace.
        row_sources, fields = [], []
        resolved_all = True
        if current_fields:
            template = next((p.end_state for p in current_fields if p is not None), None)
            if template is None:
                template = next(self.parameters())
            base = template.new_zeros(B, 3, int(self.conceptualSpace.stm.concept_dim))
            for b, q in enumerate(per_row):
                source = "identity"
                entry = current_fields[b]
                if q.relation is WhatRelation.PAST:
                    k = abs(int(q.offset))
                    history = self._recall_sentence_history().get(b)
                    entry = (history[-k] if history is not None
                             and k >= 1 and len(history) >= k else None)
                    source = "recall" if entry is not None else "identity:cold-memory"
                elif q.relation is WhatRelation.FUTURE:
                    entry, source = None, "prediction"
                resolved_all = resolved_all and entry is not None
                fields.append(entry)
                row_sources.append(source)
            answer = torch.stack([base[b] if field is None else field.end_state.to(base)
                                  for b, field in enumerate(fields)])
        else:
            answer = symbolic.clone()
            for b, q in enumerate(per_row):
                source = "identity"
                if q.relation in (WhatRelation.PAST, WhatRelation.FUTURE):
                    rep = self._temporal_answer_rep_row(
                        q.relation, q.offset, b, symbolic.shape[-1])
                    if rep is None:
                        source, resolved_all = "identity:cold-memory", False
                    else:
                        answer[b:b + 1] = self._install_root_slot(symbolic[b:b + 1], rep)
                        source = "recall" if q.relation is WhatRelation.PAST else "prediction"
                row_sources.append(source)
        # Only a completed interrogative opens the normal controller episode.
        choose_thoughts=selected_thoughts is None
        selected_thoughts=() if choose_thoughts else selected_thoughts
        if current_fields and choose_thoughts:
            try:
                selected_budget = int(getattr(
                    self, "attention_budget", 32) or 0)
            except (TypeError, ValueError):
                selected_budget = 32
            selected_budget = max(0, selected_budget)
            memory = self._what_memory()
            # Never replace another live episode on the chronological owner.
            if memory is None or not any(
                    getattr(memory, "in_episode", lambda _row: False)(row)
                    for row in range(len(fields))):
                costed={}
                def thought_cost(row,result):
                    # No query is rerun to adapt an already checked result.
                    held=self._resolve_answer(understanding,questions,selected_thoughts=((row,result),))
                    constructed=self.reverseOutput(understanding,held,score=score)
                    costed[id(result.records)]=constructed
                    return score(constructed)[row]
                selected_thoughts = self._run_selected_sentence_thoughts(
                    tuple(fields), work_budget=selected_budget,**({} if score is None else {'score':thought_cost}))
                for row,result in (selected_thoughts if costed else ()):
                    if id(result.records) in costed:
                        self._costed_thought_outputs[row]=costed[id(result.records)]
        selected_rows = tuple(row for row, _result in selected_thoughts)
        # All checked result kinds have an explicit target-free adapter.
        # Sets preserve every member as separate role triples; no averaging,
        # first-member shortcut or post-execution codebook read is allowed.
        selected_answer_rows = list(answer.unbind(0))
        answer_meanings = [() for _ in range(B)]
        selected_answer_applied = False
        # A declarative relation has the same full semantic operands as an
        # interrogative one. Its lossy numerical root is not an answer seed.
        # Recover only its actual selected completed field; this performs no
        # extra parse, learned classification, thought execution or LTM write.
        language = getattr(self, "languageSpace", None)
        registry = getattr(self, "grammatical_thoughts", None)
        if language is not None and registry is not None:
            for row, entry in enumerate(fields):
                if row in selected_rows or entry is None:
                    continue
                meaning = entry.meaning
                if meaning is None or meaning.mode == "interrogative":
                    continue
                answer_meanings[row] = (meaning,)
                selected_answer_rows[row] = meaning.roles.to(answer)
                selected_answer_applied = True
        for row, selected in selected_thoughts:
            checked = getattr(selected, "result", None)
            if not isinstance(checked, ThoughtResult):
                continue
            items = thought_answer_meanings(selected)
            answer_meanings[row] = items
            if items:
                selected_answer_rows[row] = torch.cat(tuple(
                    item.roles.to(device=answer.device, dtype=answer.dtype)
                    for item in items), dim=0)
            else:
                selected_answer_rows[row] = torch.zeros_like(selected_answer_rows[row])
                if checked.incomplete or checked.result_kind != "set":
                    resolved_all = False
            row_sources[row] = ("thought" if checked.result_kind == "truth"
                                else "thought-" + checked.result_kind)
            selected_answer_applied = True
        if selected_answer_applied:
            slots = max(int(item.shape[0]) for item in selected_answer_rows)
            answer = torch.stack(tuple(F.pad(item, (0, 0, 0, slots - item.shape[0]))
                                       for item in selected_answer_rows))
        distinct = set(row_sources)
        source = row_sources[0] if len(distinct) == 1 else "mixed"
        steps, step_trace, exact_steps = (), (), ()
        # Completed interrogatives alone open controller episodes. Other
        # rows retain their prepared seed without a second lexical selector.
        context, _detail = self._what_grammar_context(
            questions, device=answer.device, dtype=answer.dtype)
        references = self._select_perceptual_bindings(understanding)
        trace = ({"operation": f"resolve:{source}",
                  "relation": first.relation.value,
                  "offset": int(first.offset),
                  "row_sources": tuple(row_sources), "temporal": temporal,
                  "conditioned": "conceptual", "bindings": references},)
        if selected_thoughts:
            trace += tuple({
                "operation": "selected_query",
                "row": row,
                "semantic_id": result.evidence.get("semantic_id"),
                "result_kind": result.evidence.get("result_kind"),
                "signature": result.evidence.get("query_signature"),
                "support_true": result.evidence["support_true"],
                "support_false": result.evidence["support_false"],
                "work": result.work.spent,
                "incomplete": result.evidence.get("incomplete", ()),
            } for row, result in selected_thoughts)
        return AnswerDerivation(
            answer_symbol=None if current_fields else answer,
            conceptual_answer=answer if current_fields else None,
            grammar_trace=trace + tuple(step_trace),
            bindings={"perceptual_slots": references},
            synthesis_references=references, sentence_location=0, prefix=None,
            resolved=resolved_all, source=source, row_sources=tuple(row_sources),
            step=steps, exact_steps=exact_steps, sentence_states=tuple(fields),
            conditioning_context=context, questions=questions,
            selected_thoughts=selected_thoughts,
            answer_meanings=tuple(answer_meanings))

    # -- retained memory utilities and normal thought accounting ------------
    WHAT_STEP_MAX_CANDIDATES = 32
    WHAT_STEP_COST = 0.01          # per actual shared work unit
    WHAT_FORCED_COST = 0.1         # per forced closure

    def _what_or_think(self, questions, input_data, *, executor, record, score=None):
        """One understanding and answer boundary per batch presentation."""
        return self.what(questions, input_data, executor=executor, record=record, score=score)

    def _end_what_episodes(self):
        """Close every row's episode (detaching its slots under ``episode``
        mode) -- called after the optimizer step (spec 8.2)."""
        memory = self._what_memory()
        if memory is None or not hasattr(memory, "end_what_episode"):
            return 0
        rows = int(getattr(memory, "batch", 0) or getattr(memory, "_batch", 0) or 0)
        detached = 0
        for b in range(rows):
            if not hasattr(memory, "in_episode") or memory.in_episode(b):
                detached += int(memory.end_what_episode(b) or 0)
        self._what_policy_records = []
        self._selected_thought_policy_records = []
        return detached

    def _thinking_enabled(self):
        """True when an episode may take more than one iteration."""
        return int(getattr(self, "what_thinking_iterations", 1) or 1) > 1

    def _ltm_attention(self, width, key_width, *, device, dtype):
        """The learned conditioning of the root answer idea on the row's
        LTM OUTPUT representations (spec 7.3): a single-head attention
        whose query is the root slot and whose keys / values are the
        stored responses, with a ZERO-initialised output projection so the
        answer path starts independent of memory.  Built on first use."""
        module = getattr(self, "ltm_attention", None)
        if (module is None or int(module["query"].in_features) != int(width)
                or int(module["key"].in_features) != int(key_width)):
            module = nn.ModuleDict({
                "query": nn.Linear(int(width), int(width), bias=False),
                "key": nn.Linear(int(key_width), int(width), bias=False),
                "value": nn.Linear(int(key_width), int(width), bias=False),
                "out": nn.Linear(int(width), int(width), bias=False),
            })
            nn.init.zeros_(module["out"].weight)
            module = module.to(device=device, dtype=dtype)
            self.ltm_attention = module
        return module

    def _attend_ltm(self, root, outputs):
        """``root`` ``[D]`` attends over ``outputs`` (a list of stored
        response tensors); returns the delta to add to the root slot."""
        if not outputs:
            return None
        keys = []
        for value in outputs:
            if torch.is_tensor(value) and value.numel() > 0:
                keys.append(value.to(device=root.device, dtype=root.dtype).reshape(-1))
        if not keys:
            return None
        width = min(k.numel() for k in keys)
        stack = torch.stack([k[:width] for k in keys])          # [K, W]
        module = self._ltm_attention(root.numel(), width,
                                     device=root.device, dtype=root.dtype)
        q = module["query"](root)                                # [D]
        k = module["key"](stack)                                 # [K, D]
        v = module["value"](stack)                               # [K, D]
        weights = torch.softmax(k @ q / float(root.numel()) ** 0.5, dim=0)
        return module["out"](weights @ v)

    def _presented_surface(self, question):
        """The PRESENTED surface of ``question`` (its prompt, else the
        dataset input at its ``where``): the input side only."""
        prompt = getattr(question, "prompt", None)
        if isinstance(prompt, str) and prompt.strip():
            return prompt
        data = getattr(getattr(self, "inputSpace", None), "data", None)
        if data is None or not hasattr(data, "presentation"):
            return None
        try:
            presentation = data.presentation(question, include_desired=False)
        except (KeyError, IndexError, TypeError, ValueError):
            return None
        value = presentation.input
        return value if isinstance(value, str) else None

    def _begin_referents(self, questions):
        """The REFERENTS each row may open a subquestion about: the distinct
        words of its presented surface, as the lexicon segments them
        (``Meronomy.word_spans``), in surface order.  Purely lexical: no
        structure is read from the surface."""
        import Meronomy
        referents = {}
        self._what_referents = referents
        if not self._thinking_enabled():
            return referents
        for b, question in enumerate(questions):
            surface = self._presented_surface(question)
            if not surface:
                continue
            raw = surface.encode("ascii", errors="replace")
            words = []
            for span in Meronomy.word_spans(raw):
                a, z = int(span[0]), int(span[1])
                word = raw[a:z].decode("ascii", errors="replace")
                if word and word not in words:
                    words.append(word)
            referents[b] = tuple(words)
        return referents

    def _open_referents(self, b):
        """Referent names of row ``b``'s open LTM inputs, oldest first
        (``None`` = the root question); read from the slots' traces."""
        memory = self._what_memory()
        if memory is None:
            return []
        out = []
        for slot in memory.open_what_slots(b=b):
            referent = None
            for entry in slot.grammar_trace:
                if (isinstance(entry, dict)
                        and entry.get("operation") == "what_open_referent"):
                    referent = entry.get("referent")
            out.append(referent)
        return out

    def _answered_referents(self, b):
        """Referents whose subquestion row ``b`` already answered (from the
        LTM slot traces): the model's own record of what it has thought."""
        memory = self._what_memory()
        if memory is None:
            return set()
        out = set()
        for slot in memory.get_what_slots(b=b):
            for entry in slot.grammar_trace:
                if (isinstance(entry, dict)
                        and entry.get("operation") == "what_answer_referent"
                        and entry.get("referent")):
                    out.add(entry["referent"])
        return out

    def _active_referent(self, b):
        """Which question row ``b`` answers now: the subquestion posed at
        the previous iteration (``pending``), else the newest open LTM input
        (``open``), else the root (``root``, referent ``None``)."""
        pending = (self.__dict__.get("_what_pending") or {}).get(b)
        if pending is not None:
            return pending, "pending"
        opens = self._open_referents(b)
        if opens and opens[-1] is not None:
            return opens[-1], "open"
        return None, "root"

    def _enumerate_step_candidates(self, referents, active, open_refs, answered):
        """Candidate actions for one row (spec 6.3): ANSWER first (the
        neutral chooser's tie-break), then OPEN(w) for every presented
        referent not already open or active.  Features are lexical
        (surface position) and mnemonic (already answered in this row's
        LTM); nothing is computed about the referent."""
        cands = [{"kind": "answer", "operand": None, "label": "answer",
                  "active": True, "answered": False, "position": 0.0}]
        busy = {r for r in open_refs if r} | ({active} if active else set())
        n = max(1, len(referents))
        for i, word in enumerate(referents):
            if word in busy:
                continue
            cands.append({"kind": "open", "operand": word, "label": f"open:{word}",
                          "active": False, "answered": word in answered,
                          "position": float(i) / float(n)})
        return cands[: self.WHAT_STEP_MAX_CANDIDATES]

    def _referent_representation(self, understanding, b, referents, word,
                                 answer_row, *, detach=True):
        """Use an unambiguous lexical association, or retain the answer root.

        A completed field has no word list. An opening supplies no grammatical
        order, so competing associations remain unresolved.
        """
        if understanding.sentence_states:
            owner = self._concept_owner()
            definitions = owner.definitions
            word_id = definitions.word(form=word)
            candidates = (() if word_id is None else tuple(
                cid for cid in definitions.objects(word_id)
                if cid not in definitions.word_ids))
            cid = candidates[0] if len(candidates) == 1 else None
            row = None if cid is None else owner._csw_row_of(cid)
            rep = answer_row[0, 0] if row is None else owner.similarity_codebook.getW()[row]
            root = answer_row.detach() if detach else answer_row
            rep = rep.detach() if detach else rep
            return self._install_root_slot(root, rep.to(root))
        field = understanding.perceptual_context
        rep = None
        if torch.is_tensor(field) and field.dim() == 3 and word in referents:
            position = referents.index(word)
            if position < int(field.shape[1]):
                rep = field[b, position, :]
        if rep is None:
            rep = answer_row[0, 0, :]
        if detach:
            return self._install_root_slot(answer_row.detach(), rep.detach())
        return self._install_root_slot(answer_row, rep)

    def _step_choice_for_row(self, row):
        construction = getattr(self, "_last_answer_construction", None)
        derivation = getattr(construction, "derivation", None)
        steps = tuple(getattr(derivation, "step", ()) or ())
        if 0 <= int(row) < len(steps):
            return steps[int(row)]
        return None

    def _select_perceptual_bindings(self, understanding):
        """NAME the perceptual context slots output synthesis may bind.

        Spec 5.3: the live perceptual field primes the answer only through
        selected, replayable bindings, never as an unrestricted residual.
        The selection is the ``<synthesisBindings>`` most active slots of
        the understanding's perceptual context (activation = event norm),
        recorded in the derivation and its trace.  0 (default) binds nothing.
        """
        k = int(getattr(self, "synthesis_bindings", 0) or 0)
        field = understanding.perceptual_context
        if k <= 0 or not torch.is_tensor(field) or field.dim() != 3:
            return ()
        salience = field.detach().float().norm(dim=-1).mean(dim=0)   # [N]
        k = min(k, int(salience.shape[0]))
        chosen = torch.topk(salience, k).indices.tolist()
        return tuple(sorted(int(i) for i in chosen))

    def _question_conditioner(self, width, *, device, dtype):
        """The learned question -> conceptual-answer operator.

        Maps the target-free question context (relation bits, offset, the
        absolute ``.where`` ladder, LTM scalars -- the same vector the grammar
        chooser sees) onto the conceptual answer's root slot. Zero-initialised,
        so the answer path starts independent of the question; built on
        first use (state-dict keys unchanged for configurations that never
        synthesize) and handed to the live optimizer by ``runBatch``.  It is
        the differentiable consumer of the question: ``answer_construction``
        trains it, which is what makes temporal question content CAUSALLY
        used rather than merely present in context.
        """
        # Retain historical widths for checkpoint compatibility. An answer
        # actively uses only its conceptual width, once after materialisation.
        table = getattr(self, "question_conditioners", None)
        if table is None:
            table = nn.ModuleDict()
            self.question_conditioners = table
        key = str(int(width))
        module = table[key] if key in table else None
        legacy = getattr(self, "question_conditioner", None)
        if module is None and legacy is not None and legacy.out_features == int(width):
            module = legacy
            table[key] = module
        ctx_dim = int(getattr(getattr(getattr(self, "symbolSpace", None),
                                      "languageLayer", None),
                              "WHAT_CONTEXT_DIM", 0) or 0)
        if module is None:
            from Language import MLPTransformChooser
            in_dim = ctx_dim or MLPTransformChooser.WHAT_CONTEXT_DIM
            module = nn.Linear(in_dim, int(width), bias=False)
            nn.init.zeros_(module.weight)
            module = module.to(device=device, dtype=dtype)
            table[key] = module
            self.question_conditioner = module
        return module

    def _condition_answer_on_question(self, answer, context, *, occupied=None):
        """Condition the conceptual root from the derivation's frozen context."""
        if not torch.is_tensor(answer) or answer.dim() != 3:
            return answer
        if not torch.is_tensor(context):
            return answer
        context = context.to(device=answer.device, dtype=answer.dtype)
        module = self._question_conditioner(
            answer.shape[-1], device=answer.device, dtype=answer.dtype)
        if context.shape[-1] != module.in_features:
            return answer
        delta = module(context)                             # [B, D]
        if delta.shape[0] == 1 and answer.shape[0] > 1:
            delta = delta.expand(answer.shape[0], -1)
        if delta.shape[0] != answer.shape[0]:
            return answer
        # Exclusion may leave a silent leading role. Condition the first
        # occupied answer role, which becomes the decoder's root after
        # packing, rather than a hole that hard packing would discard.
        live = answer.detach().abs().amax(-1).ne(0) if occupied is None else occupied
        root = live.long().argmax(-1)
        role = F.one_hot(root, answer.shape[1]).to(answer)
        return answer + role[..., None] * delta[:, None]

    def _recall_history(self):
        """Per-row chronological sentence reps for ``past`` recall.

        The discourse ARMA ring changes layout between its fill phase and
        its rolling phase, so ``what()`` keeps its own plain history: every
        sentence rep the discourse layer observes is appended here (newest
        last), per row, cleared with the row's hard reset.  ``past -k`` is
        ``history[b][-k]`` -- exactly "what row b observed k sentences ago".
        """
        return self.__dict__.setdefault("_what_recall_history", {})



    def _sentence_end_state(self, t=None):
        """``[B, 3, D]`` end state of packed sentence slot ``t`` (from the
        end-state bank the word loop carried) or of the row's last sentence
        (``t`` None: the final closing's buffer); ``None`` when unknown."""
        if t is not None:
            bank = getattr(self, "_tensor_sentence_roots_live", None)
            if torch.is_tensor(bank) and bank.dim() == 3 and 0 <= int(t) < int(bank.shape[1]):
                B = int(bank.shape[0]); D = int(bank.shape[-1]) // 3
                slab = bank[:, int(t), :].reshape(B, 3, D)
                if float(slab.abs().sum()) > 0.0:
                    return slab
        end = getattr(self, "_tensor_final_end_slots", None)
        if torch.is_tensor(end) and end.dim() == 3:
            return end
        S = getattr(self, "_stm_single_S", None)
        if torch.is_tensor(S) and S.dim() == 2:
            return torch.cat((S.unsqueeze(1), S.new_zeros(int(S.shape[0]), 2, int(S.shape[-1]))), dim=1)
        return None

    def _observe_discourse(self, disc, sentence, mask=None, slot=None,
                           *, understanding=None):
        """Route every discourse observation through one seam so the recall
        history stays in step with the ARMA ring (and the concept-level
        end state of the sentence rides beside its pooled rep)."""
        result = disc.observe(sentence, mask=mask) if mask is not None else disc.observe(sentence)
        pooled = disc._pool_sentence_rep(sentence) if hasattr(disc, "_pool_sentence_rep") else None
        entries = (() if understanding is None else
                   understanding.sentence_states if slot is None else
                   understanding.sentence_fields.get(int(slot), ()))
        if torch.is_tensor(pooled):
            if pooled.dim() == 1:
                pooled = pooled.unsqueeze(0)
            history = self._recall_history()
            keep = max(8, int(getattr(disc, "p", 0) or 0), 64)
            for b in range(int(pooled.shape[0])):
                if mask is not None:
                    try:
                        if not bool(mask[b]):
                            continue
                    except (IndexError, TypeError):
                        pass
                row = history.setdefault(b, collections.deque(maxlen=keep))
                row.append(pooled[b].detach().clone())
                programs = self._recall_sentence_history().setdefault(
                    b, collections.deque(maxlen=keep))
                entry = entries[b] if b < len(entries) else None
                programs.append(entry.detached() if entry is not None else None)
        return result

    def _temporal_answer_rep_row(self, relation, offset, b, width):
        """Row ``b``'s recalled (past) or predicted (future) sentence rep,
        or ``None`` when that row's memory is cold."""
        k = abs(int(offset))
        if relation is WhatRelation.PAST:
            row = self._recall_history().get(int(b))
            if row is None or k < 1 or len(row) < k:
                return None
            return row[-k]
        memory = getattr(getattr(self, "symbolSpace", None), "expectation", None)
        history = getattr(memory, "_s_history", None)
        counts = getattr(memory, "_s_count", None)
        predict = getattr(memory, "predict_next", None)
        if (memory is None or predict is None
                or getattr(memory, "predictor", None) is None
                or not torch.is_tensor(history) or history.dim() != 3
                or int(b) >= int(history.shape[0])):
            return None
        if torch.is_tensor(counts) and int(counts[int(b)]) <= 0:
            return None
        saved = history[int(b)].clone()
        try:
            rep = None
            for _ in range(max(1, k)):
                rep = predict(b=int(b))
                if rep is None:
                    return None
                rolled = torch.roll(history[int(b)], shifts=-1, dims=0).clone()
                rolled[-1, :] = rep.detach()
                history[int(b)].copy_(rolled)
            return rep
        finally:
            history[int(b)].copy_(saved)

    def _temporal_answer_rep(self, relation, offset, symbolic):
        """The recalled (past) or predicted (future) ``[B, sentence_dim]``
        sentence rep from the discourse layer, or ``None`` when cold."""
        memory = getattr(getattr(self, "symbolSpace", None), "expectation", None)
        history = getattr(memory, "_s_history", None)
        counts = getattr(memory, "_s_count", None)
        if memory is None or not torch.is_tensor(history) or history.dim() != 3:
            return None
        B = int(symbolic.shape[0])
        if history.shape[0] != B:
            return None
        k = abs(int(offset))
        if relation is WhatRelation.PAST:
            if k < 1 or k > history.shape[1]:
                return None
            if torch.is_tensor(counts) and bool((counts < k).any()):
                return None                      # some row has no such memory
            return history[:, -k, :]
        # FUTURE: predict, then roll the ring forward without committing.
        predict = getattr(memory, "predict_next", None)
        if predict is None or getattr(memory, "predictor", None) is None:
            return None
        if torch.is_tensor(counts) and bool((counts <= 0).any()):
            return None
        saved = history.clone()
        try:
            rep = None
            for _ in range(max(1, k)):
                rep = predict(b=None)
                if rep is None:
                    return None
                if rep.dim() == 1:
                    rep = rep.unsqueeze(0)
                rolled = torch.roll(history, shifts=-1, dims=1).clone()
                rolled[:, -1, :] = rep.detach()
                history.copy_(rolled)
            return rep
        finally:
            history.copy_(saved)

    @staticmethod
    def _install_root_slot(symbolic, rep):
        """Return ``symbolic`` with the root slot (row 0) replaced by ``rep``
        (right-padded / truncated to the slot width)."""
        B, N, D = symbolic.shape
        rep = rep.to(device=symbolic.device, dtype=symbolic.dtype)
        if rep.dim() == 1:
            rep = rep.unsqueeze(0).expand(B, -1)
        if rep.shape[-1] < D:
            rep = torch.nn.functional.pad(rep, (0, D - rep.shape[-1]))
        elif rep.shape[-1] > D:
            rep = rep[..., :D]
        out = symbolic.clone()
        out[:, 0, :] = rep
        return out

    def _synthesis_state_objects(self):
        """Objects whose per-batch state the inverse operators write."""
        objs = []
        seen = set()
        def add(o):
            if o is not None and id(o) not in seen:
                seen.add(id(o)); objs.append(o)
        spaces = list(getattr(self, "spaces", []) or [])
        for name in ("inputSpace", "perceptualSpace", "conceptualSpace",
                     "wholeSpace", "outputSpace"):
            add(getattr(self, name, None))
        for group in ("conceptualSpaces", "wholeSpaces"):
            for sp in (getattr(self, group, None) or []):
                add(sp)
        for stage in (getattr(self, "body_stages", None) or ()):
            for key in ("cs", "ws"):
                add(stage[key])
            if "merge" in stage:
                add(stage["merge"])
        for sp in spaces:
            add(sp)
        symbol_space = getattr(self, "symbolSpace", None)
        add(getattr(symbol_space, "subspace", None))
        for sp in list(objs):
            sub = getattr(sp, "subspace", None)
            if sub is not None:
                add(sub)
                for role in ("event", "activation", "what", "where", "when"):
                    add(getattr(sub, role, None))
            add(getattr(sp, "syntacticLayer", None))
        return objs

    @staticmethod
    def _snapshot_vars(obj):
        saved = {}
        for k, v in vars(obj).items():
            if torch.is_tensor(v) and not isinstance(v, nn.Parameter):
                saved[k] = v.clone()
            else:
                saved[k] = v
        return saved

    @_contextmanager
    def _synthesis_guard(self):
        """Run answer synthesis without disturbing reconstruction state.

        The Space-level inverse operators write their results into the live
        ``Space.subspace`` (and consume forward-local carriers).  Inside this
        guard every such object is snapshotted, the reconstruction-only
        carriers are hidden (so synthesis cannot read them, spec 5.4), and
        the live state is restored afterwards -- reconstruction and output
        can therefore run in either order with identical results.
        """
        objs = self._synthesis_state_objects()
        saved = [(o, self._snapshot_vars(o)) for o in objs]
        saved_combine = getattr(self, "_combine_carriers", None)
        try:
            object.__setattr__(self, "_combine_carriers", None)
            for o in objs:
                if isinstance(o, GrammarMergeGlue):
                    o._merge_diff = None
                for attr in ("_bind_carrier", "_aligned_carrier",
                             "_percept_field", "_fold_support"):
                    if attr in vars(o):
                        object.__setattr__(o, attr, None)
            yield
        finally:
            for o, state in saved:
                vars(o).clear()
                vars(o).update(state)
            object.__setattr__(self, "_combine_carriers", saved_combine)

    def _materialize_answer_path(self):
        """Build the answer-path modules whose widths are known at
        construction (both Space synthesis operators and the question
        conditioner) so a checkpoint written by a synthesizing model reloads
        into a fresh model without unexpected keys.  The percept adapter's
        slot count is only known once an answer has been realized, so it is
        restored from checkpoint metadata instead
        (``_materialize_answer_path_from_checkpoint``)."""
        if not getattr(self, "answer_synthesis", False):
            return
        try:
            device = next(self.parameters()).device
            dtype = next(self.parameters()).dtype
        except StopIteration:
            device, dtype = TheDevice.get(), torch.float32
        for space in (getattr(self, "conceptualSpace", None),
                      getattr(self, "perceptualSpace", None)):
            width = int(getattr(getattr(space, "subspace", None), "muxedSize", 0) or 0)
            if space is not None and width > 0 and getattr(space, "synthesis_layer", None) is None:
                space.synthesis_operator(width, device=device, dtype=dtype)
        cs = getattr(self, "conceptualSpace", None)
        width = int(getattr(getattr(cs, "subspace", None), "muxedSize", 0) or 0)
        if width > 0 and getattr(self, "question_conditioner", None) is None:
            self._question_conditioner(width, device=device, dtype=dtype)
        self._collect_fresh_synthesis_modules()

    def _materialize_answer_path_from_checkpoint(self, state):
        """Instantiate answer-path modules named in a checkpoint (shapes from
        the saved tensors) before the key audit, so their learned weights
        load instead of being reported unexpected or silently dropped."""
        from Layers import InvertibleLinearLayer, LDUReadout
        try:
            device = next(self.parameters()).device
            dtype = next(self.parameters()).dtype
        except StopIteration:
            device, dtype = TheDevice.get(), torch.float32
        built = 0
        answer_spaces = tuple(getattr(self, name, None) for name in (
            "conceptualSpace", "perceptualSpace", "outputSpace"))
        owners = tuple((name, module) for name, module in
                       self.named_modules(remove_duplicate=False)
                       if any(module is owner for owner in answer_spaces))
        for space_name, space in owners:
            for module_name in ("synthesis_layer", "percept_adapter"):
                if getattr(space, module_name, None) is not None:
                    continue
                key_L = f"{space_name}.{module_name}.raw_L"
                key_U = f"{space_name}.{module_name}.raw_U"
                if key_L in state and key_U in state:
                    n_in = int(state[key_L].shape[0])
                    n_out = int(state[key_U].shape[1])
                    compact = (module_name == "percept_adapter"
                               and f"{space_name}.{module_name}._readout_format" in state)
                    adapter_type = LDUReadout if compact else InvertibleLinearLayer
                    setattr(space, module_name, adapter_type(
                        n_in, n_out, hasBias=True).to(device=device, dtype=dtype))
                    built += 1
        # The singular key is a compatibility alias, historically pointing
        # at the last-created width. Preserve all width-owned weights before
        # rebinding that alias to the symbol width; otherwise a saved concept
        # conditioner is loaded into the freshly built symbol conditioner.
        alias = "question_conditioner.weight"
        prefix, suffix = "question_conditioners.", ".weight"
        legacy = state.get(alias)
        if legacy is not None:
            state.setdefault(f"{prefix}{int(legacy.shape[0])}{suffix}", legacy)
        saved = {}
        for key in state:
            if key.startswith(prefix) and key.endswith(suffix):
                width = key[len(prefix):-len(suffix)]
                weight = state[key]
                if (not width.isdigit() or weight.dim() != 2
                        or int(width) != int(weight.shape[0])):
                    raise ValueError(f"invalid question conditioner checkpoint: {key}")
                saved[width] = weight
        if saved:
            table = getattr(self, "question_conditioners", None)
            if table is None:
                table = nn.ModuleDict()
                self.question_conditioners = table
            for width, weight in saved.items():
                out_dim, in_dim = (int(v) for v in weight.shape)
                if (width not in table
                        or tuple(table[width].weight.shape) != tuple(weight.shape)):
                    module = nn.Linear(in_dim, out_dim, bias=False)
                    nn.init.zeros_(module.weight)
                    table[width] = module.to(device=device, dtype=dtype)
                    built += 1
            # A legacy checkpoint may contain only the old symbol-width
            # conditioner. Keep it and initialise the newly active conceptual
            # width at zero; never fabricate a learned wide weight by padding.
            if getattr(self, "answer_synthesis", False):
                conceptual = getattr(self, "conceptualSpace", None)
                active_width = int(getattr(
                    getattr(conceptual, "subspace", None), "muxedSize", 0) or 0)
                if active_width > 0 and str(active_width) not in table:
                    self._question_conditioner(active_width, device=device, dtype=dtype)
                    built += 1
            for width, module in table.items():
                state.setdefault(f"{prefix}{width}{suffix}", torch.zeros_like(module.weight))
            ws = getattr(self, "wholeSpace", None)
            symbol_width = str(int(getattr(
                getattr(ws, "subspace", None), "muxedSize", 0) or 0))
            alias_width = (symbol_width if symbol_width in table else
                           str(int(legacy.shape[0])) if legacy is not None else
                           next(iter(saved)))
            self.question_conditioner = table[alias_width]
            # Normalize duplicate state keys before load_state_dict visits
            # the alias. Never overwrite a width-owned weight with another
            # width's historical alias.
            state[alias] = state[f"{prefix}{alias_width}{suffix}"]
        key_q, key_k = "ltm_attention.query.weight", "ltm_attention.key.weight"
        if key_q in state and key_k in state and getattr(self, "ltm_attention", None) is None:
            width = int(state[key_q].shape[1])
            key_width = int(state[key_k].shape[1])
            self._ltm_attention(width, key_width, device=device, dtype=dtype)
            built += 1
        # Retired controllers had incompatible action/context schemas.
        # Discard their parameters explicitly; never reinterpret their logits.
        for key in tuple(state):
            if (key.startswith(("what_step_chooser.", "_next_op_policy.",
                                "_predict_next_scorer.", "_intervening_generator.",
                                "_reasoning_ga.")) or "meaning_codec." in key):
                del state[key]
        self._pending_thought_policy_reset = set()
        # Width-owned normal selected-thought choosers are lazy like the
        # answer conditioner. Rebuild exactly the saved MLP shape before the
        # strict state-dict audit; never infer a semantic width from a native
        # concept ID or pad a learned controller weight.
        selected_prefix = "selected_thought_choosers."
        selected = {}
        for key, weight in state.items():
            if not (key.startswith(selected_prefix)
                    and key.endswith(".mlp.0.weight")):
                continue
            suffix = key[len(selected_prefix):]
            width = suffix.split(".", 1)[0]
            if not width.isdigit() or weight.dim() != 2:
                raise ValueError(f"invalid selected thought chooser checkpoint: {key}")
            selected[width] = weight
        if selected:
            from Language import SelectedThoughtChooser
            table = getattr(self, "selected_thought_choosers", None)
            if table is None:
                table = nn.ModuleDict()
                self.selected_thought_choosers = table
            for width, first_weight in selected.items():
                hidden, in_dim = (int(value) for value in first_weight.shape)
                # The input schema is owned by ThoughtFeatures. Retire a
                # saved incomplete-context policy instead of padding it.
                from ThoughtFeatures import context_width
                context_dim = context_width(int(width))
                expected_in = context_dim + SelectedThoughtChooser.CANDIDATE_FEATURES
                if in_dim == 9 * int(width) + 17:
                    # Retired incomplete-context schema: reset this policy at
                    # its neutral baseline, retaining no fabricated columns.
                    if width in table:
                        del table[width]
                    module = self._selected_thought_chooser(ConceptualMeaning(
                        torch.zeros(3, int(width), device=device, dtype=dtype),
                        torch.ones(3, device=device, dtype=torch.bool)))
                    prefix = f"{selected_prefix}{width}."
                    for name in tuple(state):
                        if name.startswith(prefix):
                            self._pending_thought_policy_reset.add(name)
                            del state[name]
                    state.update({prefix + name: value.detach().clone()
                                  for name, value in module.state_dict().items()})
                    built += 1
                    continue
                if in_dim == expected_in - (3 * int(width) + 7):
                    first_weight = torch.cat((first_weight[:, :-2],
                        first_weight.new_zeros(hidden, 3 * int(width) + 7),
                        first_weight[:, -2:]), dim=1)
                    key = f"{selected_prefix}{width}.mlp.0.weight"
                    state[key] = first_weight
                    self._pending_thought_policy_reset.add(key)
                    in_dim = expected_in
                if in_dim != expected_in:
                    raise ValueError(
                        f"selected thought chooser width {width} has input "
                        f"{in_dim}, expected {expected_in}")
                prefix = f"{selected_prefix}{width}.mlp."
                indices = sorted(int(name[len(prefix):].split(".")[0])
                                 for name in state
                                 if name.startswith(prefix)
                                 and name.endswith(".weight")
                                 and name[len(prefix):].split(".")[0].isdigit())
                if (len(indices) < 2
                        or indices != list(range(0, 2 * len(indices), 2))):
                    raise ValueError(
                        "invalid SelectedThoughtChooser checkpoint layer layout")
                for layer, index in enumerate(indices):
                    expected = ((1, hidden) if layer == len(indices) - 1 else
                                (hidden, in_dim if layer == 0 else hidden))
                    weight_key = f"{prefix}{index}.weight"
                    if tuple(state[weight_key].shape) != expected:
                        raise ValueError(
                            f"invalid SelectedThoughtChooser checkpoint shape for "
                            f"{weight_key}: expected {expected}, got "
                            f"{tuple(state[weight_key].shape)}")
                module = SelectedThoughtChooser(
                    context_dim=context_dim, hidden=hidden,
                    depth=len(indices) - 1).to(device=device, dtype=dtype)
                table[width] = module
                built += 1
        if built or saved:
            self._collect_fresh_synthesis_modules()
        return built

    def _question_conditioner_modules(self):
        """All retained widths, with the compatibility alias deduplicated."""
        table = getattr(self, "question_conditioners", None)
        modules = list(table.values()) if table is not None else []
        legacy = getattr(self, "question_conditioner", None)
        if legacy is not None and all(legacy is not module for module in modules):
            modules.append(legacy)
        return modules


    def _selected_thought_chooser_modules(self):
        """One normal-controller chooser per semantic payload width."""
        table = getattr(self, "selected_thought_choosers", None)
        return list(table.values()) if table is not None else []

    def _collect_fresh_synthesis_modules(self):
        """Queue lazily built answer-path modules for the live optimizer.

        The dedicated synthesis operators and the percept adapter are built
        on first use, after ``getOptimizer`` ran; ``runBatch`` hands their
        parameters to the optimizer through ``add_param_group`` exactly once
        (the leaf-distill head idiom), otherwise they would never be stepped.
        """
        registered = self.__dict__.setdefault("_registered_synthesis_modules", set())
        fresh = self.__dict__.setdefault("_fresh_synthesis_params", [])
        modules = (self._question_conditioner_modules()
                   + self._selected_thought_chooser_modules() + [
            getattr(self, "ltm_attention", None)])
        for module in modules:
            if module is not None and id(module) not in registered:
                registered.add(id(module))
                fresh.extend(p for p in module.parameters() if p.requires_grad)
        for space in (getattr(self, "conceptualSpace", None),
                      getattr(self, "perceptualSpace", None),
                      getattr(self, "outputSpace", None)):
            if space is None:
                continue
            for name in ("synthesis_layer", "percept_adapter"):
                module = getattr(space, name, None)
                if module is None or id(module) in registered:
                    continue
                registered.add(id(module))
                fresh.extend(p for p in module.parameters() if p.requires_grad)

    def synthesis_parameters(self):
        """Enlist synthesis parameters; objective_parameter_groups assigns writers.

        The shared generate chooser is enlisted here but reconstruction owns
        it. Question conditioners and answer readers belong to output.
        """
        params = []
        for conditioner in self._question_conditioner_modules():
            params.extend(conditioner.parameters())
        for chooser in self._selected_thought_chooser_modules():
            params.extend(chooser.parameters())
        for module in (getattr(self, "ltm_attention", None),
                       getattr(self, "answer_attention", None),
                       getattr(getattr(self, "languageSpace", None), "generate_policy", None)):
            if module is not None:
                params.extend(module.parameters())
        for space in (getattr(self, "conceptualSpace", None),
                      getattr(self, "perceptualSpace", None),
                      getattr(self, "outputSpace", None)):
            for name in ("synthesis_layer", "percept_adapter"):
                module = getattr(space, name, None) if space is not None else None
                if module is not None:
                    params.extend(module.parameters())
        return list({id(p): p for p in params}.values())

    @_sentence_query_mask
    def reverseOutput(self, understanding, derivation, *, score=None, _walk_options=None):
        """Realize a prepared AnswerDerivation without running resolution.

        Condition its owned concepts once, then use the independent generate
        walk or dedicated synthesis operators, the shared reverse chain and
        OutputSpace. Dense prepared seeds remain supported for topologies
        without row programs. Desired answers enter scoring later; synthesis
        preserves the carriers needed by reconstruction.
        """
        if not isinstance(understanding, Understanding):
            raise TypeError("output expects an Understanding")
        if not isinstance(derivation, AnswerDerivation):
            raise TypeError("output expects a prepared AnswerDerivation; call resolveAnswer first")
        if score is not None and self.training and torch.is_grad_enabled():
            from WalkTrials import output_pair
            def realize(**options):
                value=self.reverseOutput(understanding,derivation,_walk_options=options)
                return value,self._last_output_walk_trace
            value,audit=output_pair(realize,score)
            observation = getattr(self, '_answer_attention_obs', None)
            if observation is not None:
                for row, meter in enumerate(getattr(self, '_attention_meters', ())):
                    if bool(observation['space_id'][row] >= 0):
                        meter.require('space-read')
            self._last_output_comparison=audit
            from WalkTrials import observe_comparison
            observe_comparison(self,"generate.output",audit,sentence=getattr(self,"_open_sentence_slot",None))
            self._last_answer_construction=value
            return value
        self._last_output_comparison=None
        self._last_output_walk_trace=None
        cs = self.conceptualSpace
        ps = self.perceptualSpace
        questions = derivation.questions
        temporal = bool(questions) and questions[0].relation in (
            WhatRelation.PAST, WhatRelation.FUTURE)
        surface = None
        texts = ()
        # Generation owns its state path. The concluded idea and any named
        # contextual operands are given values; shared inverse/operator
        # hosts transmit to the reader, while owned backward excludes their weights.
        answer_event = (derivation.answer_symbol.detach()
                        if torch.is_tensor(derivation.answer_symbol)
                        else derivation.answer_symbol)
        conceptual_context = understanding.conceptual_state
        if torch.is_tensor(conceptual_context):
            conceptual_context = conceptual_context.detach()
        perceptual_context = understanding.perceptual_context
        if torch.is_tensor(perceptual_context):
            perceptual_context = perceptual_context.detach()
        output_truncated = None
        walked = None
        idea = None
        if derivation.sentence_states:
            # The answer-materialisation boundary (spec sections 1-2): the
            # resolved answer as its own conceptual idea, the operand of the
            # output loop; the walk un-folds it into words (the second
            # compiled loop) and the words are realised through the
            # reverse chain.  The symbol vector is never padded to fit.
            idea, idea_resolved, idea_sources, _targets = self._materialize_answer_idea(
                understanding, derivation, questions)
            object.__setattr__(self, "_output_idea_sources", idea_sources)
            object.__setattr__(self, "_output_idea_resolved", idea_resolved)
            if torch.is_tensor(idea):
                occupied = self._answer_occupancy(derivation, idea)
                idea = self._generation_read(idea,
                    record=understanding.sentence_records[-1] if understanding.sentence_records else None,
                    charge=_walk_options is None)
                # A prepared answer may be trained after a no-grad capture,
                # without entering forward/runBatch's anchor setup first.
                _ensure_grad_anchors(idea.device, (idea.dtype,))
                budget = self._walk_budget()
                bank = understanding.sentence_records[-1].primed if understanding.sentence_records else None
                walk = (
                    self._compiled_output_walk()(
                        self._walk_operand(idea, infix_rows=tuple(
                            bool(items) for items in derivation.answer_meanings), occupied=occupied), budget, False,
                        None, False,
                        None if bank is None else bank.codes.detach(),
                        None if bank is None else bank.valid, self.reconstruction_basis_limit,
                        basis_priming=None if bank is None else bank.weights,
                        case_bank=(None if bank is None or bank.case_bank is None
                                   else bank.case_bank.detached()),
                        initial_depth=occupied.long().sum(-1),
                        require_symbols=not self._aligned_serial_word_mode(),
                        **dict(_walk_options or {},return_trace=True)))
                words,n_emitted,output_truncated,policy_cost=walk[:4]
                alternatives=(walk[5] if len(walk)>5 else torch.zeros_like(walk[4],dtype=torch.bool))
                self._last_output_walk_trace=(walk[4],alternatives)
                kept = max(2, 2 * int(getattr(self, "serial_word_capacity", 0) or 8))
                if int(words.shape[1]) > kept:       # the realised slab keeps 2W words
                    output_truncated = torch.logical_or(output_truncated, n_emitted > kept)
                    words = words[:, :kept]
                object.__setattr__(self, "_output_truncated", output_truncated)
                walked = words
                if not self.training or not torch.is_grad_enabled():
                    texts = (self._generated_word_text(words, n_emitted, bank=bank)
                             if bank is not None else ())
        with self.languageSpace.generation_scope(), self._synthesis_guard():
            if walked is not None:
                # words (concept width) -> percepts through the tied reverse
                # chain, the same realisation the reconstruction uses
                cs.commit_event(walked)
                realized = self._reverse_perceptual(self._reverse_body(cs.subspace))
                concepts = walked
                percepts = (realized.materialize()
                            if hasattr(realized, "materialize") else realized)
            else:
                if torch.is_tensor(idea):
                    concepts = cs.synthesize_idea(
                        idea, context=conceptual_context,
                        selections=derivation.synthesis_references)
                else:
                    concepts = cs.synthesize(
                        answer_event, derivation.bindings,
                        context=conceptual_context,
                        selections=derivation.synthesis_references,
                        condition=lambda idea: self._generation_read(self._condition_answer_on_question(
                            idea, derivation.conditioning_context.detach()
                            if torch.is_tensor(derivation.conditioning_context)
                            else derivation.conditioning_context), charge=_walk_options is None))
                percepts = ps.synthesize(
                    concepts, context=perceptual_context,
                    selections=derivation.synthesis_references,
                    reverse_chain=(lambda sub: self._reverse_perceptual(self._reverse_body(sub)))
                    if torch.is_tensor(idea) else self._reverse_body)
            actual = self.outputSpace.from_percepts(percepts)
            if temporal:
                surface = self._answer_surface_from_percepts(percepts)
        trace = derivation.grammar_trace + (
            {"operation": "generate:grammar" if walked is not None else "synthesize:conceptual",
             "shape": tuple(concepts.shape) if torch.is_tensor(concepts) else None},
            {"operation": "synthesize:perceptual",
             "shape": tuple(percepts.shape) if torch.is_tensor(percepts) else None,
             "selections": derivation.synthesis_references},
            {"operation": "output:from_percepts",
             "shape": tuple(actual.shape) if torch.is_tensor(actual) else None},
        )
        if texts:
            trace = trace + ({"operation": "generate:lexical_inverse",
                              "vocabulary": "all_owned_word_surfaces"},)
        self._collect_fresh_synthesis_modules()
        if surface is not None:
            trace = trace + ({"operation": "output:surface",
                              "shape": tuple(surface.shape)
                              if torch.is_tensor(surface) else None},)
        construction = AnswerConstruction(
            actual=actual, derivation=derivation, concepts=concepts,
            percepts=percepts, surface=surface, trace=trace, texts=texts)
        self._last_answer_construction = construction
        if self._last_output_walk_trace is None:
            # Dense synthesis has no grammatical action to depart from.
            batch=int(actual.shape[0])
            self._last_output_walk_trace=(torch.full((batch,1),-1,device=actual.device,dtype=torch.long),
                                         torch.zeros(batch,1,device=actual.device,dtype=torch.bool))
        return construction

    def _output_target_cost(self, construction, values):
        """Answer error on already realized outputs; targets never enter a walk."""
        costs=[]
        for row,value in enumerate(values):
            actual=construction.actual[row:row+1]
            if value is None:
                costs.append(actual.sum()*0)
            elif isinstance(value,str):
                target=self._embed_answer_texts([value]).detach()
                surface=self._answer_surface_from_percepts(construction.percepts[row:row+1])
                costs.append(self._reverse_event_loss(surface,target))
            else:
                target=self.outputSpace.prepOutput([value])
                pred=self._align_output_pred(actual,target)
                if pred is None:raise RuntimeError('output trial and supplied answer do not align')
                costs.append((pred-target.to(pred)).square().mean())
        return torch.stack(costs)

    def _answer_surface_from_percepts(self, percepts):
        """Realise fixed answer percepts in input-event space, without a target."""
        try:
            with self._synthesis_guard():
                carrier = self.perceptualSpace.subspace.carrier_like()
                carrier.set_event(percepts)
                realized = self.inputSpace.reverse(self._reverse_perceptual(carrier))
                return realized.materialize() if hasattr(realized, "materialize") else realized
        except (RuntimeError, AssertionError, ValueError, TypeError, AttributeError) as exc:
            self._warn_zeroed_channel("answer_surface", f"answer surface unavailable: {exc}")
            return None

    def branch_gradient_diagnostics(self, costs=None, understanding=None):
        """Gradient norms and cosine of the primary costs at the branch points.

        For ``input_reconstruction`` and ``answer_construction`` (from
        ``primary_costs()`` unless ``costs`` is given), differentiate each
        with respect to the understanding's conceptual and symbolic states.
        Uses ``torch.autograd.grad`` with ``retain_graph`` so the caller's
        backward is untouched and no parameter is updated.  Returns a dict
        ``{branch: {"reconstruction_norm", "answer_norm", "cosine"}}``;
        branches or costs without a live graph are reported as ``None``.
        """
        costs = dict(costs if costs is not None else self.primary_costs())
        understanding = understanding or getattr(self, "_last_understanding", None)
        report = {}
        if understanding is None:
            return report
        branches = {"conceptual": understanding.conceptual_state,
                    "symbolic": understanding.symbolic_state}
        for name, state in branches.items():
            entry = {"reconstruction_norm": None, "answer_norm": None,
                     "cosine": None}
            if torch.is_tensor(state) and state.requires_grad:
                grads = {}
                for key, label in (("input_reconstruction", "reconstruction"),
                                   ("answer_construction", "answer")):
                    cost = costs.get(key)
                    if (label == "reconstruction" and not (
                            torch.is_tensor(cost) and cost.grad_fn is not None)):
                        # The legacy channel may be zeroed (no masked-LM
                        # inputs); fall back to reconstruct()'s own cost.
                        cost = costs.get("input_reconstruction_reverse")
                    if (torch.is_tensor(cost) and cost.requires_grad
                            and cost.grad_fn is not None):
                        try:
                            (g,) = torch.autograd.grad(
                                cost, state, retain_graph=True,
                                allow_unused=True)
                        except RuntimeError:
                            g = None
                        if g is not None:
                            grads[label] = g.detach().reshape(-1)
                            entry[f"{label}_norm"] = float(g.norm())
                if "reconstruction" in grads and "answer" in grads:
                    r, a = grads["reconstruction"], grads["answer"]
                    denom = float(r.norm() * a.norm())
                    entry["cosine"] = (float(torch.dot(r, a)) / denom
                                       if denom > 0 else None)
            report[name] = entry
        self._last_branch_diagnostics = report
        return report

    def _embed_answer_texts(self, texts):
        """Embed desired answer sentences into the input-event space.

        A READ-ONLY encoding: the real stem (lex -> PartSpace embed) runs on
        the target texts inside the synthesis guard with online learning
        frozen on every Space, so no word is promoted into the percept store
        and no live carrier changes (spec section 11, learning isolation);
        the model-level stem stash is saved and restored too.  Returns a
        detached ``[B, N, D_in]`` scoring target, the same event the forward
        input carries for a presented sentence (never a model input).
        """
        stash = (self.__dict__.get("_staged_concepts_in"),
                 self.__dict__.get("_ws_universe"))
        try:
            with self._synthesis_guard():
                for space in (getattr(self, "inputSpace", None),
                              getattr(self, "perceptualSpace", None),
                              getattr(self, "conceptualSpace", None),
                              getattr(self, "wholeSpace", None)):
                    if space is not None:
                        object.__setattr__(space, "_online_learning_frozen", True)
                prepared = self.inputSpace.prepInput(list(texts))
                in_sub = self._lex_embed_stem(prepared)
                event = (in_sub.materialize()
                         if hasattr(in_sub, "materialize") else in_sub)
                if not torch.is_tensor(event):
                    event = getattr(self.inputSpace, "_ar_embedded", None)
                if not torch.is_tensor(event):
                    event = getattr(self.perceptualSpace, "_embedded_input", None)
                return event.detach().clone() if torch.is_tensor(event) else None
        finally:
            self._staged_concepts_in = stash[0]
            object.__setattr__(self, "_ws_universe", stash[1])

    def _what_answer_target(self, questions, output_tensor, *, supervised_only=False):
        """Assemble the realized-answer target from ``Data.what()``.

        Step 5 of the What spec: the dataset's answer to each question, not
        the loader's incidental ``outputTensor``, is the answer target. Rows
        whose desired answer is unavailable (inference, an out-of-document
        past/future, or a non-tensor answer the head cannot be scored
        against yet) are masked out of the loss rather than substituted.
        Returns ``(target, mask)``; ``target`` is ``None`` when no row is
        scoreable, and ``mask`` is a bool ``[B]`` tensor. Training sets
        ``supervised_only`` to accept only available, explicitly supplied
        answers to supervised questions. Evaluation can score automatic
        temporal answers. Targets are resolved after the model response is
        fixed and never enter any model-visible context.
        """
        self._answer_surface_target = None
        desired = tuple(getattr(self, "_last_what_desired", ()) or ())
        if not desired or output_tensor is None or not torch.is_tensor(output_tensor):
            empty = (torch.zeros(output_tensor.shape[0], dtype=torch.bool,
                                 device=output_tensor.device)
                     if supervised_only and torch.is_tensor(output_tensor) else None)
            return None, empty
        questions = question_batch(questions)
        supplied = bool(getattr(self.inputSpace.data, "has_supervised_outputs", False))
        # Filter before choosing the scoring modality: an automatic text
        # target must not displace a supplied numeric target in another row.
        values = [answer.what if answer.available and (not supervised_only or (
            supplied and questions
            and questions[min(b, len(questions) - 1)].relation is WhatRelation.SUPERVISED))
            else None for b, answer in enumerate(desired)]
        rows = []
        mask = []
        construction = getattr(self, "_last_answer_construction", None)
        surface = getattr(construction, "surface", None)
        texts = [value if isinstance(value, str) else None for value in values]
        if (surface is None and any(t is not None for t in texts)
                and isinstance(construction, AnswerConstruction)):
            # Desired content never enters realization. Only its modality
            # selects how to score the already fixed answer percepts.
            surface = self._answer_surface_from_percepts(construction.percepts)
            if torch.is_tensor(surface):
                from dataclasses import replace
                construction = replace(construction, surface=surface,
                    trace=construction.trace + ({"operation": "output:surface",
                                                "shape": tuple(surface.shape)},))
                self._last_answer_construction = construction
        if torch.is_tensor(surface) and any(t is not None for t in texts):
            # Text answers are scored in input-event
            # space against the constructed surface; rows without a text
            # answer are masked.  Fill the masked rows with any available
            # text so the stem batch is well-formed.
            filler = next(t for t in texts if t is not None)
            try:
                embedded = self._embed_answer_texts(
                    [t if t is not None else filler for t in texts])
            except (RuntimeError, ValueError, TypeError) as exc:
                self._warn_zeroed_channel(
                    "answer_text_target",
                    f"text answer target unavailable: {exc}")
                embedded = None
            if (torch.is_tensor(embedded) and embedded.dim() == 3
                    and embedded.shape[0] == surface.shape[0]):
                mask_t = torch.tensor([t is not None for t in texts],
                                      dtype=torch.bool, device=surface.device)
                self._answer_surface_target = embedded.to(surface.device)
                return embedded.to(surface.device), mask_t
        for value in values:
            if value is not None and not torch.is_tensor(value):
                try:
                    value = torch.as_tensor(value, dtype=output_tensor.dtype)
                except (TypeError, ValueError):
                    value = None       # e.g. a text answer the head cannot score
            if value is None:
                rows.append(None)
                mask.append(False)
            else:
                rows.append(value.to(device=output_tensor.device,
                                     dtype=output_tensor.dtype))
                mask.append(True)
        mask_t = torch.tensor(mask, dtype=torch.bool, device=output_tensor.device)
        if not any(mask):
            return None, mask_t
        template = next(row for row in rows if row is not None)
        stacked = torch.stack([
            row if row is not None else torch.zeros_like(template)
            for row in rows], dim=0)
        # Mirror ``OutputSpace.prepOutput`` ([B, D] rows -> [B, 1, D]) so a
        # fully available target is byte-identical to the loader's tensor.
        while stacked.dim() < output_tensor.dim():
            stacked = stacked.unsqueeze(1)
        if stacked.shape[0] != output_tensor.shape[0]:
            self._warn_zeroed_channel(
                "what_answer_target_shape",
                f"Data.what target {tuple(stacked.shape)} does not match the "
                f"loader output {tuple(output_tensor.shape)} batch; answer "
                "loss cannot use this target batch")
            return None, (torch.zeros(output_tensor.shape[0], dtype=torch.bool,
                                      device=output_tensor.device)
                          if supervised_only else None)
        if stacked.shape != output_tensor.shape:
            # ``Data.what()`` is the authority (What spec Step 5): a loader
            # tensor of another shape is a placeholder (the byte cursor
            # yields no labels and runEpoch fabricates [B, 1, 1]); the head
            # prediction is aligned to THIS target by _align_output_pred.
            self._warn_zeroed_channel(
                "what_answer_target_shape",
                f"Data.what target {tuple(stacked.shape)} replaces the loader "
                f"output {tuple(output_tensor.shape)} (placeholder labels)")
        return stacked, mask_t

    # -- model-owned training seam (What spec 12.16) ----------------------
    @property
    def errors(self):
        """The per-batch loss registry: the attached Teacher adapter's when
        present, else the process registry ``TheError``."""
        teacher = self.__dict__.get("teacher")
        if teacher is not None and getattr(teacher, "errors", None) is not None:
            return teacher.errors
        return TheError

    def record_loss(self, name, value, *, weight=1.0, space=None,
                    category="other", kind="penalty", objective=None, trained=True):
        """Register an explicit penalty or a reported metric; errors keep targets."""
        self.errors.add(name, value, weight=weight, space=space,
                        category=category, kind=kind, objective=objective, trained=trained)

    def _primary_loss(self, loss_out, loss_in=None, sbow=None):
        """Compose the established task and reconstruction objective."""
        return self.loss.total(loss_out, loss_in, sbow)

    def _open_batch(self, *, split, batch_size, training, clean_input=None):
        """Open a batch: reset the registry and, when a Teacher adapter is
        attached, let it open its provenance lesson too."""
        self.errors.reset()
        self.errors.attach(self.loss)
        teacher = getattr(self, "teacher", None)
        if teacher is None:
            return None
        return teacher.begin_batch(
            split=split, batch_size=batch_size, training=training,
            clean_input=clean_input)

    def _runtime_batch(self, inputs, outputs=None, *, context=None, document_keys=None):
        """Stage interactive data; through the Teacher adapter when attached
        (it also installs the interactive context), else directly on Data."""
        teacher = getattr(self, "teacher", None)
        if teacher is not None:
            return teacher.runtime_batch(inputs, outputs, context=context, document_keys=document_keys)
        return self.data.runtime_batch(inputs, outputs, context=context, document_keys=document_keys)

    def _what_report_state(self):
        return self.__dict__.setdefault("_what_report", {
            "families": {}, "thinking": {"episodes": 0, "iterations": 0,
                                         "forced_closures": 0},
            "batches": 0, "sentences": 0, "seconds": 0.0})

    def _record_what_batch(self, questions, answer_cost, recon_cost,
                           *, seconds=None, sentences=None):
        """Accumulate per-family answer quality and the primary costs
        (spec section 11 'Grammar and performance': present reconstruction,
        past recall, future completion, supervised answer quality, both
        primary losses and sentences/s are reported SEPARATELY)."""
        report = self._what_report_state()
        report["batches"] += 1
        if sentences:
            report["sentences"] += int(sentences)
        if seconds:
            report["seconds"] += float(seconds)
        for question in question_batch(questions):
            fam = report["families"].setdefault(question.relation.value, {
                "batches": 0, "answer_cost_sum": 0.0,
                "reconstruction_cost_sum": 0.0})
            fam["batches"] += 1
            if torch.is_tensor(answer_cost):
                fam["answer_cost_sum"] += float(answer_cost.detach())
            if torch.is_tensor(recon_cost):
                fam["reconstruction_cost_sum"] += float(recon_cost.detach())

    def _record_thinking(self, result):
        report = self._what_report_state()
        report["thinking"]["episodes"] += 1
        report["thinking"]["iterations"] += int(result.iterations)
        report["thinking"]["forced_closures"] += int(result.forced_closures)

    def what_report(self):
        """Separate means per question family plus thinking and throughput."""
        report = self._what_report_state()
        out = {"families": {}, "thinking": {}, "throughput": {}}
        for name, fam in report["families"].items():
            n = max(1, fam["batches"])
            out["families"][name] = {
                "batches": fam["batches"],
                "answer_construction": fam["answer_cost_sum"] / n,
                "input_reconstruction": fam["reconstruction_cost_sum"] / n,
            }
        th = report["thinking"]
        episodes = max(1, th["episodes"])
        out["thinking"] = {
            "episodes": th["episodes"],
            "mean_iterations": th["iterations"] / episodes if th["episodes"] else 0.0,
            "forced_closure_rate": th["forced_closures"] / max(1, th["iterations"]),
            "iteration_limit": int(getattr(self, "what_thinking_iterations", 1) or 1),
            "detach": str(getattr(self, "what_thinking_detach", "slot") or "slot"),
        }
        out["policy"] = {
            "selected_thought": {
                "weight": float(getattr(
                    self, "selected_thought_policy_weight", 0.0) or 0.0),
                "credit": report.get("policy_selected_thought_credit_sum", 0.0)
                          / max(1, report.get("policy_selected_thought_batches", 0)),
                "mean_return": report.get("policy_selected_thought_return_sum", 0.0)
                               / max(1, report.get("policy_selected_thought_batches", 0)),
                "batches": report.get("policy_selected_thought_batches", 0),
                "choices": report.get("policy_selected_thought_choices", 0),
            },
        }
        out["throughput"] = {
            "batches": report["batches"],
            "sentences": report["sentences"],
            "sentences_per_second": (report["sentences"] / report["seconds"]
                                     if report["seconds"] > 0 else None),
        }
        return out

    def primary_costs(self):
        """The two primary costs of the last batch under their spec names:
        ``input_reconstruction`` (the input-associated inverse branch) and
        ``answer_construction`` (the question's answer scored against
        ``Data.what()``). Values are the raw normalized terms before their
        independent weights."""
        return dict(getattr(self, "_last_primary_costs", {}) or {})

    def _what_where_encoder(self, split):
        """The absolute ``.where`` ladder for a question's dataset position.

        A presentation index is a position in the dataset (which exists all
        at once), so it is encoded with the model's ``.where`` ladder rather
        than its ``.when`` clock. The period is the split extent (number of
        presentations); one plain, parameter-free ``WhereEncoding`` is cached
        per split and re-perioded when the extent changes.
        """
        data = getattr(getattr(self, "inputSpace", None), "data", None)
        extent = 1
        if data is not None and hasattr(data, "what_extent"):
            try:
                extent = max(1, int(data.what_extent(split)))
            except (KeyError, TypeError, ValueError):
                extent = 1
        cache = self.__dict__.setdefault("_what_where_encoders", {})
        encoder = cache.get(str(split))
        if encoder is None:
            encoder = WhereEncoding(
                extent, 4, 0,
                rung_ratio=int(TheXMLConfig.get(
                    "architecture.whereRungRatio", _WHERE_RUNG_RATIO)))
            cache[str(split)] = encoder
        elif int(encoder.maxVal) != extent:
            encoder.set_period(extent)
        return encoder

    def _what_grammar_context(self, questions, *, device, dtype):
        """Build target-free chooser context for a question batch.

        The question's absolute dataset position and its target position are
        given to the chooser both normalized by the split extent and through
        the model's own ``.where`` ladder (``_what_where_encoder``); the
        zero-initialized ``what_projection`` learns the mapping.
        """
        memory = self._what_memory()
        rows = []
        detailed = []
        for b, question in enumerate(questions):
            if memory is not None and hasattr(memory, "what_context"):
                context = memory.what_context(question=question, b=b)
            else:
                context = {
                    "temporal": question.context_values(),
                    "input_mask": (), "output_mask": (),
                    "input_representations": (),
                    "output_representations": (),
                    "open_depth": 0, "parity": True,
                    "closure_pressure": 0.0,
                }
            detailed.append(context)
            encoder = self._what_where_encoder(question.split)
            extent = float(max(1, int(encoder.maxVal)))
            *relation_offset, where, target_where = question.context_values()
            # Out-of-range targets (an unavailable past/future) are left
            # unclamped: the ladder folds them and the normalized scalar
            # leaves [0, 1], so "no such position" stays learnable.
            scalar = torch.tensor(
                tuple(relation_offset) + (
                    where / extent, target_where / extent,
                ), device=device, dtype=dtype)
            where_ladder = torch.cat((
                encoder.encode(where), encoder.encode(target_where),
            )).to(device=device, dtype=dtype)
            memory_scalar = torch.tensor((
                float(sum(context["input_mask"])),
                float(sum(context["output_mask"])),
                float(context["open_depth"]),
                float(context["closure_pressure"]),
            ), device=device, dtype=dtype)
            input_summary = self._what_representation_summary(
                context["input_representations"], device=device, dtype=dtype)
            output_summary = self._what_representation_summary(
                context["output_representations"], device=device, dtype=dtype)
            rows.append(torch.cat((scalar, where_ladder, memory_scalar,
                                   input_summary, output_summary)))
        tensor = torch.stack(rows, dim=0)
        return tensor, tuple(detailed)

    def choose_what_slot(self, question, *, conceptual_input,
                         conceptual_output, produced, iteration=0,
                         closure_pressure=0.0):
        """Chooser seam for answer/defer/close grammatical decisions.

        The clean default records a complete interaction.  Learned grammar
        policies may override this seam to return input-only, balanced, or
        output-only slots; :meth:`think` applies their stack effects
        iteratively through the same ``what()`` evaluator.
        """
        output = conceptual_output if conceptual_output is not None else produced
        kwargs = dict(question=question, iteration=iteration,
                      closure_pressure=closure_pressure)
        choice = self._step_choice_for_row(
            int(getattr(self, "_what_current_row", 0) or 0))
        if choice is None:
            return LTMSlot(input=conceptual_input, output=output,
                           grammar_trace=("grammar:what_answer",), **kwargs)
        # Resolve-step choices (mathematical thinking spec 6.3 / 7.2):
        #   OPEN   -> input-only slot for the ACTIVE question (the root's
        #             conceptual state, or the deferred subquestion's QUERY
        #             symbol); the chosen subquestion becomes pending;
        #   ANSWER -> a complete slot when it answers the pending
        #             subquestion, an output-only slot when it closes an
        #             open LTM input, else the complete root slot.
        row = int(choice.row)
        pending = self.__dict__.setdefault("_what_pending", {})
        memory = self._what_memory()
        open_depth = memory.what_open_depth(b=row) if memory is not None else 0
        referent_entry = {"operation": "what_open_referent",
                          "referent": choice.referent}
        if choice.kind == "open":
            pending[row] = choice.operand
            if choice.role == "open" or (choice.role == "root" and open_depth > 0):
                # The active question is ALREADY an open LTM input: posing
                # another subquestion changes only what is pending; no slot
                # is appended (an opening slot is never duplicated).
                return None
            question_rep = (conceptual_input if choice.role == "root"
                            else choice.question_rep)
            if question_rep is None:
                question_rep = conceptual_input
            return LTMSlot(
                input=question_rep,
                grammar_trace=("grammar:what_open", referent_entry,
                               {"operation": "what_subquestion",
                                "referent": choice.operand}),
                **kwargs)
        pending.pop(row, None)
        answered = {"operation": "what_answer_referent",
                    "referent": choice.referent}
        if choice.role == "pending":
            return LTMSlot(
                input=(choice.question_rep if choice.question_rep is not None
                       else conceptual_input),
                output=output,
                grammar_trace=("grammar:what_answer", answered), **kwargs)
        if open_depth > 0:
            return LTMSlot(output=output,
                           grammar_trace=("grammar:what_close", answered),
                           **kwargs)
        return LTMSlot(input=conceptual_input, output=output,
                       grammar_trace=("grammar:what_answer", answered), **kwargs)

    def what(self, question, input_data=None, *, executor=None,
             execution=None, record=True, iteration=0,
             closure_pressure=0.0, score=None):
        """Produce the model's answer through the existing forward path.

        A sequence of questions shares one batched execution and returns a
        tuple of answers.  A single question returns one ``WhatAnswer``.  The
        target is never accepted by this interface.  ``execution`` lets
        ``runBatch`` or a compatibility test wrap an already-computed clean
        path without a second model pass.
        """
        questions = question_batch(question)
        if not questions:
            raise ValueError("Model.what requires at least one question")
        # Episode bookkeeping for the resolve step (mathematical thinking
        # spec 6): iteration 0 opens fresh scratchpads / pending referents /
        # policy records; later iterations reuse them.
        self._what_current_iteration = int(iteration)
        self._what_current_closure_pressure = float(closure_pressure)
        if int(iteration) == 0:
            self._what_pending = {}
            self._what_policy_records = []
            self._what_root_symbols = {}
            self._what_episode_steps = []          # every iteration's step trace
            self._begin_referents(questions)

        if torch.is_tensor(input_data):
            device = input_data.device
            dtype = (input_data.dtype if input_data.is_floating_point()
                     else torch.float32)
        else:
            try:
                parameter = next(self.parameters())
                device, dtype = parameter.device, parameter.dtype
            except StopIteration:
                device, dtype = TheDevice.get(), torch.float32
        chooser_context, detailed_context = self._what_grammar_context(
            questions, device=device, dtype=dtype)
        language = getattr(getattr(self, "symbolSpace", None),
                           "languageLayer", None)
        # Install the target-free question context on the LanguageLayer AND
        # on every grammar layer with a chooser: the STM bounded-reduce pass
        # calls the grammar layers directly (no ``what_ctx`` threaded), and
        # its choices are the ones the policy objective credits.
        holders = [language] if language is not None else []
        symbol_space = getattr(self, "symbolSpace", None)
        named_modules = getattr(symbol_space, "named_modules", None)
        if callable(named_modules):
            for _name, module in named_modules():
                if (hasattr(module, "chooser") and hasattr(module, "forward")
                        and module is not language):
                    holders.append(module)
        saved = [(h, getattr(h, "_what_context", None),
                  getattr(h, "_what_ltm_context", None)) for h in holders]
        self._active_what_questions = questions
        for h in holders:
            h._what_context = chooser_context
            h._what_ltm_context = detailed_context
        try:
            if execution is None:
                if input_data is None:
                    raise ValueError(
                        "Model.what needs input_data or an existing execution")
                execution = self._execute_input_sentence(input_data, executor)
        finally:
            for h, ctx, detail in saved:
                h._what_context = ctx
                h._what_ltm_context = detail

        _forward_input, symbols, produced_all = self._what_execution_parts(
            execution)
        if produced_all is None:
            raise RuntimeError("Model.what received no produced response")
        previous = getattr(self, "_last_understanding", None)
        self._last_understanding = (
            previous if previous is not None and previous.execution is execution
            else self._capture_understanding(execution))
        self._last_answer_construction = None
        selected_thought_rows = {}
        if getattr(self, "answer_synthesis", False):
            # Complete conceptual resolution before entering surface generation.
            options={} if score is None else {'score':score}
            derivation = self.resolveAnswer(self._last_understanding, questions,**options)
            selected_thought_rows = {
                int(row): result
                for row, result in getattr(derivation, "selected_thoughts", ())
            }
            construction = self.reverseOutput(self._last_understanding, derivation,**options)
            # Use exactly the output whose cost selected each thought. A new
            # output departure cannot change the already compared return.
            for row,costed in getattr(self,'_costed_thought_outputs',{}).items():
                from WalkTrials import select_output
                selected=torch.arange(construction.actual.shape[0],device=construction.actual.device)==row
                construction=select_output(construction,costed,selected)
            self._last_answer_construction=construction
            produced_all = construction.actual
        programs = self._last_understanding.sentence_states
        if programs:
            # The interaction's input is the captured 1-3 idea form, including
            # every retained slot. Neither a one-slot STM view nor a dense
            # symbolic compatibility field owns this input.
            empty = produced_all.new_zeros(3, int(self.conceptualSpace.stm.concept_dim))
            conceptual_all = torch.stack([
                entry.end_state if entry is not None else empty for entry in programs])
        else:
            try:
                conceptual_all = self._reconstruction_seed()
            except (AttributeError, RuntimeError, TypeError):
                conceptual_all = symbols
            if conceptual_all is None:
                conceptual_all = symbols

        memory = self._what_memory()
        count = len(questions)
        answers = []
        for b, current in enumerate(questions):
            produced = self._what_row(produced_all, b, count)
            conceptual_input = self._what_row(conceptual_all, b, count)
            selected = selected_thought_rows.get(b)
            if selected is not None:
                # ``resolveAnswer`` has already executed this completed
                # grammatical question through the ordinary thought owner.
                # A legacy LTMSlot would be a second controller/trace on the
                # same row (and the owner correctly rejects that mixture).
                # Keep the answer/output handoff explicit in the public
                # result, but leave the selected episode as the one record of
                # the question and its actual work/evidence.
                answers.append(WhatAnswer(
                    question=current, what=produced, available=True,
                    provenance="model", source_where=current.where,
                    grammar_trace=({
                        "operation": "selected_thought",
                        "signature": selected.evidence.get("query_signature"),
                        "support_true": selected.evidence["support_true"],
                        "support_false": selected.evidence["support_false"],
                        "work": selected.work.spent,
                        "incomplete": selected.evidence.get("incomplete", ()),
                    },),
                    ltm_slot=None, execution=execution))
                continue
            if memory is not None and memory.thought_state(b=b) is not None:
                # The ordinary controller already owns this row's history.
                # A declarative presentation is retained by the closing, not as
                # a legacy input/output parity slot or a new thought episode.
                answers.append(WhatAnswer(
                    question=current, what=produced, available=True,
                    provenance="model", source_where=current.where,
                    grammar_trace=(), ltm_slot=None, execution=execution))
                continue
            # Rows already at parity with nothing pending are SETTLED at
            # iteration >= 1 (spec 6.2): their answer stands and no further
            # slot is appended for them.
            if (int(iteration) > 0 and memory is not None
                    and memory.what_at_parity(b=b)
                    and (self.__dict__.get("_what_pending") or {}).get(b) is None):
                answers.append(WhatAnswer(
                    question=current, what=produced, available=True,
                    provenance="model", source_where=current.where,
                    grammar_trace=(), ltm_slot=None, execution=execution))
                continue
            # The output half records the response the head actually made.
            # It must not silently substitute the input-side symbol state or
            # the desired Data target when the two differ.
            conceptual_output = produced
            self._what_current_row = b
            slot = self.choose_what_slot(
                current,
                conceptual_input=conceptual_input,
                conceptual_output=conceptual_output,
                produced=produced,
                iteration=iteration,
                closure_pressure=closure_pressure,
            )
            if slot is None:
                # Deferred again without a new opening (the active question
                # is already open in LTM): nothing to append this iteration.
                answers.append(WhatAnswer(
                    question=current, what=None, available=False,
                    provenance="model", reason="answer deferred for thinking",
                    grammar_trace=({"operation": "what_defer",
                                    "iteration": int(iteration),
                                    "closure_pressure": float(closure_pressure)},),
                    ltm_slot=None, execution=execution))
                continue
            if not isinstance(slot, LTMSlot):
                raise TypeError("choose_what_slot must return an LTMSlot")
            trace = ({
                "operation": f"what_{slot.operation.value}",
                "temporal": current.context_values(),
                "ltm": detailed_context[b],
                "iteration": int(iteration),
                "closure_pressure": float(closure_pressure),
            },)
            if slot.operation is WhatSlotOperation.OPEN:
                answer = WhatAnswer(
                    question=current, what=None, available=False,
                    provenance="model", reason="answer deferred for thinking",
                    grammar_trace=trace, ltm_slot=slot,
                    execution=execution)
            else:
                answer = WhatAnswer(
                    question=current, what=produced, available=True,
                    provenance="model", source_where=current.where,
                    grammar_trace=trace, ltm_slot=slot,
                    execution=execution)
            complete = self._compose_completed_rows()
            completed = complete is None or bool(complete[b])
            if record and memory is not None and completed:
                stored = memory.append_what_slot(slot, b=b)
                answer = WhatAnswer(
                    question=answer.question, what=answer.what,
                    available=answer.available,
                    provenance=answer.provenance,
                    source_where=answer.source_where, reason=answer.reason,
                    grammar_trace=answer.grammar_trace,
                    ltm_slot=stored, execution=answer.execution)
            answers.append(answer)
        construction = getattr(self, "_last_answer_construction", None)
        texts = tuple(getattr(construction, "texts", ()) or ())
        if len(texts) == len(answers):
            from dataclasses import replace
            answers = [replace(answer, text=texts[b]) if answer.available else answer
                       for b, answer in enumerate(answers)]
        self._last_what_answers = tuple(answers)
        return answers[0] if isinstance(question, WhatQuestion) else tuple(answers)

    @staticmethod
    def _valid_best_effort(value):
        return not (value is None or (
            isinstance(value, str)
            and value.strip().lower() in {"unknown", "unresolved", "failure"}))

    @staticmethod
    def _batch_row(value, b):
        """Row ``b`` of a batched tensor (``[1, ...]``); scalars and
        non-tensors pass through."""
        if torch.is_tensor(value) and value.dim() > 0 and value.shape[0] > int(b):
            return value[int(b):int(b) + 1]
        return value

    def _best_effort_what(self, answer, input_data, b=0):
        """Choose a concrete forced response for ROW ``b`` without consulting
        a target: the row's constructed response (through ``reverseOutput``
        when the answer path is on), else its input, else a literal."""
        construction = getattr(self, "_last_answer_construction", None)
        produced = getattr(construction, "actual", None)
        if not torch.is_tensor(produced):
            _, _symbols, produced = self._what_execution_parts(answer.execution)
        candidate = self._batch_row(produced, b)
        if self._valid_best_effort(candidate):
            return candidate, candidate
        candidate = self._batch_row(input_data, b)
        if self._valid_best_effort(candidate):
            return candidate, candidate
        # A literal response is preferable to an unscoreable status escape.
        return "?", "?"

    def _thinking_pressure(self, iteration, limit):
        """Closure-pressure schedule (mathematical thinking spec 6.4):
        monotone in the iteration index with ``p(L - 1) = 1``."""
        mode = str(getattr(self, "what_thinking_pressure", "linear") or "linear")
        L = max(2, int(limit))
        x = min(1.0, float(iteration) / float(L - 1))
        if mode == "quadratic":
            return x * x
        if mode == "step":
            return 0.0 if float(iteration) < L / 2.0 else 1.0
        return x

    def think(self, question, input_data, *, max_iterations=None,
              pressure_schedule=None, executor=None):
        """Understand once and resolve through the ordinary thought controller.

        WhatQuestion retains its serving/temporal interface. Any completed
        interrogative program is handled by run_selected_thought with the one
        shared work budget; this adapter owns no iterative frame loop.
        """
        questions = question_batch(question)
        if not questions:
            raise TypeError("Model.think expects one WhatQuestion or a batch")
        if max_iterations is not None and int(max_iterations) < 1:
            raise ValueError("max_iterations must be positive")
        first = self.what(question, input_data, executor=executor, record=True,
                          iteration=0, closure_pressure=0.0)
        answers = first if isinstance(first, tuple) else (first,)
        if not all(answer.available for answer in answers):
            raise RuntimeError("no completed grammatical answer is available")
        result = WhatThinkingResult(
            answer=answers[0], answers=answers,
            slots=[answer.ltm_slot for answer in answers if answer.ltm_slot is not None],
            iterations=1, closure_pressures=[0.0])
        self._last_what_thinking = result
        self._record_thinking(result)
        return result

    def runTrial(self, numEpochs=1, batchSize=10, lr=0.01, profile=None):
        """Main training loop: train for numEpochs, evaluate on test set each epoch.

        Alpha (exploration temperature) anneals from 1.0 (full exploration)
        to 0.0 (full exploitation) over the first 5% of training.  This is
        propagated to all Spaces and their layers/bases via set_sigma().

        A single persistent optimizer is used across all epochs so Adam's
        momentum and variance estimates accumulate properly.

        ``BASIC_RUN_TEST`` env (set by ``train.py --test [N]``) controls
        the baseline + post-train test/validation passes:

        * unset: skip both passes (default; avoids the long test-split
          traversal that can dominate wall-clock at large maxDocs).
        * empty string: run both passes uncapped.
        * integer ``N``: run both passes capped at ``N`` batches each.

        Returns a list of per-epoch test accuracies.
        """
        max_seconds_raw = os.environ.get("BASIC_MAX_SECONDS", "").strip()
        self._training_deadline_reached = False
        self._training_deadline_monotonic = None
        if max_seconds_raw:
            try:
                max_seconds = float(max_seconds_raw)
            except ValueError as exc:
                raise ValueError(
                    "BASIC_MAX_SECONDS must be a number of seconds; got "
                    f"{max_seconds_raw!r}") from exc
            if max_seconds > 0.0:
                self._training_deadline_monotonic = (
                    time.monotonic() + max_seconds)
                TheMessage(
                    f"Training wall-clock cap armed: {max_seconds:g}s "
                    "(checked between completed batches).")

        trainLosses       = [[],[]]  # [output_losses, reconstruction_losses]
        validationLosses  = [[],[]]
        testLosses        = [[],[]]
        self.plot         = False
        accuracy          = []
        from ConceptLessons import teach_concept_lessons
        teach_concept_lessons(self)
        self._optimizer   = self.getOptimizer(lr=lr)

        # Test gating from BASIC_RUN_TEST. Tri-state: None (skip),
        # 0 (uncapped run), positive int (cap each pass at that many
        # batches). The empty-string env value maps to uncapped.
        _test_env = os.environ.get("BASIC_RUN_TEST")
        if _test_env is None:
            _test_max_batches = None  # signal: skip the test passes
            _run_test = False
        else:
            try:
                _n = int(_test_env) if _test_env != "" else 0
            except ValueError:
                _n = 0
            _run_test = True
            _test_max_batches = _n if _n > 0 else None

        # Enable sigma-driven self-annealing for ergodic layers
        self.set_sigma(0.5)

        # Baseline evaluation before any training (gated on --test).
        if _run_test:
            self.set_sigma(0)
            outErr, inErr, allOut, lastIn = self.runEpoch(
                batchSize=batchSize, split="test",
                max_batches=_test_max_batches)
            outErr = outErr.item() if torch.is_tensor(outErr) else outErr
            inErr = inErr.item() if torch.is_tensor(inErr) else inErr
            self.set_sigma(0.5)
            testLosses[0].append(outErr)
            testLosses[1].append(inErr)
            TheMessage(f"Baseline Test Loss: output={outErr:.4f}, reconstruction={inErr:.4f}")
        else:
            TheMessage(
                "Baseline test pass skipped (--test not specified). "
                "Re-invoke train.py with --test to include baseline + "
                "post-epoch evaluation.")

        for epoch in range(numEpochs):
            TheMessage(f"Epoch [{epoch + 1}/{numEpochs}]")

            outErr, inErr, allOut, lastIn = self.runEpoch(optimizer=self._optimizer, batchSize=batchSize, split="train")
            outErr = outErr.item() if torch.is_tensor(outErr) else outErr
            inErr = inErr.item() if torch.is_tensor(inErr) else inErr
            trainLosses[0].append(outErr)
            trainLosses[1].append(inErr)
            TheMessage(f"Train Loss: output={outErr:.4f}, reconstruction={inErr:.4f}")

            if getattr(self, "_training_deadline_reached", False):
                # Do not start another epoch or an optional test traversal:
                # return through the normal runTrial tail so ModelFactory's
                # final autosave still records the last completed update.
                accuracy += [0.0]
                if len(accuracy) < int(numEpochs):
                    accuracy.extend([0.0] * (int(numEpochs) - len(accuracy)))
                TheMessage(
                    "Training wall-clock cap reached; finishing normally "
                    "for final reporting/checkpoint save.")
                break

            if not _run_test:
                # Per-epoch test pass skipped under --test gating.
                # Record sentinel zeros so the epoch's accuracy slot is
                # well-formed; the post-trial summary still reports the
                # train-side losses.
                accuracy += [0.0]
                continue

            self.set_sigma(0)  # suppress exploration during eval
            outErr, inErr, allOut, lastIn = self.runEpoch(
                batchSize=batchSize, split="test",
                max_batches=_test_max_batches)
            outErr = outErr.item() if torch.is_tensor(outErr) else outErr
            inErr = inErr.item() if torch.is_tensor(inErr) else inErr
            self.set_sigma(0.5)  # re-enable for next training epoch
            testLosses[0].append(outErr)
            testLosses[1].append(inErr)

            if not getattr(self.inputSpace.data,
                           "has_supervised_outputs", True):
                accuracy += [0.0]
                TheMessage(
                    f"Test Loss: reconstruction={inErr:.4f} "
                    "(self-supervised corpus; output accuracy disabled)")
            elif not isinstance(allOut, torch.Tensor) or allOut.numel() == 0:
                # No output predictions (empty dataset or no batches)
                accuracy += [0.0]
                TheMessage(f"Test Loss: output={outErr:.4f}, reconstruction={inErr:.4f} (no predictions)")
            elif allOut.dim() == 1:
                predicted = (allOut > 0.5).long()
                actual = (self.outputSpace.getTestOutput().squeeze() > 0.5).long()
                # test_output now lives on CPU (list-of-tensors kept off the
                # accelerator so DataLoader workers can pickle slices); align
                # to the model's device for comparison.
                actual = actual.to(predicted.device)
                total   = predicted.size(0)
                correct = (predicted == actual).sum().item()
                accuracy += [correct / total]
                TheMessage(f"Test Accuracy: {100 * correct / total:.2f}%")
            else:
                _, predicted = torch.max(allOut, 1)
                _, actual = torch.max(self.outputSpace.getTestOutput(), 1)
                actual = actual.to(predicted.device)
                total   = predicted.size(0)
                correct = (predicted == actual).sum().item()
                accuracy += [correct / total]
                TheMessage(f"Test Accuracy: {100 * correct / total:.2f}%")

            if profile:
                profile.step()

        TheMessage(f"Final Stats:")
        TheReport.plotLoss(self.name, trainLosses, validationLosses, testLosses)
        self.rCorrect = TheReport.mnistReport(self)

        # Post-training: dump the hard selected grammar per
        # test row so the user can read the discrete derivation the
        # router committed to. Useful for grammar-from-chart inspection
        # (XOR_grammar.xml et al.).
        try:
            ss = self.symbolSpace
            router = getattr(ss, 'languageLayer', None) if ss is not None else None
            if router is not None:
                rules = ss.current_rules
                gen_rules = ss.generate_rules
                from Language import TheGrammar
                def _decode(rule_id):
                    rid = int(rule_id)
                    if 0 <= rid < len(TheGrammar.rules):
                        rd = TheGrammar.rules[rid]
                        return f"{rid}:{rd.canonical}"
                    return f"{rid}:?"
                TheMessage("=== Selected operation grammar ===")
                def _decode_row(row):
                    head, omitted, tail = _grammar_row_preview(row)
                    decoded = [_decode(rid) for rid in head]
                    if omitted:
                        decoded.append(f"... {omitted} rules omitted ...")
                        decoded.extend(_decode(rid) for rid in tail)
                    return decoded
                max_report_rows = int(os.environ.get(
                    "BASIC_GRAMMAR_REPORT_MAX_ROWS", "4"))
                for space_role, rows in (rules or {}).items():
                    TheMessage(f"  compose space_role={space_role!r}:")
                    report_rows = _grammar_rows_for_report(rows)
                    shown_rows = (report_rows if max_report_rows <= 0
                                  else report_rows[:max_report_rows])
                    for b, row in enumerate(shown_rows):
                        decoded = _decode_row(row)
                        TheMessage(f"    row[{b}] = {decoded}")
                    if len(shown_rows) < len(report_rows):
                        TheMessage(
                            f"    ... {len(report_rows) - len(shown_rows)} "
                            "batch rows omitted ...")
                for space_role, rows in (gen_rules or {}).items():
                    TheMessage(f"  generate space_role={space_role!r}:")
                    report_rows = _grammar_rows_for_report(rows)
                    shown_rows = (report_rows if max_report_rows <= 0
                                  else report_rows[:max_report_rows])
                    for b, row in enumerate(shown_rows):
                        decoded = _decode_row(row)
                        TheMessage(f"    row[{b}] = {decoded}")
                    if len(shown_rows) < len(report_rows):
                        TheMessage(
                            f"    ... {len(report_rows) - len(shown_rows)} "
                            "batch rows omitted ...")
                if getattr(router, '_last_root_state', None) is not None:
                    rs = router._last_root_state.detach()
                    TheMessage(f"  S root state shape = {tuple(rs.shape)}")
                    n_root_rows = int(rs.shape[0])
                    shown_root_rows = (n_root_rows if max_report_rows <= 0
                                       else min(n_root_rows, max_report_rows))
                    root_dim_limit = int(os.environ.get(
                        "BASIC_GRAMMAR_REPORT_MAX_DIMS", "32"))
                    for b in range(shown_root_rows):
                        vec = rs[b, 0].tolist()
                        if root_dim_limit > 0:
                            head, omitted, tail = _grammar_row_preview(
                                vec, limit=root_dim_limit)
                        else:
                            head, omitted, tail = vec, 0, []
                        preview = [round(v, 4) for v in head]
                        if omitted:
                            preview.append(f"... {omitted} dims omitted ...")
                            preview.extend(round(v, 4) for v in tail)
                        TheMessage(f"    row[{b}] root = {preview}")
                    if shown_root_rows < n_root_rows:
                        TheMessage(
                            f"    ... {n_root_rows - shown_root_rows} root "
                            "rows omitted ...")
        except Exception as _exc:
            import logging
            logging.getLogger(__name__).warning(
                "post-training grammar dump failed: %s", _exc)

        # Reconstruction report: run final test pass and show input vs reconstructed
        if self.reversible and self.inputSpace.model_type == "embedding":
            self._reconstructionReport()

        self.trainLosses = trainLosses
        self.testLosses  = testLosses
        return accuracy
    
    BatchResult = namedtuple('BatchResult', [
        'outputPred', 'symbols', 'lossOut', 'lossIn', 'inputPred', 'forwardInput',
    ])

    def trainEmbeddings(self, trainMod, index, split, *, errors=None):
        """Run one SBOW training step on the sample at (index, split).

        ``trainMod`` is the iterable of training-embedding modes that
        should fire (e.g. {'SBOW'}); the call is a no-op when the
        configured ``train_embedding`` isn't in that set or when the
        lexer is byte-mode (perceptual SBOW replaces InputSpace SBOW).
        Returns the per-step loss or None.
        """
        sbow = None
        te = getattr(self, 'train_embedding', 'NONE')
        if te in trainMod:
            # Skip InputSpace SBOW/CBOW when lexer=byte -- perceptual SBOW
            # replaces it (see perceptual_sbow_loss).
            if getattr(self, 'lexer', None) in ('byte', 'bytes'):
                return None
            emb = self.perceptualSpace.vocabulary
            if isinstance(emb, Embedding):
                sentences = self._get_sentences(split)
                if sentences and index < len(sentences):
                    sentence = sentences[index]
                    words = [t for t, _ in parse(sentence, lex='words')]
                    if te in ('JOINT'):
                        sbow = self.perceptualSpace.sbow_loss(words, errors=errors)
                    elif te in ('CBOW', 'SBOW', 'BOTH'):
                        # CBOW uses padded context; SBOW and BOTH use the faster centroid method
                        method = 'CBOW' if te == 'CBOW' else 'SBOW'
                        self.perceptualSpace.train_embeddings(words, method=method)
        return sbow

    def perceptual_sbow_loss(self, *, errors=None):
        """SBOW loss over the percepts USED in the forward, WITH negative
        sampling (the pode/antipode repulsion).

        Each used percept is trained toward the leave-one-out centroid of the
        OTHER used percepts in its row, while K random codebook rows are
        repelled -- ``PretrainModel.sbow_loss_indices`` -> the canonical
        ``_neg_sampling_loss`` in embed.py. Two things make this NOT collapse,
        where the prior centroid-only cosine did (every row decoded to the
        null percept): (1) the positives are exactly the gathered percept ids,
        excluding the null/padding slots AND the untrained reserve -- we train
        ONLY the vectors used in the computation; (2) the negative samples
        supply the antipode repulsion that balances the centroid attractor.

        Returns a scalar loss tensor, or None when the percept-index path is
        unavailable or every row holds < 2 used percepts.
        """
        ps_space = getattr(self, "perceptualSpace", None)
        sub = getattr(ps_space, "subspace", None) if ps_space is not None else None
        cb = getattr(sub, "what", None) if sub is not None else None
        pretrain = getattr(cb, "pretrain", None) if cb is not None else None
        fwd = getattr(ps_space, "_forward_input", None) if ps_space is not None else None
        if (pretrain is None
                or not hasattr(pretrain, "sbow_loss_indices")
                or fwd is None or "indices" not in fwd):
            return None
        pid_grid = fwd["indices"]
        if not torch.is_tensor(pid_grid) or pid_grid.dim() != 2:
            return None
        # Resolve the null/padding percept id so its slots are excluded.
        null_pid = None
        ps_store = fwd.get("percept_store", None)
        if ps_store is not None:
            try:
                null_pid = ps_store.get_id(b"\x00")
            except Exception:
                null_pid = None
        null_pid = int(null_pid) if null_pid is not None else None
        terms = []
        for row in pid_grid.detach().cpu().tolist():
            used = [int(p) for p in row
                    if null_pid is None or int(p) != null_pid]
            if len(used) < 1:
                continue
            t = pretrain.sbow_loss_indices(used, errors=errors)
            if t is not None:
                terms.append(t)
        if not terms:
            return None
        return torch.stack(terms).mean()

    def conceptual_sbow_loss(self, *, errors=None):
        """Rotation SBOW (CBOW-NS) over the per-concept similarity codebook.

        Snaps each parked all-siblings concept-slab position to its nearest
        similarity-codebook row by cosine (no grad -- self-supplied concept
        identity), gathers those rows as the SBOW window, and situates them via
        ``embed.conceptual_sbow_loss_codes``. The gather is grad-bearing, so the
        rotation gradient (tangential, radius-preserving) trains the codebook
        rows as the per-concept located codes. Returns a scalar tensor, or
        ``None`` when the codebook / parked slab is unavailable or serial.

        NOTE (2026-06-24, HISTORICAL for the sparse path): the ConceptualSpace
        has NO forward codebook -- its ``.what`` is a *computed* Tensor from
        the percept binding -- so situating the codebook alone could not
        differentiate the conceptual representation. RESOLVED 2026-07-02 (plan
        C1) for sparse-active configs: the parked slab is the LIVE composed
        code (grad-bearing through the SparseLayer families), and the SBOW
        situates the CODES against the codebook pool -- the window is the
        slab, not the snapped rows -- so co-location trains the
        percept->concept binding upstream. The no-grad snap-gather below
        remains the sparse-INACTIVE legacy path.
        """
        cs = getattr(self, "conceptualSpace", None)
        cb = getattr(cs, "similarity_codebook", None) if cs is not None else None
        slab = getattr(self, "_cs_parallel_slab", None)
        cs_src = getattr(self, "_cs_parallel_slab_cs", None)
        object.__setattr__(self, "_cs_parallel_slab", None)  # consume-once
        object.__setattr__(self, "_cs_parallel_slab_cs", None)
        if cs_src is not None:
            # Live sparse path: pool from the dictionary that composed the slab
            # (the parked stage CS), not the terminal codebook.
            cb = getattr(cs_src, "similarity_codebook", None) or cb
        if cb is None or slab is None or self.word_brackets:
            return None
        if not torch.is_tensor(slab) or slab.dim() != 3 or slab.shape[1] < 2:
            return None
        rows = cb.prototype()
        if rows is None or not torch.is_tensor(rows) or rows.shape[0] < 1:
            return None
        eps = 1e-8
        D = min(int(slab.shape[-1]), int(rows.shape[-1]))
        slab = slab[..., :D]
        rows = rows[..., :D]
        from embed import conceptual_sbow_loss_codes
        if slab.requires_grad:
            # Sparse-active live codes (plan C1): the window IS the composed
            # code slab; situating it differentiates the sparse binding.
            return conceptual_sbow_loss_codes(slab, pool=rows, scale=1.0, errors=errors)
        with torch.no_grad():
            s = slab / slab.norm(dim=-1, keepdim=True).clamp_min(eps)
            r = rows / rows.norm(dim=-1, keepdim=True).clamp_min(eps)
            assign = torch.einsum('bnd,vd->bnv', s, r).argmax(dim=-1)   # [B, N]
        window = rows[assign]                                           # [B, N, D]
        return conceptual_sbow_loss_codes(window, pool=rows, scale=1.0, errors=errors)

    def _reconstruction_seed(self):
        """The terminal C-space event seeding the reconstruction reverse.

        PARALLEL mode prefers the LIVE stage carrier (``_combine_last_cs_sub``)
        over the detached STM snapshot: the reverse chain is
        input-differentiable, so a live seed lets ``lossRev`` train the
        forward representation to be reversible. With the detached snapshot
        the loss was a CONSTANT -- no gradient anywhere -- the 2026-07-02
        MM-20M "recon does not converge" root cause. The STM snapshot itself
        stays detached (memory, not a gradient carrier); SERIAL keeps the
        snapshot's reduced-single-idea convention. ``None`` when no usable
        seed exists."""
        serial = bool(getattr(self, 'word_brackets', False))
        if not serial:
            live = getattr(self, "_combine_last_cs_sub", None)
            ev = (live.materialize()
                  if live is not None and hasattr(live, "materialize")
                  else None)
            if (ev is not None and torch.is_tensor(ev) and ev.dim() == 3
                    and ev.shape[1] >= 1):
                return ev
        stm = (self.conceptualSpace.stm
               if self.conceptualSpace is not None else None)
        snap = stm.snapshot() if stm is not None else None
        if (snap is not None and torch.is_tensor(snap)
                and snap.dim() == 3 and snap.shape[1] >= 1):
            return snap if not serial else snap[:, :1, :]
        return None

    def _maybe_compile_brick(self):
        """One-shot Inductor / Dynamo / TF32 setup on first ``runBatch``.

        The actual ``torch.compile`` call lives in ``util.compile`` (the
        canonical compile site, called once at model build in
        ``ModelFactory.run``). This method just configures Dynamo /
        Inductor knobs that are useful regardless of which mode the
        canonical site picked, and enables TF32 for fp32 matmuls.
        Idempotent: only runs on the first invocation.
        """
        if getattr(self, '_brick_compile_attempted', False):
            return
        self._brick_compile_attempted = True
        if not torch.cuda.is_available():
            return
        try:
            dev_type = TheDevice.get().type
        except Exception:
            dev_type = None
        if dev_type != "cuda":
            return
        try:
            import torch._dynamo as _dynamo
            # Bump the cache size limit so warm-up across dtype/shape
            # variants in the cursor path doesn't recompile.
            _dynamo.config.cache_size_limit = max(
                64, int(getattr(_dynamo.config, 'cache_size_limit', 0) or 0))
            # Allow Dynamo to capture ``int(tensor.item())`` patterns
            # rather than break the graph at every site.
            _dynamo.config.capture_scalar_outputs = True
            # Enable TF32 on Ampere+ / Blackwell tensor cores for fp32
            # matmuls -- free perf win on TF32-capable CUDA hardware.
            try:
                torch.set_float32_matmul_precision('high')
            except Exception:
                pass
            # Raise the CUDAGraph "distinct sizes" warning limit. The
            # default (8) is conservative for models with N-halving
            # stages, where shapes across stages form an ``log2(N)``
            # sequence (each is static per stage). Set to 128 so the
            # warning only fires on genuinely-pathological shape variance.
            try:
                torch._inductor.config.triton.cudagraph_dynamic_shape_warn_limit = 128
            except Exception:
                pass
            # The complete canonical word loop has one fixed W/B layout and
            # is exactly the graph we want CUDA to capture. Older segmented
            # paths retain the dynamic-shape skip so their many N-halving
            # specializations do not each pay a capture cost.
            try:
                torch._inductor.config.triton.cudagraph_skip_dynamic_graphs = (
                    not bool(getattr(
                        self, "_compiled_word_loop_fullgraph", False)))
            except Exception:
                pass
        except Exception as e:
            print(
                f"[BasicModel] §7 dynamo / inductor setup failed: "
                f"{type(e).__name__}: {e}. Continuing without these "
                f"hints; util.compile's torch.compile is unaffected.")

    def _flush_partspace_promotions(self, optimizer=None):
        """Activate queued rows without changing any compiled tensor shape."""
        flush = getattr(getattr(self, "perceptualSpace", None), "flush_pending_promotions", None)
        return flush(optimizer=optimizer) if callable(flush) else None

    def _normalize_perceptual_embedding(self):
        """Re-project only the legacy lexicon Embedding after a train step.

        The post-step projection was introduced for ``Embedding`` rows.  A
        radix PartSpace owns a ``Codebook`` in the same ``subspace.what``
        position; calling generic ``Basis.normalize()`` there reads/transforms
        every physical percept row and then rewrites the table.  Radix reads
        are already bounded by the percept UNORM STE and must not take this
        lexicon-only full-capacity path.
        """
        emb = getattr(
            getattr(self.perceptualSpace, "subspace", None), "what", None)
        if isinstance(emb, Embedding):
            emb.normalize()

    def _stage_reading_word_concepts(self):
        """Admit native word objects before either binding enters its graph.

        TEMPORARY reading forcing (item 7 §§17–18): run the whole interpret
        unary on every read word, including its object and DEF row. Reading
        mode will eventually decide when an object is interpreted. The
        learned mixing of the two percept towers remains in place.
        """
        self._reading_word_percepts = None
        self._reading_word_extents = None
        attention=getattr(self,'_attention_words',None)
        self.inputSpace._ar_grammar_leaf_mask = None if attention is None else attention.accepted
        for name in ('rows', 'orders', 'atoms'):
            setattr(self.inputSpace, '_ar_grammar_object_' + name, None)
        if self._aligned_serial_word_mode():
            return  # the canonical word boundary already calls interpret
        self._stage_mixing_grammar_leaf_mask()
        ps, ws, owner = self.perceptualSpace, self.wholeSpaces[0], self._concept_owner()
        fi = getattr(ps, '_forward_input', None) or {}
        raw = self._staged_concepts_in
        ids = fi.get('native_indices', fi.get('indices'))
        if not torch.is_tensor(raw) or not torch.is_tensor(ids):
            return
        spans = fi.get('native_part_spans', fi.get('part_spans'))
        if not torch.is_tensor(spans):
            # The lexicon's native units are tokens, including separator
            # tokens. Give those observed units their original byte extents.
            spans = ids.new_zeros(*ids.shape, 2)
            for b, tokens in enumerate(fi.get('tokens', ())):
                offset = 0
                for i, token in enumerate(tokens[:ids.shape[1]]):
                    end = offset + len(str(token).encode('latin1', 'replace'))
                    spans[b, i] = spans.new_tensor((offset, end))
                    offset = end
        from Meronomy import percept_spans
        raw_rows = raw.detach().to('cpu').reshape(raw.shape[0], -1).long().tolist()
        id_rows, span_rows = ids.detach().to('cpu').tolist(), spans.detach().to('cpu').tolist()
        extents, grammar_words = [], []
        for b, values in enumerate(raw_rows):
            data = bytes(values).split(b'\0', 1)[0]
            words = []
            for lo, hi in percept_spans(data):
                attended=getattr(self,'_attention_spans',None)
                if attention is not None and torch.is_tensor(attended):
                    if not bool((attention.accepted[b] & (attended[b,:,0]==lo) & (attended[b,:,1]==hi)).any()):
                        continue
                # A single byte at a clipped input edge is still a percept,
                # not an identified word. Complete one-letter words remain
                # eligible, including when their supplied sentence ends here.
                sentences = getattr(self.inputSpace, '_last_sentences', None)
                complete = (sentences is not None and b < len(sentences)
                            and len(sentences[b].encode('utf-8')) <= len(data))
                if hi - lo == 1 and hi == len(data) == len(values) and not complete:
                    continue
                selected = [i for i, (a, z) in enumerate(span_rows[b])
                            if lo <= a < z <= hi and id_rows[b][i] >= 0]
                if not selected:
                    continue
                # Admit only the part of the input actually exposed by PS.
                # A truncated or unresolved native unit cannot name unseen bytes.
                if sum(span_rows[b][i][1] - span_rows[b][i][0] for i in selected) != hi - lo:
                    continue
                form = data[lo:hi].decode('latin1')
                word = owner.interpret.lookup_word([id_rows[b][i] for i in selected],
                    ws.property_rows_for_bytes(data[lo:hi]), form=data[lo:hi], word_reading=True)
                if word is not None:
                    object_id = owner.interpret.forward(word)
                    if object_id is not None:
                        grammar_words.append((b, lo, hi, form, selected[-1], word, object_id))
                words.append((lo, hi))
            extents.append(words)
        width = max(map(len, extents), default=0)
        if not width:
            return
        brackets = spans.new_tensor([row + [(0, 0)] * (width - len(row)) for row in extents])
        positions, _ = ws.concept_evidence_layout(raw, int(ws.inputShape[0]))
        self._reading_word_percepts = (ids, spans,
            getattr(ws.subspace.what, 'primitive_properties', None), raw, positions)
        self._reading_word_extents = brackets
        self._stage_reading_grammar_references(grammar_words, fi)

    def _stage_mixing_grammar_leaf_mask(self):
        """Keep whitespace in perception, but off the mixing grammar's stack.

        Classify the staged unit's observed surface, independently of whether
        its word or object identity has been admitted. Unknown surfaces and
        punctuation keep their existing grammar admission.
        """
        isp = self.inputSpace
        active = getattr(isp, '_word_active_mask', None)
        if not torch.is_tensor(active):
            return
        percepts = getattr(self.perceptualSpace, '_forward_input', None) or {}
        texts = percepts.get('word_texts')
        spans = percepts.get('part_spans')
        raw = getattr(self, '_staged_concepts_in', None)
        if torch.is_tensor(spans) and torch.is_tensor(raw):
            spans = spans.detach().cpu().tolist()
            raw = raw.detach().cpu().reshape(raw.shape[0], -1).long().tolist()
        else:
            spans = raw = None
        tokens = percepts.get('tokens', ())
        leaves = active.detach().cpu().clone()
        for b, row in enumerate(leaves.tolist()):
            for w, present in enumerate(row):
                if not present:
                    continue
                surface = None
                if (texts is not None and b < len(texts) and texts[b] is not None
                        and w < len(texts[b])):
                    surface = texts[b][w]
                elif spans is not None and b < len(spans) and w < len(spans[b]):
                    lo, hi = spans[b][w]
                    if 0 <= lo < hi <= len(raw[b]):
                        surface = bytes(raw[b][lo:hi]).decode('utf-8', errors='replace')
                elif b < len(tokens) and w < len(tokens[b]):
                    surface = tokens[b][w]
                if isinstance(surface, bytes):
                    surface = surface.decode('utf-8', errors='replace')
                if isinstance(surface, str) and surface.isspace():
                    leaves[b, w] = False
        attention=getattr(self,'_attention_words',None)
        isp._ar_grammar_leaf_mask = leaves.to(active.device)
        if attention is not None:isp._ar_grammar_leaf_mask &= attention.accepted

    def _stage_reading_grammar_references(self, words, percepts):
        """Stage only the mixing grammar's admitted OBJECT leaves.

        Reading already admitted these identities. Resolve their physical
        rows once, at the eager boundary; grammar receives full codes without
        consulting the lexicon or allocating another concept in its loop.
        """
        isp = self.inputSpace
        active = getattr(isp, '_word_active_mask', None)
        if not getattr(self, 'word_brackets', False) or not torch.is_tensor(active):
            return
        B, W = active.shape
        owner = self._concept_owner()
        rows = torch.full_like(active, -1, dtype=torch.long)
        object_orders = rows.clone()
        object_ids = rows.clone()
        offsets = getattr(isp, '_ar_word_part_offsets', None)
        texts = percepts.get('word_texts')
        word_major = torch.is_tensor(offsets) and offsets.ndim == 3 and texts is not None
        starts = offsets[:, :, 0].detach().cpu().tolist() if word_major else None
        loop_spans = percepts.get('part_spans')
        loop_spans = (loop_spans.detach().cpu().tolist()
                      if torch.is_tensor(loop_spans) else None)
        active_host = active.detach().cpu().tolist()
        for b, lo, hi, form, native_last, word_id, object_id in words:
            if word_major and texts[b] is not None:
                columns = [p for p in range(W) if active_host[b][p]
                           and starts[b][p] == lo and p < len(texts[b])
                           and texts[b][p] == form]
            elif loop_spans is not None:
                columns = [p for p, (a, z) in enumerate(loop_spans[b][:W])
                           if active_host[b][p] and lo <= a < z == hi]
            else:
                columns = [native_last] if native_last < W else []
            if len(columns) != 1:
                continue  # an unresolved/clipped percept cannot claim a word
            p = columns[0]
            if not active_host[b][p]:
                continue
            row = owner._csw_row_of(object_id)
            if row is None:
                continue
            rows[b, p] = int(row)
            object_ids[b, p] = int(object_id)
            object_orders[b, p] = int(owner._concept_source_order(object_id))
        atoms = owner.similarity_codebook.lookup_rows(rows.clamp_min(0))
        atoms = atoms * rows.ge(0)[..., None].to(atoms.dtype)
        # These references select the grammar's numerical leaves. They do
        # not publish native word identities, lexical roles or evidence in
        # a binding whose symbolic reading has not supplied those products.
        isp._ar_grammar_object_rows = rows
        isp._ar_grammar_object_ids = object_ids
        isp._ar_grammar_object_orders = object_orders
        isp._ar_grammar_object_atoms = atoms

    def _publish_reading_symbols(self, concept_sub):
        """Publish the native word evidence through its concept identities."""
        percepts = getattr(self, '_reading_word_percepts', None)
        if percepts is None or concept_sub is None:
            return None
        owner = self._concept_owner()
        if owner._sparse_active() and torch.is_tensor(
                getattr(concept_sub, '_concept_activations', None)):
            # The completed symbolic phase includes higher-order and negative
            # evidence; retain that field instead of rereading its word leaves.
            return self.symbolSpace.forward_concept_to_symbol(concept_sub)
        field = owner.cs_read_memberships(percepts, self._reading_word_extents)
        codes = owner._field_codes(owner.similarity_codebook.getW())
        # The read supplies order-zero evidence. Native field metadata also
        # includes allocated higher-order rows, which remain silent here.
        # Keep their axes aligned without manufacturing higher-order support.
        field = torch.cat((field, field.new_zeros(
            codes.shape[-2] - field.shape[0], *field.shape[1:])))
        # Symbolization reads the native field; the continuous mixing carrier
        # remains the forward/reconstruction state of ConceptualSpace.
        for name, value in dict(activations=field,
                codes=codes,
                ids=owner._cs_field_concept_ids, inventory_rows=owner._cs_field_rows,
                where=owner._cs_field_where, when=owner._cs_field_when).items():
            object.__setattr__(concept_sub, '_concept_' + name, value)
        object.__setattr__(concept_sub, '_concept_code_owner',
                           next(i for i, cs in enumerate(self.conceptualSpaces) if cs is owner))
        object.__setattr__(concept_sub, '_thought_occurrence', None)
        return self.symbolSpace.forward_concept_to_symbol(concept_sub)

    def _stage_serial_concept_rows(self):
        """Resolve each staged word to one exact joint CS identity eagerly.

        The compiled word cell must never walk Python relation dictionaries or
        scan the million-row concept inventory. At this boundary we therefore
        resolve ``surface + PS parts + WS properties`` against the durable
        word/location concept ``A`` and park only its codebook row. First-sight
        identities are admitted atomically at this safe pre-graph boundary;
        an admission refused at capacity remains the exact ``-1`` unknown.

        Stage 0 owns the relation identities while every aligned CS stage
        shares the same physical concept dictionary, so a row resolved here is
        valid for the terminal serial cell's indexed decode.
        """
        isp = getattr(self, "inputSpace", None)
        if isp is None:
            return None
        ws = getattr(self, "wholeSpace", None)
        if ws is not None:
            object.__setattr__(ws, "_staged_word_primitive_counts", None)
            object.__setattr__(ws, "_staged_word_property_spans", None)
        isp._ar_word_concept_rows = None
        isp._ar_word_concept_ids = None
        isp._ar_word_concept_orders = None
        isp._ar_word_lexical_forms = {}
        isp._ar_word_symbol_where = None
        isp._ar_word_symbol_when = None
        isp._ar_word_object_rows = None
        isp._ar_word_object_ids = None
        isp._ar_word_object_orders = None
        isp._ar_word_concept_atoms = None
        isp._ar_word_object_atoms = None
        isp._ar_concept_lookup_rows = None
        isp._ar_concept_lookup_atoms = None
        isp._ar_concept_lookup_sentence_ids = None
        for name in ("_ar_percept_reference_codes", "_ar_percept_reference_roles",
                     "_ar_part_reference_vectors", "_ar_whole_reference_vectors",
                     "_ar_readout_coefficients", "_ar_whole_reference_presence"):
            setattr(isp, name, None)
        aligned = self._aligned_serial_word_mode()
        if not aligned:
            return None

        part_ids = getattr(isp, "_ar_word_part_ids", None)
        part_mask = getattr(isp, "_ar_word_part_mask", None)
        active = getattr(isp, "_word_active_mask", None)
        ps_fwd = getattr(getattr(self, "perceptualSpace", None),
                         "_forward_input", None)
        word_texts = (ps_fwd.get("word_texts")
                      if isinstance(ps_fwd, dict) else None)
        if (not torch.is_tensor(part_ids) or part_ids.dim() != 3
                or not torch.is_tensor(part_mask)
                or tuple(part_mask.shape) != tuple(part_ids.shape)
                or not torch.is_tensor(active) or active.dim() != 2
                or tuple(active.shape) != tuple(part_ids.shape[:2])
                or word_texts is None):
            return None

        spaces = list(getattr(self, "conceptualSpaces", None) or ())
        owner = spaces[0] if spaces else getattr(self, "conceptualSpace", None)
        alloc = getattr(owner, "_concept_allocator", None)
        if owner is None or ws is None:
            rows = torch.full(
                active.shape, -1, dtype=torch.long, device=part_ids.device)
            isp._ar_word_concept_rows = rows
            isp._ar_word_concept_ids = rows.clone()
            isp._ar_word_concept_orders = rows.clone()
            isp._ar_word_object_rows = rows.clone()
            isp._ar_word_object_ids = rows.clone()
            isp._ar_word_object_orders = rows.clone()
            return rows

        self._word_observation_serial = int(getattr(self, "_word_observation_serial", 0)) + 1
        B, W, P = (int(part_ids.shape[0]), int(part_ids.shape[1]),
                   int(part_ids.shape[2]))
        stage_word_properties = getattr(
            ws, "stage_word_primitives", None)
        if callable(stage_word_properties):
            word_offsets = None
            part_offsets = getattr(isp, "_ar_word_part_offsets", None)
            if (torch.is_tensor(part_offsets)
                    and tuple(part_offsets.shape) == tuple(part_ids.shape)):
                word_offsets = part_offsets[:, :, 0]
            stage_word_properties(
                word_texts, active, word_offsets=word_offsets)
        pid_host = part_ids.detach().to("cpu").reshape(B, W, P).tolist()
        mask_host = part_mask.detach().to("cpu").reshape(B, W, P).tolist()
        attention = getattr(self, "_attention_words", None)
        admitted = active if attention is None else active & attention.accepted
        active_host = admitted.detach().to("cpu").reshape(B, W).tolist()
        row_host = [[-1] * W for _ in range(B)]
        cid_host = [[-1] * W for _ in range(B)]
        order_host = [[-1] * W for _ in range(B)]
        object_row_host = [[-1] * W for _ in range(B)]
        object_cid_host = [[-1] * W for _ in range(B)]
        object_order_host = [[-1] * W for _ in range(B)]
        reference_codes = [[[-1] * 8 for _ in range(W)] for _ in range(B)]
        reference_roles = [[[-1] * 8 for _ in range(W)] for _ in range(B)]
        pending = []
        # Perceptual passes change attention, not conceptual order. Native
        # word definitions are order 0; only symbolization raises an object.
        fold_support = owner._ordered_fold_support((), ())
        definitions = owner.definitions
        language = getattr(self, "languageSpace", None)
        if language is None:
            language = getattr(getattr(self, "symbolSpace", None),
                               "languageSpace", None)
        anchors = getattr(language, "_surface_anchors", {})
        lexical_forms = isp._ar_word_lexical_forms

        def _raw_int_refs(refs):
            out = set()
            for ref in refs or ():
                if isinstance(ref, tuple):
                    continue
                try:
                    out.add(int(ref))
                except (TypeError, ValueError):
                    continue
            return out

        for b in range(B):
            texts_b = word_texts[b] if b < len(word_texts) else ()
            for p in range(W):
                if not bool(active_host[b][p]):
                    continue
                value = texts_b[p] if p < len(texts_b) else None
                if value is None:
                    pending.append((b, p, None))
                    continue
                key = str(value)
                word_id = definitions.word(form=key)
                triple = None if word_id is None else (word_id, definitions.deref(word_id))
                ordered_parts = [
                    int(pid_host[b][p][j]) for j in range(P)
                    if bool(mask_host[b][p][j])
                    and int(pid_host[b][p][j]) >= 0
                ]
                current_parts = set(self.perceptualSpace.fuse_parts(ordered_parts))
                current_wholes = set(int(v) for v in
                                     ws.property_rows_for_bytes(key))
                if triple is None:
                    # First sight is admitted here, at the same eager boundary
                    # that already owns radix admission and WS analysis. The
                    # aligned dictionary is physically fixed-capacity, so this
                    # mutates only bounded relation records, the active-prefix
                    # mask, and row metadata before any graph uses them. Exhaustion
                    # raises with nVectors named before partial admission.
                    triple = owner.interpret_word(
                        ordered_parts, sorted(current_wholes), key=key,
                        occurrence=(self._word_observation_serial, b, p))
                    if triple is None:
                        pending.append((b, p, key))
                        continue
                    alloc = getattr(owner, "_concept_allocator", None)
                A = int(triple[0])
                object_id = owner.interpret.forward(A, occurrence=(
                    self._word_observation_serial, b, p))
                stored_parts = _raw_int_refs(owner.concept_parts(A))
                stored_wholes = _raw_int_refs(owner.concept_wholes(A))
                # Surface identity alone is not enough: the active PS/WS
                # support must already belong to the durable concept. A trie
                # promotion or newly-discovered property therefore receives an
                # honest unknown tick, then autobind accrues it at Reset.
                if not current_parts.issubset(set(self.perceptualSpace.fuse_parts(stored_parts))):
                    pending.append((b, p, key))
                    continue
                row = owner._csw_row_of(object_id)
                if row is None:
                    pending.append((b, p, key))
                    continue
                object_order = int(owner._concept_source_order(object_id))
                object_row = owner._csw_row_of(object_id)
                if object_row is None:
                    object_row = owner._csw_concept_row(
                        object_order, object_id)
                if object_row is None:
                    pending.append((b, p, key))
                    continue
                row_host[b][p] = int(row)
                # Resolve lexical anchoring while the forward owns the word's
                # segmented surface and exact WORD row.  A canonical OBJECT
                # may be shared by converse forms, so it is not this key.
                # Capture later reads only this per-staging provenance; it
                # must not reclassify a completed word from transient text.
                if int(row) not in lexical_forms:
                    form = (anchors.get(value.casefold())
                            if isinstance(value, str) else None)
                    lexical_forms[int(row)] = form if isinstance(form, str) else None
                slots = owner.concepts_from_percepts.admit_references(
                    row, stored_parts, stored_wholes)
                for slot, (role, code) in enumerate(slots):
                    reference_codes[b][p][slot] = code
                    reference_roles[b][p][slot] = role
                cid_host[b][p] = A
                # One utility observation per resolved unit (contract 4):
                # counted once per presentation at the boundary Reset.
                if hasattr(owner, "propose_utility_observation"):
                    owner.propose_utility_observation(
                        A, sorted(current_parts) + [10_000_000 + w for w in sorted(current_wholes)])
                record = owner.record_concept_fold_support(
                    A, fold_support, owner._concept_source_order(A))
                order_host[b][p] = int(record["actual_order"])
                object_row_host[b][p] = int(object_row)
                object_cid_host[b][p] = object_id
                object_order_host[b][p] = object_order

        rows = torch.tensor(row_host, dtype=torch.long, device=part_ids.device)
        object_rows = torch.tensor(
            object_row_host, dtype=torch.long, device=part_ids.device)
        isp._ar_word_concept_rows = rows
        isp._ar_word_concept_ids = torch.tensor(
            cid_host, dtype=torch.long, device=part_ids.device)
        isp._ar_word_concept_orders = torch.tensor(
            order_host, dtype=torch.long, device=part_ids.device)
        isp._ar_word_object_rows = object_rows
        isp._ar_word_object_ids = torch.tensor(
            object_cid_host, dtype=torch.long, device=part_ids.device)
        isp._ar_word_object_orders = torch.tensor(
            object_order_host, dtype=torch.long, device=part_ids.device)
        registry = getattr(self, 'where_registry', None)
        if registry is not None:
            offsets = getattr(isp, '_ar_word_part_offsets', None)
            if (not torch.is_tensor(offsets) or offsets.ndim != 3
                    or tuple(offsets.shape[:2]) != (B, W) or offsets.shape[2] < 1):
                raise RuntimeError('input word occurrences require their byte starts')
            starts = torch.where(object_rows >= 0, offsets[:, :, 0], -1)
            isp._ar_word_symbol_where = registry.encode('input', starts)
            from Occurrence import relative_positions
            positions = relative_positions(self, isp._packed_sentence_ids.to(rows.device))
            isp._ar_word_symbol_when = self.when_encoding.encode(positions)
            isp._ar_word_symbol_when = torch.where((rows >= 0)[..., None],
                                                    isp._ar_word_symbol_when, 0.)
        codes = torch.tensor(reference_codes, dtype=torch.long, device=part_ids.device)
        roles = torch.tensor(reference_roles, dtype=torch.long, device=part_ids.device)
        isp._ar_percept_reference_codes = codes
        isp._ar_percept_reference_roles = roles
        part_codes = torch.where(roles == 0, codes, torch.zeros_like(codes))
        whole_codes = torch.where(roles == 1, codes, torch.zeros_like(codes))
        ps = self.perceptualSpace
        part_vectors = ps.subspace.what.lookup_rows(part_codes)
        whole_vectors = ws.subspace.what.lookup_rows(whole_codes)
        # These are exact selected prototype reads, never a vocabulary scan.
        # The compiler sees the small sentence bank; sparse encoder gradients
        # and indexed Sigma gradients are formed outside the while-loop HOP.
        isp._ar_part_reference_vectors = F.pad(
            part_vectors[..., :int(ps.nWhat)],
            (0, max(0, int(ps.nWhat) - int(part_vectors.shape[-1]))))
        isp._ar_whole_reference_vectors = F.pad(
            whole_vectors[..., :int(ws.nWhat)],
            (0, max(0, int(ws.nWhat) - int(whole_vectors.shape[-1]))))
        isp._ar_readout_coefficients = owner.concepts_from_percepts.lookup_coefficients(rows)
        primitive_counts = ws._staged_word_primitive_counts
        if torch.is_tensor(primitive_counts):
            # Reference ids name properties, while the staged witness names
            # bytes. Evaluate the live definitions before gathering by id.
            properties = ws.subspace.what.primitive_properties.on_counts(primitive_counts)
            indices = whole_codes.unsqueeze(2).expand(B, W, int(properties.shape[2]), 8)
            gathered = properties.gather(-1, indices)
            isp._ar_whole_reference_presence = torch.where(
                primitive_counts.any(dim=-1, keepdim=True), gathered,
                torch.full_like(gathered, -1))
        else:
            isp._ar_whole_reference_presence = None
        # Perform the only contextual dictionary read once at this eager
        # boundary. The compiled word loop resolves all current/prior lexical
        # references against this small sentence bank. The read-only boundary
        # keeps W outside autograd while avoiding W graph breaks and repeated
        # B*N gathers per iteration.
        cb = getattr(owner, "similarity_codebook", None)
        lookup = getattr(cb, "lookup_rows", None)
        if callable(lookup):
            # Keep this bank width invariant across the configured W buckets
            # so the same K=2 graph serves 16/32/64/128-word slabs.  Padding
            # rows gather row zero and are explicitly zero-masked. Contextual
            # dictionary rows remain read-only; their one owner updates them
            # only through the post-sentence reduction below.
            bank_width = max(
                int(rows.shape[1]),
                int(getattr(self, "serial_word_capacity", 0) or 0),
                max(tuple(int(v) for v in
                          (getattr(self, "serial_word_buckets", ()) or (0,)))))
            bank_rows = torch.full(
                (int(rows.shape[0]), 2 * bank_width), -1,
                dtype=torch.long, device=rows.device)
            bank_rows[:, :int(rows.shape[1])] = rows
            object_start = bank_width
            bank_rows[
                :, object_start:object_start + int(object_rows.shape[1])
            ] = object_rows
            lookup_rows = bank_rows.clamp_min(0).long()
            lookup_atoms = lookup(lookup_rows)
            if torch.is_tensor(lookup_atoms) and lookup_atoms.dim() == 3:
                lookup_atoms = lookup_atoms * bank_rows.ge(0).unsqueeze(-1).to(
                    dtype=lookup_atoms.dtype)
                isp._ar_concept_lookup_rows = bank_rows
                isp._ar_concept_lookup_atoms = lookup_atoms
                # Every candidate retains its source occurrence's sentence.
                # Repeated rows in another sentence are separate bank entries;
                # admitting them to an inverse or byte softmax changes its prior.
                sentence_ids = isp._packed_sentence_ids.to(device=rows.device)
                bank_sentence_ids = torch.full_like(bank_rows, -1)
                bank_sentence_ids[:, :int(rows.shape[1])] = sentence_ids
                bank_sentence_ids[:, object_start:object_start + int(rows.shape[1])] = sentence_ids
                isp._ar_concept_lookup_sentence_ids = torch.where(
                    bank_rows >= 0, bank_sentence_ids, torch.full_like(bank_rows, -1))
                # These are carried into the ``while_loop`` beside the full
                # sentence lookup bank.  HOP inputs may not alias one another,
                # even when both are read-only, so give the two lexical
                # convenience slabs independent storage at this eager
                # boundary.  This is not a per-word copy and the contextual
                # codebook remains a single owner/read.
                isp._ar_word_concept_atoms = lookup_atoms[
                    :, :int(rows.shape[1])].clone()
                isp._ar_word_object_atoms = lookup_atoms[
                    :, object_start:object_start + int(object_rows.shape[1])
                ].clone()
        object.__setattr__(self, "_pending_sparse_concept_support", pending)
        return rows

    # -- per-step lifecycle (model-level) ------------------------------
    #
    # ``runBatch`` orchestrates a step but reaches only through the model,
    # never into model *contents* (``self.symbolSpace.expectation``,
    # ``self.inputSpace`` ...). The model owns the reusable helpers for its
    # lex+embed stem, discourse loss, and post-forward teardown. Per-batch
    # timing is NOT the grammar ``soft_reset`` (that fires only on chart
    # sentence-completion and never per-batch on the IR/MM_20M path, so
    # relocating discourse there would silently stop ARMA).

    def _pad_staged_unit_maps(self, ws):
        """Pad the staged unit parent/clause maps ``[B, K]`` to the staged
        word width ``[B, W]`` (``-1`` beyond the units).  The compiled word
        loop reads them as constants; a width that varied with the batch's
        unit count made dynamo recompile the loop for every new count."""
        isp = getattr(self, "inputSpace", None)
        slab = getattr(isp, "_ar_embedded_N", None) if isp is not None else None
        if ws is None or not torch.is_tensor(slab):
            return
        width = int(slab.shape[1])
        for name in ("_staged_unit_parent", "_staged_unit_clause"):
            value = getattr(ws, name, None)
            if not torch.is_tensor(value) or value.dim() != 2:
                continue
            B, K = int(value.shape[0]), int(value.shape[1])
            if K == width:
                continue
            out = torch.full((B, width), -1, dtype=torch.long, device=value.device)
            k = min(K, width)
            out[:, :k] = value[:, :k].to(dtype=torch.long)
            object.__setattr__(ws, name, out)

    # -- compiled reverse-loops plan, slices 1-2: the bounded traversal -----

    def _ensure_pid_byte_table(self):
        """``[n_ids]`` long on the PS: percept id -> byte value for the 256
        one-byte atoms (``-1`` otherwise), rebuilt eagerly when the store
        grows; the byte-level fidelity reads word bytes through it."""
        ps = getattr(self, "perceptualSpace", None)
        store = getattr(ps, "percept_store", None) if ps is not None else None
        if store is None or not hasattr(store, "get_id"):
            return
        size = int(getattr(store, "_size", 0) or 0)
        cached = getattr(ps, "_pid_byte_table", None)
        if torch.is_tensor(cached) and int(cached.numel()) == size:
            return
        table = torch.full((max(size, 1),), -1, dtype=torch.long, device="cpu")
        for value in range(256):
            pid = store.get_id(bytes([value]))
            if pid is not None and 0 <= int(pid) < size:
                table[int(pid)] = value
        object.__setattr__(ps, "_pid_byte_table", table)

    def _stage_snapshot_bytes(self):
        """Stage full byte targets and the separate WORD-owned row snapshot.

        Input percept IDs expand to their complete spellings for scoring only;
        promotion must not remove target bytes. OBJECT candidates translate
        through their current WORD association. Retain one extra candidate
        byte so a longer spelling cannot acquire a fabricated word end at the
        target window. Missing WORD surfaces produce invalid candidates.
        """
        isp = self.inputSpace
        part_ids = getattr(isp, "_ar_word_part_ids", None)
        part_mask = getattr(isp, "_ar_word_part_mask", None)
        active = getattr(isp, "_word_active_mask", None)
        store = getattr(getattr(self, "perceptualSpace", None), "percept_store", None)
        isp._ar_target_word_bytes = None
        isp._ar_target_word_mask = None
        if (torch.is_tensor(part_ids) and part_ids.dim() == 3
                and torch.is_tensor(part_mask) and part_mask.shape == part_ids.shape
                and torch.is_tensor(active) and active.shape == part_ids.shape[:2]
                and callable(getattr(store, "bytes_for", None))):
            B, W = (int(v) for v in active.shape)
            ids = part_ids.detach().to("cpu").tolist()
            masks = part_mask.detach().to("cpu").tolist()
            live = active.detach().to("cpu").tolist()
            spellings = [[b""] * W for _ in range(B)]
            pieces = {}
            # Match the dynamic target-axis lower bound; the padding is masked.
            width = 3
            identity = getattr(store, 'identity', None)
            texts = (getattr(self.perceptualSpace, '_forward_input', None) or {}).get('word_texts', ())
            for b in range(B):
                for w in range(W):
                    if not live[b][w]:
                        continue
                    chunks = []
                    for pid, valid in zip(ids[b][w], masks[b][w]):
                        if valid:
                            if pid not in pieces:
                                pieces[pid] = store.bytes_for(pid)
                            chunks.append(pieces[pid])
                    raw = b"".join(chunks)
                    if identity is not None:
                        # Identity atoms are parts, not substrings. Targets
                        # retain the separately staged input byte witness.
                        raw = (str(texts[b][w]).encode('latin1')
                               if b < len(texts) and w < len(texts[b]) else b'')
                    spellings[b][w] = raw
                    width = max(width, len(raw))
            targets = torch.zeros(B, W, width, dtype=torch.long, device="cpu")
            valid = torch.zeros(B, W, width, dtype=torch.bool, device="cpu")
            for b, row in enumerate(spellings):
                for w, raw in enumerate(row):
                    if raw:
                        targets[b, w, :len(raw)] = torch.tensor(list(raw), device="cpu")
                        valid[b, w, :len(raw)] = True
            isp._ar_target_word_bytes = targets.to(part_ids.device)
            isp._ar_target_word_mask = valid.to(part_ids.device)
        bank = getattr(isp, "_ar_concept_lookup_rows", None)
        if not torch.is_tensor(bank) or bank.dim() != 2:
            isp._ar_bank_bytes = None
            isp._ar_bank_valid = None
            return
        targets = isp._ar_target_word_bytes
        P = (int(part_ids.shape[-1]) if torch.is_tensor(part_ids) and part_ids.dim() == 3
             else int(getattr(self, "serial_residual_part_capacity", 1)))
        if torch.is_tensor(targets):
            P = max(P, int(targets.shape[-1]))
        B, L = (int(v) for v in bank.shape)
        P = max(1, P) + 1
        bank_bytes = torch.zeros(B, L, P, dtype=torch.long)
        bank_valid = torch.zeros(B, L, P, dtype=torch.bool)
        owner = self._concept_owner()
        # Only the brick's row IDs cross to the host. No vocabulary scan and
        # no OBJECT-owned copy of a word's surface is needed.
        for b, rows in enumerate(bank.detach().to('cpu').tolist()):
            for col, row in enumerate(rows):
                raw = owner.word_surface_for_row(row) if row >= 0 else None
                if raw:
                    n = min(P, len(raw))
                    bank_bytes[b, col, :n] = torch.tensor(list(raw[:n]), dtype=torch.long)
                    bank_valid[b, col, :n] = True
        isp._ar_bank_bytes = bank_bytes.to(device=bank.device)
        isp._ar_bank_valid = bank_valid.to(device=bank.device)

    def _stage_mixing_reconstruction_bank(self):
        """Snapshot the mixing reading's object candidates and observed bytes.

        This is the eager reading boundary. Object references remain grammar
        references; none of the native WORD identity fields are published.
        Candidate surfaces belong to admitted objects, while scoring targets
        come from the observed units, including words not yet admitted.
        """
        if (not self.word_brackets or self._aligned_serial_word_mode()
                or not (getattr(self, 'reconstruct_in_loop', False)
                        or getattr(self, '_sentence_reconstruction', False)
                        or getattr(self, 'answer_synthesis', False))):
            return
        isp = self.inputSpace
        active = getattr(isp, '_word_active_mask', None)
        rows = getattr(isp, '_ar_grammar_object_rows', None)
        atoms = getattr(isp, '_ar_grammar_object_atoms', None)
        if not (torch.is_tensor(active) and torch.is_tensor(rows)
                and torch.is_tensor(atoms)):
            return
        isp._finalize_sentence_word_layout(active)
        B, W = active.shape
        owner = self._concept_owner()
        # Physical grammar rows may be unavailable while a staged native
        # object identity still names an existing symbol. Resolve that saved
        # identity read-only; never reconstruct a candidate from target bytes.
        ids = getattr(isp, '_ar_grammar_object_ids', None)
        if torch.is_tensor(ids) and ids.shape == rows.shape:
            from Queries import _existing_row
            rows = rows.clone()
            for b, w in ((rows < 0) & (ids > 0)).nonzero().tolist():
                try:
                    rows[b, w] = _existing_row(owner, ('sym', int(ids[b, w])))
                except ValueError:
                    pass
            # The forward resolver and the reconstruction bank must use
            # the same existing identity's physical row.
            isp._ar_grammar_object_rows = rows
        percepts = getattr(self.perceptualSpace, '_forward_input', None) or {}
        texts = percepts.get('word_texts')
        tokens = percepts.get('tokens', ())
        spans = percepts.get('part_spans')
        raw = getattr(self, '_staged_concepts_in', None)
        if torch.is_tensor(spans) and torch.is_tensor(raw):
            spans = spans.detach().cpu().tolist()
            raw = raw.detach().cpu().reshape(B, -1).long().tolist()
        else:
            spans = raw = None
        surfaces = [[b''] * W for _ in range(B)]
        targets = [[b''] * W for _ in range(B)]
        width = 3
        live = active.detach().cpu().tolist()
        for b, row in enumerate(rows.detach().cpu().tolist()):
            for w, concept_row in enumerate(row):
                if not live[b][w]:
                    continue
                spelling = owner.word_surface_for_row(concept_row) if concept_row >= 0 else None
                if spelling:
                    surfaces[b][w] = spelling
                surface = None
                if (texts is not None and b < len(texts) and texts[b] is not None
                        and w < len(texts[b])):
                    # Word-major stems preserve each input byte as one
                    # Latin-1 character. This is a byte carrier, not Unicode.
                    surface = texts[b][w].encode('latin1')
                elif spans is not None and b < len(spans) and w < len(spans[b]):
                    lo, hi = spans[b][w]
                    if 0 <= lo < hi <= len(raw[b]):
                        surface = bytes(raw[b][lo:hi])
                elif b < len(tokens) and w < len(tokens[b]):
                    surface = tokens[b][w]
                if isinstance(surface, str):
                    surface = surface.encode('utf-8')
                if isinstance(surface, bytes):
                    targets[b][w] = surface
                width = max(width, len(surfaces[b][w]), len(targets[b][w]))
        def tensor_bytes(values, lookahead=0):
            data = torch.zeros(B, W, width + lookahead, dtype=torch.long, device='cpu')
            valid = torch.zeros_like(data, dtype=torch.bool)
            for b, row in enumerate(values):
                for w, value in enumerate(row):
                    if value:
                        data[b, w, :len(value)] = torch.tensor(list(value), device='cpu')
                        valid[b, w, :len(value)] = True
            return data.to(rows.device), valid.to(rows.device)
        isp._ar_concept_lookup_rows = rows.clone()
        isp._ar_concept_lookup_atoms = atoms
        isp._ar_concept_lookup_sentence_ids = torch.where(
            rows >= 0, isp._packed_sentence_ids, torch.full_like(rows, -1))
        isp._ar_bank_bytes, isp._ar_bank_valid = tensor_bytes(surfaces, lookahead=1)
        isp._ar_target_word_bytes, isp._ar_target_word_mask = tensor_bytes(targets)

    def _understanding_reconstruction_scope(self):
        """The retained reading paths always reconstruct their understanding.

        A grammar-free path has no concluded grammar field to invert.
        """
        language = getattr(getattr(self, 'symbolSpace', None), 'languageLayer', None)
        if not self.word_brackets or getattr(language, 'operation_layer', None) is None:
            return 'perception: no grammar'
        return 'understanding'

    def _validate_reconstruction_bank(self):
        """Check sentence coverage at the eager boundary, after admission.

        The bank is a snapshot of admitted WORD/OBJECT concepts, not an
        independently growing vocabulary. A missing snapshot is an error;
        a sentence with no admitted surfaces contributes no reconstruction.
        Tensor invariants stay on device; only structural metadata is read
        by Python. Accelerator assertion failures surface asynchronously.
        """
        isp = self.inputSpace
        active = getattr(isp, "_word_active_mask", None)
        ids = getattr(isp, "_packed_sentence_ids", None)
        rows = getattr(isp, "_ar_concept_lookup_rows", None)
        atoms = getattr(isp, "_ar_concept_lookup_atoms", None)
        owners = getattr(isp, "_ar_concept_lookup_sentence_ids", None)
        surfaces = getattr(isp, "_ar_bank_bytes", None)
        valid = getattr(isp, "_ar_bank_valid", None)
        if not (torch.is_tensor(active) and active.ndim == 2
                and torch.is_tensor(ids) and ids.shape == active.shape):
            raise RuntimeError("tied reconstruction bank requires staged word and sentence masks")
        B, W = active.shape
        if not (torch.is_tensor(rows) and rows.ndim == 2 and rows.shape[0] == B
                and rows.shape[1] > 0 and torch.is_tensor(atoms) and atoms.ndim == 3
                and atoms.shape[:2] == rows.shape):
            raise RuntimeError("tied reconstruction bank was not staged after concept admission")
        if not (torch.is_tensor(owners) and owners.shape == rows.shape
                and owners.dtype == torch.long):
            raise RuntimeError("tied reconstruction bank lost its sentence ownership")
        if not (torch.is_tensor(surfaces) and surfaces.ndim == 3
                and surfaces.shape[:2] == rows.shape and torch.is_tensor(valid)
                and valid.shape == surfaces.shape and valid.dtype == torch.bool):
            raise RuntimeError("tied reconstruction bank requires staged WORD surfaces and validity")
        torch._assert_async(
            ~((rows >= 0) & ((owners < 0) | (owners >= W))).any(),
            "tied reconstruction bank has invalid sentence ownership")
        torch._assert_async(
            ~(active & ((ids < 0) | (ids >= W))).any(),
            "tied reconstruction bank has invalid input sentence ownership")
        if W == 0:
            return
        # O(B*(W+L)): a populated first sentence must not conceal an empty
        # later sentence. Padding and absent rows require no candidates.
        usable = (rows >= 0) & valid.any(-1)
        counts = torch.zeros_like(active, dtype=torch.long).scatter_add(
            1, owners.clamp(0, W - 1), usable.long())
        present = torch.zeros_like(counts).scatter_add(
            1, ids.clamp(0, W - 1), active.long()) > 0
        isp._reconstruction_sentence_available = present & (counts > 0)
        isp._reconstruction_missing_sentence_count = (present & (counts == 0)).sum()

    def _word_symbol_rows(self):
        """``[B, W]`` the symbol row of each staged word: its object
        concept's row where the word has one, else its word concept's row
        (the row the forward pushed and SymbolSpace references: the symbol
        and concept tables share indices); ``-1`` where a word has no
        durable identity; ``None`` before staging."""
        isp = getattr(self, "inputSpace", None)
        concept = getattr(isp, "_ar_word_concept_rows", None)
        obj = getattr(isp, "_ar_word_object_rows", None)
        if not torch.is_tensor(concept) or concept.dim() != 2:
            return None
        concept = concept.to(torch.long)
        if torch.is_tensor(obj) and tuple(obj.shape) == tuple(concept.shape):
            obj = obj.to(device=concept.device, dtype=torch.long)
            return torch.where(obj >= 0, obj, concept)
        return concept

    def _word_symbol_concept_ids(self):
        """Native concept handles aligned to the actually selected symbol rows.

        Missing OBJECT identity stays unknown even when its WORD identity is
        known: the WORD would denote a different referent. A row is never
        interpreted as an allocator ID. Reads allocate no concepts or rows.
        """
        isp = getattr(self, "inputSpace", None)
        rows = getattr(isp, "_ar_word_concept_rows", None)
        if not torch.is_tensor(rows) or rows.ndim != 2:
            return None
        objects = getattr(isp, "_ar_word_object_rows", None)
        has_objects = torch.is_tensor(objects) and objects.shape == rows.shape
        # The fixed pipeline metadata also covers unaligned numerical input.
        # Its all-unknown row slab is not a native identity carrier.
        if not bool((rows >= 0).any()) and not (
                has_objects and bool((objects >= 0).any())):
            return None
        unknown = torch.full_like(rows, -1, dtype=torch.long)
        def addresses(name):
            values = getattr(isp, name, None)
            if not torch.is_tensor(values) or values.shape != rows.shape:
                return unknown
            if values.dtype != torch.long:
                raise TypeError("native concept IDs must use integer address tensors")
            values = values.to(device=rows.device)
            return torch.where(values > 0, values, unknown)
        ids = torch.where(rows >= 0, addresses("_ar_word_concept_ids"), unknown)
        if has_objects:
            ids = torch.where(objects.to(rows.device) >= 0,
                              addresses("_ar_word_object_ids"), ids)
        return ids

    def _word_lexical_forms(self, batch, width):
        """Gather forward-resolved grammar forms by retained WORD row.

        Rows are dispatch keys, never semantic values or policy features.
        Unknown words and older staging without provenance stay unclassified;
        capture never consults input text or the current anchor table.
        """
        batch, width = int(batch), int(width)
        empty = tuple(tuple(None for _ in range(width)) for _ in range(batch))
        isp = getattr(self, "inputSpace", None)
        rows = getattr(isp, "_ar_word_concept_rows", None)
        resolved = getattr(isp, "_ar_word_lexical_forms", None)
        if (not torch.is_tensor(rows) or rows.ndim != 2
                or not hasattr(resolved, "get")):
            return empty
        retained = rows[:batch, :width].detach().to("cpu").tolist()
        forms = []
        for b in range(batch):
            word_rows = retained[b] if b < len(retained) else ()
            row_forms = []
            for word in range(width):
                row = word_rows[word] if word < len(word_rows) else -1
                form = resolved.get(row) if row >= 0 else None
                row_forms.append(form if isinstance(form, str) else None)
            forms.append(tuple(row_forms))
        return tuple(forms)

    def _pushed_word_slab(self, B, W, D, like, activations):
        """``[B, W, D]`` retained constituent references: the leaves the
        forward pushed, each word's symbol row's dictionary atom (its
        object concept's where it has one, else its word concept's) scaled
        by activation magnitude on form and signed activation on meaning,
        channels (zeros elsewhere and where a word has no row)."""
        if getattr(self, '_attention_pole_representation', False):
            from ModelAttention import read_poles
            pair = read_poles(self, '_pushed_word_slab:poles').to(like)
            valid = self._attention_words.accepted
            return F.pad(torch.where(valid[...,None],pair,0.),(0,D-2,0,W-pair.shape[1]))
        isp = self.inputSpace
        concept_atoms = getattr(isp, "_ar_word_concept_atoms", None)
        object_atoms = getattr(isp, "_ar_word_object_atoms", None)
        object_rows = getattr(isp, "_ar_word_object_rows", None)
        rows = self._word_symbol_rows()
        grammar_rows = getattr(isp, '_ar_grammar_object_rows', None)
        grammar_atoms = getattr(isp, '_ar_grammar_object_atoms', None)
        if torch.is_tensor(grammar_rows) and torch.is_tensor(grammar_atoms):
            concept_atoms, rows = grammar_atoms, grammar_rows
            object_atoms = object_rows = None
        reference = like.new_zeros(B, W, D)
        if not (torch.is_tensor(concept_atoms) and concept_atoms.dim() == 3
                and torch.is_tensor(rows)):
            return reference
        atoms = concept_atoms
        if (torch.is_tensor(object_atoms) and tuple(object_atoms.shape) == tuple(concept_atoms.shape)
                and torch.is_tensor(object_rows)
                and tuple(object_rows.shape) == tuple(concept_atoms.shape[:2])):
            atoms = torch.where(
                (object_rows >= 0).unsqueeze(-1).to(device=concept_atoms.device),
                object_atoms, concept_atoms)
        k = min(int(atoms.shape[1]), W, int(rows.shape[1]))
        da = min(int(atoms.shape[-1]), D)
        content = atoms[:, :k, :da].to(device=like.device, dtype=like.dtype)
        content = self._concept_owner().interpret.binding_atoms(content)
        if torch.is_tensor(activations) and int(activations.numel()) >= B * k:
            act = activations.reshape(B, -1)[:, :k].to(
                device=like.device, dtype=like.dtype).unsqueeze(-1)
            content = self._concept_owner().interpret.activate(content, act.squeeze(-1))
        present = (rows[:, :k] >= 0).to(device=like.device, dtype=like.dtype).unsqueeze(-1)
        content = content * present
        return torch.cat(
            (torch.cat((content, like.new_zeros(B, k, D - da)), dim=-1),
             like.new_zeros(B, W - k, D)), dim=1)

    def _recovered_word_ideas(self, S):
        """``[B, W, D]`` per-word ideas of the last forward's sentences,
        unwound from their end states through the recorded derivation
        (the traversal with the recovered-idea slab kept); ``None`` when
        no staged sentence state exists."""
        reference = getattr(self, "_tensor_pushed_ideas", None)
        roots = getattr(self, "_tensor_sentence_roots_live", None)
        if not (torch.is_tensor(reference) and torch.is_tensor(roots)):
            return None
        recon = getattr(self, "_recon_ideas", None)
        if getattr(self, "_recon_completed", False) and torch.is_tensor(recon):
            return recon
        depth = getattr(self, "_tensor_sentence_roots_depth", None)
        end = getattr(self, "_tensor_final_end_slots", None)
        end_d = getattr(self, "_tensor_final_end_depth", None)
        if not (torch.is_tensor(end) and torch.is_tensor(end_d)):
            end, end_d = self._final_end_state(S, getattr(self, "_stm_post_depth", None))
        keep = bool(getattr(self, "_recon_keep_ideas", False))
        object.__setattr__(self, "_recon_keep_ideas", True)
        try:
            values = self._reconstruct_sentences(
                S, reference, roots, depth, end, end_d)
            for name, value in zip(("_recon_ideas", "_recon_idea_cost", "_recon_cost",
                                    "_recon_truncated", "_recon_sentence_costs"), values):
                object.__setattr__(self, name, value)
            object.__setattr__(self, "_recon_completed", True)
        finally:
            object.__setattr__(self, "_recon_keep_ideas", keep)
        return values[0]

    def _final_end_state(self, S, post_depth):
        """``(end_slots [B, 3, D], end_depth [B])`` of the row's last
        sentence after the final closing: the top three STM slots (newest at
        0; a relative sentence keeps its depth-3 end state, an absolute
        one its single root) and the depth."""
        B, D = int(S.shape[0]), int(S.shape[-1])
        stm = getattr(getattr(self, "conceptualSpace", None), "stm", None)
        buf = getattr(stm, "_buffer", None) if stm is not None else None
        if (torch.is_tensor(buf) and buf.dim() == 3 and int(buf.shape[0]) == B
                and int(buf.shape[-1]) == D and torch.is_tensor(post_depth)):
            k = min(3, int(buf.shape[1]))
            slots = buf[:, :k, :]
            if k < 3:
                slots = torch.cat((slots, S.new_zeros(B, 3 - k, D)), dim=1)
            depth = post_depth.reshape(B).to(torch.long).clamp(-1, 3)
            # the single-root case reads S itself (the buffer's root slot)
            # Negative depth marks an incomplete forest; preserve its slots
            # for reconstruction rather than treating it as a single root.
            single = post_depth.reshape(B).abs() == 1
            slots = torch.where(
                single.reshape(B, 1, 1),
                torch.cat((S.reshape(B, 1, D), S.new_zeros(B, 2, D)), dim=1), slots)
            return slots, depth
        return (torch.cat((S.reshape(B, 1, D), S.new_zeros(B, 2, D)), dim=1),
                torch.ones(B, dtype=torch.long, device=S.device))

    def _reconstruct_sentence_if_enabled(self, S, pushed_ideas, roots_live,
                                         roots_depth, end_slots, end_depth):
        """Run the tied traversals when ``<reconstructInLoop>`` is on; else
        zero-shaped placeholders (explicit outputs keep a fixed arity)."""
        B = int(S.shape[0])
        W = int(pushed_ideas.shape[1])
        D = int(pushed_ideas.shape[-1])
        slots = int(roots_live.shape[1]) if torch.is_tensor(roots_live) else 1
        placeholders = (S.new_zeros(B, W, D), S.new_zeros(B), S.new_zeros(B),
                        torch.zeros(B, dtype=torch.bool, device=S.device),
                        S.new_zeros(B, slots))
        state = (pushed_ideas, roots_live, roots_depth, end_slots, end_depth)
        if (getattr(self, '_sentence_ends', False)
                and getattr(self, '_recon_completed', False)):
            # Sentence transactions already scored their immutable records.
            # Their open journals have been discarded; replaying those here
            # would overwrite the explicit result with a different inverse.
            return (self._recon_ideas, self._recon_idea_cost, self._recon_cost,
                    self._recon_truncated, self._recon_sentence_costs) + state
        if not getattr(self, "reconstruct_in_loop", False):
            return placeholders + state
        if self._recon_placement() != "graph":
            # The traversal runs after the forward (eager, or as its own
            # compiled call) from the published references and end states.
            return placeholders + state
        return self._reconstruct_sentences(
            S, pushed_ideas, roots_live, roots_depth, end_slots, end_depth) + state

    def _recon_placement(self):
        """Configured graph/separate/eager placement, with a diagnostic override.

        BasicModel selects a separate compiled reconstruction so its backward
        can be captured independently. Legacy configurations default to graph.
        """
        configured = getattr(self, "reconstruction_placement", "graph")
        value = str(os.environ.get("BASICMODEL_RECON_PLACEMENT", configured) or configured).strip().lower()
        return value if value in ("graph", "compiled", "eager") else "graph"

    def _compiled_reconstruct(self):
        """``_reconstruct_sentences`` as its own compiled call (cached)."""
        cached = self.__dict__.get("_reconstruct_compiled")
        if cached is not None:
            return cached
        import util as _util
        backend = getattr(_util, "TheCompileBackend", "none")
        fn = self._reconstruct_sentences
        placement = self._recon_placement()
        # Sentence endings are eager optimizer boundaries. A reconstruction
        # formerly inside the batch graph is now its own numerical brick.
        separate = placement == "compiled" or (
            placement == "graph" and getattr(self, '_sentence_ends', False))
        if backend and backend != "none" and separate:
            # "auto" is our backend policy, not a torch backend name. Match
            # util.compile's first choice before resolving the torch compiler.
            backend = _util._COMPILE_BACKENDS[0] if backend == "auto" else backend
            # Eager forward capture alone rebuilds the nested loop/conditional
            # backward programs on every differentiation. AOT eager captures
            # that backward once while retaining ordinary ATen execution.
            backend = "aot_eager" if backend == "eager" else backend
            from torch._dynamo.backends.registry import lookup_backend
            from torch._functorch import config as aot_config
            compiler = lookup_backend(backend)

            def compile_reconstruction(graph, inputs):
                # Read-only operator diagnostics read this graph more than once.
                # A cached single-use backward must never donate its saved
                # buffers, even if the first call did not retain the graph.
                # Scope the setting to this compiler; other models keep theirs.
                with aot_config.patch(donated_buffer=False):
                    compiled = compiler(graph, inputs)
                    # This torch build leaves disabled donation as None, but
                    # its retained-backward check requires the explicit empty
                    # list once the caller's global setting is restored.
                    # Normalize only the disabled sentinel: no compiled buffer
                    # donation is being hidden or retroactively disabled here.
                    from torch._guards import TracingContext
                    context = TracingContext.try_get()
                    metadata = getattr(context, "fw_metadata", None)
                    if metadata is not None and metadata.bw_donated_idxs is None:
                        metadata.bw_donated_idxs = []
                    return compiled

            # These are bounded traversals of this model's fixed word/stack
            # geometry. Specialize the shapes: automatic shape generalization
            # across models otherwise lifts integer extents into while_loop's
            # operands, where Inductor requires tensor operands.
            fn = torch.compile(fn, backend=compile_reconstruction, fullgraph=True,
                               dynamic=False)
        self.__dict__["_reconstruct_compiled"] = fn
        return fn

    def _decode_conceptual_sentence(self, root, end_slots, end_depth, codes, valid, weights,
                                    *, exploit_actions=None, departure=None,
                                    return_candidates=False, case_bank=None):
        """Root/end slots and echoic symbols are the decoder's entire input."""
        B, K, D = end_slots.shape
        positions = torch.arange(K, device=root.device)[None]
        slots = torch.where((positions < end_depth[:, None])[..., None], end_slots, 0.)
        slots = torch.where(((end_depth == 1)[:, None] & (positions == 0))[..., None],
                            root[:, None], slots)
        return self._output_generate_walk(self._walk_operand(slots), self._walk_budget(),
            basis=codes, basis_valid=valid, basis_priming=weights,
            candidate_limit=self.reconstruction_basis_limit, return_trace=True,
            exploit_actions=exploit_actions, departure=departure,
            return_candidates=return_candidates, case_bank=case_bank)

    def _reconstruct_sentences(self, S, reference, roots_live, roots_depth=None,
                               end_slots=None, end_depth=None, sentence_slot=None,
                               *, candidate_basis=None, keep_ideas=None, understanding=None,
                               return_decoded=False, decoder_exploit=None,
                               decoder_departure=None, decoder_candidates=False):
        """Score the generate decoder against bytes; no journal is consulted.

        Target positions only align the already decoded leaves for scoring.
        Missing words and excess leaves are scored too; target length never
        determines the walk's actions or stopping decision.
        """
        isp = self.inputSpace
        B, W, D = reference.shape
        slots = roots_live.shape[1]
        active = isp._word_active_mask.bool()
        leaf_mask = getattr(isp, '_ar_grammar_leaf_mask', None)
        if torch.is_tensor(leaf_mask):
            active = active & leaf_mask
        ids = getattr(isp, '_packed_sentence_ids', torch.zeros_like(active, dtype=torch.long))
        ready, targets, target_valid = self._byte_tables(B, W)
        if understanding is not None:
            bank = understanding.primed
            codes, valid, weights, surfaces, surface_valid = (
                bank.codes, bank.valid, bank.weights, bank.bytes, bank.byte_valid)
        elif candidate_basis is not None:
            codes, valid = candidate_basis
            weights = torch.ones_like(valid, dtype=S.dtype)
            surfaces = torch.zeros(*valid.shape, 1, dtype=torch.long, device=S.device)
            surface_valid = torch.zeros_like(surfaces, dtype=torch.bool)
            ready = False
        else:
            _, codes, surfaces, surface_valid = self._snapshot_tables(reference)
            _, valid = self._reconstruction_basis_snapshot(reference)
            weights = torch.ones_like(valid, dtype=S.dtype)
        recovered = reference.new_zeros(B, W, D)
        byte_all = S.new_zeros(B, slots)
        bad = torch.zeros(B, device=S.device, dtype=torch.bool)
        visits = (sentence_slot,) if sentence_slot is not None else range(slots)
        decoded = None
        for sid in visits:
            scope = active & (ids == sid)
            if understanding is not None:
                root, end, depth = understanding.root, understanding.end_slots, understanding.end_depth
                candidates = valid
            else:
                field = roots_live[:, sid]
                if field.shape[-1] == D:
                    root = field
                    end = torch.cat((root[:, None], root.new_zeros(B, 2, D)), 1)
                else:
                    end = field.reshape(B, 3, D)
                    root = end[:, 0]
                depth = (roots_depth[:, sid] if roots_depth is not None
                         else torch.ones(B, device=S.device, dtype=torch.long))
                # A direct one-sentence reconstruction owns its explicit end.
                if slots == 1 and end_slots is not None:
                    end, depth = end_slots, end_depth
                    root = S
                candidates = valid
                ownership = getattr(isp, '_ar_concept_lookup_sentence_ids', None)
                if candidate_basis is None and torch.is_tensor(ownership):
                    candidates = valid & (ownership == sid)
            decoder_options = {}
            if understanding is not None and bank.case_bank is not None:
                decoder_options['case_bank'] = bank.case_bank
            if decoder_candidates or decoder_exploit is not None:
                decoder_options.update(exploit_actions=decoder_exploit,
                    departure=decoder_departure, return_candidates=decoder_candidates)
            decoded = self._decode_conceptual_sentence(root, end, depth, codes, candidates, weights,
                                                        **decoder_options)
            leaves, count, truncated, _, actions = decoded[:5]
            T = leaves.shape[1]
            rank = scope.long().cumsum(-1) - 1
            recovered = recovered + torch.where(scope[..., None],
                leaves.gather(1, rank.clamp(0, T-1)[..., None].expand(B, W, D)), 0.)
            # Compact target words after decoding. Beyond their last word,
            # emitted leaves are scored against an empty (NUL) surface.
            positions = torch.arange(W, device=S.device)[None].expand(B, W)
            order = torch.argsort(positions + (~scope).long()*W, dim=1)
            compact = targets.gather(1, order[..., None].expand_as(targets))
            compact_valid = target_valid.gather(1, order[..., None].expand_as(target_valid))
            n_target = scope.sum(-1)
            P = targets.shape[-1]
            indices = torch.arange(T, device=S.device).clamp_max(W-1)
            scored_targets = compact.index_select(1, indices)
            scored_valid = compact_valid.index_select(1, indices)
            is_target = torch.arange(T, device=S.device)[None] < n_target[:, None]
            scored_targets = torch.where(is_target[..., None], scored_targets, 0)
            empty = torch.arange(P, device=S.device) == 0
            scored_valid = torch.where(is_target[..., None], scored_valid, empty[None, None])
            n_score = torch.maximum(n_target, count).clamp_max(T)
            def cond(w, total):
                return w < n_score.amax()
            def body(w, total):
                value = leaves.gather(1, w.reshape(1,1,1).expand(B,1,D)).squeeze(1)
                cost = self._byte_word_cost(value, w, codes, surfaces,
                    surface_valid & candidates[..., None], scored_targets, scored_valid, ready,
                    priming=weights)
                return w+1, total + torch.where(w < n_score, cost, 0.)
            _, total = _reconstruction_while_loop(cond, body, _carries_with_grad((
                torch.zeros((), device=S.device, dtype=torch.long), S.new_zeros(B))))
            eligible = scope.any(-1) & candidates.any(-1)
            cost = torch.where(eligible, total / n_score.clamp_min(1), 0.)
            column = torch.as_tensor(sid, device=S.device).reshape(1,1).expand(B,1)
            byte_all = byte_all.scatter(1, column, cost[:, None])
            bad = bad | (scope.any(-1) & (truncated | ~candidates.any(-1)))
        present = torch.zeros_like(byte_all, dtype=torch.long)
        scored = active if sentence_slot is None else active & (ids == sentence_slot)
        present = present.scatter_add(1, ids.clamp(0, slots-1), scored.long()).bool()
        cost = byte_all.sum(-1) / present.sum(-1).clamp_min(1)
        result = (recovered, S.sum(-1)*0, cost, bad, byte_all)
        return (result, decoded) if return_decoded else result

    @_sentence_query_mask
    def reconstruct_grammar_sentence(self, state, sid, active):
        """The gate spells exactly the leaves emitted by the shared decoder."""
        from SentenceUnderstanding import readback_scores, readback_decisions
        self._publish_sentence_scratch(state)
        record = self._trial_understanding(state, sid, active)
        bank = record.primed
        words, count, truncated, _, _ = self._decode_conceptual_sentence(
            record.root, record.end_slots, record.end_depth, bank.codes, bank.valid, bank.weights,
            **({} if bank.case_bank is None else {"case_bank": bank.case_bank}))
        scores = torch.stack([readback_scores(words[:,w], bank.codes, bank.weights,
                              percept_width=bank.percept_width)
                              for w in range(words.shape[1])], 1)
        valid = bank.valid & bank.byte_valid.any(-1)
        self._last_readback_decisions = readback_decisions(words, count, bank, active)
        chosen = scores.masked_fill(~valid[:,None], -torch.inf).argmax(-1).cpu().tolist()
        rows, counts = bank.rows.cpu().tolist(), count.cpu().tolist()
        owner = self._concept_owner()
        texts = tuple(b' '.join(owner.word_surface_for_row(rows[b][i]) or b''
            for i in indices[:counts[b]]).decode('utf8') if bool(valid[b].any()) else None
            for b, indices in enumerate(chosen))
        return texts, (truncated | ~valid.any(-1)) & active

    def _reconstruct_sentence_traversal(self, S, reference, **_unused):
        """One row-level traversal (``_reconstruct_sentences`` with one
        sentence per row): ``(recovered, idea_cost, byte_cost, truncated)``."""
        B, D = int(S.shape[0]), int(S.shape[-1])
        roots = S.new_zeros(B, 1, 3 * D)
        rec, idea, byte_c, trunc, _per = self._reconstruct_sentences(
            S, reference, roots, torch.ones(B, 1, dtype=torch.long, device=S.device),
            torch.cat((S.reshape(B, 1, D), S.new_zeros(B, 2, D)), dim=1),
            torch.ones(B, dtype=torch.long, device=S.device))
        return rec, idea, byte_c, trunc

    def _reconstruction_basis_snapshot(self, reference):
        """Own the invocation's active concept rows, independent of surface targets."""
        atoms = getattr(self.inputSpace, "_ar_concept_lookup_atoms", None)
        rows = getattr(self.inputSpace, "_ar_concept_lookup_rows", None)
        B, _, D = reference.shape
        if not (torch.is_tensor(atoms) and atoms.ndim == 3 and atoms.shape[0] == B
                and torch.is_tensor(rows) and rows.shape == atoms.shape[:2]):
            raise RuntimeError("tied reconstruction requires a staged concept lookup bank")
        bank = atoms.to(reference).clone()
        interpretation = getattr(self._concept_owner(), 'interpret', None)
        if interpretation is not None:
            bank = interpretation.binding_atoms(bank)
        bank = F.pad(bank[..., :D], (0, max(0, D - bank.shape[-1])))
        return bank, rows.detach().to(reference.device).ge(0).clone()

    def _snapshot_tables(self, reference):
        """``(ready, bank_n [B, L, D], bank_bytes [B, L, P], bank_valid
        [B, L, P])``: the brick's dictionary snapshot as the byte
        decoder's candidates (normalised rows). Missing snapshots are staging
        errors; input bytes are scoring targets only."""
        isp = self.inputSpace
        atoms = getattr(isp, "_ar_concept_lookup_atoms", None)
        bank_bytes = getattr(isp, "_ar_bank_bytes", None)
        bank_valid = getattr(isp, "_ar_bank_valid", None)
        B, W, D = int(reference.shape[0]), int(reference.shape[1]), int(reference.shape[2])
        if (torch.is_tensor(atoms) and atoms.dim() == 3 and torch.is_tensor(bank_bytes)
                and torch.is_tensor(bank_valid) and bank_bytes.dim() == 3
                and bank_valid.shape == bank_bytes.shape and int(atoms.shape[0]) == B
                and int(bank_bytes.shape[0]) == B
                and int(atoms.shape[1]) == int(bank_bytes.shape[1])):
            bank = atoms.to(device=reference.device, dtype=reference.dtype).clone()
            interpretation = getattr(self._concept_owner(), 'interpret', None)
            if interpretation is not None:
                bank = interpretation.binding_atoms(bank)
            valid = bank_valid.detach().to(device=reference.device).clone()
            rows = getattr(isp, "_ar_concept_lookup_rows", None)
            if torch.is_tensor(rows) and rows.shape == bank.shape[:2]:
                valid = valid & rows.detach().to(reference.device).ge(0)[:, :, None]
            # An inactive dictionary row must not enter a dot product, even
            # with a later zero weight: zero * NaN would poison backward.
            bank = torch.where(valid.any(-1)[:, :, None], bank, torch.zeros_like(bank))
            if int(bank.shape[-1]) != D:
                bank = torch.cat((bank[..., :D], bank.new_zeros(
                    B, int(bank.shape[1]), max(0, D - int(bank.shape[-1])))), dim=-1)
            return (True, bank,
                    bank_bytes.detach().to(device=reference.device).clone(),
                    valid)
        raise RuntimeError("tied reconstruction requires a staged WORD surface bank")

    def _byte_tables(self, B, W):
        """Full staged target bytes and validity ``[B, W, P]``, for scoring.

        The eager boundary expands multi-byte percepts. The one-byte table is
        a compatibility fallback for callers without that lexical staging.
        """
        isp = self.inputSpace
        targets = getattr(isp, "_ar_target_word_bytes", None)
        mask = getattr(isp, "_ar_target_word_mask", None)
        if (torch.is_tensor(targets) and targets.dim() == 3
                and targets.shape[:2] == (B, W) and torch.is_tensor(mask)
                and mask.shape == targets.shape):
            return True, targets, mask
        ps = self.perceptualSpace
        part_ids = getattr(isp, "_ar_word_part_ids", None)
        part_mask = getattr(isp, "_ar_word_part_mask", None)
        table = getattr(ps, "_pid_byte_table", None)
        dev = isp._word_active_mask.device
        if not (torch.is_tensor(part_ids) and torch.is_tensor(part_mask)
                and torch.is_tensor(table)):
            return (False, torch.zeros(B, W, 1, dtype=torch.long, device=dev),
                    torch.zeros(B, W, 1, dtype=torch.bool, device=dev))
        table = table.to(device=part_ids.device)
        safe_ids = part_ids.clamp(0, int(table.numel()) - 1)
        bytes_bwp = table[safe_ids]                                     # [B, W, P]
        valid = torch.logical_and(part_mask.to(torch.bool), bytes_bwp >= 0)
        return True, bytes_bwp.clamp(0, 255), valid

    def _byte_word_cost(self, idea, word, bank_n, bank_bytes, bank_valid,
                        target_bytes, target_valid, ready, *, priming=None):
        """``[B]`` rung-zero identity audit, or the legacy byte cross entropy.

        Fixed identities read exact bytes through their sparse index. Their
        term is zero for an identified bank word and one for an unresolved
        word. The continuous byte objective below remains for dictionaries
        without identity by construction.

        A derived concept row carries its native perceptual fold. The lexical
        read-back matches that fold to a row whose surface is its bytes: the decoder's
        candidates are the rows of the brick's staged dictionary snapshot
        (``bank_n``, every word and object row the brick staged, with a
        null candidate of similarity 0 and uniform scoring symbols so a one-word
        brick, a zero idea or an idea near no row cannot score zero by
        having nothing to choose between). Score byte values 0..255, including
        the token's first NUL terminator (0), to distinguish a word from a
        longer word with the same prefix. No extra scoring category is added.
        Derived-code logits are absolute perceptual cosine × priming /
        temperature. Other dictionaries retain activation × cosine.
        The target byte's log mass sums only candidates emitting that byte,
        plus the null column's uniform byte mass; the normalizer sums every
        candidate and the null column. Both sums stay in log space. Thus a
        wrong winner cannot erase reconstruction credit through underflow or
        a probability floor. Gradients reach the recovered idea and its compose
        chooser; candidate codes, surface bytes and priming are constants.
        """
        B, L, C = (int(size) for size in bank_bytes.shape)
        W, P = int(target_bytes.shape[1]), int(target_bytes.shape[2])
        if not ready or P == 0:
            return idea.new_zeros(B)
        identity = getattr(getattr(getattr(self, 'perceptualSpace', None), 'percept_store', None), 'identity', None)
        if identity is not None:
            # A bank leaf names a row whose sparse form is checked at the
            # eager index boundary. Its bytes are exact, not a learned read.
            # Unknown/non-bank leaves remain an audit failure, not a soft CE.
            from SentenceUnderstanding import readback_scores
            present = bank_valid.any(-1)
            candidates = torch.where(present[..., None], bank_n.detach(), torch.zeros_like(bank_n))
            score = readback_scores(idea, candidates, torch.ones_like(present, dtype=idea.dtype),
                                    percept_width=identity.width)
            identified = (present & (score > 1.-1e-5)).any(-1)
            return (present.any(-1) & ~identified).to(idea.dtype) + idea.sum(-1) * 0.
        bank_n = bank_n.detach()
        present = bank_valid.any(dim=-1)                                 # [B, L]
        # Packing may place the same sentence's candidates in different
        # columns. Compact them stably before the dot products and softmax,
        # preserving the fixed bank capacity and the candidates' order.
        columns = torch.arange(L, device=bank_n.device).expand(B, L)
        compact = torch.argsort(columns + (~present).to(columns.dtype) * L, dim=1)
        bank_n = bank_n.gather(1, compact[:, :, None].expand_as(bank_n))
        bank_bytes = bank_bytes.gather(1, compact[:, :, None].expand_as(bank_bytes))
        bank_valid = bank_valid.gather(1, compact[:, :, None].expand_as(bank_valid))
        present = present.gather(1, compact)
        bank_n = torch.where(present[:, :, None], bank_n, torch.zeros_like(bank_n))
        # a symbol's value is its signed activation and its identity its
        # row: the snap reads the row regardless of the sign
        from SentenceUnderstanding import readback_scores
        priming = (torch.ones_like(present, dtype=idea.dtype) if priming is None
                   else priming.gather(1, compact))
        # Inductor reassociates float32 reductions/reciprocals in the dot,
        # norm and cosine. Large activation logits magnify those roundoff
        # differences before normalization. Accumulate the score and log
        # masses in double where supported, then return the input dtype.
        score_dtype = (torch.float64 if idea.device.type != 'mps'
                       and idea.dtype in (torch.float16, torch.bfloat16, torch.float32)
                       else idea.dtype)
        sim = readback_scores(idea.to(score_dtype), bank_n.to(score_dtype),
                              priming.to(score_dtype),
                              percept_width=getattr(self, '_readback_percept_width', None))
        sim = sim / self._BYTE_ASSIGNMENT_TAU
        # Token buffers terminate at their first NUL, even if a caller's
        # span includes padding or stale bytes after it.
        bank_valid = bank_valid & (bank_bytes != 0).to(torch.long).cumprod(-1).bool()
        sim = torch.where(present, sim, torch.full_like(sim, -1e4))
        normalizer = torch.logsumexp(
            torch.cat((sim, sim.new_zeros(B, 1)), dim=-1), dim=-1)
        positions = torch.arange(P + 1, device=idea.device)
        bank_end = (torch.where(bank_valid, torch.arange(C, device=idea.device) + 1, 0).amax(-1)
                    if C else torch.zeros_like(present, dtype=torch.long))
        bank_eow = positions == bank_end[:, :, None]
        # Candidate and target windows differ by the retained lookahead byte.
        # Score only the target's P bytes and its possible word end at P.
        # Gather through one masked sentinel column. Padding by max(P+1-C, 0)
        # followed by slicing imposes incompatible shape guards on dynamic P.
        candidate_positions = positions.clamp(max=C)
        bank_tokens = F.pad(bank_bytes, (0, 1)).index_select(-1, candidate_positions)
        bank_tokens = torch.where(bank_eow, torch.zeros_like(bank_tokens), bank_tokens)
        # Integer padding avoids Inductor's mixed VecMask types when a
        # boolean cumprod mask is fused across the sentinel boundary on ARM.
        bank_emits = (F.pad(bank_valid.to(torch.int32), (0, 1)).index_select(-1, candidate_positions).bool()
                      | bank_eow) & present[:, :, None]
        safe = word.clamp(0, W - 1).reshape(1, 1, 1)
        target = target_bytes.gather(1, safe.expand(B, 1, P)).reshape(B, P)
        valid = target_valid.gather(1, safe.expand(B, 1, P)).reshape(B, P).bool()
        target_present = valid.any(-1, keepdim=True)
        valid = valid & (target != 0).to(torch.long).cumprod(-1).bool()
        target_end = torch.where(valid, positions[:P] + 1, 0).amax(-1, keepdim=True)
        # Without a scoreable word, do not manufacture an empty-word target.
        target_eow = (positions == target_end) & target_present
        target = F.pad(target, (0, 1))
        target = torch.where(target_eow, torch.zeros_like(target), target)
        pos = (F.pad(valid.to(torch.int32), (0, 1)).bool() | target_eow).to(idea.dtype)
        emits_target = bank_emits & (bank_tokens == target[:, None, :])
        target_logits = sim[:, :, None].expand(B, L, P + 1).masked_fill(
            ~emits_target, -torch.inf)
        null_byte = sim.new_full((B, 1, P + 1), -math.log(256.0))
        logp = torch.logsumexp(torch.cat((target_logits, null_byte), dim=1), dim=1) \
            - normalizer[:, None]
        cost = (-logp * pos).sum(-1) / pos.sum(-1).clamp_min(1.0)
        return torch.where(present.any(-1), cost, torch.zeros_like(cost)).to(idea.dtype)
    _BYTE_ASSIGNMENT_TAU = 0.1

    # -- compiled reverse-loops plan, slice 3: the output generate walk ----

    def _stamp_channel(self, event_width):
        """Index of the rule stamp in a symbol-level event: the symbol
        space's ``.what`` width (the first ``.where`` channel); the event
        width less the canonical band when the space is unknown."""
        ss = getattr(getattr(self, "symbolSpace", None), "subspace", None)
        n_what = int(getattr(ss, "nWhat", 0) or 0)
        if 0 < n_what < int(event_width):
            return n_what
        return max(0, int(event_width) - 8)

    @staticmethod
    def _answer_occupancy(derivation, idea):
        """Keep declared roles, including resolved roles whose current value is zero."""
        occupied = torch.zeros(idea.shape[:2], dtype=torch.bool, device=idea.device)
        for b, field in enumerate(derivation.sentence_states):
            items = derivation.answer_meanings[b] if b < len(derivation.answer_meanings) else ()
            if items:
                mask = torch.cat([item.role_mask for item in items]).to(occupied.device)
            elif field is not None:
                mask = field.meaning.role_mask.to(occupied.device)
            else:
                continue
            occupied[b, :len(mask)] = mask
        return occupied

    def _materialize_answer_idea(self, understanding, derivation, question):
        """Condition a resolved end state once, then let the grammar generate."""
        fields = derivation.sentence_states
        idea = derivation.conceptual_answer
        if not fields or not torch.is_tensor(idea):
            return None, None, (), None
        resolved = torch.tensor([field is not None for field in fields],
                                dtype=torch.bool, device=idea.device)
        sources = []
        for b, field in enumerate(fields):
            source = derivation.row_sources[b] if b < len(derivation.row_sources) else 'identity'
            if field is None:
                source = ('no-concept-predictor' if source == 'prediction' else
                          'cold-memory' if 'cold-memory' in source or source == 'recall' else 'unresolved')
            sources.append('idea:' + source)
        occupied = self._answer_occupancy(derivation, idea)
        idea = idea.detach()
        context = derivation.conditioning_context
        idea = self._condition_answer_on_question(idea,
            context.detach() if torch.is_tensor(context) else context, occupied=occupied)
        # The compatibility fourth result remains absent: no input-reading
        # targets or generation actions cross this boundary.
        return torch.where(resolved[:, None, None], idea, torch.zeros_like(idea)), resolved, tuple(sources), None

    def _sentence_scope(self, t=None):
        """``[B, W]`` bool: the active words of sentence slot ``t``
        (``None``: the row's last sentence); ``None`` without a word mask."""
        isp = getattr(self, "inputSpace", None)
        active = getattr(isp, "_word_active_mask", None)
        if not torch.is_tensor(active):
            return None
        active = active.to(torch.bool)
        B, W = int(active.shape[0]), int(active.shape[1])
        packed = bool(getattr(isp, "_sentence_pack_enabled", False))
        ids = getattr(isp, "_packed_sentence_ids", None)
        if not (packed and torch.is_tensor(ids) and tuple(ids.shape) == (B, W)):
            if t is None or int(t) == 0:
                return active
            return torch.zeros_like(active)
        ids = ids.to(device=active.device, dtype=torch.long)
        if t is None:
            positions = torch.arange(W, device=active.device).reshape(1, W)
            last = torch.where(active, positions, torch.full_like(positions, -1)).amax(dim=1)
            sid = ids.gather(1, last.clamp_min(0).reshape(B, 1)).reshape(B)
        else:
            sid = torch.full((B,), int(t), dtype=torch.long, device=active.device)
        return torch.logical_and(active, ids == sid.reshape(B, 1))

    def _answer_symbol_rows(self, t=None):
        """``[B, W]`` concept rows of the symbols of sentence slot ``t``:
        the word concept rows the forward pushed (the symbol of a word is
        its concept row plus one activation), ``-1`` outside the sentence
        or where a word has no durable identity yet."""
        rows = self._word_symbol_rows()
        scope = self._sentence_scope(t)
        if not (torch.is_tensor(rows) and torch.is_tensor(scope)
                and tuple(rows.shape) == tuple(scope.shape)):
            return None
        rows = rows.to(device=scope.device, dtype=torch.long)
        return torch.where(scope, rows, torch.full_like(rows, -1))

    def _answer_leaf_slab(self, rows):
        """``[B, W, D]`` leaves of the symbols ``rows``: the concept
        dictionary row at each symbol's index (the shared index of the
        symbol and concept tables), the word's retained reference where it
        has no index yet; ``None`` without staged references."""
        reference = getattr(self, "_tensor_pushed_ideas", None)
        if not torch.is_tensor(reference) or reference.dim() != 3:
            return None
        B, W, D = int(reference.shape[0]), int(reference.shape[1]), int(reference.shape[2])
        if not (torch.is_tensor(rows) and tuple(rows.shape) == (B, W)):
            return reference
        try:
            owner = self._concept_owner()
        except Exception:
            owner = None
        cb = getattr(owner, "similarity_codebook", None)
        if cb is None:
            cb = getattr(getattr(self, "conceptualSpace", None), "similarity_codebook", None)
        lookup = getattr(cb, "lookup_rows", None)
        if not callable(lookup):
            return reference
        atoms = lookup(rows.clamp_min(0).to(torch.long))
        if not (torch.is_tensor(atoms) and atoms.dim() == 3):
            return reference
        interpretation = getattr(owner, 'interpret', None)
        if interpretation is not None:
            atoms = interpretation.binding_atoms(atoms)
        da = min(int(atoms.shape[-1]), D)
        indexed = (rows >= 0).reshape(B, W, 1).to(device=reference.device)
        atoms = atoms[..., :da].to(device=reference.device, dtype=reference.dtype)
        # Match the interpreted leaf: sign belongs only to the meaning face.
        acts = getattr(getattr(self, "symbolSpace", None), "_word_reference_activations", None)
        if torch.is_tensor(acts) and int(acts.numel()) == B * W:
            from Interpret import activate_code
            derived = getattr(cb, 'mereology', None)
            width = da if derived is None else derived.percept_event_width
            atoms = activate_code(atoms, acts.reshape(B, W).to(atoms), width)
        content = torch.where(indexed, atoms, reference[..., :da])
        if da < D:
            band = torch.where(indexed, torch.zeros_like(reference[..., da:]),
                               reference[..., da:])
            return torch.cat((content, band), dim=-1)
        return content

    def _walk_budget(self):
        """Trips of the generate walk: every word's pop plus its three
        possible folds plus the endings (the longest derivation the trace can
        record), a static bound so the compiled walk keeps one shape."""
        W = int(getattr(self, "serial_word_capacity", 0) or 8)
        cap = int(getattr(getattr(self.conceptualSpace, "stm", None), "capacity", 0) or 0)
        return max(2, 4 * W + max(1, 2 * cap))

    def _walk_operand(self, idea, infix_rows=(), *, occupied=None):
        """The materialised idea ``[B, K, D]`` as the walk's stack
        ``[B, cap, D]``: the idea's slots are newest first (the STM/LTM
        order) and the walk's top is its last live slot, so the live slots
        are reversed and the stack is padded to the STM capacity (an
        un-reduce needs room above the top)."""
        B, K, D = int(idea.shape[0]), int(idea.shape[1]), int(idea.shape[2])
        cap = max(K, int(getattr(self.conceptualSpace.stm, "capacity", K) or K))
        # A resolved role can have value zero. Its declared occupancy, not
        # the initial conditioner's numerical value, owns the gradient path.
        live = idea.abs().amax(dim=-1) > 0 if occupied is None else occupied
        d = live.to(torch.long).sum(dim=1)                              # [B]
        # Exclusion can leave a silent slot before occupied roles. Compact
        # the live roles before reversing; a count alone is not a prefix mask.
        positions = torch.arange(K, device=idea.device)[None, :]
        order = torch.where(live, positions, positions + K).argsort(dim=1, stable=True)
        idea = idea.gather(1, order[..., None].expand(B, K, D))
        pos = torch.arange(cap, device=idea.device).reshape(1, cap)
        src = (d.reshape(B, 1) - 1 - pos).clamp(0, K - 1)
        if infix_rows:
            if len(infix_rows) != B:
                raise ValueError("generate layout must name every answer row")
            infix = torch.tensor(infix_rows, device=idea.device, dtype=torch.bool)
            src = torch.where(infix[:, None], pos.expand(B, cap).clamp_max(K - 1), src)
        gathered = idea.gather(1, src.unsqueeze(-1).expand(B, cap, D))
        keep = pos < d.reshape(B, 1)
        return torch.where(keep.unsqueeze(-1), gathered, torch.zeros_like(gathered))

    def _derivation_program(self, t=None, budget=None):
        """The recorded derivation of sentence slot ``t`` (``None``: the
        row's last sentence) as owned compose tensors:
        ``positions [B, n]`` (the sentence's words as
        absolute word indices, -1 padded), ``actions [B, L, 3]`` (forward
        order, ``(kind, local op, local word)``: kind 0 pushes the word,
        1 folds the two tops by the binary op, 2 rewrites the top by the
        unary op; -1 padded) and ``targets [B, T]`` (reconstruction's reverse
        order: the endings last applied first, then per word latest
        first its unary, post-binary, pop and pre-binary, in the walk's
        action ids: a binary local id, ``R2 +`` a unary local id,
        ``R2 + R1`` = pop; -1 once exhausted).  Assembled on the host at
        the eager boundary from the trace; ``None`` without a trace."""
        trace = self._reconstruction_stack()
        language = getattr(self, "languageSpace", None)
        isp = getattr(self, "inputSpace", None)
        active = getattr(isp, "_word_active_mask", None)
        if trace is None or language is None or not torch.is_tensor(active):
            return None
        try:
            rule_ids, _arities, mask = trace.choices()
        except Exception:
            return None
        if not (torch.is_tensor(rule_ids) and torch.is_tensor(mask)
                and rule_ids.dim() == 2 and int(rule_ids.shape[0]) == int(active.shape[0])):
            return None
        B, W = int(active.shape[0]), int(active.shape[1])
        S = int(rule_ids.shape[1])
        binary_map = getattr(language, "_cs_binary_rule_ids", None)
        unary_map = getattr(language, "_cs_unary_rule_ids", None)
        R2 = int(binary_map.numel()) if torch.is_tensor(binary_map) else 0
        R1 = int(unary_map.numel()) if torch.is_tensor(unary_map) else 0
        stop = R2 + R1
        flat = rule_ids.reshape(-1)
        local_b, known_b = language.local_op_from_rule_ids(flat, binary_map)
        local_u, known_u = language.local_op_from_rule_ids(flat, unary_map)
        recorded = mask.reshape(-1).to(torch.bool)
        if bool((recorded & ~(known_b | known_u)).any()):
            raise ValueError('compose trace contains an unknown recorded operation')
        kind = torch.where(known_b, torch.ones_like(local_b),
                           torch.where(known_u, torch.full_like(local_b, 2),
                                       torch.full_like(local_b, -1)))
        kind = torch.where(recorded, kind, torch.full_like(kind, -1)).reshape(B, S)
        op = torch.where(known_b, local_b, torch.where(
            known_u, local_u, torch.full_like(local_b, -1))).reshape(B, S)
        cap = int(getattr(self.conceptualSpace.stm, "capacity", 0) or 0)
        closing_width = max(1, 2 * cap)
        packed = bool(getattr(isp, "_sentence_pack_enabled", False))
        ids = getattr(isp, "_packed_sentence_ids", None)
        if packed and torch.is_tensor(ids) and tuple(ids.shape) == (B, W):
            ids = ids.to("cpu").tolist()
        else:
            ids = [[0] * W for _ in range(B)]
        pos_tensor = getattr(trace, '_choice_positions', None)
        pos_l = (pos_tensor.to('cpu').tolist() if torch.is_tensor(pos_tensor)
                 else [[0] * S for _ in range(B)])
        kind_l = kind.to("cpu").tolist()
        op_l = op.to("cpu").tolist()
        rows = active.to("cpu").tolist()
        leaf_mask = getattr(isp, '_ar_grammar_leaf_mask', None)
        leaves = leaf_mask.to('cpu').tolist() if torch.is_tensor(leaf_mask) else rows
        T = int(budget) if budget is not None else self._walk_budget()
        positions_l, actions_l, targets_l, columns_l = [], [], [], []
        for b in range(B):
            words_all = [w for w in range(W) if rows[b][w]]
            words, actions, targets, columns = [], [], [], []
            if words_all:
                last = words_all[-1]
                sid = ids[b][last] if t is None else int(t)
                words = [w for w in words_all if ids[b][w] == sid]
            if words:
                hi = words[-1]
                base = 3 * W if hi == words_all[-1] else 3 * W + (hi + 1) * closing_width
                words = [w for w in words if leaves[b][w]]

                def _at(slot):
                    if 0 <= slot < S and kind_l[b][slot] >= 0:
                        return kind_l[b][slot], op_l[b][slot]
                    return -1, -1
                forest = []
                def apply(slot):
                    k, o = _at(slot)
                    if k == 1:
                        if len(forest) < 2:
                            raise ValueError('compose trace binary operation underflows')
                        right, left = forest.pop(), forest.pop()
                        forest.append((1, o, slot, left, right))
                    elif k == 2:
                        position = pos_l[b][slot]
                        if not 0 <= position < len(forest):
                            raise ValueError('compose trace unary position is not occupied')
                        forest[-1 - position] = (2, o, slot, forest[-1 - position])
                for i, w in enumerate(words):
                    forest.append((0, i))
                    for r in range(3):
                        apply(3 * w + r)
                for k in range(closing_width):
                    apply(base + k)
                for node in forest:
                    # A legal long sentence can nest beyond Python's call
                    # stack. Preserve left-to-right postorder explicitly;
                    # the configured trace, not recursion depth, bounds it.
                    pending = [(node, False)]
                    while pending:
                        node, emitted_children = pending.pop()
                        if node[0] == 0:
                            actions.append((0, -1, node[1]))
                            columns.append(-1)
                        elif emitted_children:
                            actions.append((node[0], node[1], -1))
                            columns.append(node[2])
                        else:
                            pending.append((node, True))
                            pending.extend((child, False) for child in reversed(node[3:]))
                targets = [stop if k == 0 else o if k == 1 else R2 + o
                           for k, o, _ in reversed(actions)]
            positions_l.append(words)
            actions_l.append(actions)
            targets_l.append(targets[:T])
            columns_l.append(columns)
        n_max = max(1, max(len(p) for p in positions_l))
        L_max = max(1, max(len(a) for a in actions_l))
        positions = torch.full((B, n_max), -1, dtype=torch.long)
        actions = torch.full((B, L_max, 3), -1, dtype=torch.long)
        columns = torch.full((B, L_max), -1, dtype=torch.long)
        targets = torch.full((B, T), -1, dtype=torch.long)
        for b in range(B):
            if positions_l[b]:
                positions[b, :len(positions_l[b])] = torch.tensor(positions_l[b], dtype=torch.long)
            if actions_l[b]:
                actions[b, :len(actions_l[b])] = torch.tensor(actions_l[b], dtype=torch.long)
                columns[b, :len(columns_l[b])] = torch.tensor(columns_l[b], dtype=torch.long)
            if targets_l[b]:
                targets[b, :len(targets_l[b])] = torch.tensor(targets_l[b], dtype=torch.long)
        dev = active.device
        return positions.to(dev), actions.to(dev), targets.to(dev), columns.to(dev)

    def _derivation_targets(self, t=None, budget=None):
        """``[B, T]`` teacher actions of the recorded derivation (see
        ``_derivation_program``); ``None`` without a trace."""
        program = self._derivation_program(t, budget)
        return None if program is None else program[2]

    def _capture_sentence_end_states(self):
        """Current and packed completed fields, already fixed by their endings."""
        captured = dict(getattr(self, '_sentence_fields', {}))
        if not captured:
            return (), {}
        B = len(next(iter(captured.values())))
        active = self.inputSpace._word_active_mask.to(torch.bool)
        ids = getattr(self.inputSpace, '_packed_sentence_ids', None)
        if torch.is_tensor(ids) and ids.shape == active.shape:
            final = torch.where(active, ids, -1).amax(-1).tolist()
        else:
            final = [max(captured)] * B
        return tuple(captured.get(int(sid), (None,) * B)[b]
                     for b, sid in enumerate(final)), captured

    def _capture_reading_programs(self, sentence_slot=None, *, admit=True):
        """Capture one program per sentence, sharing final rows with their slot.

        This is the eager boundary after forward publication. The whole brick's
        indexed leaves are gathered once, then copied into compact per-row
        records. A packed row with no sentence in a slot contributes None.
        """
        if getattr(self, '_open_sentence_slot', None) is None:
            raise RuntimeError('operation records exist only while a sentence is open')
        reference = getattr(self, "_tensor_pushed_ideas", None)
        isp = getattr(self, "inputSpace", None)
        active = getattr(isp, "_word_active_mask", None)
        if (not torch.is_tensor(reference) or reference.dim() != 3
                or not torch.is_tensor(active)
                or tuple(active.shape) != tuple(reference.shape[:2])):
            return (), {}
        B, W, D = reference.shape
        rows = self._word_symbol_rows()
        if not torch.is_tensor(rows) or tuple(rows.shape) != (B, W):
            rows = torch.full((B, W), -1, dtype=torch.long, device=reference.device)
        word_rows = getattr(isp, "_ar_word_concept_rows", None)
        if not torch.is_tensor(word_rows) or tuple(word_rows.shape) != (B, W):
            word_rows = torch.full_like(rows, -1)
        concept_ids = self._word_symbol_concept_ids()
        if not torch.is_tensor(concept_ids) or concept_ids.shape != rows.shape:
            concept_ids = torch.full_like(rows, -1)
        activations = getattr(self.symbolSpace, "_word_reference_activations", None)
        if not torch.is_tensor(activations) or activations.numel() != B * W:
            activations = reference.new_ones(B, W)
        else:
            activations = activations.reshape(B, W)
        leaves = self._answer_leaf_slab(rows)
        lexical_forms = self._word_lexical_forms(B, W)
        ids = getattr(isp, "_packed_sentence_ids", None)
        packed = (bool(getattr(isp, "_sentence_pack_enabled", False))
                  and torch.is_tensor(ids) and tuple(ids.shape) == (B, W))
        if packed:
            active = active.to(torch.bool)
            slots = sorted(int(t) for t in ids[active].unique().tolist() if int(t) >= 0)
            positions = torch.arange(W, device=active.device).expand(B, W)
            last = torch.where(active, positions, -1).amax(dim=1)
            last_ids = ids.gather(1, last.clamp_min(0)[:, None]).squeeze(1)
            last_ids = torch.where(last >= 0, last_ids, -1).tolist()
        else:
            slots, last_ids = [0], [0] * B
        captured = {}
        if sentence_slot is not None:
            slots = [sentence_slot]
        bank = getattr(self, "_tensor_sentence_roots_live", None)
        for slot in slots:
            if sentence_slot is None and slot in captured:
                continue
            program = self._derivation_program(slot if packed else None)
            if packed or sentence_slot is not None:
                end = (bank[:, slot].reshape(B, 3, D)
                       if torch.is_tensor(bank) and bank.dim() == 3
                       and slot < bank.shape[1] and bank.shape[-1] == 3 * D
                       else None)
            else:
                end = self._sentence_end_state(None)
            captured[slot] = (
                self._program_entries(program, leaves, rows, word_rows, activations, end,
                                      concept_ids=concept_ids,
                                      lexical_forms=lexical_forms, admit=admit)
                if program is not None and torch.is_tensor(end)
                else (None,) * B)
        current = tuple(captured.get(int(t), (None,) * B)[b]
                        for b, t in enumerate(last_ids))
        return current, captured

    def _program_entries(self, program, leaf_slab, rows, word_rows, activations, end_state,
                         *, concept_ids=None, lexical_forms=None, admit=True):
        """Own compact row references and compose actions for each batch row.

        ``lexical_forms`` is frozen grammar provenance aligned to the original
        word slab.  It is selected by the same retained positions as leaves;
        the answer record never stores the source text that supplied it.
        """
        positions, actions, targets, columns = program
        journal = getattr(self._reconstruction_stack(), "_choice_values", None)
        addresses = getattr(self._reconstruction_stack(), "_choice_refs", None)
        relations = getattr(self._reconstruction_stack(), "_choice_ref_relations", None)
        journal_columns = getattr(self._reconstruction_stack(), "_choice_journal_columns", None)
        if journal_columns is not None:
            columns = journal_columns.gather(1, columns.clamp(0, journal_columns.shape[1] - 1))
        entries = []
        for b in range(int(positions.shape[0])):
            pos = positions[b]
            n = int((pos >= 0).sum())
            if n == 0:
                entries.append(None)
                continue
            pos = pos[:n]
            acts = actions[b]
            L = int((acts[:, 0] >= 0).sum())
            source_forms = (
                lexical_forms[b]
                if lexical_forms is not None and b < len(lexical_forms) else ())
            selected_forms = tuple(
                source_forms[index] if 0 <= index < len(source_forms) else None
                for index in pos.detach().to("cpu").tolist())
            selected_words = word_rows[b].index_select(0, pos.to(word_rows.device))
            selected_ids = (concept_ids[b].index_select(0, pos.to(concept_ids.device))
                            if torch.is_tensor(concept_ids) else None)
            reference_ids = reference_orders = None
            resolve = getattr(getattr(self, 'languageSpace', None),
                              'resolve_lexical_references', None)
            owner = getattr(self, '_concept_owner', None)
            if callable(resolve) and callable(owner) and selected_ids is not None:
                args = (owner(), selected_words, selected_ids, acts[:L])
                reference_ids, reference_orders = resolve(*args) if admit else resolve(*args, admit=False)
                if not bool((reference_orders >= 0).any()):
                    reference_ids = reference_orders = None
            entry = AnswerProgram(
                rows=rows[b].index_select(0, pos.to(rows.device)),
                word_rows=word_rows[b].index_select(0, pos.to(word_rows.device)),
                activations=activations[b].index_select(0, pos.to(activations.device)),
                leaves=leaf_slab[b].index_select(0, pos.to(leaf_slab.device)),
                actions=acts[:L], targets=targets[b], end_state=end_state[b],
                word_ids=(None if not torch.is_tensor(getattr(getattr(self, 'inputSpace', None), '_ar_word_concept_ids', None)) else
                          self.inputSpace._ar_word_concept_ids[b].index_select(0, pos.to(self.inputSpace._ar_word_concept_ids.device))),
                concept_ids=selected_ids, reference_ids=reference_ids,
                reference_orders=reference_orders, lexical_forms=selected_forms,
                **{name: value[b].index_select(0, pos.to(value.device))
                   for name, value in (
                       ('leaf_orders', getattr(self.symbolSpace, '_word_reference_orders', None)),
                       ('leaf_evidence', getattr(self.symbolSpace, '_word_reference_evidence', None)))
                   if torch.is_tensor(value)},
                operation_values=(None if journal is None else
                    journal[b, columns[b, :L].clamp_min(0)].reshape(L, 3, leaf_slab.shape[-1])),
                operation_refs=(None if addresses is None else
                    addresses[b, columns[b, :L].clamp_min(0)]),
                operation_relations=(None if relations is None else
                                     relations[b, columns[b, :L].clamp_min(0)]),
                **{name: value[b].index_select(0, pos.to(value.device))
                   for name, value in (
                       ('symbol_where', getattr(getattr(self, 'inputSpace', None), '_ar_word_symbol_where', None)),
                       ('symbol_when', getattr(getattr(self, 'inputSpace', None), '_ar_word_symbol_when', None)))
                   if torch.is_tensor(value)})
            entries.append(entry)
        return tuple(entries)




    def _recall_sentence_history(self):
        """Bounded recency of completed fields; no compose history survives."""
        return self.__dict__.setdefault('_what_recall_sentence_history', {})

    def _generate_walk_width(self):
        """Concept width consumed by the answer's generate chooser."""
        language = getattr(self, "languageSpace", None)
        return int(getattr(language, "_generate_policy_width", 0) or -1)

    def _output_generate_walk(self, event, budget, stamped_events=False,
                              targets=None, sample_actions=False,
                              basis=None, basis_valid=None, candidate_limit=16,
                              *, basis_priming=None, return_trace=False,
                              exploit_actions=None, departure=None,
                              return_candidates=False, case_bank=None,
                              initial_depth=None, require_symbols=True):
        """The shared conceptual decoder. No compose actions enter this walk.

        Hard generate choices determine the stack topology. Reconstruction
        teaches the policy separately from the compose derivation's structure;
        this free walk supplies no straight-through policy gradient.
        """
        del targets, stamped_events
        language = self.languageSpace
        B, N, D = event.shape
        T = int(budget)
        R2, R1 = len(language._generate_binary_ops), len(language._generate_unary_ops)
        stop = R2 + R1
        ar = torch.arange(B, device=event.device)
        n_live0 = (event.abs().amax(-1).ne(0).sum(-1)
                   if initial_depth is None else initial_depth)
        if exploit_actions is not None:
            # A preceding differentiable while_loop can expose symbolic
            # journal strides. Materialize its fixed-shape trace before it
            # becomes an invariant input of the second compiled loop.
            exploit_actions = exploit_actions.clone(memory_format=torch.contiguous_format)
        draws = torch.rand(B, T, device=event.device) if sample_actions else None
        departure_draw = (torch.rand(B, 1, device=event.device, dtype=event.dtype)
                          if exploit_actions is not None else None)

        def cond(t, stack, depth, emitted, count, actions, alternatives):
            return (t < T) & (depth > 0).any()

        def body(t, stack, depth, emitted, count, actions, alternatives):
            pos = (depth - 1).clamp(0, N - 1)
            parent = stack[ar, pos]
            live = depth > 0
            logits = language.generate_policy_logits(parent)
            # Only the chosen numerical inverse supplies a pathwise gradient.
            lefts, rights, unavailable = [], [], []
            for i in range(R2):
                index = torch.full_like(depth, i)
                if basis is None and require_symbols:
                    left, right, missing = parent, parent, live
                else:
                    left, right, missing = language.reverse_binary_step(
                        parent, index, live, ops=language._generate_binary_ops,
                        basis=basis if require_symbols else None,
                        basis_valid=basis_valid if require_symbols else None, basis_priming=basis_priming,
                        candidate_limit=candidate_limit, free=require_symbols, return_status=True, case_bank=case_bank)
                lefts.append(left); rights.append(right); unavailable.append(missing)
            for i in range(R1):
                value, missing = language.generate_unary_step(
                    parent, torch.full_like(depth, i), live, return_status=True)
                # Pole-only operations preserve the code. Such an identity
                # cannot advance this code walk and must not consume its
                # entire allowance before STOP can emit the operand.
                missing = missing | ~value.detach().ne(parent.detach()).any(-1)
                lefts.append(value); rights.append(parent); unavailable.append(missing)
            lefts.append(parent); rights.append(parent); unavailable.append(torch.zeros_like(live))
            from Language import LanguageSpace
            available = ~torch.stack(unavailable, 1)
            # Native numerical answers realize through the shared inverse
            # chain; their values need not be an admitted word. Lexical
            # reconstruction retains its supported-pair/one-code eligibility.
            legal = (LanguageSpace.decoder_eligibility(parent, lefts, rights,
                available, language._generate_binary_ops,
                basis, basis_valid, case_bank=case_bank) if require_symbols else available)
            is_binary = torch.arange(stop + 1, device=event.device) < R2
            legal = legal & (~is_binary[None] | (depth < N)[:, None])
            logits = logits.masked_fill(~legal, -torch.inf)
            # An unreadable or capacity-blocked top remains pending. A finite
            # no-op distribution avoids NaNs but does not admit an emit.
            ready = legal.any(-1)
            logits = torch.where(ready[:, None], logits, torch.zeros_like(logits))
            choice = language.choose_generate(logits)
            if sample_actions:
                draw = draws.gather(1, t.reshape(1, 1).expand(B, 1))
                choice = (draw >= logits.detach().softmax(-1).cumsum(-1)).sum(-1).clamp_max(stop)
            if exploit_actions is not None:
                prior = exploit_actions.gather(1, t.reshape(1, 1).expand(B, 1)).reshape(B)
                excluded = F.one_hot(prior.clamp_min(0), stop + 1).bool()
                other_logits = logits.masked_fill(excluded, -torch.inf)
                from Language import sample_eligible_logits
                alternate = sample_eligible_logits(other_logits, departure_draw)
                choice = torch.where((t == departure) & legal.sum(-1).gt(1), alternate, choice)
                choice = torch.where((t < departure) & (prior >= 0), prior, choice)
            options = torch.stack(lefts, 1)
            others = torch.stack(rights, 1)
            selected = F.one_hot(choice, stop + 1).to(parent)
            left = (options * selected[..., None]).sum(1)
            right = (others * selected[..., None]).sum(1)
            missing = ~legal.gather(1, choice[:, None]).reshape(B)
            binary = live & (choice < R2) & (depth < N) & ~missing
            unary = live & (choice >= R2) & (choice < stop) & ~missing
            pop = live & (choice == stop) & ~missing
            rewritten = torch.where((binary | unary)[:, None], left, parent)
            stack1 = stack.clone()
            stack1[ar, pos] = torch.where(pop[:, None], 0., rewritten)
            above = (pos + 1).clamp_max(N - 1)
            stack1[ar, above] = torch.where(binary[:, None], right, stack1[ar, above])
            slot = (T - 1 - count).clamp(0, T - 1)
            emitted1 = emitted.clone()
            # At STOP, left is exactly the parent.
            emitted1[ar, slot] = torch.where(pop[:, None], left, emitted1[ar, slot])
            actions1 = actions.scatter(1, t.reshape(1, 1).expand(B, 1),
                                       torch.where(live & ready, choice, -1)[:, None])
            alternatives1 = alternatives.scatter(1, t.reshape(1, 1).expand(B, 1),
                                                  (live & legal.sum(-1).gt(1))[:, None])
            return (t + 1, stack1, depth + binary.long() - pop.long(),
                    emitted1, count + pop.long(), actions1, alternatives1)

        zeros = torch.zeros(B, device=event.device, dtype=torch.long)
        _, stack, depth, emitted, count, actions, alternatives = _reconstruction_while_loop(
            cond, body, _carries_with_grad((zeros.new_zeros(()), event.clone(), n_live0,
                event.new_zeros(B, T, D), zeros, zeros.new_full((B, T), -1),
                torch.zeros(B, T, device=event.device, dtype=torch.bool))))
        index = (torch.arange(T, device=event.device)[None] + (T-count)[:, None]).clamp_max(T-1)
        out = emitted.gather(1, index[..., None].expand(B, T, D))
        keep = torch.arange(T, device=event.device)[None] < count[:, None]
        out = torch.where(keep[..., None], out, 0.)
        result = (out, count, depth > 0, event.new_zeros(B))
        if return_candidates:
            return (*result, actions, alternatives)
        return (*result, actions) if return_trace else result

    def _compiled_output_walk(self):
        """The generate walk as the second compiled call (cached)."""
        cached = self.__dict__.get("_output_walk_compiled")
        if cached is not None:
            return cached
        import util as _util
        backend = getattr(_util, "TheCompileBackend", "none")
        fn = self._output_generate_walk
        if backend and backend != "none":
            try:
                fn = torch.compile(fn, backend=backend, fullgraph=True, dynamic=False)
            except Exception:
                fn = self._output_generate_walk
        self.__dict__["_output_walk_compiled"] = fn
        return fn

    def _install_unit_span_fn(self):
        """Hand the InputSpace the analysis ladder's unit tiler (packers and
        bucket choice count units, not whitespace words) when the canonical
        ``meronomy`` analysis is live; legacy cuts keep ``None``."""
        isp = getattr(self, "inputSpace", None)
        ws_list = getattr(self, "wholeSpaces", None) or []
        ws = ws_list[0] if ws_list else getattr(self, "wholeSpace", None)
        if isp is None or ws is None:
            return
        fn = None
        if (getattr(ws, "analysis_mode", "byte") == "meronomy"
                and hasattr(ws, "unit_spans_of_bytes")):
            fn = ws.unit_spans_of_bytes
            if (torch.is_tensor(getattr(ws, "begins_weight", None))
                    and hasattr(ws, "_predicate_masks")):
                ws._predicate_masks()     # prime the host masks (main thread)
        isp._unit_span_fn = fn

    def _lex_embed_stem(self, x):
        """Eager stem: lex (InputSpace) -> embed (PartSpace) -> finalize
        bookkeeping (InputSpace), model-orchestrated (2026-06-07).

        Replaces the retired ``InputSpace._peer_perceptual`` coupling: neither
        space holds a reference to the other; PartSpace is passed
        TRANSIENTLY to ``InputSpace.finalize_stem``. Runs in the EAGER pre-
        forward region (the compiled branch of ``runBatch``; inline for the
        eager path) so PS's host-side tokenization never enters the fullgraph
        trace -- the compiled body's ``PartSpace.forward`` then sees
        ``stem_embedded=True`` and skips re-embedding (pi only). Numeric input
        (``InputSpace.forward`` already embeds via the vocab codebook) returns
        ``stem_embedded=True`` and is passed through untouched.

        Dual view (analysis/synthesis plan, rev. 2026-06-09): InputSpace now
        emits ``(percepts_in, concepts_in)``; the ATOM view feeds the
        PS embed (synthesis), the UNITY view is parked on
        ``_staged_concepts_in`` for the symbolic branch (Phase 1: staged,
        UNUSED; Phase 2 consumes it at WS stage 0). This unpack is the
        orchestration-side shim the plan allows -- downstream contracts are
        unchanged.
        """
        # Keep the gated word-major radix mode in sync with the model flag on
        # every forward.  Tests/ablations may toggle ``serialObjectMeta`` on a
        # live model; a construction-time PartSpace stamp must not leave the
        # alternate representation active after the gate is disabled.
        if getattr(self, "perceptualSpace", None) is not None:
            object.__setattr__(
                self.perceptualSpace, "_serial_object_meta",
                bool(getattr(self, "serial_object_meta", False)
                     and getattr(self.inputSpace,
                                 "_serial_object_meta", False)))
        # Both bindings traverse analysis units. The mixing binding uses
        # its already configured PS word slots; native binding keeps its
        # explicit serialWordCapacity/buckets. Identity publication is still
        # controlled solely by the binding, not by this input representation.
        ps = self.perceptualSpace
        object.__setattr__(ps, '_serial_reading', bool(self.word_brackets))
        if self.word_brackets and not self.serial_object_meta:
            object.__setattr__(ps, '_serial_word_capacity', int(ps.outputShape[0]))
        in_sub, concepts_in = self.inputSpace.forward(x)
        if (getattr(self, "word_brackets", False)
                and getattr(self, "serial_object_meta", False)):
            self.inputSpace.select_word_loop_bucket(
                in_sub,
                tuple(self.serial_word_buckets
                      or (int(getattr(
                          self.inputSpace, "_serial_word_capacity", 1)),)),
                perceptual_space=self.perceptualSpace)
        self._staged_concepts_in = concepts_in
        # Dual-towers: an ALL-ZERO unity is NO unity -- validity is decided
        # HERE (host-eager stem, once per batch), never in routing. A None
        # offer routes the carrier body; a real unity routes universe,
        # unconditionally.
        _u_ok = (torch.is_tensor(concepts_in)
                 and bool((concepts_in != 0).any()))
        object.__setattr__(self, "_ws_universe",
                           concepts_in if _u_ok else None)
        # Phase 4b: host-eager analysis cut. The configured WS analysis
        # (word / analyse) divides the unity into parts HERE -- in the
        # eager stem, exactly like the PS host tokenization -- and parks
        # the spans on each WholeSpace for the stage-0 evidence
        # (pure tensor reads inside the compiled body). byte mode parks
        # None (uniform-region pooling needs no spans).
        _ws_list = (list(getattr(self, "wholeSpaces", None) or [])
                    or ([self.wholeSpace]
                        if getattr(self, "wholeSpace", None) is not None
                        else []))
        if _ws_list:
            _spans = (_ws_list[0].stage_analysis_spans(concepts_in)
                      if hasattr(_ws_list[0], "stage_analysis_spans")
                      else None)
            _kinds = getattr(_ws_list[0], "_staged_analysis_kinds", None)
            for _ss in _ws_list:
                # Preserve the complete eager cut for diagnostics. The live
                # WS kernel has exactly inputShape[0] locations and already
                # consumed only that prefix via ``min(K, N)``. Fit it here so
                # a compiled fixed-W graph does not specialize on the
                # sentence-dependent number of type runs.
                object.__setattr__(_ss, "_staged_analysis_spans_full", _spans)
                object.__setattr__(_ss, "_staged_analysis_kinds_full", _kinds)
                _live_spans = _spans
                _live_kinds = _kinds
                if (getattr(self, "serial_object_meta", False)
                        and torch.is_tensor(_spans)):
                    _n_live = max(1, int(_ss.inputShape[0]))
                    _live_spans = _spans[:, :_n_live, :]
                    if int(_live_spans.shape[1]) < _n_live:
                        _live_spans = torch.cat([
                            _live_spans,
                            _live_spans.new_zeros(
                                int(_live_spans.shape[0]),
                                _n_live - int(_live_spans.shape[1]), 2),
                        ], dim=1)
                    # B=1 makes a sliced tensor report ``is_contiguous`` even
                    # when its size-1 batch stride still reflects full K.
                    # Force a compact allocation so stride guards are stable.
                    _live_spans = _live_spans.clone(
                        memory_format=torch.contiguous_format)
                    if torch.is_tensor(_kinds):
                        _live_kinds = _kinds[:, :_n_live]
                        if int(_live_kinds.shape[1]) < _n_live:
                            _live_kinds = torch.cat([
                                _live_kinds,
                                _live_kinds.new_zeros(
                                    int(_live_kinds.shape[0]),
                                    _n_live - int(_live_kinds.shape[1])),
                            ], dim=1)
                        _live_kinds = _live_kinds.clone(
                            memory_format=torch.contiguous_format)
                _ss._staged_analysis_spans = _live_spans
                _ss._staged_analysis_kinds = _live_kinds
        if in_sub is None:
            return in_sub
        if hasattr(in_sub, "is_empty") and in_sub.is_empty():
            return in_sub
        if getattr(in_sub, "stem_embedded", True) is False:
            # The callback is transient to avoid a persistent model<->space
            # reference cycle. Atomic byte growth occurs inside embed_stem,
            # before its first W gather; queued word growth remains post-step.
            # The analysis tiling staged above is the ladder stem's unit
            # list (meronomy fold-ladder plan, contract 2: the towers share
            # one tiling); handed over transiently, like the callback.
            _unit_rows = None
            _spans_full = (getattr(_ws_list[0], "_staged_unit_spans", None)
                           if _ws_list else None)
            if torch.is_tensor(_spans_full) and _spans_full.dim() == 3:
                _unit_rows = [[(int(a), int(z)) for (a, z) in row.tolist() if z > a]
                              for row in _spans_full.detach().to("cpu")]
            object.__setattr__(self.perceptualSpace, "_staged_unit_spans", _unit_rows)
            self._observe_word_units(concepts_in, _unit_rows)
            try:
                self.perceptualSpace.embed_stem(in_sub)
            finally:
                object.__setattr__(self.perceptualSpace, "_staged_unit_spans", None)
            self.inputSpace.finalize_stem(in_sub, self.perceptualSpace)
            self._record_unit_pulls(_ws_list[0] if _ws_list else None)
            self._pad_staged_unit_maps(_ws_list[0] if _ws_list else None)
            self._ensure_pid_byte_table()
        self._ensure_chunk_machinery()
        # Resolve sparse concept identities only after the word-major PS stem
        # has exposed its exact residual parts and WS has staged the matching
        # property analysis. This remains wholly eager; the compiled word cell
        # sees fixed tensors and performs no dictionary walk or host sync.
        from ModelAttention import stage_input, stage_expectation
        stage_input(self)
        attention = self._attention_words
        self._attention_words = None
        try:
            self._stage_serial_concept_rows()
            self._stage_reading_word_concepts()
        finally:
            self._attention_words = attention
        self._attention_grammar_mask = self.inputSpace._ar_grammar_leaf_mask
        if attention is not None:
            from ModelAttention import handoff
            handoff(self,attention)
        stage_expectation(self)
        # the snapshot's surfaces need the bank the concept rows just staged
        self._stage_snapshot_bytes()
        self._stage_mixing_reconstruction_bank()
        if getattr(self, "reconstruct_in_loop", False):
            self._validate_reconstruction_bank()
        # Teacher objective addresses are a separate student query seam. This
        # records corpus/document/sentence/span codes on ``self.teacher.lesson``
        # without reading or changing the event's subjective .where/.when
        # bands, and without placing Python metadata inside the compiled body.
        teacher = getattr(self, "teacher", None)
        if teacher is not None:
            lesson = teacher.bind_input(
                in_sub,
                word_mask=getattr(
                    self.inputSpace, "_word_active_mask", None),
            )
            object.__setattr__(
                self, "_objective_query",
                (
                    lesson.objective_where_code,
                    lesson.objective_when_code,
                    lesson.objective_mask,
                ) if lesson is not None else None,
            )
        return in_sub


    def _end_step(self):
        """Per-step teardown: drop the staging parked by ``runBatch``
        (consume-once; eager, post-forward)."""
        # The complete captured W-loop uses only the live tensor depth for
        # capacity demand; it intentionally never reads or mutates the host
        # mirror inside the graph.  Synchronize that mirror once here for
        # eager sentence-boundary consumers (reports, snapshots, and a later
        # eager call) instead of letting its changing Python value fragment
        # the fullgraph specialization.
        if (getattr(self, "_compiled_word_loop_fullgraph", False)
                and self._active_compiled_step is not None):
            stm = getattr(getattr(self, "conceptualSpace", None), "stm", None)
            depth = getattr(stm, "_depth", None) if stm is not None else None
            if torch.is_tensor(depth) and depth.numel():
                stm._max_depth_host = int(depth.max().item())
        self._staged_in_sub = None
        self._staged_concepts_in = None
        self._active_compiled_step = None
        for _ss in (getattr(self, "wholeSpaces", None) or []):
            _ss._staged_analysis_spans = None
            _ss._staged_analysis_kinds = None
            _ss._staged_analysis_spans_full = None
            _ss._staged_analysis_kinds_full = None
            _ss._staged_unit_spans = None
            _ss._staged_tiling_ladder = None
            _ss._staged_unit_parent = None
            _ss._staged_word_primitive_counts = None
            _ss._staged_word_property_spans = None
        # Drop the global-attention soft-read (consume-once; the consumer in
        # Finish read it earlier this forward) so a stale obs can never leak
        # into the next forward's head.
        if getattr(self, "answer_attention", None) is not None:
            self._answer_attention_obs = None
        disc = (self.symbolSpace.expectation
                if self.symbolSpace is not None else None)
        if disc is not None:
            disc.clear_staged_prediction()

    def set_sentence_expectation(self, enabled):
        """Toggle expectation without replacing understanding or What memory.

        A head first enabled after optimizer construction joins the next
        training step through the existing fresh-parameter adoption boundary.
        """
        symbol_space = self.symbolSpace
        if symbol_space is None:
            raise RuntimeError("sentence expectation requires SymbolSpace")
        discourse = symbol_space.expectation
        if enabled and discourse is None:
            discourse = symbol_space.ensure_sentence_expectation()
            fresh = self.__dict__.setdefault("_fresh_synthesis_params", [])
            fresh.extend(p for p in discourse.parameters()
                         if p.requires_grad and all(p is not old for old in fresh))
            if getattr(self, "_compiled_step", None) is not None:
                self._compiled_step_needs_rebuild = True
        if discourse is not None:
            discourse.set_inter_loss_weight(self.inter_loss_weight)
            discourse.set_inter_contrastive(
                self.inter_contrastive_weight, self.inter_contrastive_temp)
            discourse.set_expectation_enabled(enabled)

    def _stage_expectation_documents(self, split, source_rows, batch):
        """Capture only cursor addresses, never text or supplied targets.

        FineWeb sentences have a shared document address across source rows.
        The packed slot retains its own address even when a brick crosses a
        document boundary. Unaddressed callers explicitly form one stream per
        row until reset; a guessed presentation index is not a document ID.
        """
        data = getattr(getattr(self, "inputSpace", None), "data", None)
        addresses = getattr(data, "source_addresses", {}).get(str(split), ())
        if source_rows is None:
            self._expectation_documents = None
            return
        rows = list(source_rows)
        nested = (rows if rows and isinstance(rows[0], (list, tuple))
                  else [[r] for r in rows])
        documents = []
        for b in range(int(batch)):
            row = []
            for source in nested[b] if b < len(nested) else ():
                if source is None or int(source) < 0:
                    row.append(None)
                    continue
                source = int(source)
                if source >= len(addresses):
                    row.append(None)
                    continue
                address = addresses[source]
                if "document" not in address:
                    raise ValueError("prediction source is missing its document")
                row.append((str(split), address["document"]))
            documents.append(tuple(row))
        self._expectation_documents = tuple(documents)
        discourse = getattr(getattr(self, "symbolSpace", None), "expectation", None)
        if discourse is not None:
            # Clear a new document's predecessor before anticipatory queries or
            # any other staging can consume it. Later packed slots repeat
            # this identity check at their individual observation boundary.
            discourse._prepare_expectation_documents(
                [row[0] if row else None for row in documents],
                [bool(row) for row in documents],
                int(batch))

    def _expectation_documents_for_slot(self, slot, batch):
        documents = getattr(self, "_expectation_documents", None)
        if documents is None:
            return None
        return [documents[b][slot]
                if b < len(documents) and slot < len(documents[b]) else None
                for b in range(int(batch))]

    def _discourse_arma_loss(self):
        """Inter-sentence ARMA(p, q) loss term for this step, or ``None``.

        Encapsulates ``BracketExpectation`` so runBatch sees only a
        model-level loss contribution. Must be called post-body /
        pre-backward: the term trains the ARMA predictor, and
        ``observe`` also commits the sentence rep + residual into the
        per-row rings (vectorized, sync-free).
        """
        disc = (self.symbolSpace.expectation
                if self.symbolSpace is not None else None)
        if disc is None or self._current_discourse_s is None:
            return None
        disc._arma_errors = Error()
        isp = getattr(self, "inputSpace", None)
        roots = getattr(self, "_packed_sentence_roots", None)
        if (isp is not None
                and bool(getattr(isp, "_sentence_pack_enabled", False))
                and torch.is_tensor(roots)):
            positions = isp._packed_sentence_slot_end_positions
            valid = isp._packed_sentence_slot_mask
            if (not torch.is_tensor(positions)
                    or not torch.is_tensor(valid)
                    or int(positions.shape[0]) != int(roots.shape[0])
                    or tuple(valid.shape) != tuple(positions.shape)):
                raise RuntimeError(
                    "packed discourse roots are missing their sentence slots")
            B, root_slots, _D = roots.shape
            if int(positions.shape[1]) != int(root_slots):
                raise RuntimeError(
                    "packed discourse root FIFO differs from its "
                    "chronological slots")
            loss_sum = roots.sum() * 0.0
            weight_sum = roots.new_zeros(())
            # Chronological time is the sentence-slot axis. Row b at slot t is
            # therefore followed only by row b at slot t+1, never by another
            # batch row or a length-sorted sentence.
            for t in range(int(positions.shape[1])):
                sentence = roots[:, t, :]
                mask = valid[:, t].to(
                    device=roots.device, dtype=torch.bool)
                primed = torch.logical_and(
                    disc._s_count.to(mask.device) > 0, mask)
                weight = primed.sum().to(dtype=roots.dtype)
                local = self._observe_discourse(
                    disc, sentence, mask=mask, slot=t,
                    understanding=getattr(self, "_last_understanding", None))
                if local is not None:
                    loss_sum = loss_sum + local * weight
                    weight_sum = weight_sum + weight
            return loss_sum / weight_sum.clamp_min(1.0)
        return self._observe_discourse(
            disc, self._current_discourse_s,
            understanding=getattr(self, "_last_understanding", None))

    def _discourse_inter_loss(self):
        """Inter-sentence end-state prediction loss term (Task 8, plan §9),
        or ``None``.

        The sentence-boundary hook ran ``predict_next_end_state`` (staging a
        predicted root) and ``observe_stm_end_state`` (scoring it against the
        arriving end-state, accumulating ``L_inter`` live on the discourse
        layer). Consume the per-sentence mean here, post-body / pre-backward
        (mirroring the ARMA + intra terms), so the term trains the
        inter-level predictor. Returns ``None`` when the discourse layer is
        absent (absolute-only configs no-op) or nothing was accumulated
        (eval, weight off, or no scored sentence this batch)."""
        disc = (self.symbolSpace.expectation
                if self.symbolSpace is not None else None)
        if disc is None:
            return None
        return disc.consume_inter_loss()

    def present(self) -> int:
        """The absolute model time (the serialized ``when_time`` clock).

        0-initialized; ``runBatch`` advances it by 1 per processed batch on
        BOTH train and inference. It is the authoritative absolute-time
        record; event .when bands carry document positions independently."""
        return int(self.when_time)

    def _advance_when_time(self):
        """Advance recency time once per batch; event bands do not read it."""
        # In-place so the registered buffer (and its device) is preserved.
        self.when_time += 1

    def _curriculum_questions(self, step, *, split, batch_size, sentence_index,
                              source_rows=None, training=True):
        """Question family for this training batch under <whatCurriculum>.

        Bresenham-style (no RNG): every ``1/ratio``-th batch is a curriculum
        trial.  ``present`` keeps the default family (present reconstruction
        / supervised answers); ``temporal`` alternates past and future at
        the configured distance on trial batches; ``full`` also cycles
        inference trials.  ``None`` means "use the default family".
        """
        mode = str(getattr(self, "what_curriculum", "none") or "none").lower()
        if not training or mode in ("none", "present"):
            return None
        ratio = float(getattr(self, "what_curriculum_ratio", 0.0) or 0.0)
        if ratio <= 0.0:
            return None
        # Count TRAINING BATCHES on the model: ``runEpoch``'s ``step`` advances
        # by the batch size, so a schedule keyed on it would skip trials.
        count = int(self.__dict__.get("_curriculum_batches", 0))
        self.__dict__["_curriculum_batches"] = count + 1
        if int((count + 1) * ratio) == int(count * ratio):
            return None
        trial = int((count + 1) * ratio)
        distance = int(getattr(self, "what_curriculum_distance", 1) or 1)
        default = self._questions_for_batch(
            split=split, batch_size=batch_size, sentence_index=sentence_index,
            source_rows=source_rows, questions=None, trial_mode="reconstruct")
        cycle = ["past", "future"] + (["inference"] if mode == "full" else [])
        family = cycle[(trial - 1) % len(cycle)]       # first trial = past
        out = []
        for q in default:
            if family == "past":
                out.append(What.past(q.where, -distance, split=split))
            elif family == "future":
                out.append(What.future(q.where, distance, split=split))
            else:
                out.append(What.inference(q.where, split=split))
        return tuple(out)

    def _questions_for_batch(self, *, split, batch_size, sentence_index,
                             source_rows=None, questions=None,
                             trial_mode="reconstruct"):
        """Normalize explicit questions or derive them from cursor rows."""
        if questions is not None:
            normalized = question_batch(questions)
            if len(normalized) != int(batch_size):
                raise ValueError(
                    f"question batch length {len(normalized)} != model batch "
                    f"size {int(batch_size)}")
            if any(question.split != str(split) for question in normalized):
                raise ValueError("every what question must use the active split")
            return normalized

        data = getattr(getattr(self, "inputSpace", None), "data", None)
        # A presentation index is a real position in the split.  Drivers whose
        # batch counter is not a row (the throughput bench warms up with
        # negative indices; cyclic corpus cursors) are folded into the split
        # extent; negative cursor pads (``-1``) count as "no source row".
        extent = 0
        if data is not None and hasattr(data, "what_extent"):
            try:
                extent = int(data.what_extent(split))
            except (KeyError, TypeError, ValueError):
                extent = 0

        def _fold(row):
            row = int(row)
            if extent > 0:
                return row % extent
            return max(0, row)

        if source_rows is not None:
            rows = list(source_rows)
            nested = (rows if rows and isinstance(rows[0], (list, tuple))
                      else [[row] for row in rows])
            resolved_rows = []
            for b in range(int(batch_size)):
                row = [r for r in (nested[b] if b < len(nested) else [])
                       if r is not None and int(r) >= 0]
                resolved_rows.append(
                    _fold(row[-1]) if row else _fold(int(sentence_index) + b))
        else:
            resolved_rows = [
                _fold(int(sentence_index) + b) for b in range(int(batch_size))]

        supervised = bool(getattr(data, "has_supervised_outputs", False))
        if str(trial_mode) == "predict":
            factory = lambda row: What.future(row, split=split)
        elif supervised:
            factory = lambda row: What.supervised(row, split=split)
        elif str(split) == "runtime":
            factory = lambda row: What.inference(row, split=split)
        else:
            factory = lambda row: What.present(row, split=split)
        return tuple(factory(row) for row in resolved_rows)

    @torch.no_grad()
    def _generated_word_text(self, words, lengths, *, bank=None):
        """Invert generated word concepts through the whole known vocabulary.

        This is the lexical inverse AFTER the generate grammar has emitted its
        concepts. It does not choose a relation or insert function words. All
        WORD/OBJECT rows with an owned spelling compete; neither the current
        input brick nor a hand-selected output alphabet limits the candidates.
        Both query and vocabulary axes are tiled to bound temporary storage.
        """
        owner = self._concept_owner()
        if bank is not None:
            from SentenceUnderstanding import readback_scores
            valid = bank.valid & bank.byte_valid.any(-1)
            scores = torch.stack([readback_scores(words[:,w], bank.codes, bank.weights,
                                  percept_width=bank.percept_width)
                                  for w in range(words.shape[1])], 1)
            chosen = scores.masked_fill(~valid[:, None], -torch.inf).argmax(-1).cpu().tolist()
            rows = bank.rows.cpu().tolist()
            counts = lengths.cpu().tolist()
            return tuple(b' '.join(owner.word_surface_for_row(rows[b][i]) or b''
                for i in indices[:counts[b]]).decode('utf8') if bool(valid[b].any()) else None
                for b, indices in enumerate(chosen))
        vocabulary = sorted({row for cid in owner.definitions.object_ids
                             if (row := owner._csw_row_of(cid)) is not None})
        spellings = {row: owner.word_surface_for_row(row) for row in vocabulary}
        vocabulary = [row for row in vocabulary if spellings[row] is not None]
        counts = lengths.detach().cpu().tolist()
        if not vocabulary:
            return tuple(None for _ in counts)
        B, W, D = words.shape
        flat = torch.nn.functional.normalize(words.detach().reshape(-1, D), dim=-1)
        chosen = torch.full((len(flat),), -1, device=flat.device, dtype=torch.long)
        for lo in range(0, len(flat), 256):
            queries = flat[lo:lo + 256]
            best = queries.new_full((len(queries),), -1)
            ids = chosen[lo:lo + 256]
            for start in range(0, len(vocabulary), 4096):
                rows = torch.tensor(vocabulary[start:start + 4096],
                                    device=flat.device, dtype=torch.long)
                atoms = owner.similarity_codebook.lookup_rows(rows).to(queries)
                if atoms.shape[-1] != D:
                    raise ValueError("word inverse requires the full conceptual width")
                atoms = torch.nn.functional.normalize(atoms, dim=-1)
                scores, index = (queries @ atoms.T).abs().max(-1)
                ids.copy_(torch.where(scores > best, rows[index], ids))
                best = torch.maximum(scores, best)
        rows = chosen.reshape(B, W).cpu().tolist()
        return tuple(b" ".join(spellings[index] for index in row[:min(W, int(count))]).decode("utf8")
                     for row, count in zip(rows, counts))

    def _grammar_target_word(self, word):
        """Teacher-side full concept of a word already in the live vocabulary."""
        owner = self._concept_owner()
        word_id = owner.definitions.word(form=word)
        if word_id is None:
            return None
        row = owner._csw_row_of(owner.definitions.deref(word_id))
        if row is None:
            raise ValueError("grammar target word has no live conceptual row")
        reference = owner.similarity_codebook.W
        return owner.similarity_codebook.lookup_rows(torch.tensor(row, device=reference.device)).detach()

    def _grammar_lesson_objectives(self, programs, *, split, source_rows):
        """Score supplied annotations after the student has fixed its parse.

        No labels enter forward, resolution or generation. Ordinary unlabelled
        corpora have no lessons. Stable source rows, not a word-to-operation
        map, select the teacher target for an annotated training presentation.
        """
        if split != "train" or self.grammar_lesson_weight <= 0:
            return None
        table = getattr(self.inputSpace.data, "grammar_lessons", {}).get(split, ())
        if not table:
            return None
        if source_rows is None or len(source_rows) != len(programs):
            raise ValueError("annotated grammar training requires stable source rows")
        lessons = []
        for row, program in zip(source_rows, programs):
            if isinstance(row, (tuple, list)) and len(row) == 1:
                row = row[0]
            if not isinstance(row, (int, np.integer)):
                raise ValueError("grammar lessons require unpacked sentence source rows")
            if not 0 <= int(row) < len(table) or program is None:
                raise ValueError("grammar lesson requires a live captured source row")
            lesson = table[int(row)]
            # Guard against accidentally crediting a different staged input.
            owner = self._concept_owner()
            words = [owner.word_surface_for_row(int(value))
                     for value in program.word_rows.detach().cpu().tolist()]
            if any(value is None for value in words) or b" ".join(words).decode("utf8") != lesson["text"]:
                raise ValueError("grammar lesson text does not match its captured forward words")
            lessons.append(lesson)
        from GrammarLessons import compose_loss, generate_loss
        self._grammar_lesson_errors = {'compose': Error(), 'generate': Error()}
        costs = {"compose": compose_loss(self.languageSpace, programs, lessons,
                                       errors=self._grammar_lesson_errors['compose']),
                 "generate": generate_loss(self.languageSpace, programs, lessons,
                               self.grammatical_thoughts, self._grammar_target_word,
                               errors=self._grammar_lesson_errors['generate'])}
        return {name: cost for name, cost in costs.items() if cost is not None} or None

    def runBatch(self, *args, **kwargs):
        return self._run_sentence_batch(*args, **kwargs)

    def _compose_completed_rows(self):
        """Completion mask for the serial or parallel derivation, if present."""
        depths = getattr(self, '_stm_post_depth', None)
        if getattr(self, 'word_brackets', False) and torch.is_tensor(depths):
            return depths > 0
        language = getattr(getattr(self, 'symbolSpace', None), 'languageLayer', None)
        derivation = getattr(language, '_last_derivation', None)
        return derivation.get('complete') if isinstance(derivation, dict) else None

    def _compose_records_enabled(self):
        return not getattr(self, '_exploration_trial', False)

    def _compose_round_owners(self, actions):
        """Sentence identity for every fixed word/closing operation slot."""
        B, T = actions.shape
        active = self.inputSpace._word_active_mask
        W = active.shape[1]
        ids = getattr(self.inputSpace, '_packed_sentence_ids', None)
        ids = ids if torch.is_tensor(ids) else torch.zeros_like(active, dtype=torch.long)
        owners = torch.full_like(actions, -1)
        owners[:, :3 * W] = ids.repeat_interleave(3, 1)[:, :T]
        closing_width = max(1, 2 * int(self.conceptualSpace.stm.capacity))
        last = torch.where(active, torch.arange(W, device=active.device)[None, :], -1).amax(1).clamp_min(0)
        last_id = ids.gather(1, last[:, None])
        if T > 3 * W:
            # Group zero belongs to the final closing. An intermediate sentence
            # ending at word w uses group w+1, including the one-word case.
            closing_ids = torch.cat((last_id, ids[:, :-1]), dim=1)
            owners[:, 3 * W:] = closing_ids.repeat_interleave(closing_width, 1)[:, :T - 3 * W]
        return owners, ids, last_id


    def _exploration_constraints(self):
        """One uniformly selected branchable round per row-owned sentence."""
        trace = self._reconstruction_stack()
        actions = getattr(trace, '_choice_actions', None)
        attempted = getattr(trace, '_choice_attempted', None)
        if not torch.is_tensor(actions) or not torch.is_tensor(attempted):
            return None, None, None
        actions, attempted = actions.detach().clone(), attempted.detach().clone()
        explorable = getattr(trace, "_choice_explorable", None)
        if torch.is_tensor(explorable):
            attempted &= explorable
        B, T = actions.shape
        owners, ids, _ = self._compose_round_owners(actions)
        forced = torch.zeros_like(attempted)
        counts = getattr(trace, '_choice_alternative_counts', attempted.long()).detach()
        self._compose_sampling_scale = torch.zeros_like(counts)
        for sid in range(int(ids.max().detach()) + 1):
            eligible = attempted & (owners == sid)
            self._compose_sampling_scale += torch.where(
                eligible, counts * eligible.sum(-1, keepdim=True), 0)
            # iid continuous ranks give a uniform draw over the eligible rounds.
            ranks = torch.rand(B, T, device=actions.device).masked_fill(~eligible, -1)
            selected = ranks.argmax(-1)
            forced = forced | torch.zeros_like(forced).scatter(
                1, selected[:, None], eligible.any(-1)[:, None])
        return actions, forced, owners

    @contextmanager
    def _sentence_run(self, *, training=False, optimizer=None, split='runtime',
                      source_rows=None, trial_mode='reconstruct'):
        """One sentence-boundary context for raw forward, evaluation and training."""
        from SentenceCompose import saved_sentence_values
        language = getattr(getattr(self, 'symbolSpace', None), 'languageLayer', None)
        self._sentence_ends = (self.word_brackets and  getattr(language, 'operation_layer', None) is not None)
        # Word-major sentences use the tied traversal at both training endings,
        # including configurations that retain the older event-loss report.
        # A reporting switch must not turn both compose objectives into zero.
        self._sentence_training = bool(training)
        self._sentence_supplied_answers = None
        self._sentence_credit_audits = []
        self._sentence_departure = None
        self._sentence_answer_questions = ()
        self._sentence_answer_cost = None
        self._sentence_run_active = True
        self._sentence_reader_updates = 0
        self._sentence_comparison_reader_updates = 0
        self._open_sentence_slot = None
        self._sentence_reconstruction = self._sentence_ends and self.reconstruct_in_loop
        keep_ideas = self._recon_keep_ideas
        self._recon_keep_ideas = keep_ideas or self._sentence_reconstruction
        self._sentence_optimizer = optimizer if training else None
        self._sentence_trial_costs = []
        self._sentence_winners = []
        self._sentence_fields = {}
        self._sentence_understandings = {}
        self._last_sentence_understanding = None
        self._sentence_primed_bank = None
        self._sentence_priming_written = False
        self._reading_lesson_sources = source_rows
        self._reading_lesson_split = split
        self._reading_lesson_enabled = training and trial_mode != 'predict'
        self._reading_lesson_reports = []
        self._sentence_reconstructions = []
        self._objective_gradient_writers = {}
        # Keep the initial and later compiled entries structurally identical.
        self._compose_exploit_actions = self._compose_forced_slots = None
        self._compose_prefix_slots = None
        self._compose_sampling_scale = None
        # Perception is shared by two backward/step pairs. Saved values must
        # remain those of its one forward even when the first update mutates
        # parameters. The graph itself still credits the perception parameters.
        hooks = (saved_sentence_values(self.parameters(), self.buffers())
                 if training and self._sentence_ends else nullcontext())
        try:
            with hooks:
                yield
        finally:
            self._sentence_ends = False
            self._sentence_reconstruction = False
            self._recon_keep_ideas = keep_ideas
            self._sentence_optimizer = None
            self._sentence_amp_scaler = None
            self._sentence_pullback = None
            self._compose_exploit_actions = self._compose_forced_slots = None
            self._compose_prefix_slots = None
            self._compose_sampling_scale = None

            self._sentence_training = False
            self._sentence_supplied_answers = None
            self._sentence_answer_questions = ()
            self._sentence_answer_cost = None
            self._sentence_run_active = False
            self._open_sentence_slot = None
            self.languageSpace._reference_bank = None
            self.languageSpace._compose_primed_bank = None

    def _run_sentence_batch(self, *args, **kwargs):
        """One public batch, with two local trials only when training is requested."""
        import inspect
        bound = inspect.signature(self._run_batch_once).bind(*args, **kwargs)
        bound.apply_defaults()
        call = dict(bound.arguments)
        with self._sentence_run(training=call['train'], optimizer=call['optimizer'],
                split=call['split'], source_rows=call['source_rows'], trial_mode=call['trial_mode']):
            return self._run_batch_once(**call)

    def _run_batch_once(self, train=True, batchNum=0, batchSize=10, split="train",
                 optimizer=None, batch_override=None, progress=None,
                 exploration_trial=False,
                 trial_mode="reconstruct", questions=None,
                 source_rows=None, attach_outputs=False, document_keys=None):
        """Run a single batch: forward pass, loss, and (if training) backward + step.

        Sentence trials are completed by the eager closing driver during forward.
        ``exploration_trial`` is the non-recording mode-schedule context read;
        it does not run a second batch derivation.

        Args:
            train: whether to compute gradients and update parameters.
            batchNum: opaque cursor for the next batch position.
            batchSize: number of examples per batch.
            split: "train", "test", or "validation".
            optimizer: pre-built optimizer (required when train=True).
            batch_override: optional ``(inputTensor, outputTensor)`` pair;
                the primary dispatch path used by the DataLoader streaming
                path in ``runEpoch``.
            progress: optional fraction in ``[0.0, 1.0]`` indicating how
                far through the current split's data the cursor has
                advanced. When set, the per-batch timing line includes
                a percentage so long runs report visible progress.
                ``runEpoch`` populates this from
                ``SentenceStreamDataset.progress()``; callers that drive
                ``runBatch`` directly leave it ``None``.
            questions: optional one-per-row ``WhatQuestion`` batch. When
                omitted, cursor coordinates select present reconstruction,
                supervised output, runtime inference, or future prediction.
            source_rows: stable zero-based presentation rows emitted by the
                data cursor (nested for packed sentence batches).
            attach_outputs: on runtime inference, retain each generated
                response on the presentation's output side with model
                provenance. Supplied labels remain unchanged.


        Returns:
            (BatchResult, nextBatchNum) on success, or (None, batchNum) when
            the dataset is exhausted.
        """
        self._install_unit_span_fn()
        record_trial = not exploration_trial
        self._packed_prediction_drained = False
        self._compose_complete = None
        # Completion belongs to this derivation, including serial/parallel
        # interleaving whose context batch can have a different row count.
        self._stm_post_depth = None
        language = getattr(getattr(self, 'symbolSpace', None), 'languageLayer', None)
        if language is not None:
            language._last_derivation = None
        self.train(bool(train))
        _ensure_grad_anchors(TheDevice.get())
        _disc = getattr(getattr(self, "symbolSpace", None), "expectation", None)
        if _disc is not None:
            _disc.detach_prediction_context()
        _stm = getattr(getattr(self, "conceptualSpace", None), "stm", None)
        if _stm is not None and hasattr(_stm, "detach_live"):
            _stm.detach_live()                  # no graph crosses a brick
        _trace = getattr(self, "_reconstruction_stack", None)
        _trace = _trace() if callable(_trace) else None
        if _trace is not None and hasattr(_trace, "detach_live"):
            _trace.detach_live()
        _release_loop_checkpoints(tuple(        # the previous brick's own loops
            getattr(self, name, None) for name in (
                "_stm_single_S", "_recon_cost", "_recon_idea_cost",
                "_tensor_sentence_roots_live", "_tensor_pushed_ideas",
                "_packed_sentence_roots")))
        object.__setattr__(self, "_recon_cost", None)
        object.__setattr__(self, "_recon_completed", False)
        object.__setattr__(self, "_reconstruction_product", None)
        object.__setattr__(self, "_recon_ideas", None)
        object.__setattr__(self, "_tensor_pushed_ideas", None)
        object.__setattr__(self, "_tensor_sentence_roots_depth", None)
        object.__setattr__(self, "_tensor_final_end_slots", None)
        object.__setattr__(self, "_tensor_final_end_depth", None)
        object.__setattr__(self, "_tensor_sentence_roots_live", None)
        # A caller may supply an optimizer built outside ``getOptimizer``.
        # Make the live owner visible to the PartSpace admission boundary.
        if optimizer is not None and getattr(
                self, "perceptualSpace", None) is not None:
            object.__setattr__(
                self.perceptualSpace, "_radix_optimizer", optimizer)
        # Enabling a previously absent expectation head changes the graph.
        if getattr(self, "_compiled_step_needs_rebuild", False):
            self.enable_compiled_step()
            self._compiled_step_needs_rebuild = False

        # First-call hook: try to enable §7 torch.compile reduce-overhead
        # mode on CUDA targets. Idempotent; safe on non-CUDA hosts.
        self._maybe_compile_brick()
        sentenceIdx = batchNum  # sentence index before batchNum increments
        if batch_override is None:
            raise RuntimeError(
                "runBatch: no batch_override supplied. Callers must pass "
                "batch_override=(inputTensor, outputTensor) — training "
                "path via the DataLoader in runEpoch, inference path via "
                "InputSpace.prepInput (or, for sentence-level generation, "
                "BasicModel.generate_sentence)."
            )
        batch = batch_override
        inputTensor, outputTensor = batch
        if train and trial_mode != 'predict':
            self._sentence_supplied_answers = outputTensor
        from Occurrence import stage_sources
        if split == 'runtime' and source_rows is None and 'runtime' in self.inputSpace.data.source_addresses:
            source_rows = list(range(len(inputTensor)))
        source = getattr(inputTensor, '_sentence_source', None) if source_rows is None else None
        address_split, address_rows = source if source is not None else (split, source_rows)
        stage_sources(self, address_split, address_rows, inputTensor, document_keys)
        self._stage_expectation_documents(
            split, source_rows, int(inputTensor.shape[0])
            if isinstance(inputTensor, torch.Tensor) else len(inputTensor))
        inference_only = not train and split == "runtime"
        what_questions = self._questions_for_batch(
            split=split,
            batch_size=(int(inputTensor.shape[0])
                        if isinstance(inputTensor, torch.Tensor)
                        else int(len(inputTensor))),
            sentence_index=sentenceIdx,
            source_rows=source_rows,
            questions=questions,
            trial_mode=trial_mode,
        )
        self._sentence_answer_questions = what_questions

        # Advance the serialized model clock once per PROCESSED batch (this
        # point is past the no-batch early raise, so it ticks exactly once on
        # BOTH the train and inference paths regardless of which return fires
        # below). The timestamp writer reads this clock; source positions
        # have already been staged independently for event .when bands.
        # The mode schedule's internal context read does not consume an
        # external batch. Compose's sentence trials run inside this one tick.
        if not exploration_trial:
            self._advance_when_time()

        # Pre-allocate per-batch state OUTSIDE the compiled forward.
        # ``SymbolSpace.ensure_microbatch`` allocates completion state /
        # ``_last_svo`` / ``_svo_valid`` / ``_recent_count`` etc. on
        # first call (and on shape changes); when those allocations
        # happen INSIDE a torch.compile region, CUDAGraph capture
        # takes ownership of the underlying memory, so the next
        # replay's allocation overwrites the previous step's state
        # and the next attribute read raises ``RuntimeError: Error:
        # accessing tensor output of CUDAGraphs that has been
        # overwritten by a subsequent run.`` Hoisting the call up
        # here keeps the resulting tensors Python-owned.
        if self.symbolSpace is not None and not inference_only:
            ss = self.symbolSpace
            try:
                if isinstance(inputTensor, torch.Tensor):
                    B_pre = int(inputTensor.shape[0])
                else:
                    B_pre = int(len(inputTensor))
            except Exception:
                B_pre = None
            if B_pre is not None:
                ss.ensure_microbatch(B_pre, 1)

        if train:
            optimizer.zero_grad()
        if record_trial:
            with torch.set_grad_enabled(bool(train)):
                self._stage_expectation_queries(training=bool(train))

        # Teacher owns the lesson, clean complete-input target, and error-term
        # registration window. Objective corpus addresses staged by runEpoch
        # are resolved here; the model's subjective .where/.when state is not
        # an input to Teacher and remains untouched.
        self._open_batch(
            split=split,
            batch_size=(
                int(inputTensor.shape[0])
                if isinstance(inputTensor, torch.Tensor)
                else int(len(inputTensor))
            ),
            training=train,
            clean_input=inputTensor,
        )

        # Per-batch Space.Start cascade (moved out of forward() so sliding
        # buffers can persist across forward() calls within a stream).
        self._start_spaces_for_forward()

        # AMP: torch.autocast wrapper from util.amp_context() honors
        # MODEL_AMP env var (hydrated from XML <architecture><amp> in
        # ModelFactory.run). bf16 returns scaler=None; fp16+CUDA returns
        # the process-wide GradScaler used in the backward path below.
        amp_cm, amp_scaler = amp_context()
        self._sentence_amp_scaler = amp_scaler
        with torch.set_grad_enabled(bool(train)), amp_cm:
            # Forward pass returns a 4-tuple.  IR-only contract:
            # ``predictions`` is ``[B, N, predDim]`` (one head emission
            # per P-slot) and ``forwardInput`` is the inputSpace event
            # ``[B, N, D]``.  ``reconstruction`` is always None after
            # the reverse pipeline retirement (2026-05-14); the slot
            # is kept in the tuple for downstream code that pattern-
            # matches on the legacy shape.
            #
            # ``cudagraph_mark_step_begin`` (only meaningful under modes
            # that capture CUDAGraphs -- "reduce-overhead", "max-
            # autotune") tells the runtime to release the previous
            # step's CUDAGraph outputs so the memory pool can be reused
            # for this step.  No-op under "default" mode; idempotent on
            # non-CUDA hosts.
            try:
                torch.compiler.cudagraph_mark_step_begin()
            except (AttributeError, RuntimeError):
                pass
            # O1: route the per-batch compute through the compiled
            # callable when enabled (else eager). runEpoch/runBatch stay
            # eager Python; only this forward+loss+backward unit is
            # torch.compiled. See doc/plans/2026-05-16-compiled-step-
            # boundary-design.md.
            # Keep eager staging immediately beside the compiled invocation:
            # the traced forward only reads these parked tensors.  The eager
            # path intentionally remains unchanged and lexes inline.
            if self._compiled_step is not None:
                if isinstance(inputTensor, torch.Tensor):
                    inputTensor = inputTensor.to(TheDevice.get())
                self._staged_in_sub = self._lex_embed_stem(inputTensor)
                # Sentence traces are staged after the cold-start reset and
                # before every compiled callable.  This keeps dense detached
                # surface copies and all Python lifecycle mutation outside the
                # graph while preserving the trace through its reverse/loss
                # consumer until the outer sentence-boundary reset.
                _ss_trace = getattr(self, "symbolSpace", None)
                if (getattr(self, "word_brackets", False)
                        and _ss_trace is not None
                        and not getattr(
                            _ss_trace, "_per_sentence_initialized", False)):
                    _ss_trace.soft_reset()
                    _ss_trace._per_sentence_initialized = True
                self._stage_reconstruction_teacher()
                _trace_slab = getattr(
                    self.inputSpace, "_ar_embedded_N", None)
                if (getattr(self, "word_brackets", False)
                        and torch.is_tensor(_trace_slab)):
                    self._prepare_reconstruction_choices(
                        int(_trace_slab.shape[0]),
                        int(_trace_slab.shape[1]),
                        _trace_slab.device)
                _requires_sparse_bank = self._aligned_serial_sparse_bank_mode()
                if _requires_sparse_bank:
                    _bank_rows = getattr(
                        self.inputSpace, "_ar_concept_lookup_rows", None)
                    _bank_atoms = getattr(
                        self.inputSpace, "_ar_concept_lookup_atoms", None)
                    if (not torch.is_tensor(_bank_rows) or _bank_rows.dim() != 2
                            or not torch.is_tensor(_bank_atoms)
                            or _bank_atoms.dim() != 3
                            or tuple(_bank_rows.shape)
                            != tuple(_bank_atoms.shape[:2])):
                        raise RuntimeError(
                            "compiled aligned serial forward requires the eager "
                            "sparse concept row bank; lexical staging did not "
                            "produce a shape-aligned rows/atoms pair")
                # A full W-loop owns one fixed, identity-masked residual-part
                # layout.  Do not give MPS a symbolic P range or compile a
                # separate full loop for every radix spelling.  The older
                # word-cell path retains its broad dynamic contract below.
                _fullgraph_word_loop = bool(getattr(
                    self, "_compiled_word_loop_fullgraph", False))
                if _fullgraph_word_loop:
                    # Cold-start sentence state must be materialized before
                    # Dynamo observes the word-loop module.  Creating this
                    # attribute inside the captured prelude changes an
                    # ``hasattr`` guard after the first forward and forces a
                    # duplicate W specialization.
                    _ss = getattr(self, "symbolSpace", None)
                    if (_ss is not None
                            and not getattr(_ss, "_per_sentence_initialized", False)):
                        _ss.soft_reset()
                        _ss._per_sentence_initialized = True
                    if _ss is not None:
                        # Establish every scalar/carrier attribute the
                        # captured recurrence writes before its first guard
                        # census.
                        object.__setattr__(
                            _ss, "_target_cursor_length", int(getattr(
                                self.inputSpace, "_active_word_bucket", 0) or 0))
                    _cs_owner = getattr(self, "conceptualSpace", None)
                    if _cs_owner is not None:
                        object.__setattr__(
                            _cs_owner, "_peer_prev_sub", getattr(
                                _cs_owner, "_peer_empty_sub", None))
                        object.__setattr__(
                            _cs_owner, "_peer_prev_sym", getattr(
                                _cs_owner, "_peer_empty_sym", None))
                    # ``_per_word_prelude`` creates a fresh STM working slab
                    # inside the graph.  Establish the same MPS-backed state
                    # before the first guard census; otherwise the
                    # constructor's CPU placeholder is observed on call one
                    # and the MPS replacement forces call two to compile
                    # again.
                    _staged_event = self._staged_in_sub.materialize()
                    _stm = getattr(
                        getattr(self, "conceptualSpace", None), "stm", None)
                    if torch.is_tensor(_staged_event) and _stm is not None:
                        _stm.begin_forward(
                            int(_staged_event.shape[0]),
                            device=_staged_event.device,
                            dtype=(_staged_event.dtype
                                   if _staged_event.is_floating_point() else None))
                    self._stage_fixed_residual_part_capacity()
                elif self.word_brackets:
                    # Only the serial word carrier has a variable part axis.
                    # Parallel perception uses its configured fixed slot count.
                    # W is deliberately static (one of 16/32/64/128); the
                    # number of residual radix constituents inside one
                    # complete word is not.  Mark only that P axis dynamic so
                    # promotion (e.g. five pieces -> one stored percept) does
                    # not compile another W graph. P>=3 excludes the
                    # contradictory Inductor guard ``P - 1 != 1`` while
                    # masked identity padding preserves words with one or two
                    # real constituents.
                    _part_min = 3
                    _part_max = max(_part_min, int(getattr(
                        self.inputSpace, "outputShape", (8192,))[0]))
                    for _part_tensor in (
                            getattr(self.inputSpace, "_ar_word_part_ids", None),
                            getattr(self.inputSpace, "_ar_word_part_mask", None),
                            getattr(self.inputSpace, "_ar_word_part_offsets", None),
                            getattr(self.inputSpace, "_ar_target_word_bytes", None),
                            getattr(self.inputSpace, "_ar_target_word_mask", None)):
                        if torch.is_tensor(_part_tensor) and _part_tensor.dim() == 3:
                            torch._dynamo.mark_dynamic(
                                _part_tensor, 2, min=_part_min, max=_part_max)
                    _word_width = max(1, int(getattr(
                        self.inputSpace, "_active_word_bucket", 1) or 1))
                    _flat_min = _part_min * _word_width
                    _flat_max = _part_max * _word_width
                    _ps_forward = getattr(
                        self.perceptualSpace, "_forward_input", None)
                    if isinstance(_ps_forward, dict):
                        for _name in ("indices", "seed_event", "word_groups",
                                      "part_spans", "percept_where"):
                            _value = _ps_forward.get(_name)
                            if torch.is_tensor(_value) and _value.dim() >= 2:
                                torch._dynamo.mark_dynamic(
                                    _value, 1, min=_flat_min, max=_flat_max)
                        for _name in ("word_part_indices", "word_part_mask"):
                            _value = _ps_forward.get(_name)
                            if torch.is_tensor(_value) and _value.dim() == 3:
                                torch._dynamo.mark_dynamic(
                                    _value, 2, min=_part_min, max=_part_max)
                for _cs in (getattr(self, "conceptualSpaces", None) or ()):
                    _validate_routing = getattr(_cs, "validate_intra_routing", None)
                    if callable(_validate_routing):
                        _validate_routing()
                _active_bucket = int(getattr(
                    self.inputSpace, "_active_word_bucket", 0) or 0)
                if _fullgraph_word_loop:
                    self._active_compiled_step = (
                        self._ensure_lazy_fullgraph_word_loop(_active_bucket))
                else:
                    self._active_compiled_step = self._compiled_word_steps.get(
                        _active_bucket, self._compiled_step)
                disc = (self.symbolSpace.expectation
                        if self.symbolSpace is not None else None)
                self._stage_legacy_discourse_prediction(
                    disc, fullgraph_word_loop=_fullgraph_word_loop)
            _fwd = (self.forward if exploration_trial or getattr(self, '_sentence_ends', False) else
                    (self._active_compiled_step if torch.is_grad_enabled()
                     and self._active_compiled_step is not None else self.forward))
            self._exploration_trial = bool(exploration_trial)
            try:
                # ``what()`` is a thin delegation over this exact executor.
                # It installs only target-free question/LTM chooser context;
                # the returned execution is the ordinary forward tuple.
                # The loss boundary supplies a scorer, never target content
                # to a forward or thought choice. Resolve desired answers only
                # when a complete realization is available to score.
                def score_answer(construction):
                    desired=tuple(self.inputSpace.data.what(q) for q in what_questions)
                    values=tuple(a.what if a.available and q.relation is WhatRelation.SUPERVISED else None
                                 for q,a in zip(what_questions,desired))
                    return self._output_target_cost(construction,values)
                _what_answers = self._what_or_think(
                    what_questions, inputTensor, executor=_fwd,
                    record=record_trial, score=(score_answer if train and trial_mode != 'predict'
                        and self.inputSpace.data.has_supervised_outputs else None))
                _forward_result = _what_answers[0].execution
                (forwardInput, symbols, predictions,
                 _) = self._publish_compiled_sentence_state(_forward_result)
                self._last_what_actual = tuple(_what_answers)
                # Answer-path modules built during this what() join the live
                # optimizer now (they post-date getOptimizer).
                if train and optimizer is not None:
                    self._adopt_fresh_parameters(optimizer)
                # This value is already a public graph output.  Publish its
                # detached discourse view eagerly as well, avoiding the same
                # attribute-only escape that PyTorch 2.14 eliminates for S.
                self._current_discourse_s = (
                    symbols.detach() if torch.is_tensor(symbols) else None)
            finally:
                self._exploration_trial = False
            self._end_step()
            # Unconditional SEEN priming: the rows this forward fired bump
            # their surfaces (no-grad bookkeeping; consumers read next batch).
            self._prime_seen_step()
            outputDataPred = predictions
            _construction = getattr(self, "_last_answer_construction", None)
            if (getattr(self, "answer_synthesis", False)
                    and _construction is not None
                    and torch.is_tensor(_construction.actual)):
                outputDataPred = _construction.actual

            # Resolve desired answers only AFTER the model response is fixed.
            # The resulting values are loss-side metadata and never enter the
            # forward call, grammar context, STM, LTM, or runtime cache.
            _what_data = getattr(self.inputSpace, "data", None)
            if _what_data is not None and hasattr(_what_data, "what"):
                self._last_what_desired = tuple(
                    _what_data.what(question) for question in what_questions)
            else:
                self._last_what_desired = tuple()
            if (inference_only and attach_outputs
                    and _what_data is not None
                    and hasattr(_what_data, "attach_output")):
                for question, answer in zip(
                        what_questions, self._last_what_actual):
                    _what_data.attach_output(question, answer)

            # ε-growing codebook hook (Phase 4 follow-up): when any
            # codebook-bearing space carries ``codebookGrowthEpsilon > 0``
            # in its XSD, invoke ``VectorQuantize.grow_on_novelty`` on
            # the encoder output to insert novel inputs into empty
            # slots before the EMA path locks in assignments.  No-op
            # when ``growth_epsilon`` is 0 (default) or every slot is
            # already populated.
            if train:
                for _sp_attr in ("perceptualSpace", "conceptualSpace",
                                 "wholeSpace"):
                    _sp = getattr(self, _sp_attr, None)
                    _cb = getattr(getattr(_sp, "subspace", None),
                                  "what", None)
                    _vq = getattr(_cb, "vq", None)
                    if _vq is None:
                        continue
                    _eps = float(getattr(_vq, "growth_epsilon", 0.0)
                                 or 0.0)
                    if _eps <= 0.0:
                        continue
                    _ev = (_sp.subspace.materialize()
                           if _sp.subspace is not None else None)
                    if _ev is None:
                        continue
                    try:
                        _vq.grow_on_novelty(_ev, _eps)
                    except Exception:
                        # Growth is best-effort -- never let an
                        # insertion glitch stop the training step.
                        pass

            if inference_only:
                # Inference path: forward only, no loss.
                result = self.BatchResult(
                    outputPred=outputDataPred, symbols=symbols,
                    lossOut=None, lossIn=None,
                    inputPred=None, forwardInput=forwardInput,
                )
                self.End()
                return result, batchNum

            if outputTensor is None:
                raise RuntimeError(
                    f"runBatch: missing output targets for split='{split}'. "
                    "For inference use split='runtime'."
                )

            # 2026-05-28: restore supervised output-head loss for
            # tasks that need it (e.g. XOR_exact with binary labels).
            # The prior IR-only regime hardcoded output_weight=0 and
            # routed all gradient through the masked-LM ``lossIn``;
            # that path is preserved (when ``outputTensor`` is absent
            # or the labels are zero-width, the supervised branch
            # degenerates to the original "side channel" semantics).
            # When ``outputTensor`` IS supplied, compare the head
            # prediction against the labels and apply a non-zero
            # weight so the head receives gradient. Mirrors the
            # ``reconstruction_reverse`` pattern (try-guarded so a
            # shape edge case degrades to zero contribution rather
            # than crashing the step).
            lossOut = torch.zeros((), device=TheDevice.get())
            output_errors, input_errors, reverse_errors = Error(), Error(), Error()
            output_weight = 0.0
            selected_answer_credit = None
            # ``Data.what()`` is the answer-loss authority (What spec Step 5):
            # the question's desired answer replaces the loader's incidental
            # ``outputTensor``; unavailable rows are masked out of the term.
            _answer_target, _answer_mask = self._what_answer_target(
                what_questions, outputTensor,
                supervised_only=bool(train and getattr(self, "answer_synthesis", False)))
            self._last_answer_target = _answer_target
            self._last_answer_mask = _answer_mask
            _answer_authority = _answer_target is not None
            _scored_target = _answer_target if _answer_authority else (
                None if _answer_mask is not None else outputTensor)
            _surface_target = getattr(self, "_answer_surface_target", None)
            _surface = getattr(getattr(self, "_last_answer_construction", None),
                               "surface", None)
            try:
                if (_surface_target is not None and torch.is_tensor(_surface)
                        and _answer_mask is not None and bool(_answer_mask.any())):
                    # Text answer: constructed surface vs embedded
                    # target sentence, band-aware, masked to answerable rows.
                    lossOut = self._reverse_event_loss(
                        _surface[_answer_mask], _surface_target[_answer_mask],
                        registry=output_errors, name='answer', objective='output')
                    output_weight = 1.0
                    if train and float(getattr(self, "selected_thought_policy_weight", 0.0)) > 0:
                        selected_answer_credit = self._selected_thought_answer_errors(
                            _surface, _surface_target, _answer_mask, what_questions, surface=True)
                elif (getattr(self.inputSpace.data,
                            "has_supervised_outputs", True)
                        and _scored_target is not None
                        and torch.is_tensor(_scored_target)
                        and _scored_target.numel() > 0
                        and outputDataPred is not None
                        and torch.is_tensor(outputDataPred)
                        and outputDataPred.numel() > 0):
                    # shape reconciliation lives in _align_output_pred; irreconcilable warns once and zeroes the term.
                    _pred = self._align_output_pred(outputDataPred,
                                                    _scored_target)
                    if _pred is not None:
                        if train and float(getattr(self, "selected_thought_policy_weight", 0.0)) > 0:
                            selected_answer_credit = self._selected_thought_answer_errors(
                                _pred, _scored_target, _answer_mask, what_questions)
                        if (_answer_authority
                                and not bool(_answer_mask.all())):
                            _pred = _pred[_answer_mask]
                            _scored_target = _scored_target[_answer_mask]
                        lossOut = self.loss.compute(_pred, _scored_target)
                        self.loss.register(output_errors, 'answer', _pred, _scored_target,
                            category='prediction', objective='output')
                        output_weight = 1.0
            except Exception as _out_exc:
                # Best-effort degrade to zero, but never SILENTLY (5b fail-loud).
                lossOut = torch.zeros((), device=TheDevice.get())
                output_weight = 0.0
                selected_answer_credit = None
                self._warn_zeroed_channel(
                    "output_loss_exception",
                    f"supervised output loss zeroed by "
                    f"{type(_out_exc).__name__}: {_out_exc}")
            self.record_loss(
                "output", lossOut,
                weight=output_weight,
                space="OutputSpace", category="prediction", trained=False,
            )
            # Supplied answers have already trained their reader once at
            # each sentence closing. The batch-end read is reporting only.
            self.errors.merge(output_errors, trained=(False if
                getattr(self, '_sentence_reader_updates', 0) else None))

            # IR masked-LM loss: compare the post-body perceptual event
            # at masked positions against the pre-mask embedding the
            # forward snapshotted in ``_ir_pre_mask_input``.  No reverse
            # pipeline involved -- the body / head ran masked, the
            # masked positions carry the prediction target, the head
            # plays no role in the loss.  This is the BERT-style
            # masked-LM contract.
            inputDataPred = None
            inputPred = None
            mask_pos = getattr(self, "_ir_mask_positions", None)
            pre_mask = getattr(self, "_ir_pre_mask_input", None)
            pred_full = None
            if hasattr(self.perceptualSpace.subspace, 'materialize'):
                pred_full = self.perceptualSpace.subspace.materialize()
            # None checks stay Python (no sync). The masked reconstruction
            # loss is computed densely via `compute_masked` instead of a
            # boolean-mask gather `pred[mask]` -- the gather is
            # data-dependent (its row count is read to host: an implicit
            # cudaMemcpyDtoH that breaks CUDA-graph capture).
            # `compute_masked` is the sync-free, value-equivalent form
            # (masked-sum / masked-count) and returns 0.0 on an empty
            # mask with no NaN (replacing the old nan_to_num gate). See
            # doc/BrickHostSyncStatus.md residual D.
            # Serial grammar readings consume the owned byte reconstruction.
            # Paths without a grammar keep perceptual reconstruction.
            if self.reconstruct_in_loop:
                # Completion belongs to understanding, before reasoning and
                # output can change staging. Training and evaluation consume
                # precisely the same owned byte objective, once.
                owned = self._last_understanding.input_reconstruction
                if owned is None or not torch.is_tensor(owned.byte_cost):
                    raise RuntimeError("tied reconstruction completed without its byte objective")
                lossIn = owned.byte_cost.mean()
                input_errors.error('reconstruction.free_bytes', owned.byte_cost, math.log(256),
                    mask=self.inputSpace._reconstruction_sentence_available.any(-1),
                    category='reconstruction')
                if not train:
                    inputDataPred = owned.event.detach()
            elif (mask_pos is not None and pre_mask is not None
                    and pred_full is not None):
                # Band-aware seam: percept-layout where/when scales (silent-band wiring fix, 2026-07-04).
                lossIn = self._masked_event_loss(pred_full, pre_mask,
                                                 mask_pos, registry=input_errors)
            else:
                lossIn = torch.zeros((), device=TheDevice.get())
                # 5b fail-loud: a dead reconstruction channel must announce itself (warn-once, names the gate).
                _missing = ", ".join(
                    n for n, v in (("mask", mask_pos), ("target", pre_mask),
                                   ("pred", pred_full)) if v is None)
                _cb = getattr(getattr(self.perceptualSpace, 'subspace',
                                      None), 'what', None)
                self._warn_zeroed_channel(
                    "reconstruction_zeroed",
                    f"perceptual reconstruction inputs missing "
                    f"({_missing}); percept .what={type(_cb).__name__}, "
                    f"pred_full shape="
                    f"{tuple(pred_full.shape) if torch.is_tensor(pred_full) else None}")
            self.record_loss(
                "reconstruction", lossIn,
                weight=1.0,
                space="InputSpace", category="reconstruction", trained=False,
            )
            self.errors.merge(input_errors, weight=self.loss.reconstruction_scale)
            missing = getattr(self.inputSpace, '_reconstruction_missing_sentence_count', None)
            self.record_loss('reconstruction_unavailable_sentences', missing, trained=False, category='count')

            # A grammar-free reading retains its perceptual event inverse.
            # The grammar path has already supplied its single byte objective.
            lossRev = torch.zeros((), device=TheDevice.get())
            _rev_dedupe = self.reconstruct_in_loop
            try:
                if forwardInput is not None and not _rev_dedupe:
                    # reverseReconstruct owns the input inverse and its seed;
                    # runBatch consumes its result and diagnostic score.
                    # One understanding for both downward paths (Step 6):
                    # reuse the one ``what()`` captured for this execution.
                    understanding = getattr(self, "_last_understanding", None)
                    if (understanding is None
                            or understanding.execution is not (
                                tuple(_forward_result)
                                if isinstance(_forward_result, list)
                                else _forward_result)
                            and understanding.symbolic_state is not symbols):
                        understanding = self._capture_understanding(
                            _forward_result)
                    self._last_understanding = understanding
                    rev_ev, lossRev_rec = self.reverseReconstruct(
                        understanding, target=forwardInput, train=train, registry=reverse_errors)
                    if (not train and rev_ev is not None
                            and torch.is_tensor(rev_ev)):
                        inputDataPred = rev_ev.detach()
                    if lossRev_rec is not None:
                        lossRev = lossRev_rec
            except Exception:
                # Reverse round-trip is approximate through averaged
                # loops; never let a reconstruction edge case stop the
                # training step.
                lossRev = torch.zeros((), device=TheDevice.get())
            if not _rev_dedupe:
                self.record_loss(
                    "reconstruction_reverse", lossRev,
                    weight=float(getattr(self.loss, 'reconstruction_scale',
                                         0.0) or 0.0),
                    space="InputSpace", category="reconstruction", trained=False,
                )
                self.errors.merge(reverse_errors, weight=self.loss.reconstruction_scale)

            # Raw diagnostic costs, recorded before backward. The Error
            # registry owns the trained total; tied byte reconstruction has
            # no second reverse-event training term.
            self._last_primary_costs = {
                "input_reconstruction": lossIn,
                "input_reconstruction_reverse": lossRev,
                "answer_construction": lossOut,
            }
            self._record_what_batch(
                what_questions, lossOut,
                lossIn if (torch.is_tensor(lossIn) and float(lossIn.detach()) != 0.0)
                else lossRev,
                sentences=len(what_questions))

            # JOINT mode: compute SBOW embedding loss
            sbow = None
            if train:
                embedding_errors = Error()
                sbow = self.trainEmbeddings(('JOINT'), sentenceIdx, split, errors=embedding_errors)
                # Perceptual SBOW: when lexer=byte, train percept vectors
                # via leave-one-out centroid prediction
                if getattr(self, 'lexer', None) in ('byte', 'bytes'):
                    psbow = self.perceptual_sbow_loss(errors=embedding_errors)
                    if psbow is not None:
                        sbow = psbow if sbow is None else sbow + psbow
                if sbow is not None:
                    self.record_loss(
                        "embedding_sbow", sbow,
                        weight=self.loss.embedding_scale,
                        space="SymbolSpace", category="embedding", trained=False,
                    )
                    self.errors.merge(embedding_errors, prefix='embedding.', weight=self.loss.embedding_scale)

            # Inter-sentence ARMA(p, q) loss term -- model-owned
            # (``_discourse_arma_loss``): predicts ``s_hat_t`` from the
            # lagged reps/residuals, returns the per-batch MSE, and
            # commits the new rep + residual into the rings (vectorized,
            # sync-free). Cold-start rows return ``None``. Computed here,
            # post-body / pre-backward, so the term trains the predictor.
            # Each paired trial starts from the same prior runtime. Its
            # private observation and prediction context survive only if that
            # trial wins; both trials are scored under the same objective.
            legacy_prediction = bool(getattr(self, "legacy_prediction_enabled", False))
            arma_loss = (self._discourse_arma_loss()
                         if (train and legacy_prediction
                             and record_trial) else None)

            # Intra-sentence prediction loss term (Task 3, STM serial/
            # parallel modes) -- ``ConceptualSpace.forward`` ran the
            # in-STM predictor predict-then-perceive over the per-word
            # steps and accumulated ``L_intra = MSE(prediction, perceived)``
            # live (grad-bearing) on the conceptual space. Consume the
            # per-batch mean here, post-body / pre-backward (mirroring the
            # ARMA term), so the term trains the intra-sentence predictor.
            # ``consume_intra_loss`` resets the accumulator; it returns
            # ``None`` when nothing was accumulated (eval, weight off, or
            # an all-degenerate sentence).
            intra_loss = (self.conceptualSpace.consume_intra_loss()
                          if train and legacy_prediction else None)

            # Inter-sentence end-state prediction loss term (Task 8, plan
            # §9) -- the sentence-boundary hook ran the inter-level
            # predictor + scored it against the arriving end-state,
            # accumulating ``L_inter`` live on the discourse layer. Consume
            # the per-sentence mean here, post-body / pre-backward (mirroring
            # the ARMA + intra terms). ``None`` when the discourse layer is
            # absent (absolute-only no-op), eval-time, weight off, or no
            # scored sentence this batch.
            inter_loss = (
                self._discourse_inter_loss()
                if train and record_trial else None
            )
            expectation_policy_loss = self._expectation_policy_loss() if train and record_trial else None
            # InfoNCE next-idea contrastive term (the discourse layer's second
            # accumulator; populated during the forward boundary observe).
            inter_contrastive = None
            if train and record_trial and self.symbolSpace is not None:
                _disc = getattr(self.symbolSpace, "expectation", None)
                if _disc is not None and hasattr(
                        _disc, "consume_inter_contrastive_loss"):
                    inter_contrastive = _disc.consume_inter_contrastive_loss()

            # Trial-split: on a PURE next-idea PREDICTION trial, zero the
            # reconstruction + auxiliary terms so the next-idea signal (inter
            # MSE + InfoNCE contrastive) is the SOLE gradient. prediction_trial_
            # ratio == 0 -> trial_mode is always "reconstruct" -> this never
            # fires -> byte-identical. Done post-forward so the forward stays
            # mode-independent (no Dynamo recompiles).
            if train and trial_mode == "predict":
                _z = torch.zeros((), device=TheDevice.get())
                lossOut, lossIn = _z, _z
                sbow = None
                lossRev = None
                arma_loss = None
                intra_loss = None

            # The registry owns the trained sum; raw gate metrics stay separate.
            # Keep the actual weighted objectives distinct for diagnostics.
            # A missing answer is not substituted with reconstruction credit.
            gradient_objectives = None
            _rr = float(self.loss.reconstruction_scale)
            if train:
                gradient_objectives = {
                    "reconstruction": _rr * lossIn,
                    "output": (1.0 - _rr) * lossOut,
                    "expectation": lossIn.new_zeros(()),
                }
            lesson_reports = getattr(self, '_reading_lesson_reports', ())
            if train and trial_mode != 'predict' and lesson_reports:
                grammar_lesson = torch.stack(lesson_reports).mean()
                # Already trained inside the sentence; this detached term
                # keeps the batch's reported total complete without replay.
                self.record_loss('grammar_lesson', grammar_lesson,
                    weight=self.grammar_lesson_weight, space='LanguageSpace', category='grammar', trained=False)
            _cscale = float(getattr(
                self.loss, "conceptual_similarity_scale", 0.0) or 0.0)
            if train and not self.word_brackets and _cscale > 0.0:
                concept_errors = Error()
                csbow = self.conceptual_sbow_loss(errors=concept_errors)
                if csbow is not None:
                    self.record_loss(
                        "conceptual_sbow", csbow, weight=_cscale,
                        space="ConceptualSpace", category="embedding", trained=False,
                    )
                    self.errors.merge(concept_errors, prefix='conceptual_sbow.', weight=_cscale)
            # Rank-ordered soft-L0 that keeps concept definitions compact
            # (snap contract sec 5). Default lambda 0.0 -- byte-identical off.
            _dss = float(getattr(
                self.loss, "definition_sparsity_scale", 0.0) or 0.0)
            if train and _dss > 0.0 and self.conceptualSpace is not None:
                defsp = self.conceptualSpace.definition_sparsity_loss(lam=1.)
                if defsp is not None:
                    self.record_loss(
                        "definition_sparsity", defsp, weight=_dss,
                        space="ConceptualSpace", category="reg")
            if lossRev is not None:
                if gradient_objectives is not None:
                    gradient_objectives["reconstruction"] = (
                        gradient_objectives["reconstruction"] + _rr * lossRev)
            word_expected = getattr(self, '_word_expectation', None)
            if train and word_expected is not None and not getattr(self, '_sentence_trial_costs', ()):
                mask = self._word_expectation_mask
                word_loss = (word_expected.loss * mask).sum() / mask.sum().clamp_min(1)
                self.record_loss('expectation.word', word_loss,
                    weight=self.word_expectation_weight, category='expectation')
                if gradient_objectives is not None:
                    gradient_objectives['expectation'] += self.word_expectation_weight * word_loss
            if arma_loss is not None:
                if gradient_objectives is not None:
                    gradient_objectives["expectation"] += self.arma_scale * arma_loss
                self.errors.merge(self.symbolSpace.expectation._arma_errors,
                                  prefix='expectation.', weight=self.arma_scale)
            if intra_loss is not None:
                self.errors.merge(self.conceptualSpace._consumed_intra_errors,
                                  prefix='expectation.', weight=self.conceptualSpace.intra_loss_weight)
            if inter_loss is not None and self.inter_loss_weight > 0.0:
                if gradient_objectives is not None:
                    gradient_objectives["expectation"] += self.inter_loss_weight * inter_loss
                self.errors.merge(_disc._consumed_inter_errors, prefix='expectation.',
                                  weight=self.inter_loss_weight)
            if inter_contrastive is not None and self.inter_contrastive_weight > 0.0:
                if gradient_objectives is not None:
                    gradient_objectives["expectation"] += self.inter_contrastive_weight * inter_contrastive
                self.errors.merge(_disc._consumed_contrastive_errors, prefix='expectation.',
                                  weight=self.inter_contrastive_weight)
            if hasattr(self, 'outputSpace'):
                pipeline_errors = self.outputSpace.subspace.errors
                self.errors.merge(pipeline_errors)
                pipeline_errors.clear()

            if expectation_policy_loss is not None and self.expectation_policy_weight > 0:
                self.record_loss("expectation_policy", expectation_policy_loss,
                    weight=self.expectation_policy_weight, space="SymbolSpace", category="policy")
                if gradient_objectives is not None:
                    gradient_objectives["expectation"] = (gradient_objectives["expectation"]
                        + self.expectation_policy_weight * expectation_policy_loss)
            # One hard-choice credit contract for completed grammatical
            # episodes, using the shared meter and the later answer error.
            if train and selected_answer_credit is not None and float(
                    getattr(self, "selected_thought_policy_weight", 0.0) or 0.0) > 0.0:
                selected_pol_loss = self._selected_thought_policy_loss(
                    selected_answer_credit[0], mask=selected_answer_credit[1])
                if selected_pol_loss is not None:
                    self.record_loss(
                        "selected_thought_policy", selected_pol_loss,
                        weight=self.selected_thought_policy_weight,
                        space="SymbolSpace", category="policy")


            # Method-1 -> Method-2 leaf distillation (snap design doc step
            # 3): the exact-leaf teacher supervises a from-root decoder so
            # the collapsed root stays SEPARABLE per sentence. Default
            # weight 0.0 -> skipped -> byte-identical.
            if train and float(
                    getattr(self, "leaf_distill_weight", 0.0) or 0.0) > 0.0 \
                    and not self.reconstruct_in_loop:
                try:
                    leaf_errors = Error()
                    ld_loss = self._leaf_distill_loss(registry=leaf_errors)
                except Exception:
                    ld_loss = None     # distillation must not abort training
                if ld_loss is not None:
                    if gradient_objectives is not None:
                        gradient_objectives["reconstruction"] = (
                            gradient_objectives["reconstruction"]
                            + self.leaf_distill_weight * ld_loss)
                    self.errors.merge(leaf_errors, weight=self.leaf_distill_weight)
                    # The head is built lazily on first use — hand its
                    # params to the LIVE optimizer once (getOptimizer ran
                    # before the head existed).
                    if (optimizer is not None
                            and getattr(self, "_leaf_distill_head_fresh",
                                        False)):
                        self._leaf_distill_head_fresh = False
                        optimizer.add_param_group({"params": list(
                            self._leaf_distill_head_module.parameters())})

            # Truth-modulated loss: delegated to SymbolSpace since the
            # TruthLayer lives there.  SymbolSpace handles the empty-store
            # guard internally; we only gate on ``train``.  The falsity
            # penalty operand is the last cached symbol activation --
            # stored truths are also recorded from symbol space, so both
            # sides of the disjunction live in the basis's native space.
            if train and self.symbolSpace is not None:
                symbol_acts = None
                if hasattr(self, 'symbol_states') and self.symbol_states:
                    symbol_acts = self.symbol_states[-1]
                truth_base = self.errors.total()
                self.symbolSpace.truth_modulated_loss(
                    lossOut*0 if truth_base is None else truth_base,
                    symbolic_space=self.conceptualSpace,
                    symbol_acts=symbol_acts,
                    universality_score=getattr(self, '_universality_score', None),
                    luminosity_weight=getattr(self, 'luminosity_weight', 0.1),
                    universality_weight=getattr(self, 'universality_weight', 0.1),
                    truth_loss_weight=getattr(self, 'truth_loss_weight', 0.0),
                    allow_excluded_middle=getattr(self, 'allow_excluded_middle', 1),
                    allow_contradiction=getattr(self, 'allow_contradiction', 0),
                    model=self,
                    gradient_objectives=gradient_objectives,
                )
                # Gate-L1 sparsity penalty on LiftLayer / LowerLayer
                # raw_gate parameters. Pulls unused singular-component
                # multipliers toward zero so each rule converges to a
                # low-rank slice of its host operator. Default lambda
                # is 0.0 -- no penalty unless a config opts in.
                gate_l1 = self.symbolSpace.gate_l1_loss(
                    lam=1. if getattr(self, 'gate_l1_lambda', 0.0) > 0 else 0.)
                if gate_l1 is not None:
                    self.record_loss(
                        "gate_l1", gate_l1,
                        weight=getattr(self, 'gate_l1_lambda', 0.0),
                        space="SymbolSpace", category="reg")

                # Stage 3 cleanup: the chart's sparse-MoE load-balance
                # bookkeeping retired with the chart itself. The
                # <loadBalanceWeight> knob stands by for any future
                # signal-router rule load-balancing; no consumer yet.

            if train:
                batch_objective = self.errors.total()
                readout_l1 = self._configure_concept_readout_l1(optimizer,
                    stage=batch_objective is not None and batch_objective.requires_grad)
                if readout_l1 is not None:
                    # Reporting only: the single optimizer step handles the
                    # non-smooth L1 term in Adam's diagonal metric. Adding its
                    # subgradient here would penalize every connection twice.
                    self.record_loss(
                        "concept_readout_l1", readout_l1 / self._concept_readout_l1_strength,
                        weight=self._concept_readout_l1_strength,
                        space="ConceptualSpace", category="reg", trained=False)

            if train and trial_mode == 'predict':
                for term in self.errors._terms.values():
                    if term['category'] in ('reconstruction', 'prediction', 'embedding', 'grammar'):
                        term['trained'] = False
            totalLoss = self.errors.total()
            if totalLoss is None:
                totalLoss = lossOut + lossIn * 0
                if getattr(self, '_sentence_reader_updates', 0):
                    totalLoss = totalLoss.detach()
            gradient_objectives = {name: self.errors.total(objective=name)
                for name in ('reconstruction', 'output', 'expectation')} if train else None

            # Snapshot the breakdown before the backward pass so later
            # calls to TheError.covariance() can see it in the history
            # even if the step is aborted by a non-finite detector below.
            # snapshot()'s per-term .item() is a cudaMemcpyDtoH (breaks
            # the brick CUDA-graph-capture contract, test_brick_no_sync)
            # and only feeds the diagnostic covariance() API (no
            # training-loop consumer). Gate behind MODEL_DEBUG, like the
            # finite-loss guard just below.
            if _util.MODEL_DEBUG:
                self.errors.snapshot()

        # Per-batch finite-loss guard is a GPU sync (.all() materializes).
        # Gate it behind MODEL_DEBUG so production training pays no per-batch
        # sync; failures still surface via NaN gradients downstream.
        if _util.MODEL_DEBUG and not torch.isfinite(totalLoss).all():
            def _loss_value(name, value):
                if value is None:
                    return f"{name}=None"
                if isinstance(value, torch.Tensor):
                    finite = torch.isfinite(value).all().item()
                    if value.numel() == 1:
                        return f"{name}={value.detach().item()} finite={finite}"
                    return f"{name}=shape{tuple(value.shape)} finite={finite}"
                return f"{name}={value}"

            details = ", ".join([
                _loss_value("lossOut", lossOut),
                _loss_value("lossIn", lossIn),
                _loss_value("sbow", sbow),
                _loss_value("arma", arma_loss),
                _loss_value("symbol", symbol_loss),
                _loss_value("total", totalLoss),
            ])
            raise FloatingPointError(
                f"Non-finite total loss in {self.name}.runBatch("
                f"split={split}, batch={batchNum}): {details}"
            )

        # Plain f-string without totalLoss -- interpolating a tensor's
        # __format__ forces a device sync every batch.  The epoch summary
        # still carries per-epoch losses; per-batch loss is available via
        # MODEL_DEBUG if needed.
        #
        # Per-batch wall-clock: time.perf_counter() reads the host
        # monotonic clock (no GPU sync). The first batch (before
        # ``self._last_batch_time`` is set) prints without a delta --
        # that "compile + warm-up" tick is heavily front-loaded and
        # measuring it as "delta from epoch start" would be misleading.
        # Subsequent batches print ``(Δ=X.XXXs)`` where X is the
        # wall-clock elapsed since the last batch's report.
        import time as _time
        now = _time.perf_counter()
        last = getattr(self, '_last_batch_time', None)
        # Optional percent-complete suffix when the cursor populated
        # ``progress`` (set from ``SentenceStreamDataset.progress()``
        # in ``runEpoch``). Direct ``runBatch`` callers (tests,
        # inference) pass progress=None and get the bare timing line.
        pct = ("" if progress is None
               else f", {min(progress, 1.0) * 100.0:.2f}%")
        if last is None:
            TheMessage(f"batch = {batchNum} (warm-up{pct})")
        else:
            TheMessage(f"batch = {batchNum} (Δ={now - last:.3f}s{pct})")
        self._last_batch_time = now

        # Inductor / Dynamo recompile detector. Per-shape recompiles can
        # show up as wall-clock variance on otherwise identical batches;
        # this prints a one-line delta whenever Dynamo records new
        # frame events (compiles, recompiles, graph breaks). Defensive
        # try/except: torch._dynamo counters API has changed across
        # versions, and on MODEL_COMPILE=none there's nothing to count.
        try:
            from torch._dynamo.utils import counters as _dyn_counters
            frames = _dyn_counters.get('frames', {})
            rc_now = sum(int(v) for v in frames.values())
            rc_last = getattr(self, '_last_recompile_count', None)
            if rc_last is None:
                self._last_recompile_count = rc_now
            elif rc_now > rc_last:
                delta = rc_now - rc_last
                # Show the breakdown (e.g. ok=N, recompile=M) so a
                # stable steady-state with occasional recompiles is
                # visible at a glance.
                detail = ", ".join(f"{k}={v}" for k, v in sorted(frames.items()))
                TheMessage(f"  [compile] dynamo +{delta} frame events (total {rc_now}; {detail})")
                self._last_recompile_count = rc_now
        except Exception:
            pass

        if train:
            _every = int(getattr(self, "branch_diagnostics_every", 0) or 0)
            if (_every > 0 and int(getattr(
                    self, "_training_step_count", 0) or 0) % _every == 0):
                self._sample_gradient_diagnostics(gradient_objectives, optimizer)
            if not totalLoss.requires_grad:
                # An input-only batch already trained at its sentence endings.
                # With no batch-end teacher term there is no third backward.
                _fineweb_step_performed = bool(self._sentence_trial_costs)
            elif amp_scaler is not None:
                # fp16 on CUDA: scale grads to avoid underflow, then unscale
                # inside scaler.step() before the actual optimizer update.
                self._backward_training_loss(
                    totalLoss, amp_scaler, optimizer=optimizer)
                self._assert_finite_train_state("after backward")
                if self.ergodic:
                    self.paramUpdate()
                # CUDA fp16 GradScaler owns its fused unscale/non-finite
                # check. In auto mode the optimizer wrapper's guard is also
                # disabled, preserving the brick's zero-D2H contract.
                from LearningEvaluation import scaler_step_performed
                _fineweb_step_performed = scaler_step_performed(amp_scaler, optimizer)
            else:
                self._backward_training_loss(
                    totalLoss, optimizer=optimizer)
                self._assert_finite_train_state("after backward")
                preflight_finite_gradients(
                    optimizer, self.named_parameters(),
                    cache_for_step=hasattr(
                        optimizer, "_step_without_finite_preflight"))
                if self.ergodic:
                    self.paramUpdate()
                optimizer.step()
                _fineweb_step_performed = True
            self._project_sentence_parameters()
            self._assert_finite_train_state("after optimizer.step")
            # The episode credit boundary (spec 8.2): durable LTM detaches
            # here, after the one optimizer step of the episode.
            self._end_what_episodes()
            self._flush_partspace_promotions(optimizer=optimizer)
            self._clamp_symbolic_codebook()
            # 2026-05-28: enforce the |W| <= 1 invariant on the
            # Embedding (Lexicon) by re-projecting rows onto the unit
            # ball after each optimizer step. Matches the SBOW
            # pre-training pattern at bin/embed.py:1976. Without this,
            # JOINT training drifts Embedding rows beyond [-1, 1]
            # (measured: |W|.max ~ 1.54 after 200 epochs on XOR_exact),
            # which breaks the nearest-Embedding reverse decode -- the
            # bounded recon vector from pi.reverse cannot reach the
            # unbounded target rows.
            self._normalize_perceptual_embedding()
            self._advance_codebook_parameter_versions()
            # Sentence updates never advance this public batch counter.
            if record_trial:
                self._training_step_count = (
                    int(getattr(self, "_training_step_count", 0) or 0) + 1
                )
                from LearningEvaluation import record_fineweb_training
                if _fineweb_step_performed:
                    record_fineweb_training(self, split=split, source_rows=source_rows)
        else:
            # The eager lexical stem may discover promotions during no-grad
            # inference too. The completed forward is its graph-safe boundary;
            # install now so the next request can use the promoted row.
            self._flush_partspace_promotions(optimizer=None)

        result = self.BatchResult(
            outputPred=outputDataPred,
            symbols=symbols,
            lossOut=lossOut,
            lossIn=lossIn,
            inputPred=inputDataPred,
            forwardInput=forwardInput,
        )
        # Spec names for the two primary costs (``primary_costs()``); the
        # legacy lossOut/lossIn fields stay for existing callers.
        self._last_primary_costs = {
            **(getattr(self, "_last_primary_costs", None) or {}),
            "input_reconstruction": lossIn,
            "answer_construction": lossOut,
        }
        # Pure compute brick: no Reset, no truth-layer compact, no host
        # sync inside runBatch. The outer doc-streaming loop in runEpoch
        # (or any per-tick driver) is responsible for:
        #   * Hard reset (per-row, on document boundary) via
        #     ``BasicModel.dispatch_per_row_reset(hard_eos_list)``.
        #   * Soft reset (per-row, on grammar sentence completion) via
        #     ``symbolSpace.drain_sentence_completed()`` →
        #     ``symbolSpace.soft_reset(b)``.
        #   * ``truth_layer.compact()`` (one host sync per tick, kept
        #     outside the brick).
        # See doc/plans/2026-04-26-rolling-cursor-doc-streaming-handoff.md.

        # Memory-leak diagnostics (perf-notes/08-*). Three independently
        # gated probes; each is a no-op without its env var.
        if os.environ.get("BASIC_PROFILE_DIAG"):
            try:
                ss_diag = self.symbolSpace
                tl_diag = getattr(ss_diag, 'truth_layer', None) if ss_diag is not None else None
                if tl_diag is not None and hasattr(tl_diag, 'count'):
                    tl_count_diag = int(tl_diag.count.item())
                    tl_pending_diag = int(getattr(tl_diag, '_pending_count', 0))
                else:
                    tl_count_diag = 0
                    tl_pending_diag = 0
                if torch.cuda.is_available():
                    cuda_alloc_mb = torch.cuda.memory_allocated() / (1024 * 1024)
                    cuda_max_mb = torch.cuda.max_memory_allocated() / (1024 * 1024)
                else:
                    cuda_alloc_mb = 0.0
                    cuda_max_mb = 0.0
                opt_state_numel = 0
                if optimizer is not None:
                    for st in optimizer.state.values():
                        for v in st.values():
                            if torch.is_tensor(v):
                                opt_state_numel += v.numel()
                word_lens_diag = {}
                for sp in self.spaces:
                    sub = getattr(sp, 'subspace', None)
                    if sub is not None and hasattr(sub, 'word'):
                        word_lens_diag[sp.__class__.__name__] = len(sub.word)
                pair_counts_diag = {}
                for sp in self.spaces:
                    cl = getattr(sp, 'chunkLayer', None) or getattr(sp, 'chunk_layer', None)
                    if cl is not None:
                        pair_counts_diag[sp.__class__.__name__] = (
                            len(getattr(cl, '_pair_counts', {})),
                            len(getattr(cl, '_unigram_counts', {})),
                        )
                TheMessage(
                    f"[diag] batch={batchNum} tl={tl_count_diag}/{tl_pending_diag} "
                    f"cuda_alloc_mb={cuda_alloc_mb:.1f} cuda_max_mb={cuda_max_mb:.1f} "
                    f"opt_state_numel={opt_state_numel} word_lens={word_lens_diag} "
                    f"chunk_pair_uni={pair_counts_diag}"
                )
            except Exception as _diag_exc:
                TheMessage(f"[diag] batch={batchNum} diag_error={_diag_exc!r}")

        if os.environ.get("BASIC_PROFILE_LEAK") and torch.cuda.is_available():
            if batchNum >= 96 and not getattr(self, "_leak_recording", False):
                torch.cuda.memory._record_memory_history(
                    enabled="all", context="all", stacks="python",
                    max_entries=400_000)
                self._leak_recording = True
                TheMessage(f"[leak] start recording at batch {batchNum}")
            elif batchNum >= 160 and getattr(self, "_leak_recording", False):
                _leak_dir = os.path.expanduser("~/WikiOracle/basicmodel/perf-notes")
                os.makedirs(_leak_dir, exist_ok=True)
                out = os.path.join(_leak_dir, "08-leak-snapshot.pkl")
                try:
                    torch.cuda.memory._dump_snapshot(out)
                    TheMessage(f"[leak] dumped snapshot to {out} at batch {batchNum}")
                except Exception as _leak_exc:
                    TheMessage(f"[leak] dump failed: {_leak_exc!r}")
                torch.cuda.memory._record_memory_history(enabled=None)
                self._leak_recording = False

        if os.environ.get("BASIC_PROFILE_TENSORS") and torch.cuda.is_available():
            import gc as _gc, collections as _coll
            counts = _coll.Counter()
            for obj in _gc.get_objects():
                try:
                    if isinstance(obj, torch.Tensor) and obj.device.type == "cuda":
                        counts[(tuple(obj.shape), str(obj.dtype))] += 1
                except Exception:
                    continue
            prev = getattr(self, "_leak_prev_counts", None)
            if prev is not None:
                keys = set(counts) | set(prev)
                deltas = sorted(
                    ((k, counts.get(k, 0) - prev.get(k, 0)) for k in keys
                     if counts.get(k, 0) != prev.get(k, 0)),
                    key=lambda kv: -abs(kv[1]))
                top = ", ".join(f"{k[0]}/{k[1]}:{d:+d}" for k, d in deltas[:8])
                TheMessage(f"[tensors] batch={batchNum} top deltas: {top}")
            self._leak_prev_counts = dict(counts)

        # Clear per-batch IR scratch so the next batch's
        # create_ir_mask starts from a clean slate (no stale mask /
        # pre-mask tensor pinned in GPU memory).
        self._ir_mask_positions = None
        self._ir_pre_mask_input = None

        self.End()
        return result, batchNum

    def _clear_recall_history(self, rows=None):
        history = self.__dict__.get("_what_recall_history")
        if not history:
            return
        if rows is None:
            history.clear()
            return
        for b in rows:
            history.pop(int(b), None)

    def dispatch_per_row_reset(self, hard_eos):
        """Fire per-row hard Reset on rows whose ``hard_eos[b]`` is True.

        Called by the outer doc-streaming loop after ``runBatch`` returns.
        ``hard_eos`` is the host-side ``list[bool]`` from
        ``SentenceStreamDataset.next_tick``; rows with True consumed the
        last bytes of their current document this tick and need a full
        per-row state wipe before the next document starts.

        Fast-path: when every row is True (the legacy DataLoader contract,
        and also the common cursor case where all rows finish a doc on
        the same tick), collapse to a single global ``space.Reset()`` per
        space — one call instead of B. That keeps the dispatch overhead
        at parity with the pre-handoff legacy path while preserving the
        per-row capability for the partial-eos cursor case.

        Otherwise, cascades ``space.Reset(batch=b, hard=True)`` over
        every Reset-capable space. Every Reset accepts the per-row
        signature now (the §8d legacy zero-arg fallback was removed).
        """
        try:
            self._clear_recall_history(
                [b for b, flag in enumerate(hard_eos) if flag]
                if hard_eos else None)
        except TypeError:
            self._clear_recall_history()
        if not hard_eos:
            return
        if all(hard_eos):
            # Legacy-parity hot path (L6 in the handoff): a single
            # global Reset per space when every row finishes a doc on
            # the same tick (the common DataLoader case). Keeps the
            # dispatch overhead at parity with the pre-handoff path
            # while preserving the per-row capability for partial-eos.
            for space in self.spaces:
                if hasattr(space, 'Reset'):
                    space.Reset()
        else:
            for b, done in enumerate(hard_eos):
                if not done:
                    continue
                for space in self.spaces:
                    if hasattr(space, 'Reset'):
                        space.Reset(batch=b, hard=True)
        # Clear the per-row eos diagnostic. ``_end_of_stream`` is a
        # host-side ``list[bool]`` post-§8c; resize lazily if the cursor
        # batch grew beyond the AR forward()'s previous sizing.
        eos = self.inputSpace._end_of_stream
        if len(eos) < len(hard_eos):
            eos.extend([False] * (len(hard_eos) - len(eos)))
        for b, done in enumerate(hard_eos):
            if done:
                eos[b] = False

    def dispatch_soft_reset(self):
        """Drain ``symbolSpace._sentence_completed`` and fire per-row soft reset.

        Called by the outer doc-streaming loop after ``runBatch`` returns
        (and *after* ``dispatch_per_row_reset`` so a hard-reset row's soft
        signal is dropped — hard subsumes soft).
        """
        ss = self.symbolSpace
        if ss is None or not hasattr(ss, 'drain_sentence_completed'):
            return
        completed = ss.drain_sentence_completed()
        for b in completed:
            ss.soft_reset(batch=b)

    def dispatch_packed_soft_reset(self, hard_eos=None):
        """Soft-reset rows whose final packed sentence completed this brick.

        Intermediate sentences were reset functionally inside CSLang. The
        final sentence must remain available through reconstruction,
        discourse loss, backward, and contextual updates; this eager boundary
        clears it afterwards. Rows receiving a simultaneous hard EOS are
        skipped because the subsequent hard-reset dispatch subsumes the soft
        reset.
        """
        isp = getattr(self, "inputSpace", None)
        counts = tuple(getattr(
            isp, "_packed_sentence_counts_host", ()) or ())
        if not bool(getattr(isp, "_sentence_pack_enabled", False)) or not counts:
            return
        hard = list(hard_eos or [False] * len(counts))
        if len(hard) < len(counts):
            hard.extend([False] * (len(counts) - len(hard)))
        for b, count in enumerate(counts):
            if int(count) < 1 or bool(hard[b]):
                continue
            for space in self.spaces:
                if hasattr(space, "Reset"):
                    space.Reset(batch=b, hard=False)

    def post_tick_compact(self):
        """Run post-tick host work: truth-layer compaction.

        Lives outside the compute brick so the brick body remains
        sync-free. Called once per tick by the outer doc-streaming loop
        after ``runBatch`` returns.

        Also severs any cross-batch autograd graph carried by persistent
        state (``SymbolSpace._last_svo``; Basis transient
        activations in ``_active_payload`` / non-Parameter ``W``; all
        floating-point registered buffers). In-place writes during the
        brick's forward leave persistent attributes wired to that
        batch's autograd graph; once ``backward()`` runs and the saved
        tensors are freed, the next batch's forward re-reads the same
        attributes and the next ``backward()`` walks into freed nodes
        ("Trying to backward through the graph a second time"). This
        hook runs in eager Python every tick after ``backward()``, so
        ``self.modules()`` iteration is safe here (it would graph-break
        if placed inside a traced reset path).
        """
        ss = self.symbolSpace
        if ss is not None:
            tl = getattr(ss, 'truth_layer', None)
            if tl is not None and hasattr(tl, 'compact'):
                tl.sync_from_ltm()
        self._detach_persistent_state()

    def _detach_persistent_state(self):
        """Walk every submodule under this model and detach the floats
        that carry cross-batch autograd edges. See ``post_tick_compact``
        for the full rationale.

        Touches:
          * registered buffers (``self.buffers()``)
          * Basis ``_active_payload`` (transient activations stored when
            ``W`` is a learned Parameter)
          * Basis ``W`` (when ``W`` is a plain tensor, i.e. not an
            ``nn.Parameter``)
          * Model-level cached state tensors that don't live as buffers
            (``InputSpace._ar_embedded``, ``inputSpace._embedded_input``,
            spaces' ``_embedded_input``).
        """
        # 1. All registered FP buffers in the model tree.
        for buf in self.buffers():
            if buf.is_floating_point():
                buf.detach_()
        # 2. Plain-tensor W on every submodule (the ``_active_payload``
        # shadow was retired Stage 4 of
        # doc/plans/2026-05-21-active-payload-retirement.md; per-batch
        # content for codebook-bearing slots now reconstructs via
        # ``SubSpace.materialize`` from prototype + selection).
        for mod in self.modules():
            w = getattr(mod, 'W', None)
            if (w is not None and torch.is_tensor(w)
                    and not isinstance(w, nn.Parameter)
                    and w.is_floating_point()):
                mod.W = w.detach()
        # 3. Known plain-attribute tensor caches that ride across batches.
        for sp_attr in ("inputSpace", "perceptualSpace",
                        "conceptualSpace", "wholeSpace", "outputSpace"):
            sp = getattr(self, sp_attr, None)
            if sp is None:
                continue
            for tn in ("_ar_embedded", "_embedded_input",
                       "_cached_embedding"):
                t = getattr(sp, tn, None)
                if t is not None and torch.is_tensor(t) and t.is_floating_point():
                    setattr(sp, tn, t.detach())
        # 4. Serial-arc carriers -- deliberately PLAIN attributes (kept out
        # of buffers/traces), so steps 1-3 miss them; the next batch's
        # forward re-reads each one, chaining the consumed (already
        # optimizer-stepped) graph into its loss ("[1016] at version 1"
        # backward crash, the ladder5 relaunch 2026-07-13).
        def _sever(obj, name):
            t = getattr(obj, name, None)
            if (t is not None and torch.is_tensor(t)
                    and t.is_floating_point() and t.grad_fn is not None):
                object.__setattr__(obj, name, t.detach())

        def _sever_dict(d):
            if isinstance(d, dict):
                for k, v in list(d.items()):
                    if torch.is_tensor(v) and v.grad_fn is not None:
                        d[k] = v.detach()

        for mod in self.modules():
            for tn in ("_live_buffer", "_last_output", "_last_root_state",
                       "_intent_boosts", "_stage0_recon_loss",
                       "_stage0_property_membership"):
                _sever(mod, tn)
            rs = getattr(mod, "routing_state", None)
            if rs is not None:
                _sever(rs, "rule_probs")
            _sever_dict(getattr(mod, "_bind_context", None))
            # Host-layer registry values are host wrappers, not children.
            reg = getattr(mod, "_host_layer_registry", None)
            if isinstance(reg, dict):
                for hl in reg.values():
                    _sever_dict(getattr(hl, "_bind_context", None))
        _sever(self, "_stm_single_S")
        _sever(self, "_packed_sentence_roots")

    def flush_word_buffers(self):
        """Drain the per-subspace tensor word buffers (§6c Path B).

        The chart compose writes per-cell entries into each subspace's
        ``word_records`` / ``word_count`` buffers inside the brick;
        this hook materializes them into the legacy ``subspace.word``
        Python list once per tick so ``decompose``, ``reconstruct``,
        the SVO walker, and derivation-trace tests keep working
        unchanged. One ``.tolist()`` sync per subspace per tick, kept
        outside the brick.
        """
        for space in self.spaces:
            sub = getattr(space, 'subspace', None)
            if sub is None or not hasattr(sub, 'flush_word_buffer'):
                continue
            sub.flush_word_buffer()

    def _stub_outputs(self, B):
        """Per-row sentinel outputs for cursor-mode AR ticks.

        AR training is self-supervised on the input bytes; the
        ``OutputSpace`` only needs a per-row tensor to keep its
        prepOutput signature stable. Returns a list of B zero scalars
        (matches the placeholder created by ``Data.processLM`` when
        labels are absent).
        """
        return [torch.zeros(1) for _ in range(int(B))]

    class _TickPrefetcher:
        """Background-thread prefetch over a dataset cursor callable.

        A *single* worker thread calls ``next_fn`` ahead of the
        consumer and queues the ``(inp_items, out_items, hard_eos)``
        tuple. The main ``runEpoch`` loop pulls from the queue, hiding
        the per-tick CPU cost behind GPU compute (which releases the
        GIL while in CUDA / C++ kernels).

        Single-threaded by design: ``next_tick`` is Python-bound and
        the GIL serializes Python execution, so additional threads
        would contend without speedup. The XML ``<numWorkers>`` knob
        therefore controls *queue depth* (in-flight tick budget),
        not thread count. Queue depth = ``queue_size``: at most one
        tick consumed by main + ``queue_size - 1`` buffered ahead.

        The cursor callable is safe to call from this worker because it is a
        pure state machine over ``ds``'s internal cursor: no main-
        thread feedback, no shared mutable state outside ``ds``.
        """

        _SENTINEL = object()

        def __init__(self, ds, queue_size, next_fn=None, done_fn=None):
            """Spawn the prefetch worker and size the bounded queue.

            ``queue_size`` of N permits up to N-1 in-flight ticks buffered
            ahead of the consumer. The worker is a daemon thread so it
            does not block process exit on abrupt termination.
            """
            from queue import Queue
            from threading import Thread, Event
            self._ds = ds
            self._next_fn = next_fn or ds.next_tick
            self._done_fn = done_fn or ds.all_done
            self._queue = Queue(maxsize=max(1, int(queue_size)))
            self._stop = Event()
            self._exc = None
            self._thread = Thread(
                target=self._produce, name="TickPrefetcher", daemon=True)
            self._thread.start()

        def _produce(self):
            """Worker loop: call ``ds.next_tick`` and enqueue results.

            Honours the ``_stop`` event, captures any exception into
            ``_exc`` so the consumer can re-raise it, and always enqueues
            ``_SENTINEL`` on exit so the consumer doesn't deadlock.
            """
            try:
                while not self._stop.is_set() and not self._done_fn():
                    tick = self._next_fn()
                    # Capture provenance at the same cursor step. The producer
                    # may advance several ticks before the consumer runs, so
                    # reading ``ds.last_source_indices`` later would attach the
                    # wrong objective Teacher address.
                    queued = (
                        tick,
                        copy.deepcopy(getattr(
                            self._ds, "last_source_indices", None)),
                    )
                    while not self._stop.is_set():
                        try:
                            self._queue.put(queued, timeout=0.1)
                            break
                        except Exception:
                            continue
            except BaseException as e:
                self._exc = e
            finally:
                # Normal exhaustion often arrives while every bounded slot is
                # occupied by prefetched ticks. A one-shot timed put can then
                # expire before the consumer finishes its current GPU brick;
                # after draining those ticks it waits forever because no
                # exhaustion marker exists. Keep offering the sentinel until
                # the consumer makes room. ``close()`` sets ``_stop`` first,
                # in which case no marker is needed and the daemon can exit.
                while not self._stop.is_set():
                    try:
                        self._queue.put(self._SENTINEL, timeout=0.1)
                        break
                    except Exception:
                        continue

        def next(self):
            """Return next tick, ``None`` when the dataset is exhausted.
            Re-raises any exception that the worker hit."""
            item = self._queue.get()
            if item is self._SENTINEL:
                if self._exc is not None:
                    raise self._exc
                return None
            return item

        def close(self):
            """Signal stop, drain the queue, and join the worker.

            Bounded ``thread.join`` with a 2s timeout so a stuck worker
            can't block process exit indefinitely.
            """
            self._stop.set()
            while not self._queue.empty():
                try:
                    self._queue.get_nowait()
                except Exception:
                    break
            self._thread.join(timeout=2.0)

    def runEpoch(self, optimizer=None, batchSize=10, split="train",
                 max_batches=None):
        """Run one epoch over the dataset (training if optimizer given, eval if None).

        Drives batching with a ``SentenceStreamDataset`` DataLoader so every
        split is consumed as ``B = batchSize`` contiguous streams. ``B`` is
        capped at ``len(split)`` by ``data_loader``, so small eval sets
        degrade gracefully.

        Interleaving instead stages complete N-sentence groups in corpus
        order and consumes them in serial batches up to ``batchSize``.

        ``max_batches`` (optional int): cap the outer cursor loop at this
        many ``runBatch`` calls. ``None`` (default) walks the full split.
        Used by ``--test N`` to bound the test-pass cost on large
        corpora; the bound applies to whichever split this call drives.

        Inference (split="runtime", no optimizer) shares the data-driven loop
        with the eval splits (training=False): it drives the data
        ``runtime_batch`` staged into ``train_input`` (via
        ``data_loader(split="runtime")``) through ``runBatch(train=False)``
        with a real ``batch_override``. Training-only work (loss/backward,
        CBOW, two-pass) is gated on ``training`` and skipped.

        Args:
            optimizer: pre-built Adam optimizer (persistent across epochs).
                       Pass None for evaluation mode.
            batchSize: requested batch size (capped by split length).
            split: "train", "test", or "validation"

        Returns (output_loss, reconstruction_loss, all_predictions, last_reconstruction).
        """
        training = optimizer is not None

        # LTM consolidation FU (Change 3, 2026-06-18): provision the unified
        # LTM from the XML <truthSet> LAZILY at the first runEpoch -- by which
        # point the dataset is loaded, so provision_ltm can run the truth
        # texts through the REAL forward. Guard with ``_ltm_provisioned`` set
        # True BEFORE provisioning so the inner runEpoch (split="runtime")
        # provision_ltm fires does NOT recurse. No-op (and the flag flips
        # harmlessly) when the gate is off / no <truthSet> -- byte-identical.
        if not getattr(self, '_ltm_provisioned', True):
            self._ltm_provisioned = True
            if getattr(self, 'ltm_consolidation', False):
                self.provision_ltm()

        self.train(training)
        self.outputSpace.clearBatchResults()
        ss = self.symbolSpace
        if ss is not None and getattr(ss, 'expectation', None) is not None:
            ss.expectation.reset()
            ss.expectation.reset_expectation_metrics()
        if ss is not None and getattr(ss, 'what_memory', None) is not None:
            ss.what_memory.reset()
        ctx = torch.no_grad() if not training else nullcontext()

        # Runtime / inference (split="runtime", no optimizer) shares the
        # normal data-driven loop below with the eval splits (training=False):
        # ``data_loader(split="runtime")`` serves the data ``runtime_batch``
        # staged into ``train_input``, the cursor builds a real per-tick
        # ``batch_override``, and ``runBatch(train=False)`` runs the forward
        # (which records supplied truths with external provenance). The previous
        # bespoke fast-path called ``runBatch`` WITHOUT a batch_override (the
        # retired ARIR/arir_step entry), so EVERY ``runEpoch(split="runtime")``
        # raised "no batch_override supplied" -- ``store_truths``' documented
        # ingestion path. Falling through reuses the correct cursor + per-row
        # reset + tail dispatch; record()/accumulation is negligible for the
        # small runtime ingestion.

        allOutput = []
        allInput = []
        outputChunks = []
        inputChunks = []
        outErr = 0.0
        inErr = 0.0

        def record(result):
            """Book-keep one runBatch result into the shared accumulators.

            Updates ``outErr`` / ``inErr`` from the result's loss tensors
            (kept 0-dim to avoid a GPU sync). Appends per-batch
            prediction clones into ``outputChunks`` / ``inputChunks``
            only during eval -- training discards them.
            """
            nonlocal outErr, inErr
            # Note: do NOT call outputSpace.putBatch(result).  The list it
            # would append to has no readers, and each BatchResult retains
            # ~one batch of detached tensors -- a per-batch growth of
            # ~17 MB measured on MM_20M, accumulating over the epoch.
            #
            # Keep losses as 0-dim tensors here; .item() is a GPU sync.
            # The epoch-end return path materializes scalars exactly once.
            if result.lossOut is not None:
                outErr = result.lossOut.detach()
            if result.lossIn is not None:
                inErr = result.lossIn.detach()
            # Only the eval path (split in {test, validation, runtime})
            # reads ``allOut``/``allIn`` -- the train caller at runTrial
            # line ~2016 destructures and immediately discards them. So
            # accumulating per-batch outputPred clones during training was
            # pure overhead: ~0.5 MB / runBatch on MM_20M, growing across
            # the entire epoch.
            if not training:
                outputChunks.append(result.outputPred.clone().detach().squeeze())
                if self.reversible and result.inputPred is not None:
                    inputChunks.append(result.inputPred.clone().detach().squeeze())

        # Data splits live on CPU (see Data.toDevice); prepInput/prepOutput
        # move per-batch to device in the main process, so workers just
        # pickle CPU tensors. XML <numWorkers> sets _num_workers via
        # ModelFactory.run; the default lives in data/model.xml.
        num_workers = self._num_workers

        # Cursor universal (§8e). Two cursor modes share one outer loop:
        #
        #   * **Byte cursor** (AR text byte): each row's document is
        #     walked one ``slab_bytes``-wide tick at a time;
        #     ``hard_eos[b]`` flips True when row b crosses a doc
        #     boundary. Sized to ``nIdeas - 1`` so the lex's reserved
        #     EOS-sentinel slot stays byte-faithful.
        #   * **Trial cursor** (numeric / non-AR / non-byte): each tick
        #     yields one batch of trials with ``hard_eos = [True] * B``.
        #     The data cursor aligns with the trial: each tick is one
        #     atomic data unit per row (MNIST image, XOR sample,
        #     non-AR sentence). Per-row Reset fires for every row each
        #     tick, mirroring the pre-handoff DataLoader contract.
        text_input = (
            isinstance(self.inputSpace.data.train_input, list)
            and len(self.inputSpace.data.train_input) > 0
            and isinstance(self.inputSpace.data.train_input[0], str)
        )
        byte_lexer = getattr(self, 'lexer', None) in ('byte', 'bytes')
        use_byte_cursor = text_input and byte_lexer
        use_packed_cursor = bool(
            training
            and split == "train"
            and text_input
            and not byte_lexer
            and getattr(self, "pack_sentences", False)
            and getattr(self, "_tensor_peer_while_enabled", False)
            and int(getattr(self, "serial_word_capacity", 0) or 0) > 0)

        if use_byte_cursor:
            # InputSpace.outputShape[0] (= ``nIdeas``) is the byte-buffer
            # width the lex emits. Under the §8g/§EOS-removal change
            # the lex no longer reserves a slot for an EOS sentinel
            # (the slot held a null-embedding indistinguishable from
            # the codebook's null padding -- no reader consumed it as
            # a stop signal). Sizing the slab to ``nIdeas`` keeps the
            # cursor byte-faithful through the lex: every byte emitted
            # ends up in a real token, and the assert in
            # ``InputSpace._lex_batch`` (``n_tokens <= nIdeas``) holds
            # exactly under the bytes-mode parse fix that produces one
            # token per input byte.
            slab_bytes = max(1, int(self.inputSpace.outputShape[0]))
        else:
            slab_bytes = None           # trial cursor (one tick = one trial)

        # The runEpoch outer loop drives ``ds.next_tick()`` directly
        # for both modes; the surrounding ``DataLoader`` is built only
        # so existing tests can grab ``loader.dataset``. PyTorch's
        # ``num_workers`` is forced to 0 because the loader is never
        # iterated -- async workers would prefetch tensors no one
        # consumes. Parallel feed is provided by ``_TickPrefetcher``
        # below (see XML ``<numWorkers>``), which calls ``next_tick``
        # on a single background thread.
        loader = self.inputSpace.data.data_loader(
            split=split,
            num_streams=batchSize,
            num_workers=0,
            prefetch_factor=None,
            pin_memory=(TheDevice.get().type == "cuda"),
            slab_bytes=slab_bytes,
        )
        ds = loader.dataset
        B_eff = ds.num_streams

        packed_next = None
        packed_done = None
        if use_packed_cursor:
            if getattr(self.inputSpace.data,
                       "has_supervised_outputs", False):
                raise ValueError(
                    "packed sentence training currently requires a "
                    "self-supervised text corpus")
            import Meronomy

            self._install_unit_span_fn()

            def _packed_word_count(sentence):
                # Units as the sentence sits in a brick (its joining space
                # included), so bricks are budgeted in the loop's own units.
                return self.inputSpace.sentence_unit_count(
                    sentence, trailing_space=True)

            packed_next = partial(
                ds.next_packed_tick,
                int(self.serial_word_capacity),
                _packed_word_count,
                max_bytes=int(self.inputSpace.data.inputLength),
                max_sentences=(
                    self.inputSpace.packed_sentence_slot_capacity()))
            packed_done = ds.packed_done

        # A mid-epoch checkpoint contains the update state *after* the saved
        # number of cursor ticks. Recreate the deterministic cursor and skip
        # those ticks before resuming updates. A different stream count would
        # map rows to different ticks, so fail loudly instead of silently
        # replaying or omitting training examples.
        resume_skip = 0
        if training and split == "train":
            resume_skip = int(getattr(
                self, "_resume_batches_to_skip", 0) or 0)
            saved_batch_size = getattr(
                self, "_checkpoint_batch_size", None)
            if (resume_skip and saved_batch_size is not None
                    and int(saved_batch_size) != int(batchSize)):
                raise ValueError(
                    "Cannot resume a mid-epoch checkpoint with a different "
                    f"batch size (saved={saved_batch_size}, "
                    f"requested={batchSize})")

        # Async tick prefetch. ``<numWorkers>`` becomes the in-flight
        # tick budget (1 tick consumed by main + N-1 buffered). 0
        # preserves the legacy synchronous path.
        prefetcher = (
            BasicModel._TickPrefetcher(
                ds, queue_size=num_workers,
                next_fn=packed_next if use_packed_cursor else None,
                done_fn=packed_done if use_packed_cursor else None)
            if num_workers > 0 else None)

        # Pre-build the AR stub outputs once for the byte-cursor path
        # (every tick reuses them; the AR target is the input bytes).
        if use_byte_cursor:
            byte_stub_output = self.outputSpace.prepOutput(
                self._stub_outputs(B_eff))
        else:
            byte_stub_output = None
        packed_stub_output = (
            self.outputSpace.prepOutput(self._stub_outputs(B_eff))
            if use_packed_cursor else None)

        # BASIC_MAX_BATCHES caps the cumulative training-batch count
        # across all epochs (train.py forwards --batches here).
        # split=="train" only -- test/validation passes use the
        # explicit ``max_batches`` arg from --test.
        global_max = None
        if (training and split == "train"
                and not getattr(self, "_preflight_active", False)):
            # The brick pre-flight runs bounded throw-away epochs; they
            # must NOT consume (or be capped by) the BASIC_MAX_BATCHES
            # ``--batches`` budget, or the warm-up eats it all and the
            # profiled epoch + real training run zero batches.
            try:
                _v = os.environ.get("BASIC_MAX_BATCHES", "").strip()
                global_max = int(_v) if _v else None
            except ValueError:
                global_max = None
            if not hasattr(self, "_train_batches_seen"):
                self._train_batches_seen = 0
        with ctx:
            step = 0
            batches_run = 0
            packed_sentences_run = 0
            self.reset_word_unit_stats()
            epoch_started = time.monotonic()
            while True:
                deadline = getattr(
                    self, "_training_deadline_monotonic", None)
                if (training and split == "train"
                        and not getattr(self, "_preflight_active", False)
                        and deadline is not None
                        and time.monotonic() >= float(deadline)):
                    self._training_deadline_reached = True
                    TheMessage(
                        f"runEpoch({split}): hit BASIC_MAX_SECONDS after "
                        f"{batches_run} completed batches this epoch; "
                        "cursor exiting before the next tick.")
                    break
                if max_batches is not None and batches_run >= max_batches:
                    TheMessage(
                        f"runEpoch({split}): hit max_batches={max_batches} "
                        f"cap; cursor exiting early ({batches_run} batches "
                        f"processed, ds.all_done={ds.all_done()}).")
                    break
                if (global_max is not None
                        and self._train_batches_seen >= global_max):
                    TheMessage(
                        f"runEpoch({split}): hit BASIC_MAX_BATCHES="
                        f"{global_max} cumulative cap; cursor exiting "
                        f"early ({batches_run} batches this epoch, "
                        f"{self._train_batches_seen} total).")
                    break
                if prefetcher is not None:
                    queued_tick = prefetcher.next()
                    if queued_tick is None:
                        break
                    tick, source_rows = queued_tick
                    inp_items, out_items, hard_eos = tick
                else:
                    cursor_done = (
                        packed_done() if use_packed_cursor else ds.all_done())
                    if cursor_done:
                        break
                    if use_packed_cursor:
                        inp_items, out_items, hard_eos = packed_next()
                    else:
                        inp_items, out_items, hard_eos = ds.next_tick()
                    source_rows = copy.deepcopy(getattr(
                        ds, "last_source_indices", None))
                if resume_skip > 0:
                    resume_skip -= 1
                    self._resume_batches_to_skip = resume_skip
                    continue
                packed_batch_sentences = 0
                if use_byte_cursor:
                    # Byte slab: convert uint8 -> int8 [B, 1, slab_bytes]
                    # to match prepInput's expected shape downstream.
                    # Synchronous H2D: correct + race-free (non_blocking
                    # on an ephemeral pinned buffer corrupts data when
                    # freed pre-transfer -- the NaN source).
                    inputTensor = inp_items.to(
                        device=TheDevice.get(), dtype=torch.int8
                    ).unsqueeze(1)
                    # Hand the *host* slab to the lexer (consumed once in
                    # InputSpace._lex_batch). `inputTensor` is exactly
                    # `inp_items.to(device,int8).unsqueeze(1)`, so the
                    # bytes are identical (_to_text masks `& 0xFF`, so
                    # int8/uint8 agree); lexing the host copy makes
                    # `_to_text`'s `.tolist()` a CPU op instead of a
                    # cudaMemcpyDtoH (residual A, doc/BrickHostSyncStatus
                    # .md). Device path stays the fallback for non-cursor
                    # callers.
                    self.inputSpace._host_input_slab = inp_items
                    outputTensor = byte_stub_output
                    B_step = B_eff
                elif use_packed_cursor:
                    packed_batch_sentences = sum(
                        len(row) for row in inp_items)
                    if packed_batch_sentences < 1:
                        raise RuntimeError(
                            "packed cursor emitted no live sentences")
                    inputTensor = self.inputSpace.prepPackedInput(inp_items)
                    outputTensor = packed_stub_output
                    B_step = B_eff
                else:
                    # Trial mode: caller supplies raw inputs/outputs;
                    # prepInput / prepOutput stage them onto device.
                    B_step = (inp_items.shape[0]
                              if isinstance(inp_items, torch.Tensor)
                              else len(inp_items))
                    inputTensor = self.inputSpace.prepInput(inp_items)
                    outputTensor = self.outputSpace.prepOutput(out_items)

                teacher = getattr(self, "teacher", None)
                if teacher is not None:
                    teacher.stage_batch_sources(split, source_rows)

                # Unified path: AR modes drive their outer pos loop
                # inside BasicModel.forward() via the sliding-window
                # buffer on InputSpace; non-AR modes run one pass. See
                # basicmodel/doc/specs/2026-04-20-streaming-ar-training-loop-design.md
                #
                # ``progress`` (cursor's doc-fraction completed) lets
                # ``runBatch`` print a percent next to its ``batch =``
                # line so long runs report visible progress. Cap at the
                # ``max_batches`` slice when set so a capped pass shows
                # 100% at its own completion rather than the underlying
                # cursor's fraction.
                if max_batches is not None and max_batches > 0:
                    cap_frac = (batches_run + 1) / float(max_batches)
                    progress_frac = min(1.0, cap_frac)
                else:
                    progress_frac = ds.progress() if hasattr(ds, 'progress') else None
                # Trial-split: a deterministic fraction of TRAINING batches run
                # as pure next-idea PREDICTION trials (recon terms zeroed); the
                # rest reconstruct. Bresenham-style ratio (no RNG -> no test
                # flakiness); ratio 0 -> always "reconstruct" -> byte-identical.
                # Decided ONCE per sentence so both two-pass passes agree.
                _ptr = float(getattr(self, 'prediction_trial_ratio', 0.0) or 0.0)
                _trial_mode = ("predict"
                               if (training and _ptr > 0.0
                                   and int((step + 1) * _ptr) != int(step * _ptr))
                               else "reconstruct")
                # What curriculum (Step 9): a deterministic fraction of
                # training batches ask past/future (temporal) or inference
                # questions instead of the default family; distance grows
                # with <whatCurriculumDistance>. "none" -> byte-identical.
                _cur_questions = self._curriculum_questions(
                    step, split=split, batch_size=B_step,
                    sentence_index=step, source_rows=source_rows,
                    training=training)
                result, _ = self.runBatch(
                    train=training, batchNum=step,
                    batchSize=B_step, split=split,
                    optimizer=optimizer,
                    batch_override=(inputTensor, outputTensor),
                    progress=progress_frac,
                    questions=_cur_questions,
                    trial_mode=_trial_mode,
                    source_rows=source_rows,
                )
                if result is not None:
                    record(result)
                # Training record() retains no BatchResult tensors. Release
                # the graph-attached outputs before the next brick so the
                # preceding forward tape cannot overlap the next forward's
                # while-loop allocation. The benchmark already enforced this
                # boundary explicitly; the production cursor must match it.
                del result
                # Tail dispatch: word-buffer flush (§6c Path B), per-row
                # hard reset, soft reset, then the truth-layer compact
                # -- all live outside runBatch under the rolling-cursor
                # compute-brick contract. Flush runs first so the
                # materialized ``subspace.word`` is available to any
                # post-tick consumer the Reset path might touch.
                self.flush_word_buffers()
                if use_packed_cursor:
                    self.dispatch_packed_soft_reset(hard_eos)
                self.dispatch_per_row_reset(hard_eos)
                self.dispatch_soft_reset()
                self.post_tick_compact()
                step += B_step
                batches_run += 1
                packed_sentences_run += packed_batch_sentences
                if (training and split == "train"
                        and not getattr(self, "_preflight_active", False)):
                    self._train_batches_seen += 1
                    self._epoch_batches_seen = int(getattr(
                        self, "_epoch_batches_seen", 0) or 0) + 1
                    self._checkpoint_batch_size = int(batchSize)
                    # Save after the outer cursor count advances so a resumed
                    # checkpoint's progress metadata describes the update it
                    # actually contains, not the preceding batch.
                    self._maybe_save_periodic_checkpoint()

                # Per-batch CBOW/SBOW embedding training for text AR
                # modes that don't use the byte cursor (word/sentence
                # lexer). Byte-cursor path has its own embedding update
                # plumbing inside runBatch.
                if (training and not use_byte_cursor
                        and text_input
                        and isinstance(inp_items, list)
                        and inp_items
                        and (isinstance(inp_items[0], str)
                             or (use_packed_cursor
                                 and isinstance(inp_items[0], list)))):
                    te = getattr(self, 'train_embedding', 'NONE')
                    if te in ('CBOW', 'SBOW', 'BOTH'):
                        method = 'CBOW' if te == 'CBOW' else 'SBOW'
                        sentences = (
                            [sentence for row in inp_items for sentence in row]
                            if use_packed_cursor else inp_items)
                        for sentence in sentences:
                            words = [t for t, _
                                     in parse(sentence, lex='words')]
                            self.perceptualSpace.train_embeddings(
                                words, method=method)

        # Stop the prefetch worker now that the loop is done. The
        # thread is daemon=True so an exception unwinding past this
        # point will not leak a zombie thread; explicit close() lets
        # us reclaim resources promptly on the normal-exit path.
        if prefetcher is not None:
            prefetcher.close()

        cursor_all_done = (
            packed_done() if use_packed_cursor else ds.all_done())
        if not use_packed_cursor and self.word_unit_fraction() is not None:
            # The word-unit assurance also for one-sentence-per-row epochs.
            elapsed = max(1e-9, time.monotonic() - epoch_started)
            TheMessage(
                "Training throughput: "
                f"{batches_run} batches in {elapsed:.3f}s; "
                f"{self._word_unit_report()}.")
        if use_packed_cursor:
            elapsed = max(1e-9, time.monotonic() - epoch_started)
            _wu_text = self._word_unit_report()
            _wu_text = f"; {_wu_text}" if _wu_text else ""
            TheMessage(
                "Packed training throughput: "
                f"{packed_sentences_run} complete sentences in "
                f"{elapsed:.3f}s = "
                f"{packed_sentences_run / elapsed:.3f} sentences/s "
                f"({batches_run} optimizer bricks, "
                f"B={B_eff}, W={self.serial_word_capacity}{_wu_text}).")

        if training and split == "train" and cursor_all_done:
            self._epoch_batches_seen = 0
            self._resume_batches_to_skip = 0

        if inputChunks:
            if outputChunks[0].dim() == 0:
                allInput = torch.stack(inputChunks, dim=0)
            else:
                allInput = torch.cat(inputChunks, dim=0)
        if outputChunks:
            if outputChunks[0].dim() == 0:
                allOutput = torch.stack(outputChunks, dim=0)
            else:
                allOutput = torch.cat(outputChunks, dim=0)

        # Trim eval-pass outputs to the test-split row count.  The
        # byte-cursor's per-stream pacing keeps emitting one row per
        # tick per stream until every stream's data is drained, so
        # streams that finish early contribute trailing padding rows
        # that have no matching ground-truth label.  Post-epoch
        # consumers (``mnistReport``, accuracy plots) align
        # ``allOutput`` against ``model.outputSpace.getTestOutput()``
        # row-for-row; trim to the shorter length so they stay in
        # sync.  Train pass discards both so the trim is eval-only.
        if not training and isinstance(allOutput, torch.Tensor):
            try:
                ref = self.outputSpace.getTestOutput()
                if isinstance(ref, torch.Tensor) and ref.dim() >= 1:
                    target_n = int(ref.shape[0])
                    if allOutput.shape[0] > target_n:
                        allOutput = allOutput[:target_n]
                        if isinstance(allInput, torch.Tensor) and allInput.shape[0] > target_n:
                            allInput = allInput[:target_n]
            except (AttributeError, RuntimeError):
                pass

        # Return the loss scalars as tensors; the caller (runTrial)
        # materializes them with .item(). That keeps the host sync
        # OUTSIDE the brick's profiled runEpoch -- the pre-flight
        # profiles runEpoch directly, and an in-runEpoch .item() is a
        # cudaMemcpyDtoH that breaks the CUDA-graph-capture contract
        # (test_brick_no_sync). Consumers must materialize before any
        # ``:.4f`` format / list-accumulation (see runTrial).
        return outErr, inErr, allOutput, allInput
    def _create_per_stage(self, nInput, nPercepts, nConcepts, nSymbols, nWords=16, nOutput=32,
               bindingDepth=1,
               model_type="numeric", data=None,
               reconstruction_scale=0.5,
               what_scale=0.7, where_scale=0.2, when_scale=0.1,
               **kwargs):
        """Wire the full per-stage space stack from architecture parameters.

        Builds Input / Perceptual / Conceptual stages (one per
        ``bindingDepth`` step) / Symbolic / Output, plus the optional
        SymbolSpace, subsymbolic, and pipeline modules. Mutates ``self``
        extensively (sets every ``self.*Space`` attribute, ``self.spaces``,
        ``self.symbolSpace``, ``self.reversible``, etc.).
        """
        self.spaces = []
        # Execution-only epoch used by immutable carrier/codebook identities.
        # It intentionally does not ride in state_dict: no carrier or replica
        # survives a model rebuild/checkpoint load.
        self._parameter_epoch = 0
        # Serialized model clock (doc/plans/2026-06-07-model-time-when-
        # encoding.md): a 0-initialized ``long`` that increments once per
        # processed batch (train AND inference) in ``runBatch`` and rides
        # ``state_dict()`` through save/load. It is the AUTHORITATIVE absolute
        # time for row timestamps; event .when bands carry source positions.
        # Guarded so a re-entrant build does not re-register the buffer.
        if "when_time" not in self._buffers:
            self.register_buffer(
                "when_time", torch.zeros((), dtype=torch.long))
        self.symbolSpace = None  # wired below once the home spaces exist
        self.reversible = True
        self.nInput = nInput
        self.nPercepts = nPercepts
        self.nConcepts = nConcepts
        # The construction argument is the number of simultaneously live WS
        # locations. Keep that geometry distinct from both the WholeSpace
        # property inventory and the downstream concept-reference inventory.
        self.nSymbolSlots = int(nSymbols)
        self.nOutput = nOutput
        self.nWords = nWords
        self.data = data
        self.model_type = model_type
        # Phase 4b (rev. 2026-06-09): <lexer> lives on WholeSpace
        # (lexing is analytic cutting); IS-side <lexer> rejected loudly.
        from Spaces import resolve_lexer as _resolve_lexer
        self.lexer = _resolve_lexer()
        self.ergodic = TheXMLConfig.get("architecture.ergodic")
        self.processSymbols = TheXMLConfig.get("architecture.processSymbols")
        self.certainty = TheXMLConfig.get("architecture.training.certainty")
        # InputSpace.codebook defaults to false; see the matching note in
        # BasicModel.create.
        self.codebook = Space.normalize_codebook_mode(
            TheXMLConfig.space("InputSpace", "codebook", default=False)) != "none"
        # PartSpace is subsymbolic (2026-06-09 asymmetric-VQ plan §7
        # task 7): its <codebook> element was retired from the schema and PS is
        # hardwired to "none" in Space.__init__. The former
        # ``self.perceptCodebook = TheXMLConfig.space("PartSpace",
        # "codebook")`` read is gone -- it was dead (assigned, never consumed)
        # and would now KeyError on the removed element.
        self.conceptCodebook = TheXMLConfig.space("ConceptualSpace", "codebook")
        # Canonical WS role: an upstream property basis, independent of the
        # concept/symbol namespace. Legacy configs omit the knob and retain the
        # pre-migration construction path until they are converted explicitly.

        self.bindingDepth = bindingDepth
        self.attention_budget = int(TheXMLConfig.get('architecture.attentionBudget',default=32))
        if self.attention_budget < 1:raise ValueError('attentionBudget must be positive')
        self.concept_order_limit = max(0,int(TheXMLConfig.get('architecture.conceptLayers',default=2))-1)

        # Monotonic SigmaLayer weights (W >= 0). Mirrors PiLayer's monotonic
        # flag; when True, invertible SigmaLayers use NonNegativeInvertibleLinearLayer.
        self.monotonic = bool(
            TheXMLConfig.get("architecture.monotonic", default=False))
        # ``useGrammar`` XML knob retired 2026-05-13: derived from the
        # configured grammar instead. See ``_derive_use_grammar``.
        self.useGrammar = self._derive_use_grammar()
        # ``<reconstruct>`` enum retired (A1: schema element +
        # ``reconstructEnum`` removed). C3 (spec sec 7): reconstruction is
        # now UNCONDITIONALLY concepts-seeded in ``runBatch``, so there is
        # no ``self.reconstruct`` attribute and no gate to parse.
        # Gate-L1 sparsity lambda for LiftLayer / LowerLayer raw_gate
        # parameters. 0.0 (default) disables the penalty; configs that
        # use lift/lower opt in via <gateL1Lambda> in <architecture>.
        self.gate_l1_lambda = float(
            TheXMLConfig.get("architecture.gateL1Lambda", default=0.0) or 0.0)
        # Sparse-MoE load-balance loss weight (Shazeer et al. 2017).
        # Currently INERT: read here but has no consumer -- the chart's
        # sparse-MoE load-balance bookkeeping was retired with the chart
        # itself (see ~line 4254), and ``chartTopK`` is retired. The knob
        # stands by for any future signal-router rule load-balancing.
        self.load_balance_weight = float(
            TheXMLConfig.get(
                "architecture.loadBalanceWeight", default=0.0) or 0.0)
        # thoughtFree is structurally equivalent to bindingDepth=0: no
        # higher-order P/C/S cycles. Reject the nonsense combination early.
        TheXMLConfig.require(
            lambda cfg, _ug=self.useGrammar, _co=self.bindingDepth:
                _ug != "thoughtFree" or _co == 0,
            f"useGrammar='thoughtFree' requires bindingDepth=0 "
            f"(got useGrammar={self.useGrammar!r}, "
            f"bindingDepth={self.bindingDepth})"
        )
        # Truth integration config (optional -- absent in BasicModel.xml)
        self.truth_bias_scale = float(TheXMLConfig.get("architecture.truthBiasScale", default=0.1) or 0.1)
        self.luminosity_weight = float(TheXMLConfig.get("architecture.LuminosityWeight", default=0.1) or 0.1)
        self.universality_weight = float(TheXMLConfig.get("architecture.UniversalityWeight", default=0.1) or 0.1)
        # Quaternary-corner balance knobs (see Philosophy.md for
        # the tetralemma/catuskoti mapping). Defaults permit NEITHER
        # (epistemic uncertainty) but forbid BOTH (classical
        # non-contradiction):
        #   allowExcludedMiddle=1  permit NEITHER
        #   allowContradiction=0   forbid BOTH
        self.allow_excluded_middle = int(
            TheXMLConfig.get("architecture.allowExcludedMiddle", default=1) or 1)
        self.allow_contradiction = int(
            TheXMLConfig.get("architecture.allowContradiction", default=0) or 0)
        self.truth_loss_weight = float(TheXMLConfig.training("TruthLoss", default=0.0) or 0.0)
        if float(TheXMLConfig.training("answerLossWeight", default=0.0) or 0.0):
            raise ValueError("answerLossWeight is retired; use selectedThoughtPolicyWeight")
        if float(TheXMLConfig.training("predictNextLossWeight", default=0.0) or 0.0):
            raise ValueError("predictNextLossWeight is retired; use the normal thought policy")
        # Legacy loss knobs migrate into the one hard-choice contract.
        self.thinking_loss_weight = float(TheXMLConfig.training("thinkingLossWeight", default=0.0) or 0.0)
        self.what_thinking_policy_weight = float(TheXMLConfig.training("whatThinkingPolicyWeight", default=0.0) or 0.0)
        self.selected_thought_policy_weight = max(
            float(TheXMLConfig.training("selectedThoughtPolicyWeight", default=0.0) or 0.0),
            self.thinking_loss_weight, self.what_thinking_policy_weight)
        # Method-1 -> Method-2 leaf distillation weight (root separability;
        # snap design doc step 3). 0.0 -> no term -> byte-identical.
        self.leaf_distill_weight = float(
            TheXMLConfig.training("leafDistillWeight", default=0.0) or 0.0)

        # Syntax tree dump — when <writeSyntax>true</writeSyntax> is
        # set in the model XML (under <architecture>), BasicModel.forward
        # writes an XML syntax tree (one per batch row) to syntaxOutPath
        # at the end of each forward pass. See doc/Language.md
        # "POS side-channel" for the format.
        self._write_syntax = bool(TheXMLConfig.get(
            "architecture.writeSyntax", default=False) or False)
        self._syntax_out_path = TheXMLConfig.get(
            "architecture.syntaxOutPath",
            default="output/syntax.xml") or "output/syntax.xml"
        self._syntax_truncated = False

        # --- Dimensional-governance knobs (A1/A2, 2026-06-06) ---
        # ``<reconstruct>`` enum RETIRED (A1, 2026-06-09): the schema element
        # + ``reconstructEnum`` were removed. The retired ``perfect`` mode
        # SKIPPED the per-stage ConceptualCombine (carrier carried unchanged
        # for an exact round-trip). Under ``conceptBinding=mixing`` the
        # surviving learned combine runs unconditionally; ``aligned`` is a
        # separate same-location binder and allocates no ConceptualCombine.
        # No ``self.reconstruct`` / ``self.perfect_reconstruction`` attribute
        # is parsed; binding mode, not reconstruction mode, now selects the
        # appropriate forward/reverse carrier.
        if TheXMLConfig.get("architecture.prediction", default=None) is not None:
            raise ValueError("architecture.prediction is retired: use sentenceExpectation and expectationGain")
        # ``<architecture><sigmaPi>`` (sigmaPiEnum: last|butterfly|full,
        # default "butterfly" at the architecture level per the XSD default).
        # Routed through the same Space.sigma_pi_mode() normalizer used by
        # PartSpace and WholeSpace so the canonical mode string is
        # identical wherever it is read.
        self.sigma_pi_mode = Space.sigma_pi_mode(
            TheXMLConfig.get("architecture.sigmaPi", default="butterfly")
            or "butterfly")

        teacher_data = data if data is not None else TheData
        self.teacher = Teacher(
            teacher_data,
            enabled=bool(TheXMLConfig.training(
                "teacherReconstruction", default=False)),
            context_name=TheXMLConfig.get(
                "architecture.data.contextWhole", default=None),
            errors=TheError,
            loss_kwargs={
                "reconstruction_scale": reconstruction_scale,
                "what_scale": what_scale,
                "where_scale": where_scale,
                "when_scale": when_scale,
                "nOutput": nOutput,
                "bindingDepth": bindingDepth,
                # Loss operates on OutputSpace, which has no subjective
                # where/when bands. Objective corpus addresses remain
                # Teacher metadata and do not enter this event geometry.
                "nWhere": canonical_shape("OutputSpace")[0],
                "nWhen": canonical_shape("OutputSpace")[1],
            },
        )
        # The model owns its data authority, loss registry and loss
        # composition (What spec 12.16); Teacher is an optional adapter for
        # source provenance / lessons / interactive context and may be
        # detached (``model.teacher = None``) without breaking training.
        self.data = teacher_data
        # ``errors`` is a PROPERTY (below): the shared registry must not be an
        # instance attribute, or ``copy.deepcopy(model)`` would recurse into
        # the non-leaf loss tensors another batch left in it (Teacher shields
        # it the same way in its ``__deepcopy__``).
        self.loss = self.teacher.loss
        self.legacy_prediction_enabled = bool(
            self.teacher.legacy_prediction_enabled)
        # Optional swappable loss head fed STM snapshots during the
        # body forward (Phase 3, 2026-05-12). Installed by
        # ``embed.py embed_pretrain`` for CBOW-over-STM pretraining;
        # AR training leaves it None and keeps using ``outputSpace``
        # for the loss.
        self.loss_head = None

        # "6+2+2": config <nDim> is the EVENT width (it EMBRACES the
        # .where/.when band), not the bare content width. Carve the bare CONTENT
        # width ``*_dim = event - band``; downstream shapes restore the event via
        # ``*_dim + obj_*`` (I/O + per-stage shapes), while a bare ``*_dim`` is the
        # content (codebook / C->P feedback / symbol snap). So nWhat == content
        # == nDim - band and the event width == nDim.
        # Helpers _resolve_dim / _obj_size / _nvec live on BaseModel.
        obj_input   = self._obj_size("InputSpace")
        obj_percept = self._obj_size("PartSpace")
        obj_concept = self._obj_size("ConceptualSpace")
        obj_symbol  = self._obj_size("WholeSpace")
        obj_output  = self._obj_size("OutputSpace")

        # Every interior space carries the canonical (nWhere=4, nWhen=4)
        # band, so ``nDim = nWhat + nWhere + nWhen``. PS/WS native WHAT
        # widths may differ from CS: their sparse codebook activation already
        # emits a conceptual-width event before the CS boundary. ``*_dim`` is
        # therefore the native WHAT width of that space, not evidence of a
        # linear PS->WS->CS chain.
        input_event   = self._resolve_dim("InputSpace",      1)
        percept_event = self._resolve_dim("PartSpace", input_event)
        concept_event = self._resolve_dim("ConceptualSpace", percept_event)
        symbol_event  = self._resolve_dim("WholeSpace",   concept_event)
        # The task head consumes terminal CS directly.  An omitted OutputSpace
        # width therefore inherits the conceptual event, not WholeSpace's
        # native property width.
        output_event  = self._resolve_dim("OutputSpace",    concept_event)

        input_dim   = input_event   - obj_input    # = nWhat (InputSpace)
        percept_dim = percept_event - obj_percept  # = nWhat (PartSpace)
        concept_dim = concept_event - obj_concept  # = nWhat (ConceptualSpace)
        symbol_dim  = symbol_event  - obj_symbol   # = nWhat (WholeSpace)
        output_dim  = output_event  - obj_output   # = nWhat (OutputSpace)

        nvec_input   = self._nvec("InputSpace",      nInput)
        nvec_percept = self._nvec("PartSpace", nPercepts)
        nvec_concept = self._nvec("ConceptualSpace", nConcepts)
        nvec_whole_properties = self._nvec("WholeSpace", nSymbols)
        nvec_output  = self._nvec("OutputSpace",     nOutput)
        self.nConceptCodes = int(nvec_concept)
        # Symbols are downstream references into the conceptual inventory;
        # they do not allocate a second learned prototype table. Preserve the
        # historical attribute name for consumers that ask for reference
        # capacity, while spelling out the independent WS property count.
        self.nSymbols = self.nConceptCodes
        self.nWholeProperties = int(nvec_whole_properties)

        # Stage 2: the loopback is always wired -- ConceptualSpace's
        # per-stage input PiLayer is widened by ``symbolShape[1]`` at
        # construction time. No separate XML validator required.

        # Build I/O shape tuples: [count, dim + objectSize]
        inputShape   = [nInput,    input_dim   + obj_input]
        perceptShape = [nPercepts, percept_dim + obj_percept]
        conceptShape = [nConcepts, concept_dim + obj_concept]
        symbolShape  = [nSymbols,  symbol_dim  + obj_symbol]
        outputShape  = [nOutput,   output_dim  + obj_output]

        # Build codebook (space-internal) shape tuples: [nVectors, nDim]
        spaceShape_input   = [nvec_input,   input_dim]
        spaceShape_percept = [nvec_percept, percept_dim]
        spaceShape_concept = [nvec_concept, concept_dim]
        spaceShape_symbol  = [nvec_whole_properties, symbol_dim]
        spaceShape_output  = [nvec_output,  output_dim]

        rawInputShape = [nInput, input_dim]
        self.inputSpace = self._make_input_space(
            rawInputShape, spaceShape_input, inputShape,
            model_type=model_type)

        # Input -> Percept (uses _make_perceptual_space so demuxed
        # configs route to ModalSpace).
        self.perceptualSpace = self._make_perceptual_space(
            inputShape, spaceShape_percept, perceptShape)
        # 2026-06-07: the ``_peer_perceptual`` back-ref (InputSpace -> PS) is
        # RETIRED. InputSpace is a pure RAW lexer and PartSpace owns all
        # tokenization + codebook work; the forward pipeline drives IS.forward
        # then PS.forward, so no back-reference is wired here.

        conceptInputShape = [nPercepts, percept_dim + obj_percept]

        # ConceptualSpace output shape uses the explicit XML values
        # ``<nOutput>`` (already resolved to ``nConcepts`` upstream)
        # and ``<nOutputDim>`` (when supplied) directly. Earlier
        # versions of this code derived N from a volume-preserving
        # ``input_volume // nOutputDim`` formula; that's wrong because
        # the C-space_role codebook can re-dimension between input and
        # output independent of any volume-preservation contract, and
        # because users who set both ``<nOutput>`` and
        # ``<nOutputDim>`` already accounted for the reshape they
        # want. ``nConcepts`` is ``_resolve('ConceptualSpace',
        # nPercepts)`` -- it returns the XML ``<nOutput>`` when set,
        # else falls through to ``nPercepts``.
        try:
            _c_nOutputDim = TheXMLConfig.space("ConceptualSpace", "nOutputDim")
        except KeyError:
            _c_nOutputDim = 0
        if _c_nOutputDim > 0:
            conceptOutputShape = [nConcepts, _c_nOutputDim]
        else:
            conceptOutputShape = [nConcepts, concept_dim + obj_concept]

        # -- Grammar path: progressive bottleneck per conceptual order --
        if self.useGrammar == "all":
            n_stages = self.bindingDepth
            self._level_shapes_list = self._level_shapes(
                nPercepts, percept_dim + obj_percept, n_stages)
        else:
            n_stages = self.bindingDepth
            self._level_shapes_list = None

        # -- Per-stage arrays: independent ConceptualSpace / WholeSpace
        # per stage. The pipeline flows stage-by-stage with no shared
        # per-level views; cross-forward autograd retention vanishes.
        # bindingDepth=0 still needs one stage so the pre-seed C->S
        # pass (test_merged_loop.test_unified_loop_conceptualorder_zero_pre_seed_only)
        # has a concreteSpace/wholeSpace to populate. The j-iteration
        # count reported to runBatch is still the configured value.
        T = max(1, int(n_stages))
        self.conceptualSpaces = nn.ModuleList()
        self.wholeSpaces = nn.ModuleList()
        # A canonical aligned/property-basis model has one unpartitioned
        # conceptual namespace.  Build its large physical Codebook once at
        # stage 0 and hand that module to later folds at construction time.
        # Mixing and legacy WholeSpace models retain per-stage dictionaries.
        _share_concept_dictionary = (
            getattr(self, "concept_binding", "mixing") == "aligned")
        _serial_meta_raw = TheXMLConfig.get(
            "architecture.serialObjectMeta", default=False)
        _serial_meta = (
            _serial_meta_raw if isinstance(_serial_meta_raw, bool)
            else str(_serial_meta_raw or "").strip().lower()
            in ("true", "1", "yes", "on"))
        # Construction precedes the public ``self.word_brackets`` assignment below,
        # so resolve the selector here with the same legacy fallback. Indexed
        # sparse codebook reads are safe only on the canonical word-serial
        # path; a parallel CS has differentiable dense inventory consumers.
        _serial_requested = self._has_word_objects()
        _aligned_codebook_sources = bool(
            _share_concept_dictionary
            and _serial_meta
            and _serial_requested)
        _shared_concept_dictionary = None
        _shared_percept_readout = None
        # Fold provenance is keyed by the same stable concept identities as the
        # shared aligned dictionary.  Keep one host-side registry across every
        # conceptual stage as well: stage 0 resolves/adopts identities, while
        # the production checkpoint envelope is collected from the terminal CS.
        # A shared mapping makes both views authoritative and also means loading
        # the terminal checkpoint view immediately restores stage-0 lookups.
        _shared_concept_fold_support = (
            {} if _share_concept_dictionary else None)
        for t in range(T):
            is_last = (t == T - 1)
            if self.useGrammar == "all":
                # A pass changes attention, not the perceptual dimension.
                n_t = nPercepts
                # In the aligned serial model PS/WS recurse at their native
                # widths, then each rung's sigma/codebook read emits a
                # conceptual-width activation. CS receives that activation;
                # its boundary itself performs no feature-width change.
                d_in = (concept_dim + obj_concept
                        if _aligned_codebook_sources
                        else percept_dim + obj_percept)
                # CS output muxed width = concept_dim + obj_concept, so the CS
                # SubSpace derives nWhat == concept_dim (= nDim) and the event
                # carries where/when. The per-stage codebook content
                # (stage_space_concept) stays bare nDim -- where/when ride as
                # muxed traces, not codebook rows.
                d_out = concept_dim + obj_concept
                cs_in = [n_t, d_in]
                cs_out = [n_t, d_out]
                # WS is BARE concept_dim (the demux target; canonical WS=(0,0)).
                # WS slot count is the PRE-merge stage input ``n_t`` -- NOT the
                # post-merge ``cs_out[0]`` (= ``n_t >> 1`` for non-last stages).
                # The merge runs at the END of a stage and halves the CS that
                # becomes the NEXT stage's input; so the WS at stage ``t``
                # consumes the prior stage's post-merge output, whose slot count
                # is ``nPercepts >> t == n_t`` (this stage's ``cs_in[0]``), and
                # the stage-``t`` merge then takes that same ``n_t`` down to
                # ``n_t >> 1`` for stage ``t+1``.  Sizing the WS (and its square
                # ``sigma`` butterfly, N == ws_in[0] * sigma_dim) at the halved
                # ``cs_out[0]`` made it one power-of-two too small on every
                # non-last stage: a runtime ``n_t``-slot event overflowed the
                # ``n_t>>1``-slot cascade (``butterfly_flatten`` M_total
                # mismatch) the moment the WS sigma fold was live. Last stage:
                # ``cs_out[0] == n_t`` already, so this is unchanged there.
                ws_in = [n_t, concept_dim]
                ws_out = [n_t, concept_dim]
            else:
                # Plain path: all stages share the legacy conceptInputShape /
                # conceptOutputShape. No N-halving.
                cs_in = list(conceptInputShape)
                cs_out = list(conceptOutputShape)
                ws_in = list(conceptOutputShape)
                ws_out = list(symbolShape)

            # dimensional-governance (2026-06-06): WS may RESHAPE the deep CS
            # idea into WIDE symbols -- honor an explicit
            # <WholeSpace><nOutputDim> as the OUTPUT width (e.g. deep
            # [8,1024] -> wide [1024,8] with a small symbol code), DECOUPLED
            # from the codebook/processing width (nDim). Without this the
            # construction sizes the WS output at concept width, ballooning a
            # wide-symbol config. Applies to both grammar and plain paths.
            try:
                _ws_od = int(TheXMLConfig.space("WholeSpace", "nOutputDim"))
            except (KeyError, TypeError, ValueError):
                _ws_od = 0
            if _ws_od > 0:
                ws_out = [ws_out[0], _ws_od]

            # Non-codebook spaces require nVectors (spaceShape[0]) ==
            # nActive (outputShape[0]); resize the per-stage codebook shape
            # to match the halved N. Dual-towers rev 2: the sparse-PARALLEL
            # path instead honors the config <nVectors> INVENTORY (the taper
            # blocks + inert tail live inside it; concept_order_limit parses after
            # create, so read the XML directly).
            _so_v = self.concept_order_limit
            _ser_v = self._has_word_objects()
            if (getattr(self, 'concept_binding', 'mixing') == 'aligned'):
                # Canonical aligned models address concepts by CS inventory
                # row. Every stage therefore owns the full preallocated CS
                # dictionary; WholeSpace's much smaller property basis is not
                # a fallback source of concept rows.
                stage_space_concept = [spaceShape_concept[0],
                                       spaceShape_concept[1]]
            elif _so_v > 0 and not _ser_v:
                stage_space_concept = [spaceShape_concept[0],
                                       spaceShape_concept[1]]
            else:
                stage_space_concept = [cs_out[0], spaceShape_concept[1]]
                # Concept index-read (snap design doc §ontology): the
                # concept inventory must seat the word/object concepts
                # (≈2× distinct words at order 0 + the METAs in the pool)
                # — vocabulary-scaled, not tile-scaled. The serial arm's
                # tile-count sizing starved it (measured: 4 words onto
                # caps0=2 rows COLLIDED and the read hurt). Honor an
                # EXPLICIT <ConceptualSpace><nVectors> as a floor, gated
                # on <conceptIndexRead> so every existing config keeps
                # byte-identical shapes.
                _explicit_word_traversal = TheXMLConfig.get(
                    "architecture.serialWordCapacity", default=None)
                if (_serial_requested or bool(TheXMLConfig.get(
                        "architecture.conceptIndexRead", default=False))
                        or _explicit_word_traversal not in (None, "")):
                    _nv_cs = self._nvec("ConceptualSpace", 0)
                    if _nv_cs > 0:
                        stage_space_concept[0] = max(
                            int(stage_space_concept[0]), int(_nv_cs))
            # In the canonical property-basis mode every quantized WholeSpace
            # stage draws from the configured property inventory. It is
            # independent of live slot geometry and ConceptualSpace capacity.
            # This is the initial physical seed only; later dynamic property
            # growth must rebuild optimizer/compiled ownership at an explicit
            # reset boundary. Legacy configs retain their prior terminal-only
            # inventory sizing until explicitly migrated.
            stage_space_symbol = [spaceShape_symbol[0], spaceShape_symbol[1]]
            # Right-half loopback widening retired (see ConceptualSpace
            # docstring): per-order input sourcing replaces the concat,
            # so the C-space_role PiLayer input width is just nInputDim.
            cs = ConceptualSpace(
                cs_in, stage_space_concept, cs_out,
                stage_idx=t, is_last=is_last,
                shared_similarity_codebook=(
                    _shared_concept_dictionary
                    if _share_concept_dictionary else None),
                indexed_similarity_codebook=_aligned_codebook_sources,
                derived_similarity_codebook=_serial_requested,
                shared_percept_readout=(
                    _shared_percept_readout if _share_concept_dictionary else None),
            )
            if _shared_concept_fold_support is not None:
                object.__setattr__(
                    cs, "_concept_fold_support",
                    _shared_concept_fold_support)
            if _share_concept_dictionary and _shared_concept_dictionary is None:
                _shared_concept_dictionary = cs.similarity_codebook
                _shared_percept_readout = cs.concepts_from_percepts
            if _aligned_codebook_sources:
                # The serial aligned path reaches the million-row dictionary
                # only through indexed concept identities.  Preserve that
                # sparsity in backward so the dedicated row-local optimizer
                # never allocates a dense 1M x ConceptDim gradient/moment set.
                cs.similarity_codebook.sparse_lookup_grad = True
            ws = WholeSpace(ws_in, stage_space_symbol, ws_out)
            # Non-owning back-ref CS->WS (mirrors the perceptualSpace_ref
            # idiom below): object.__setattr__ so it is NOT registered as
            # an nn.Module child of cs. Read-only structural pairing.
            object.__setattr__(cs, 'wholeSpace_ref', ws)
            # Per-stage flags consumed by build_pipelines / forward.
            ws.is_last = is_last
            ws.quantize = not is_last
            self.conceptualSpaces.append(cs)
            self.wholeSpaces.append(ws)

        # Backwards-compat aliases: read-only callers (e.g.
        # symbolSpace.truth_layer = self.wholeSpace) see the terminal stage.
        # Terminal convenience aliases are routing references; the ModuleLists
        # above are the sole structural owners.
        object.__setattr__(self, 'conceptualSpace', self.conceptualSpaces[-1])
        object.__setattr__(self, 'wholeSpace', self.wholeSpaces[-1])

        # §6d reference-partitioned codebook update law (GrammarOpsPass;
        # author 2026-06-11): percepts are shaped by the parallel pass,
        # references by the serial pass. Install on both towers with a
        # LAZY table getter (the binding table is created on first gate
        # use; the mask stays None — legacy behavior — until then or
        # with the meronomy off). PS/extent tower: bound OBJECT ids are
        # references; WS/intent tower: bound WORD ids (WS also
        # self-installs at table creation; this is idempotent).
        _law_ss = self.wholeSpace
        _law_get = lambda: self._concept_owner()._definition_index()
        if getattr(self, 'perceptualSpace', None) is not None:
            self.perceptualSpace.install_reference_update_law(
                _law_get, side='object')
        _law_ss.install_reference_update_law(_law_get, side='word')

        # §5 intent priming (GrammarOpsPass; author 2026-06-11): wire
        # both codebook towers' row selection to the single current
        # intent (``set_intent``). Dark by construction: with no intent
        # set the producer returns None and recognition is
        # byte-identical to the unprimed path.
        if getattr(self, 'perceptualSpace', None) is not None:
            self.perceptualSpace.install_intent_priming()
        _law_ss.install_intent_priming()

        # VQ-VAE EMA / growing-codebook knob overrides per space.
        # Each Space's ``subspace.what`` may carry an internal
        # ``VectorQuantize`` (``.vq``); when XSD knobs are set, override
        # the defaults baked in at ``Codebook.addVectors`` time so
        # configs can tune EMA decay and dead-code retirement without
        # code edits.  ``codebookGrowthEpsilon`` is stashed as
        # ``.growth_epsilon`` on the VQ for runBatch to consult.
        for _sect, _sp in (
            ("PartSpace", self.perceptualSpace),
            ("ConceptualSpace", self.conceptualSpace),
            ("WholeSpace", self.wholeSpace),
        ):
            _cb = getattr(getattr(_sp, 'subspace', None), 'what', None)
            _vq = getattr(_cb, 'vq', None) if _cb is not None else None
            if _vq is None:
                continue
            _decay = TheXMLConfig.space(_sect, "commitmentDecay",
                                        default=None)
            if _decay is not None:
                _vq.decay = float(_decay)
            _retire = TheXMLConfig.space(_sect, "codebookRetire",
                                         default=None)
            if _retire is not None:
                _vq.codebook_retire = bool(_retire)
            _thr = TheXMLConfig.space(_sect, "codebookEmaDeadThreshold",
                                      default=None)
            if _thr is not None:
                _vq.threshold_ema_dead_code = int(_thr)
            _eps = TheXMLConfig.space(_sect, "codebookGrowthEpsilon",
                                      default=None)
            _vq.growth_epsilon = (float(_eps) if _eps is not None
                                  else 0.0)

        # Whole-property VQ training: the canonical property-basis mode has
        # exactly one WS dictionary (``subspace.what``). It drops EMA and
        # learns selected properties from the reconstruction gradient. Legacy
        # configs temporarily retain their separate ``analysis_store`` update
        # path for checkpoint compatibility; it is never involved in aligned
        # concept-capacity growth.
        for _ws_stage in self.wholeSpaces:
            _ws_codebooks = [getattr(
                getattr(_ws_stage, 'subspace', None), 'what', None)]
            pass
            for _cb in _ws_codebooks:
                _vq = getattr(_cb, 'vq', None) if _cb is not None else None
                if _vq is None:
                    # Canonical properties are a direct learned Parameter,
                    # without VQ/EMA shadow tensors. WholeSpace constructs and
                    # registers W; enlist that one physical owner explicitly.
                    _W = (_cb.getW() if _cb is not None
                          and hasattr(_cb, 'getW') else None)
                    if (isinstance(_W, nn.Parameter)
                            and all(_W is not p for p in _ws_stage.params)):
                        _ws_stage.params += [_W]
                    continue
                if _vq is None:
                    continue
                _vq.ema_update = False
                _vq.commitment_weight = 0.0
                # The recon leg (input -> codebook, asymmetric-vq sec.4):
                # the WS property codebook trains by the EXACT reconstruction
                # gradient -- promote the VQ codebook to an nn.Parameter
                # (auto-registered on the VQ module) and enlist it in the
                # space's optimised params. The stage-0 unity path emits
                # the recon term (plain differentiable gather vs the
                # DETACHED pre-snap evidence: gradient lands on the
                # selected rows only; the argmin blocks the encoder leg);
                # the t>0 symbolic iteration emits the CS-leg twin.
                if not isinstance(_vq.codebook, nn.Parameter):
                    _vq.codebook = nn.Parameter(
                        _vq.codebook.detach().clone())
                    with torch.no_grad():
                        _vq._b_norms_sq.copy_(
                            (_vq.codebook.detach() ** 2).sum(dim=-1))
                _ws_stage.params += [_vq.codebook]

        # Cross-space forward inputs (perceptual + symbolic loop into C,
        # C→P feedback into P) are now passed as explicit ``forward``
        # arguments by the recurrent cell in ``_forward_body`` -- no
        # post-construction ``wholeSpace_ref`` / ``perceptualSpace_ref``
        # / ``conceptualSpace_ref`` plumbing. The WholeSpace lexicon
        # ref below is structural (vocabulary ownership), not forward
        # input, and is kept.
        # Lexicon ownership (post-lexicon-migration): wire every
        # WholeSpace stage to PartSpace so ``S.vocabulary``
        # and the orthographic-API methods reach the physical Embedding
        # that lives on PartSpace for input-pipeline reasons.
        for ws in self.wholeSpaces:
            object.__setattr__(ws, 'perceptualSpace_ref',
                               self.perceptualSpace)

        # Task G auto-META on word learning: the auto-bind moved from
        # PartSpace to ConceptualSpace. Each ``cs`` already has
        # ``wholeSpace_ref`` (wired above per stage); add the
        # matching ``perceptualSpace_ref`` so the stage-0 cs.forward
        # can read the pid grid stashed on
        # ``perceptualSpace_ref._forward_input['indices']``. The
        # back-ref points at the canonical PartSpace; the autobind
        # gate (``if int(self.stage_idx) == 0``) restricts firing to
        # the first stage where the pid grid still aligns with the
        # incoming subspace event.
        #
        # The autobind grows the META taxonomy, which is owned by the
        # TERMINAL WholeSpace (``self.wholeSpace`` ==
        # ``wholeSpaces[-1]``). Per-stage WS codebooks are slot-fixed
        # by the where-space registry and cannot grow without overrunning
        # a downstream slice -- so wire a separate
        # ``terminalSymbolSpace_ref`` distinct from the per-stage
        # ``wholeSpace_ref`` used by other CS consumers.
        for cs in self.conceptualSpaces:
            object.__setattr__(cs, 'perceptualSpace_ref',
                               self.perceptualSpace)
            object.__setattr__(cs, 'terminalSymbolSpace_ref',
                               self.wholeSpace)
            # serialObjectMeta reaches CS here (a NEW stamp site — _mereology_
            # raise never reaches CS; _maybe_autobind_words reads it off self).
            # Read the live config directly: _create_per_stage runs DURING
            # construction, before self.serial_object_meta is parsed (same
            # order-safety idiom as the mereologyRaise request below).
            object.__setattr__(cs, '_serial_object_meta', bool(
                TheXMLConfig.get("architecture.serialObjectMeta", default=False)))
            # Model-level incoming assertion trust reaches CS here too for
            # probes/tests that need the architecture value during construction.
            object.__setattr__(cs, '_trust', self._unit_interval(
                TheXMLConfig.get("architecture.trust", default=1.0),
                default=1.0))
            object.__setattr__(cs, '_ltm_consolidation', True)

        # S3 relocation (2026-06-17): ConceptualSpace is the OWNER of the
        # relation-only symbol table / taxonomy (doc/specs/mereological-order-
        # raising.md "relation-only completion"). Like the META taxonomy, the
        # relation table is a SINGLE TERMINAL owner -- the terminal CS
        # (``conceptualSpaces[-1]`` == ``self.conceptualSpace``) -- so wire a
        # ``terminalConceptualSpace_ref`` onto every CS and onto legacy
        # symbol-dictionary WS instances, mirroring the
        # ``terminalSymbolSpace_ref`` fan-out, so any symbolic stage can reach
        # the one canonical relation owner without fragmenting it into N
        # tables. A property-basis WS is strictly upstream and receives no
        # downstream ConceptualSpace pointer.
        # (Fix #1 ownership-by-reference: the physical position-keyed dicts are
        # still served from the terminal WholeSpace, which mints the codebook
        # rows atomically; CS owns the relation INTERFACE. A full physical move
        # is blocked on retiring the meta-vector seed -- a gradient-path change,
        # deferred -- and is NOT attempted here.)
        for sp in self.conceptualSpaces:
            object.__setattr__(sp, 'terminalConceptualSpace_ref',
                               self.conceptualSpace)
        for sp in self.wholeSpaces:
            if not bool(isinstance(sp, WholeSpace)):
                object.__setattr__(sp, 'terminalConceptualSpace_ref',
                                   self.conceptualSpace)

        # Wire the back-ref WS <- Embedding (terminal stage:
        # ``wholeSpaces[-1]`` == ``self.wholeSpace``) so the
        # vocabulary/orthographic API delegation keeps working. The
        # Stage-1.B paired-row contract this ref used to serve
        # (``insert_paired_word`` on PS-side OOV inserts) was RETIRED in
        # Step 3 of the 2026-06-10 symbolic-iteration plan.
        terminal_ss = (self.wholeSpaces[-1]
                       if self.wholeSpaces else None)
        emb = getattr(self.perceptualSpace, 'vocabulary', None)
        if terminal_ss is not None and isinstance(emb, Embedding):
            object.__setattr__(emb, 'wholeSpace_ref', terminal_ss)
            # Step 3 (2026-06-10 symbolic-iteration plan): the tied-
            # storage migration (``_tie_lexicon_to_codebook`` -- the
            # PS->WS reach-across that wrote an orth row + random
            # semantic partner per lexicon word and remapped
            # ``key_to_index`` onto WS rows) is RETIRED. The Step-1
            # symbol codebook on the CS leg captures the code-as-written
            # vs code-for-the-concept correspondence in place; the
            # lexicon keeps PS-LOCAL storage permanently (untied), and
            # the decode resolves row->word through the inverse of
            # ``key_to_index`` (identity when untied).

        # No SyntacticSpace -- syntax is handled by Grammar centrally.
        self.syntacticSpace = None

        # Output: primary path is IS→PS→CS→OS, so OutputSpace consumes
        # the terminal ConceptualSpace output (WholeSpace is the
        # symbolic recurrent loop leg, off the head path). Size the head
        # from the terminal C stage's ACTUAL ``outputShape`` (the
        # source of truth) rather than a recomputed
        # ``concept_dim + obj_concept``. The bivector regime was retired
        # (2026-05): the terminal C stage emits a single signed scalar
        # per prototype, so ``.nOutputDim == .outputShape[1]`` for every
        # config and the old stale-width mismatch ("Bug #1") is
        # structurally gone -- this site needs no special-casing.
        _term_cs_shape = list(self.conceptualSpaces[-1].outputShape)
        output_n = int(_term_cs_shape[0])
        outputInputShape = [output_n, int(_term_cs_shape[1])]
        self.outputSpace = OutputSpace(outputInputShape, spaceShape_output, outputShape,
                                       vectors=self.perceptualSpace.vocabulary)

        self._symbol_shape = [nPercepts, percept_dim + obj_percept]

        # Build SymbolSpace -- the unified container for grammar
        # infrastructure (SymbolSubSpace, three SyntacticLayers, the
        # TruthLayer, and conditionally the DiscourseSpace substrate).
        # Its ``__init__`` configures the grammar, sizes the word
        # buffer from ConceptualSpace's column layout, builds each space_role's
        # SyntacticLayer, and back-wires the home spaces so
        # compose/decompose routes through ``self.symbolSpace``.
        self.symbolSpace = SymbolSpace(
            perceptualSpace=self.perceptualSpace,
            conceptualSpace=self.conceptualSpace,
            wholeSpace=self.wholeSpace,
            nPercepts=nPercepts,
            nConcepts=nPercepts,
            nSymbols=nSymbols,
            concept_dim=concept_dim + obj_concept,
            # Symbol identities/operators live in CS WHAT coordinates.  The
            # 128-D WholeSpace property basis is upstream and never sizes SS.
            symbol_dim=concept_dim,
        )
        # Scheduling ownership is separate from SymbolSpace's parameter/state
        # ownership. Keep a non-registering model reference so state_dict does
        # not acquire a second LanguageLayer path.
        object.__setattr__(self, 'languageSpace', self.symbolSpace.languageSpace)
        # Bind the grammar's native VP identities once during construction.
        # Forming a selected linguistic meaning later is pure: it reuses these
        # addresses and must never allocate a concept or write memory at a
        # sentence boundary.  This is the one production grammar-to-thought
        # bridge; the preserved legacy reasoner owns no grammar registry.
        object.__setattr__(
            self, 'grammatical_thoughts',
            GrammaticalThoughtRegistry.install(
                self._concept_owner() if _share_concept_dictionary else self.conceptualSpace,
                TheGrammar))
        object.__setattr__(
            self.symbolSpace, 'grammatical_thoughts', self.grammatical_thoughts)

        # MetaSymbol Category codebook (doc/Language.md
        # "Participation Categories"). Enabled by default via
        # <categoryCodebook>: in property-basis mode request the small
        # role-space VQ from terminal ConceptualSpace, which owns concepts and
        # META structure. Legacy configs keep the prior WholeSpace host until
        # they opt into the migration. Role columns are enumerated from the
        # now-configured grammar (SymbolSubSpace.__init__ ran
        # _ensure_configured above).
        # Read the flag from config HERE (not self.category_codebook): the
        # architecture flags are assigned in create_from_config AFTER the
        # spaces are built, so self.category_codebook is not yet set when
        # _create_per_stage runs -- reading the live config is the order-safe
        # source (the config is loaded before any space is created).
        _category_codebook = bool(TheXMLConfig.get(
            "architecture.categoryCodebook", default=True))
        category_owner = self.conceptualSpace
        if _category_codebook and category_owner is not None:
            # REQUEST allocation; the actual enable runs LAZILY from the
            # autobind hook on the first perception forward, when TheGrammar is
            # fully configured with the (role-collapsed) operator roles. At
            # build the role rules may not be loaded yet, so a build-time
            # enable would see 0 roles and no-op.
            category_owner._category_codebook_requested = True

        # Mereological order-raising (doc/specs/mereological-order-raising.md).
        # Opt-in via <mereologyRaise>: build a meronymic lattice in perception
        # and raise abstraction order as attention requires. Read the LIVE
        # config (the self.* arch flags are not yet assigned when
        # _create_per_stage runs). Stamp the flag onto the PartSpace +
        # terminal WholeSpace so the perception hot path reads it off
        # ``self`` (the _symbolic_order stamping convention).
        # NOTE (todo "make abstraction order canonical"): the ramsification
        # table is NO LONGER gated here -- Codebook.create allocates it for
        # every built codebook with max_order = max(1, bindingDepth),
        # and the sigma/pi processing sites stamp it live. This flag now
        # gates ONLY the lattice behaviors (word-whole autobind, order
        # raising, the top-down handoff).
        _mereology_raise = bool(TheXMLConfig.get(
            "architecture.mereologyRaise", default=False))
        if _mereology_raise and terminal_ss is not None:
            object.__setattr__(terminal_ss, '_mereology_raise', True)
            object.__setattr__(self.perceptualSpace, '_mereology_raise', True)
        # <radialStmReduce> (Alec 2026-07-13, "min should be a radial min
        # to deal with signed activations"): the STM idea folds use the
        # RADIAL kernels (radmin/radmax) and their reverses use the radial
        # recommender filters. Stamped on the terminal WS grammar hosts
        # the bounded reducer adapts; identical to the lattice pair on the
        # non-negative SS activations, signed-safe on CS ideas. Default
        # off = byte-identical.
        if bool(TheXMLConfig.get("architecture.radialStmReduce",
                                 default=False)) and terminal_ss is not None:
            _sl = getattr(terminal_ss, 'syntacticLayer', None)
            for _h in (getattr(_sl, '_by_name', {}) or {}).values():
                if getattr(_h, 'uses_operand_activation', False):
                    object.__setattr__(_h, 'radial', True)

        # The conceptual basis honours the ``architecture.monotonic``
        # knob rather than being unconditionally bitonic: monotone
        # (W>=0) is order-preserving, which the parthood predicate
        # (``Ops.part``) requires for the ramsified symbolic codebook
        # to match a symbol mapped through the subsymbolic loop across
        # orders. Default False -> unchanged (bitonic) behavior.
        self.conceptualSpace.subspace.basis.monotonic = self.monotonic

        self.spaces.extend([self.inputSpace, self.perceptualSpace])
        self.spaces.extend(list(self.conceptualSpaces))
        self.spaces.extend(list(self.wholeSpaces))
        self.spaces.extend([self.outputSpace])
        self.spaces.append(self.symbolSpace)

        # Bind stable, unique owner paths before any carrier reader is issued.
        # The terminal aliases (``conceptualSpace`` / ``wholeSpace``) are not
        # used because the ModuleLists are the structural owners.
        _carrier_owners = [
            ('inputSpace', self.inputSpace),
            ('perceptualSpace', self.perceptualSpace),
            *[
                (f'conceptualSpaces.{i}', space)
                for i, space in enumerate(self.conceptualSpaces)
            ],
            *[
                (f'wholeSpaces.{i}', space)
                for i, space in enumerate(self.wholeSpaces)
            ],
            ('outputSpace', self.outputSpace),
            ('symbolSpace', self.symbolSpace),
        ]
        for _owner_path, _space in _carrier_owners:
            binder = getattr(_space, 'bind_codebook_owner_path', None)
            if callable(binder):
                binder(_owner_path)

        self.inputSpace.outputSpace = self.outputSpace
        # Seed the pipeline context: InputSpace stamps every outgoing
        # subspace's ``symbolSpace`` with this reference so downstream stages
        # read ``vspace.symbolSpace`` instead of reaching back through a
        # Model back-channel.
        self.inputSpace.set_word_space(self.symbolSpace)

        # Phase 1: wire a Normalizer onto every space so spaces can call
        # self.normalizer.{normalize,denormalize} instead of the TheData global.
        # Phase G of doc/specs/2026-05-21-wordsubspace-stm-layer-refactor.md
        # retired the per-SubSpace ``symbolSpace`` back-pointer; the
        # SymbolSubSpace reference lives on each ``Space`` via the routing
        # pointer set by ``Space.attach_symbolSpace``. SymbolSubSpace's
        # constructor wires P/C/S spaces; here we mirror that wiring onto
        # every other space (InputSpace / OutputSpace / ModalSpace) so
        # ``space.symbolSpace`` is non-None project-wide.
        self.normalizer = Normalizer(self.data)
        for space in self.spaces:
            space.normalizer = self.normalizer
            sub = getattr(space, 'subspace', None)
            if sub is not None:
                sub.normalizer = self.normalizer
            if (space is not self.symbolSpace and (not isinstance(space, WholeSpace)) and (getattr(space, 'symbolSpace', None) is None) and hasattr(space, 'attach_symbolSpace')):
                space.attach_symbolSpace(self.symbolSpace)

        # Slice C: the per-stage ConceptualSpace cells (which run bind_streams)
        # need the SymbolSpace ref so the CS-mediated symbol leg
        # (ConceptualSpace._build_symbol_leg) can sync the order-raising codes
        # onto SS.subspace.what. GATED on symbol_tower so off-path per-stage CS
        # keep _model_symbolSpace=None -> byte-identical (the autobind's
        # _model_symbolSpace read at Reset is unaffected for non-tower configs).
        if bool(TheXMLConfig.get("architecture.symbolTower", default=False)):
            for _cs in getattr(self, 'conceptualSpaces', ()):
                if getattr(_cs, '_model_symbolSpace', None) is None:
                    object.__setattr__(_cs, '_model_symbolSpace', self.symbolSpace)

        # Precompute partition boundaries for partitioned symbolSum
        self._partitions = self._order_partitions(concept_dim,
                                                   self.bindingDepth)
        self.symbol_states = []
        # Per-step lifecycle slots, initialized explicitly so every
        # read is a plain attribute access (no getattr-with-default):
        #   _staged_in_sub      -- lex+embed stem subspace parked by
        #                          runBatch for the compiled forward
        #                          (None == not staged: eager/uncompiled
        #                          path lexes inline).
        #   _compiled_step      -- the torch.compiled callable, or None
        #                          (set by enable_compiled_step; None
        #                          here so the eager path is valid even
        #                          if that is never called).
        #   _current_discourse_s -- S-space_role sentence rep stashed by the
        #                          forward for the post-body ARMA term.
        #   _staged_concepts_in -- the UNITY view [B, 1, N] parked by
        #                          _lex_embed_stem for the symbolic
        #                          branch (analysis/synthesis dual-input
        #                          plan; Phase 2 consumes it at WS
        #                          stage 0).
        self._staged_in_sub = None
        self._staged_concepts_in = None
        self._compiled_step = None
        self._compiled_word_steps = {}
        self._active_compiled_step = None
        self._compiled_word_chunk_step = None
        self._compiled_word_chunk_active = False
        self._compiled_word_chunk_replaying = False
        self._compiled_word_chunk_trace_active = False
        self._compiled_word_chunk_width = 0
        self._brick_compiled = False
        self._brick_cuda_graph_mode = None
        # Canonical aligned serial execution uses the three-stage peer contract.
        # Older configurations retain the legacy static A/B/C compatibility
        # scheduler. The switch is read at construction, never inside a
        # captured word loop.
        self._peer_pipeline_enabled = (
            os.environ.get("BASICMODEL_PEER_PIPELINE", "1").strip().lower()
            not in ("0", "false", "no", "off"))
        # The compiled production path carries the recurrent word scheduler as
        # tensor state through ``torch.while_loop``.  Eager execution keeps the
        # static scheduler as the serial reference and for ownership
        # diagnostics; setting the value to ``always`` also exercises the HOP
        # in eager tests/benchmarks.
        _tensor_peer_mode = os.environ.get(
            "BASICMODEL_TENSOR_PEER_WHILE", "compiled").strip().lower()
        self._tensor_peer_while_enabled = (
            _tensor_peer_mode not in ("0", "false", "no", "off", "none"))
        self._tensor_peer_while_eager = _tensor_peer_mode in (
            "1", "true", "yes", "on", "always", "eager")
        # Read once at construction so eager peer execution has the same
        # ownership diagnostics as an explicitly compiled model.
        self._debug_peer_mutation = (
            os.environ.get("BASICMODEL_DEBUG_PEER_MUTATION", "0") == "1")
        self._current_discourse_s = None
        # Fullgraph sentence products consumed by the eager loss/diagnostic
        # tail.  The lazy compiled wrapper returns these explicitly so their
        # publication does not depend on Dynamo replaying Python attributes.
        self._stm_single_S = None
        self._stm_post_depth = None
        self._packed_sentence_roots = None
        self._tensor_peer_trip_count = None
        # MPHF instrumentation handles -- always initialised so the
        # per-word body can use direct attribute reads (no getattr
        # fallback, which is a Dynamo graph break).
        # Persistent empty CS seeds for the recurrent cell's pass-0
        # (prevCS_forPS / prevCS_forSS). Built ONCE here instead of
        # constructing a fresh SubSpace every _forward_body call: the
        # per-forward object churn changes traced object-identity and
        # is the prime suspect for splitting the compiled forward into
        # 2 guarded graphs. These are zero-length ``is_empty()``
        # sentinels; the recurrent cell only ``.is_empty()`` /
        # ``.materialize()``s them (consumers write their own subspace,
        # never the seed), so a shared persistent instance is
        # behaviour-identical to the prior fresh-per-forward seed.
        self._empty_seed_ps = self._empty_subspace()
        self._empty_seed_ss = self._empty_subspace()
        # Routing state lives with the conceptual owner. BasicModel retains
        # only construction-time empty sentinels for legacy parallel paths.
        object.__setattr__(self.conceptualSpace, '_peer_empty_sub',
                           self._empty_seed_ps)
        object.__setattr__(self.conceptualSpace, '_peer_empty_sym',
                           self._empty_seed_ss)
        object.__setattr__(self.conceptualSpace, '_peer_prev_sub',
                           self._empty_seed_ps)
        object.__setattr__(self.conceptualSpace, '_peer_prev_sym',
                           self._empty_seed_ss)

        self.word_brackets = self._has_word_objects()
        self._install_unit_span_fn()

        # Phase 2: Sequential pipeline is the only path.
        self.build_pipelines()

        self.to(TheDevice.get())
        TheXMLConfig.validate()

    # -- Phase 2: Sequential pipeline ----------------------------------
    #
    # ``_flatten_k`` / ``_restore_k`` retired 2026-05-13 together with
    # the AR cursor unfold. The body and head now operate on
    # B-shaped tensors throughout; per-cursor predictions are produced
    # by the serial K-loop in ``_forward_per_stage_no_unfold``.

    def _build_pipelines_per_stage(self):
        """Phase 2: stem/body/head pipelines for BasicModel.

        Pipeline shape (microbatch AR):
            stem  : nn.Sequential(inputSpace, FlattenK(perceptualSpace))
                    + per-word P->C->S->C round trip filling
                    ConceptualSpace.stm
            body  : explicit for-loop over ``self.body_stages``
                    (ModuleList of ModuleDicts), one dict per stage:
                      cs -> chart-at-C -> [merge?] -> ws
                    K-axis flatten/restore is hoisted into _forward_body.
            head  : FlattenK(outputSpace)

        T = len(self.conceptualSpaces). Per-stage WholeSpace and
        ConceptualSpace outputs are persisted directly on the stage
        spaces' ``.subspace`` — the per-stage forward capture lists
        ``_ws_cache`` / ``_cs_cache`` were retired by Stage 1.F of the
        two-loop pi/sigma substrate refactor (doc/plans/
        2026-05-26-two-loop-pi-sigma-substrate.md). Reverse-pass
        consumers read the terminal C-space_role idea from
        ``self.conceptualSpace.stm.snapshot()``; ``symbol_states`` is
        rebuilt by iterating ``self.wholeSpaces`` directly.
        ``self.symbol_cache`` is a property returning the terminal
        WholeSpace's ``.subspace`` — same role as before, no longer
        a CachePoint module and no longer a per-stage list lookup.
        """
        T = len(self.conceptualSpaces)
        use_grammar_merge = (self.useGrammar == "all")

        # PartSpace quantize: matches legacy's percept_quantize logic.
        # Reversible+invertible configurations skip codebook quantization to
        # preserve exact-invertibility of the perceptual step.
        self.perceptualSpace.quantize = not (
            self.reversible and getattr(self.perceptualSpace, "invertible", False))

        # Compatibility-only ownership: legacy WholeSpace doubled as the
        # symbolic stage. Canonical property-basis WS is strictly upstream and
        # must not retain a downstream SymbolSpace pointer.
        pass

        # Stage 1.F substrate refactor (doc/plans/2026-05-26-two-loop-
        # pi-sigma-substrate.md): the per-stage forward capture lists
        # ``_ws_cache`` / ``_cs_cache`` are retired entirely. The
        # terminal C-space_role idea built up over the sentence lives on
        # ``self.conceptualSpace.stm`` (ShortTermMemory snapshot); the
        # terminal symbolic subspace lives directly on
        # ``self.wholeSpace.subspace`` (each stage's
        # ``ws.forward(...)`` writes there in place). Both
        # ``symbol_cache`` and the reverse-pass reconstruction loss
        # consumer were migrated to read from those canonical owners.

        # Subsymbolic passes retain the same attended geometry.
        self.body_stages = nn.ModuleList([
            _BodyStage(self.conceptualSpaces[t], self.wholeSpaces[t])
            for t in range(T)])
        from WhereRegistry import install_where_registry
        install_where_registry(self)

        # --- A4 (2026-06-06 parallel-conceptual-recurrence): per-stage
        # ConceptualCombine modules. One SQUARE augment-threaded invertible
        # combine per stage replaces the per-stage ``cs.forward`` content
        # fold + the prior WS.sigma (pi/sigma) alternation in the PARALLEL
        # ``_forward_body`` (doc/plans/2026-06-06-parallel-conceptual-
        # recurrence.md sec. 3.3). Built ONCE here and registered on its
        # ConceptualSpace (``cs.layers`` / ``cs.params``) so the LDU /
        # butterfly weights are optimised with the rest of the model -- they
        # must NOT be constructed inside ``forward`` (that re-inits the
        # weights every call and loses learning).
        #
        # ``content_dim`` D is the per-stage FULL MUXED EVENT width
        # ``cs.muxedSize`` (== ``nWhat + nWhere + nWhen``), NOT the demux'd
        # content. Option B (doc/specs/2026-06-06-muxed-events-and-positional-
        # bands.md): the combine transforms the WHOLE muxed event -- content
        # AND the .where/.when band TOGETHER -- so the positional tail
        # PARTICIPATES in the conceptual advance instead of riding along
        # untouched. (That is the whole point of muxing where/when in.)
        #
        # DIMENSIONAL-GOVERNANCE NOTE (MM_20M today): PS and CS events are
        # both ``muxedSize = 1024`` (``[B, 8, 1024]``, 1020 what + 2 where +
        # 2 when), but the WholeSpace OUTPUT is a COMPRESSED symbol code
        # (``ws.nOutputDim = 8``) -- the WS event width does NOT match the
        # CS/PS event width. This is the wide<->deep symbol handoff: WS emits
        # an 8-wide code that the combine (like ``ConceptualSpace.forward``'s
        # STM) zero-pads up to D. The combine therefore sizes D to the
        # CONCEPTUAL event width (``cs.muxedSize``) -- the dominant stream and
        # the carrier the head consumes -- and the WS stream is fit (zero-
        # padded) up to D before the combine (see ``_combine_demux`` /
        # ``_combine_fit`` in ``_forward_body``).
        # The flat-slab invariant holds for the PS/CS carriers (both 1024);
        # the WS-narrower-than-D case is handled by the pad rather than
        # blocking the integration.
        # ``naive=False`` is the design's REQUIRED reverse path (exact
        # structured ``_solve_ldu`` / closed-form butterfly inverse, NOT
        # pinv). Read the architecture knob only to honour an explicit
        # debug override; default False.
        #
        # OWNERSHIP (2026-06-06): the combine is the C-space_role conceptual-advance
        # operator, so each ``ConceptualSpace`` HOLDS its own (cf. PS owns
        # ``pi``, WS owns ``sigma``). Built here -- where the per-stage config
        # (sigmaPi span, naive/ergodic, merge gating) is resolved -- then
        # registered ON the cs: appended to ``cs.layers`` (so ``paramUpdate``/
        # ``set_sigma`` cascade through ``Space``) and its params added to
        # ``cs.params`` (so the ``self.spaces`` getParameters() walk optimises
        # it). ``cs.combine`` is the access handle; there is NO model-level
        # ``conceptual_combines`` list -- the combine learns through its cs,
        # like every other Space layer.
        _combine_naive = bool(TheXMLConfig.get("architecture.naive", False))
        _combine_binding = str(TheXMLConfig.get(
            "architecture.conceptBinding", default="mixing")
        ).strip().lower()
        for t in range(T):
            cs = self.conceptualSpaces[t]
            if _combine_binding != "mixing":
                # Location-aligned binding is parameter-free and retains its
                # source carrier directly on CS.  Do not allocate a dormant
                # ConceptualCombine: the mixing matrix exists only for the
                # explicitly selected parallel ablation.
                object.__setattr__(cs, "combine", None)
                continue
            # Slot-stack bind (geometry corrected 2026-06-10): the streams
            # stack along the VECTOR axis (N slots each, 2N total) and ONE
            # cascade runs over the flattened 2N*D slab -- 16*nDim for the
            # production parallel config (= 2^14 exactly, zero pad):
            # cross-slot reach. D is the FULL muxed event width
            # (cs.muxedSize == the config nDim: content + where/when band)
            # so the band PARTICIPATES in the bind (option B, as in the
            # 3-stream design) -- the spec's 16*nDim arithmetic is the
            # event width.
            D_t = int(getattr(cs, "muxedSize", 0))
            if D_t < 1:
                # Defensive: fall back to the concept buffer / content width
                # so the combine is always constructible (D>=1 is the bar).
                D_t = max(1, int(getattr(cs, "concept_dim",
                                         getattr(cs, "nWhat", 1))))
            # The combine binds the DEEP conceptual hub (n_vectors slots of
            # the muxed event width D_t), NOT the wide per-stage position
            # grid. For flat-slab wide<->deep configs (e.g. MM_20M_grammar:
            # wide PS [1024, 8] reshapes to deep CS [8, 1024]) the grammar
            # N-halving path inflated ``cs.outputShape[0]`` to the WIDE
            # position count (nPercepts>>t = 512/256), so the cascade ballooned
            # to next_pow2(2 * 512 * 1028) = 2^21 (~339M params, ~114s build)
            # binding phantom slots that never carry deep content. Cap the slot
            # count at the deep conceptual hub ``nConcepts``: bind_streams'
            # ``_bind_regroup`` already reshapes the wide legs into n_vectors
            # deep slots, so the runtime data is unchanged -- only the cascade
            # is sized to the real 8-slot hub (MM_20M's 2^15-scale combine).
            N_t = max(1, int(cs.outputShape[0]))
            _deep_n = int(getattr(self, "nConcepts", 0))
            if _deep_n > 0 and _deep_n < N_t:
                N_t = _deep_n
            combine = ConceptualCombine(
                content_dim=D_t,
                n_vectors=N_t,
                naive=_combine_naive,
                sigma_pi_mode=self.sigma_pi_mode,
                ergodic=self.ergodic,
                # Slice B: 3-stream when symbolTower is on. Read the config
                # DIRECTLY (not self.symbol_tower) -- the per-stage pipelines are
                # built by _create_per_stage BEFORE create_from_config sets
                # self.symbol_tower (line ~794), so the attr isn't live yet here.
                # combine.n_streams is what the bind keys on; the forward-time
                # loop gate (self.symbol_tower) is set by the time forward runs.
                n_streams=(3 if bool(TheXMLConfig.get(
                    "architecture.symbolTower", default=False)) else 2),
                # Concepts live on the unit ball: when ConceptualSpace
                # <nonlinear> is set, the per-stage combine saturates the bound
                # concept with tanh (forward) / atanh (reverse) -- the joint
                # nonlinearity a non-separable readout (XOR) needs. Read the
                # config directly (cs.nonlinear may not be live at per-stage
                # build time, matching the symbolTower read above).
                nonlinear=bool(TheXMLConfig.space(
                    "ConceptualSpace", "nonlinear")))
            # Held by the ConceptualSpace: register for paramUpdate/set_sigma
            # (cs.layers) and optimisation (cs.params); expose as cs.combine
            # WITHOUT a second nn.Module registration (object.__setattr__,
            # mirroring the wholeSpace_ref idiom -- cs.layers is the real
            # child registration).
            cs.layers.append(combine)
            cs.params += combine.getParameters()
            object.__setattr__(cs, "combine", combine)

        all_spaces = ([self.inputSpace, self.perceptualSpace]
                      + list(self.conceptualSpaces)
                      + list(self.wholeSpaces)
                      + [self.outputSpace])
        self.any_invertible = any(
            s.invertible if hasattr(s, "invertible") else False
            for s in all_spaces)

        # Forward midpoint cache. None for invertible (Case A); for
        # non-invertible (Case B) the forward result is stored here so
        # the round-trip path can rebuild from it. Plain attribute --
        # used to be a CachePoint module.
        self.midpoint_cache = None

    # BasicModel.End and BasicModel.Finish were dropped 2026-05-05:
    # End() was identical to BasicModel.End; Finish() differed only in
    # skipping the optional plotActivations call, which is gated on
    # ``self.plot`` (False by default) so inheriting BasicModel.Finish
    # is a no-op behavior change for the per-stage path.

    @property
    def symbol_cache(self):
        """The last SymbolSpace-owned result of the current forward."""
        return getattr(self, '_reading_symbol_result', None)



    def _forward_head(self, sub, *, sentence_state=None, understanding=None):
        """Read the concluded state as fixed input to the answer map."""
        if self.outputSpace.concept_ids:
            sub = self._combine_last_cs_sub
        elif getattr(self, 'word_brackets', False):
            # A fullgraph body returns these tensors explicitly. Its eager
            # diagnostic attributes are published only after the head runs.
            root = (sentence_state[0] if sentence_state is not None
                    else getattr(self, '_stm_single_S', None))
            if not torch.is_tensor(root):
                raise RuntimeError('a serial numeric answer requires a concluded understanding')
            slots = (sentence_state[-2] if sentence_state is not None
                     else getattr(self, '_tensor_final_end_slots', None))
            depth = (sentence_state[-1] if sentence_state is not None
                     else getattr(self, '_tensor_final_end_depth', None))
            if not (torch.is_tensor(slots) and torch.is_tensor(depth)):
                slots, depth = self._final_end_state(
                    root, getattr(self, '_stm_post_depth', None))
            B, D = root.shape
            occupied = depth.reshape(B).abs().clamp_max(3)
            single = torch.cat((root[:, None], root.new_zeros(B, 2, D)), dim=1)
            slots = torch.where((occupied == 1)[:, None, None], single, slots)
            slots = torch.where(
                (torch.arange(3, device=root.device)[None] < occupied[:, None])[..., None],
                slots, torch.zeros_like(slots))
            # Preserve the existing map's parameter geometry. Unoccupied
            # inputs are zeros; no per-word carrier can bypass the state cut.
            shape = tuple(self.outputSpace.inputShape)
            width = int(shape[0]) * int(shape[1])
            torch._assert_async((occupied * D <= width).all(),
                'the answer map cannot hold the concluded understanding')
            value = slots.detach().reshape(B, 3 * D)
            value = F.pad(value, (0, max(0, width - 3 * D)))[:, :width]
            sub = SubSpace.from_tensor(value.reshape(B, *shape),
                inputShape=shape, outputShape=shape,
                nInputDim=shape[1], nOutputDim=shape[1])
        # Numeric answers read the concluded state affinely. Nonlinear memory
        # retrieval belongs to thought and generation, never this gate's head.
        result = self.outputSpace(sub)
        record = understanding if understanding is not None else getattr(self, '_last_sentence_understanding', None)
        reader = getattr(self, 'answer_record_reader', None)
        if (self.word_brackets and record is not None and reader is not None
                and not self.answer_synthesis):
            value = result.materialize()
            result.set_event(value + reader(record).reshape_as(value))
        return result

    @staticmethod
    def _empty_subspace(d=1):
        """A zero-length SubSpace seed: ``is_empty()`` is True so the
        recurrent cell's pass-0 inputs short-circuit (PS uses pi_input
        alone; CS uses the perceptual primary alone; WS returns it
        unchanged)."""
        return SubSpace(inputShape=(0, d), outputShape=(0, d),
                        nInputDim=d, nOutputDim=d)

    @staticmethod
    def _zero_symbol_subspace(ws, ctx_sub):
        """"Nothing to quantize -> pass zeros": a correctly-batched
        zero WholeSpace output.

        When WS is fed an empty seed (e.g. bindingDepth=1, where the
        only pass's ``prevCS_forSS`` is the empty seed) it returns the
        activation-less empty subspace, breaking the symbol-state
        contract (``end_state`` / discourse / ARMA / head). The cell
        knows the real batch (from ``ctx_sub`` = the percept-side input),
        so it emits a ``[B, N_S, D_S]`` zero symbol here. ``set_event``
        installs a (non-None) activation, satisfying the contract;
        zeros are an additive no-op into any downstream consumer.
        """
        sample = ctx_sub.materialize()
        if sample is not None and sample.dim() >= 1:
            B = int(sample.shape[0])
            dev, dt = sample.device, sample.dtype
        else:
            B = 1
            dev, dt = TheDevice.get(), torch.get_default_dtype()
        N = int(ws.outputShape[0])
        D = int(ws.subspace.muxedSize)
        # Write onto WS's OWN subspace (mirrors the held_at_zero idiom)
        # so ``model.wholeSpace.subspace`` carries the zero event +
        # activation -- the symbol-state contract inspects that object,
        # not just the cached return. Place the zeros on the model's
        # device/dtype (held_at_zero uses ``device=sample.device,
        # dtype=sample.dtype``); a bare ``torch.zeros`` is CPU and
        # mismatches a CUDA model (``cuda:0 vs cpu`` on metalbaby).
        return ws.commit_from(
            ctx_sub, torch.zeros(B, N, D, device=dev, dtype=dt))

    def _read_subsymbolic_field(self, part_ids, part_spans, pass_idx):
        """Read the shared attentive extent at this perceptual pass."""
        owner = self._concept_owner()
        if not owner._sparse_active():
            return None
        ws, raw = self.wholeSpaces[0], self._staged_concepts_in
        positions, extents = ws.concept_evidence_layout(raw, int(ws.inputShape[0]))
        from PerceptProperties import uniform_spans
        if part_ids is None:
            part_ids = torch.empty(raw.shape[0], 0, device=raw.device, dtype=torch.long)
        if part_spans is None:
            part_spans = uniform_spans(raw.shape[0], raw.shape[-1],
                                       part_ids.shape[1], device=raw.device)
        if pass_idx == 0:
            object.__setattr__(self, '_subsymbolic_scope', None)
        elif pass_idx > 0:
            scope = getattr(self.conceptualSpace, '_passback_scope_where', None)
            if torch.is_tensor(scope):
                object.__setattr__(self, '_subsymbolic_scope', scope.detach())
        scope = getattr(self, '_subsymbolic_scope', None)
        if torch.is_tensor(scope):
            scope = scope.to(extents.device).reshape(-1, 2).expand(raw.shape[0], -1).clamp(0, 1)
            lo = (scope[:, 0] * raw.shape[-1]).floor().long()[:, None]
            hi = (scope[:, 1] * raw.shape[-1]).ceil().long()[:, None]
            start = torch.maximum(extents[..., 0], lo)
            end = torch.minimum(extents[..., 1], hi)
            extents = torch.stack((start, end), -1)
            extents = torch.where((end > start)[..., None], extents, 0)
        primitive = getattr(ws.subspace.what, 'primitive_properties', None)
        percepts = (part_ids, part_spans, primitive, raw, positions)
        field = owner.cs_read_memberships(percepts, extents)
        object.__setattr__(owner, '_cs_last_a0', field.detach())
        object.__setattr__(self, '_subsymbolic_field', field)
        object.__setattr__(self, '_subsymbolic_percepts', percepts)
        return field

    def _forward_body(self, in_sub, *, return_sentence_state=False):
        """Recurrent cell: IS→PS→CS→OS with CS→PS and CS→WS loops.

        Per pass t over ``self.body_stages`` (T = bindingDepth):

          * PS and WS run **in parallel** (no intra-pass dependency --
            WS still consumes the prior pass's CS view; PS is single-
            arg post-Stage-1.A substrate refactor):
              ``PS_sub = perceptualSpace.forward(in_sub)``
              ``WS_sub = ws.forward(prevCS_forSS)``
          * ConceptualSpace combines them (CS is the per-pass terminal):
              ``CS_sub = cs.forward(PS_sub, WS_sub)``
          * ``cs._subspaceForPS`` / ``cs._subspaceForWS`` (read
            post-merge) feed the next pass's subsymbolic / symbolic
            loops.

        Pass 0 seeds ``prevCS_*`` with empty subspaces so the cell
        degrades to PS-only / primary-only (matches the old
        ``ref is None`` cold start). The head consumes the terminal CS
        (``return last_cs``); WholeSpace is the symbolic loop leg,
        off the head path. ``in_sub`` is the stable InputSpace subspace
        (InputSpace ran once in the stem).

        When ``self.loss_head`` is set the post-body STM snapshot feeds
        the head and the loss is stashed on ``self._loss_head_loss``.
        """
        # Stage 1.E: explicit two-mode dispatch on
        # ``self.word_brackets`` (XML knob ``<architecture><serial>``, parsed in
        # ``create_from_config``).
        #
        #   * ``True`` (= SERIAL / GRAMMATICAL) -- per-word IR-reconstruction
        #     loop via :meth:`_forward_body_per_word`. ONE forward = ONE
        #     sentence: each ground-truth word ``[B,1,D]`` is pumped
        #     through the SAME per-stage PS->CS->WS computation and the
        #     resulting per-word concept is SHIFTed onto
        #     ConceptualSpace.stm; the NULL closing (next_word -> None)
        #     ends the loop. The accumulated STM then feeds the EXISTING
        #     compose-to-S / chart / head / reverse() / IR-loss TAIL
        #     entirely unchanged.
        #
        #   * ``False`` (= PARALLEL) -- T iterations of the per-stage body
        #     (whole-slab path, T = ``<bindingDepth>``), the legacy
        #     non-grammar path. Falls through to the loop below.
        #
        # Pre-Stage-1.E this dispatch was implicit (driven by the
        # InputSpace-side ``_per_word_enabled`` boolean derived from
        # ``useGrammar``); ``_per_word_enabled`` is now a back-ref
        # mirrored from ``self.word_brackets`` (see
        # ``create_from_config``) and retained for the remaining InputSpace
        # / per-word-loop late-stage consumers.
        if self.word_brackets:
            return self._forward_body_per_word(
                in_sub, return_sentence_state=return_sentence_state)
        if return_sentence_state:
            raise RuntimeError(
                "explicit compiled sentence state requires the serial "
                "per-word body")

        # A5 fullgraph fix (doc/plans/2026-06-06-parallel-conceptual-
        # recurrence.md sec 2 & 4): seed a FRESH per-forward STM working
        # buffer as a trace INTERMEDIATE before any stage touches the STM.
        # The STM accumulates the per-stage slabs WITHIN this forward
        # (parallel mode writes all N slots per stage via
        # ``_stm_set_all_slots``); seeding fresh here is identical to the
        # sentence-boundary clear it already starts from, but makes the
        # buffer a graph intermediate (not a mutated/output-aliased graph
        # input), which is the load-bearing fullgraph fix -- nothing with an
        # oscillating ``requires_grad`` survives across forwards. The live
        # grad threads through the ``folded`` slab the combine/loss hold.
        stm = (self.conceptualSpace.stm
               if self.conceptualSpace is not None else None)
        if stm is not None:
            in_ev = in_sub.materialize() if in_sub is not None else None
            B_stm = (int(in_ev.shape[0])
                     if in_ev is not None and torch.is_tensor(in_ev) else 1)
            dev_stm = (in_ev.device
                       if in_ev is not None and torch.is_tensor(in_ev)
                       else None)
            stm.begin_forward(B_stm, device=dev_stm)

        # Stage 10 (doc/plans/2026-05-27-perceptstore-meta-taxonomy-
        # reentrancy.md): PARALLEL mode walks the per-stage CS pipeline:
        #
        #   * Stage 0 ingests ``PS.pi(IS)`` as its contribution; the
        #     stage's owned ``sigma_in[0]`` folds it (inside
        #     ``cs.forward``).
        #   * Stage k > 0 ingests the PRIOR stage's CS output as its
        #     contribution; the stage's owned ``sigma_in[k]`` folds it.
        #     Additionally, ``sigma_cs[k]`` lifts the prior CS state
        #     (residual lift) and is added to the new contribution per
        #     the unified equation:
        #
        #       ``CS_t1[k] = sigma_in[k](contribution) + SS_t1[k]
        #                   + sigma_cs[k](CS_t0[k])``
        #
        #     PARALLEL: ``SS_t1[k] = 0`` per the plan's mode table; the
        #     legacy ``ws.forward(prevCS_forSS)`` call is preserved
        #     (the WS state contract still updates) but the WS
        #     contribution at C-space_role is the empty seed when the seed
        #     was empty.
        #
        # The merge step (when ``useGrammar=='all'``) halves N
        # between stages; the next stage's sigma_in is sized for that
        # halved shape at construction time.
        prevCS_forSS = self._empty_seed_ss
        last_cs = None
        # Run PS ONCE for stage-0 ingestion (subsymbolic is single-
        # pass per the locked decision; PS.pi(IS) is the canonical
        # contribution at stage 0).
        # Gate PartSpace's serial warm-path on pass 0.
        if self.symbolSpace is not None:
            self.symbolSpace.recur_pass = 0
        else:
            self.perceptualSpace._recurrent_pass_idx = 0
        PS_sub_stage0 = self.perceptualSpace.forward(in_sub)
        self.create_ir_mask(PS_sub_stage0)
        # Retain native row identities and their locations before binding.
        _part_input = getattr(self.perceptualSpace, '_forward_input', None)
        _part_ids = _part_input.get('native_indices', _part_input.get('indices')) if isinstance(_part_input, dict) else None
        _part_spans = _part_input.get('native_part_spans', _part_input.get('part_spans')) if isinstance(_part_input, dict) else None
        # ``contribution`` is the incoming subspace for each stage's
        # ``cs.forward``. Stage 0 -> PS output; stage k > 0 -> prior
        # stage's post-merge CS output.
        contribution = PS_sub_stage0
        # A4 (2026-06-06 parallel-conceptual-recurrence): per-stage augment
        # list, threaded as a LOCAL through the T stages and into the SAME
        # forward's reverse. NOT stored on any space/layer (the design's
        # data-flow rule; A5 makes the per-batch threading fully clean).
        # Composition starts from its own percepts and codes, never an estimate.
        carriers = []            # per-stage exact bind output (the FULL mix)
        prev_cs_stage = None     # P3: prior stage's cs (demux-feedback reads)
        for t, stage in enumerate(self.body_stages):
            cs = stage["cs"]
            ws = stage["ws"]
            # Preserve the recur_pass back-ref for any consumer that
            # still reads it (the AR-streaming warm-cache gate, sparse
            # state tests).
            if self.symbolSpace is not None:
                self.symbolSpace.recur_pass = int(t)
            else:
                self.perceptualSpace._recurrent_pass_idx = t
            # P4 stack selection: WS reads the pump pass for its per-pass pi
            # (plain host stamp -- byte-identical when the stack is off).
            object.__setattr__(ws, "_pump_pass_idx", int(t))
            # Dual-input plan sec.2 (rev. 2026-06-09): stage 0 reads the
            # UNITY view (parked by _lex_embed_stem) as direct symbolic
            # evidence -- the top-down analysis branch's input. Later
            # stages read only the recurrent CS (input once, mirroring
            # PS). Pure attr read, so the compiled/export paths trace it
            # exactly like _staged_in_sub.
            # Dual-towers rev 2: the universe bootstraps stage 0 ALWAYS and
            # drives every stage on the PARALLEL path (glue contract);
            # non-parallel t>0 stays carrier-driven (the live recurrent leg).
            _par = self.concept_order_limit > 0 and not self.word_brackets
            # Under trace the unity is a lifted constant that the export
            # config leaves unused (lift_constants_pass StopIteration);
            # the traced path takes the carrier -- numerically what the
            # pre-delivery export computed (its unity was all-zero).
            _u_ok = not (torch.compiler.is_compiling()
                         or torch.compiler.is_exporting())
            WS_sub = ws.forward(
                (self._staged_concepts_in
                 if (t == 0 and _u_ok) else None),
                cs_out=prevCS_forSS)
            # ``cs.forward`` does the STM push + the C->P / C->S handoff
            # bookkeeping and produces this stage's perception event CS_0
            # (STM bookkeeping, no parameterised fold). PRESERVED intact --
            # the combine only replaces the CONTENT advance below.
            CS_sub = cs.forward(contribution, WS_sub)
            # Park the all-siblings concept slab at the parallel pass (stage 0)
            # for the post-forward conceptual SBOW. Used only for the (no-grad)
            # nearest-row assignment, so a detached materialize suffices. Gated
            # on conceptualSimilarityScale > 0 so a config that does not train
            # the similarity codebook keeps a byte-identical forward.
            if (t == 0 and not self.word_brackets and not cs._sparse_active()
                    and float(getattr(getattr(self, "loss", None),
                                      "conceptual_similarity_scale", 0.0) or 0.0) > 0.0):
                # Sparse-inactive legacy park: detached t=0 slab (terminal-
                # codebook pool). Sparse-active parks LIVE at the POST-PUMP
                # cutover instead (P3): the SBOW situates the SETTLED
                # symbolic content, so the substitutability gradient reaches
                # the sparse family values and the snap (2026-07-02 plan C1).
                object.__setattr__(self, "_cs_parallel_slab",
                                   CS_sub.materialize().detach())
            if t == 0:
                # Asymmetric recon leg (input -> codebook): lift the
                # stage-0 WS codebook reconstruction term -- threaded by
                # ``_stage0_unity_forward`` as a forward-local -- onto the
                # pipeline-chained error container (CS_sub's errors object
                # is shared down to the OutputSpace via copy_context; the
                # fresh stage-0 WS subspace's is not).
                _ws_recon = getattr(ws, "_stage0_recon_loss", None)
                if (_ws_recon is not None and torch.is_tensor(_ws_recon)
                        and _ws_recon.requires_grad):
                    CS_sub.errors.add(
                        "ws_codebook_recon", _ws_recon, weight=1.0,
                        space="WholeSpace", category="symbol")
                object.__setattr__(ws, "_stage0_recon_loss", None)
                # Task 5 (C-13): lift the semantic-arrangement term the
                # same way (off unless <semanticArrangement> is set).
                _ws_sem = getattr(ws, "_stage0_semantic_loss", None)
                if (_ws_sem is not None and torch.is_tensor(_ws_sem)
                        and _ws_sem.requires_grad):
                    CS_sub.errors.add(
                        "ws_semantic_arrangement", _ws_sem, weight=1.0,
                        space="WholeSpace", category="symbol")
                object.__setattr__(ws, "_stage0_semantic_loss", None)
            else:
                # Step 1 (2026-06-10 symbolic-iteration plan): lift the
                # CS-leg recon gather the same way the stage-0 gather is
                # lifted at t==0 -- the winner row trains toward the
                # concept code that selected it. Same error name: Error
                # sums same-name terms, so multi-stage runs accumulate.
                _ws_recon = getattr(ws, "_csleg_recon_loss", None)
                if (_ws_recon is not None and torch.is_tensor(_ws_recon)
                        and _ws_recon.requires_grad):
                    CS_sub.errors.add(
                        "ws_codebook_recon", _ws_recon, weight=1.0,
                        space="WholeSpace", category="symbol")
                object.__setattr__(ws, "_csleg_recon_loss", None)
            # A4 conceptual combine: ONE square invertible 2-stream BIND
            # per stage (held by the cs) replaces the prior
            # ``cs.forward`` content fold + the WS.sigma (pi/sigma)
            # alternation (doc/plans/2026-06-06-parallel-conceptual-
            # recurrence.md sec. 3.3). Gated to the plain (non-grammar)
            # parallel path, matching the retired sigma gate -- the
            # useGrammar="all" cascade keeps its own N-halving ``merge``.
            #
            #   next_cs, aug_t = combine_t(PS_t, WS_t, CS_t)
            #
            # Option B: each stream is the FULL muxed event (sized at
            # ``cs.muxedSize``), so .where/.when PARTICIPATE in the combine.
            # PS_t is live ONLY at t=0 (alpha_ps reads the input once), WS_t
            # the WS event zero-padded to D, and CS_t the prior carrier event
            # (zeros at t=0). The advanced carrier ``next_cs`` (the full muxed
            # event) is written straight back into CS_sub -- the band is INSIDE
            # the transformed event now, not a tail riding along. The reverse
            # consumes the structured zero-pad (dropped) to invert the same
            # square map. (The retired ``reconstruct=perfect`` mode skipped the
            # combine -- only one stream live per stage, carrier carried
            # unchanged for an exact round-trip; when mixing is selected the
            # combine now always runs. Aligned binding takes the sibling path.)
            combine = (getattr(cs, "combine", None)
                       if self.bindingDepth >= 1
                       and "merge" not in stage else None)
            _aligned_binding = bool(
                getattr(self, "concept_binding", "mixing") == "aligned"
                and self.bindingDepth >= 1
                and "merge" not in stage)
            if combine is not None or _aligned_binding:
                # Processing contract (2026-06-10): the bind CALCULATION
                # lives on ConceptualSpace (``bind_streams``: demux / fit /
                # slot-stack / cascade / corpus-callosum glue / event
                # write); this loop only orchestrates. PS_t is the stage-0
                # percept re-fed at every stage; the full bind carrier
                # rides ON the stage's SubSpace (``_bind_carrier``) for the
                # reverse, with ``carriers`` kept as a test/verification
                # handle.
                ps_t = PS_sub_stage0 if t == 0 else contribution
                if t > 0 and not prevCS_forSS.is_empty():
                    # Top-down attention handoff (doc/specs/mereological-order-
                    # raising.md "the top-down attention handoff"): the stage-0
                    # WholeSpace passes back a scoped chunk/.where that scopes
                    # PartSpace's analysis on this t>0 pass (t==0 stays
                    # wide-open -- the first-pass-wide gate IS this t>0 guard).
                    # Dark unless a scope or words-category attention is engaged
                    # -> the pass-back action is "noop" -> byte-identical.
                    _prev_ps_fb = (getattr(prev_cs_stage, "_subspaceForPS", None)
                                   if prev_cs_stage is not None else None)
                    ps_t = self._passback_scope_ps(
                        t, ps_t, prevCS_forSS,
                        prevPS_forPS=_prev_ps_fb)
                # Slice C: the SS (symbol) bind leg comes from
                # ``SymbolSpace.forward_concept_to_symbol(CS_sub)`` -- the
                # ``.forward()``-mediated CS->SS transform (the dataflow rule:
                # cross-space interaction goes ONLY through ``forward``; the old
                # CS-mediated ``_build_symbol_leg`` reach into WholeSpace +
                # ``_model_symbolSpace`` is retired). Computed only under the
                # symbol tower in parallel mode -- the leg the 3-stream bind
                # consumes. Off-path (2-stream / symbol tower off) leaves it
                # None, so ``bind_streams`` never enters the SS branch ->
                # byte-identical. P3 two-phase forward: the SPARSE pump is
                # 2-stream -- NO symbol leg inside the loop (quantization only
                # at the post-pump cutover below); the concept_order_limit=0
                # symbolTower scaffold path keeps its in-loop leg untouched.
                SS_sub = (self.symbolSpace.forward_concept_to_symbol(CS_sub)
                          if (getattr(self, "symbol_tower", False)
                              and not self.word_brackets
                              and self.symbolSpace is not None
                              and not cs._sparse_active())
                          else None)
                if _aligned_binding:
                    full_t = cs.bind_aligned_streams(ps_t, WS_sub, CS_sub)
                else:
                    full_t = cs.bind_streams(
                        ps_t, WS_sub, CS_sub, SS_sub=SS_sub)
                if full_t is not None and t == 0:
                    # Snapshot the stage-0 bind so round-trip tests can
                    # compare it against the threaded carrier.
                    object.__setattr__(
                        self, "_combine_fwd_cs0", full_t.detach())
                carriers.append(full_t)
            # Stage 1.F: ``_cs_cache[t] = CS_sub`` retired. The
            # terminal C-space_role idea lives on ``conceptualSpace.stm``
            # (the bookkeeping push happens inside cs.forward); the
            # reverse path reads ``stm.snapshot()[:, -1, :]``.
            self._chart_compose_at_C(stage_idx=t)
            if "merge" in stage:
                CS_sub = stage["merge"](CS_sub)
            # Read the two C views after the optional merge (merge
            # mutates the CS subspace in place; the C->S view aliases
            # it so it reflects post-merge N). The cross-pass handoff
            # lives directly on the persistent ``cs._subspaceForPS`` /
            # ``cs._subspaceForWS`` SubSpaces (mutated in place by
            # ConceptualSpace.forward).
            prevCS_forSS = cs._subspaceForWS
            # "Nothing to quantize -> pass zeros": WS is inert when its
            # input was the empty seed (bindingDepth=1, or pass 0).
            # CS already consumed WS_sub as-is above (pass-0 math
            # unchanged); the correctly-batched zero symbol is
            # produced here so the symbol-state contract holds for
            # the head / discourse.
            if WS_sub.is_empty():
                WS_sub = self._zero_symbol_subspace(ws, in_sub)
            # Stage 1.F: ``_ws_cache[t] = WS_sub`` retired. The
            # terminal symbolic state lives on
            # ``self.wholeSpace.subspace`` (written by
            # ``ws.forward(...)``); ``symbol_cache`` resolves there.
            self._read_subsymbolic_field(_part_ids, _part_spans, t)
            last_cs = CS_sub
            # Cascade: this stage's (symbolically generalized) output
            # becomes the next stage's contribution -- the MIX goes UP
            # (the demux feedback above sends the un-mix DOWN per tower).
            contribution = CS_sub
            prev_cs_stage = cs
        # P3 LATE CUTOVER (two-phase forward): the pump above stayed purely
        # continuous/subsymbolic; NOW -- once, at the bandwidth seam -- read
        # native feature memberships into order-0 concepts and run the
        # symbolic phase (``cs_symbolic_phase``). The activations stamp the
        # terminal CS (the SS leg + head-side losses read them); the settled
        # symbolic content feeds the conceptual SBOW (C1, live). The cutover
        # cs is the definition owner used by word admission and the grammar;
        # concept_order_limit=0 (incl. the symbolTower scaffold) never
        # enters -- byte-identical.
        _cut_cs = self._concept_owner()
        if (last_cs is not None and _cut_cs is not None
                and _cut_cs._sparse_active()):
            _settled = last_cs.materialize()
            # Relevance integration (sec C, UNCONDITIONAL 2026-07-12): the
            # priming surface is always warm (``_prime_seen_step``), so the
            # pyramid's top-K always reads the boost-1 ranking bias -- zero
            # (neutral) until primes accumulate. no_grad -- relevance
            # selects, never trains.
            _prio = self._assemble_relevance_priority(
                _cut_cs, prev_cs_stage, last_cs, _settled)
            object.__setattr__(_cut_cs, "_relevance_priority", _prio)
            _percepts = getattr(self, '_subsymbolic_percepts', None)
            _content, _acts = _cut_cs.cs_symbolic_phase(
                _settled, extents=getattr(_cut_cs, '_cs_field_where', None),
                percepts=_percepts, a_0=getattr(self, '_subsymbolic_field', None))
            # SEEN write moved to ``_prime_seen_step`` (unconditional, once
            # per batch, both paths) -- awareness primes (simplified law).
            assert _acts is None or (
                _acts.ndim == 4 and _acts.shape[-1] == 2
                and int(_acts.shape[0]) == sum(_cut_cs._field_caps())), (
                'symbolic phase requires [store span, batch, occurrence, 2]')
            object.__setattr__(last_cs, '_concept_activations', _acts)
            object.__setattr__(last_cs, '_concept_ids', _cut_cs._cs_field_concept_ids.detach().clone())
            object.__setattr__(last_cs, '_concept_inventory_rows', _cut_cs._cs_field_rows.detach().clone())
            object.__setattr__(last_cs, '_thought_occurrence', None)
            object.__setattr__(last_cs, '_concept_code_owner',
                               next(i for i, cs in enumerate(self.conceptualSpaces) if cs is _cut_cs))
            for name in ('where', 'when'):
                object.__setattr__(last_cs, '_concept_' + name,
                                   getattr(_cut_cs, '_cs_field_' + name, None))
            if _acts is not None:
                object.__setattr__(last_cs, '_concept_codes',
                                   _cut_cs._field_codes(_cut_cs.similarity_codebook.getW()).detach())
            if _acts is not None:
                # The SS leg, ONCE: syncs the SS codebook to the settled
                # concept codes; the leg's gradient rides the activations.
                if (getattr(self, "symbol_tower", False)
                        and self.symbolSpace is not None):
                    self.symbolSpace.forward_concept_to_symbol(last_cs)
                # SBOW C1 on the SETTLED symbolic slab (grad-bearing; the
                # pool is the SAME dictionary that composed it).
                if float(getattr(getattr(self, "loss", None),
                                 "conceptual_similarity_scale", 0.0)
                         or 0.0) > 0.0:
                    object.__setattr__(self, "_cs_parallel_slab", _content)
                    object.__setattr__(self, "_cs_parallel_slab_cs", _cut_cs)
        # A4: thread the per-stage augments to the reverse as a transient
        # local on ``self`` that the SAME forward's reverse reads (the
        # design's accepted near-term threading; A5 makes per-batch data
        # threading fully clean). ``object.__setattr__`` matches the CS
        # handoff idiom -- avoids mutating ``self._modules`` under the
        # torch.compile guards. ``_combine_last_cs_sub`` lets a caller
        # (e.g. the perfect-reconstruction test) reproduce CS_0 by driving
        # ``_reverse_body`` from the terminal carrier.
        # 2-stream bind (C-10): the augment thread is GONE -- the carrier
        # IS the whole bind, so the reverse needs nothing alongside it.
        object.__setattr__(self, "_combine_carriers", carriers)
        object.__setattr__(self, "_combine_last_cs_sub", last_cs)
        # Reset so standalone PartSpace.forward calls (and the
        # next forward's pass 0) see the AR-streaming serial warm path.
        if self.symbolSpace is not None:
            self.symbolSpace.recur_pass = 0
        else:
            self.perceptualSpace._recurrent_pass_idx = 0
        if self.loss_head is not None:
            # Prefer the grad-bearing per-word stack stashed by
            # ``_forward_stem_per_word``; fall back to the (detached)
            # STM snapshot when the stack is missing (e.g. body-only
            # forward path that bypasses the per-word stem).
            grad_input = self._loss_head_input
            if grad_input is None:
                grad_input = self.conceptualSpace.stm.snapshot()
            if grad_input is not None:
                self._loss_head_loss = self.loss_head(grad_input)
            else:
                self._loss_head_loss = None
        return last_cs

    # ------------------------------------------------------------------
    # 2b-2-i: bounded binary grammar producer (STM -> single S).
    # ------------------------------------------------------------------
    def _reconstruction_stack(self):
        """Return the SymbolSpace-owned sentence construction trace."""
        owner = getattr(self, "symbolSpace", None)
        return getattr(owner, "reconstruction_stack", None)

    def _stage_reconstruction_teacher(self):
        """Stage detached surface targets before any compiled sentence body."""
        trace = self._reconstruction_stack()
        isp = getattr(self, "inputSpace", None)
        if trace is None or isp is None or not getattr(self, "word_brackets", False):
            return
        trace.begin_sentence()
        leaves = getattr(isp, "_ar_embedded_N", None)
        if torch.is_tensor(leaves) and leaves.dim() == 3:
            trace.store_leaves(leaves)
        word_mask = getattr(isp, "_word_active_mask", None)
        word_ids = getattr(isp, "_ar_word_concept_ids", None)
        if (torch.is_tensor(word_ids) and word_ids.dim() == 2
                and torch.is_tensor(word_mask)
                and tuple(word_mask.shape) == tuple(word_ids.shape)):
            trace.store_words(word_ids, word_mask & (word_ids >= 0))
        part_ids = getattr(isp, "_ar_word_part_ids", None)
        part_mask = getattr(isp, "_ar_word_part_mask", None)
        if (torch.is_tensor(part_ids) and part_ids.dim() == 3
                and torch.is_tensor(part_mask)
                and tuple(part_mask.shape) == tuple(part_ids.shape)):
            trace.store_word_parts(part_ids, part_mask)

    def _prepare_reconstruction_choices(self, batch, word_width, device):
        """Prepare the fixed operation trace outside a captured word loop."""
        object.__setattr__(self, "_recon_completed", False)
        object.__setattr__(self, "_reconstruction_product", None)
        trace = self._reconstruction_stack()
        language = getattr(getattr(self, "symbolSpace", None),
                           "languageLayer", None)
        stm = getattr(getattr(self, "conceptualSpace", None), "stm", None)
        if trace is None or language is None:
            return
        unary = (getattr(language, "_unary_rule_ids", {}) or {}).get(
            "CS", ())
        binary = (getattr(language, "_binary_rule_ids", {}) or {}).get(
            "CS", ())
        cap = int(getattr(stm, "capacity", 1) or 1)
        # Three joint operation rounds per word. Each word column also owns
        # 2*cap boundary rounds; ordinary one-sentence
        # input uses only the first such group, while packed input writes the
        # group attached to every row-local sentence end. The fixed slab keeps
        # the compiled graph identical across packed/non-packed calls.
        max_steps = (
            3 * int(word_width)
            + int(word_width) * max(1, 2 * cap))
        trace.prepare_choices(
            int(batch), max_steps, device=device,
            unary_rule_ids=unary, binary_rule_ids=binary)
        active = getattr(self.inputSpace, '_word_active_mask', None)
        trace._choice_sentence_ids = trace._last_sentence_id = None
        trace._relative_rule_ids = self.languageSpace._relative_cs_rule_ids
        if torch.is_tensor(active) and active.shape == (int(batch), int(word_width)):
            trace._choice_sentence_ids, _, trace._last_sentence_id = self._compose_round_owners(
                trace._choice_rule_ids)


    def _stm_reducer(self):
        """The one model-owned operation layer, also used by parallel compose."""
        language = getattr(getattr(self, 'symbolSpace', None), 'languageLayer', None)
        return getattr(language, 'operation_layer', None)




    def _record_unit_pulls(self, ws):
        """After the ladder stem: each unit's rung-0 code pulls on every
        property row its bytes hold (the LBG accumulation of contract 2),
        with the unit's bytes for predicate acquisition.  Eager, bounded by
        the number of units; no-op off the canonical path."""
        ps = getattr(self, "perceptualSpace", None)
        if ws is None or ps is None or not getattr(ps, "_meronomy", False):
            return
        if not hasattr(ws, 'record_property_pull'):
            return
        fi = getattr(ps, "_forward_input", None) or {}
        texts = fi.get("word_texts"); codes = getattr(ps, "_embedded_input", None)
        if not texts or not torch.is_tensor(codes) or codes.dim() != 3:
            return
        primitive = ws.subspace.what.primitive_properties
        n_what = int(getattr(ws, "nWhat", codes.shape[-1]) or codes.shape[-1])
        # Which rows a byte holds: one [256, R] host table (the same
        # predicate LUT the tiling uses), so a unit's rows are a lookup.
        n_rows = int(primitive.members.shape[0])
        lut = ws._build_predicate_byte_lut(n_rows) if n_rows > 0 and hasattr(
            ws, "_build_predicate_byte_lut") else None
        if lut is None or not lut.numel():
            return
        unit_rows, unit_codes, unit_bytes = [], [], []
        for b, row_texts in enumerate(texts):
            for w, text in enumerate(row_texts):
                if w >= int(codes.shape[1]) or not text:
                    continue
                bv = list(text.encode("latin1", "replace"))
                held = lut[torch.tensor(bv, dtype=torch.long, device="cpu") & 0xFF].any(dim=0)
                held_rows = held.nonzero().reshape(-1).tolist()
                if not held_rows:
                    continue
                unit_rows.append(held_rows)
                unit_codes.append(codes[b, w, :n_what])
                unit_bytes.append(bv)
        if unit_rows and hasattr(ws, "record_property_pulls"):
            ws.record_property_pulls(unit_rows, torch.stack(unit_codes, dim=0), unit_bytes)

    def _concept_owner(self):
        """The grammar's shared identity owner, including unshared bodies.

        An unshared multi-stage body gives the grammar its terminal space.
        Word definitions must use that same allocator as clause endings;
        stage-local integer IDs are not interchangeable in the common store.
        Before registry construction the shared aligned owner is stage zero.
        """
        registry = getattr(self, "grammatical_thoughts", None)
        owner = getattr(registry, "space", None)
        if owner is not None:
            return owner
        spaces = list(getattr(self, "conceptualSpaces", None) or ())
        return spaces[0] if spaces else getattr(self, "conceptualSpace", None)

    def _chunk_op_index(self):
        cached = self.__dict__.get("_chunk_op_index_cached", None)
        if cached is not None:
            return cached if cached >= 0 else None
        reducer = self._stm_reducer()
        names = list(getattr(reducer, "op_names", None) or []) if reducer is not None else []
        idx = names.index("chunk") if "chunk" in names else -1
        self.__dict__["_chunk_op_index_cached"] = idx
        return idx if idx >= 0 else None

    _WHITESPACE_BYTES = (9, 10, 11, 12, 13, 32)

    def _observe_word_units(self, concepts_in, unit_rows):
        """Word-unit assurance (Alec 2026-09-11): with the analysis tiling
        learned rather than fixed, count how many whitespace-delimited
        words of the presentation are exactly one staged unit.  Host
        bookkeeping on the eager stem (the unit rows are already host
        lists); reported per epoch as ``word units`` and readable through
        :meth:`word_unit_fraction`."""
        if unit_rows is None or not torch.is_tensor(concepts_in):
            return
        rows = concepts_in.reshape(int(concepts_in.shape[0]), -1)
        rows = rows.detach().to("cpu").to(torch.long).tolist()
        words = hits = letter_words = letter_hits = 0
        for b, values in enumerate(rows):
            units = set(unit_rows[b]) if b < len(unit_rows) else set()
            start = None
            for i, v in enumerate(values + [0]):
                inside = v > 0 and v not in self._WHITESPACE_BYTES
                if inside and start is None:
                    start = i
                elif not inside and start is not None:
                    one_unit = int((start, i) in units)
                    words += 1
                    hits += one_unit
                    # Letters-only words: the tokens the canonical tiling
                    # must keep whole (punctuation and digits are units of
                    # their own by design, so "word," is two units).
                    if all(chr(c).isalpha() for c in values[start:i]):
                        letter_words += 1
                        letter_hits += one_unit
                    start = None
        stats = self.__dict__.setdefault("_word_unit_stats", [0, 0, 0, 0])
        stats[0] += words
        stats[1] += hits
        stats[2] += letter_words
        stats[3] += letter_hits

    def word_unit_fraction(self):
        """Fraction of whitespace-delimited words staged as exactly one
        unit since the counters were last reset (``None`` before any)."""
        stats = self.__dict__.get("_word_unit_stats")
        if not stats or stats[0] <= 0:
            return None
        return float(stats[1]) / float(stats[0])

    def letter_word_unit_fraction(self):
        """The same fraction over letters-only words (``None`` before any)."""
        stats = self.__dict__.get("_word_unit_stats")
        if not stats or len(stats) < 4 or stats[2] <= 0:
            return None
        return float(stats[3]) / float(stats[2])

    def _word_unit_report(self):
        """``word units A% of N words (letters-only B% of M)`` or ``""``."""
        wu = self.word_unit_fraction()
        if wu is None:
            return ""
        stats = self.__dict__["_word_unit_stats"]
        text = f"word units {100.0 * wu:.1f}% of {stats[0]} words"
        lw = self.letter_word_unit_fraction()
        if lw is not None:
            text += f" (letters-only {100.0 * lw:.1f}% of {stats[2]})"
        return text

    def reset_word_unit_stats(self):
        self.__dict__["_word_unit_stats"] = [0, 0, 0, 0]

    def _ensure_chunk_machinery(self):
        """Eager (pre-loop) allocation of every tensor the ``chunk`` gate
        reads inside the word loop (fold-ladder plan, Phase 2b): the learned
        prior parameter (registered with the live optimizer once), the STM
        provenance slab, the proposal slab and the phrase-row table.  No
        allocation or host sync then happens inside the compiled body."""
        owner = self._concept_owner()
        if owner is None:
            return
        if self._chunk_op_index() is not None:
            bias = owner.ensure_chunk_prior() if hasattr(owner, "ensure_chunk_prior") else None
            if torch.is_tensor(bias) and not self.__dict__.get("_chunk_prior_registered"):
                self.__dict__.setdefault("_fresh_synthesis_params", []).append(bias)
                self.__dict__["_chunk_prior_registered"] = True
        # The slabs exist whether or not the grammar has a chunk op: the
        # compiled word loop carries them regardless, and an attribute that
        # first appears inside a compiled call fails the next call's guard
        # (measured: one extra compile of the word loop).
        stm = getattr(self.conceptualSpace, "stm", None)
        if stm is None or not torch.is_tensor(getattr(stm, "_buffer", None)):
            return
        # On the device and batch the word loop runs on (the staged word
        # slab), not the STM's current buffer (still the previous batch's,
        # or the construction-time CPU seed): a slab reallocated inside the
        # compiled call changed its guard and recompiled the loop.
        slab = getattr(self.inputSpace, "_ar_embedded_N", None)
        if not torch.is_tensor(slab):
            return
        device, batch = slab.device, int(slab.shape[0])
        wholes = getattr(stm, "_wholes", None)
        shape = (batch, int(stm.capacity), 3)
        if (not torch.is_tensor(wholes) or tuple(wholes.shape) != shape
                or wholes.device != device):
            stm._wholes = torch.full(shape, -1, dtype=torch.long, device=device)
        if hasattr(owner, "ensure_chunk_proposal_state"):
            owner.ensure_chunk_proposal_state(batch, device)
            owner.chunk_row_table(device)

    def _unit_provenance(self, p, B, device):
        """``(whole, unit, clause)`` ``[B]`` longs of loop position ``p``
        from the staged tiling ladder (``-1`` when no ladder is staged)."""
        ws0 = (self.wholeSpaces[0]
               if getattr(self, "wholeSpaces", None) else self.wholeSpace)
        parent = getattr(ws0, "_staged_unit_parent", None)
        clause = getattr(ws0, "_staged_unit_clause", None)
        minus = torch.full((B,), -1, dtype=torch.long, device=device)
        if not torch.is_tensor(parent) or p >= int(parent.shape[1]):
            return minus, minus, minus
        unit = torch.full((B,), int(p), dtype=torch.long, device=device)
        whole = parent[:, p].to(device=device, dtype=torch.long)
        clause_col = (clause[:, p].to(device=device, dtype=torch.long)
                      if torch.is_tensor(clause) and p < int(clause.shape[1])
                      else minus)
        return whole, unit, clause_col

    def _push_unit_provenance(self, stm, commit_b_1, p):
        """Eager push of loop position ``p``'s provenance on the STM slab."""
        wholes = stm.ensure_whole_state()
        B = int(wholes.shape[0])
        whole, unit, clause = self._unit_provenance(p, B, wholes.device)
        stm._wholes = ShortTermMemory.functional_wholes_push(
            wholes, commit_b_1.reshape(B), whole, unit, clause)

    def _chunk_structural_prior(self, wholes, B, window):
        """``[B, 1, R]`` additive logits: ``chunk`` is licensed (the learned
        bias) on a pair the analysis tiling places in one coarser whole and
        forbidden elsewhere (fold-ladder plan, Phase 2b), read from the STM
        provenance slab ``wholes`` ``[B, cap, 3]``.  ``None`` when the
        grammar has no chunk op or the prior is not built.  Pure tensor
        arithmetic: the same code runs eagerly and under ``while_loop``."""
        idx = self._chunk_op_index()
        if idx is None or not torch.is_tensor(wholes):
            return None
        owner = self._concept_owner()
        bias = getattr(owner, "chunk_prior", None)
        if not torch.is_tensor(bias):
            return None
        reducer = self._stm_reducer()
        R = int(reducer.r_reduce)
        same = ShortTermMemory.same_whole(wholes)
        column = torch.zeros(R, dtype=window.dtype, device=window.device)
        column = column.scatter(
            0, torch.tensor([idx], device=window.device),
            torch.ones(1, dtype=window.dtype, device=window.device))
        forbidden = torch.full(
            (), -1e4, dtype=window.dtype, device=window.device)
        gate = torch.where(same, bias.to(window.dtype), forbidden)
        return gate.reshape(B, 1, 1) * column.reshape(1, 1, R)

    def _chunk_reduce_provenance(self, wholes, op_b, can_b, prop_slab, prop_count,
                                 table=None):
        """Pure, fixed-shape bookkeeping of one top-2 fold (contract 7):

        * a ``chunk`` chosen on a same-whole pair whose units carry concept
          ids is appended to the proposal slab (counted and possibly admitted
          at ``Reset``);
        * an already admitted pair yields its phrase row (``-1`` otherwise);
        * the provenance slab folds (shared whole/clause kept, else ``-1``).

        Returns ``(wholes', phrase_row [B], prop_slab', prop_count')``.
        """
        B = int(wholes.shape[0])
        idx = self._chunk_op_index()
        ids = getattr(self.inputSpace, "_ar_word_concept_ids", None)
        phrase_row = torch.full(
            (B,), -1, dtype=torch.long, device=wholes.device)
        if idx is not None and torch.is_tensor(ids) and int(ids.shape[1]) > 0:
            cs = self._concept_owner()
            same = ShortTermMemory.same_whole(wholes)
            units = ShortTermMemory.newest_units(wholes)          # [B, 2]
            W = int(ids.shape[1])
            valid_units = torch.logical_and(units >= 0, units < W).all(dim=1)
            safe = units.clamp(0, W - 1)
            ids_dev = ids.to(device=wholes.device, dtype=torch.long)
            members = ids_dev.gather(1, safe)                     # [B, 2]
            valid = torch.logical_and(
                valid_units, (members >= 0).all(dim=1))
            chunked = torch.logical_and(
                can_b.reshape(B).to(torch.bool),
                torch.logical_and(op_b.reshape(B) == idx, same))
            write = torch.logical_and(chunked, valid)
            shared = ShortTermMemory.shared_whole(wholes)
            prop_slab, prop_count = cs.functional_chunk_propose(
                prop_slab, prop_count, write,
                members[:, 0], members[:, 1], shared)
            if not torch.is_tensor(table):
                table = getattr(cs, "_chunk_row_table", None)
            if not torch.is_tensor(table):
                table = cs.chunk_row_table(wholes.device)
            table = table.to(device=wholes.device)
            rows = cs.lookup_chunk_rows(table, members[:, 0], members[:, 1])
            phrase_row = torch.where(write, rows, phrase_row)
        next_wholes = ShortTermMemory.functional_wholes_reduce(wholes, can_b)
        return next_wholes, phrase_row, prop_slab, prop_count



    def _stm_operation_step(self, protect_depth=None, row_gate=None, trace_slot=None,
                            allowance=None, rounds_left=None):
        """One operation over the newest two slots; fixed shape in both modes."""
        stm = self.conceptualSpace.stm
        if self._stm_reducer() is None:
            return torch.zeros_like(stm._depth, dtype=torch.bool)
        stm.ensure_order_state(); stm.ensure_reference_state()
        # A compiled owner assignment may replay as copy_ into its prior
        # storage. The choice backward needs this round's values after later
        # rounds commit, so each operation owns an immutable input snapshot.
        state = tuple(value.clone() for value in (
            stm._buffer, stm._depth, stm._orders, stm._grammar_orders,
            stm._concept_rows, stm._concept_activations))
        B = state[0].shape[0]
        gate = (state[1] > 0 if row_gate is None else row_gate.reshape(B).bool())
        slots = 1 if protect_depth is None else protect_depth
        history = getattr(stm, "_last_unary", None)
        if history is None or history.shape != state[0].shape[:2]:
            history = torch.full_like(state[2], -1)
        else:
            previous_depth = stm._unary_history_depth
            pushed = (state[1] - previous_depth).clamp_min(0)
            positions = torch.arange(history.shape[1], device=history.device)[None]
            source = positions - pushed[:, None]
            history = torch.where((source >= 0) & (state[1] >= previous_depth)[:, None],
                history.gather(1, source.clamp_min(0)), -1)
        choice = self.languageSpace.choose_operation(
            state, gate, slots=slots, allowance=allowance, rounds_left=rounds_left,
            previous_unary=history, sample=False,
            masked_action=self._compose_masked_action(trace_slot, state[1]),
            replay_action=self._compose_replayed_action(trace_slot, state[1]),
            op_prior=self._chunk_structural_prior(stm.ensure_whole_state(), B, state[0]))
        next_state = self.conceptualSpace.apply_language_choice(state, choice)
        stm._last_unary = self.languageSpace.update_unary_history(history, choice)
        stm._unary_history_depth = next_state[1]
        scope = self.languageSpace.clause_scope
        stm._clause_state, closing_kind = scope.apply(stm.ensure_clause_state(), choice,
            torch.as_tensor(0 if trace_slot is None else trace_slot, device=state[0].device))
        next_state = scope.publish_name(next_state, stm._clause_state, closing_kind)
        (stm._buffer, stm._depth, stm._orders, stm._grammar_orders,
         stm._concept_rows, stm._concept_activations) = next_state
        self._record_operation_choice(trace_slot, choice, state)
        binary = choice.applied & (choice.kind == 1)
        if not torch.compiler.is_compiling():
            trace = self._reconstruction_stack()
            if trace is not None and bool(binary.any()):
                count = int(self._stm_reducer().r_reduce)
                selected = torch.nn.functional.one_hot(choice.local_op.clamp(0, count - 1), count).to(state[0].dtype)
                trace.record_reduction(selected[:, None, :], binary)
        owner = self._concept_owner()
        slab, count = owner.ensure_chunk_proposal_state(B, state[0].device)
        stm._wholes, phrase, owner._chunk_prop_slab, owner._chunk_prop_count = self._chunk_reduce_provenance(
            stm.ensure_whole_state(), choice.local_op, binary, slab, count)
        (_, _, _, _, stm._concept_rows, stm._concept_activations) = self.conceptualSpace.apply_phrase_rows(
            next_state, phrase, binary)
        if not torch.compiler.is_compiling():
            stm._max_depth_host = int(stm._depth.max())
        return choice.applied

    def _compose_admission(self, gate):
        stm = self.conceptualSpace.stm
        torch._assert_async((~gate.reshape(-1) | (stm._depth < int(stm.capacity))).all(),
                            'compose admission reached a full stack despite its reduction deadline')
        return gate

    def _stm_word_rounds(self, gate, word):
        from Language import sentence_row_slots
        active = gate.reshape(-1).bool()
        for index in range(3):
            relative = self._sentence_relative_mask(active.shape[0], device=active.device, word=word)
            slots = sentence_row_slots(relative)
            applied = self._stm_operation_step(
                protect_depth=slots, row_gate=active, trace_slot=3 * word + index,
                allowance=int(self.conceptualSpace.stm.capacity) - 1, rounds_left=3 - index)
            active = active & applied

    def _compose_masked_action(self, slot, like):
        return self._compose_action_constraint(slot, like, '_compose_forced_slots')

    def _compose_replayed_action(self, slot, like):
        return self._compose_action_constraint(slot, like, '_compose_prefix_slots')

    def _compose_action_constraint(self, slot, like, constraint):
        actions = getattr(self, '_compose_exploit_actions', None)
        forced = getattr(self, constraint, None)
        if slot is None or actions is None or forced is None:
            return None
        index = torch.as_tensor(slot, device=like.device, dtype=torch.long).reshape(-1, 1).expand(actions.shape[0], 1)
        chosen = actions.gather(1, index.clamp(0, actions.shape[1] - 1)).reshape(-1)
        mask = forced.gather(1, index.clamp(0, forced.shape[1] - 1)).reshape(-1)
        return torch.where(mask, chosen, -1)

    def _exploration_prefix_slots(self, actions, forced, owners):
        """Chronological prefix per sentence, including interleaved closing slots.

        Neither trial has updated the parameters yet. Replaying the hard
        choices preserves the zero-temperature counterfactual's prefix,
        while recomputing candidates and their live credit for its own graph.
        """
        words = self.inputSpace._word_active_mask.shape[1]
        closing = max(1, 2 * int(self.conceptualSpace.stm.capacity))
        order = []
        for word in range(words):
            order.extend(range(3 * word, 3 * word + 3))
            if word + 1 < words:
                begin = 3 * words + (word + 1) * closing
                order.extend(range(begin, begin + closing))
        order.extend(range(3 * words, 3 * words + closing))
        order = [slot for slot in order if slot < actions.shape[1]]
        ranks = torch.tensor(order, device=actions.device).argsort()[None, :]
        prefix = torch.zeros_like(forced)
        for sid in range(int(owners.max().detach()) + 1):
            chosen = torch.where(forced & (owners == sid), ranks, actions.shape[1]).amin(1)
            prefix |= (owners == sid) & (ranks < chosen[:, None]) & (actions >= 0)
        return prefix

    def _record_operation_choice(self, slot, choice, state):
        trace = self._reconstruction_stack()
        if slot is None or trace is None:
            return
        B = state[0].shape[0]
        ids = torch.full((B,), -1, dtype=torch.long, device=state[0].device)
        for kind, arity in ((1, 2), (2, 1)):
            mapping = trace.rule_map(arity)
            if mapping.numel():
                chosen = mapping.index_select(0, choice.local_op.clamp(0, mapping.numel() - 1))
                ids = torch.where(choice.applied & (choice.kind == kind), chosen, ids)
        trace._choice_rule_ids[:, slot] = ids
        trace._choice_arities[:, slot] = torch.where(choice.applied,
            torch.where(choice.kind == 1, 2, 1), 0).to(torch.int8)
        trace._choice_mask[:, slot] = choice.applied
        trace._choice_positions[:, slot] = choice.position
        trace._choice_actions[:, slot] = choice.action
        trace._choice_attempted[:, slot] = choice.valid
        trace._choice_explorable[:, slot] = (choice.valid if choice.alternatives is None else choice.alternatives)
        if getattr(trace, '_choice_alternative_counts', None) is None:
            trace._choice_alternative_counts = torch.zeros_like(trace._choice_actions)
        trace._choice_alternative_counts[:, slot] = (choice.alternative_count
            if choice.alternative_count is not None else trace._choice_explorable[:, slot].long())
        trace._choice_left_rows, trace._choice_right_rows = self._tensor_record_operands(
            trace._choice_left_rows, trace._choice_right_rows,
            torch.as_tensor(slot, device=state[0].device), state,
            choice.applied & (choice.kind == 1))
        if not torch.compiler.is_compiling():
            self.languageSpace.record_category_observations(
                trace, getattr(self.inputSpace, '_word_active_mask', None))


    def _sentence_relative_mask(self, B, device=None, word=None):
        """Relative-row capacity from the actual, sentence-scoped hard choices.

        Existing explicit grammar plans remain readable. Serial composition
        uses its selected operation trace, with the same closed-class anchor
        condition. It never reruns a parser to infer choices.
        """
        from Language import sentence_relative_mask
        stm = getattr(getattr(self, 'conceptualSpace', None), 'stm', None)
        scope = getattr(getattr(self, 'languageSpace', None), 'clause_scope', None)
        clause_state = getattr(stm, '_clause_state', None)
        if scope is not None and torch.is_tensor(clause_state) and clause_state.shape[0] == B:
            return scope.slots(clause_state, stm._depth) == 3
        owner = getattr(self, 'symbolSpace', None)
        trace = self._reconstruction_stack()
        ids = getattr(trace, '_choice_rule_ids', None)
        valid = getattr(trace, '_choice_mask', None)
        if not torch.is_tensor(ids) or ids.shape[0] != B or not torch.is_tensor(valid):
            return sentence_relative_mask(owner, B, device=device)
        active = getattr(self.inputSpace, '_word_active_mask', None)
        if torch.is_tensor(active) and active.shape[0] == B:
            owners, sentences, last = self._compose_round_owners(ids)
            selected = last if word is None else sentences[:, word:word + 1]
            valid = valid & (owners == selected)
        from Language import sentence_anchor_mask
        return self.languageSpace.relative_from_choices(ids, valid,
            sentence_anchor_mask(owner, B, device=device))

    def _stm_reduce_to_single_S(self):
        """Run the fixed closing budget, admitting STOP only when the row fits.

        An unfinished forest remains a training result. Its depth is tagged
        negative at the publication boundary so it cannot become a program
        or a memory row.
        """
        from Language import sentence_row_slots
        stm = self.conceptualSpace.stm
        cap = int(stm.capacity)
        buf = stm._buffer
        B = buf.shape[0]
        device = buf.device
        # Reset SymbolSpace's grammatical-choice trace per sweep so it covers
        # exactly the folds that build THIS root S.  A sentence-scoped trace
        # already began at sentence start so online folds are
        # retained and this reset stands down.
        if not torch.compiler.is_compiling():
            trace = self._reconstruction_stack()
            if trace is not None and not trace.reductions_sentence_scoped:
                trace.begin_reductions(sentence_scoped=False)
        protect_depth = sentence_row_slots(self._sentence_relative_mask(B, device=device))
        # A positive syntacticOrder caps the fixed operation-round budget;
        # a budget too small at phase start can still leave an incomplete forest.
        _syn = int(getattr(self, "syntacticOrder", 0) or 0)
        _n_levels = max(1, 2 * cap)
        if _syn > 0:
            _n_levels = min(_n_levels, _syn)
        _grammar_boundary_demand = bool(
            getattr(self, "serial_object_meta", False)
            and getattr(self, "serial_word_capacity", None) is not None)
        _trace_word_slab = getattr(self.inputSpace, "_ar_embedded_N", None)
        _trace_word_count = (
            int(_trace_word_slab.shape[1])
            if torch.is_tensor(_trace_word_slab) else 0)
        _closing_active = stm._depth > 0
        for _closing_index in range(_n_levels):
            protect_depth = sentence_row_slots(self._sentence_relative_mask(B, device=device))
            _trace_slot = (
                3 * _trace_word_count + _closing_index
                if _trace_word_count > 0 else None)
            _operated = self._stm_operation_step(
                protect_depth=protect_depth, row_gate=_closing_active, trace_slot=_trace_slot,
                allowance=protect_depth, rounds_left=_n_levels - _closing_index)
            _closing_active = _closing_active & _operated
        protect_depth = sentence_row_slots(self._sentence_relative_mask(B, device=device))
        complete = (stm._depth <= protect_depth) & (stm._depth > 0)
        self._compose_complete = complete
        # Slot depth-1 is the oldest surviving constituent; incomplete
        # forests are flagged at publication rather than declared roots.
        post_depth = stm._depth
        B = int(stm._buffer.shape[0])
        rows = torch.arange(B, device=stm._buffer.device)
        root_idx = (post_depth - 1).clamp(min=0)            # [B]
        S = stm._buffer[rows, root_idx]                     # [B, D]
        return S, torch.where(complete, post_depth, -post_depth.clamp_min(1))

    def _maybe_concept_index_read(self, idea_bd):
        """Replace ``idea_bd``'s content slice with the word's already-known
        OBJECT-concept row (snap design doc §ontology; Alec: the forward
        folds object concepts — Method-2 un-folds into object concepts and
        TRANSLATES them back to word concepts, the exact reverse). Sources
        the promoted percept id per batch row from the per-word PS forward's
        index grid (the same PS codes ``interpret`` tied at
        mint), resolves each to its object-concept's ``similarity_codebook``
        row, and writes the re-normalized row into the content dims —
        keeping the ``.where`` / ``.when`` bands (placement is untouched).
        Untied rows keep the computed idea (mask). Best-effort: any failure
        returns ``idea_bd`` unchanged (never break the forward)."""
        try:
            # Resolve against the CS that HOLDS the reverse index — the
            # autobind runs on a per-stage/terminal CS instance that may
            # differ from ``self.conceptualSpace`` (multi-stage towers;
            # same pattern as recognized_word_rows in the un-fold).
            cs = self.conceptualSpace
            for _c in (list(getattr(self, "conceptualSpaces", []) or [])
                       or [cs]):
                if _c._definition_index() is not None and _c.definitions.word_ids:
                    cs = _c
                    break
            ps = self.perceptualSpace
            fi = getattr(ps, "_forward_input", None) or {}
            idxg = fi.get("indices")
            if not torch.is_tensor(idxg) or idxg.dim() < 2:
                return idea_bd
            pid_b = idxg[:, 0].reshape(-1)          # promoted percept / row
            if int(pid_b.shape[0]) != int(idea_bd.shape[0]):
                return idea_bd
            content, mask = cs.concept_row_content(pid_b)
            if content is None or mask is None or not bool(mask.any()):
                return idea_bd
            d = min(int(content.shape[-1]), int(idea_bd.shape[-1]))
            sel = mask.to(idea_bd.device).unsqueeze(-1)
            out = idea_bd.clone()
            out[:, :d] = torch.where(sel, content[:, :d].to(idea_bd.dtype),
                                     idea_bd[:, :d])
            return out
        except Exception:
            return idea_bd


    def _per_word_prelude(self, in_sub):
        """D8 boundary-side setup that MUST run before the per-word
        loop. Hoisted out of ``_forward_body_per_word`` so the gate
        test (which calls ``_per_word_body_step`` in isolation) can
        replay the same contract.

        Side effects:
          * ``conceptualSpace.stm.begin_forward(B)`` -- seeds a FRESH
            per-forward STM working buffer (a ``torch.zeros`` graph
            INTERMEDIATE) sized to the live batch and starting empty
            (A5 fullgraph fix; replaces the retired ``ensure_batch`` +
            in-place ``clear`` of a persisted registered buffer).
          * ``perceptualSpace._mphf_tables()`` -- lazy build-once
            cache is primed (build path iterates ``bytes`` which
            Dynamo refuses to trace).
          * ``symbolSpace.recur_pass = 0`` -- invariant across the
            per-word loop (pass-index 0 throughout).
          * ConceptualSpace's peer lanes pre-seeded to the persistent empty
            views so iteration 0's
            PS/WS forwards see a non-None feedback subspace (avoids a
            None-vs-SubSpace branch inside the captured body that
            would force a recompile after iteration 1). The body
            switches these to ``cs._subspaceForPS`` /
            ``cs._subspaceForWS`` (the persistent CS-space_role storage that
            CS.forward mutates in place) right after iteration 0's
            cs.forward, so iterations 1+ pick up the in-place updates
            without any further pointer churn.

        Stage 1.F of the two-loop pi/sigma substrate refactor
        (doc/plans/2026-05-26-two-loop-pi-sigma-substrate.md) retired
        the per-stage ``_cs_cache`` / ``_ws_cache`` capture lists —
        no per-forward reallocation here either; the terminal C-space_role
        idea lives on ``stm`` (cleared above), and the terminal
        symbolic subspace is the persistent ``self.wholeSpace
        .subspace`` (overwritten in place by each ``ws.forward``).

        Returns ``(stm, N_target, word_carrier, in_event)`` -- the
        values ``_forward_body_per_word`` needs from the prelude.
        ``in_event`` is the materialized whole-sentence event the
        post-loop step uses to restore the InputSpace subspace.
        """
        stm = self.conceptualSpace.stm
        in_event = in_sub.materialize() if in_sub is not None else None
        if stm is not None:
            B_in = int(in_event.shape[0]) if in_event is not None else 1
            # A5 fullgraph fix (doc/plans/2026-06-06-parallel-conceptual-
            # recurrence.md sec 2 & 4): seed a FRESH per-forward STM working
            # buffer as a trace INTERMEDIATE (was: ``ensure_batch`` + in-place
            # ``clear`` of a persisted registered buffer, which the compiled
            # forward then mutated/output-aliased -> the recompile guard flip
            # + AOT alias-regeneration crash). The per-word loop SHIFTs onto
            # this fresh buffer; the live grad to the head threads through the
            # stacked ``_per_word_contributions`` list, not the buffer.
            dev_in = (in_event.device
                      if in_event is not None and torch.is_tensor(in_event)
                      else None)
            stm.begin_forward(B_in, device=dev_in)
            stm._last_unary = torch.full(stm._buffer.shape[:2], -1,
                                         dtype=torch.long, device=stm._buffer.device)
            stm._unary_history_depth = stm._depth.clone()

        # STM bounded-reducer pre-warm: hoisted to ``enable_compiled_step``
        # (the true eager boundary BEFORE the compile wrapper closes
        # over ``self.forward``). The prelude itself runs INSIDE the
        # compiled forward on the production path, so a lazy build
        # here would still be traced.

        # SymbolSpace per-sentence state + per-forward pre-seed. The
        # cursor / recur_pass are allocated by ``symbolSpace.soft_reset``
        # (triggered by ``post_tick_compact`` when a sentence
        # completes); the first forward of the first sentence runs
        # BEFORE any soft_reset has fired, so cold-start allocation
        # falls to this prelude. ConceptualSpace peer lanes are
        # UNCONDITIONALLY re-seeded to the empty seeds each forward so
        # the per-word loop's iteration 0 always sees the canonical
        # empty starting context -- never a stale SubSpace from a prior
        # sentence's per-word loop. The body switches these to
        # ``cs._subspaceForPS`` / ``cs._subspaceForWS`` after the first
        # iteration's cs.forward; subsequent iterations read the same
        # persistent objects (in-place updates via set_event keep the
        # references stable).
        # Cold-start: the per-sentence state (STM arms, SVO clear, etc.)
        # is normally re-initialized by ``post_tick_compact`` when a
        # sentence completes. The first forward of the first sentence
        # runs BEFORE any compaction has fired, so we run soft_reset
        # once at construction-time. ``_per_sentence_initialized`` is a
        # plain Python bool sentinel — Dynamo-friendly (specializes once
        # then becomes a no-op).
        if not getattr(self.symbolSpace, '_per_sentence_initialized', False):
            self.symbolSpace.soft_reset()
            self.symbolSpace._per_sentence_initialized = True
        self.symbolSpace.recur_pass = 0
        # These are transient carrier pointers, not owned model children.
        # Registering them through ``nn.Module.__setattr__`` on the first
        # captured forward mutates ``self._modules`` and invalidates the just
        # compiled W-loop guard on the next sentence.
        # CS owns recurrence routing; model-level ``_prev_cs_*`` pointers
        # were retired so peer stages cannot accidentally exchange mutable
        # carrier references through BasicModel.
        object.__setattr__(self.conceptualSpace, "_peer_prev_sub",
                           self.conceptualSpace._peer_empty_sub)
        object.__setattr__(self.conceptualSpace, "_peer_prev_sym",
                           self.conceptualSpace._peer_empty_sym)
        # Grammar feedback is sentence-local.  The first two B ticks have no
        # eligible C result, so they must not inherit a prior sentence's plan.
        self.conceptualSpace.clear_language_plan()
        N_target = (int(in_event.shape[1])
                    if in_event is not None and in_event.dim() == 3
                    else None)
        word_carrier = in_sub

        # Static per-word loop scaffolding
        # (doc/plans/2026-05-20-static-per-word-loop-impl.md §2).
        # ``_target_cursor_length`` tells SymbolSpace.compose to pad the
        # S-space_role rule cursor to N with ``id_SS`` (forward-only). The
        # per-iteration commit-time gate is sourced from
        # ``inputSpace._word_active_mask`` (tensor-only, compile-stable);
        # the rule cursor itself stays aligned for downstream consumers
        # but does NOT drive control flow inside the captured body.
        _word_slab = getattr(self.inputSpace, "_ar_embedded_N", None)
        N_static = (int(_word_slab.shape[1])
                    if torch.is_tensor(_word_slab)
                    and _word_slab.dim() == 3
                    else int(getattr(
                        self.inputSpace, "_serial_word_capacity",
                        self.inputSpace.outputShape[0])))
        if self.symbolSpace is not None:
            object.__setattr__(
                self.symbolSpace, "_target_cursor_length", N_static)
        # ``_per_word_contributions`` holds the per-position ``[B, D_c]``
        # contributions (zero at inactive batch rows / padding columns) for
        # ``torch.stack`` after the loop; a python list + stack preserves
        # autograd flow through the per-position concept outputs (an in-place
        # write into a non-grad buffer would silently detach). Seeded empty
        # here; ``_forward_body_per_word`` reallocates it to a FIXED-LENGTH
        # ``N_static`` list (index = word position) so the accumulator length
        # no longer varies with the sentence word-count (a Dynamo recompile
        # driver -- see the loop site).
        self._per_word_contributions: list = []
        return stm, N_target, word_carrier, in_event

    # -- §6c sentence protocol (GrammarOpsPass; author 2026-06-11) ------
    # (The §6 preemption knobs PREEMPT_THRESHOLD/HYSTERESIS left with the
    # mid-sentence reground's removal, 2026-07-07; the layer-level
    # ``preemption_signal`` keeps its own defaults for the reasoning path.)

    def _set_serial_pump(self, flag):
        """Stamp the per-pump mode for the §6d update law (mode is a
        PER-PUMP property within a serial sentence — §6b/§6c): the
        parallel prelude runs with ``serial_pump=False`` (percepts
        move), the per-word serial ticks with ``True`` (references
        move). ``None`` un-stamps (the law falls back to the legacy
        ``serial_mode`` read)."""
        for sp in (getattr(self, 'perceptualSpace', None),
                   getattr(self, 'wholeSpace', None)):
            if sp is not None:
                sp.serial_pump = flag

    @torch.no_grad()
    def _sentence_prelude(self, in_event, word_carrier):
        """The whole-input bracket was read once at lexical staging.

        Re-entering a sentence does not pump the model, update a codebook,
        push STM, or take a gradient. The prepared field is shared by trials.
        """
        self._set_serial_pump(True)
        self._prelude_pumps = int(getattr(self, '_prelude_pumps', 0)) + 1
        return getattr(self, '_last_gist', None)


    def _aligned_word_chunk2(self, words_b_2_d, gates_b_2):
        """Run two canonical aligned word ticks as one reusable graph.

        The eager driver presents a two-column view through InputSpace's
        ordinary staged attributes, so the existing word cell can use local
        positions 0 and 1.  No sentence-global ``p`` value or growing output
        list enters this callable.  Contributions are returned as tensors and
        installed in the sentence-wide lists by the driver after replay.
        """
        if (words_b_2_d.dim() != 3 or int(words_b_2_d.shape[1]) != 2
                or gates_b_2.dim() != 2 or int(gates_b_2.shape[1]) != 2):
            raise RuntimeError(
                "aligned word chunk requires words [B,2,D] and gates [B,2]")

        cs = self.conceptualSpace
        # Keep the Python accumulator structure identical at every replay.
        # The fixed-capacity predictor appends one term per local word,
        # including a zero-weight first-word term when STM is empty.
        cs._intra_loss_accum = None
        cs._intra_loss_weight_accum = None
        cs._intra_loss_count = 0
        cs._intra_errors = Error()
        concept_slots = [None, None]
        percept_slots = [None, None]
        self._per_word_percept_contributions = percept_slots

        for local_p in range(2):
            self._per_word_body_step(
                words_b_2_d[:, local_p:local_p + 1, :],
                local_p,
                gates_b_2[:, local_p:local_p + 1],
                concept_slots,
                active_host=True)

        if (concept_slots[0] is None or concept_slots[1] is None
                or percept_slots[0] is None or percept_slots[1] is None):
            raise RuntimeError(
                "canonical aligned chunk did not emit both concept and "
                "percept contributions")
        return (
            torch.stack(concept_slots, dim=1),
            torch.stack(percept_slots, dim=1),
        )

    def _aligned_word_chunk1(self, words_b_1_d, gates_b_1):
        """Run one canonical word tick in a static fullgraph kernel.

        K=1 avoids the compilation blow-up of the two-tick stateful AOT
        backward while still containing the complete numerical PS/WS/CS/STM
        recurrence for one word.  The outer adapter establishes sentence order
        and passes a fixed residual-part bucket on every replay.
        """
        if (words_b_1_d.dim() != 3 or int(words_b_1_d.shape[1]) != 1
                or gates_b_1.dim() != 2 or int(gates_b_1.shape[1]) != 1):
            raise RuntimeError(
                "aligned word chunk requires words [B,1,D] and gates [B,1]")
        cs = self.conceptualSpace
        cs._intra_loss_accum = None
        cs._intra_loss_weight_accum = None
        cs._intra_loss_count = 0
        cs._intra_errors = Error()
        concept_slots = [None]
        percept_slots = [None]
        self._per_word_percept_contributions = percept_slots
        self._per_word_body_step(
            words_b_1_d, 0, gates_b_1, concept_slots, active_host=True)
        if concept_slots[0] is None or percept_slots[0] is None:
            raise RuntimeError(
                "canonical aligned chunk did not emit concept and percept "
                "contributions")
        return (
            concept_slots[0].unsqueeze(1),
            percept_slots[0].unsqueeze(1),
        )

    @torch.compiler.disable
    def _run_aligned_word_chunk_loop(self, out_slot, n_trips):
        """Eager sentence driver around the reusable two-word graph.

        Only fixed-shape, canonical-layout tensors cross into the compiled
        callable. The full sparse concept bank remains installed and grad-bearing for the
        whole sentence; the temporary InputSpace swaps affect only surfaces
        whose second axis the legacy word cell indexes by ``p``.
        """
        step = self._compiled_word_chunk_step
        chunk_width = int(getattr(self, "_compiled_word_chunk_width", 2))
        isp = self.inputSpace
        slab = getattr(isp, "_ar_embedded_N", None)
        if (step is None or not torch.is_tensor(slab)
                or chunk_width < 1 or int(n_trips) < chunk_width
                or int(n_trips) % chunk_width != 0):
            return None
        n_trips = int(n_trips)
        if int(slab.shape[1]) < n_trips:
            return None

        active = getattr(isp, "_word_active_mask", None)
        if active is None:
            active = torch.ones(
                int(slab.shape[0]), n_trips, dtype=torch.bool,
                device=slab.device)

        staged_names = (
            "_ar_word_part_ids",
            "_ar_word_part_mask",
            "_ar_word_part_offsets",
            "_ar_word_concept_rows",
            "_ar_word_concept_orders",
            "_word_last_slot_mask",
            "_ar_percept_reference_codes", "_ar_percept_reference_roles",
            "_ar_part_reference_vectors", "_ar_whole_reference_vectors",
            "_ar_readout_coefficients", "_ar_whole_reference_presence",
        )
        dynamic_part_names = {
            "_ar_word_part_ids",
            "_ar_word_part_mask",
            "_ar_word_part_offsets",
        }
        full = {name: getattr(isp, name, None) for name in staged_names}
        required = tuple(full[name] for name in staged_names)
        if not all(torch.is_tensor(value) for value in required):
            return None

        # The residual-part axis is semantic but normally tiny.  Marking it
        # dynamic over InputSpace's 8192-byte ceiling made MPS Inductor lower
        # a very broad symbolic graph for every K=1/K=2 word cell.  Instead,
        # stage an exact padded bucket (8/16/32/...) once per sentence.  The
        # sentinel IDs and false mask make the added lanes identity elements;
        # nothing is truncated.  A finite bucket set gives a bounded number of
        # fullgraph specializations while retaining arbitrary long residual
        # words through the next power-of-two fallback.
        part_width = int(full["_ar_word_part_ids"].shape[-1])
        part_bucket = next(
            (width for width in (8, 16, 32, 64, 128)
             if part_width <= width),
            1 << max(0, part_width - 1).bit_length())
        staged = dict(full)
        if part_width < part_bucket:
            for name in dynamic_part_names:
                value = full[name]
                pad_shape = tuple(value.shape[:-1]) + (
                    part_bucket - part_width,)
                fill = False if name == "_ar_word_part_mask" else -1
                pad = torch.full(
                    pad_shape, fill, dtype=value.dtype, device=value.device)
                staged[name] = torch.cat((value, pad), dim=-1)

        ps_out_slot = self._per_word_percept_contributions
        cs = self.conceptualSpace
        # The first compiled push must see the same module layout as later
        # chunks; otherwise lazy clause state creation invalidates its guard.
        cs.stm.ensure_clause_state()
        loss_terms = list(getattr(cs, "_intra_loss_accum", None) or [])
        loss_weights = list(
            getattr(cs, "_intra_loss_weight_accum", None) or [])
        cost_terms = Error()
        cost_terms.merge(cs._intra_errors)
        last_cs = None
        was_replaying = bool(getattr(
            self, "_compiled_word_chunk_replaying", False))
        was_trace_active = bool(getattr(
            self, "_compiled_word_chunk_trace_active", False))
        trace = self._reconstruction_stack()
        global_choices = trace.choices() if trace is not None else (None,) * 3
        global_forward = (trace.forward_loss_slots()
                          if trace is not None else (None, None))
        local_choices = None
        local_forward = None
        if (all(torch.is_tensor(value) for value in global_choices)
                and int(global_choices[0].shape[0]) == int(slab.shape[0])
                and int(global_choices[0].shape[1]) >= 3 * n_trips):
            local_choices = (
                torch.full(
                    (int(slab.shape[0]), 3 * chunk_width), -1,
                    dtype=global_choices[0].dtype,
                    device=global_choices[0].device),
                torch.zeros(
                    int(slab.shape[0]), 3 * chunk_width,
                    dtype=global_choices[1].dtype,
                    device=global_choices[1].device),
                torch.zeros(
                    int(slab.shape[0]), 3 * chunk_width,
                    dtype=global_choices[2].dtype,
                    device=global_choices[2].device),
            )
            trace._choice_rule_ids = local_choices[0]
            trace._choice_arities = local_choices[1]
            trace._choice_mask = local_choices[2]
            if all(torch.is_tensor(value) for value in global_forward):
                local_forward = (
                    torch.zeros(
                        int(slab.shape[0]), 3 * chunk_width,
                        dtype=global_forward[0].dtype,
                        device=global_forward[0].device),
                    torch.zeros(
                        int(slab.shape[0]), 3 * chunk_width,
                        dtype=global_forward[1].dtype,
                        device=global_forward[1].device),
                )
                trace._forward_losses = local_forward[0]
                trace._forward_loss_mask = local_forward[1]
        self._compiled_word_chunk_replaying = True
        self._compiled_word_chunk_trace_active = local_choices is not None
        try:
            for start in range(0, n_trips, chunk_width):
                stop = start + chunk_width
                for name in staged_names:
                    value = staged[name]
                    # A view retains its sentence slab's W-dependent leading
                    # stride, even though its visible shape is always K=2.
                    # Force a fresh canonical layout so W=16/32/64/128 all
                    # satisfy the same Dynamo guards (``contiguous()`` alone
                    # may return the original view when B=1).
                    chunk_value = value[:, start:stop].clone(
                        memory_format=torch.contiguous_format)
                    object.__setattr__(isp, name, chunk_value)
                word_chunk = slab[:, start:stop, :].clone(
                    memory_format=torch.contiguous_format)
                gate_chunk = active[:, start:stop].clone(
                    memory_format=torch.contiguous_format)
                if local_choices is not None:
                    local_choices[0].fill_(-1)
                    local_choices[1].zero_()
                    local_choices[2].zero_()
                if local_forward is not None:
                    local_forward[0].zero_()
                    local_forward[1].zero_()
                concept_chunk, percept_chunk = step(
                    word_chunk, gate_chunk)
                if local_choices is not None:
                    target = slice(3 * start, 3 * stop)
                    for global_value, local_value in zip(
                            global_choices, local_choices):
                        global_value[:, target].copy_(local_value)
                    if local_forward is not None:
                        for global_value, local_value in zip(
                                global_forward, local_forward):
                            global_value[:, target].copy_(local_value)
                for local_p in range(chunk_width):
                    out_slot[start + local_p] = concept_chunk[:, local_p, :]
                    if isinstance(ps_out_slot, list):
                        ps_out_slot[start + local_p] = (
                            percept_chunk[:, local_p, :])
                loss_terms.extend(
                    list(getattr(cs, "_intra_loss_accum", None) or []))
                loss_weights.extend(list(
                    getattr(cs, "_intra_loss_weight_accum", None) or []))
                cost_terms.merge(cs._intra_errors)
                last_cs = cs.subspace
        finally:
            for name, value in full.items():
                object.__setattr__(isp, name, value)
            self._per_word_percept_contributions = ps_out_slot
            self._compiled_word_chunk_replaying = was_replaying
            self._compiled_word_chunk_trace_active = was_trace_active
            if trace is not None and local_choices is not None:
                trace._choice_rule_ids = global_choices[0]
                trace._choice_arities = global_choices[1]
                trace._choice_mask = global_choices[2]
                if local_forward is not None:
                    trace._forward_losses = global_forward[0]
                    trace._forward_loss_mask = global_forward[1]

        cs._intra_loss_accum = loss_terms or None
        cs._intra_loss_weight_accum = loss_weights or None
        cs._intra_loss_count = len(loss_terms)
        cs._intra_errors = cost_terms
        stm = cs.stm
        if stm is not None and torch.is_tensor(getattr(stm, "_depth", None)):
            # One boundary sync, outside every compiled replay.  Snapshot and
            # the NULL-closing reducer need the current logical width; no word
            # cell reads this Python mirror in chunk mode.
            stm._max_depth_host = int(stm._depth.max().item())
        return last_cs

    def _per_word_body_step(self, w, p, gate_b_1, out_slot, active_host=True,
                            _pipeline_stage_a=False):
        """One per-word iteration of the static loop (replaces the
        legacy data-dependent ``while next_word()`` body).

        Static-N variant of the constant-shape PS/WS -> CS sub-graph
        replayed ``N = InputSpace.outputShape[0]`` times per forward.
        Per-iteration side-effects (carrier event commits, STM push,
        concept-buffer scatter) are masked by ``gate_b_1`` so padding
        columns leave recurrent state bit-identical to the active
        prefix. See
        doc/plans/2026-05-20-static-per-word-loop-impl.md §2.4.

        Args:
          w: ``[B, 1, D]`` word slice for position ``p``
             (``InputSpace.word_at(p)``); zero at inactive batch rows.
          p: Python int loop position; constant per unrolled iteration.
          gate_b_1: ``[B, 1]`` bool active mask from
             ``inputSpace._word_active_mask[:, p:p+1]``. ``torch.where``
             gate for masked commits.
          out_slot: fixed-length ``N_static`` python list (per-position
             concept accumulator); this call writes slot ``p`` by its
             python-constant index (``None`` in unwritten slots).

        Returns ``(CS_sub, idea_bd)`` — last_cs tracking and idea
        broadcast handle. Both are produced unconditionally (PS/WS/CS
        forwards always fire); only their downstream effects are gated.

        Capture-gate contract: still the ONLY callable that runs inside
        the middle captured graph; every helper it calls remains
        DtoH-free. ``test/test_per_word_capture_gate.py`` is the active
        gate.
        """
        isp = self.inputSpace
        ps = self.perceptualSpace
        cs = self.conceptualSpace
        ws = self.wholeSpace
        stm = cs.stm
        word_carrier = isp.subspace

        # Sentence-global ReconstructionStack slots. The complete W-loop has a
        # compiler-constant global ``p``. The reusable K=1/K=2 word cell writes
        # the same local 3*K layout; its eager adapter copies that slab into the
        # corresponding global sentence slice without passing a changing
        # offset through the compiled graph.
        _trace_p = (
            int(p) if (not self._compiled_word_chunk_replaying
                       or getattr(
                           self, "_compiled_word_chunk_trace_active", False))
            else None)
        # Three chronological opportunities per word: capacity-demand binary,
        # ordinary binary, then unary.  The boundary drain begins at 3*W.
        _trace_pre_binary = (
            None if _trace_p is None else 3 * _trace_p)
        _trace_post_binary = (
            None if _trace_p is None else 3 * _trace_p + 1)
        _trace_unary = (
            None if _trace_p is None else 3 * _trace_p + 2)

        # Word-major radix: InputSpace presents this word's discrete local
        # part state; PartSpace consumes and synthesizes it inside PS.forward.
        # The sentence loop advances over W words while the PS-local part axis
        # is reset for each presentation.
        local_part_ids = (isp.word_part_ids_at(p)
                          if hasattr(isp, "word_part_ids_at") else None)
        local_part_mask = (isp.word_part_mask_at(p)
                           if hasattr(isp, "word_part_mask_at") else None)
        local_part_offsets = (isp.word_part_offsets_at(p)
                              if hasattr(isp, "word_part_offsets_at")
                              else None)
        word_major = local_part_ids is not None and local_part_mask is not None

        # Gaussian window + MPHF route. ``p`` is the static loop position;
        # the legacy ``_per_word_cursor - 1`` mirror is retired with
        # ``next_word()``.
        _full_seq = isp._ar_embedded
        # serialObjectMeta: HARD-MASK-TO-WORD-SPAN — replace the soft gaussian
        # window with the hard same-word window so PS processes the ACTIVE WORD
        # ONLY (the word's block; no slot outside it). Whole-sentence context
        # re-enters via the §6c prelude's gist/intent, not this window. Flag-off
        # keeps the gaussian path byte-identical.
        if word_major:
            _ctx_w = None
        elif getattr(self, 'serial_object_meta', False):
            _ctx_w = self.word_span_window(
                _full_seq, p, getattr(isp, '_word_index_N', None))
        else:
            _ctx_w = self.gaussian_window_word(_full_seq, p)
        if (not word_major and _ctx_w is not None
                and torch.is_tensor(_ctx_w)
                and _ctx_w.dim() == 3
                and _ctx_w.shape[1] == 1
                and w is not None and torch.is_tensor(w)
                and _ctx_w.shape[0] == w.shape[0]
                and _ctx_w.shape[-1] == w.shape[-1]):
            w = _ctx_w

        word_sub = isp.present_word(
            w,
            word_local_parts=word_major,
            part_ids=local_part_ids,
            part_mask=local_part_mask,
            part_offsets=local_part_offsets)

        # The canonical word path commits once at the word boundary. Its
        # aligned concept option interprets bindingDepth=T as one base
        # field plus T-1 cumulative folds on EACH tower, all inside this word
        # iteration. Existing configs default to the learned mixing path.
        word_commit_mode = bool(
            getattr(self, 'serial_object_meta', False)
            and getattr(isp, '_word_last_slot_mask', None) is not None)
        aligned_fold_binding = bool(
            word_commit_mode
            and getattr(self, "concept_binding", "mixing") == "aligned")

        # Capture the prior CS lane events only for masked owner commits below.
        # PS and WS are InputSpace peers; neither receives a conceptual carrier
        # as a hidden input.  CS is the downstream reducer of their results.
        prevCS_forPS = cs._peer_prev_sub
        prevCS_forSS = cs._peer_prev_sym
        # Snapshot the carriers' event tensors BEFORE cs.forward writes
        # new ones (set_event mutates in place; without snapshots the
        # masked-blend below would compare new-vs-new).
        prev_ps_event_snap = (
            prevCS_forPS._event
            if (prevCS_forPS is not None
                and getattr(prevCS_forPS, '_event', None) is not None)
            else None)
        prev_ws_event_snap = (
            prevCS_forSS._event
            if (prevCS_forSS is not None
                and getattr(prevCS_forSS, '_event', None) is not None)
            else None)

        # Stage 1.A substrate refactor: PartSpace.forward is
        # single-arg now (``pi(x) + sigma(x)`` on the same input —
        # no CS-feedback path entering PS at this level).
        # PS and WS are peers.  InputSpace fans its atom and unity views to
        # them independently; WS never consumes PS output or a CS feedback
        # carrier.  In debug mode guard the InputSpace atom view so a PS
        # regression cannot mutate another space's storage. Production keeps
        # these reads zero-copy and has no Python guard overhead.
        # Never construct Python view/guard objects inside an AOT word loop.
        # The flag is frozen at model setup and this branch specializes away
        # for production; debug runs remain eager by construction.
        _peer_guard = (bool(getattr(self, "_debug_peer_mutation", False))
                       and not torch.compiler.is_compiling())
        _unity = getattr(self, "_ws_universe", None)
        # The live peer scheduler is host-owned, so PS receives InputSpace's
        # read-only capability rather than its mutable carrier.  The legacy
        # standalone fullgraph-cell test deliberately stays on the raw carrier:
        # Dynamo cannot represent Python capability objects, and no peer guard
        # or scheduler state is captured on that compatibility path.
        ps_input = (word_sub if torch.compiler.is_compiling()
                    else word_sub.view())
        if _peer_guard:
            with guard_peer_views(ps_input):
                PS_base = ps.forward(ps_input)
                WS_base = (
                    ws.forward(_unity)
                    if _unity is not None
                    else self._zero_symbol_subspace(ws, word_sub))
        else:
            PS_base = ps.forward(ps_input)
            WS_base = (
                ws.forward(_unity)
                if _unity is not None
                else self._zero_symbol_subspace(ws, word_sub))
        PS_sub = PS_base
        # Retain one PartSpace result per word so post-loop loss/reverse
        # readers see a word-aligned slab instead of only the last iteration.
        if word_major and PS_sub is not None:
            _ps_event = PS_sub.materialize()
            _ps_slots = getattr(self, "_per_word_percept_contributions", None)
            if (torch.is_tensor(_ps_event) and _ps_event.dim() == 3
                    and int(_ps_event.shape[1]) >= 1
                    and isinstance(_ps_slots, list)
                    and 0 <= p < len(_ps_slots)):
                _ps_slots[p] = torch.where(
                    gate_b_1, _ps_event[:, 0, :],
                    torch.zeros_like(_ps_event[:, 0, :]))
        whole_base_event = WS_base.materialize() if aligned_fold_binding else None
        WS_sub = WS_base
        # ``serialObjectMeta`` makes the grammar loop word-grained even when
        # the radix store still spells an unfamiliar word with several
        # percepts.  Predict/perceive only at the word's final percept: the
        # hard ``word_span_window`` above has already assembled the complete
        # word event by then.  Earlier percepts are representation-building
        # steps, not extra language-model targets.
        #
        # The legacy flag-off path remains slot-grained.  In word mode the
        # outer block below owns the single physical STM push (it also owns
        # capacity back-pressure and grammar dispatch), so ConceptualSpace
        # computes/stashes the prediction but defers its push to that block.
        commit_b_1 = (
            isp._word_last_slot_mask[:, p:p + 1] & gate_b_1
            if word_commit_mode else gate_b_1)

        concept_orders_full = None
        prior_symbol_source = None
        prior_symbol_validity = None
        word_concept_row = None
        word_concept_activation = None
        if aligned_fold_binding:
            # Each tower completes its native recursion before the addressed
            # part/whole-code evidence enters the plain Sigma readout. Full
            # native fields remain alongside that readout for reconstruction.
            n_locations = int(cs.outputShape[0])

            # P0 is the parameter-free union of the word's residual parts.
            # Keep it and the complete learned ladder, not scalar summaries.
            # P0 is retained on PS's own working carrier.  InputSpace remains
            # read-only to the PS peer, so the raw input carrier is never used
            # as a cross-space scratch surface.
            base_parts = ()
            if word_major:
                base_event = getattr(
                    PS_base, "_word_local_base_event", None)
                if torch.is_tensor(base_event):
                    base_parts = (base_event,)
            native_parts = ()
            base_wholes = ()
            if torch.is_tensor(whole_base_event):
                base_wholes = (whole_base_event,)
            native_wholes = ()
            native_part_sources = base_parts or (PS_base.materialize(),)
            native_whole_sources = base_wholes or (WS_base.materialize(),)
            native_sources = native_part_sources + native_whole_sources
            if not native_sources:
                raise RuntimeError(
                    "aligned concept activation requires native fold sources")

            row_b = (isp.word_concept_rows_at(p)
                     if hasattr(isp, "word_concept_rows_at") else None)
            order_b = (isp.word_concept_orders_at(p)
                       if hasattr(isp, "word_concept_orders_at") else None)
            batch = int(native_sources[0].shape[0])
            if row_b is None:
                row_b = torch.full(
                    (batch,), -1, dtype=torch.long,
                    device=native_sources[0].device)
            else:
                row_b = row_b.to(
                    device=native_sources[0].device, dtype=torch.long)
            if order_b is None:
                order_b = torch.full_like(row_b, -1)
            else:
                order_b = order_b.to(
                    device=native_sources[0].device, dtype=torch.long)
            active_rows = gate_b_1.reshape(-1).to(
                device=row_b.device, dtype=torch.bool)
            row_b = torch.where(active_rows, row_b,
                                torch.full_like(row_b, -1))
            order_b = torch.where(active_rows, order_b,
                                  torch.full_like(order_b, -1))
            concept_orders_full = order_b.unsqueeze(1).expand(
                -1, n_locations)

            part_what = int(ps.nWhat)
            whole_what = int(ws.nWhat)
            reference_codes = isp._ar_percept_reference_codes[:, p]
            reference_roles = isp._ar_percept_reference_roles[:, p]
            presence_bank = isp._ar_whole_reference_presence
            presence = None if presence_bank is None else presence_bank[:, p]
            evidence, evidence_mask = cs.percept_code_evidence(
                native_part_sources[-1],
                native_whole_sources[-1],
                isp._ar_part_reference_vectors[:, p],
                isp._ar_whole_reference_vectors[:, p], reference_roles, active_rows,
                part_n_what=part_what, whole_n_what=whole_what,
                whole_presence=presence)

            # Canonical SS peer: read the complete *prior* STM slab before
            # this word enters CS. Slot i maps directly to location i. The
            # indexed CS lookup is SS's sigma fold / dimensional increase;
            # there is no inventory scan and no current-tick CS->SS->CS edge.
            prior_symbol_source, prior_symbol_validity = (
                cs.decode_prior_stm_peer(
                    stm, active_rows,
                    staged_rows=getattr(
                        isp, "_ar_concept_lookup_rows", None),
                    staged_atoms=getattr(
                        isp, "_ar_concept_lookup_atoms", None)))

            (concept_event, concept_orders_full, word_concept_row,
             word_concept_activation, prior_symbol_source,
             prior_symbol_validity) = cs.reduce_aligned_word_peers(
                native_part_sources, native_whole_sources,
                prior_symbol_source, prior_symbol_validity,
                row_b, order_b, active_rows,
                staged_rows=isp._ar_concept_lookup_rows,
                staged_atoms=isp._ar_concept_lookup_atoms,
                part_n_what=part_what, whole_n_what=whole_what,
                percept_evidence=evidence, evidence_mask=evidence_mask,
                readout_coefficients=isp._ar_readout_coefficients[:, p])
            cs_input = cs.commit_from(PS_sub, concept_event)
            cs_symbol_input = None
        else:
            cs_input = PS_sub
            cs_symbol_input = WS_sub

        object.__setattr__(cs, "_serial_row_gate", commit_b_1)
        object.__setattr__(cs, "_serial_defer_push", True)
        # In the live peer scheduler, A owns only the CSsub publication.  B
        # receives this word's completed tensor and performs the delayed CSsym
        # publication after SS.  The legacy direct word cell remains atomic.
        object.__setattr__(
            cs, "_serial_defer_symbolic_lane", bool(_pipeline_stage_a))
        try:
            CS_sub = cs.forward(cs_input, cs_symbol_input)
        finally:
            object.__setattr__(cs, "_serial_row_gate", None)
            object.__setattr__(cs, "_serial_defer_push", False)
            object.__setattr__(cs, "_serial_defer_symbolic_lane", False)

        # The live PS and WS fields meet here, inside the current word
        # iteration. CS.forward above is explicitly in defer mode, so field
        # positions are not mistaken for separate workspace pushes.
        #
        # ``aligned``: preserve location indices and aggregate P0..P3 plus
        # W0..W3 (BasicModel T=4 -> eight sources). ``mixing`` retains the
        # historical learned matrix.
        if word_commit_mode and CS_sub is not None:
            if aligned_fold_binding:
                # Attach complete processed fields without re-evaluating or
                # overwriting the live event.
                cs.commit_percept_field(
                    native_part_sources, native_whole_sources,
                    reference_codes=reference_codes, reference_roles=reference_roles,
                    evidence=evidence, evidence_mask=evidence_mask, target=CS_sub,
                    active_rows=active_rows)
                support = cs._ordered_fold_support((), ())
                support["source_count"] = len(native_sources)
                support["includes_base_fields"] = True
                object.__setattr__(CS_sub, "_fold_support", support)
                object.__setattr__(CS_sub, "_concept_orders", concept_orders_full)
                object.__setattr__(CS_sub, "_prior_symbolic_event", prior_symbol_source)
                object.__setattr__(CS_sub, "_prior_symbolic_validity", prior_symbol_validity)
                object.__setattr__(self, "_last_concept_fold_support", support)
                # META minting is intentionally eager at the sentence
                # boundary. Stage the tensor-free ordered support on its WS
                # owner so those durable concepts retain the same paths.
                object.__setattr__(ws, "_active_fold_support", support)
            else:
                cs.bind_streams(PS_sub, WS_sub, CS_sub)

        # Masked-blend the persistent CS carriers' new events with the
        # snapshots so padding columns preserve the recurrent state
        # from the prior iteration (no ConceptualSpace averaging leak
        # from WS at zero input). Shapes must match — on iteration 0
        # the prev is the empty seed (length 0) and the blend is
        # skipped; the cs.forward result propagates as-is.
        self._maybe_blend_event(
            cs._subspaceForPS, prev_ps_event_snap, gate_b_1)
        if not _pipeline_stage_a:
            self._maybe_blend_event(
                cs._subspaceForWS, prev_ws_event_snap, gate_b_1)

        # Switch the prev pointer to the persistent CS storage so the
        # next iteration's first reads see CS.forward's in-place
        # writes. After this line ConceptualSpace publishes its CSsub lane
        # ``cs._subspaceForPS``; subsequent iterations read the same
        # object whose ``_event`` cs.forward keeps fresh.
        object.__setattr__(cs, "_peer_prev_sub", cs.CSsub)
        if not _pipeline_stage_a:
            object.__setattr__(cs, "_peer_prev_sym", cs.CSsym)

        if _pipeline_stage_a:
            # Do not retain the live ``SubSpace``: A(w+1) reuses it before
            # B(w) runs.  CS publishes zero-copy *read-only snapshots* of the
            # completed event and the common prior symbolic event instead.
            # Their tensor bindings remain valid through the delayed peer
            # stage, while a debug guard can still detect illicit in-place
            # writes through either view.
            concept_event = (
                CS_sub.materialize() if CS_sub is not None else None)
            return _PeerAResult(
                concept_view=cs.publish_peer_view(concept_event),
                prior_symbolic_view=cs.publish_peer_view(
                    prev_ws_event_snap),
                concept_orders=(getattr(CS_sub, "_concept_orders", None)
                                if CS_sub is not None else None),
                gate_b_1=gate_b_1,
                commit_b_1=commit_b_1,
                word_concept_row=word_concept_row,
                word_concept_activation=word_concept_activation,
                trace_pre_binary=_trace_pre_binary,
                trace_post_binary=_trace_post_binary,
                trace_unary=_trace_unary,
                p=p,
                out_slot=out_slot,
                active_host=active_host,
            )

        # Stage 1.F substrate refactor (doc/plans/2026-05-26-two-loop-
        # pi-sigma-substrate.md): the per-stage ``_cs_cache`` /
        # ``_ws_cache`` capture lists are retired. The terminal C-space_role
        # idea is owned by ``cs.stm`` (the bookkeeping push fires
        # below via ``stm.push_step_masked``, which is host-gated to
        # active iterations); the terminal symbolic subspace is owned
        # by ``self.wholeSpace.subspace`` (overwritten in place by
        # ``ws.forward`` above on every iteration). On padding
        # iterations the WS write is harmless (the input was empty)
        # and downstream readers gate on the active-host mask
        # / STM depth, so no extra guard is needed here.
        if WS_sub.is_empty():
            WS_sub = self._zero_symbol_subspace(ws, word_sub)

        idea_bd = None
        if CS_sub is not None:
            idea = CS_sub.materialize()
            if (idea is not None and idea.dim() == 3
                    and idea.shape[1] >= 1):
                idea_bd = idea[:, 0, :]                 # [B, D_c]
                # Concept index-read (snap design doc §ontology, Alec
                # 2026-07-15): light up the word's ALREADY-KNOWN concept
                # (minted by the parallel path) — replace the idea's
                # content slice with the concept's random signed-hypersphere
                # row so the fold consumes a separable concept, not the
                # collapsing percept-binding. Default-off -> byte-identical;
                # eager-only (host resolve). No-op where the percept is
                # untied (untrained / not-yet-minted).
                if (getattr(self, 'concept_index_read', False)
                        and not torch.compiler.is_compiling()
                        and idea_bd is not None):
                    idea_bd = self._maybe_concept_index_read(idea_bd)
                if stm is not None and active_host:
                    # serialObjectMeta: fire the STM push ONCE PER WORD (the
                    # last-slot-of-word commit gate) so a multi-slot
                    # (radix-spelled) word pushes ONE idea, not one per byte.
                    # Flag-off / no word-index -> commit_b_1 IS gate_b_1
                    # (per-slot, byte-identical). The host depth mirror stays
                    # per-iteration -- a conservative UPPER bound that may
                    # trigger an early (but safe) reduce in radix multi-slot
                    # words; raise stmCapacity in the serial config if a long
                    # sentence would trip it.
                    # ``commit_b_1`` was resolved before CS.forward so the
                    # predictor target and the physical STM commit share the
                    # exact same word boundary.
                    # Capacity demand fires here, immediately before a word
                    # that would overflow a full row.  It may only select a
                    # binary grammatical operator; silently rolling off the
                    # oldest constituent would hide a failed parse.
                    # ``push_step_masked`` is gated on ``active_host``
                    # so padding iterations never index past depth and
                    # never trip a capacity OOB.
                    #
                    # Recompile-churn fix (doc/plans/2026-07-04): the loop now
                    # runs the full static per-word slab width, so a SHORT
                    # sentence's padding columns (``commit_b_1`` all-False)
                    # reach here. ``push_step_masked`` is a masked rolling roll
                    # -> a byte-identical no-op there, and the mirror
                    # over-advance those columns cause is corrected by the
                    # single post-loop re-pin in ``_forward_body_per_word``
                    # (mirror only sizes ``snapshot()``; back-pressure stays
                    # dormant below capacity, so a below-cap sentence's padding
                    # never trips the reduce -- the pre-filled configs that DO
                    # reach cap fill every column, i.e. have no padding).
                    # Relative protection (depth-3 campaign, 2026-07-13 +
                    # review finding same day): computed ONCE per word from
                    # the rules the PREVIOUS fires populated, and threaded
                    # into the capacity demand and the online pressure
                    # decision below — the batch-global _max_depth_host mirror
                    # otherwise force-folds a finished relative row below its
                    # protected depth-3 end-state. Eager-only, like the
                    # per-word fire that feeds it (compile has no per-word
                    # rules to read). Depth <= 3 rows are never the rows
                    # actually at capacity, so protection cannot block a
                    # genuinely forced fold.
                    _protect = None
                    if (not torch.compiler.is_compiling()
                            and stm._buffer is not None):
                        _Bp = int(stm._buffer.shape[0])
                        _rel = self._sentence_relative_mask(
                            _Bp, device=stm._buffer.device)
                        _protect = torch.where(
                            _rel,
                            torch.full((_Bp,), 3, dtype=stm._depth.dtype,
                                       device=_rel.device),
                            torch.ones(_Bp, dtype=stm._depth.dtype,
                                       device=_rel.device))
                    # Predict from the retained reduced context against the
                    # freshly bound word concept. Its actual subsymbolic order
                    # is carried explicitly from the aligned fold support;
                    # grammatical depth starts separately at zero.
                    _compiled_recurrent = bool(
                        self._compiled_word_chunk_replaying
                        or (torch.compiler.is_compiling()
                            and getattr(self,
                                        "_compiled_word_loop_fullgraph",
                                        False)))
                    if _compiled_recurrent:
                        cs._stm_predict_then_perceive_serial_fixed(
                            idea_bd, row_gate=commit_b_1)
                    else:
                        cs._stm_predict_then_perceive_serial(
                            idea_bd, row_gate=commit_b_1)
                    _concept_orders = getattr(
                        CS_sub, "_concept_orders", None)
                    if (torch.is_tensor(_concept_orders)
                            and _concept_orders.dim() == 2
                            and int(_concept_orders.shape[0])
                            == int(idea_bd.shape[0])):
                        _word_concept_order = _concept_orders[:, 0].to(
                            device=idea_bd.device, dtype=torch.long)
                    else:
                        _word_concept_order = torch.full(
                            (int(idea_bd.shape[0]),), -1,
                            dtype=torch.long, device=idea_bd.device)
                    _word_grammar_order = torch.zeros_like(
                        _word_concept_order)
                    commit_b_1 = self._compose_admission(commit_b_1)
                    stm.push_step_masked(
                        idea_bd, commit_b_1,
                        orders=_word_concept_order,
                        grammar_orders=_word_grammar_order,
                        concept_row=word_concept_row,
                        concept_activation=word_concept_activation)
                    # Coarser-whole provenance of this unit (fold-ladder
                    # plan, Phase 2b): the tiling ladder's parent map,
                    # pushed on the STM provenance slab (tensor-pure).
                    self._push_unit_provenance(stm, commit_b_1, p)
                    if not _compiled_recurrent:
                        stm._max_depth_host = stm._max_depth_host + 1
                    self._stm_word_rounds(commit_b_1, p)
                # Masked contribution: at inactive batch rows / padding
                # columns the contribution is zero so it doesn't push
                # bogus state into downstream concept reads. ``out_slot``
                # is the caller's FIXED-LENGTH per-position buffer (a list
                # preallocated to ``N_static``); write column ``p`` by its
                # python-constant index (was ``append`` -> a length that grew
                # with the trip count, a Dynamo recompile driver). The caller
                # ``torch.stack``s all columns post-loop so autograd flows
                # through the per-position contributions.
                contribution = torch.where(
                    gate_b_1, idea_bd, torch.zeros_like(idea_bd))
                if (out_slot is not None and isinstance(out_slot, list)
                        and 0 <= p < len(out_slot)):
                    out_slot[p] = contribution
        return CS_sub, idea_bd

    def _peer_stage_b(self, a_result, p, grammar_feedback, *, cache_only=False):
        """Finish one delayed symbolic/STM word stage.

        A result is a tensor snapshot, not a live carrier.  By the time this
        runs, A has already started the next word and has reused PS, WS, and
        CSsub storage.  B therefore performs the SS read and the CSsym/STM
        owner commits from the explicit result only.
        """
        if a_result is None:
            return None
        cs = self.conceptualSpace
        stm = cs.stm
        concept_view = a_result.concept_view
        prior_symbolic_view = a_result.prior_symbolic_view
        event = (concept_view.materialize(mode="event")
                 if concept_view is not None else None)
        prior_symbolic_event = (
            prior_symbolic_view.materialize(mode="event")
            if prior_symbolic_view is not None else None)

        # SS owns its codebook/output carrier.  It receives CS's completed
        # read-only snapshot and the same prior symbolic snapshot as CSsym;
        # neither peer gets a mutable CS carrier.  The Language plan is also
        # passed as an explicit B input (its source is C[p-2]).
        symbol_event = None
        ss = getattr(self, "symbolSpace", None)
        if ss is not None and concept_view is not None:
            _peer_guard = (bool(getattr(self, "_debug_peer_mutation", False))
                           and not torch.compiler.is_compiling())
            if _peer_guard:
                with guard_peer_views(concept_view, prior_symbolic_view):
                    ss_sub = ss.forward_concept_to_symbol(
                        concept_view, prior_symbolic=prior_symbolic_view,
                        language_plan=grammar_feedback)
            else:
                ss_sub = ss.forward_concept_to_symbol(
                    concept_view, prior_symbolic=prior_symbolic_view,
                    language_plan=grammar_feedback)
            if ss_sub is not None:
                symbol_event = ss_sub.materialize(mode="event")

        if not torch.is_tensor(event):
            return _PeerBResult(None, symbol_event, p)

        # The only conceptual mutation in B.  CS receives the completed SS
        # representation and the (possibly absent) delayed Language plan as
        # explicit peer outputs, then publishes CSsym itself.
        cs_sym = cs.commit_symbolic_peer_results(
            event, symbol_event=symbol_event,
            prior_symbolic_event=prior_symbolic_event,
            language_plan=grammar_feedback)
        self._maybe_blend_event(
            cs_sym, prior_symbolic_event, a_result.gate_b_1)
        object.__setattr__(cs, "_peer_prev_sym", cs.CSsym)

        if cache_only:
            return event, a_result.concept_orders, a_result.word_concept_row, a_result.word_concept_activation
        idea_bd = None
        grammar_snapshot = None
        if event.dim() == 3 and event.shape[1] >= 1:
            idea_bd = event[:, 0, :]
            if (getattr(self, 'concept_index_read', False)
                    and not torch.compiler.is_compiling()):
                idea_bd = self._maybe_concept_index_read(idea_bd)
            if stm is not None and a_result.active_host:
                _protect = None
                if (not torch.compiler.is_compiling()
                        and stm._buffer is not None):
                    _Bp = int(stm._buffer.shape[0])
                    _rel = self._sentence_relative_mask(
                        _Bp, device=stm._buffer.device)
                    _protect = torch.where(
                        _rel,
                        torch.full((_Bp,), 3, dtype=stm._depth.dtype,
                                   device=_rel.device),
                        torch.ones(_Bp, dtype=stm._depth.dtype,
                                   device=_rel.device))
                _compiled_recurrent = bool(
                    self._compiled_word_chunk_replaying
                    or (torch.compiler.is_compiling()
                        and getattr(self, "_compiled_word_loop_fullgraph",
                                    False)))
                if _compiled_recurrent:
                    cs._stm_predict_then_perceive_serial_fixed(
                        idea_bd, row_gate=a_result.commit_b_1)
                else:
                    cs._stm_predict_then_perceive_serial(
                        idea_bd, row_gate=a_result.commit_b_1)
                _concept_orders = a_result.concept_orders
                if (torch.is_tensor(_concept_orders)
                        and _concept_orders.dim() == 2
                        and int(_concept_orders.shape[0])
                        == int(idea_bd.shape[0])):
                    _word_concept_order = _concept_orders[:, 0].to(
                        device=idea_bd.device, dtype=torch.long)
                else:
                    _word_concept_order = torch.full(
                        (int(idea_bd.shape[0]),), -1,
                        dtype=torch.long, device=idea_bd.device)
                _word_grammar_order = torch.zeros_like(_word_concept_order)
                commit = self._compose_admission(a_result.commit_b_1)
                stm.push_step_masked(
                    idea_bd, commit,
                    orders=_word_concept_order,
                    grammar_orders=_word_grammar_order,
                    concept_row=a_result.word_concept_row,
                    concept_activation=a_result.word_concept_activation)
                # Coarser-whole provenance (fold-ladder plan, Phase 2b).
                self._push_unit_provenance(stm, commit, p)
                if not _compiled_recurrent:
                    stm._max_depth_host = stm._max_depth_host + 1

                # C owns the grammar call.  Snapshot the post-push, pre-reduce
                # state the old eager fire consumed, but make it an explicit
                # working tensor because subsequent B ticks mutate STM.
                # Mirror ``_chart_compose_per_word``'s two-constituent
                # admission rule.  The full-router has no action routing for
                # a one-item stack, so sending that early drain snapshot into
                # Language would fabricate an invalid grammar request.
                _grammar_ready = (
                    torch.compiler.is_compiling()
                    or int(getattr(stm, "_max_depth_host", 0)) >= 2)
                if _grammar_ready:
                    snap = stm.snapshot()
                    if torch.is_tensor(snap):
                        grammar_snapshot = snap.detach().clone()

                _protect = None
                if (not torch.compiler.is_compiling()
                        and stm._buffer is not None):
                    _Bp = int(stm._buffer.shape[0])
                    _rel = self._sentence_relative_mask(
                        _Bp, device=stm._buffer.device)
                    _protect = torch.where(
                        _rel,
                        torch.full((_Bp,), 3, dtype=stm._depth.dtype,
                                   device=_rel.device),
                        torch.ones(_Bp, dtype=stm._depth.dtype,
                                   device=_rel.device))
                self._stm_word_rounds(commit, p)

            contribution = torch.where(
                a_result.gate_b_1, idea_bd, torch.zeros_like(idea_bd))
            if (a_result.out_slot is not None
                    and isinstance(a_result.out_slot, list)
                    and 0 <= p < len(a_result.out_slot)):
                a_result.out_slot[p] = contribution
        return _PeerBResult(grammar_snapshot, symbol_event, p)

    def _peer_stage_c(self, b_result, p):
        """Return feedback from this word's recorded operation choices."""
        if b_result is None or b_result.symbolic_snapshot is None:
            return None
        if getattr(self, 'router_wire_serial', 'both') not in ('per-word', 'both'):
            return None
        trace = self._reconstruction_stack()
        if trace is None or trace._choice_rule_ids is None:
            return None
        ids = trace._choice_rule_ids[:, 3 * p:3 * p + 3]
        valid = trace._choice_mask[:, 3 * p:3 * p + 3]
        n = int(self.languageSpace._n_rules)
        counts = b_result.symbolic_snapshot.new_zeros(ids.shape[0], n)
        legal = valid & (ids >= 0) & (ids < n)
        counts = counts.scatter_add(1, ids.clamp(0, max(0, n - 1)), legal.to(counts.dtype))
        mass = counts.sum(-1, keepdim=True)
        from Language import RoutingState
        return {'rules': {}, 'routing': RoutingState(
            rule_probs=counts / mass.clamp_min(torch.finfo(counts.dtype).tiny)),
            'generation': p + 1}

    def _tensor_peer_while_ready(self, width):
        """Whether the staged sentence satisfies the functional HOP contract.

        The first production slice intentionally targets the canonical aligned
        word-major model.  Every required tensor is already staged by the eager
        lexical boundary; an older/more general configuration keeps using the
        static reference scheduler instead of silently changing its math.
        """
        if (not self._tensor_peer_while_enabled
                or not (torch.compiler.is_compiling()
                        or self._tensor_peer_while_eager
                        or self.reconstruct_in_loop)
                or not getattr(self, "serial_object_meta", False)
                or getattr(self, "concept_binding", "mixing") != "aligned"
                or getattr(self, "sentence_protocol", False)
                or getattr(self, "concept_index_read", False)
                or getattr(self, "router_wire_serial", "both")
                not in ("per-word", "both")):
            return False
        isp = self.inputSpace
        ws = self.wholeSpace
        cs = self.conceptualSpace
        stm = getattr(cs, "stm", None)
        if stm is None:
            return False
        required = (
            getattr(isp, "_ar_embedded_N", None),
            getattr(isp, "_word_active_mask", None),
            getattr(isp, "_ar_word_part_ids", None),
            getattr(isp, "_ar_word_part_mask", None),
            getattr(isp, "_ar_word_part_offsets", None),
            getattr(isp, "_ar_word_concept_rows", None),
            getattr(isp, "_ar_word_concept_orders", None),
            getattr(isp, "_ar_word_object_rows", None),
            getattr(isp, "_ar_word_object_orders", None),
            getattr(isp, "_ar_word_object_atoms", None),
            getattr(isp, "_ar_concept_lookup_rows", None),
            getattr(isp, "_ar_concept_lookup_atoms", None),
            getattr(isp, "_ar_percept_reference_codes", None),
            getattr(isp, "_ar_percept_reference_roles", None),
            getattr(isp, "_ar_part_reference_vectors", None),
            getattr(isp, "_ar_whole_reference_vectors", None),
            getattr(isp, "_ar_readout_coefficients", None),
            getattr(isp, "_ar_whole_reference_presence", None),
            getattr(isp, "_packed_sentence_end_mask", None),
            getattr(isp, "_packed_sentence_intermediate_end_mask", None),
            getattr(isp, "_packed_sentence_ids", None),
            getattr(ws, "_staged_word_primitive_counts", None),
            getattr(stm, "_buffer", None),
            getattr(stm, "_depth", None),
        )
        if not all(torch.is_tensor(value) for value in required):
            return False
        slab, active = required[:2]
        if (slab.dim() != 3 or active.dim() != 2
                or int(slab.shape[1]) != int(width)
                or tuple(active.shape) != tuple(slab.shape[:2])):
            return False
        reducer = self._stm_reducer()
        layer = getattr(cs, "intraSentenceLayer", None)
        language = getattr(self, "languageSpace", None)
        n_rules = int(getattr(language, "_n_rules", 0) or 0)
        routing_dim = int(getattr(layer, "routing_dim", 0) or 0)
        return (
            reducer is not None and layer is not None
            and language is not None and language.language_layer is not None
            and n_rules > 0 and routing_dim == n_rules
        )

    @staticmethod
    def _tensor_write_word_column(slab, index, values):
        """Return ``slab`` with one dynamic word column replaced."""
        B, width, D = slab.shape
        safe = index.clamp(0, width - 1)
        if int(safe.numel()) == 1:
            scatter_index = safe.reshape(1, 1, 1).expand(B, 1, D)
        else:
            scatter_index = safe.reshape(B, 1, 1).expand(B, 1, D)
        return slab.scatter(1, scatter_index, values.unsqueeze(1))

    @staticmethod
    def _tensor_record_operands(left_slab, right_slab, index, state, valid):
        """Record the operand rows of a binary fold at trace column
        ``index``: the concept rows of STM slot 1 (left, older) and slot 0
        (right, newest) of ``state`` (a functional STM state tuple), -1
        where the fold did not fire."""
        rows = state[4]
        B, width = int(left_slab.shape[0]), int(left_slab.shape[1])
        active = valid.reshape(B).to(device=left_slab.device, dtype=torch.bool)
        left = torch.where(active, rows[:, 1] if int(rows.shape[1]) > 1 else torch.full_like(rows[:, 0], -1),
                           torch.full_like(rows[:, 0], -1))
        right = torch.where(active, rows[:, 0], torch.full_like(rows[:, 0], -1))
        column = index.clamp(0, width - 1).reshape(-1, 1).expand(B, 1)
        return (left_slab.scatter(1, column, torch.where(active[:, None], left[:, None], left_slab.gather(1, column))),
                right_slab.scatter(1, column, torch.where(active[:, None], right[:, None], right_slab.gather(1, column))))

    @staticmethod
    def _sentence_journal_layout(active, sentence_ids, closing_width, trace_width):
        """Map row-wide trace addresses to one open sentence's numerical frames.

        Endings train and discard these frames before the next sentence.
        Structural choices retain their row-wide addresses; only their bulky
        operands/results, references and offsets reuse sentence-local storage.
        Called at the eager sentence boundary, before compiling word bricks.
        """
        B, W = active.shape
        positions = torch.arange(W, device=active.device).expand(B, -1)
        # Count actual words, so an inactive column inside a sentence
        # neither consumes a frame nor makes its next word alias the first.
        ordinal = active.long().cumsum(dim=1) - 1
        owners = sentence_ids.clamp(0, W - 1)
        starts = torch.full_like(positions, W).scatter_reduce(
            1, owners, torch.where(active, ordinal, W), reduce='amin')
        local = torch.where(active, ordinal - starts.gather(1, owners), 0)
        # Select a bound from the loop's existing static word buckets before
        # compiling, never an arbitrary sentence length. The minimum normal
        # bucket is eight; a smaller configured capacity remains unchanged.
        # A large packed-row ceiling need not make every sentence's numerical
        # records that large. One closing window serves every packed sentence.
        needed = max(1, int(torch.where(active, local + 1, 0).amax().item()))
        bounds = sorted({int(W), *(v for v in StaticPeerPipeline.WIDTHS
                                   if 8 <= v <= int(W))})
        words = next(v for v in bounds if v >= needed)
        rounds = (3 * local[..., None] + torch.arange(3, device=active.device)).flatten(1)
        endings = (3 * words + torch.arange(trace_width - 3 * W,
                                            device=active.device) % closing_width)
        return torch.cat((rounds, endings[None].expand(B, -1)), dim=1), 3 * words + closing_width

    @staticmethod
    def _tensor_record_selected_values(journal, slot, value, active):
        B = journal.shape[0]
        column = slot.reshape(-1, 1, 1).expand(B, 1,
                                               journal.shape[-1]).clamp(0, journal.shape[1] - 1)
        selected = torch.where(active[:, None], value, journal.gather(1, column)[:, 0])
        return journal.scatter(1, column, selected[:, None])

    @staticmethod
    def _tensor_record_choice(trace_state, index, local_op, valid,
                              local_loss, arity, rule_map, *,
                              record_loss):
        """Pure dynamic-column equivalent of ReconstructionStack.record_choice."""
        rule_ids, arities, mask, losses, loss_mask = trace_state
        B, width = rule_ids.shape
        map_width = int(rule_map.numel())
        if map_width == 0:
            return trace_state
        local = local_op.reshape(B).to(
            device=rule_ids.device, dtype=torch.long)
        active = valid.reshape(B).to(
            device=rule_ids.device, dtype=torch.bool)
        active = torch.logical_and(active, local >= 0)
        active = torch.logical_and(active, local < map_width)
        safe_local = local.clamp(0, map_width - 1)
        chosen = rule_map.to(
            device=rule_ids.device, dtype=torch.long
        ).index_select(0, safe_local)
        chosen = torch.where(
            active, chosen, torch.full_like(chosen, -1))
        safe_column = index.clamp(0, width - 1).reshape(-1, 1).expand(B, 1)
        next_ids = rule_ids.scatter(1, safe_column, chosen.reshape(B, 1))
        chosen_arity = torch.where(
            active,
            torch.full_like(chosen, int(arity), dtype=torch.int8),
            torch.zeros_like(chosen, dtype=torch.int8))
        next_arities = arities.scatter(
            1, safe_column, chosen_arity.reshape(B, 1))
        next_mask = mask.scatter(1, safe_column, active.reshape(B, 1))
        loss_active = (
            active if bool(record_loss) else torch.zeros_like(active))
        local_loss = local_loss.reshape(B).to(
            device=losses.device, dtype=losses.dtype)
        local_loss = torch.where(
            loss_active, local_loss, torch.zeros_like(local_loss))
        next_losses = losses.scatter(
            1, safe_column, local_loss.reshape(B, 1))
        next_loss_mask = loss_mask.scatter(
            1, safe_column, loss_active.reshape(B, 1))
        return (
            next_ids, next_arities, next_mask,
            next_losses, next_loss_mask)

    @staticmethod
    def _tensor_record_operation(trace_state, position_slab, action_slab, attempted_slab,
                                 index, choice, binary_map, unary_map):
        ids, arities, mask, losses, loss_mask = trace_state
        B, width = ids.shape
        chosen = torch.full_like(choice.local_op, -1)
        for kind, mapping in ((1, binary_map), (2, unary_map)):
            if mapping.numel():
                mapped = mapping.index_select(0, choice.local_op.clamp(0, mapping.numel() - 1))
                chosen = torch.where(choice.applied & (choice.kind == kind), mapped, chosen)
        column = index.clamp(0, width - 1).reshape(-1, 1).expand(B, 1)
        def write(slab, value):
            value = torch.where(choice.valid.reshape(B, 1), value.to(slab.dtype).reshape(B, 1), slab.gather(1, column))
            return slab.scatter(1, column, value)
        arity = torch.where(choice.applied, torch.where(choice.kind == 1, 2, 1), 0)
        return ((write(ids, chosen), write(arities, arity), write(mask, choice.applied), losses, loss_mask),
                write(position_slab, choice.position), write(action_slab, choice.action),
                write(attempted_slab, choice.valid))

    def _project_sentence_parameters(self):
        with torch.no_grad():
            for ws in self.wholeSpaces:
                primitives = getattr(getattr(ws.subspace, 'what', None), 'primitive_properties', None)
                if primitives is not None:
                    primitives.project()
            for cs in self.conceptualSpaces:
                allocator = getattr(cs, '_concept_allocator', None)
                if allocator is not None:
                    for layer in allocator._layers.values():
                        layer.project_parts()
        self._clamp_symbolic_codebook()
        self._normalize_perceptual_embedding()

    def _attention_sentence_payload(self, payload, index):
        """Field operations change the pole, preserving form and magnitude."""
        reading = getattr(self, '_attention_words', None)
        if reading is None:
            return payload
        event, orders, row, activation, obj, obj_order, atom, gate, commit, routing, valid = payload
        w = index.clamp(0,reading.accepted.shape[1]-1)
        B = event.shape[0]
        from ModelAttention import read_poles, pole_activation
        pair = read_poles(self, '_attention_sentence_payload').gather(
            1,w.reshape(1,1,1).expand(B,1,2)).squeeze(1)
        changed = reading.pole_changes.gather(1,w.reshape(1,1).expand(B,1))
        activation = pole_activation(activation, pair, changed)
        # interpret resolves atom * activation; multiplying atom would apply
        # the evidence twice and turn a negative witness positive again.
        pole_representation = getattr(self, '_attention_pole_representation', False)
        if pole_representation:
            event = pair[:,None].to(event)
            atom = pair.to(atom)
            activation = torch.ones_like(activation)
        return (event,orders,row,activation,obj,obj_order,atom,gate,
                commit & reading.accepted.gather(1,w.reshape(1,1).expand(B,1)).reshape_as(commit),routing,valid)

    def _compose_score_function_loss(self, path, costs):
        """§16.3: p(departure) times its detached paired cost difference.

        Both trials were costed at one parameter version. The uniform
        departure draw is independent of the chooser's probability; this is
        the correction K*R_walk*W for uniform walk, round and action draws.
        The scorer's features are detached, so the ordinary reconstruction
        owner can train the chooser without writing perception or operators.
        Exact ties register no term and supply no momentum-only update.
        """
        costs = costs.detach()
        forced = self._compose_forced_slots
        mask = ((torch.zeros_like(path[1][18], dtype=torch.bool) if forced is None
                 else forced) & (path[1][18] >= 0))
        advantage = costs[:, 1] - costs[:, 0]
        probabilities = path[1][27].exp()
        scale = getattr(self, "_compose_sampling_scale", None)
        if scale is None:
            raise RuntimeError("compose surrogate requires the sampled proposal correction")
        scale = scale.detach().to(probabilities)
        actions = path[1][18].detach()
        walks = torch.ones_like(actions)
        draw = getattr(self, '_sentence_departure', None)
        reading = getattr(self, '_attention_words', None)
        if draw is not None and reading is not None:
            attention_mask = (torch.arange(reading.actions.shape[1],device=costs.device)[None]
                              == draw['attention_round'][:,None])
            mask = torch.cat((attention_mask,mask),-1)
            probabilities = torch.cat((reading.probabilities,probabilities),-1)
            scale = torch.cat((reading.alternative_counts *
                (draw['walk_count'] * draw['walk_rounds'])[:,None],scale),-1)
            actions = torch.cat((reading.actions.detach(),actions),-1)
            walks = torch.cat((torch.zeros_like(reading.actions),walks),-1)
        from SentenceCredit import score_function
        surrogate, record = score_function(probabilities, scale, mask, costs)
        self._last_compose_score_function = dict(record, actions=actions, walk=walks)
        if not surrogate.requires_grad:
            return probabilities.new_zeros(())
        self._sentence_cost_registry.add('reconstruction.compose_score_function', surrogate,
            category='reconstruction')
        active = self._sentence_cost_registry.row_mask
        return (surrogate.mean() if active is None else
                (surrogate * active).sum() / active.sum().clamp_min(1))

    def _sentence_train_step(self, loss):
        """Train one derivation; public time/episode accounting stays at batch end."""
        optimizer = self._sentence_optimizer
        if optimizer is None:
            raise RuntimeError('sentence training requires the live optimizer')
        self._adopt_fresh_parameters(optimizer)
        optimizer.zero_grad()
        self._sentence_backward = True
        try:
            self._backward_training_loss(loss, self._sentence_amp_scaler)
        finally:
            self._sentence_backward = False
            self._sentence_pullback = None
        self._assert_finite_train_state('after sentence backward')
        # The same proximal regularizer belongs to each actual smooth update.
        # Input-only batches may have no additional batch-end backward at all.
        self._configure_concept_readout_l1(optimizer)
        if self.ergodic:
            self.paramUpdate()
        if self._sentence_amp_scaler is not None:
            from LearningEvaluation import scaler_step_performed
            scaler_step_performed(self._sentence_amp_scaler, optimizer)
        else:
            preflight_finite_gradients(optimizer, self.named_parameters(),
                cache_for_step=hasattr(optimizer, '_step_without_finite_preflight'))
            optimizer.step()
        self._project_sentence_parameters()
        self._advance_codebook_parameter_versions()
        self._assert_finite_train_state('after sentence optimizer.step')
        optimizer.zero_grad()

    @staticmethod
    def _snapshot_sentence_state(state):
        return state

    def _restore_sentence_state(self, state):
        self._publish_sentence_scratch(state)

    def _publish_sentence_scratch(self, state):
        """Install bounded STM/trace values for scoring, without observing them."""
        current_stm, lang, feedback = state
        stm = self.conceptualSpace.stm
        (stm._buffer, stm._depth, stm._orders, stm._grammar_orders,
         stm._concept_rows, stm._concept_activations) = current_stm
        stm._clause_state = lang[20]
        stm._last_unary = lang[25]
        stm._unary_history_depth = current_stm[1]
        stm._wholes = lang[10]
        trace = self._reconstruction_stack()
        for name, value in zip(('_choice_rule_ids', '_choice_arities', '_choice_mask',
                                '_forward_losses', '_forward_loss_mask'), lang[4:9]):
            setattr(trace, name, value)
        for name, value in zip(('_choice_left_rows', '_choice_right_rows',
                                '_choice_positions', '_choice_actions', '_choice_attempted'), lang[15:20]):
            setattr(trace, name, value)
        trace._choice_ends = lang[21]
        trace._choice_values = lang[22]
        trace._choice_journal_columns = getattr(self, '_sentence_journal_columns', None)
        trace._choice_refs = lang[23]
        trace._choice_ref_relations = lang[24]
        trace._choice_alternative_counts = lang[26]
        trace._choice_explorable = lang[26] > 0
        self._packed_sentence_roots = lang[9]
        self._tensor_sentence_roots_live = lang[13]
        self._tensor_sentence_roots_depth = lang[14]
        B, W = lang[0].shape[:2]
        D = current_stm[0].shape[-1]
        self._tensor_pushed_ideas = self._pushed_word_slab(B, W, D, current_stm[0], lang[0])
        isp = self.inputSpace
        object_rows = getattr(isp, '_ar_word_object_rows', None)
        concept_rows = getattr(isp, '_ar_word_concept_rows', None)
        if torch.is_tensor(object_rows) and torch.is_tensor(concept_rows):
            rows = torch.where(object_rows >= 0, object_rows, concept_rows)
            orders = torch.where(object_rows >= 0, isp._ar_word_object_orders, isp._ar_word_concept_orders)
            grammar_rows = getattr(isp, '_ar_grammar_object_rows', None)
            if torch.is_tensor(grammar_rows):
                rows = torch.where(grammar_rows >= 0, grammar_rows, rows)
                orders = torch.where(grammar_rows >= 0, isp._ar_grammar_object_orders, orders)
            from ModelAttention import reference_evidence
            self.symbolSpace.commit_word_reference_slab(rows, lang[0],
                isp._word_active_mask, orders=orders,
                evidence=reference_evidence(self, lang[0], 'commit_word_reference_slab:per_word'))

    def _sentence_observation(self, state, sid, active, *, admit=False):
        current_stm, lang, _feedback = state
        B, _K, D = current_stm[0].shape
        depths = lang[14][:, sid]
        mask = active & (depths > 0)
        slots = lang[13][:, sid].reshape(B, 3, D)
        payloads = [slots[b, :int(depths[b])] if bool(mask[b]) else None for b in range(B)]
        depth_list = [int(d) if bool(m) else 0 for d, m in zip(depths, mask)]
        _current, programs = self._capture_reading_programs(sentence_slot=sid, admit=admit)
        entries = programs.get(sid, (None,) * B)
        disc = getattr(self.symbolSpace, 'expectation', None)
        clauses = []
        meanings, observed, observed_depths, layout, roles = _boundary_observation_view(
            self.languageSpace, _boundary_registry(self), entries, payloads, depth_list,
            structured=getattr(disc, 'expectation_scope', None) == 'structured', clauses=clauses)
        return dict(payloads=payloads, depths=depth_list, mask=mask, entries=entries,
                    meanings=meanings, observed=observed, observed_depths=observed_depths,
                    layout=layout, roles=roles, clauses=clauses)

    def _trial_understanding(self, state, sid, active):
        from SentenceUnderstanding import SentenceUnderstanding
        current, lang, feedback = state
        root = lang[9][:, sid]
        B, D = root.shape
        word_rows = getattr(self.inputSpace, '_ar_grammar_object_rows', None)
        if not torch.is_tensor(word_rows):
            word_rows = self._word_symbol_rows()
        words = self._tensor_pushed_ideas
        if not torch.is_tensor(word_rows):
            word_rows = torch.full(words.shape[:2], -1, device=root.device, dtype=torch.long)
        valid = self.inputSpace._word_active_mask & (self.inputSpace._packed_sentence_ids == sid)
        leaf = getattr(self.inputSpace, '_ar_grammar_leaf_mask', None)
        if torch.is_tensor(leaf):
            valid = valid & leaf
        return SentenceUnderstanding(root, lang[13][:, sid].reshape(B, 3, D), lang[14][:, sid],
            lang[13], lang[14], words, word_rows, valid,
            self._sentence_primed_bank, torch.tensor(sid, device=root.device))



    def _reconstruct_trial(self, record):
        """Cost a greedy walk and one departure before either graph trains.

        The byte relative error is the entire comparison. The
        selected graph supplies reconstruction's gradient; strict ties keep
        greedy. Evaluation decodes once, without drawing an explore round.
        """
        from SentenceCompose import select_rows
        training = getattr(self, '_sentence_training', False) and torch.is_grad_enabled()
        def decode(**options):
            result, trace = self._compiled_reconstruct()(record.root.clone(), record.word_values,
                record.roots, record.depths, record.end_slots.clone(), record.end_depth.clone(),
                record.sentence, understanding=record, return_decoded=True, **options)
            return result, trace
        greedy, trace = decode(decoder_candidates=True) if training else decode()
        self._last_decoder_comparison = None
        self._last_decoder_trace = trace[:5]
        if not training:
            return greedy
        eligible = trace[5]
        rank = (torch.rand(eligible.shape[0], device=eligible.device) * eligible.sum(-1)).long()
        selected = eligible & (eligible.long().cumsum(-1) == rank[:, None] + 1)
        departure = torch.where(eligible.any(-1), selected.long().argmax(-1), -1)
        explore, other = decode(decoder_exploit=trace[4], decoder_departure=departure)
        costs = torch.stack((greedy[2]/math.log(256),
                             explore[2]/math.log(256)), -1).detach()
        wins = eligible.any(-1) & (costs[:, 1] < costs[:, 0])
        self._last_decoder_comparison = dict(costs=costs, wins=wins, departure=departure,
            greedy=trace[4].detach(), explore=other[4].detach())
        from WalkTrials import observe_comparison
        observe_comparison(self,"generate.decoder",self._last_decoder_comparison,
            sentence=int(record.sentence),active=record.end_depth>0)
        self._last_decoder_trace = select_rows(trace[:5], other[:5], wins)
        return select_rows(greedy, explore, wins)

    def _decomposition_teacher_loss(self, observation, record):
        """Teacher-force actual compose operands; targets never enter free decoding.

        Pair identities come from the input positions, not nearest-code labels.
        A compound or missing symbol outside this word shortlist is counted and
        contributes no term. Both trials' teacher graphs precede either step;
        CE is added only in the owner step, after the byte-cost comparison.
        """
        from DecompositionChooser import DecompositionChooser
        bank = record.primed
        chooser = self.languageSpace.decomposition_chooser
        terms = [[] for _ in observation['entries']]
        reports = []
        ops = self.languageSpace.language_layer.operation_layer.ops
        for b, program in enumerate(observation['entries']):
            if program is None or program.operation_values is None:
                continue
            stack = []
            # The reconstruction record carries the same resolved physical
            # symbol rows as its primed bank. The legacy WORD lane can be
            # absent in the open perceptual read and is not this address space.
            word_rows = record.word_rows[b][record.word_valid[b]]
            for index, (kind, op_index, word) in enumerate(program.actions.detach().cpu().tolist()):
                if kind == 0:
                    stack.append(int(word_rows[word]))
                elif kind == 2:
                    continue
                elif kind == 1:
                    right = stack.pop(); left = stack.pop(); stack.append(-1)
                    parent = program.operation_values[index, 2].detach()[None]
                    op = getattr(ops[op_index], 'gl', ops[op_index])
                    if getattr(op, 'inverse_kind', None) == 'case_search':
                        continue  # CaseSelection has its own non-word candidate algebra.
                    valid = bank.valid[b:b+1]
                    if not bank.codes.shape[1]:
                        reports.append(dict(row=b, operation=op_index, present=False, picked_true=False))
                        continue
                    _, _, _, details = self.languageSpace._bounded_binary_reconstruction(
                        op, parent, torch.zeros_like(parent),
                        torch.zeros(1, dtype=torch.bool, device=parent.device),
                        torch.zeros(1, dtype=torch.bool, device=parent.device),
                        bank.codes[b:b+1], valid, self.reconstruction_basis_limit,
                        left_priming=bank.weights[b:b+1], right_priming=bank.weights[b:b+1],
                        chooser=chooser, return_details=True)
                    target = torch.tensor([[left, right]], device=parent.device)
                    loss, present, picked = DecompositionChooser.teacher_loss(
                        details, bank.rows[b:b+1], bank.rows[b:b+1], target)
                    if bool(present[0]):
                        terms[b].append(loss[0])
                    reports.append(dict(row=b, operation=op_index,
                        target=[left, right], present=bool(present[0]), picked_true=bool(picked[0])))
        zero = record.root.new_zeros(())
        loss = torch.stack([torch.stack(row).mean() if row else zero for row in terms])
        self._last_decomposition_teacher = reports
        return loss

    def _decomposition_walk_teacher_loss(self, observation, record):
        """Teach undo/unary/STOP on the actual compose tree's detached states.

        Each leaf teaches STOP; each recorded parent teaches its declared
        generate face. Replaying these states is teacher forcing, independent
        of the free decoder's decisions, legal mask and numerical inverses.
        No target or compose trace enters inference.
        """
        language = self.languageSpace
        stop = len(language._generate_binary_ops) + len(language._generate_unary_ops)
        keys = language._generate_rule_keys.detach().cpu().tolist() if language.generate_policy is not None else []
        mappings = {}
        for kind, arity, rules in ((1, 2, language._compose_binary_rules),
                                    (2, 1, language._compose_unary_rules)):
            for index, rule in enumerate(rules):
                key = language._generate_rule_key(rule, arity)
                mappings[kind, index] = keys.index(key) if key in keys else -1
        terms, reports = [], []
        for b, program in enumerate(observation['entries']):
            states, targets = [], []
            if program is not None and program.operation_values is not None:
                for index, (kind, operation, word) in enumerate(program.actions.detach().cpu().tolist()):
                    if kind == 0:
                        value, target = program.leaves[word], stop
                    elif kind in (1, 2):
                        value = program.operation_values[index, 2]
                        target = mappings.get((kind, operation), -1)
                    else:
                        continue
                    reports.append(dict(row=b, kind=kind, operation=operation, target=target,
                                        present=target >= 0))
                    if target >= 0:
                        states.append(value.detach())
                        targets.append(target)
            if states and language.generate_policy is not None:
                logits = language.generate_policy_logits(torch.stack(states))
                target = torch.tensor(targets, device=logits.device)
                terms.append(F.cross_entropy(logits, target))
            else:
                terms.append(record.root.new_zeros(()))
        self._last_decomposition_walk_teacher = reports
        return torch.stack(terms)

    def _sentence_path_cost(self, state, sid, active):
        """Both trials use the registry's named, relative objectives."""
        self._publish_sentence_scratch(state)
        current_stm, lang, _feedback = state
        B, W, D = self._tensor_pushed_ideas.shape
        slots = lang[13][:, sid].reshape(B, 3, D)
        depths, root = lang[14][:, sid], lang[9][:, sid]
        errors = Error(row_mask=active)
        record = self._trial_understanding(state, sid, active)
        if getattr(self, '_sentence_reconstruction', self.reconstruct_in_loop):
            reconstruction = self._reconstruct_trial(record)
            available = self.inputSpace._reconstruction_sentence_available[:, sid] & active
            errors.error('reconstruction.free_bytes', reconstruction[2], math.log(256), mask=available,
                weight=self.loss.reconstruction_scale, category='reconstruction')
        else:
            zero = root.sum(-1) * 0
            reconstruction = (root.new_zeros(B, W, D), zero, zero,
                              torch.zeros(B, dtype=torch.bool, device=root.device), lang[14].to(root) * 0)
        observation = self._sentence_observation(state, sid, active)
        observation['record'] = record
        observation['decomposition_loss'] = (self._decomposition_teacher_loss(observation, record)
            if getattr(self, '_sentence_training', False) and torch.is_grad_enabled() else None)
        observation['walk_loss'] = (self._decomposition_walk_teacher_loss(observation, record)
            if getattr(self, '_sentence_training', False) and torch.is_grad_enabled() else None)
        if getattr(self, '_reading_lesson_enabled', False) and self.grammar_lesson_weight > 0:
            source_rows = self._reading_lesson_sources
            for b, program in enumerate(observation['entries']):
                if program is None or not bool(active[b]):
                    continue
                source = None if source_rows is None else source_rows[b]
                if isinstance(source, (tuple, list)):
                    source = source[sid] if sid < len(source) else None
                objectives = self._grammar_lesson_objectives([program],
                    split=self._reading_lesson_split, source_rows=[source])
                if objectives:
                    for name, value in objectives.items():
                        errors.merge(self._grammar_lesson_errors[name], prefix='grammar.',
                                     weight=self.grammar_lesson_weight, row=b)
                    self._reading_lesson_reports.append(torch.stack(tuple(objectives.values())).sum().detach())
        disc = getattr(self.symbolSpace, 'expectation', None)
        pending = None
        self._sentence_expectation_comparison = None
        if disc is not None:
            inter, contrast, pending = disc.sentence_prediction_cost(
                observation['observed_depths'], observation['observed'], observation['mask'],
                documents=self._expectation_documents_for_slot(sid, B),
                layout=observation['layout'], role_masks=observation['roles'],
                sentence_kinds=[None if m is None else m.sentence_kind for m in observation['meanings']],
                gain=getattr(self, 'expectation_gain', 1.))
            gated = disc._sentence_comparison_errors.total()
            if gated is not None:
                self._sentence_expectation_comparison = gated * self.inter_loss_weight
            if self.inter_loss_weight > 0:
                errors.merge(disc._sentence_prediction_errors[0],
                             prefix='expectation.', weight=self.inter_loss_weight)
            if self.inter_contrastive_weight > 0:
                errors.merge(disc._sentence_prediction_errors[1],
                             prefix='expectation.', weight=self.inter_contrastive_weight)
        word_inputs = getattr(self, '_word_expectation_input', None)
        word_expected = (None if word_inputs is None or disc is None else disc.expect('word', *word_inputs,
            teacher_forcing=bool(self.training), gain=self.word_expectation_gain,
            active=self._word_expectation_mask))
        if word_expected is not None and self.word_expectation_weight > 0:
            mask = self._word_expectation_mask & (self.inputSpace._packed_sentence_ids == sid)
            loss = (word_expected.loss * mask).sum(-1) / mask.sum(-1).clamp_min(1)
            errors.error('expectation.word', loss, 1., mask=active & mask.any(-1),
                         weight=self.word_expectation_weight, category='expectation')
        BasicModel._sentence_answer_error(self, state, sid, active, observation, registry=errors)
        if getattr(self, '_sentence_training', False):
            configure_l1 = getattr(self, '_configure_concept_readout_l1', None)
            penalty = None if configure_l1 is None else configure_l1(None, stage=False)
            if penalty is not None:
                strength = self._concept_readout_l1_strength
                errors.add('concept_readout_l1', penalty / strength, weight=strength,
                           category='reg', trained=False)
        self._sentence_cost_registry = errors
        self._sentence_gradient_objectives = {name: errors.total(objective=name)
            for name in ('reconstruction', 'expectation', 'output')}
        cost = errors.total()
        if cost is None:
            cost = root.sum(-1) * 0
        elif cost.ndim == 0:
            cost = cost.expand(B)
        return cost, reconstruction, observation, pending

    def _sentence_answer_error(self, state, sid, active, observation, *, registry=None):
        """The presented reader supplies output training; its twin supplies A."""
        presented = Error(row_mask=active)
        self._sentence_reader_observation = None
        self._sentence_comparison_registry = Error(row_mask=active)
        cost = BasicModel._sentence_reader_error(self, state, sid, active, observation,
                                               registry=presented)
        if cost is None:
            return None
        presented_read = dict(mse=self._sentence_answer_raw_cost.detach(),
                              predictions=self._sentence_answer_predictions.detach())
        if registry is not None:
            registry.merge(presented)
        reader = getattr(self, 'comparison_reader', None)
        if reader is not None:
            cost = reader(self, state, sid, active, observation,
                          registry=self._sentence_comparison_registry)
        self._sentence_reader_observation = dict(presented=presented_read,
            comparison=dict(mse=self._sentence_answer_raw_cost.detach(),
                            predictions=self._sentence_answer_predictions.detach()))
        self._sentence_answer_cost = cost
        return cost

    def _sentence_reader_error(self, state, sid, active, observation, *, registry=None):
        """A supplied answer trains only this trial's reader of the understanding.

        The target is loss-side metadata: it never enters composition. Both
        trials read it after composing, before either optimizer update. The
        understanding is detached at its reader; reconstruction owns its graph.
        """
        self._sentence_answer_cost = None
        destination = registry
        # Keep the supplied answer distinct from generation lessons. Its
        # detached error enters the comparison and remains observable;
        # the reader's single update is assembled after both trials are scored.
        registry = Error(row_mask=active)
        target = getattr(self, '_sentence_supplied_answers', None)
        if (not getattr(self, '_sentence_training', False)
                or not torch.is_tensor(target) or not target.numel()
                or not self.inputSpace.data.has_supervised_outputs):
            return None
        _stm, lang, _feedback = state
        root = lang[9][:, sid]
        slots = lang[13][:, sid].reshape(root.shape[0], 3, root.shape[-1])
        depth = lang[14][:, sid]
        if getattr(self, 'answer_synthesis', False):
            data = self.inputSpace.data
            questions = self._sentence_answer_questions
            desired = tuple(data.what(question) for question in questions)
            values = [answer.what if answer.available and question.relation is WhatRelation.SUPERVISED
                      else None for question, answer in zip(questions, desired)]
            if not any(value is not None for value in values):
                return None
            # Realize this trial's completed field without a query or a write.
            # Generation is the reading map in these configurations. Its
            # normal batch-end call still takes the default state cut.
            # Match _commit_sentence's completed point: an open clause may
            # still describe two pre-fusion roles, which are not an end state.
            meanings = [
                replace(ConceptualMeaning.from_description(clause.point),
                        mode=meaning.mode, polarity=meaning.polarity, sentence_kind='idea')
                if clause is not None and clause.relation is None else meaning
                for meaning, clause in zip(observation['meanings'], observation['clauses'])]
            meanings = [None if meaning is None else meaning.detached() for meaning in meanings]
            fields = tuple(None if value is None else SentenceEndState(value) for value in meanings)
            idea = torch.stack([root[b].new_zeros(3, root.shape[-1])
                                if value is None else value.roles
                                for b, value in enumerate(meanings)])
            context, _ = self._what_grammar_context(questions, device=root.device, dtype=root.dtype)
            held = AnswerDerivation(answer_symbol=None, sentence_states=fields,
                conceptual_answer=idea, questions=questions, conditioning_context=context,
                answer_meanings=tuple(() if value is None else (value,) for value in meanings))
            understanding = Understanding(conceptual_state=idea, sentence_states=fields,
                sentence_records=(observation['record'],))
            construction = self.reverseOutput(understanding, held,
                score=lambda construction:self._output_target_cost(construction,values))
            pred = construction.actual
            # Supplied answers retain Data.what's authority, including empty
            # rows and text targets. Desired values only score the fixed output.
            if any(isinstance(value, str) for value in values):
                filler = next(value for value in values if isinstance(value, str))
                mask = active & torch.tensor([isinstance(value, str) for value in values], device=root.device)
                target_surface = self._embed_answer_texts(
                    [value if isinstance(value, str) else filler for value in values]).detach()
                surface = self._answer_surface_from_percepts(construction.percepts)
                error = torch.stack([self._reverse_event_loss(surface[b:b+1], target_surface[b:b+1])
                                     for b in range(root.shape[0])])
                for b in range(root.shape[0]):
                    if bool(mask[b]):
                        local = Error()
                        self._reverse_event_loss(surface[b:b+1], target_surface[b:b+1],
                            registry=local, name='answer', objective='output')
                        for name, rec in local._terms.items():
                            numerator, baseline, count, mean_count = local._statistics(rec)
                            registry.error(name, numerator/mean_count, baseline/mean_count,
                                row=b, entry_weight=count, weight=rec['weight'], objective='output')
                self._sentence_answer_raw_cost = torch.where(mask, error, torch.zeros_like(error))
                self._sentence_answer_predictions = surface.detach()
                self._sentence_answer_cost = registry.total(objective='output')
                if destination is not None:
                    destination.merge(registry)
                return self._sentence_answer_cost
            template = next(value for value in values if value is not None)
            target = self.outputSpace.prepOutput([template if value is None else value for value in values])
            active = active & torch.tensor([value is not None for value in values], device=root.device)
        else:
            answer = self._forward_head(None, sentence_state=(root, slots, depth),
                                        understanding=observation['record'])
            pred = self.normalizer.denormalize(answer.materialize(), which='output')
        pred = self._align_output_pred(pred, target)
        if pred is None:
            raise RuntimeError('sentence answer and supplied target do not align')
        error = (pred - target.to(pred)).square().reshape(root.shape[0], -1).mean(-1)
        self._sentence_answer_raw_cost = torch.where(active, error, torch.zeros_like(error))
        self._sentence_answer_predictions = pred.detach()
        self.loss.register(registry, 'answer', pred, target.to(pred), mask=active, category='prediction', objective='output')
        self._sentence_answer_cost = registry.total(objective='output')
        if destination is not None:
            destination.merge(registry)
        return self._sentence_answer_cost

    @staticmethod
    def _clause_end_state(state, sid, clauses, row_ids):
        """Publish the chosen clause field; a relation never occupies a point."""
        current, lang, feedback = state
        values = [value.clone() for value in current]
        updated = list(lang)
        for index in (9, 13, 14, 20):
            updated[index] = lang[index].clone()
        for b, clause in enumerate(clauses):
            if clause is None:
                continue
            depth = 1 if clause.relation is None else 3
            if values[0].shape[1] < depth:
                raise ValueError('STM cannot hold the ended clause field')
            field = (clause.point[None] if depth == 1 else clause.meaning.roles[[2, 0, 1]])
            values[0][b].zero_()
            values[0][b, :depth] = field.detach()
            values[1][b] = depth
            values[2][b].fill_(-1)
            values[2][b, :depth] = clause.order
            values[3][b].zero_()
            values[4][b].fill_(-1)
            values[5][b].zero_()
            values[5][b, :depth] = 1.
            slots = field.new_zeros(3, field.shape[-1])
            slots[:depth] = field.detach()
            updated[9][b, sid] = field[-1].detach()
            updated[13][b, sid] = slots.flatten()
            updated[14][b, sid] = depth
            updated[20][b].zero_()
            updated[20][b, :, 1] = -1
            from ClauseScope import ClauseScope
            updated[20][b, 0, 0] = ClauseScope.SENTENCE | (ClauseScope.RELATIVE if depth == 3 else 0)
            updated[20][b, 0, 1] = int(row_ids[b]) if depth == 3 else -1
        return tuple(values), tuple(updated), feedback

    @staticmethod
    def _discard_sentence_record(state, active):
        """After both trials train, discard their operations at the closing."""
        stm, lang, feedback = state
        lang = list(lang)
        for index in (4, 5, 6, 7, 8, 15, 16, 17, 18, 19, 21, 22, 23, 24, 25, 26, 27):
            value = lang[index]
            blank = torch.full_like(value, -1) if index in (4, 5, 15, 16, 17, 18, 23, 25) else torch.zeros_like(value)
            mask = active.reshape(active.shape[0], *((1,) * (value.ndim - 1)))
            lang[index] = torch.where(mask, blank, value)
        return stm, tuple(lang), feedback

    def _commit_sentence(self, state, sid, active, observations, predictions, wins):
        """Publish only the chosen rows before the next sentence's perception."""
        self._publish_sentence_scratch(state)
        rows = wins.detach().cpu().tolist()
        view = self._sentence_observation(state, sid, active, admit=True)
        # Optimizer updates have already happened. Admission may allocate
        # native addresses, but it must not re-read their updated dictionary
        # values or change the discrete identity choice that was scored.
        chosen = [observations[-1 if win else 0] for win in rows]
        admitted = view['entries']
        entries = []
        for b, source in enumerate(chosen):
            program, native = source['entries'][b], admitted[b]
            if program is None:
                entries.append(None)
                continue
            references = program.reference_ids
            if references is not None and native.reference_ids is not None:
                references = torch.where(references == program.concept_ids,
                                         native.reference_ids, references)
            entries.append(replace(program,
                reference_ids=references, reference_orders=native.reference_orders,
                reference_values=(program.leaves if program.reference_values is None
                                  and references is not None else program.reference_values)).detached())
        view['entries'] = tuple(entries)
        for key in ('payloads', 'depths', 'meanings', 'observed', 'observed_depths'):
            view[key] = [source[key][b] for b, source in enumerate(chosen)]
        if any(source['roles'] is not None for source in chosen):
            view['roles'] = [None if source['roles'] is None else source['roles'][b]
                             for b, source in enumerate(chosen)]
        from ClauseJournal import finish_clause
        def frozen_values(admitted, scored):
            if (len(admitted.children) != len(scored.children)
                    or len(admitted.companions) != len(scored.companions)):
                raise RuntimeError('admission changed the selected clause structure')
            return replace(admitted, point=scored.point,
                meaning=replace(admitted.meaning, roles=scored.meaning.roles,
                                role_mask=scored.meaning.role_mask),
                children=tuple(frozen_values(a, s) for a, s in zip(admitted.children, scored.children)),
                companions=tuple(frozen_values(a, s) for a, s in zip(admitted.companions, scored.companions)))
        view['clauses'] = [None if entry is None else frozen_values(
            finish_clause(self.languageSpace, entry, meaning=view['meanings'][b],
                                registry=_boundary_registry(self)), chosen[b]['clauses'][b])
            for b, entry in enumerate(entries)]
        disc = getattr(self.symbolSpace, 'expectation', None)
        # The preview owns each trial's estimate. Commit its comparison and
        # prior-query policy outcome without training prediction twice.
        if disc is not None:
            pending_a, pending_b = predictions[0], predictions[-1]
            disc._inter_last_meaning = [pending_b[0][b] if win else pending_a[0][b]
                                       for b, win in enumerate(rows)]
            disc._inter_last_pred_root = [pending_b[1][b] if win else pending_a[1][b]
                                         for b, win in enumerate(rows)]
            disc.observe_stm_end_state(view['observed_depths'], view['observed'],
                mask=view['mask'], documents=self._expectation_documents_for_slot(sid, len(rows)),
                layout=view['layout'], role_masks=view['roles'], train_prediction=False,
                sentence_kinds=[None if m is None else m.sentence_kind for m in view['meanings']])
            disc.detach_prediction_context()
        from Meaning import ClosingImage
        images = self.__dict__.setdefault('_closing_images', {})
        for b, meaning in enumerate(view['meanings']):
            if meaning is None or not bool(active[b]):
                continue
            comparison = None if disc is None else disc.last_expectation_comparison(b)
            estimate = None if comparison is None else comparison.estimate
            mask = meaning.roles.new_zeros(3)
            registry = _boundary_registry(self)
            if registry is not None and meaning.mode == 'interrogative':
                # An observed question need not yet name an executable thought.
                # Only a resolved grammatical attention object spares a role.
                try:
                    signature = registry.signature_for(meaning)
                except (TypeError,ValueError):
                    signature = None
                if signature is not None:
                    for role in signature.open_roles:
                        mask[registry._slot_for_operand(role)] = 1
            content_width = meaning.roles.shape[-1]
            form_width = getattr(self, '_image_form_width', None)
            form_width = content_width if form_width is None else min(content_width,int(form_width))
            images[b] = ClosingImage.form(meaning.roles,
                None if estimate is None else estimate.roles.to(meaning.roles),
                meaning.roles.new_zeros(3) if estimate is None else estimate.presence_logits.sigmoid(),
                gain=getattr(self,'expectation_gain',1.), object_mask=mask,
                form_width=form_width, content_width=content_width)
        self._last_closing_image_audit = dict(
            concept_widths={b:v.concept_width for b,v in images.items()},
            image_max={b:float(v.image.abs().max()) for b,v in images.items()})
        store = getattr(self.symbolSpace, 'ltm_store', None)
        row_ids = [-1] * len(rows)
        if store is not None and getattr(self.conceptualSpace, '_ltm_consolidation', False):
            retain = _is_external_expectation_observation(disc)
            for b, payload in enumerate(view['payloads']):
                if payload is None:
                    continue
                comparison = (disc.last_expectation_comparison(b) if retain else None)
                from Occurrence import source_at, sentence_key, native_content_key
                document, position = source_at(self, b, sid)
                # The scored reading owns the resolved word identities. The
                # legacy WORD lane may be empty on the mixing grammar path;
                # hashing it would give every sentence the empty content key.
                record = chosen[b].get('record')
                word_rows = getattr(record, 'word_rows', None)
                word_valid = getattr(record, 'word_valid', None)
                identified_codes = []
                if torch.is_tensor(word_rows) and torch.is_tensor(word_valid):
                    owner = self._concept_owner()
                    # Unresolved or clipped slots are not identified words.
                    # Do not substitute target text or composed coordinates.
                    identified_codes = [int(code) for code in word_rows[b][word_valid[b]].tolist()
                                        if code >= 0 and isinstance(owner.word_surface_for_row(int(code)), bytes)]
                    words = [owner.word_surface_for_row(code) for code in identified_codes]
                    content = sentence_key(words)
                else:
                    content = native_content_key(view['clauses'][b].meaning)
                clause = view['clauses'][b]
                encoding = getattr(self, 'when_encoding', None)
                if encoding is not None:
                    clause = replace(clause, eternal=False,
                                     when=encoding.encode(position).to(clause.meaning.roles))
                    view['clauses'][b] = clause
                with store.at_address(document, position, content,
                                      timestamp=float(getattr(self, 'when_time', store._next_ts))):
                    row = _append_observed_meaning(store, clause,
                        trust=self.conceptualSpace._incoming_trust_multiplier(),
                        expectation=comparison, stream=b)
                if row >= 0:
                    row_ids[b] = int(store.row_ids[row])
                    store.witness_adjacency(row, identified_codes)
                if row >= 0 and retain:
                    disc.bind_observation_occurrence(b, store.row(row)['occurrence'])
        fields = []
        registry = _boundary_registry(self)
        for b, clause in enumerate(view['clauses']):
            if clause is None:
                fields.append(None)
                continue
            index = None if store is None or row_ids[b] in (-1, 0) else store.index_of_row(row_ids[b])
            if index is not None:
                meaning = store.meaning_of(index)
                refs = tuple(store.refs[index].tolist())
            else:
                meaning = (clause.meaning if clause.relation is not None else
                           replace(ConceptualMeaning.from_description(clause.point),
                                   mode=clause.meaning.mode, polarity=clause.meaning.polarity,
                                   sentence_kind='idea'))
                refs = tuple(ref if type(ref) is int and ref not in (-1, 0) else -1 for ref in clause.refs)
            query = (self.languageSpace.program_meaning(entries[b], registry)
                     if clause.meaning.mode == 'interrogative' and registry is not None else None)
            fields.append(SentenceEndState(meaning, refs, row_ids[b], clause.where, clause.when, query,
                clause.order if index is None else int(store.order[index]),
                clause.evidence if index is None else (float(store.c_plus[index]), float(store.c_minus[index])),
                self.conceptualSpace._incoming_trust_multiplier() if index is None else float(store.trust[index])))
        self._sentence_fields[sid] = tuple(fields)
        record_categories = getattr(self.languageSpace, 'record_category_observations', None)
        trace = getattr(self, '_reconstruction_stack', lambda: None)()
        owner = self._concept_owner()
        if (callable(record_categories) and trace is not None
                and int(getattr(owner, '_category_n_roles', 0) or 0)):
            inputs = getattr(self, 'inputSpace', None)
            word_mask = getattr(inputs, '_word_active_mask', None)
            sentence_ids = getattr(inputs, '_packed_sentence_ids', None)
            if torch.is_tensor(word_mask) and torch.is_tensor(sentence_ids):
                word_mask = word_mask & (sentence_ids == sid)
            word_rows = getattr(inputs, '_ar_grammar_object_rows', None)
            if not torch.is_tensor(word_rows):
                word_rows = self._word_symbol_rows()
            identities = None
            if torch.is_tensor(word_rows):
                def identity(row):
                    value = owner.concept_id_at_row(int(row)) if row >= 0 else None
                    return -1 if value is None else value
                identities = word_rows.new_tensor([
                    [identity(row) for row in values]
                    for values in word_rows.detach().cpu().tolist()])
            record_categories(trace, word_mask, concept_ids=identities)
        state = self._clause_end_state(state, sid, view['clauses'], row_ids)
        state = self._discard_sentence_record(state, active)
        self._publish_sentence_scratch(state)
        return state

    def _sentence_reference_types(self, like):
        """Stage existing typed dictionary points for this open reading only."""
        from ReferenceContext import ReferenceTypes
        language = self.languageSpace
        orders = sorted({order for rule in (*language._compose_binary_rules,
                                            *language._compose_unary_rules)
                         for _role, order in getattr(rule, 'reference_orders', ())})
        sources = self._word_symbol_concept_ids()
        words = getattr(self.inputSpace, '_ar_word_concept_rows', None)
        if not orders or not torch.is_tensor(sources) or not torch.is_tensor(words):
            return None
        batch, count = sources.shape
        owner = self._concept_owner()
        basis = owner.similarity_codebook.getW()
        identities = torch.full((batch, count, len(orders)), -1,
                                device=like.device, dtype=torch.long)
        values = like.new_zeros(batch, count, len(orders), like.shape[-1])
        for b in range(batch):
            for w in range(count):
                surface = owner.word_surface_for_row(int(words[b, w]))
                if surface is None:
                    continue
                for index, order in enumerate(orders):
                    identity = owner.resolve_word_concept(
                        surface, order=order, previous=int(sources[b, w]))
                    row = None if identity is None else owner._csw_row_of(identity)
                    if row is not None:
                        identities[b, w, index] = identity
                        values[b, w, index] = owner.similarity_codebook.lookup_rows(
                            torch.tensor(row, device=basis.device)).to(like)
        return ReferenceTypes(sources, sources.new_tensor(orders), identities, values)

    def _sentence_reference_bank(self, active, like):
        """Read only the predictor's bounded situation, with a fresh trial graph."""
        from ReferenceContext import ReferenceBank
        disc = getattr(self.symbolSpace, 'expectation', None)
        B, D = active.shape[0], like.shape[-1]
        C = max(1, int(getattr(disc, '_inter_chain_window', 1)))
        ids = torch.full((B, C), -1, device=like.device, dtype=torch.long)
        values = like.new_zeros(B, C, D)
        valid = torch.zeros(B, C, device=like.device, dtype=torch.bool)
        relations = torch.zeros_like(valid)
        predicted = torch.zeros(B, device=like.device, dtype=torch.bool)
        queries = []
        for b in range(B):
            query = like.new_zeros(D)
            pending = (None if disc is None or b >= len(disc._inter_last_meaning)
                       else disc._inter_last_meaning[b])
            prediction = getattr(pending, 'prediction', None)
            if prediction is not None and bool(active[b]):
                query = prediction.roles[0].detach().to(like)
                inputs = getattr(pending, 'inputs', None)
                if self._sentence_training and torch.is_grad_enabled() and inputs is not None:
                    estimates, _, _ = disc._inter_predictor(*(v.detach() for v in inputs))
                    query = estimates[0, 0].detach().to(like)
                predicted[b] = True
                for i, frame in enumerate(disc.situation_references(b)[-C:]):
                    if frame.order != 1:
                        continue
                    ids[b, i] = frame.row_id
                    valid[b, i] = True
                    relations[b, i] = frame.point is None
                    if frame.point is not None:
                        values[b, i] = frame.point.detach().to(like)
            queries.append(query)
        types = self._sentence_reference_types(like)
        cases = None
        if any(getattr(rule, 'case_head_role', 0) for rule in self.languageSpace._compose_binary_rules):
            from CaseSelection import stage_case_bank
            required = self._word_symbol_concept_ids()
            if types is not None:
                required = torch.cat((required, types.identities.flatten(1)), 1)
            cases = stage_case_bank(self._concept_owner(), required, limit=self.reconstruction_basis_limit)
        return ReferenceBank(ids, values, valid, relations, torch.stack(queries), predicted, types, cases)

    def _run_sentence_word_bricks(self, words, active, sentence_ids, stm, sub, sym,
                                lang, empty_feedback, perceive, symbolize, compose_word):
        from SentenceCompose import sentence_pair, fork_perception
        # Raw forward enters here without runBatch's eager setup. Compiled
        # reconstruction must find its autograd anchors already allocated.
        _ensure_grad_anchors(words.device)
        B, W = active.shape
        slots = self.inputSpace._packed_sentence_slot_mask
        feedback = empty_feedback
        live_root = None
        for sid in range(slots.shape[1]):
            present = slots[:, sid].to(torch.bool)
            if not bool(present.any()):
                continue
            from Occurrence import stage_position
            stage_position(self, sid, B, device=words.device)
            disc = getattr(self.symbolSpace, 'expectation', None)
            if disc is not None:
                disc._prepare_expectation_documents(self._expectation_documents_for_slot(sid, B), present, B)
                for b in range(B):
                    if bool(present[b]):
                        disc.predict_next_end_state(b)
            questions = getattr(self, '_active_what_questions', None)
            if questions:
                context, detail = self._what_grammar_context(questions, device=words.device, dtype=words.dtype)
                for module in self.symbolSpace.modules():
                    if hasattr(module, '_what_context'):
                        module._what_context, module._what_ltm_context = context, detail
            # A sentence is perceived once, after its predecessor's commit.
            cache = []
            for w in range(W):
                gate = active[:, w] & (sentence_ids[:, w] == sid)
                if not bool(gate.any()):
                    continue
                index = torch.tensor(w, device=words.device)
                payload, sub = perceive(words[:, w:w + 1], gate[:, None], index, None, sub)
                payload, sym = symbolize(payload, empty_feedback, index, None, sym)
                cache.append((index, payload))
            self._open_sentence_slot = sid
            self._prime_sentence_symbols(sid)
            self.languageSpace._compose_primed_bank = self._sentence_primed_bank
            before = self._snapshot_sentence_state((stm, lang, feedback))
            observations, predictions, paths = [], [], []
            paired_costs, cost_parts, attention_trials = [], [], []
            pending_steps = []
            reader_registries = []
            comparison_registries, reader_observations = [], []
            greedy_attention = getattr(self, '_attention_greedy', None)
            attention_base = getattr(self, '_attention_words', None)
            attention_spent = words.new_tensor([m.spent for m in getattr(self,'_attention_meters',())],dtype=torch.long)
            if greedy_attention is not None:
                greedy_attention = self._attention_read(sentence=sid,spent_override=attention_spent)
            self._sentence_departure = None
            def compose(cached, exploit):
                self._sentence_trial = 'exploit' if exploit is None else 'explore'
                self._sentence_pullback = None
                if self._sentence_training and torch.is_grad_enabled():
                    cached, self._sentence_pullback = fork_perception(cached)
                from ModelAttention import handoff
                reading = greedy_attention
                if exploit is not None:
                    self._publish_sentence_scratch(exploit)
                    trace = self._reconstruction_stack()
                    actions = trace._choice_actions.detach().clone()
                    owners, _, _ = self._compose_round_owners(actions)
                    eligible = trace._choice_attempted & trace._choice_explorable & (owners == sid)
                    from SentenceCredit import departure
                    draw = departure(greedy_attention, eligible, active=present,
                        sentence_ids=sentence_ids, sentence=sid)
                    self._sentence_departure = draw
                    forced = (torch.arange(actions.shape[1],device=words.device)[None]
                              == draw['compose_round'][:,None])
                    self._compose_exploit_actions = actions
                    self._compose_forced_slots = forced
                    self._compose_prefix_slots = self._exploration_prefix_slots(actions, forced, owners)
                    # A narrowing departure changes its full continuation. Only
                    # rows departing in compose replay the old compose prefix.
                    self._compose_prefix_slots &= ~draw['narrowing'][:,None]
                    self._compose_sampling_scale = trace._choice_alternative_counts * (
                        draw['walk_count'] * draw['walk_rounds'])[:,None]
                    if greedy_attention is not None and bool(draw['narrowing'].any()):
                        reading = self._attention_read(exploit=greedy_attention,
                            departure=draw['attention_round'],sentence=sid,spent_override=attention_spent)
                        # Non-departing rows retain precisely the greedy walk.
                        from SentenceCompose import select_rows
                        selected = select_rows(greedy_attention, reading, draw['narrowing'])
                        reading = type(reading)(type(reading.table)(*selected[0]), *selected[1:])
                if reading is not None:
                    handoff(self, reading)
                attention_trials.append(reading)
                # Every trial begins with restored history. Give its first
                # word the same grad contract as subsequent word carries,
                # without connecting it to a previous optimizer version.
                restored = tuple(_carries_with_grad(bank) for bank in before)
                self._restore_sentence_state(restored)
                self.languageSpace._reference_bank = self._sentence_reference_bank(
                    present, before[0][0])
                current_stm, current_lang, current_feedback = restored
                latches = [empty_feedback, empty_feedback]
                for index, payload in cached:
                    # Grammar feedback changes with this derivation, while
                    # the cached pre-compose word representation stays fixed.
                    payload = self._attention_sentence_payload(payload,index)
                    payload = (*payload[:-2], *latches[0])
                    current_lang, current_stm, current_feedback = compose_word(
                        payload, index, None, current_lang, current_stm)
                    latches = [latches[1], current_feedback]
                path = (current_stm, current_lang, current_feedback)
                if self._sentence_training and torch.is_grad_enabled():
                    pending_steps.append((self._sentence_trial, self._sentence_pullback, path))
                return path
            def score(path, alternative):
                paths.append(path[1][18].detach().clone())
                if alternative:
                    owners, _, _ = self._compose_round_owners(path[1][18])
                    rounds = (owners == sid) & (self._compose_exploit_actions >= 0)
                    different = ((self._compose_exploit_actions != path[1][18]) & rounds).any(-1)
                    branchable = self._compose_forced_slots.any(-1)
                    if not bool((different | ~present | ~branchable).all()):
                        raise RuntimeError('exploration repeated an exploit sentence derivation')
                cost, reconstruction, observation, pending = self._sentence_path_cost(path, sid, present)
                if self._sentence_training and self.legacy_prediction_enabled:
                    numerator = path[1][1] - before[1][1]
                    counts = path[1][2] - before[1][2]
                    denominator = counts[:, 0].clamp_min(1)
                    self._sentence_cost_registry.error('expectation.intra', numerator / denominator,
                        counts[:, 1] / denominator, mask=counts[:, 0] > 0,
                        entry_weight=counts[:, 0], weight=self.conceptualSpace.intra_loss_weight, category='expectation')
                    cost = self._sentence_cost_registry.total()
                    intra = self._sentence_cost_registry.total(objective='expectation')
                    if self._sentence_gradient_objectives is not None:
                        self._sentence_gradient_objectives['expectation'] = intra
                if self._sentence_training and torch.is_grad_enabled():
                    pending_steps[-1] = (*pending_steps[-1], self._sentence_cost_registry,
                        observation['decomposition_loss'], observation['walk_loss'])
                    reader_registries.append(self._sentence_cost_registry)
                    comparison_registries.append(self._sentence_comparison_registry)
                reader_observations.append(self._sentence_reader_observation)
                from SentenceCredit import components
                parts = components(self._sentence_cost_registry,
                    self._sentence_expectation_comparison, path[1][9][:,sid].sum(-1)*0,
                    answer=self._sentence_answer_cost)
                cost_parts.append(parts)
                cost = parts.sum(-1)
                observations.append(observation)
                predictions.append(pending)
                paired_costs.append(cost.detach().clone())
                return parts[:, 0], (path, reconstruction)
            def train_trial(loss):
                # Both graphs now exist. Restore this trial's perception
                # pullback and scratch bindings before its own backward.
                trial, pullback, path, registry, decomposition_loss, walk_loss = pending_steps.pop(0)
                self._sentence_trial, self._sentence_pullback = trial, pullback
                self._sentence_cost_registry = registry
                from SentenceCredit import reader_weights, reader_costs, expectation_costs
                self._sentence_comparison_reader_weights = reader_weights(
                    torch.stack(cost_parts, 1), present, self._sentence_departure)
                self._sentence_reader_weights = reader_weights(
                    torch.stack(cost_parts, 1), present, None)
                self._sentence_reader_rows = present & (trial == 'explore')
                self._sentence_reader_costs = (reader_costs(reader_registries,
                    self._sentence_reader_weights) if trial == 'explore' else {})
                presented_step = any(v.requires_grad for v in self._sentence_reader_costs.values())
                if trial == 'explore':
                    self._sentence_reader_costs.update(expectation_costs(
                        reader_registries, self._sentence_reader_weights))
                comparison_costs = (reader_costs(comparison_registries,
                    self._sentence_comparison_reader_weights) if trial == 'explore' else {})
                for name, value in comparison_costs.items():
                    self._sentence_reader_costs[name] = self._sentence_reader_costs.get(name, 0) + value
                if greedy_attention is not None:
                    from ModelAttention import handoff
                    handoff(self, attention_trials[int(trial == 'explore')])
                self._restore_sentence_state(path)
                loss = registry.total()
                loss = (loss * registry.row_mask).sum() / registry.row_mask.sum().clamp_min(1)
                if decomposition_loss is not None and decomposition_loss.requires_grad:
                    registry.add('reconstruction.decomposition', decomposition_loss, category='reconstruction')
                    loss = loss + (decomposition_loss * registry.row_mask).sum() / registry.row_mask.sum().clamp_min(1)
                if walk_loss is not None and walk_loss.requires_grad:
                    registry.add('reconstruction.walk_policy', walk_loss, category='reconstruction')
                    loss = loss + (walk_loss * registry.row_mask).sum() / registry.row_mask.sum().clamp_min(1)
                if trial == 'explore':
                    loss = loss + self._compose_score_function_loss(path, torch.stack(paired_costs, -1))
                self._sentence_train_step(loss)
                if presented_step:
                    self._sentence_reader_updates += 1
                if any(value.requires_grad for value in comparison_costs.values()):
                    self._sentence_comparison_reader_updates += 1
            try:
                (chosen, reconstruction), costs, wins = sentence_pair(cache, compose, score,
                    train_trial, active=present,
                    training=self._sentence_training and torch.is_grad_enabled())
            finally:
                pending_steps.clear()
                reader_registries.clear()
                comparison_registries.clear()
                self._sentence_pullback = None
                self._sentence_reader_rows = None
                self._sentence_reader_costs = None
                self._compose_exploit_actions = self._compose_forced_slots = None
                self._compose_prefix_slots = None
            if len(paths)==2:
                from WalkTrials import observe_comparison
                owners,_,_=self._compose_round_owners(paths[0])
                here=owners==sid
                different=(paths[0]!=paths[1])&here
                departure=torch.where(different,torch.arange(paths[0].shape[1],device=words.device)[None],paths[0].shape[1]).amin(-1)
                departure=torch.where(different.any(-1),departure,-1)
                observe_comparison(self,'compose',dict(costs=costs,wins=wins,
                    departure=departure,
                    greedy=torch.where(here,paths[0],-1),explore=torch.where(here,paths[1],-1)),sentence=sid,active=present)
            if greedy_attention is not None:
                from SentenceCompose import select_rows
                selected = select_rows(attention_trials[0], attention_trials[-1], wins)
                kept = type(greedy_attention)(type(greedy_attention.table)(*selected[0]), *selected[1:])
                from ModelAttention import handoff
                here=sentence_ids==sid
                kept=kept._replace(**{name:torch.where(
                    here[...,None] if getattr(kept,name).ndim==3 else here,
                    getattr(kept,name),getattr(attention_base,name))
                    for name in ('values','accepted','descended','poles','pole_changes')})
                handoff(self, kept)
                for b,meter in enumerate(self._attention_meters):
                    if bool(present[b]):
                        meter.require('bracket',int(kept.table.spent[b])-meter.spent)
                self._attention_spent=kept.table.spent.detach().clone()
            from SentenceCredit import comparison
            parts = torch.stack((cost_parts[0],cost_parts[-1]),1)
            audit = comparison(parts,present)
            audit['sentence'] = sid
            audit['departure'] = self._sentence_departure
            audit['actions'] = tuple(path.detach() for path in paths)
            audit['narrowing_actions'] = tuple(None if r is None else r.actions.detach() for r in attention_trials)
            audit['readers'] = tuple(reader_observations)
            self._last_sentence_credit = audit
            self.__dict__.setdefault('_sentence_credit_audits', []).append(audit)
            from SentenceUnderstanding import SentenceUnderstanding
            self._last_sentence_understanding = SentenceUnderstanding.select(
                observations[0]['record'], observations[-1]['record'], wins)
            self._sentence_understandings[sid] = self._last_sentence_understanding
            self._sentence_trial = None
            self._sentence_trial_costs.append(costs)
            self._sentence_winners.append(wins)
            if not self._sentence_training and torch.is_grad_enabled():
                # Raw forward has not backpropagated. Expose its current
                # numerical root to callers, while the committed history and
                # the next sentence's carries remain detached below.
                buffer, depth = chosen[0][:2]
                root = buffer[torch.arange(B, device=words.device),
                              (depth - 1).clamp(0, buffer.shape[1] - 1)]
                live_root = (root if live_root is None else
                             torch.where(present[:, None], root, live_root))
            # Each compose graph has already trained and been freed. The
            # durable path is discrete history; word activations still expose
            # the original perception to the separate batch-end answer loss.
            chosen = (tuple(v.detach() for v in chosen[0]),
                      tuple(v.detach() for v in chosen[1]),
                      tuple(v.detach() for v in chosen[2]))
            activations = chosen[1][0]
            for index, payload in cache:
                payload = self._attention_sentence_payload(payload,index)
                value = torch.where(payload[7], payload[3].reshape(B, 1), 0.)
                activations = self._tensor_write_word_column(activations, index, value)
            chosen = (chosen[0], (activations, *chosen[1][1:]), chosen[2])
            chosen = self._commit_sentence(chosen, sid, present, observations, predictions, wins)
            observations.clear()
            predictions.clear()
            self._open_sentence_slot = None
            self._sentence_reconstructions.append(tuple(v.detach() for v in reconstruction))
            stm, lang, feedback = chosen
            # The next closing starts with the committed discrete history and
            # detached context. No gradient crosses optimizer versions via STM.
            stm = tuple(v.detach() for v in stm)
            lang = tuple(v.detach() for v in lang)
            reset = present & ((sentence_ids.amax(-1) > sid) | (lang[14][:, sid] <= 0))
            stm = FunctionalPeerSTM.soft_reset_rows(stm, reset)
            lang = (*lang[:10], ShortTermMemory.functional_wholes_reset(lang[10], reset),
                    *lang[11:20], self.languageSpace.clause_scope.reset(lang[20], reset), *lang[21:])
        self._publish_sentence_scratch((stm, lang, feedback))
        depth = stm[1]
        self._stm_single_S = (live_root if live_root is not None else
            stm[0][torch.arange(B, device=words.device),
                   (depth - 1).clamp(0, stm[0].shape[1] - 1)])
        final_ids = sentence_ids.amax(-1).clamp_min(0)
        self._stm_post_depth = lang[14].gather(1, final_ids[:, None]).reshape(B)
        self._tensor_final_end_slots = lang[13].gather(1,
            final_ids[:, None, None].expand(B, 1, lang[13].shape[-1])).reshape(B, 3, -1)
        self._tensor_final_end_depth = self._stm_post_depth
        self._packed_prediction_drained = True
        if self._sentence_reconstruction and self._sentence_reconstructions:
            values = self._sentence_reconstructions
            self._recon_ideas = torch.stack([v[0] for v in values]).sum(0)
            self._recon_sentence_costs = torch.stack([v[4] for v in values]).sum(0)
            available = self.inputSpace._reconstruction_sentence_available[:, :slots.shape[1]]
            count = (slots & available).sum(-1).clamp_min(1)
            self._recon_idea_cost = torch.stack([v[1] for v in values]).sum(0) / count
            self._recon_cost = self._recon_sentence_costs.sum(-1) / count
            self._recon_truncated = torch.stack([v[3] for v in values]).any(0)
            self._recon_completed = True
        return stm, sub, sym, lang, feedback, words.new_tensor(W, dtype=torch.long)

    def _run_tensor_peer_word_pipeline(self, width):
        """Run the aligned word transaction in one tensor ``while_loop``.

        The loop exposes the three ConceptualSpace-owned transactions as
        separate compiler-visible stages: CSSub performs ``IS->{PS,WS}`` and
        reduces word ``w``; CSSym performs the fixed ``CS->SS->CS`` recurrence
        for ``w-1``; CSLang deposits/resolves the reference and applies
        LanguageSpace's explicit tree plan for ``w-2``.  Grammar feedback has
        its own register and first reaches CSSym two symbolic indices after
        the Language decision that produced it.
        """
        width = int(width)
        isp = self.inputSpace
        ps = self.perceptualSpace
        ws = self.wholeSpace
        cs = self.conceptualSpace
        ss = self.symbolSpace
        stm = cs.CSLang
        words = isp._ar_embedded_N
        active = isp._word_active_mask.to(dtype=torch.bool)
        B = int(words.shape[0])
        grammar_leaf_mask = getattr(isp, '_ar_grammar_leaf_mask', None)
        capacity = int(stm.capacity)
        concept_dim = int(stm.concept_dim)
        symbolic_passes = (0,) if self.concept_order_limit > 0 else ()
        canonical = self._tensor_peer_while_ready(width)

        part_ids = getattr(isp, '_ar_word_part_ids', None)
        part_mask = getattr(isp, '_ar_word_part_mask', None)
        part_offsets = getattr(isp, '_ar_word_part_offsets', None)
        concept_rows = getattr(isp, '_ar_word_concept_rows', None)
        concept_orders = getattr(isp, '_ar_word_concept_orders', None)
        object_rows = getattr(isp, '_ar_word_object_rows', None)
        object_orders = getattr(isp, '_ar_word_object_orders', None)
        object_atoms = getattr(isp, '_ar_word_object_atoms', None)
        grammar_rows = getattr(isp, '_ar_grammar_object_rows', None)
        grammar_orders = getattr(isp, '_ar_grammar_object_orders', None)
        grammar_atoms = getattr(isp, '_ar_grammar_object_atoms', None)
        lookup_rows = getattr(isp, '_ar_concept_lookup_rows', None)
        lookup_atoms = getattr(isp, '_ar_concept_lookup_atoms', None)
        word_property_weights = getattr(ws, '_staged_word_primitive_counts', None)
        reference_codes = getattr(isp, '_ar_percept_reference_codes', None)
        reference_roles = getattr(isp, '_ar_percept_reference_roles', None)
        part_reference_vectors = getattr(isp, '_ar_part_reference_vectors', None)
        whole_reference_vectors = getattr(isp, '_ar_whole_reference_vectors', None)
        readout_coefficients = getattr(isp, '_ar_readout_coefficients', None)
        whole_reference_presence = getattr(isp, '_ar_whole_reference_presence', None)
        # Ordinary batches can differ from provisioning and from each other.
        # Rebuild their boundaries at the host entry; a compiled forward
        # consumes the layout already prepared by the lexical stem.
        if not torch.compiler.is_compiling():
            isp._finalize_sentence_word_layout(active)
        sentence_end_mask = isp._packed_sentence_end_mask.to(
            dtype=torch.bool)
        intermediate_end_mask = (
            isp._packed_sentence_intermediate_end_mask.to(dtype=torch.bool))
        sentence_transactions = bool(getattr(self, '_sentence_ends', False))
        sentence_ids = isp._packed_sentence_ids.to(dtype=torch.long)
        commit_mask = getattr(isp, "_word_last_slot_mask", None)
        if not torch.is_tensor(commit_mask):
            commit_mask = active
        else:
            commit_mask = commit_mask.to(dtype=torch.bool)

        if not canonical:
            empty_rows = torch.full((B, width), -1, device=words.device, dtype=torch.long)
            concept_rows = concept_rows if torch.is_tensor(concept_rows) else empty_rows
            concept_orders = concept_orders if torch.is_tensor(concept_orders) else empty_rows.clone()
            object_rows = object_rows if torch.is_tensor(object_rows) else empty_rows.clone()
            object_orders = object_orders if torch.is_tensor(object_orders) else empty_rows.clone()
            # Publish the current batch's complete reference slab even when
            # this path has no native rows. Scratch publication must not keep
            # the previous (often one-row provisioning) batch's metadata.
            isp._ar_word_concept_rows = concept_rows
            isp._ar_word_concept_orders = concept_orders
            isp._ar_word_object_rows = object_rows
            isp._ar_word_object_orders = object_orders

        percept_dim = int(ps.subspace.muxedSize)
        whole_dim = int(ws.subspace.muxedSize)
        whole_locations = int(ws.inputShape[0])
        n_locations = int(cs.outputShape[0])
        reducer = self._stm_reducer()
        predictor = cs.intraSentenceLayer
        interpretation = self._concept_owner().interpret
        language = self.languageSpace
        n_rules = int(language._n_rules)
        trace = self._reconstruction_stack()
        choices = trace.choices() if trace is not None else (None,) * 3
        forward_slots = (
            trace.forward_loss_slots()
            if trace is not None else (None, None))
        closing_trace_width = max(1, 2 * capacity)
        required_trace_width = 3 * width + closing_trace_width * width
        trace_ready = (
            all(torch.is_tensor(value) for value in choices)
            and all(torch.is_tensor(value) for value in forward_slots)
            and int(choices[0].shape[0]) == B
            and int(choices[0].shape[1]) >= required_trace_width)
        if not trace_ready:
            trace_width = required_trace_width
            choices = (
                torch.full(
                    (B, trace_width), -1, dtype=torch.long,
                    device=words.device),
                torch.zeros(
                    B, trace_width, dtype=torch.int8, device=words.device),
                torch.zeros(
                    B, trace_width, dtype=torch.bool, device=words.device),
            )
            forward_slots = (
                torch.zeros(
                    B, trace_width, dtype=words.dtype, device=words.device),
                torch.zeros(
                    B, trace_width, dtype=torch.bool, device=words.device),
            )
        record_columns = None
        record_width = 1  # no numerical closing reader outside sentence transactions
        if sentence_transactions:
            record_columns, record_width = self._sentence_journal_layout(
                active, sentence_ids, closing_trace_width, int(choices[0].shape[1]))
        self._sentence_journal_columns = record_columns
        if trace is not None:
            trace._choice_journal_columns = record_columns
        unary_map = (
            trace.rule_map(1) if trace is not None
            else language._cs_unary_rule_ids)
        binary_map = (
            trace.rule_map(2) if trace is not None
            else language._cs_binary_rule_ids)
        if not torch.is_tensor(unary_map):
            unary_map = language._cs_unary_rule_ids
        if not torch.is_tensor(binary_map):
            binary_map = language._cs_binary_rule_ids

        stm_state = (
            stm._buffer, stm._depth, stm._orders, stm._grammar_orders,
            stm._concept_rows, stm._concept_activations)
        # Provenance and chunk bookkeeping (fold-ladder plan, Phase 2b) ride
        # the CSLang bank as fixed-shape tensors: the STM whole slab, the
        # phrase proposal slab and its count.  Staged parent/clause maps are
        # constants of this sentence ([B, W] or absent -> -1).
        # The whole/unit/clause indices are per staged sentence, so the
        # slab starts empty at every loop entry (carried roots from an
        # earlier forward are folds: no whole, no unit).  Built fresh, not
        # read from the STM attribute: a first-seen attribute tensor as a
        # loop input suppressed the STM's buffer/depth replay on the first
        # compiled call (torch 2.14 nightly).
        wholes_state = torch.full(
            (B, capacity, 3), -1, dtype=torch.long, device=words.device)
        chunk_owner = self._concept_owner()
        prop_slab, prop_count = chunk_owner.ensure_chunk_proposal_state(
            B, words.device)
        chunk_table = getattr(chunk_owner, "_chunk_row_table", None)
        if not torch.is_tensor(chunk_table):
            chunk_table = chunk_owner.chunk_row_table(words.device)
        chunk_table = chunk_table.to(device=words.device)
        _ws0 = (self.wholeSpaces[0]
                if getattr(self, "wholeSpaces", None) else ws)
        unit_parent = getattr(_ws0, "_staged_unit_parent", None)
        unit_clause = getattr(_ws0, "_staged_unit_clause", None)
        def _fixed_width(source):
            """``[B, width]`` long: the staged map padded with ``-1`` to the
            word capacity.  The staged maps are ``[B, K]`` with ``K`` the
            batch's unit count, and a varying ``K`` in a loop constant made
            dynamo recompile the word loop on every new count (measured:
            one extra 15 s compile per distinct K)."""
            out = torch.full(
                (B, width), -1, dtype=torch.long, device=words.device)
            if torch.is_tensor(source) and source.dim() == 2:
                k = min(int(source.shape[1]), width)
                out[:, :k] = source[:, :k].to(
                    device=words.device, dtype=torch.long)
            return out

        unit_parent = _fixed_width(unit_parent)
        unit_clause = _fixed_width(unit_clause)

        def _gather_unit_column(source, index):
            """``[B]`` column of a ``[B, K]`` map, ``-1`` past its width."""
            K = int(source.shape[1])
            safe = index.clamp(0, K - 1).reshape(1, 1).expand(B, 1)
            value = source.gather(1, safe).reshape(B)
            return torch.where(
                index.reshape(1).expand(B) < K, value,
                torch.full_like(value, -1))

        zero_concept = words.new_zeros(B, n_locations, concept_dim)
        # CSLang keeps the eight full, non-quantized concepts in its owned
        # STM.  Its word-aligned output crosses the symbolic boundary as the
        # quantized zero-dimensional activation/reference only.  Carrying a
        # [B,W,D_c] concept history here is both semantically wrong and, under
        # while_loop autograd, quadratic in W because every loop step tapes
        # the entire changing slab.
        zero_symbol_activations = words.new_zeros(B, width, 1)
        zero_percept_words = words.new_zeros(B, width, percept_dim)
        zero_prediction = words.new_zeros(B, concept_dim)
        root_slots = int(
            isp._packed_sentence_slot_end_positions.shape[1])
        zero_sentence_roots = words.new_zeros(
            B, root_slots, concept_dim)
        zero_scalar = words.new_zeros(B)
        zero_whole = words.new_zeros(
            B, whole_locations, whole_dim)
        cs_sub_state = (
            zero_concept,                 # published CSSub lane
            zero_percept_words,
            zero_whole,                   # terminal WS fold
            words.new_zeros(B, 1, 1, percept_dim),
            words.new_zeros(B, 1, whole_locations, whole_dim),
            torch.full((B, 8), -1, dtype=torch.long, device=words.device),
            torch.full((B, 8), -1, dtype=torch.long, device=words.device),
            words.new_zeros(B, n_locations, 8),
            torch.zeros(B, n_locations, 8, dtype=torch.bool, device=words.device),
        )
        cs_sym_state = (
            zero_concept.clone(),         # published CSSym lane
        )
        cs_lang_state = (
            zero_symbol_activations,
            zero_scalar,
            words.new_zeros(B, 2),  # active entries and detached target energy
            zero_prediction,
            *choices,
            *forward_slots,
            zero_sentence_roots,
            wholes_state,
            prop_slab,
            prop_count,
            # the sentence's end state at its intermediate end: the top
            # three STM slots (a relative sentence keeps depth 3) and the
            # depth, for the reconstruction traversal
            words.new_zeros(B, root_slots, 3 * concept_dim),
            torch.zeros(B, root_slots, dtype=torch.long, device=words.device),
            # operand rows per recorded fold (left / right), contract 1
            torch.full((B, int(choices[0].shape[1])), -1, dtype=torch.long, device=words.device),
            torch.full((B, int(choices[0].shape[1])), -1, dtype=torch.long, device=words.device),
            torch.full_like(choices[0], -1),
            torch.full_like(choices[0], -1),
            torch.zeros_like(choices[2]),
            language.clause_scope.empty(stm._buffer),
            torch.zeros_like(choices[0]),
            words.new_zeros(B, record_width, 3 * concept_dim),
            torch.full((B, record_width, 2), -1, dtype=torch.long, device=words.device),
            torch.zeros(B, record_width, 2, dtype=torch.bool, device=words.device),
            torch.full((B, capacity), -1, dtype=torch.long, device=words.device),
            torch.zeros_like(choices[0]),
            words.new_zeros(B, int(choices[0].shape[1])),  # selected operation log probability
        )
        empty_cs_sub = (
            zero_concept.clone(),
            torch.full(
                (B, n_locations), -1, dtype=torch.long,
                device=words.device),
            torch.full(
                (B,), -1, dtype=torch.long, device=words.device),
            words.new_zeros(B),
            words.new_zeros(B, n_locations),
            torch.full(
                (B,), -1, dtype=torch.long, device=words.device),
            torch.full(
                (B,), -1, dtype=torch.long, device=words.device),
            words.new_zeros(B, concept_dim),
            torch.zeros(B, 1, dtype=torch.bool, device=words.device),
            torch.zeros(B, 1, dtype=torch.bool, device=words.device),
        )
        empty_cs_sym = (
            zero_concept.clone(),
            torch.full(
                (B, n_locations), -1, dtype=torch.long,
                device=words.device),
            torch.full(
                (B,), -1, dtype=torch.long, device=words.device),
            words.new_zeros(B),
            torch.full(
                (B,), -1, dtype=torch.long, device=words.device),
            torch.full(
                (B,), -1, dtype=torch.long, device=words.device),
            words.new_zeros(B, concept_dim),
            torch.zeros(B, 1, dtype=torch.bool, device=words.device),
            torch.zeros(B, 1, dtype=torch.bool, device=words.device),
            words.new_zeros(B, n_rules),
            torch.zeros(B, 1, dtype=torch.bool, device=words.device),
        )
        empty_feedback = (
            words.new_zeros(B, n_rules),
            torch.zeros(B, 1, dtype=torch.bool, device=words.device),
        )
        capture_intra = bool(
            self.training and torch.is_grad_enabled()
            and float(getattr(cs, "intra_loss_weight", 0.0)) > 0.0)

        def _gather_word(source, index):
            safe = index.clamp(0, width - 1).reshape(1)
            return torch.index_select(source, 1, safe)

        def stage_cs_sub(_word, row_gate, index, _live, current_cs_sub):
            """IS(w) -> {PS(w),WS(w)} -> CSSub(w), with peer-only reads."""
            del _word, _live
            local_ids = _gather_word(part_ids, index)
            local_mask = _gather_word(part_mask, index)
            local_offsets = _gather_word(part_offsets, index)
            local_properties = _gather_word(
                word_property_weights, index).reshape(
                    B, whole_locations, int(word_property_weights.shape[-1]))
            row = _gather_word(concept_rows, index).reshape(B)
            order = _gather_word(concept_orders, index).reshape(B)
            object_row = _gather_word(object_rows, index).reshape(B)
            object_order = _gather_word(object_orders, index).reshape(B)
            object_atom = _gather_word(object_atoms, index).reshape(
                B, concept_dim)
            commit = _gather_word(commit_mask, index).reshape(B, 1)
            commit = torch.logical_and(commit, row_gate)
            part_sources = (ps.synthesize_word_parts(local_ids, local_mask, local_offsets),)
            whole_sources = (ws.compute_word_property_event(local_properties),)
            local_codes = _gather_word(reference_codes, index).reshape(B, 8)
            local_roles = _gather_word(reference_roles, index).reshape(B, 8)
            local_coefficients = _gather_word(readout_coefficients, index).reshape(B, 9)
            evidence, evidence_mask = cs.percept_code_evidence(
                part_sources[-1], whole_sources[-1],
                _gather_word(part_reference_vectors, index).squeeze(1),
                _gather_word(whole_reference_vectors, index).squeeze(1),
                local_roles, row_gate.reshape(B),
                part_n_what=int(ps.nWhat), whole_n_what=int(ws.nWhat),
                whole_presence=_gather_word(whole_reference_presence, index).squeeze(1))
            percept = part_sources[-1][:, 0, :]
            percept = torch.where(
                row_gate, percept, torch.zeros_like(percept))
            next_percept_slab = self._tensor_write_word_column(
                current_cs_sub[1], index, percept)
            next_whole = torch.where(
                row_gate.unsqueeze(-1),
                whole_sources[-1], current_cs_sub[2])

            (event, orders, row, activation,
             _unused_symbol, _unused_validity,
             location_activations) = cs.reduce_aligned_percept_peers(
                part_sources, whole_sources, row, order,
                row_gate.reshape(B),
                staged_rows=lookup_rows, staged_atoms=lookup_atoms,
                part_n_what=int(ps.nWhat), whole_n_what=int(ws.nWhat),
                percept_evidence=evidence, evidence_mask=evidence_mask,
                readout_coefficients=local_coefficients)
            next_sub = torch.where(
                row_gate.unsqueeze(-1), event, current_cs_sub[0])
            payload = (
                event, orders, row, activation, location_activations,
                object_row, object_order, object_atom, row_gate, commit)
            return payload, (
                next_sub, next_percept_slab, next_whole,
                torch.where(row_gate.reshape(B, 1, 1, 1),
                            torch.stack(part_sources, dim=1), current_cs_sub[3]),
                torch.where(row_gate.reshape(B, 1, 1, 1),
                            torch.stack(whole_sources, dim=1), current_cs_sub[4]),
                torch.where(row_gate, local_codes, current_cs_sub[5]),
                torch.where(row_gate, local_roles, current_cs_sub[6]),
                torch.where(row_gate.unsqueeze(-1), evidence, current_cs_sub[7]),
                torch.where(row_gate.unsqueeze(-1), evidence_mask, current_cs_sub[8]))

        def stage_cs_sym(cs_sub_payload, feedback, index, _live,
                         current_cs_sym):
            """Promote CSSub(w) through the fixed CS/SS recurrence."""
            del _live
            (event, orders, row, activation, location_activations,
             object_row, object_order, object_atom,
             row_gate, commit) = cs_sub_payload

            # A symbol is the zero-dimensional row/activation reference to
            # this concept.  Each pass is SS-owned interpretation followed by
            # CS-owned dictionary decode/order commit; the loop is fixed and
            # compiler-visible.
            symbolic_event = event
            symbolic_orders = orders
            for _symbolic_pass in symbolic_passes:
                del _symbolic_pass
                reference = ss.compute_symbolic_reference(
                    symbolic_event, row, location_activations,
                    symbolic_orders, row_gate.reshape(B),
                    n_what=int(cs.nWhat))
                symbolic_event, symbolic_orders = (
                    cs.promote_symbol_reference(
                        *reference, prior_event=symbolic_event,
                        staged_rows=lookup_rows, staged_atoms=lookup_atoms))
            next_sym = torch.where(
                row_gate.unsqueeze(-1),
                symbolic_event, current_cs_sym[0])
            # Language's grammar plan is visible at this CSSym boundary.  SS
            # currently consumes the conceptual reference itself; the plan is
            # carried beside that reference to CSLang's routed predictor
            # without placing Language-owned state inside ConceptualSpace.
            # CSLang feedback has a two-symbolic-index latency. At a packed
            # boundary those two earlier source words may belong to the prior
            # sentence; compare the explicit sentence identities so no
            # grammar choice crosses the row-local soft reset.
            current_sentence = _gather_word(
                sentence_ids, index).reshape(B)
            feedback_source_index = (index - 2).clamp(0, width - 1)
            feedback_sentence = _gather_word(
                sentence_ids, feedback_source_index).reshape(B)
            same_sentence = torch.logical_and(
                index >= 2,
                torch.logical_and(
                    current_sentence >= 0,
                    current_sentence == feedback_sentence))
            routed_feedback = torch.where(
                same_sentence.reshape(B, 1),
                feedback[0], torch.zeros_like(feedback[0]))
            routed_valid = torch.logical_and(
                feedback[1], same_sentence.reshape(B, 1))
            payload = (
                symbolic_event, symbolic_orders, row, activation,
                object_row, object_order, object_atom, row_gate, commit,
                routed_feedback, routed_valid)
            if not sentence_transactions:
                payload=self._attention_sentence_payload(payload,index)
            return payload, (next_sym,)

        scope = language.clause_scope

        def record_clause_end(events, slot, kind):
            column = slot.reshape(-1, 1).expand(B, 1)
            index = column.clamp(0, events.shape[1] - 1)
            value = torch.where((column >= 0) & (column < events.shape[1]),
                                kind[:, None], events.gather(1, index))
            return events.scatter(1, index, value)

        def stage_cs_lang(cs_sym_payload, index, _live,
                          current_cs_lang, current_stm):
            """Alternate LS choices with CS-owned applications/STM commit.

            LanguageSpace owns every grammar decision and returns immutable
            tensor choices. ConceptualSpace alone turns those choices into the
            next STM tensors. Each round jointly scores both arities against
            the CS-applied result of the preceding operation.
            """
            del _live
            (symbolic_event, symbolic_orders, row, activation,
             object_row, object_order, object_atom, row_gate, commit,
             routing, routing_valid) = cs_sym_payload
            word_idea = symbolic_event[:, 0, :]
            if torch.is_tensor(grammar_leaf_mask) and not sentence_transactions:
                commit = commit & _gather_word(grammar_leaf_mask, index).reshape_as(commit)

            if capture_intra:
                prediction, loss_sum, loss_weight = FunctionalPeerSTM.predict(
                    current_stm, word_idea, commit, predictor,
                    routing=routing, routing_valid=routing_valid)
                has_target = commit.reshape(B) & (current_stm[1] > 0)
                loss_baseline = torch.where(has_target[:, None], word_idea.detach().square(),
                                            torch.zeros_like(word_idea)).sum(-1)
            else:
                # Teacher reconstruction replaces the independent in-STM
                # predictor in the canonical configuration. A zero loss
                # weight must therefore skip the predictor itself, not merely
                # discard its already-paid-for loss after the sentence.
                prediction = torch.zeros_like(current_cs_lang[3])
                loss_sum = word_idea.new_zeros(B)
                loss_weight = word_idea.new_zeros(B)
            prediction = torch.where(row_gate, prediction, current_cs_lang[3])
            # The previous word's deadline reserved this slot. Overflow is a
            # violated invariant, never permission to drop an incoming word.
            pre_state = current_stm
            pre_applied = torch.zeros_like(
                current_stm[1], dtype=torch.bool)
            pre_op = torch.full_like(current_stm[1], -1)
            pre_valid = torch.zeros_like(pre_applied)
            pre_loss = word_idea.new_zeros(B)
            word_order = symbolic_orders[:, 0].to(dtype=torch.long)
            grammar_order = torch.zeros_like(word_order)
            torch._assert_async((~commit.reshape(B) | (pre_state[1] < capacity)).all(),
                'compose admission reached a full stack despite its reduction deadline')
            pushed_word = ShortTermMemory.functional_push_step_masked(
                *pre_state, word_idea, commit, word_order, grammar_order,
                row, activation)
            wholes = ShortTermMemory.functional_wholes_push(
                current_cs_lang[10], commit,
                _gather_unit_column(unit_parent, index),
                index.reshape(1).expand(B),
                _gather_unit_column(unit_clause, index))
            chunk_slab, chunk_count = current_cs_lang[11], current_cs_lang[12]

            # Treating the deposited word concept as a reference resolves its
            # paired object concept before Language observes the stack.  The
            # reference keeps the word's signed activation; concepts are full codes.
            object_idea = interpretation.forward(
                word_idea, object_atoms=object_atom,
                activation=activation.reshape(B))
            object_gate = torch.logical_and(
                commit.reshape(B), object_row >= 0)
            resolved = FunctionalPeerSTM.resolve_top_reference(
                pushed_word, object_idea, object_row, object_order,
                activation, object_gate)
            trace_state = current_cs_lang[4:9]
            left_rows, right_rows = current_cs_lang[15], current_cs_lang[16]
            position_slab, action_slab, attempted_slab = current_cs_lang[17:20]
            final_stm = resolved
            # Scope carries native object identities, not physical dictionary
            # row addresses. Mixing stages these only for grammar references.
            native_ids = getattr(isp, '_ar_word_object_ids', None)
            if not torch.is_tensor(native_ids):
                native_ids = getattr(isp, '_ar_grammar_object_ids', None)
            word_ids = (_gather_word(native_ids, index).reshape(B) if torch.is_tensor(native_ids)
                        else torch.full_like(current_stm[1], -1))
            clause_state = scope.push(current_cs_lang[20], commit.reshape(B), word_ids)
            closing_events = current_cs_lang[21]
            # Only this word's three choices and its bounded closing can
            # change. Record their numerical frames locally, then publish each
            # wide journal once. Re-scattering the entire [B, W*(3+2K), 3D]
            # journal for every choice retains gigabyte-sized intermediates
            # in a compiled production batch. Gather/scatter keeps the same
            # values and autograd edges, including untouched prior frames.
            closing_width = max(1, 2 * capacity)
            syntactic_budget = int(getattr(self, 'syntacticOrder', 0) or 0)
            closing_budget = min(closing_width, syntactic_budget) if syntactic_budget > 0 else closing_width
            group = ((index + 1) % width).expand(B)
            if sentence_transactions:
                final = _gather_word(sentence_end_mask & ~intermediate_end_mask, index).reshape(B)
                group = torch.where(final, 0, group)
            # Pipeline fill/drain ticks carry an out-of-range word index.
            # They have no active grammar row, but gather/scatter addresses
            # must still be legal before the row mask makes the write a no-op.
            journal_word = index.clamp(0, width - 1)
            journal_columns = torch.cat((
                (3 * journal_word + torch.arange(3, device=words.device))[None].expand(B, -1),
                3 * width + group[:, None] * closing_width
                + torch.arange(closing_budget, device=words.device)[None]), dim=1)
            if record_columns is not None:
                journal_columns = record_columns.gather(1, journal_columns)
            if sentence_transactions:
                value_columns = journal_columns[..., None].expand(-1, -1, 3 * concept_dim)
                ref_columns = journal_columns[..., None].expand(-1, -1, 2)
                operation_values = current_cs_lang[22].gather(1, value_columns)
                operation_refs = current_cs_lang[23].gather(1, ref_columns)
                reference_relations = current_cs_lang[24].gather(1, ref_columns)
            else:
                operation_values, operation_refs, reference_relations = current_cs_lang[22:25]
            unary_history = language.push_unary_history(current_cs_lang[25], commit)
            explorable_slab = current_cs_lang[26]
            log_probability_slab = current_cs_lang[27]
            round_active = commit.reshape(B)
            post_op = unary_op = torch.full_like(current_stm[1], -1)
            post_valid = unary_valid = torch.zeros_like(round_active)
            for round_index in range(3):
                if not torch.compiler.is_compiling() and not bool(round_active.any()):
                    break
                before = final_stm
                slot = 3 * index + round_index
                journal_slot = index.new_tensor(round_index)
                proposal = language.choose_operation(
                    before, round_active, slots=scope.slots(clause_state, before[1]),
                    sample=False,
                    allowance=capacity - 1, rounds_left=3 - round_index,
                    masked_action=self._compose_masked_action(slot, before[1]),
                    replay_action=self._compose_replayed_action(slot, before[1]),
                    op_prior=self._chunk_structural_prior(wholes, B, before[0]),
                    reference_scope=clause_state if sentence_transactions else None,
                    previous_unary=unary_history)
                choice = proposal[0] if sentence_transactions else proposal
                unary_history = language.update_unary_history(unary_history, choice)
                eligible = (choice.alternative_count if choice.alternative_count is not None else
                            (choice.valid if choice.alternatives is None else choice.alternatives).long())
                explorable_slab = self._tensor_record_selected_values(
                    explorable_slab.unsqueeze(-1), slot, eligible[:, None], choice.valid).squeeze(-1)
                log_probability = (choice.log_probability if choice.log_probability is not None
                    else choice.probability.clamp_min(torch.finfo(choice.probability.dtype).tiny).log())
                log_probability_slab = self._tensor_record_selected_values(
                    log_probability_slab.unsqueeze(-1), slot, log_probability[:, None], choice.valid).squeeze(-1)
                if sentence_transactions:
                    _, refs, relative, operands = proposal
                    clause_state = scope.resolve(clause_state, choice, refs, relative)
                    frame = torch.cat((operands[:, 0],
                        torch.where((choice.kind == 1)[:, None], operands[:, 1], 0.),
                        choice.candidate), -1)
                    operation_values = self._tensor_record_selected_values(
                        operation_values, journal_slot, frame, choice.applied)
                    operation_refs = self._tensor_record_selected_values(
                        operation_refs, journal_slot, refs, choice.applied)
                    reference_relations = self._tensor_record_selected_values(
                        reference_relations, journal_slot, relative, choice.applied)
                final_stm = cs.apply_language_choice(before, choice)
                clause_state, ended = scope.apply(clause_state, choice, slot)
                final_stm = scope.publish_name(final_stm, clause_state, ended)
                closing_events = record_clause_end(closing_events, slot, ended)
                binary = choice.applied & (choice.kind == 1)
                unary_chosen = choice.applied & (choice.kind == 2)
                post_op = torch.where(binary, choice.local_op, post_op)
                unary_op = torch.where(unary_chosen, choice.local_op, unary_op)
                post_valid = post_valid | binary
                unary_valid = unary_valid | unary_chosen
                (wholes, phrase_row, chunk_slab, chunk_count) = self._chunk_reduce_provenance(
                    wholes, choice.local_op, binary, chunk_slab, chunk_count, table=chunk_table)
                final_stm = cs.apply_phrase_rows(final_stm, phrase_row, binary)
                (trace_state, position_slab, action_slab, attempted_slab) = self._tensor_record_operation(
                    trace_state, position_slab, action_slab, attempted_slab, slot,
                    choice, binary_map, unary_map)
                left_rows, right_rows = self._tensor_record_operands(
                    left_rows, right_rows, slot, before, binary)
                round_active = round_active & choice.applied

            # The full resolved concept remains only in ``final_stm`` above.
            # SymbolSpace receives the concept's quantized 0-D reference
            # activation; identity is the staged object row.  Do not retain a
            # second word-wide copy of the continuous concept dictionary.
            symbol_activation = torch.where(
                row_gate,
                activation.reshape(B, 1),
                torch.zeros(B, 1, dtype=activation.dtype,
                            device=activation.device))
            next_symbol_activations = self._tensor_write_word_column(
                current_cs_lang[0], index, symbol_activation)
            next_symbol_activations = torch.where(
                row_gate.reshape(B, 1, 1), next_symbol_activations, current_cs_lang[0])
            next_loss_sum = (
                current_cs_lang[1] + loss_sum
                if capture_intra else current_cs_lang[1])
            next_loss_weight = (
                current_cs_lang[2] + torch.stack((loss_weight, loss_baseline), -1)
                if capture_intra else current_cs_lang[2])
            # Every non-final packed sentence receives the same bounded NULL
            # closing as the ordinary post-loop sentence boundary. The root is
            # stored at that sentence's end-word column, then only those rows
            # receive the CS-owned soft reset before the next word arrives.
            intermediate_end = _gather_word(
                sentence_end_mask if sentence_transactions else intermediate_end_mask, index).reshape(B) & row_gate.reshape(B)
            end_stm = final_stm
            closing_active = intermediate_end
            for closing_index in range(closing_budget):
                if not torch.compiler.is_compiling() and not bool(closing_active.any()):
                    break
                pre_closing = end_stm
                slot = 3 * width + group * closing_width + closing_index
                journal_slot = index.new_tensor(3 + closing_index)
                proposal = language.choose_operation(
                    pre_closing, closing_active, slots=scope.slots(clause_state, pre_closing[1]),
                    sample=False,
                    allowance=scope.slots(clause_state, pre_closing[1]), rounds_left=closing_budget - closing_index,
                    masked_action=self._compose_masked_action(slot, pre_closing[1]),
                    replay_action=self._compose_replayed_action(slot, pre_closing[1]),
                    op_prior=self._chunk_structural_prior(wholes, B, pre_closing[0]),
                    reference_scope=clause_state if sentence_transactions else None,
                    previous_unary=unary_history)
                choice = proposal[0] if sentence_transactions else proposal
                unary_history = language.update_unary_history(unary_history, choice)
                eligible = (choice.alternative_count if choice.alternative_count is not None else
                            (choice.valid if choice.alternatives is None else choice.alternatives).long())
                explorable_slab = self._tensor_record_selected_values(
                    explorable_slab.unsqueeze(-1), slot, eligible[:, None], choice.valid).squeeze(-1)
                log_probability = (choice.log_probability if choice.log_probability is not None
                    else choice.probability.clamp_min(torch.finfo(choice.probability.dtype).tiny).log())
                log_probability_slab = self._tensor_record_selected_values(
                    log_probability_slab.unsqueeze(-1), slot, log_probability[:, None], choice.valid).squeeze(-1)
                if sentence_transactions:
                    _, refs, relative, operands = proposal
                    clause_state = scope.resolve(clause_state, choice, refs, relative)
                    frame = torch.cat((operands[:, 0],
                        torch.where((choice.kind == 1)[:, None], operands[:, 1], 0.),
                        choice.candidate), -1)
                    operation_values = self._tensor_record_selected_values(
                        operation_values, journal_slot, frame, choice.applied)
                    operation_refs = self._tensor_record_selected_values(
                        operation_refs, journal_slot, refs, choice.applied)
                    reference_relations = self._tensor_record_selected_values(
                        reference_relations, journal_slot, relative, choice.applied)
                end_stm = cs.apply_language_choice(pre_closing, choice)
                clause_state, ended = scope.apply(clause_state, choice, slot)
                end_stm = scope.publish_name(end_stm, clause_state, ended)
                closing_events = record_clause_end(closing_events, slot, ended)
                binary = choice.applied & (choice.kind == 1)
                (wholes, phrase, chunk_slab, chunk_count) = self._chunk_reduce_provenance(
                    wholes, choice.local_op, binary, chunk_slab, chunk_count, table=chunk_table)
                end_stm = cs.apply_phrase_rows(end_stm, phrase, binary)
                (trace_state, position_slab, action_slab, attempted_slab) = self._tensor_record_operation(
                    trace_state, position_slab, action_slab, attempted_slab,
                    slot, choice, binary_map, unary_map)
                left_rows, right_rows = self._tensor_record_operands(
                    left_rows, right_rows, slot, pre_closing, binary)
                closing_active = closing_active & choice.applied
            if sentence_transactions:
                operation_values = current_cs_lang[22].scatter(1, value_columns, operation_values)
                operation_refs = current_cs_lang[23].scatter(1, ref_columns, operation_refs)
                reference_relations = current_cs_lang[24].scatter(1, ref_columns, reference_relations)
            end_depth = end_stm[1]
            root_index = (end_depth - 1).clamp(
                min=0, max=capacity - 1)
            root_rows = torch.arange(B, device=words.device)
            end_root = end_stm[0][root_rows, root_index].clone()
            root_slot = _gather_word(
                sentence_ids, index).reshape(B).clamp(
                    0, root_slots - 1)
            root_candidate = self._tensor_write_word_column(
                current_cs_lang[9], root_slot, end_root)
            next_sentence_roots = torch.where(
                intermediate_end.reshape(B, 1, 1),
                root_candidate, current_cs_lang[9])
            # The sentence's end state with its gradient, for the
            # per-sentence reconstruction traversal (compiled reverse-loops
            # plan): the top three slots (newest at 0) and the depth.
            _k3 = min(3, int(end_stm[0].shape[1]))
            end_slots = end_stm[0][:, :_k3, :]
            if _k3 < 3:
                end_slots = torch.cat(
                    (end_slots, end_stm[0].new_zeros(B, 3 - _k3, concept_dim)), dim=1)
            live_candidate = self._tensor_write_word_column(
                current_cs_lang[13], root_slot,
                end_slots.reshape(B, 3 * concept_dim))
            next_live_roots = torch.where(
                intermediate_end.reshape(B, 1, 1),
                live_candidate, current_cs_lang[13])
            depth_candidate = current_cs_lang[14].scatter(
                1, root_slot.reshape(B, 1),
                torch.where((end_depth <= scope.slots(clause_state, end_depth)) & (end_depth > 0),
                            end_depth.to(torch.long), -1).reshape(B, 1))
            next_live_depth = torch.where(
                intermediate_end.reshape(B, 1),
                depth_candidate, current_cs_lang[14])
            reset = torch.zeros_like(intermediate_end) if sentence_transactions else intermediate_end
            final_stm = FunctionalPeerSTM.soft_reset_rows(end_stm, reset)
            wholes = ShortTermMemory.functional_wholes_reset(wholes, reset)
            clause_state = scope.reset(clause_state, reset)

            next_cs_lang = (
                next_symbol_activations, next_loss_sum, next_loss_weight,
                prediction, *trace_state, next_sentence_roots,
                wholes, chunk_slab, chunk_count, next_live_roots,
                next_live_depth, left_rows, right_rows, position_slab, action_slab, attempted_slab,
                clause_state, closing_events, operation_values, operation_refs,
                reference_relations,
                torch.where(reset[:, None], -1, unary_history), explorable_slab, log_probability_slab)
            language_feedback = language.feedback_from_local_choices(
                (pre_op, post_op), (pre_valid, post_valid),
                unary_op, unary_valid, like=word_idea)
            # A sentence-final choice has no legal consumer in the following
            # sentence. The sentence-id check in CSSym is the second,
            # explicit guard; clearing validity here also drains the latch.
            sentence_end = _gather_word(
                sentence_end_mask, index).reshape(B, 1)
            language_feedback = (
                torch.where(
                    sentence_end, torch.zeros_like(language_feedback[0]),
                    language_feedback[0]),
                torch.logical_and(
                    language_feedback[1],
                    torch.logical_not(sentence_end)),
            )
            return (
                next_cs_lang,
                final_stm,
                language_feedback,
            )

        if sentence_transactions and canonical:
            from SentenceCompose import compile_word_brick
            stage_cs_sub = compile_word_brick(stage_cs_sub)
            stage_cs_sym = compile_word_brick(stage_cs_sym)
            stage_cs_lang = compile_word_brick(stage_cs_lang)
        if sentence_transactions and not canonical:
            def stage_cs_sub(word, gate, index, live, current_sub):
                p = int(index)
                result = self._per_word_body_step(word, p, gate,
                    self._per_word_contributions, active_host=True, _pipeline_stage_a=True)
                event, orders, row, activation = self._peer_stage_b(result, p, None, cache_only=True)
                if not torch.is_tensor(orders):
                    orders = torch.full(event.shape[:2], -1, device=event.device, dtype=torch.long)
                if not torch.is_tensor(row):
                    row = torch.full((B,), -1, device=event.device, dtype=torch.long)
                if not torch.is_tensor(activation):
                    activation = event.new_ones(B)
                obj = (grammar_rows[:, p] if torch.is_tensor(grammar_rows) else object_rows[:, p])
                obj_order = (grammar_orders[:, p] if torch.is_tensor(grammar_orders) else object_orders[:, p])
                atoms = grammar_atoms if torch.is_tensor(grammar_atoms) else object_atoms
                atom = (atoms[:, p] if torch.is_tensor(atoms)
                        else event.new_zeros(B, concept_dim))
                prior = self._per_word_contributions[p]
                prior = torch.zeros_like(event[:, 0]) if prior is None else prior
                self._per_word_contributions[p] = torch.where(gate, event[:, 0], prior)
                payload = (event, orders, row, activation, obj, obj_order,
                           atom, gate, gate, *empty_feedback)
                percept = ps.subspace.materialize()[:, 0]
                slab = self._tensor_write_word_column(current_sub[1], index, percept)
                return payload, (event, slab, *current_sub[2:])
            def stage_cs_sym(payload, feedback, index, live, current_sym):
                return payload, (payload[0],)
        if sentence_transactions:
            (final_stm, final_cs_sub, final_cs_sym, final_cs_lang,
             feedback, trip_count) = self._run_sentence_word_bricks(
                words, active, sentence_ids, stm_state, cs_sub_state,
                cs_sym_state, cs_lang_state, empty_feedback,
                stage_cs_sub, stage_cs_sym, stage_cs_lang)
        else:
            (final_stm, final_cs_sub, final_cs_sym, final_cs_lang,
             feedback, trip_count) = (
                TensorPeerWhilePipeline().run_cs_lanes_banked(
                words, active,
                stm_state=stm_state,
                cs_sub_state=cs_sub_state,
                cs_sym_state=cs_sym_state,
                cs_lang_state=cs_lang_state,
                empty_cs_sub=empty_cs_sub,
                empty_cs_sym=empty_cs_sym,
                empty_feedback=empty_feedback,
                stage_cs_sub=stage_cs_sub,
                stage_cs_sym=stage_cs_sym,
                stage_cs_lang=stage_cs_lang))
        final = (
            *final_stm,
            final_cs_sub[0],
            final_cs_sym[0],
            final_cs_lang[0],
            final_cs_sub[1],
            *final_cs_lang[1:],
        )

        # A higher-order op returns its carried values as a multi-output view
        # family.  Installing those views directly as mutable owner state
        # makes the next sentence's legitimate in-place reset fail with
        # "output ... is a view and is being modified inplace".  The peer
        # callbacks themselves remain purely functional; allocate independent
        # owner storage exactly once at the commit boundary.  ``clone`` keeps
        # the live autograd edge for STM/reconstruction losses while removing
        # every alias to the HOP's result tuple.
        final = tuple(value.clone() for value in final)
        final_whole = final_cs_sub[2].clone()
        feedback = tuple(value.clone() for value in feedback)

        # Commit the owner state.  Under the compiler the commit is an
        # in-place copy into the tensors the loop started from: with a
        # ``torch.while_loop`` in the graph, dynamo (torch 2.14 nightly)
        # drops a later attribute *assignment* when the attribute was also
        # assigned earlier in the same graph (the per-forward STM seed in
        # ``_per_word_prelude``), so every read after the loop -- the
        # sentence reduce, the reconstruction loss -- saw the empty seed.
        # An in-place copy is tracked correctly and keeps the gradient.
        current = (
            stm._buffer, stm._depth, stm._orders, stm._grammar_orders,
            stm._concept_rows, stm._concept_activations)
        if (torch.compiler.is_compiling()
                and all(torch.is_tensor(old) and tuple(old.shape) == tuple(new.shape)
                        and old.dtype == new.dtype
                        for old, new in zip(current, final[:6]))):
            for old, new in zip(current, final[:6]):
                old.copy_(new)
        else:
            (stm._buffer, stm._depth, stm._orders, stm._grammar_orders,
             stm._concept_rows, stm._concept_activations) = final[:6]
        if not torch.compiler.is_compiling():
            stm._max_depth_host = int(stm._depth.max().item())
        # PS/WS callbacks are side-effect free inside the HOP. Publish the
        # terminal live WS fold once at its owner boundary.
        ws.commit_event(final_whole)
        cs.CSsub.commit_event(cs, final[6])
        cs.commit_symbolic_peer_results(
            final[7], symbol_event=final[7].detach(),
            prior_symbolic_event=None, language_plan=None)
        cs.commit_event(final[7])
        if canonical:
            cs.commit_percept_field(
            final_cs_sub[3].clone(), final_cs_sub[4].clone(),
            reference_codes=final_cs_sub[5].clone(),
            reference_roles=final_cs_sub[6].clone(),
                evidence=final_cs_sub[7].clone(), evidence_mask=final_cs_sub[8].clone())
        object.__setattr__(cs, "_peer_prev_sub", cs.CSsub)
        object.__setattr__(cs, "_peer_prev_sym", cs.CSsym)
        cs._stm_predicted_idea = final[12]
        # This loop publishes the complete forward's prediction totals.
        # Replace their registry alongside the raw accumulators; retaining
        # its old entries both double-counts prior forwards and adds a guard
        # on the previous call's Python dictionary contents.
        cs._intra_errors = Error()
        if capture_intra and not sentence_transactions:
            cs._intra_loss_accum = [final[10]]
            cs._intra_loss_weight_accum = [final[11][:, 0]]
            counts = final[11][:, 0]
            denominator = counts.clamp_min(1)
            cs._intra_errors.error('intra', final[10] / denominator,
                final[11][:, 1] / denominator, mask=counts > 0, entry_weight=counts, category='expectation')
            cs._intra_loss_count = 1
        else:
            cs._intra_loss_accum = None
            cs._intra_loss_weight_accum = None
            cs._intra_loss_count = 0
        # The W-wide CSLang result is symbolic, not another conceptual event:
        # one row identity plus one signed activation per word.  SymbolSpace
        # owns that quantized slab; CS continues to own the full eight-slot
        # non-quantized STM installed above.
        symbol_rows = torch.where(
            object_rows >= 0, object_rows, concept_rows)
        symbol_orders = torch.where(
            object_rows >= 0, object_orders, concept_orders)
        if torch.is_tensor(grammar_rows):
            symbol_rows = torch.where(grammar_rows >= 0, grammar_rows, symbol_rows)
            symbol_orders = torch.where(grammar_rows >= 0, grammar_orders, symbol_orders)
        from ModelAttention import reference_evidence
        ss.commit_word_reference_slab(
            symbol_rows, final[8], active, orders=symbol_orders,
            evidence=reference_evidence(self, final[8], 'commit_word_reference_slab:whole_slab'))
        if canonical:
            self._per_word_contributions = []
        self._per_word_percept_contributions = final[9]
        if trace is not None:
            trace._choice_rule_ids = final[13]
            trace._choice_arities = final[14]
            trace._choice_mask = final[15]
            trace._forward_losses = final[16]
            trace._forward_loss_mask = final[17]
            trace._choice_left_rows = final_cs_lang[15].clone()
            trace._choice_right_rows = final_cs_lang[16].clone()
            trace._choice_positions = final_cs_lang[17].clone()
            trace._choice_actions = final_cs_lang[18].clone()
            trace._choice_attempted = final_cs_lang[19].clone()
            trace._choice_ends = final_cs_lang[21].clone()
            trace._choice_values = final_cs_lang[22].clone()
            trace._choice_journal_columns = record_columns
            trace._choice_refs = final_cs_lang[23].clone()
            trace._choice_ref_relations = final_cs_lang[24].clone()
            trace._choice_alternative_counts = final_cs_lang[26].clone()
            trace._choice_explorable = final_cs_lang[26] > 0
        stm._clause_state = final_cs_lang[20].clone()
        stm._last_unary = final_cs_lang[25].clone()
        stm._unary_history_depth = stm._depth.clone()
        sentence_roots = final_cs_lang[9].clone()
        final_wholes = final_cs_lang[10].clone()
        final_prop_slab = final_cs_lang[11].clone()
        final_prop_count = final_cs_lang[12].clone()
        if not torch.compiler.is_compiling():
            # Eager owners commit here; a compiled forward publishes the
            # explicit ``chunk_state`` result instead (an attribute-only
            # escape is dead state the compiler may drop, and a fresh
            # attribute store inside the graph suppressed the STM's own
            # buffer/depth replay on the first compiled call).
            stm._wholes = final_wholes
            chunk_owner._chunk_prop_slab = final_prop_slab
            chunk_owner._chunk_prop_count = final_prop_count
        object.__setattr__(self, "_tensor_peer_trip_count", trip_count)
        object.__setattr__(
            self, "_tensor_symbolic_iterations", len(symbolic_passes))
        object.__setattr__(self, "_tensor_peer_feedback", feedback)
        # The provenance/chunk slabs are explicit results too: an
        # attribute-only escape from the compiled graph is dead state the
        # compiler may eliminate (see ``_forward_with_compiled_sentence_state``).
        # The reconstruction traversal's word references are the leaves
        # the loop pushed: each word's symbol row's atom scaled by its
        # activation (staged constants and the loop's activation slab, not
        # a carried bank: the loop's autograd stacks every carry once per
        # step).
        chunk_state = (final_wholes, final_prop_slab, final_prop_count,
                       self._pushed_word_slab(B, width, concept_dim, words, final[8]),
                       final_cs_lang[13].clone(), final_cs_lang[14].clone())
        if not torch.compiler.is_compiling():
            # Eager forwards (no explicit sentence state requested) run the
            # reconstruction traversal from these at loss time.
            object.__setattr__(self, "_tensor_pushed_ideas", chunk_state[3])
            object.__setattr__(self, "_tensor_sentence_roots_live", chunk_state[4])
            object.__setattr__(self, "_tensor_sentence_roots_depth", chunk_state[5])
        return cs.subspace, trip_count, sentence_roots, chunk_state

    def _run_peer_word_pipeline(self, out_slot, width):
        """Execute the legacy A/B/C schedule for a padded sentence bucket.

        All FIFOs live in :class:`StaticPeerPipeline`; the closures merely bind
        this sentence's InputSpace views and fixed output slots. Canonical
        aligned execution takes :meth:`_run_tensor_peer_word_pipeline`; this
        path remains for older configurations that do not satisfy its staged
        tensor contract.
        """
        width = int(width)
        if width not in StaticPeerPipeline.WIDTHS:
            raise ValueError(
                "peer word pipeline requires one of "
                f"{StaticPeerPipeline.WIDTHS}, got W={width}")
        isp = self.inputSpace
        active = getattr(isp, "_word_active_mask", None)
        words, gates = [], []
        for p in range(width):
            word = isp.word_at(p)
            if word is None:
                raise RuntimeError(
                    f"InputSpace has no staged word {p} for static W={width}")
            words.append(word)
            gates.append(
                active[:, p:p + 1] if active is not None else torch.ones(
                    word.shape[0], 1, dtype=torch.bool, device=word.device))

        def stage_a(word, p):
            return self._per_word_body_step(
                word, p, gates[p], out_slot, active_host=True,
                _pipeline_stage_a=True)

        def stage_b(a_result, p, feedback):
            return self._peer_stage_b(a_result, p, feedback)

        def stage_c(b_result, p):
            return self._peer_stage_c(b_result, p)

        trace = StaticPeerPipeline(width).run(
            words, stage_a, stage_b, stage_c,
            capture_trace=not torch.compiler.is_compiling())
        if trace is not None:
            object.__setattr__(self, "_last_peer_pipeline_trace", trace)
        return self.conceptualSpace.subspace

    @staticmethod
    def _maybe_blend_event(carrier, prev_event, gate_b_1):
        # Masked-blend ``carrier._event`` against ``prev_event`` using
        # ``gate_b_1`` ([B, 1] bool). Skips when the carrier is missing,
        # the new event is missing, or shapes don't match (first
        # iteration after the empty seed). Same-shape blends are pure
        # tensor ops — no DtoH, no graph break.
        #
        # ``prev_event`` is detached before use so the blend never
        # chains into the previous iteration's autograd graph at a
        # padding column — without this, repeated forward/backward
        # cycles can hit "Trying to backward through the graph a
        # second time" when an inactive batch row's carrier reuses a
        # saved intermediate that has already been freed.
        if carrier is None or prev_event is None:
            return
        new_ev = getattr(carrier, '_event', None)
        if new_ev is None or new_ev.shape != prev_event.shape:
            return
        gate_3d = gate_b_1.unsqueeze(-1)  # [B, 1, 1] broadcasts over D
        carrier._event = torch.where(gate_3d, new_ev, prev_event.detach())

    def _forward_body_per_word(self, in_sub, *,
                               return_sentence_state=False):
        """Per-word IR-reconstruction body (2b-1 capstone).

        The FRONT of the forward when the InputSpace per-word cursor is
        enabled (grammar configs). Replaces the whole-slab
        representation-build of :meth:`_forward_body` with an internal
        per-word loop -- **ONE forward = ONE sentence = ONE IR loss =
        ONE backward**:

          ``inputSpace.run_word_loop(per_word_cell, W)``:
            * the ``[B,1,D]`` ground-truth word ``w`` is run through the
              SAME per-stage PS->CS->WS recurrent cell as the whole-slab
              path (``bindingDepth`` passes, with the C->P / C->S
              feedback identical to ``_forward_body``), but with a
              single-word ``in_sub`` instead of the whole slab;
            * the resulting per-word terminal concept (the last pass's
              CS event, ``[B,1,D_c]``) is inserted into
              ``conceptualSpace.stm`` via the vectorised masked push;
          the statically masked W-position loop ends the sentence traversal.

        Then the accumulated STM feeds the **EXISTING** compose-to-S
        chart (``_chart_compose_at_C``) and the method returns the
        terminal CS subspace so the existing ``_forward_head`` +
        ``runBatch`` P-space_role masked-LM IR-loss + ``reverse()`` TAIL run
        **unchanged** (guiding principle: minimise new training-critical
        surface -- reuse the existing IR machinery verbatim; only the
        representation-build FRONT changes from whole-slab to per-word
        accumulation into STM).

        IR-loss faithfulness: the IR mask is created exactly as in the
        whole-slab path -- via the unchanged ``self.create_ir_mask`` --
        on the **first word's** pass-0 perceptual event (the faithful
        per-word analogue of "pass 0's perceptual event").
        ``runBatch``'s masked-LM loss then reads the post-body
        PartSpace event vs the snapshotted pre-mask embedding at
        the mask positions, byte-identically to today (no new loss
        surface, no compose/reverse loss rewiring).

        STM is sentence-scoped: ``ConceptualSpace.stm`` is sized to
        ``<stmCapacity>`` (sentence length -- the CKY+resize-
        equivalent baseline per the two-loop spec's Phase-1-D §3); the
        bounded soft REDUCE-to-<=7 over STM is the SEPARATE 2b-2
        increment (out of scope here). ``push_step`` requires depth to
        start at 0, so the STM is cleared once at loop entry (the
        sentence-boundary clear that ``ConceptualSpace.Reset(hard=True)``
        also performs).
        """
        # Prelude: STM resize+clear, MPHF pre-warm, SymbolSubSpace
        # per-sentence invariants + CS-feedback pre-seed
        # (ConceptualSpace peer lanes), fresh _cs/_ss caches. Hoisted
        # into ``_per_word_prelude`` so the capture-gate test can
        # replay the same boundary-side contract. Now also: allocate /
        # zero the preallocated ``_per_word_concept_buf`` [B, N, D_c]
        # and set ``symbolSpace._target_cursor_length = N`` so compose
        # pads the S-space_role rule cursor to N with id_SS.
        stm, N_target, word_carrier, in_event = self._per_word_prelude(in_sub)
        if not torch.compiler.is_compiling():
            # Eager forwards lex inline, then the prelude performs the one-time
            # cold sentence reset.  Record the detached teacher after that reset
            # so it remains available to reverse supervision.
            self._stage_reconstruction_teacher()

        # §6c sentence protocol (config-gated; default OFF until the
        # author's cutover): pump zero — the independent parallel
        # prelude seeding both towers and producing the §5 intent —
        # runs BEFORE the serial task; the per-word ticks then carry
        # the §6d serial partition (``serial_pump=True``, set by the
        # prelude's epilogue). Gist refresh below is on preemption
        # only (sign-off: no clause-boundary refresh, no sandwich).
        protocol_on = bool(getattr(self, 'sentence_protocol', False))
        if protocol_on:
            self._sentence_prelude(in_event, word_carrier)

        # The per-word loop IS the recurrence: it replaces the
        # whole-slab cell's ``bindingDepth`` pass loop with a
        # word-indexed loop. Per the ratified design each word is ONE
        # PS->CS->WS step (Pre Stage 1.C this was a single
        # ``sigma_percept`` Σ-lift; post 1.C it is a single STM push of
        # the materialised PS/WS combine onto ``cs.stm``), and the
        # C->P / C->S feedback carries word-to-word
        # (the cross-step carrier), mirroring exactly how
        # ``_forward_body`` carries ``prevCS_*`` across its passes:
        # initialise the feedback ONCE before the loop, update it each
        # step. (Resetting the feedback per word would cold-start WS
        # every word -> WS always sees the empty seed -> the symbol
        # subspace zeroes out; the whole-slab path explicitly carries
        # this feedback across steps.)
        #
        # The canonical cell is the **TERMINAL-stage** PS/CS/WS
        # (``self.perceptualSpace`` / ``self.conceptualSpace`` /
        # ``self.wholeSpace`` == ``*Spaces[-1]``). The whole-slab
        # path chains the ``bindingDepth`` per-stage spaces (each a
        # DISTINCT instance with a progressively N-halved shape, the
        # terminal one keeping full N); but the per-word loop replaces
        # that stage-chaining N-bottleneck with the per-word STM
        # accumulation, so it runs the single terminal cell -- the one
        # whose shape/codebooks the ENTIRE reused tail reads
        # (``_chart_compose_at_C`` -> ``self.conceptualSpace.stm``,
        # ``symbol_cache`` -> ``self.wholeSpace``, the head sized
        # from ``conceptualSpaces[-1].outputShape``, ``runBatch``'s
        # P-space_role IR loss -> ``self.perceptualSpace.subspace``). Using a
        # non-terminal stage would leave ``self.wholeSpace.subspace``
        # / ``self.conceptualSpace.stm`` unwritten (the bug an earlier
        # ``body_stages[0]`` cut hit). The word loop -- not a stage
        # loop -- provides the recurrence depth.
        # NOTE: cs/ws handles, prevCS_forPS/WS empty-seed init, MPHF
        # pre-warm, recur_pass reset, and STM resize+clear all folded
        # into ``_per_word_prelude`` (called above). The captured body
        # reads ConceptualSpace peer lanes uniformly (prelude seeds
        # them to the empty seeds; the body switches to
        # ``cs._subspaceForPS/WS`` once cs.forward has run for the
        # first time) -- no per-iteration None branch.

        # Static per-word loop (replaces the data-dependent
        # ``while next_word() is not None`` boundary).
        #
        # Recompile-churn fix (doc/plans/2026-07-04): the trip count is the
        # STATIC per-word SLAB WIDTH ``N_words`` (the padded ``_ar_embedded_N``
        # column count == PartSpace.nOutput, a per-config constant), NOT the
        # per-sentence ``min(N_static, K_host)`` the loop used before. That old
        # bound == ``K_host`` (since ``InputSpace.outputShape[0]`` is the huge
        # raw-byte width, e.g. 8192 >> the word count), so it varied with the
        # sentence word-count (1..N_words) -> Dynamo unrolled a fresh graph per
        # length and blew ``cache_size_limit``. ``out_slot`` is a FIXED-LENGTH
        # ``N_words`` list written by python-constant index ``p`` (was
        # ``append`` -> a length that grew with the trip count, a second
        # recompile driver -- the ``len(out_slot) == k`` guard the census hit).
        # Padding columns (``p >= K_host``) are byte-identical no-ops: the
        # ``word_active`` gate zeroes their contribution and masks the STM push
        # (``push_step_masked`` with an all-False gate leaves ``_buffer`` /
        # ``_depth`` untouched); the CS/idea forwards fired anyway. ``K_host``
        # now only reconstructs the host depth mirror post-loop -- it never
        # enters the graph.
        # See doc/plans/2026-05-20-static-per-word-loop-impl.md §2.
        _slab = self.inputSpace._ar_embedded_N
        N_words = (int(_slab.shape[1]) if _slab is not None
                   else (int(N_target) if N_target is not None
                         else int(self.inputSpace.outputShape[0])))
        word_active = self.inputSpace._word_active_mask
        # Eager path prepares the same fixed construction-choice slab that
        # runBatch prepares before entering a fullgraph W loop.  Allocation is
        # deliberately outside captured execution; the word cells only write
        # fixed integer/mask slots.
        if (not torch.compiler.is_compiling()
                and torch.is_tensor(_slab)):
            self._prepare_reconstruction_choices(
                int(_slab.shape[0]), N_words, _slab.device)
        _compiled_static_loop = bool(
            torch.compiler.is_compiling()
            and getattr(self, "_compiled_word_loop_fullgraph", False))
        if _compiled_static_loop:
            # The tensor word mask already makes padding columns exact
            # no-ops.  Do not read the eager host summary here: every distinct
            # sentence length otherwise becomes a Python guard and requests a
            # new W-loop compilation despite the static W recurrence.
            N_loop = N_words
        else:
            K_host = int(self.inputSpace._valid_len_host)
            N_loop = min(N_words, K_host)
        out_slot = [None] * N_words
        self._per_word_contributions = out_slot
        _word_major = getattr(self.inputSpace, "_ar_word_part_ids", None)
        self._per_word_percept_contributions = (
            [None] * N_words if torch.is_tensor(_word_major) else None)

        # Skip-padding (eager only): run the body only up to the batch's
        # LONGEST sentence (``N_loop == K_host`` is the last column with any
        # active row across the batch, so columns ``[N_loop, N_words)`` are
        # empty for EVERY row). Byte-identical -- a skipped column leaves
        # ``out_slot[p]`` None, which the post-loop fills with the SAME zeros
        # the gate-masked body would have produced, and its STM push / mirror
        # advance were no-ops. Under ``torch.compile`` the trip count stays the
        # static ``N_words`` (a data-dependent count recompiles per length --
        # the 2026-07-04 static-loop contract); eager (CPU / host-island MPS,
        # where MM_20M actually runs) has no such constraint, so the loop cost
        # tracks the real sentence length instead of the padded slab width.
        _n_trips = N_words
        if not torch.compiler.is_compiling():
            _n_trips = max(1, min(N_words, N_loop))

        last_cs = None
        # Mid-sentence reground REMOVED (Alec 2026-07-07). The §6 preattention
        # rung (per-word conflict-mass check -> re-pump the gist on the rising
        # edge) was the forward's ONLY fullgraph=True blocker (6 data-dependent
        # ``.item()`` reads), and it was structurally dormant in training: the
        # absolute truth store's writers (``record``/``record_batch``) live on
        # the reasoning path only, so the store is empty during runEpoch and
        # the conflict mass is identically 0 -- the rung never fired. The
        # sentence-START prelude (the §6c pump-zero gist/intent) is unchanged;
        # the intent is now sentence-scoped with no mid-sentence refresh. If a
        # truth-grounded curriculum later wires store writes into the forward,
        # reintroduce the reground MASKLESS (always-pump + ``torch.where`` on
        # the intent, latch as a tensor) so fullgraph survives; the old
        # branched form is in git history at this site.
        _peer_pipeline = bool(getattr(self, "_peer_pipeline_enabled", True))
        _chunk_replayed = False
        tensor_trip_count = None
        tensor_sentence_roots = None
        tensor_chunk_state = None
        _tensor_peer_pipeline = (
            bool(getattr(self, '_sentence_ends', False))
            or (_peer_pipeline and self._tensor_peer_while_ready(N_words)))
        if _tensor_peer_pipeline:
            # W is a capacity. The tensor loop stops at the last live column,
            # drains the final conceptual transaction, and advances both
            # grammar-feedback latches.
            (last_cs, tensor_trip_count, tensor_sentence_roots,
             tensor_chunk_state) = (
                self._run_tensor_peer_word_pipeline(N_words))
            _n_trips = N_words
        elif _peer_pipeline:
            # A/B/C is statically padded even on the eager host path: draining
            # B and C after the last active word is part of sentence semantics,
            # not an optional padding optimisation.
            _n_trips = N_words
            last_cs = self._run_peer_word_pipeline(out_slot, _n_trips)
        elif (self._compiled_word_chunk_active
                and self._compiled_word_chunk_step is not None
                and torch.is_grad_enabled()):
            # The eager outer forward would otherwise choose the active-prefix
            # trip count.  Replaying the static even bucket keeps K=2 shapes
            # stable; inactive tail columns remain exact masked no-ops.
            _n_trips = N_words
            last_cs = self._run_aligned_word_chunk_loop(
                out_slot, _n_trips)
            _chunk_replayed = last_cs is not None
        else:
            last_cs = None
        if last_cs is None:
            last_cs = self.inputSpace.run_word_loop(
                self._per_word_body_step, out_slot, _n_trips,
                active_host=True)
        if protocol_on:
            # Sentence end: un-stamp the per-pump mode (the §6d law
            # falls back to the legacy read between sentences).
            self._set_serial_pump(None)
        word_count = N_loop
        # STM host depth mirror correction (2026-07-04 recompile-churn fix).
        # The per-word body advances ``_max_depth_host`` once per iteration,
        # and the loop now runs the full static per-word slab width
        # ``N_words`` instead of the active prefix ``N_loop``. So a SHORT
        # sentence's ``N_words - N_loop`` padding columns each added ONE
        # spurious advance (their masked push is a state no-op, but the host
        # ``+= 1`` still ran). SUBTRACT exactly that over-count to restore the
        # value the varying-trip-count loop left. This is a pure host-int
        # correction (never enters the graph). It must NOT clobber the mark to
        # the per-word count: ``_max_depth_host`` is a high-water mark advanced
        # by EVERY STM push site (e.g. ConceptualSpace.forward's
        # ``_stm_shift_and_push`` also bumps it), so the true value can exceed
        # ``N_loop`` (test_bounded_stm_fold measures N_total=24 >> the 8 words).
        # Padding columns never trip the ``>= capacity`` back-pressure (a
        # below-cap sentence's mirror stays < cap there; the configs that DO
        # reach cap fill every column, so ``N_words == N_loop`` and the
        # correction is zero), so the subtraction exactly undoes the padding
        # advances. Pins: test_bounded_stm_fold::test_cap_equivalence (the
        # high-water mark survives) + test_per_word_ss_padding_noop (the
        # per-forward advance == active-prefix count, not N).
        if (stm is not None and not _tensor_peer_pipeline and not _chunk_replayed
                and not _compiled_static_loop):
            # Only the columns that ACTUALLY ran advanced the mirror, so the
            # over-count is ``_n_trips - N_loop`` (== ``N_words - N_loop`` on
            # the static/compiled path; 0 on the eager skip-padding path, which
            # never ran the padding columns).  The reusable chunk path never
            # increments this host mirror inside a padded word cell and repins
            # it from the live tensor depth once after replay, so applying the
            # legacy subtraction there would double-correct short sentences.
            _pad_overcount = max(0, _n_trips - N_loop)
            if _pad_overcount:
                stm._max_depth_host = max(
                    0, int(stm._max_depth_host) - _pad_overcount)

        # Restore the full whole-sentence event onto the InputSpace
        # subspace so post-body readers (``_forward_per_stage``'s
        # ``forwardInput``/``input_state``, the guarded ``lossRev``
        # reverse term) see the same ``[B,T,D]`` surface the whole-slab
        # path leaves behind. ``_ar_embedded`` itself was never touched
        # (the cursor source), so this only re-stamps the subspace event
        # the per-word loop borrowed.
        if in_event is not None:
            self.inputSpace.commit_event(in_event)

        # Reset the recurrent-pass index so standalone
        # PartSpace.forward calls (and the next forward's pass 0)
        # see the AR-streaming serial warm path -- mirrors the
        # whole-slab path's tail.
        if self.symbolSpace is not None:
            self.symbolSpace.recur_pass = 0
        else:
            self.perceptualSpace._recurrent_pass_idx = 0

        # Stack the per-iteration contributions (gradient-preserving)
        # and pad / truncate to ``N_target``. Inactive batch rows /
        # padding columns contributed zero so the tail is naturally
        # zero-padded. ``copy_context`` from the last per-word CS
        # subspace keeps the pipeline symbolSpace/errors/stem-route
        # contract intact.
        # See doc/plans/2026-05-20-static-per-word-loop-impl.md §2.5.
        # ``per_word_contribs`` is now the FIXED-LENGTH ``N_words`` list
        # (index = word position). Non-``None`` slots are the ``[B, D_c]``
        # per-position contributions the body wrote (padding columns and any
        # empty-CS iteration are gate-masked zeros / left ``None``); a
        # ``None`` slot is an iteration whose CS/idea never materialised --
        # the same slots the old ``append`` path simply skipped. Fill those
        # with a zero column so the stack is rectangular, then stack ALL
        # ``N_words`` columns. Padding columns already carry zeros, so the
        # stacked ``[B, N_words, D_c]`` equals the old
        # ``stack(active-prefix) + zero-pad-to-N_target`` byte-for-byte when
        # ``N_words == N_target`` (the serial-config invariant).
        per_word_contribs = self._per_word_contributions
        if torch.is_tensor(per_word_contribs):
            stacked = per_word_contribs
            _real = (
                stacked[:, 0, :] if int(stacked.shape[1]) > 0 else None)
        else:
            _real = next(
                (c for c in per_word_contribs if c is not None), None)
            if _real is not None:
                _zc = torch.zeros_like(_real)                 # [B, D_c]
                filled = [c if c is not None else _zc
                          for c in per_word_contribs]
                stacked = torch.stack(
                    filled, dim=1)                            # [B, W, D_c]
            else:
                stacked = None
        if last_cs is not None and _real is not None:
            Bc, n_w, Dc = stacked.shape
            if N_target is not None and n_w < N_target:
                pad = torch.zeros(
                    Bc, N_target - n_w, Dc,
                    device=stacked.device, dtype=stacked.dtype)
                stacked = torch.cat([stacked, pad], dim=1)
            elif N_target is not None and n_w > N_target:
                stacked = stacked[:, :N_target, :]
            last_cs = self.conceptualSpace.commit_from(last_cs, stacked)
        # Restore a word-aligned PartSpace slab for the existing P-space IR /
        # reverse consumers.  During the loop PartSpace correctly held only
        # the active word; without this stack, those readers would see the
        # final word repeated as the whole sentence representation.
        ps_word_contribs = self._per_word_percept_contributions
        if torch.is_tensor(ps_word_contribs):
            self.perceptualSpace.commit_event(ps_word_contribs)
            object.__setattr__(
                self.perceptualSpace, "_word_aligned_output",
                ps_word_contribs)
        elif isinstance(ps_word_contribs, list):
            ps_real = next(
                (c for c in ps_word_contribs if c is not None), None)
            if ps_real is not None:
                ps_zero = torch.zeros_like(ps_real)
                ps_stacked = torch.stack([
                    c if c is not None else ps_zero
                    for c in ps_word_contribs
                ], dim=1)
                self.perceptualSpace.commit_event(ps_stacked)
                object.__setattr__(
                    self.perceptualSpace, "_word_aligned_output", ps_stacked)
        self._per_word_percept_contributions = None
        # The detached surface teacher (exact leaves, radix spellings, and any
        # durable concept IDs) was staged at the eager boundary before capture.
        # Keeping that dense copy out here avoids a Python attribute mutation
        # and an O(B*W*D) clone in the compiled sentence body.
        self._per_word_contributions = []

        # 2b-2-i: NULL-closing finalize -- the BOUNDED soft REDUCE sweep
        # composes the accumulated STM down to a SINGLE idea S (the
        # start-symbol root). The legacy ``_chart_compose_at_C`` CKY
        # chart stays dormant/dead (it was a 100% runtime no-op on
        # empty STM and its math was never run); per the two-loop spec
        # ("Phase 2 rebuilds the producer, it does not tune it") it is
        # REPLACED -- not resurrected -- by this bounded soft
        # shift-reduce / selector-in-S producer. The per-word SHIFT
        # loop above filled STM (bounded <= cap by back-pressure); the
        # NULL closing (``next_word`` -> None ended the loop) now fires
        # the final bounded reduce sweep to the root.
        #
        # The numeric answer reads the concluded one- or three-slot state
        # through _forward_head, with the producer's gradient cut. The
        # position-aligned carrier remains available to the perceptual inverse.
        sentence_idea = None
        sentence_post_depth = None
        if (stm is not None and word_count > 0
                and getattr(self.inputSpace, "_per_word_enabled", False)):
            # (The S2 Method-1 leaf slab -- the per-word percept events --
            # was stashed above, BEFORE this reduce collapses the STM, so the
            # exact teacher replay never sees the folded state.)
            if getattr(self, '_packed_prediction_drained', False):
                S, post_depth = self._stm_single_S, self._stm_post_depth
            else:
                S, post_depth = self._stm_reduce_to_single_S()
            sentence_idea = S
            sentence_post_depth = post_depth
            if torch.is_tensor(tensor_sentence_roots):
                final_end = torch.logical_and(
                    self.inputSpace._packed_sentence_end_mask,
                    torch.logical_not(
                        self.inputSpace
                        ._packed_sentence_intermediate_end_mask))
                final_valid = final_end.any(dim=1)
                final_slot = (
                    self.inputSpace._packed_sentence_ids.amax(dim=1)
                    .clamp(
                        0, int(tensor_sentence_roots.shape[1]) - 1))
                root_candidate = self._tensor_write_word_column(
                    tensor_sentence_roots, final_slot, S.clone())
                tensor_sentence_roots = torch.where(
                    final_valid.reshape(
                        int(S.shape[0]), 1, 1),
                    root_candidate, tensor_sentence_roots)
                # The loop bank owns intermediate endings; complete it with
                # each row's final closing before capturing answer programs.
                # Ragged rows can finish in different sentence slots.
                end_slots, end_depth = self._final_end_state(S, post_depth)
                live_roots, live_depth = tensor_chunk_state[4:6]
                live_candidate = self._tensor_write_word_column(
                    live_roots, final_slot, end_slots.flatten(1))
                live_roots = torch.where(final_valid[:, None, None], live_candidate, live_roots)
                depth_candidate = live_depth.scatter(1, final_slot[:, None], end_depth[:, None])
                live_depth = torch.where(final_valid[:, None], depth_candidate, live_depth)
                tensor_chunk_state = (*tensor_chunk_state[:4], live_roots, live_depth)
                if not torch.compiler.is_compiling():
                    object.__setattr__(self, "_tensor_sentence_roots_live", live_roots)
                    object.__setattr__(self, "_tensor_sentence_roots_depth", live_depth)
            # Verification handles for the end-to-end probe / future
            # 2b-2-ii consumer: the single sentence idea S [B, D_c]
            # and the post-sweep STM depth (must be 1 across rows).
            self._stm_single_S = S
            self._stm_post_depth = post_depth
        # Existing loss_head plumbing (dormant: ``loss_head`` is always
        # None today) -- kept identical to the whole-slab tail so the
        # two paths stay structurally symmetric.
        if self.loss_head is not None:
            grad_input = self._loss_head_input
            if grad_input is None:
                grad_input = self.conceptualSpace.stm.snapshot()
            if grad_input is not None:
                self._loss_head_loss = self.loss_head(grad_input)
            else:
                self._loss_head_loss = None
        if return_sentence_state:
            if tensor_trip_count is None:
                raise RuntimeError(
                    "explicit compiled sentence state requires the tensor "
                    "peer while-loop")
            chunk_state = tuple(tensor_chunk_state or ())
            if not all(torch.is_tensor(value) for value in (
                    sentence_idea, sentence_post_depth,
                    tensor_trip_count, tensor_sentence_roots,
                    *chunk_state)) or len(chunk_state) != 6:
                raise RuntimeError(
                    "serial sentence body did not produce tensor "
                    "(S, post_depth, trip_count, roots, wholes, "
                    "proposals, proposal_count, references, end_slots, "
                    "end_depth) state")
            recon = self._reconstruct_sentence_if_enabled(
                sentence_idea, chunk_state[3], chunk_state[4], chunk_state[5],
                *self._final_end_state(sentence_idea, sentence_post_depth))
            return last_cs, (
                sentence_idea, sentence_post_depth, tensor_trip_count,
                tensor_sentence_roots, *chunk_state[:3], *recon)
        return last_cs

    def _chart_compose_per_word(self):
        """Per-word router fire (Alec 2026-07-13: "the router should be
        firing as every word is added, since the STM is not long enough to
        preserve the sentence before parsing is initiated").

        The same signal-router fire as the boundary chart, run over the
        CURRENT STM contents right after each word push, so
        ``current_rules`` carries THIS sentence's rules while it is still
        being read — the reduce sweep's relative mask (``protect_depth``
        3) can then key on them. This implements the documented
        ``<routerWireSerial>`` semantics ('per-word' and the 'both'
        default) which were previously VALIDATION-ONLY — no fire site
        existed. Host-eager (the full-router island is
        ``@torch.compiler.disable``'d); skipped under compile like the
        sibling provenance bookkeeping.
        """
        if not self.word_brackets:
            return
        if getattr(self, 'router_wire_serial', 'both') not in (
                'per-word', 'both'):
            return
        snap = self.conceptualSpace.stm.snapshot()
        # Parsing initiates once TWO constituents exist — a 1-item stack
        # has nothing to reduce, and the binary layer's degenerate N<=1
        # path returns a routing dict without the rule-id keys.
        if snap is None or snap.dim() != 3 or int(snap.shape[1]) < 2:
            return
        # DETACHED CLONE: snapshot() is a VIEW of the live STM buffer, and
        # the router's compose mutates its slab — an in-place write there
        # bumps the buffer version the pending backward saved (measured:
        # "[1016] at version 1" backward crash). The per-word fire exists
        # for the RULE BOOKKEEPING (current_rules); the boundary fire
        # keeps the gradient role.
        self.languageSpace.forward(snap.detach().clone())

    def _chart_compose_at_C(self, stage_idx=0):
        """Fire the signal router at C-space_role over
        ``conceptualSpace.stm`` contents.

        Populates ``symbolSpace.current_rules`` for downstream WS
        dispatch. Uses :meth:`ShortTermMemory.snapshot` to obtain a
        single uniform ``[B, max_depth, D_c]`` slab (rows with shorter
        sentences carry zero-padding at the tail).

        FULL-ROUTER fires run as an eager island
        (``_ss_compose_eager``, ``@torch.compiler.disable``'d — the
        house pattern, cf. ``observe_stm_end_state``): the router's
        rule-id bookkeeping (``languageLayer.compose``'s per-row
        ``int(kind[b, j].item())`` branching) is data-dependent host
        control flow dynamo cannot guard on (``Could not guard on
        data-dependent expression Eq(u0, 2)`` — MM_xor on the compiled
        per-stage path). Its products are host dicts
        (``current_rules`` / cursors) read BEFORE captured regions, so
        the island changes no numerics; full-router configs compile
        with fullgraph=False (see ``enable_compiled_step``). The
        DEFAULT-ONLY bypass never reaches the router loops, stays
        traceable inline, and keeps the strict fullgraph gate
        (a disabled call inside a fullgraph=True trace would itself
        hard-error — MM_20M).

        Method name preserved across the Stage 3 chart retirement; it
        now drives ``SymbolSubSpace.compose`` -> ``languageLayer.compose``.

        Gated by ``<routerWireSerial>`` (Task 4 / plan §4): the boundary
        fire runs iff ``self.router_wire_serial in ('boundary', 'both')``.
        Default ``both`` keeps this firing — pre-existing behaviour is
        preserved. This is the final routing snapshot the inter-sentence
        predictor consumes (retained per plan §4).
        """
        if not self.word_brackets:
            return
        if getattr(self, 'router_wire_serial', 'both') not in (
                'boundary', 'both'):
            return
        snap = self.conceptualSpace.stm.snapshot()
        if snap is None:
            return
        # LanguageSpace schedules the existing SymbolSpace-owned parser and
        # returns its reduction plan. CS remains the only owner that commits
        # any conceptual/STM mutation from that plan.
        self.languageSpace.forward(snap)

    def _reverse_seed_snapshot(self, seed):
        """Return a ``[B, N, D]`` idea snapshot from reverse's seed, if any."""
        if seed is None:
            return None
        try:
            snap = seed.materialize() if hasattr(seed, "materialize") else seed
        except Exception:
            return None
        if not torch.is_tensor(snap):
            return None
        if snap.dim() == 2:
            return snap.unsqueeze(1)
        if snap.dim() == 3:
            return snap
        return None

    def _chart_generate_from_stm(self, seed=None):
        """Fire ``symbolSpace.generate`` over the C-space_role STM snapshot.

        Reverse-path mirror of ``_chart_compose_at_C`` (full-router
        fires run via the ``_ss_generate_eager`` island for the same
        reason — see there): populates ``symbolSpace.generate_rules``
        so each stage's reverse dispatch can pop them via its
        SyntacticLayer cursor.

        Method name preserved across the Stage 3 chart retirement; it
        now drives ``SymbolSubSpace.generate`` -> ``languageLayer.generate``.

        Gated by ``<routerWireSerial>`` (Task 4 / plan §4): the boundary
        reverse fire runs iff
        ``self.router_wire_serial in ('boundary', 'both')``. Default
        ``both`` keeps this firing — pre-existing behaviour is preserved.

        REVERSE-LEG NOTE (Task 4): there is no per-word reverse loop
        analogous to ``_forward_body_per_word`` — the reverse path
        (``reverseReconstruct``) fires ``generate`` only here, at the
        boundary, over the whole STM snapshot. So per-word reverse has
        no natural site; the boundary reverse fire is the reverse-leg
        deliverable and is retained (gated identically to the forward
        boundary fire).

        IDEA-DECODE (``<ideaDecode>``, Goal 2 step 1): when on by itself, the
        parse tree is DELETED -- so there is no ``generate_rules`` to rebuild
        here. Skip the chart fire entirely; the reverse path then runs with an
        empty rule set, driven by the primed symbolic space rather than the
        chart. ``<reconstructFromIdea>`` is the opposite experiment: erase the
        old derivation, then rebuild ``generate_rules`` from the supplied idea
        seed (falling back to STM when no seed is usable).
        """
        if not self.word_brackets:
            return
        from_idea = bool(getattr(self, 'reconstruct_from_idea', False))
        if getattr(self, 'router_wire_serial', 'both') not in (
                'boundary', 'both'):
            return
        ss = self.symbolSpace
        if ss is None:
            return
        if from_idea and hasattr(ss, "clear_grammar_cache"):
            ss.clear_grammar_cache()
        stm = self.conceptualSpace.stm
        if stm is None:
            return
        snap = self._reverse_seed_snapshot(seed) if from_idea else None
        if snap is None:
            snap = stm.snapshot()
        if snap is None:
            return
        ss.reverse(snap)

    def _stm_symbolic_roundtrip(self, slab):
        """Idempotent C→S→C round-trip over a full ``[B, cap, D_c]`` STM
        slab (the widened symbolic-space loop -- H2).

        This is the retired ``_forward_stem_per_word`` C→S→C round-trip
        (``a8737da~1``) -- ``cb.forward(c)`` then ``cb.reverse(snap, V=1)``
        then ``idea_back.sum(dim=1)`` per single word -- generalized from
        the single-vector ``V=1`` regime to ``V = STM capacity`` so the
        whole ``[B, cap, concept_dim]`` STM slab passes through symbolic
        space and back in one shot, idempotently and **per slot** (all
        ``cap`` slots preserved -- the legacy single-slot
        ``idea_back.sum(dim=1)`` collapse is dropped, NOT replaced by a
        V-axis mean collapse).

        Mechanism (faithful generalization of the retired vectorised
        path's ``c_flat = c_all.reshape(B_flat * N, 1, D_c)`` trick):
        fold the ``cap`` axis into the batch dim so each STM slot is its
        own row through ``ProjectionBasis.forward`` / ``.reverse(V=1)``,
        then unfold. ``ProjectionBasis.forward`` collapses the V axis
        (mean-over-V); calling it with ``cb.forward(slab)`` directly +
        ``cb.reverse(snap, V=cap)`` would therefore replicate ONE summary
        across all ``cap`` slots (``x_summary.unsqueeze(1).expand(-1, v,
        -1)``) -- destroying STM as a per-slot working memory. The
        per-slot fold preserves each slot's own reverse-lift, exactly as
        the retired loop did, while remaining idempotent (forward then
        reverse projects each slot onto span(W); a re-snapped slot is a
        fixed point -- the property ``test_idempotent_loop`` pins for
        ``V=1``, here per-slot over ``cap``).

        Returns the round-tripped ``[B, cap, D_c]`` slab, or the input
        unchanged when no ``ProjectionBasis`` codebook is available
        (matches the retired loop's ``ideas = c_all`` fall-through for
        non-ProjectionBasis ``.what``: ``quantize`` / ``none`` configs).

        NOTE (H2 Part B / Phase-2B): this is the rebuilt subsymbolic
        producer's round-trip primitive. It is intentionally NOT yet
        wired into the live forward as the STM read/write -- the STM
        producer lifecycle (when to push, when ``snapshot`` is read,
        the bounded soft shift-reduce controller, the NULL-closing
        finalize, per-word vs per-sentence) is the still-pending,
        owner-perf-gated Phase-2B architecture
        (``doc/plans/2026-05-18-two-loop-pipeline-architecture.md``
        §"STM-7" / Phase-2B; CKY+resize is the documented fallback).
        """
        if slab is None or not torch.is_tensor(slab) or slab.dim() != 3:
            return slab
        cb = getattr(self.wholeSpace.subspace, 'what', None)
        cb_is_projection = (cb is not None
                            and type(cb).__name__ == 'ProjectionBasis')
        if not cb_is_projection:
            # Non-ProjectionBasis ``.what`` (``quantize`` / ``none``):
            # no idempotent projection surface -- pass the slab through
            # unchanged, exactly as the retired ``_forward_stem_per_word``
            # did (``ideas = c_all``).
            return slab
        B, cap, D_c = slab.shape
        # Fold ``cap`` into the batch dim: one STM slot per row so
        # ``ProjectionBasis.forward``'s mean-over-V is a no-op (V=1 per
        # row) and ``reverse(V=1)`` lifts each slot independently. This
        # is the retired vectorised path's ``reshape(B_flat * N, 1,
        # D_c)`` -> ``cb.forward`` -> ``cb.reverse(snap_flat, V=1)``
        # generalized to the whole slab.
        c_flat = slab.reshape(B * cap, 1, D_c)            # [B*cap, 1, D_c]
        snap_flat = cb.forward(c_flat)                    # [B*cap, N, 1]
        back_flat = cb.reverse(snap_flat, V=1)            # [B*cap, 1, D_c]
        if back_flat is None:
            return slab
        if back_flat.dim() == 3:
            # [B*cap, 1, D_c] -> [B, cap, D_c]. The legacy single-slot
            # ``idea_back.sum(dim=1)`` is dropped (V=1 here, so the sum
            # was a no-op squeeze): all ``cap`` slots are kept.
            return back_flat.reshape(B, cap, D_c)
        return back_flat.reshape(B, cap, D_c)

    # ------------------------------------------------------------------
    # A4 (2026-06-06 parallel-conceptual-recurrence) demux/fit helpers.
    # Option B (doc/specs/2026-06-06-muxed-events-and-positional-bands.md):
    # the per-stage ConceptualCombine operates on the FULL muxed event
    # (content + .where/.when together; sized at ``cs.muxedSize``), so a demux
    # AT the event width returns the whole event with an EMPTY band -- the
    # band PARTICIPATES in the combine rather than riding along. These helpers
    # also serve the narrower-stream fit (the compressed WS symbol code
    # zero-padded up to D).
    # ------------------------------------------------------------------
    @staticmethod
    def _combine_demux(sub, content_dim):
        """Delegates to :meth:`ConceptualSpace._bind_demux` -- the
        calculation lives in the Space (processing contract,
        2026-06-10); this alias serves remaining Models-side callers."""
        return ConceptualSpace._bind_demux(sub, content_dim)

    @staticmethod
    def _combine_fit(content, D, like):
        """Delegates to :meth:`ConceptualSpace._bind_fit` -- the
        calculation lives in the Space (processing contract,
        2026-06-10); this alias serves remaining Models-side callers."""
        return ConceptualSpace._bind_fit(content, D, like)

    # ``_symbolic_sigma_step`` (the content-demux WS.sigma advance the
    # ConceptualCombine replaced) was removed 2026-06-06 (Action C): it was
    # dead in ``bin/`` -- the parallel body advances the carrier through the
    # combine, and ``ws.sigma`` round-trips are exercised directly. The
    # generalization step now lives IN the combine (option B, on the full
    # muxed event), not in a separate content-only operator.

    def _addressable_spaces(self, prevCS_forSS, ps_stage0):
        """Gather the TYPED addressable spaces global attention ranges over
        (doc/specs/reading-attention.md "(B)"; Alec: input window / STM / LTM /
        symbolic codebook). Each entry is a ``PrimedSymbolReader`` space dict with
        DETACHED keys -- per-batch ``[B, M, D]`` (input window, STM) or shared
        ``[M, D]`` (LTM, codebook). Absent spaces are simply omitted."""
        GA = PrimedSymbolReader
        spaces = []
        # INPUT window: the staged word brackets pooled to per-span percept
        # content (the same keys reading uses); else the per-slot percept.
        ws0 = (self.wholeSpaces[0]
               if getattr(self, "wholeSpaces", None) else None)
        percept_ev = (ps_stage0.materialize()
                      if ps_stage0 is not None else None)
        if (percept_ev is not None and torch.is_tensor(percept_ev)
                and percept_ev.dim() == 3 and int(percept_ev.shape[1]) > 0):
            N = int(percept_ev.shape[1])
            spans = getattr(ws0, "_staged_analysis_spans", None) if ws0 else None
            if spans is not None and torch.is_tensor(spans):
                keys = BracketKeys._span_keys(percept_ev, spans)  # [B,K,D]
                spans_f = spans.to(percept_ev.dtype)
                where = (spans_f / float(max(N, 1)))[..., :2]          # [B,K,2]
                valid = (spans_f[..., 1] - spans_f[..., 0]).clamp_min(0.0) > 0
                spaces.append({"id": GA.SPACE_INPUT, "keys": keys.detach(),
                               "where": where.detach(), "valid": valid})
            else:
                spaces.append({"id": GA.SPACE_INPUT,
                               "keys": percept_ev.detach()})
        # STM: the live short-term-memory rows.
        stm = (self.conceptualSpace.stm
               if self.conceptualSpace is not None else None)
        stm_snap = stm.snapshot(detach=True) if stm is not None else None
        if (stm_snap is not None and torch.is_tensor(stm_snap)
                and stm_snap.dim() == 3 and int(stm_snap.shape[1]) > 0):
            spaces.append({"id": GA.SPACE_STM, "keys": stm_snap})
        # LTM: the consolidated TernaryTruthStore rows (present only under
        # <ltmConsolidation>); pool the three idea slots to one content key.
        ss = getattr(self, "symbolSpace", None)
        ltm = getattr(ss, "ltm_store", None) if ss is not None else None
        if ltm is not None and hasattr(ltm, "slots"):
            cnt = int(getattr(ltm, "count", torch.tensor(0)).item()) \
                if torch.is_tensor(getattr(ltm, "count", None)) else 0
            if cnt > 0:
                # A retained next-sentence estimate is durable so its
                # residual can be learned later, but it is not observed LTM
                # evidence.  Generic retrieval has no provenance channel to
                # distinguish a forecast from a fact, so letting it enter the
                # shared attention pool would feed a prediction back into the
                # parser/reasoner as if it were a new source.  The dedicated
                # expectation-pair API is its only generic reader here.
                estimate_kind = ltm.KINDS.index("estimate")
                eligible = ltm.record_kind[:cnt] != estimate_kind
                if bool(eligible.any()):
                    rows = ltm.slots[:cnt][eligible].detach().mean(dim=1)  # [M, D]
                    spaces.append({"id": GA.SPACE_LTM, "keys": rows})
        # The three tower codebooks, emitted as distinct address spaces (PART,
        # WHOLE, SYMBOL). Was previously one lumped SPACE_CODEBOOK (ws0-or-PS).
        concept_q = BracketKeys._pool(prevCS_forSS)

        def _codebook_rows(_sp):
            sub = getattr(_sp, "subspace", None) if _sp is not None else None
            cb = (sub.codebook()
                  if sub is not None and hasattr(sub, "codebook") else None)
            getW = getattr(cb, "getW", None) if cb is not None else None
            rows = getW() if callable(getW) else None
            if (rows is not None and torch.is_tensor(rows)
                    and rows.dim() == 2 and int(rows.shape[0]) > 0):
                return rows
            return None

        # PART codebook (PartSpace part-percepts).
        ps_rows = _codebook_rows(getattr(self, "perceptualSpace", None))
        if ps_rows is not None:
            spaces.append({"id": GA.SPACE_PART, "keys": ps_rows.detach()})
        # WHOLE codebook (WholeSpace) -- carries the intent-priming boosts.
        ws_rows = _codebook_rows(ws0)
        if ws_rows is not None:
            ws_boosts = ws0.intent_boosts() if ws0 is not None else None
            if ws_boosts is None and concept_q is not None:
                from Spaces import intent_priming_weights
                ws_boosts = intent_priming_weights(concept_q.detach(), ws_rows)
            spaces.append({"id": GA.SPACE_WHOLE, "keys": ws_rows.detach(),
                           "boosts": ws_boosts})
        # SYMBOL codebook (SS.subspace.what). Present only under <symbolTower>
        # (else the SS ``.what`` is an empty Basis with no ``getW``).
        ss = getattr(self, "symbolSpace", None)
        ss_sub = getattr(ss, "subspace", None) if ss is not None else None
        ss_cb = getattr(ss_sub, "what", None) if ss_sub is not None else None
        ss_getW = getattr(ss_cb, "getW", None) if ss_cb is not None else None
        if callable(ss_getW):
            sym_rows = ss_getW()
            if (sym_rows is not None and torch.is_tensor(sym_rows)
                    and sym_rows.dim() == 2 and int(sym_rows.shape[0]) > 0):
                # CLONE (not just detach): _build_symbol_leg writes this
                # codebook Parameter in-place (no_grad) LATER in the same
                # forward, which would bump the version of a detached view the
                # attention scorer saved for backward. A clone decouples the
                # attention key from the live Parameter. (The other spaces'
                # codebooks are written only at the Reset boundary, so a plain
                # detach is safe for them.)
                spaces.append({"id": GA.SPACE_SYMBOL,
                               "keys": sym_rows.detach().clone()})
        return spaces, concept_q

    @torch.compiler.disable
    def _answer_attention_step(self, prevCS_forSS, ps_stage0, *, record=None, charge=True):
        """Generation-owned read of the registry and the primed symbol bank.

        Space candidates use 7.5's categorical law. Costing a generate trial
        gets a copy of the common meter; only the concluded answer charges it.
        """
        ga=self.answer_attention
        if ga is None:return
        spaces,concept_q=self._addressable_spaces(prevCS_forSS,ps_stage0)
        bank=getattr(record,'primed',None) if record is not None else getattr(self,'_sentence_primed_bank',None)
        if bank is not None:
            spaces=[s for s in spaces if s['id'] != ga.SPACE_SYMBOL]
            spaces.append(dict(id=ga.SPACE_SYMBOL,keys=bank.codes.detach(),
                               valid=bank.valid,boosts=bank.weights.detach()))
        column=getattr(self.conceptualSpace,'_word_column',None)
        if torch.is_tensor(column):concept_q=column.detach().mean(1)
        stm=getattr(self.conceptualSpace,'stm',None)
        symbol_q=BracketKeys._pool(stm.snapshot(detach=True) if stm is not None else None)
        work=getattr(self,'_attention_meters',()) or None
        if work is not None and not charge:
            from copy import copy
            work=tuple(copy(meter) for meter in work)
            for meter in work:meter._counts=meter._counts.copy()
        obs=ga(concept_q=concept_q,symbol_q=symbol_q,spaces=spaces,
               chooser=self._stm_reducer(),work=work)
        object.__setattr__(self,'_answer_attention_obs',obs)
        if charge and obs is not None and getattr(self,'_attention_words',None) is not None:
            from Attention import LEVEL_ROW
            table=self._attention_words.table
            slot=(~table.valid).long().argmax(-1)
            rows=torch.arange(len(slot),device=slot.device)
            active=(obs['space_id']>=0)&(~table.valid).any(-1)
            selected=(torch.arange(table.valid.shape[1],device=slot.device)[None]==slot[:,None])&active[:,None]
            # Typed recall intervals use normalized coordinates, retained in
            # their own table because input intervals are byte offsets.
            from Attention import BracketTable
            intervals=table.intervals.to(obs['where'])
            self._recall_brackets=BracketTable(
                torch.where(selected[...,None],obs['where'][:,None],torch.zeros_like(intervals)),
                selected,torch.where(selected,obs['space_id'][:,None],-1),
                torch.full_like(table.level,LEVEL_ROW),selected,
                torch.tensor([meter.spent for meter in work],device=slot.device) if work is not None else table.spent)

    def _generation_read(self, idea, *, record=None, charge=True):
        """Retrieve into an owned generation operand, preserving its source."""
        reader = getattr(self, 'answer_attention', None)
        if reader is None or not torch.is_tensor(idea):
            return idea
        event = idea[:, None] if idea.ndim == 2 else idea
        shape = tuple(event.shape[1:])
        carrier = SubSpace.from_tensor(event, inputShape=shape, outputShape=shape,
                                      nInputDim=shape[-1], nOutputDim=shape[-1])
        self._answer_attention_step(carrier, self.perceptualSpace.subspace,
                                    record=record, charge=charge)
        observation = getattr(self, '_answer_attention_obs', None)
        return reader.consume(idea, None if observation is None else observation['content'])

    @torch.compiler.disable
    def _reasoning_spaces(self):
        """Gather the typed truth-space the reasoner ranges over -- STM, LTM, and
        the PART/WHOLE/SYMBOL codebooks -- via the SAME registry the forward's
        global attention uses (``_addressable_spaces``), minus the live input
        window. Built from PERSISTENT state, so it is callable outside a forward
        pass (at query/serve time)."""
        try:
            spaces, _ = self._addressable_spaces(None, None)
        except Exception:
            spaces = []
        return spaces or []


    def _run_public_thought(self, meaning, *, row=0, work_budget=32):
        """Admit a completed meaning to the one normal controller.

        Public calls have no later optimizer step. Their ordinary episode is
        detached on return, and permission is restored even on rejection.
        Natural text must first pass through ``understand``; it never selects
        an executor by matching words.
        """
        self._assert_queries_outside_sentence()
        if work_budget <= 0:
            return None
        if not isinstance(meaning, ConceptualMeaning):
            meaning = self._public_query_meaning(meaning, row=row)
        if meaning is None or meaning.mode != "interrogative":
            return None
        with self._query_boundary_scope((row,)):
            try:
                result = self.run_selected_thought(
                    meaning, row=row, work_budget=int(work_budget))
                self._last_selected_thought = result
                return result
            finally:
                self._end_finished_selected_thought_episodes()

    def _public_query_meaning(self, query, *, row=0):
        """Convert an explicit legacy typed request, never natural language."""
        from reasoning import QuerySpec, KIND_IS_PART, KIND_IS_EQUAL, KIND_IS_TRUE
        if not isinstance(query, QuerySpec):
            raise TypeError("public reasoning requires a completed ConceptualMeaning")
        registry = _boundary_registry(self)
        if registry is None:
            return None
        if query.predicate == KIND_IS_PART:
            if query.domain not in (None, "conceptual-taxonomy"):
                raise ValueError("part requires the conceptual taxonomy domain")
            opened = tuple(role for role, value in (
                ("I1", query.left), ("I2", query.right)) if value is None)
            arguments = tuple(value for value in (query.left, query.right)
                              if value is not None)
            return registry.form("part", *arguments, open_roles=opened,
                                 polarity=query.desired_polarity)
        if query.predicate == KIND_IS_EQUAL:
            return registry.form("equal", query.left, query.right,
                                 polarity=query.desired_polarity)
        if query.predicate == KIND_IS_TRUE:
            raise ValueError("exist/true are retired; query conceptual content with what")
        raise ValueError("unsupported typed grammatical query")

    @torch.no_grad()
    def reason_about(self, query_spec, *, spaces=None, beam=8, row=0):
        """Run a completed request through the grammatical thought controller."""
        return self._run_public_thought(
            query_spec, row=row,
            work_budget=int(getattr(self, "reasoning_iterations", 0) or 0))

    @torch.no_grad()
    def think_about(self, query_spec, *, spaces=None, row=0):
        """The thinking API shares the normal controller and ordinary history."""
        return self._run_public_thought(
            query_spec, row=row,
            work_budget=int(getattr(self, "thinking_budget", 0) or 0))


    @torch.no_grad()
    def answer_query(self, user_msg, *, beam=8):
        """Understand text, then execute its completed grammatical question.

        A supplied meaning is already a completed conceptual request. Text
        uses the same forward/program recovery as ordinary answer resolution;
        spelling, punctuation and word positions cannot select a thought tool.
        The returned serving summary is JSON data; the typed result remains
        available as ``_last_selected_thought`` and in ordinary history.
        """
        self._assert_queries_outside_sentence()
        budget = int(getattr(self, "reasoning_iterations", 0) or 0)
        if budget <= 0:
            return None
        self._last_selected_thought = None
        if isinstance(user_msg, ConceptualMeaning):
            meaning = user_msg
        elif isinstance(user_msg, Understanding):
            programs = user_msg.sentence_states
            meaning = (programs[0].query if programs and programs[0] is not None else None)
        else:
            if not isinstance(user_msg, str):
                raise TypeError("answer_query requires text or a completed meaning")
            with self._runtime_batch([user_msg]):
                inputs = self.inputSpace.prepInput(list(self.data.train_input))
                understanding = self.understand(inputs)
                programs = understanding.sentence_states
                if not programs or programs[0] is None:
                    return None
                meaning = programs[0].query
        if meaning is None or meaning.mode != "interrogative":
            return None
        result = self._run_public_thought(meaning, work_budget=budget)
        if result is None:
            return None
        positive = float(result.evidence.get("support_true", 0.0))
        negative = float(result.evidence.get("support_false", 0.0))
        posture = ("BOTH" if positive >= .5 and negative >= .5 else
                   "TRUE" if positive >= .5 else
                   "FALSE" if negative >= .5 else "UNKNOWN")
        return {
            "posture": posture, "confidence": max(positive, negative),
            "support_true": positive, "support_false": negative,
            "sentences": [],  # Text realization belongs to reverseOutput / <generate>.
            "trace": [{"kind": record.kind, "operation": record.operation,
                       "level": record.level} for record in result.records],
            "work": result.work.spent,
            "result_kind": (None if result.result is None
                            else result.result.result_kind),
            "incomplete": list(result.evidence.get("incomplete", ())),
        }

    def _passback_scope_ps(self, pass_idx, ps_default, prevCS_forSS,
                           prevPS_forPS=None):
        """Retarget native perception through conceptual membership attribution.

        The request addresses native percept identities, which choose the
        mereological units, and field brackets, which choose the region.
        The source carrier is read-only.
        """
        if pass_idx <= 0:
            return ps_default
        owner = self._concept_owner()
        field = getattr(self, '_subsymbolic_field', None)
        event = ps_default.materialize() if ps_default is not None else None
        if not torch.is_tensor(field) or not torch.is_tensor(event):
            return ps_default
        size = sum(owner._field_caps())
        query = torch.cat((field, field.new_zeros(size - len(field), *field.shape[1:])))
        columns, attributed, spans = owner.cs_percept_attribution(query, observed=query,
            perception=getattr(owner, '_percept_field', None))
        active = attributed.amax(dim=(1, 2, 3)) > 0
        if not bool(active.any()) or spans is None:
            return ps_default
        evidence = attributed.amax(dim=(0, 2))
        parts = (getattr(self.perceptualSpace, '_forward_input', None) or {}).get('part_spans')
        if not torch.is_tensor(parts) or parts.shape[:2] != event.shape[:2]:
            return ps_default
        overlap = ((spans[:, None, :, 0] < parts[:, :, None, 1])
                   & (spans[:, None, :, 1] > parts[:, :, None, 0]))
        strength = (evidence[:, None] * overlap).amax(-1)
        scope = getattr(self.conceptualSpace, '_passback_scope_where', None)
        if torch.is_tensor(scope):
            bounds = scope.to(parts.device).reshape(-1, 2).expand(parts.shape[0], -1).clamp(0, 1)
            width = max(1, int(self._staged_concepts_in.shape[-1]))
            inside = ((parts[..., 0] >= (bounds[:, :1] * width).floor())
                      & (parts[..., 1] <= (bounds[:, 1:] * width).ceil()))
            strength = strength * inside
        focused = SubSpace(inputShape=(1, 1), outputShape=(1, 1), nInputDim=1, nOutputDim=1)
        focused.copy_context(ps_default)
        # Attention changes salience, never visibility. A half-strength floor
        # preserves novel percepts; attributed units approach full strength.
        scale = .5 + .5 * strength.clamp(0, 1).to(event)
        width = int(self.perceptualSpace.nWhat)
        focused.set_event(torch.cat((event[..., :width] * scale[..., None],
                                      event[..., width:]), -1))
        return focused

    def _reverse_field(self, sub, field):
        """Attribute owned conceptual evidence to native rows at its positions.

        Resolve definitions by id. Descent uses the occurrence evidence before
        the extent union, never an input event, tiling or current perception.
        """
        cs = self._concept_owner()
        store = cs._concept_allocator.layer(0)
        ids = field.concept_ids
        by_id = {(key[1] if isinstance(key, tuple) else key): row
                 for row, key in store._tensor_row_keys.items()}
        rows = torch.tensor([by_id.get(int(cid), -1) if cid != -1 else -1
                             for cid in ids.reshape(-1).tolist()],
                            device=ids.device, dtype=torch.long).reshape(ids.shape)
        S, B, E, _ = field.evidence.shape
        spans = field.percepts.spans
        P = spans.shape[1]
        columns, attributed, _ = cs.cs_percept_attribution(
            field.evidence, observed=field.evidence, inventory_rows=rows,
            perception=field.percepts)
        radix = self.perceptualSpace.percept_store
        width = max(int(self.inputSpace.outputShape[0]), int(field.where.max()))
        activity = attributed.new_zeros(B, width, len(radix))
        primitive = self.wholeSpaces[0].subspace.what.primitive_properties
        properties = attributed.new_zeros(B, width, len(primitive.members), 2)
        offsets = torch.arange(width, device=attributed.device)
        covering = ((offsets >= spans[..., :1]) & (offsets < spans[..., 1:]))
        for edge, col in enumerate(columns.tolist()):
            support = attributed[edge].amax(1)
            if (col // 2) % 2:
                values = (support[..., None] * covering).amax(1)
                unit = F.one_hot(torch.tensor(col // 4, device=values.device),
                                 len(primitive.members)).to(values)
                pole = F.one_hot(torch.tensor(col % 2, device=values.device), 2).to(values)
                properties = torch.maximum(properties,
                    values[..., None, None] * unit[:, None] * pole)
            elif col % 2 == 0:
                feature_edge = edge // 2
                row, original = store.features._rows[feature_edge], store.features._cols[feature_edge]
                group = store.feature_groups.get((row, original), (col // 4,))
                # Ordered native groups are perception's units. Their event
                # support, not a concept's location, locates reconstruction.
                length = sum(len(radix.bytes_for(pid)) for pid in group)
                brackets = torch.cat((spans, field.where), 1)
                support = torch.cat((support, attributed[edge].amax(-1)), 1)
                fits = brackets[..., 1] - brackets[..., 0] == length
                shift = 0
                for pid in group:
                    at = offsets == brackets[..., :1] + shift
                    values = (support[..., None] * (fits[..., None] & at)).amax(1)
                    unit = F.one_hot(torch.tensor(pid, device=values.device), len(radix)).to(values)
                    activity = torch.maximum(activity, values[..., None] * unit)
                    shift += len(radix.bytes_for(pid))
        # Property attribution distributes support over primitive members.
        # Native identities, never nearest distributed codes, address decode.
        byte_support = primitive.reverse_poles(properties)
        byte_ids = [radix.get_id(bytes([value])) for value in range(256)]
        known = [value for value, pid in enumerate(byte_ids) if pid is not None]
        native = torch.tensor([byte_ids[value] for value in known],
                              device=activity.device, dtype=torch.long)
        property_activity = torch.zeros_like(activity).index_add(
            -1, native, byte_support[..., known])
        recovered = sub.carrier_like()
        recovered._radix_activity = torch.maximum(activity, property_activity)
        return recovered

    def _reverse_body(self, sub, *, field=None):
        """Native field attribution, or the serial/dense numerical inverse.

        Native aligned perception inverts its explicitly supplied forward
        evidence by concept id. It never reads stage events or a saved stack.

        Inverts the primary IS→PS→CS→OS path's body: walk stages in
        reverse, undo the optional N-halving ``merge`` then
        ``ConceptualSpace.reverse`` (C → percept space_role). WholeSpace is
        the symbolic recurrent loop leg, off the OS→CS→PS→IS
        reconstruction path; its loop contribution was averaged into C
        in the forward and cannot be decomposed by a single-input
        reverse (round-trip holds for the local per-space inverse).
        B-shaped throughout (the legacy K-axis flatten/restore was
        retired with the AR cursor unfold).

        The merge's forward-cached ``_merge_diff`` is overwritten on
        each of the T recurrent passes, so its N-halving is only
        exactly invertible for the last pass; per-stage reverse is
        guarded so a shape mismatch in an earlier stage degrades the
        reconstruction (approximate through the averaged loops, per the
        single-input-reverse contract) instead of aborting.
        """
        if not self.word_brackets and self.concept_binding == 'aligned':
            # A free inverse cannot substitute the latest perception. Only
            # the explicitly supplied forward field supplies evidence.
            return self._reverse_field(sub, field) if field is not None else sub
        carriers = getattr(self, "_combine_carriers", None)
        _concepts_recon = None
        for t in reversed(range(len(self.body_stages))):
            stage = self.body_stages[t]
            # A4 (2026-06-06 parallel-conceptual-recurrence): invert the
            # per-stage ConceptualCombine before the CS bookkeeping reverse
            # -- exact mirror of the forward order ``cs.forward -> combine``.
            #
            # The combine reverse is driven by the EXACT forward carrier
            # ``carriers[t]`` (the stage-t combine output, threaded as a
            # forward-local), NOT by ``sub``'s content. Reason: the STM push
            # happens INSIDE ``cs.forward`` -- BEFORE the combine writes the
            # advanced carrier via ``set_event`` -- so the STM (and therefore
            # ``sub``, which the reconstruction path sources from the STM
            # snapshot) holds the PRE-combine perception event, not the combine
            # output ``next_cs`` that ``aug_t`` is paired with. Feeding ``sub``
            # into ``combine.reverse`` would break the exact ``next_cs <-> aug``
            # pairing. CONSEQUENCE (a deliberate deviation from design sec
            # 3.2/3.3): this is NOT a propagated reverse walk -- each stage
            # re-inverts against the stashed forward carrier rather than a
            # carrier propagated from the next stage's reverse. Acceptable
            # near-term (the STM is the only state the production reverse path
            # can source); because the round-trip's exactness comes from the
            # stashing rather than a true chained walk,
            # ``test_mm5m_combine_carrier_roundtrip`` asserts the chained
            # consistency (``cs_rec[t] == carriers[t-1]``) so a future break of
            # the forward ``prev_cs`` threading is still caught.
            # ``combine.reverse`` recovers the three input
            # streams ``(PS_t, WS_t, CS_t)``:
            #
            #   * t > 0: the prior carrier is just ``carriers[t-1]`` (already
            #     threaded), so the per-stage reverse only needs to surface
            #     the recovered slab for ``cs.reverse``'s bookkeeping.
            #   * t == 0 (FINAL reverse stage): the PS-stream output PS_0 is
            #     the pi-ENCODED input content (alpha_ps live only at t=0) --
            #     the slab the downstream ``cs.reverse`` / ``_reverse_perceptual``
            #     (pi.reverse) decode back to the input. Surfacing PS_0 here
            #     closes the input-reconstruction round-trip (e.g. XOR_exact).
            #
            # The combine ALWAYS ran on the forward (the ``reconstruct=perfect``
            # skip-combine mode was retired with the enum, A1), so the reverse
            # is UNCONDITIONALLY the dropped reverse: the structured zero-pad
            # inverts the same square map (exact only on the rank-D subspace
            # that survived). Gated to the plain (non-grammar) parallel path,
            # matching the forward gate. Falls back to ``sub``'s own content
            # when the forward carrier is unavailable (e.g. a reverse not
            # preceded by a body forward in this object).
            # The combine-reverse demuxes ``sub``, recovers the content, and
            # writes it back via ``set_event`` so the downstream ``cs.reverse``
            # reads the canonical event.
            if self.bindingDepth >= 1 and "merge" not in stage:
                try:
                    combine = getattr(stage["cs"], "combine", None)
                    if combine is None:
                        raise RuntimeError("stage cs has no combine")
                    D = int(combine.content_dim)
                    content, band, event = self._combine_demux(sub, D)
                    if event is not None:
                        # 2-stream EXACT inverse (C-10), in-Space per the
                        # processing contract: ``cs.unbind`` reads the
                        # bind carrier RIDING ON the stage's SubSpace
                        # (``_bind_carrier``) and applies ILL^{-1} --
                        # (PS_t, WS_t) exactly, nothing threaded
                        # alongside. The PS stream is the percept leg
                        # (re-fed at every stage), which the downstream
                        # ``cs.reverse`` / ``_reverse_perceptual`` decode
                        # back to the input: reconstruction ends at the
                        # percept store (PS owns reconstruction). The
                        # model-level ``carriers`` handle remains a
                        # fallback for reverses driven from a foreign
                        # subspace.
                        _pure = bool(getattr(sub, "carrier_pure", False))
                        rec = (None if _pure
                               else stage["cs"].unbind(stage["cs"].subspace))
                        if (not _pure and rec is None and carriers is not None
                                and t < len(carriers)
                                and carriers[t] is not None):
                            rec = combine.reverse(carriers[t])
                        if rec is not None:
                            ps_rec, _ws_rec = rec
                            recovered = ps_rec
                            if t == 0:
                                # Phase 7 (painting reverse): the stage-0
                                # WS stream of the unbind IS the conceptual
                                # reconstruction branch. Captured here and
                                # stamped onto the RETURNED sub below (the
                                # per-stage cs.reverse may swap subspace
                                # objects); it rides the SubSpace down to
                                # InputSpace.reverse (processing contract:
                                # data in SubSpaces; reverse stays
                                # single-arg), where the Universal view
                                # paints the background and the Atomic
                                # view is averaged in.
                                _concepts_recon = _ws_rec.detach()
                        else:
                            # No carrier available (a reverse not preceded
                            # by a body forward): surface the sub's own
                            # content for cs.reverse's bookkeeping.
                            recovered = content
                        # Write the recovered slab back, band riding along
                        # unchanged.
                        if band is not None and band.shape[-1] > 0:
                            sub.set_event(
                                torch.cat([recovered, band], dim=-1))
                        else:
                            sub.set_event(recovered)
                except (RuntimeError, AssertionError, ValueError):
                    pass
            if "merge" in stage:
                try:
                    sub = stage["merge"].reverse(sub)
                except (RuntimeError, AssertionError, ValueError):
                    pass
            try:
                sub = stage["cs"].reverse(sub)
            except (RuntimeError, AssertionError, ValueError):
                pass
        if _concepts_recon is not None and sub is not None:
            # Stamp the conceptual reconstruction branch onto the RETURNED
            # sub (the per-stage reverses may have swapped objects); the
            # model reverse() re-stamps it across _reverse_perceptual's
            # handoff so it reaches InputSpace.reverse for the painting.
            object.__setattr__(sub, "_concepts_recon", _concepts_recon)
        return sub

    def _reverse_perceptual(self, sub):
        """Reverse the perceptual boundary (percept space_role → input)."""
        return self.perceptualSpace.reverse(sub)

    def reverse(self, x):
        """Reverse pipeline from the terminal ConceptualSpace state -- i.e.
        GENERATE the surface (a sentence) for an idea.

        This is NOT merely "undo the forward". When there is no reconstruction
        information for an idea -- e.g. an idea placed into STM TOP-DOWN
        (generated or recalled, never perceived) -- we still must produce a
        sentence for it. That is exactly this pass: starting from the idea (the
        terminal C-space_role state), run the reverse pipeline to emit its surface.

        The FIRST steps on that path are the high-level GRAMMATICAL operations
        (``_chart_generate_from_stm`` -> ``_reverse_body``): guess the HEAD of
        the sentence's NP (helped by the activated codebook), determine the VP
        from that head, and recurse down to all the surface words. Only then do
        the lower space_roles (``_reverse_perceptual`` -> ``inputSpace.reverse``)
        render the chosen words back to bytes.

        C3 (spec sec 7): this is the UNCONDITIONAL reconstruction carrier.
        After the ``<reconstruct>`` enum was retired (A1), the symbolic/output
        reverse modes are gone and ``runBatch`` always seeds the reverse pass
        from concepts: the output head may be intentionally lower-dimensional,
        while the terminal C-space_role state still carries the full reversible
        surface needed for reconstruction. (The retired head-seeded primitive
        ``_run_pipeline_rev`` -- which started from ``outputSpace.reverse`` /
        the lower-dim OS output, hence the wrong-size seed -- was removed
        2026-06-07; concepts-seeding is precisely the fix for that size gap.)
        """
        if x is None:
            return None
        self._chart_generate_from_stm(x)
        x = self._reverse_body(x)
        # Phase 7 (painting reverse): carry the conceptual reconstruction
        # branch across the PS handoff (the perceptual reverse may swap
        # subspace objects) so it reaches InputSpace.reverse riding the
        # SubSpace.
        _concepts = getattr(x, "_concepts_recon", None) if x is not None else None
        x = self._reverse_perceptual(x)
        if _concepts is not None and x is not None:
            object.__setattr__(x, "_concepts_recon", _concepts)
        x = self.inputSpace.reverse(x)
        return x



    def _grammar_reverse_ops(self):
        """Declared binary generate hosts that support a dictionary witness."""
        language = self.languageSpace
        result = []
        seen = set()
        for name, operation in zip(language._generate_binary_names,
                                   language._generate_binary_ops):
            host = getattr(operation, 'gl', operation)
            reverse = getattr(host, 'reverse', None)
            parameters = getattr(getattr(reverse, '__code__', None), 'co_varnames', ())
            if name not in seen and 'left_rows' in parameters:
                seen.add(name)
                result.append((name, host))
        return result

    def _reverse_choose_op(self, parent, reverse_ops, basis, word_rows):
        """Reverse chooser (Alec 2026-07-14): the reverse derivation's own
        op selection, with NO forward record. For each candidate grammar
        reverse op, snap-reverse the parent to an operand pair, RE-FOLD it
        forward, and score the ROUND-TRIP fit (cosine to the parent). The op
        whose forward fold best reconstructs the parent is the one that
        explains it — the trace-free analogue of the forward anchor-dot
        chooser. Returns ``((name, host), (x1, x2), fit)`` or ``None``."""
        import torch.nn.functional as _F
        p = parent.reshape(-1)
        d_what = int(p.shape[0])
        best = None
        for name, host in reverse_ops:
            try:
                x1, x2 = host.reverse(
                    parent.unsqueeze(0), basis=basis,
                    left_rows=word_rows, right_rows=word_rows, snap=True)
                a = x1.reshape(-1)[:d_what]
                b = x2.reshape(-1)[:d_what]
                recon = host.compose(
                    a.unsqueeze(0), b.unsqueeze(0)).reshape(-1)[:d_what]
                fit = float(_F.cosine_similarity(
                    recon.detach().unsqueeze(0),
                    p.detach().unsqueeze(0), dim=-1))
            except Exception:
                continue                        # op not applicable here
            if best is None or fit > best[2]:
                best = ((name, host), (x1, x2), fit)
        return best

    def _leaf_distill_loss(self, *, registry=None):
        """Method-1 -> Method-2 distillation (Alec 2026-07-14, snap design
        doc step 3): train the leaf-decoder head to regenerate the EXACT
        per-word leaves (the ReconstructionStack's Method-1 teacher)
        from the collapsed root (``_stm_single_S``). Gradient flows through
        the root into the fold, so the root cannot satisfy this while
        collapsing distinct sentences into one attractor (measured pairwise
        contraction 0.0117 $\\to$ 0.00017 — the root-separability gap).
        Masked MSE over the teacher's non-zero leaf slots; ``None`` when a
        stash is missing or the root carries no graph."""
        S = getattr(self, "_stm_single_S", None)
        trace = self._reconstruction_stack()
        slab = trace.leaves() if trace is not None else None
        if (S is None or slab is None or not torch.is_tensor(S)
                or not torch.is_tensor(slab) or S.dim() != 2
                or slab.dim() != 3 or S.grad_fn is None
                or int(S.shape[0]) != int(slab.shape[0])):
            return None
        _B, N, D = slab.shape
        head = getattr(self, "_leaf_distill_head_module", None)
        if (head is None or head.d_in != int(S.shape[1])
                or head.n_slots != int(N) or head.d_out != int(D)):
            from Layers import LeafDecoderHead
            head = LeafDecoderHead(int(S.shape[1]), int(N), int(D))
            head = head.to(S.device)
            self.add_module("_leaf_distill_head_module", head)
            self._leaf_distill_head_fresh = True
        pred = head(S)                                       # [B, N, D]
        target = slab.detach().to(pred.device)
        mask = (target.abs().sum(-1, keepdim=True) > 0).to(pred.dtype)
        if float(mask.sum()) == 0.0:
            return None
        n_when = int(getattr(getattr(getattr(self, 'inputSpace', None),
                                     'subspace', None), 'nWhen', 0))
        width = D - n_when
        if width < 1:
            raise ValueError('word reconstruction requires content before its time band')
        if registry is not None:
            registry.squared('leaf_distill', pred[..., :width], target[..., :width],
                             mask=mask.bool(), category='reconstruction')
        num = (mask * (pred[..., :width] - target[..., :width]) ** 2).sum()
        return num / (mask.sum() * float(width))


    def _nearest_word(self, node, basis, word_rows):
        """Nearest store word row to ``node`` (``[d_what]``) by cosine, and
        that cosine. The leaf test of the trace-free derivation: a node that
        already IS a store row (cos ~1) is a word, not a composite to
        un-fold further."""
        import torch.nn.functional as _F
        W = basis.getW()
        Wr = W.index_select(0, word_rows.to(W.device))
        sims = _F.cosine_similarity(node.reshape(1, -1), Wr, dim=-1)
        j = int(sims.argmax())
        return Wr[j], float(sims[j])

    def _reverse_derive_words(self, S, d_what, basis, word_rows, reverse_ops):
        """Trace-free reverse derivation (Alec 2026-07-14): un-fold each root
        into word leaves by CHOOSING the reverse op per step
        (``_reverse_choose_op`` — round-trip fit over the grammar's
        ``<generate>`` ops), with NO forward record. The chosen op's snap
        returns store word rows, so a node that snaps to a row (cos ~1) is a
        leaf; the flat/2-word corpus bottoms out in one un-fold. Deeper trees
        recurse (bounded by the STM cap) but the collapsed root cannot yet
        yield separable composite children — gated on root separability
        (step 3). Returns ``[[word_vec, …], …]`` per batch row."""
        B = S.shape[0]
        cap = int(getattr(self.conceptualSpace.stm, "capacity", 8) or 8)
        LEAF = 0.999
        words_per_row = [[] for _ in range(B)]
        for b in range(B):
            leaves, frontier, steps = [], [S[b, :d_what]], 0
            while frontier and len(leaves) < cap and steps < 2 * cap:
                steps += 1
                node = frontier.pop(0)          # FIFO -> left-first reading
                if float(node.abs().sum()) == 0.0:
                    continue
                w, wf = self._nearest_word(node, basis, word_rows)
                if wf > LEAF:
                    leaves.append(w)             # node IS a word: leaf
                    continue
                choice = self._reverse_choose_op(
                    node, reverse_ops, basis, word_rows)
                if choice is None:
                    leaves.append(w)             # no op inverts: snap + stop
                    continue
                (_name, _host), (x1, x2), _fit = choice
                frontier.append(x1.reshape(-1)[:d_what])
                frontier.append(x2.reshape(-1)[:d_what])
            words_per_row[b] = leaves
        return words_per_row

    def _stamp_unfold_where(self, out, d_what, basis, word_rows):
        """Write sequential word offsets into the un-fold output's ``.where``
        band. Each emitted slot is matched to its word row (the recommender
        returns basis rows verbatim); offset = cumulative surface length + 1
        separator, encoded through the CS ``whereEncoding`` (the forward's
        stamp idiom). Slots that are not word rows (sentinels / zeros tail)
        stop the row's stamp — the band stays unwritten there, exactly the
        pre-existing below-noise-floor contract."""
        cs_sub = self.conceptualSpace.subspace
        w_enc = getattr(cs_sub, "whereEncoding", None)
        if w_enc is None or int(getattr(w_enc, "nDim", 0) or 0) <= 0:
            return
        D = int(out.shape[-1])
        idx = [int(i) for i in w_enc.resolve(D)]
        if not idx or idx[0] < d_what or idx[-1] >= D:
            return
        store = getattr(getattr(self, "perceptualSpace", None),
                        "percept_store", None)
        W = basis.getW() if hasattr(basis, "getW") else None
        if store is None or W is None:
            return
        Wr = W.index_select(0, word_rows.to(W.device)).detach()  # [K, d_what]
        B, n = int(out.shape[0]), int(out.shape[1])
        offsets = torch.full((B, n), -1.0, device=out.device)
        for b in range(B):
            cum = 0
            for i in range(n):
                v = out[b, i, :d_what].detach()
                if float(v.abs().sum()) == 0.0:
                    break                        # zeros tail: row done
                d2 = ((Wr - v.unsqueeze(0)) ** 2).sum(dim=-1)
                j = int(d2.argmin())
                if float(d2[j]) > 1e-6:
                    break                        # sentinel / non-row operand
                pid = int(word_rows[j])
                word = store.bytes_for(pid)
                if not word:
                    break
                offsets[b, i] = float(cum)
                cum += len(word) + 1             # word + separator
        mask = offsets >= 0.0
        if not bool(mask.any()):
            return
        stamp = w_enc.encode(offsets.clamp(min=0.0))
        stamp = stamp * mask.unsqueeze(-1).to(stamp.dtype)
        out[..., idx] = stamp.to(out.dtype)





    def _forward_per_stage(self, inputData, in_sub_override=None, *,
                           return_sentence_state=False):
        """IR-only forward via stem/body/head pipeline.

        Shape:
          stem -> ``[B, N, D]`` (InputSpace.forward + PartSpace
                  .forward; no K-axis).
          body -> per-stage CS/WS chain on B-shaped tensors; each
                  WholeSpace output lives on that stage's
                  ``.subspace`` (the per-stage ``_ws_cache`` /
                  ``_cs_cache`` capture lists were retired by Stage
                  1.F of doc/plans/2026-05-26-two-loop-pi-sigma-
                  substrate.md — terminal STM owns the C-space_role idea
                  and ``self.wholeSpaces[*]`` own the per-stage
                  symbolic state).
          head -> ``outputSpace``; result event ``[B, N, predDim]``.

        Within-sentence training is IR-only (BERT-style masked-LM at
        the P-space_role).  Sentence-level AR moved to ``BracketExpectation``
        (ARMA(p, q) over sentence reps).  ``<maskedPrediction>`` and
        the per-cursor K-loop retired 2026-05-14; legacy reverse
        pipeline retired in the same change.
        """
        if isinstance(inputData, torch.Tensor):
            # Device placement is the eager producer's job on the
            # compiled path: runBatch moves inputTensor onto the compute
            # device *before* the traced step (same principle as the
            # Phase-3 lex+embed stem). Calling ``TheDevice.get()``
            # *inside* the trace hands dynamo a ``DeviceHandle`` it
            # cannot proxy ("Failed to convert args/kwargs to proxy")
            # -> hard error under ``fullgraph=True``. Skip it when staged
            # (compiled path; producer already placed it); keep it for
            # eager / uncompiled callers (tests, MPS) where no producer
            # ran -- behaviour there is unchanged.
            if self._staged_in_sub is None:
                inputData = inputData.to(TheDevice.get())

        # Detach per-batch event content carried over from the prior
        # forward to break the autograd graph. Post-Stage-4 of
        # doc/plans/2026-05-21-active-payload-retirement.md the
        # per-batch event lives:
        #   * on ``event.W`` for pure-event (plain Tensor) slots; can
        #     be detached in place via setW.
        #   * reconstructed from prototype + selection for muxed
        #     codebook slots — the Parameter handles grad-tracking
        #     directly; no cached event to detach.
        # Skip the detach for codebook-bearing slots (``getW`` returns
        # the 2-D Parameter, which detach would clobber).
        for sp in (self.perceptualSpace, self.conceptualSpace,
                   self.wholeSpace):
            if sp is None:
                continue
            sub = sp.subspace
            if sub is None or sub.event is None:
                continue
            if getattr(sub, "muxed", False):
                # Per-batch event reconstructs from prototype +
                # selection; nothing to detach on ``event`` itself.
                continue
            w = sub.event.getW()
            # Host housekeeping only: under export the traced detach of a
            # stem-parked host event lifts a DEAD constant (StopIteration
            # in torch.export's lift_constants_pass), so skip it there.
            if (w is not None and torch.is_tensor(w)
                    and not isinstance(w, nn.Parameter)
                    and w.ndim >= 3 and w.requires_grad
                    and not torch.compiler.is_exporting()):
                sub.event.setW(w.detach())

        # Per-run scratch.
        self.symbol_states = []
        self._unified_j_iterations = 0

        # Task D1: with an export-driven ``in_sub_override`` there is no
        # ``inputData`` tensor (it is None); derive B/device from the
        # override's materialized staged slab so the symbolic seed batches
        # correctly. Otherwise read them off ``inputData`` (unchanged).
        if isinstance(inputData, torch.Tensor):
            B = inputData.shape[0]
            device = inputData.device
        elif in_sub_override is not None:
            _ov_ev = in_sub_override.materialize()
            if _ov_ev is not None and torch.is_tensor(_ov_ev):
                B = int(_ov_ev.shape[0])
                device = _ov_ev.device
            else:
                B = 1
                device = TheDevice.get()
        else:
            # Complete MPS W-loop callables deliberately receive no raw
            # lexer tensor: that surface has already been staged eagerly and
            # its varying byte extent must not become a Dynamo guard.  Recover
            # the true batch/device from the staged carrier instead of
            # assuming B=1, so the boundary remains correct for configured
            # microbatches other than the current default.
            _staged_ev = (
                self._staged_in_sub.materialize()
                if self._staged_in_sub is not None else None)
            if torch.is_tensor(_staged_ev):
                B = int(_staged_ev.shape[0])
                device = _staged_ev.device
            else:
                B = 1
                device = TheDevice.get()
        self.symbolic_state = self.wholeSpace.empty_state(batch=B).to(device)

        # Inter-sentence prior (read-only at forward time; the actual
        # ARMA observe + loss happen in ``runBatch`` after the body). The
        # full-sentence W loop receives its actual prior through the eager
        # closing-time expectation pair.  The older ARMA snapshot below
        # has no consumer there, so skip its Python tuple reader: cold
        # ``(None, None)`` followed by a tensor tuple would otherwise guard
        # and recompile the complete graph on sentence two.
        self._predicted_snapshot = None
        self._predicted_confidence = None
        discourse_for_prime = (
            self.symbolSpace.expectation
            if self.symbolSpace is not None else None)
        if (discourse_for_prime is not None
                and not getattr(self, "_compiled_word_loop_fullgraph", False)):
            d_pred, d_conf = discourse_for_prime.predict()
            self._predicted_snapshot = d_pred
            self._predicted_confidence = d_conf

        # Stem: InputSpace forward only (``[B, N, D]``). PartSpace
        # now runs inside the recurrent cell (it takes the C→P feedback
        # as an explicit arg), so it is no longer a once-per-sentence
        # stem step.
        #
        # Phase 3: when runBatch staged the lex+embed eagerly (compiled
        # path), read the pre-populated persistent subspace instead of
        # lexing here -- keeps host tokenisation/OOV out of the traced
        # region (graph breaks #1-4). Read-only (no attr write in the
        # traced path). Eager/uncompiled callers don't stage, so this
        # falls back to inline lexing -- behaviour unchanged.
        #
        # Task D1 (torch.export tensor core): ``forward_core`` drives the
        # body from a SubSpace whose materialized event IS the export
        # ARGUMENT (not ``self._staged_in_sub``). When ``in_sub_override``
        # is supplied we read it instead, so the traced tensor pipeline
        # roots in the passed-in staged tensor -- the normal forward keeps
        # reading the parked ``self._staged_in_sub`` (no regression).
        if in_sub_override is not None:
            in_sub = in_sub_override
        else:
            in_sub = self._staged_in_sub
        if in_sub is None:
            in_sub = self._lex_embed_stem(inputData)
        if in_sub is None or in_sub.is_empty():
            # Phase 1.5: the five inputs/percepts/concepts/symbols/outputs
            # back-ref aliases were subsumed -- every reader now goes
            # through the owning Space directly
            # (``self.perceptualSpace.subspace`` etc.), so there is no
            # alias to (re)stamp here. Empty-input early return unchanged.
            if return_sentence_state:
                raise RuntimeError(
                    "compiled sentence forward received an empty staged input")
            return None, None, None, None

        # Body: recurrent cell over T stages on B rows. PartSpace
        # runs per pass with the C→P feedback; the IR masked-LM mask is
        # applied once inside the cell on pass 0's perceptual event
        # (``_ir_pre_mask_input`` / ``_ir_mask_positions`` for
        # ``runBatch``). Chart-at-C reads ``ConceptualSpace.stm``.
        body_result = self._forward_body(
            in_sub, return_sentence_state=return_sentence_state)
        if return_sentence_state:
            body_sub, sentence_state = body_result
        else:
            body_sub = body_result
            sentence_state = None

        _restore_ev = None
        # Head: outputSpace -> ``[B, N, predDim]``. The restore is in a finally
        # so the pre-consume carrier is ALWAYS put back for the reverse /
        # reconstruction, even if the head raises.
        try:
            head_sub = (self._forward_head(body_sub, sentence_state=sentence_state)
                        if sentence_state is not None else self._forward_head(body_sub))
        finally:
            if _restore_ev is not None:
                body_sub.set_event(_restore_ev)
        pred = head_sub.materialize() if head_sub is not None else None
        if pred is not None and not self.outputSpace.concept_ids:
            pred = self.normalizer.denormalize(pred, which="output")

        # WholeSpace owns properties only. The public symbolic state is the
        # paired activation of concept identities, published by SymbolSpace.
        sym_sub = self._publish_reading_symbols(body_sub)
        if sym_sub is None:
            sym_sub = self.symbolSpace.forward_concept_to_symbol(body_sub)
        object.__setattr__(self, '_reading_symbol_result', sym_sub)
        sym_vectors = sym_sub.materialize() if sym_sub is not None else None
        self.symbol_states = [sym_vectors] if sym_vectors is not None else []
        self._unified_j_iterations = min(self.bindingDepth, len(self.symbol_states))

        # forwardInput contract for runBatch: [B, N, D] embedded input.
        input_state = self.inputSpace._ar_embedded
        if input_state is None:
            input_state = self.inputSpace.subspace.materialize()
        if input_state is None:
            input_state = self.perceptualSpace._embedded_input

        # Inter-sentence snapshot: pass the S-space_role event to runBatch,
        # which calls ``BracketExpectation.observe`` to capture the
        # sentence rep, compute the ARMA loss, and update the rings.
        # ``_current_discourse_s`` carries the unmodified S-space_role event;
        # the layer's ``_pool_sentence_rep`` does the flattening.
        self._current_discourse_s = (
            sym_vectors.detach() if sym_vectors is not None else None)

        self._universality_score = None

        # Downward head emission (S -> C).
        self._predicted_head = None
        try:
            gen_on = bool(TheXMLConfig.get('SymbolSpace.downwardGeneration'))
        except KeyError:
            gen_on = False
        if (gen_on and self.symbolSpace is not None
                and sym_vectors is not None and sym_vectors.ndim >= 3):
            final_state = sym_vectors[:, 0, :]
            codebook_space = (self.perceptualSpace
                              if self.inputSpace.model_type == "embedding"
                              else self.inputSpace)
            head_result = self.symbolSpace.reconstruct(final_state, codebook_space)
            self._predicted_head = head_result['heads']

        # Optional syntax tree dump.
        if self._write_syntax:
            try:
                self.write_syntax_tree(self._syntax_out_path)
            except Exception as e:
                import sys
                print(f"[writeSyntax] error: {e}", file=sys.stderr)

        public = (input_state, sym_vectors, pred, None)
        if return_sentence_state:
            return (*public, *sentence_state)
        return public


    def write_syntax_tree(self, path):
        """Append an XML syntax tree per batch row to ``path``.

        Reads the chart's derivation trace
        (``Chart._derivation_trace``, a list-per-batch of
        ``(gid, i, k, j, A)`` tuples — rule global id, left edge, split
        point, right edge, merged-cell category index) and the
        symbolic codebook's per-atom category tags
        (``WholeSpace.subspace.what.category_ids``).  Decodes input
        atoms to surface tokens via ``InputSpace.wv.index_to_key``.

        Format (one ``<forward>`` element per call, with a ``<batch>``
        per row).  Category names (``cat=...``), rule canonicals
        (``rule=...``), and POS tags (``pos=...``) come straight from
        the live grammar's ``Grammar.categories`` /
        ``RuleDef.canonical``; the dumper has no built-in category
        vocabulary.  Example output for an XOR_grammar parse where the
        only non-terminal is ``S``::

            <forward tick="42">
              <batch n="0">
                <node cat="S" rule="S=conjunction(S,S)" i="0" j="2">
                  <leaf token="1" pos="S" i="0"/>
                  <leaf token="1" pos="S" i="1"/>
                </node>
                <rules>1</rules>
              </batch>
            </forward>

        A grammar declaring richer typed categories (e.g.
        ``NP = intersection(ADJ, N)``) produces trees with those
        category names instead.

        The output file is a stream of ``<forward>`` fragments — one
        per call.  Wrap with a ``<syntaxLog>`` root element (or use a
        streaming parser) if a single fully-valid XML document is
        needed.

        Side effects: appends to ``path`` (creating parent dirs as
        needed). The first call within a process truncates ``path``
        so old content from prior runs is cleared.
        """
        import os
        import xml.etree.ElementTree as ET
        symbolSpace = self.symbolSpace
        if symbolSpace is None:
            return
        # Chart's per-leaf POS category names and per-leaf atom_idx
        # aren't populated by the signal router yet; until they are,
        # this branch emits ``<noTrace/>``.
        chart = None
        traces = None
        cat_names = ['?']

        # Resolve atom_idx -> surface token via InputSpace.wv (word
        # vectors); fall back to a placeholder when wv isn't wired.
        # `pos` here is a position within the parsed sentence (0..N-1),
        # NOT a codebook index — surface-decoding requires looking up
        # the actual codebook row of the atom at that position.
        index_to_key = None
        try:
            wv = getattr(self.inputSpace, 'wv', None)
            if wv is not None:
                index_to_key = getattr(wv, 'index_to_key', None)
        except Exception:
            index_to_key = None

        # Per-leaf atom indices: prefer the chart's stashed nearest-match
        # row from `_apply_codebook_pos_seed`. Shape [B*N], may be None.
        # Reshape to [B, N] so we can look up by (batch, position).
        per_leaf_atom = None
        try:
            stash = getattr(chart, '_last_seed_atom_idx', None)
            if stash is not None and traces is not None:
                B_t = len(traces)
                if B_t > 0 and stash.numel() % B_t == 0:
                    N_t = stash.numel() // B_t
                    per_leaf_atom = stash.reshape(B_t, N_t).cpu()
        except Exception:
            per_leaf_atom = None

        # Direct surface-form recovery: re-tokenize the last batch's
        # input strings (stored on the InputSpace as `_last_input_texts`
        # if available, otherwise pulled from TheData splits when the
        # input subspace exposes its byte buffer). Falls through to the
        # atom-index path when no source text is reachable.
        per_leaf_text = None
        try:
            sym_sub = self.wholeSpace.subspace
            in_sub = self.inputSpace.subspace
            # Spec doc/specs/2026-05-21-subspace-slot-architecture.md
            # Reader API: ``materialize(mode='what')`` is the per-batch
            # what-content read. InputSpace's ``.what`` is a plain
            # ``Tensor`` (no Parameter), so this returns the same
            # ``[B, N, nWhat]`` slab as the legacy ``what.getW()``;
            # the migrated call is contract-stable AND survives the
            # Stage-4 strict assertion on Parameter-bearing slots.
            wbuf = (in_sub.materialize(mode="what")
                    if in_sub is not None
                    and hasattr(in_sub, "materialize") else None)
            if wbuf is not None and torch.is_tensor(wbuf) and wbuf.dim() == 3:
                B_t = wbuf.shape[0]
                from util import parse as _parse
                texts_per_batch = []
                for bi in range(B_t):
                    # what_buf row is [N, nWhat] of UTF-8 bytes
                    # (null-terminated). Decode each token slot.
                    row = wbuf[bi]
                    toks = []
                    for sj in range(row.shape[0]):
                        bs = row[sj].to(torch.uint8).tolist()
                        # Strip trailing nulls; everything else is the token.
                        while bs and bs[-1] == 0:
                            bs.pop()
                        if bs:
                            try:
                                toks.append(bytes(bs).decode('utf-8', errors='replace'))
                            except Exception:
                                toks.append(f"slot_{sj}")
                        else:
                            toks.append("")
                    texts_per_batch.append(toks)
                per_leaf_text = texts_per_batch
        except Exception:
            per_leaf_text = None

        def _decode_token(b, pos):
            """Return the surface text for batch row ``b`` at slot ``pos``.

            Prefers the decoded UTF-8 text from ``per_leaf_text``, falls
            back to the codebook key via ``per_leaf_atom`` / index_to_key,
            and finally to a ``slot_<pos>`` placeholder.
            """
            if (per_leaf_text is not None and b < len(per_leaf_text)
                    and pos < len(per_leaf_text[b])
                    and per_leaf_text[b][pos]):
                return per_leaf_text[b][pos]
            atom_idx = None
            if per_leaf_atom is not None and b < per_leaf_atom.shape[0] \
                    and pos < per_leaf_atom.shape[1]:
                atom_idx = int(per_leaf_atom[b, pos].item())
            if (index_to_key is not None and atom_idx is not None
                    and 0 <= atom_idx < len(index_to_key)):
                return str(index_to_key[atom_idx])
            if atom_idx is not None:
                return f"atom_{atom_idx}"
            return f"slot_{pos}"

        # POS lookup: prefer the chart's per-leaf POS distribution
        # (chart._chart_pos[b, i, i+1, :] argmax) over the stale
        # codebook category_ids buffer. Fall back to category_ids when
        # chart_pos isn't available.
        chart_pos = None
        try:
            chart_pos = getattr(chart, '_chart_pos', None)
        except Exception:
            chart_pos = None

        cat_ids = None
        try:
            sym_sub = self.wholeSpace.subspace
            what = getattr(sym_sub, 'what', None)
            cat_ids = getattr(what, 'category_ids', None) if what else None
        except Exception:
            cat_ids = None

        def _pos_at(b, pos):
            """Return the POS tag name for batch row ``b`` at slot ``pos``.

            Prefers the chart's per-leaf POS distribution
            (``chart_pos[b, pos, pos+1, :].argmax``); falls back to the
            possibly-stale codebook ``category_ids`` and finally ``'?'``.
            """
            # Prefer chart_pos[b, pos, pos+1, :].argmax() — what the
            # chart actually believed at this leaf during this parse.
            if chart_pos is not None:
                try:
                    if (b < chart_pos.shape[0]
                            and pos + 1 < chart_pos.shape[1]):
                        cid = int(chart_pos[b, pos, pos + 1, :].argmax().item())
                        if 0 <= cid < len(cat_names):
                            return cat_names[cid]
                except Exception:
                    pass
            # Fallback: stale codebook tag.
            if cat_ids is not None and 0 <= pos < cat_ids.shape[0]:
                cid = int(cat_ids[pos].item())
                if 0 <= cid < len(cat_names):
                    return cat_names[cid]
            return '?'

        os.makedirs(os.path.dirname(path) or '.', exist_ok=True)
        mode = 'w' if not getattr(self, '_syntax_truncated', False) else 'a'
        self._syntax_truncated = True

        try:
            from Language import TheGrammar
        except ImportError:
            TheGrammar = None

        def _entry_str(entry):
            gid, i, k, j, A = entry
            try:
                canon = TheGrammar.rules[gid].canonical if TheGrammar else str(gid)
            except Exception:
                canon = str(gid)
            cat = (cat_names[int(A)] if 0 <= int(A) < len(cat_names)
                   else '?')
            return cat, canon

        def _rule_canon(rule_id):
            try:
                if TheGrammar:
                    return TheGrammar.rules[int(rule_id)].canonical
                return str(rule_id)
            except Exception:
                return str(rule_id)

        forward_el = ET.Element(
            'forward',
            {'tick': str(getattr(self, '_current_tick', '?'))})
        if traces is None:
            ET.SubElement(forward_el, 'noTrace')
        else:
            for b, trace in enumerate(traces):
                batch_el = ET.SubElement(
                    forward_el, 'batch', {'n': str(b)})
                if not trace:
                    ET.SubElement(batch_el, 'noTrace')
                    continue
                span_to_entry = {}
                for entry in trace:
                    _, i_e, _, j_e, _ = entry
                    span_to_entry.setdefault((i_e, j_e), entry)

                def _build(span, parent_el, _b=b):
                    """Recursively emit XML nodes/leaves for chart ``span``.

                    Looks up the chart entry at ``(si, sj)``; emits a
                    ``<node>`` element with category + rule then recurses
                    into the left/right children. Spans without an entry
                    become a run of ``<leaf>`` elements.
                    """
                    entry = span_to_entry.get(span)
                    si, sj = span
                    if entry is None:
                        for pos in range(si, sj):
                            ET.SubElement(parent_el, 'leaf', {
                                'token': _decode_token(_b, pos),
                                'pos': _pos_at(_b, pos),
                                'i': str(pos),
                            })
                        return
                    cat, canon = _entry_str(entry)
                    _, _, k_e, _, _ = entry
                    node_el = ET.SubElement(parent_el, 'node', {
                        'cat': cat,
                        'rule': canon,
                        'i': str(si),
                        'j': str(sj),
                    })
                    _build((si, k_e), node_el)
                    _build((k_e, sj), node_el)

                root = trace[0]
                _, root_i, _, root_j, _ = root
                _build((root_i, root_j), batch_el)
                rules_el = ET.SubElement(batch_el, 'rules')
                rules_el.text = ",".join(str(int(e[0])) for e in trace)

        # Pretty-print and write the fragment.
        try:
            ET.indent(forward_el, space="  ")
        except AttributeError:
            # ET.indent landed in Python 3.9; older versions get
            # the unindented form.
            pass
        with open(path, mode, encoding='utf-8') as fh:
            fh.write(ET.tostring(forward_el, encoding='unicode'))
            fh.write("\n")


    # -- Intent priming (GrammarOpsPass §5; author 2026-06-11) ---------

    def set_intent(self, intent, *, gain=1.0):
        """ONE current-intent code priming BOTH codebook towers
        simultaneously: primed RECOGNITION on the PS/extent tower
        alongside primed RETRIEVAL on the WS/intent tower, weighting
        the analytical and synthetic superpositions toward the same
        context. Priming is attention over symbols — codebook focus
        only, never rule dispatch.

        The intent is the product of the parallel parse (the §6c
        pump-zero gist); it is sentence-scoped and refreshed on
        preemption. ``intent=None`` clears the tower boosts (the
        byte-identical off state); the taxonomy buffer's merged boost
        dissipates through its own sentence-scoped decay/reset.

        Returns the WS-tower boosts (or ``None``).
        """
        ps = getattr(self, 'perceptualSpace', None)
        ws = getattr(self, 'wholeSpace', None)
        if ps is not None and hasattr(ps, 'set_intent'):
            ps.set_intent(intent, gain=gain)
        ws_boosts = None
        if ws is not None and hasattr(ws, 'set_intent'):
            ws_boosts = ws.set_intent(intent, gain=gain)
        # WS retrieval plumbing: merge into the word-space taxonomy
        # priming buffer (consumed by the inverse recommender through
        # priming_kwargs_for_slots). Best-effort and dark: no taxonomy
        # or no buffer => recognition priming alone.
        if ws_boosts is not None:
            tax = getattr(getattr(self, 'symbolSpace', None),
                          'taxonomy', None)
            if tax is not None and hasattr(tax, 'prime_with_weights'):
                try:
                    tax.prime_with_weights(ws_boosts)
                except Exception:
                    pass
        return ws_boosts

    # -- Bidirectional Reasoning Loop (Phase 3) ------------------------

    @torch.no_grad()

    def reason(self, givens, target=None, direction='forward', max_steps=8):
        """Bidirectional reasoning loop.

        Forward (givens -> conclusion):
            Encode givens, extrapolate new truths, check isTrue(target)
            at each step. Stop when target DoT exceeds threshold or
            max_steps reached.

        Reverse (target -> grounding):
            Encode target, ground() to find minimal basis, extrapolate
            if insufficient.

        Args:
            givens: tensor or list of tensors to encode as premises.
            target: optional target activation to prove/ground.
            direction: 'forward' or 'reverse'.
            max_steps: maximum reasoning steps.

        Returns:
            dict with 'proved' (bool), 'confidence' (float),
            'steps' (int), 'trace' (list of step results).
        """
        truth_layer = self._get_truth_layer()
        if truth_layer is None:
            return {'proved': False, 'confidence': 0.0,
                    'steps': 0, 'trace': []}

        trace = []

        if direction == 'forward':
            basis = self._get_basis()
            # Encode givens into TruthSet
            if isinstance(givens, (list, tuple)):
                for g in givens:
                    if g.norm() > 1e-6:
                        truth_layer.record(g.detach(), degree=1.0, basis=basis)
            elif givens.norm() > 1e-6:
                truth_layer.record(givens.detach(), degree=1.0, basis=basis)

            for step in range(max_steps):
                lum_before = float(self.Luminosity(truth_layer=truth_layer))

                # Extrapolate new truths
                result = self.extrapolate(max_new=16,
                                           attenuation=0.8 ** (step + 1))
                trace.append({
                    'step': step,
                    'added': len(result['added']),
                    'rejected': len(result['rejected']),
                    'luminosity': lum_before,
                })

                # Check target if provided
                if target is not None:
                    dot = self.isTrue(target)
                    trace[-1]['target_dot'] = dot
                    if abs(dot) > 0.5:
                        return {'proved': True, 'confidence': dot,
                                'steps': step + 1, 'trace': trace}

                # Stop if no progress
                if len(result['added']) == 0:
                    break

            confidence = self.isTrue(target) if target is not None else 0.0
            return {'proved': abs(confidence) > 0.5,
                    'confidence': confidence,
                    'steps': len(trace), 'trace': trace}

        else:  # reverse
            if target is None:
                return {'proved': False, 'confidence': 0.0,
                        'steps': 0, 'trace': []}

            for step in range(max_steps):
                result = self.ground(target)
                trace.append({
                    'step': step,
                    'grounded': result['grounded'],
                    'basis_size': len(result['basis']),
                    'confidence': result['confidence'],
                })

                if result['grounded']:
                    return {'proved': True,
                            'confidence': result['confidence'],
                            'steps': step + 1, 'trace': trace}

                # Extrapolate and retry
                ext = self.extrapolate(max_new=16)
                if len(ext['added']) == 0:
                    break

            return {'proved': False, 'confidence': 0.0,
                    'steps': len(trace), 'trace': trace}

TheBasicModel = BasicModel()

class ModelFactory:
    """Create, train, and evaluate models from an XML config file.

    Dispatches to the right model class based on <data><dataType>:
      - dataType=embedding -> BasicModel (embedding/language model path)
      - dataType=numeric   -> BasicModel (dense-slab path; e.g. MNIST)
      - Otherwise           -> SimpleModel parameterized by:
            ergodic, certainty, codebook, normed, reverse, invert
    """

    @staticmethod
    def model_name(ergodic, certainty, codebook, normed=False, reverse=False, invert=False):
        """Generate a human-readable model name from its flags.

        Returns ``"SimpleModel"`` when no flags are set; otherwise
        concatenates the matching flag names with ``" + "``. Reverse /
        invert are mutually exclusive in the rendered name (invert wins).
        """
        if not ergodic and not certainty and not codebook:
            return "SimpleModel"
        parts = []
        if ergodic:
            parts.append("Ergodic")
        if certainty:
            parts.append("Certainty")
        if codebook:
            parts.append("Codebook")
        if normed:
            parts.append("Normed")
        if invert:
            parts.append("Invertible")
        elif reverse:
            parts.append("Reversible")
        return " + ".join(parts) if parts else "SimpleModel"

    @staticmethod
    def get_space_param(cfg, space_name, key):
        """Look up key in space section, fall back to architecture section.

        Resolution order: cfg[space_name][key] -> cfg["architecture"][key]
        All parameters must be in model.xml; raises KeyError if missing.
        """
        space = cfg.get(space_name, {})
        if key in space:
            return space[key]
        arch = cfg.get("architecture", {})
        if key in arch:
            return arch[key]
        raise KeyError(f"Required parameter '{key}' not found in <{space_name}> or <architecture>")

    @staticmethod
    def validate_config(cfg):
        """Check merged config for known inconsistencies and raise on error.

        Called after defaults have been merged so all keys are present.
        Uses get_space_param() to read from space-scoped sections.
        """
        gsp = ModelFactory.get_space_param
        arch = cfg.get("architecture", {})
        errors = []
        # Clear any requirements left over from a previous validate_config
        # call (e.g. one that bailed via ``errors`` before reaching
        # ``TheXMLConfig.validate()``). Otherwise stale ``require()``
        # closures from one test leak into the next.
        TheXMLConfig._requirements.clear()

        # The old ``hasAttention``-vs-``nInputDim``/``flatten`` reshape guard
        # (and its ``_has_reshape`` helper) was retired together with the
        # ``QKVAttentionLayer`` enlistment in PartSpace/ConceptualSpace
        # (plan 2026-06-06-symbolic-heat-retrieval.md §Handoff addendum). It
        # only protected the constraint that transformer self-attention needs
        # 3D multi-vector input; ``<attention>`` is now a symbolic-retrieval
        # mode (not tensor self-attention), so ``hasAttention=True`` together
        # with a reshape/flatten is no longer an error.

        # ``<maskedPrediction>`` retired 2026-05-14: within-sentence
        # training is IR-only and there's no ARIR mode to validate.
        # ``<reconstruct>`` enum retired (A1: schema + ``reconstructEnum``
        # removed). C3 (spec sec 7): reconstruction is unconditionally
        # concepts-seeded in ``runBatch`` -- there is no mode to validate.

        def _resolve_dim(space_name, prev_dim):
            try:
                raw = gsp(cfg, space_name, "nDim")
            except KeyError:
                return prev_dim
            return prev_dim if raw == 0 else raw

        def _resolve_count(space_name, prev_count):
            try:
                raw = gsp(cfg, space_name, "nOutput")
            except KeyError:
                return prev_count
            return prev_count if raw == 0 else raw

        # Aligned binding uses ConceptualSpace's concept-reference inventory.
        # WholeSpace.nVectors is an independent upstream property inventory;
        # live CS/WS slot counts are separate geometry as well.
        if str(arch.get("conceptBinding", "mixing")).strip().lower() == "aligned":
            try:
                _cs_codes = int(gsp(cfg, "ConceptualSpace", "nVectors"))
                try:
                    _cs_active = int(gsp(
                        cfg, "ConceptualSpace", "activeVectors"))
                except KeyError:
                    _cs_active = _cs_codes
                if not (0 < _cs_active <= _cs_codes):
                    errors.append(
                        "ConceptualSpace.activeVectors must be positive and "
                        f"no larger than its nVectors; got active={_cs_active}, "
                        f"capacity={_cs_codes}")
            except (KeyError, TypeError, ValueError):
                errors.append(
                    "aligned binding requires explicit positive nVectors in "
                    "ConceptualSpace")

        from architecture import canonical_shape as _cshape
        input_dim = _resolve_dim("InputSpace", 1)
        percept_dim = _resolve_dim("PartSpace", input_dim)
        concept_dim = _resolve_dim("ConceptualSpace", percept_dim)
        # 2026-06-06 uniform-band convention: every space_role carries the same
        # (nWhere, nWhen) band, so nDim = nWhat + band uniformly. An omitted WS
        # width still inherits for legacy configs; canonical serialObjectMeta
        # sets the native WS property width explicitly because WS is a peer,
        # not a downstream copy of CS.
        symbol_dim = _resolve_dim("WholeSpace", concept_dim)

        # Bivector / projection configs let ConceptualSpace output a
        # narrower activation via ``<nOutputDim>``. Compare nWhat-to-nWhat
        # across CS and WS (subtract each space_role's own band).
        try:
            cs_out_dim = int(gsp(cfg, "ConceptualSpace", "nOutputDim"))
        except KeyError:
            cs_out_dim = 0
        _cs_band = sum(_cshape("ConceptualSpace"))
        _ws_band = sum(_cshape("WholeSpace"))
        _cs_event = cs_out_dim if cs_out_dim > 0 else concept_dim
        effective_concept_dim = _cs_event - _cs_band          # CS nWhat
        symbol_nwhat = symbol_dim - _ws_band                  # WS nWhat

        # WholeSpace owns no legacy C->S width-changing bridge. Parallel legacy
        # configurations that treat WS as a pass-through still require equal
        # widths; the serial peer architecture below does not.
        #
        # Skip only the explicit ``passthrough`` bypass mode. The CS->WS
        # dimensional pass-through (WS owns no Sigma) is real for both the
        # simple and embedding pipelines -- ``test_symbol_dim_must_match_
        # concept_dim`` exercises it in default/simple mode -- so this is
        # NOT gated as narrowly as the embedding-only flat-slab invariant
        # below. ``passthrough`` carries arbitrary placeholder per-space
        # <nDim> (e.g. the config-scoping nOutput-reading fixture, all
        # nDim=1) and intentionally bypasses dimensional validation; the
        # "6+2+2" band subtraction would otherwise drive its CS content
        # negative and trip this check spuriously.
        # dimensional-governance (doc/specs/2026-06-05-dimensional-
        # governance.md sec.4/sec.6): SERIAL mode treats WS as an independent
        # native-width property tower whose sparse codebook activation enters
        # CS at conceptual width. Therefore ``symbol_dim == concept_dim`` is
        # relaxed for serial configs. Parallel legacy configs (square Pi/Sigma
        # over the constant slab) still require the pass-through match.
        _ws_fold_bridged = int(arch.get('conceptLayers',1)) > 1
        # This remains only a legacy PASS-THROUGH assumption. An explicit
        # nInputDim != nOutputDim likewise says WS's recurrent input and native
        # peer output are distinct interfaces, so output-width equality with
        # CS must not be imposed.
        def _ws_dim(key, fallback):
            try:
                v = int(gsp(cfg, "WholeSpace", key))
                return v if v > 0 else int(fallback)
            except (KeyError, TypeError, ValueError):
                return int(fallback)
        _ws_reshapes = (_ws_dim("nInputDim", symbol_dim)
                        != _ws_dim("nOutputDim", symbol_dim))
        # The data space_role (was architecture-level <modelType>) now lives under
        # <data> as <dataType> (embedding | numeric). The flat-slab
        # WS.nWhat==CS.nWhat invariant below is embedding-only: the numeric
        # (dense-slab) path carries no lexicon, so it may re-dimension across
        # space_roles (e.g. MNIST IS=784 -> CS=20). Read from the PASSED cfg (this
        # validator runs on a merged dict that may not be the global config),
        # canonical <data><dataType> first then an architecture-level dataType
        # fallback (dict-based test overrides set it there).
        _data_sec = arch.get("data") if isinstance(arch.get("data"), dict) else {}
        data_type = str(_data_sec.get("dataType")
                        or arch.get("dataType") or "numeric").strip().lower()
        is_embedding_mode = (data_type == "embedding")
        if (is_embedding_mode
                and not _ws_fold_bridged and not _ws_reshapes):
            # A concept is one opaque code the width of the whole WholeSpace
            # event (its coordinates included): the concept width equals the
            # WholeSpace event width, not its band-stripped content.
            TheXMLConfig.require(
                lambda cfg, _c=effective_concept_dim, _s=symbol_dim: _c == _s,
                f"WholeSpace requires WS event width == CS width "
                f"(got CS width={effective_concept_dim}, "
                f"WS event width={symbol_dim}). Fix: set <WholeSpace><nDim> "
                f"to match <ConceptualSpace><nOutputDim> if present, else "
                f"<ConceptualSpace><nDim>."
            )

        # ---- Concept-activation boundary ----------------------------
        # Stage 1.D refactor (doc/plans/2026-05-26-two-loop-pi-sigma-
        # substrate.md): legacy PS->CS tensor handoffs require equal flat
        # content slabs (nOutput * content width). The canonical aligned
        # serial-word architecture has a different boundary: PS, WS, and SS
        # remain independent peers, and each source's sparse sigma/codebook
        # activation reads a conceptual-width row before CS. Thus CS receives
        # conceptual-width events and performs no feature-width conversion.
        #
        # Embedding-mode only: the numeric (dense-slab) path doesn't carry a
        # lexicon, so the "PS per-word is CS-space" rationale doesn't apply --
        # the slab can re-dimension across space_roles (e.g. MNIST IS=784 pixels,
        # CS=20 features). The invariant fires only when
        # ``<data><dataType>embedding`` (``is_embedding_mode``, resolved above).

        def _effective_out_dim(space_name, fallback_dim):
            """Return nOutputDim if set, else nDim, else the chained
            ``fallback_dim`` from the previous space_role."""
            try:
                raw = gsp(cfg, space_name, "nOutputDim")
                if raw and int(raw) > 0:
                    return int(raw)
            except KeyError:
                pass
            try:
                raw = gsp(cfg, space_name, "nDim")
                if raw and int(raw) > 0:
                    return int(raw)
            except KeyError:
                pass
            return int(fallback_dim)

        def _effective_out_count(space_name, fallback_count):
            try:
                raw = gsp(cfg, space_name, "nOutput")
                if raw and int(raw) > 0:
                    return int(raw)
            except KeyError:
                pass
            return int(fallback_count)

        # "6+2+2": nDim/nOutputDim are EVENT widths; chain on the event width
        # but the flat-slab reshape invariant holds on the CONTENT slab
        # (nDim - band) -- the .where/.when band is per-position overhead, not
        # part of the reshaped content. Subtract each space_role's band for the slab.
        from architecture import canonical_shape as _cshape
        is_dim_e = _effective_out_dim("InputSpace", input_dim)
        is_n = _effective_out_count("InputSpace", 1)
        ps_dim_e = _effective_out_dim("PartSpace", is_dim_e)
        ps_n = _effective_out_count("PartSpace", is_n)
        cs_dim_e = _effective_out_dim("ConceptualSpace", ps_dim_e)
        cs_n = _effective_out_count("ConceptualSpace", ps_n)
        _is_band_shape = tuple(_cshape("InputSpace"))
        _ps_band_shape = tuple(_cshape("PartSpace"))
        _cs_band_shape = tuple(_cshape("ConceptualSpace"))
        is_dim = is_dim_e - sum(_is_band_shape)
        ps_dim = ps_dim_e - sum(_ps_band_shape)
        cs_dim = cs_dim_e - sum(_cs_band_shape)

        is_slab = is_n * is_dim
        # A concept absorbs the whole percept event (its coordinates too):
        # with no conceptual band, the percept side of the slab invariant
        # is the full percept event width, not its band-stripped content.
        ps_slab = ps_n * (ps_dim if sum(_cs_band_shape) > 0 else ps_dim_e)
        cs_slab = cs_n * cs_dim
        # Handoff-consistency (dimensional-governance, 2026-06-06): IS is the
        # raw input and may be BIGGER than perception -- PS scopes it down via
        # chunking/embedding ("more input than output"), so the char input is
        # NOT constrained to the PS/CS content slab. Historically PS->CS then
        # had to be a pure reshape. The one narrow exception is the canonical
        # aligned serial-word model: its native PS/WS peers share locations
        # and width, then each sparse sigma/codebook activation reads the
        # high-dimensional concept row. Mixing/parallel/legacy paths retain
        # the flat-slab equality.
        def _config_true(raw):
            if isinstance(raw, bool):
                return raw
            return str(raw or "").strip().lower() in (
                "true", "1", "yes", "on")

        _serial_word_major = (
            (int(arch.get('conceptLayers', 2)) > 1 or _config_true(arch.get('ltmConsolidation', False)))
            and _config_true(arch.get("serialObjectMeta", False)))
        _aligned_serial_word = (
            _serial_word_major
            and str(arch.get("conceptBinding", "mixing")).strip().lower()
            == "aligned")
        try:
            _cs_input_dim_raw = int(gsp(
                cfg, "ConceptualSpace", "nInputDim"))
        except (KeyError, TypeError, ValueError):
            _cs_input_dim_raw = 0
        _cs_input_dim = (
            _cs_input_dim_raw if _cs_input_dim_raw > 0 else ps_dim_e)
        try:
            _cs_input_n_raw = int(gsp(cfg, "ConceptualSpace", "nInput"))
        except (KeyError, TypeError, ValueError):
            _cs_input_n_raw = 0
        _cs_input_n = _cs_input_n_raw if _cs_input_n_raw > 0 else ps_n
        _ws_band_shape = tuple(_cshape("WholeSpace"))
        ws_dim_e = _effective_out_dim("WholeSpace", cs_dim_e)
        ws_n = _effective_out_count("WholeSpace", cs_n)
        ws_dim = ws_dim_e - sum(_ws_band_shape)
        _sparse_activation_boundary = (
            _aligned_serial_word
            and ps_n == ws_n == cs_n == _cs_input_n
            and ps_dim_e == ws_dim_e
            and _ps_band_shape == _ws_band_shape
            and _cs_input_dim == cs_dim_e
            and ps_dim == ws_dim
            and 0 < ps_dim < cs_dim)
        # A declared sentence-identity complement is an indexed extension of
        # each word's unchanged form, also on the small grammar fixtures'
        # mixing path. It does not reshape the perceptual slab.
        _meaning_extension = (
            is_embedding_mode and int(cfg.get('ConceptualSpace', {}).get('meaningWidth', 128)) >= 0
            and ps_n == cs_n == _cs_input_n and _cs_input_dim == ps_dim_e
            and cs_dim_e > ps_dim_e and (cs_dim_e-ps_dim_e) % 2 == 0)
        if (is_embedding_mode and not (ps_slab == cs_slab or _meaning_extension)
                and not _sparse_activation_boundary):
            errors.append(
                f"flat-slab invariant violated: PS.nOutput*content "
                f"({ps_n}*{ps_dim}={ps_slab}) must equal CS.nOutput*content "
                f"({cs_n}*{cs_dim}={cs_slab}), except when aligned "
                "serialObjectMeta uses equal native PS/WS peers followed by "
                "sparse sigma/codebook activation. That activation must "
                "already emit CS-width events. The configured geometry is "
                f"PS {ps_n}x{ps_dim_e}, WS {ws_n}x{ws_dim_e}, and CS input "
                f"{_cs_input_n}x{_cs_input_dim} -> output {cs_n}x{cs_dim_e}; "
                "IS may be larger (PS scopes the input down)."
            )
        if is_embedding_mode and _aligned_serial_word:
            if (ps_n != ws_n or ps_dim_e != ws_dim_e
                    or _ps_band_shape != _ws_band_shape):
                errors.append(
                    "aligned serialObjectMeta requires PS and WS to be "
                    "independent peers with identical native event geometry; "
                    f"got PS={ps_n}x{ps_dim_e} with band {_ps_band_shape} and "
                    f"WS={ws_n}x{ws_dim_e} with band {_ws_band_shape}. The "
                    "conceptual codebook activation widens both sources only "
                    "after their native folds; PS must not feed WS.")
            if (_cs_input_n != cs_n or _cs_input_dim != cs_dim_e):
                errors.append(
                    "aligned serialObjectMeta requires ConceptualSpace input "
                    "to match its conceptual output geometry because source "
                    "sigma/codebook activation owns the dimension increase; "
                    f"got CS input={_cs_input_n}x{_cs_input_dim} and output="
                    f"{cs_n}x{cs_dim_e}.")
        if is_embedding_mode and _serial_word_major:
            # The outer word traversal is configured independently by
            # <serialWordCapacity>.  PS/CS remain the canonical instantaneous
            # field and STM workspace, so their slot counts stay aligned with
            # STM capacity rather than expanding to the surface-word cap.
            try:
                _stm_cap = int(gsp(cfg, "ConceptualSpace", "stmCapacity"))
            except (KeyError, TypeError, ValueError):
                _stm_cap = 8
            if ps_n != _stm_cap or cs_n != _stm_cap:
                errors.append(
                    "serialObjectMeta field/workspace mismatch: "
                    f"PartSpace.nOutput={ps_n} and "
                    f"ConceptualSpace.nOutput={cs_n} must both equal "
                    f"stmCapacity={_stm_cap}. The independent outer sentence "
                    "limit belongs in <serialWordCapacity>.")

        # ---- Recurrent WS input and direct CS->OS head (fail-loud) ---
        # dimensional-governance Task C1 (doc/specs/2026-06-05-dimensional-
        # governance.md sec.4/sec.6; doc/plans/2026-06-06-dimensional-
        # governance-completion.md). BasicModel is not a linear
        # IS->PS->WS->CS->OS chain: PS, WS, and SS are peers feeding CS. Two
        # explicit shape contracts remain around that peer loop:
        #
        #   CS->WS : WS's recurrent INPUT accepts the prior conceptual event.
        #            WS still emits its native property-width peer state; this
        #            input compatibility is not a PS->WS dependency.
        #   CS->OS : the terminal output head consumes terminal CS directly.
        #            WholeSpace is an upstream property peer and is not an
        #            intermediate terminal producer.
        #
        # An UNSET consumer dim means "inherit the producer's width" (the
        # resolvers fall back to the producer value), so an omitted
        # <nInputDim> can never trip these -- only an EXPLICIT mismatching
        # value RAISES. Gated on embedding mode + non-passthrough to stay
        # consistent with the flat-slab and nWhat checks (legacy
        # SimpleModel / numeric / passthrough configs are untouched).
        def _effective_in_dim(space_name, fallback_dim):
            """nInputDim if explicitly set (>0), else the chained
            ``fallback_dim`` (the producer's output width)."""
            try:
                raw = gsp(cfg, space_name, "nInputDim")
                if raw and int(raw) > 0:
                    return int(raw)
            except KeyError:
                pass
            return int(fallback_dim)

        def _effective_in_count(space_name, fallback_count):
            try:
                raw = gsp(cfg, space_name, "nInput")
                if raw and int(raw) > 0:
                    return int(raw)
            except KeyError:
                pass
            return int(fallback_count)

        if is_embedding_mode:
            # CS recurrent feedback accepted by WS (event width). cs_dim_e is
            # CS's effective output event width resolved above.
            ws_in_dim = _effective_in_dim("WholeSpace", cs_dim_e)
            if ws_in_dim != cs_dim_e:
                errors.append(
                    f"CS->WS recurrent input inconsistent: "
                    f"WS.nInputDim={ws_in_dim} must equal "
                    f"CS.nOutputDim={cs_dim_e}. WS may then emit its native "
                    f"property-width peer state. Fix: set "
                    f"<WholeSpace><nInputDim> to "
                    f"{cs_dim_e} (or omit it to inherit CS.nOutputDim)."
                )
            # The output head is constructed from terminal CS, not WS. Keep
            # the direct event geometry exact; a coincidentally equal flattened
            # product with swapped count/dimension is not the same interface.
            os_in_dim = _effective_in_dim("OutputSpace", cs_dim_e)
            os_in_n = _effective_in_count("OutputSpace", cs_n)
            if os_in_n != cs_n or os_in_dim != cs_dim_e:
                errors.append(
                    f"CS->OS handoff inconsistent: terminal CS emits "
                    f"{cs_n}x{cs_dim_e}, but OutputSpace expects "
                    f"{os_in_n}x{os_in_dim}. The output head consumes CS "
                    "directly; WholeSpace is not an intermediate producer."
                )

        # Monotonicity ⟹ no ConceptualSpace projection codebook.
        # ``architecture.monotonic`` makes the subsymbolic loop
        # order-preserving (W>=0) so the ramsified codebook can match a
        # symbol mapped across orders via ``Ops.part``. A ConceptualSpace
        # projection codebook is a basis *expansion* to a wide prototype
        # space and is not reliably order-preserving, so it breaks that
        # invariant. Require the projection bypassed when monotonic.
        if bool(arch.get("monotonic", False)) and Space.normalize_codebook_mode(
                gsp(cfg, "ConceptualSpace", "codebook")) != "none":
            errors.append(
                "architecture.monotonic=True requires "
                "<ConceptualSpace><codebook>none</codebook>: a basis "
                "expansion (quantize/project codebook) is not order-"
                "preserving and breaks the monotone-loop invariant the "
                "ramsified symbolic match (Ops.part) depends on. Set "
                "<ConceptualSpace><codebook>none</codebook> or "
                "<architecture><monotonic>false</monotonic>.")

        # ---- Respect-explicit endpoint dims (fail-loud) -------------------
        # Task #11 (architecture-backlog §1, decision (3)). The endpoint space_roles
        # (InputSpace, OutputSpace) carry author-facing task widths: the input
        # cardinality and the OUTPUT TARGET cardinality the head must
        # represent. An EXPLICITLY-set <nDim> on these must be honoured
        # verbatim by ``_resolve_dim`` -- never silently replaced by the
        # chained upstream width or a canonical band-derived value. Assert the
        # resolver returns the explicit value (it does today; this pins the
        # contract so a future canonical-override regression fails loud here
        # instead of silently collapsing the head's target cardinality).
        for _endpoint, _prev in (("InputSpace", 1),
                                 ("OutputSpace", symbol_dim)):
            try:
                _raw = gsp(cfg, _endpoint, "nDim")
            except KeyError:
                continue  # omitted -> inherit sentinel, nothing to honour
            if _raw and int(_raw) > 0:
                _resolved = _resolve_dim(_endpoint, _prev)
                if int(_resolved) != int(_raw):
                    errors.append(
                        f"{_endpoint} explicit <nDim>={int(_raw)} was "
                        f"overridden to {int(_resolved)}: endpoint widths are "
                        f"honoured verbatim (respect-explicit, Task #11). The "
                        f"config-author-sized {_endpoint} width must not be "
                        f"silently canonical/chained-overridden.")

        # Invertible PartSpace shape constraints are registered inside
        # PartSpace._register_requirements() (not here) to keep them self-contained.
        percept_inv = gsp(cfg, "PartSpace", "invertible")

        # Warn only for the legacy naive reverse path. Non-naive inversion
        # uses the LDU/triangular-solve path and does not use pinv.
        naive = bool(arch.get("naive", False))
        if naive and percept_inv:
            warnings.warn(
                "PartSpace: architecture.naive=True materializes dense "
                "inverse weights on the reverse path. This is slower and less "
                "memory efficient than the non-naive LDU solve path. Consider "
                "setting <naive>false</naive> unless debugging the dense path.",
                stacklevel=2)

        if errors:
            raise ValueError(
                "XML config inconsistencies:\n  - " + "\n  - ".join(errors))

        # Fire any requirements registered above at validate_config time, so
        # they surface as config errors *before* model construction, alongside
        # the errors.append path.  Any remaining requirements registered later
        # (inside Space._register_requirements during __init__) will fire
        # via the second TheXMLConfig.validate() call at the end of
        # BasicModel.__init__.
        TheXMLConfig.validate()

    @staticmethod
    def resolve_xml(path):
        """Resolve an XML config path relative to the project directory.

        Tries the absolute path first, then ``PROJECT_DIR/path``, then
        ``PROJECT_DIR/data/path``. Returns the input unchanged if none
        of the candidates exist so the eventual open() surfaces the
        original argument in its error.
        """
        if os.path.isabs(path):
            return path
        # Try relative to project root first (handles "data/simple.xml")
        candidate = os.path.join(ProjectPaths.PROJECT_DIR, path)
        if os.path.exists(candidate):
            return candidate
        # Try inside data/ (handles bare "simple.xml")
        candidate = os.path.join(ProjectPaths.PROJECT_DIR, "data", path)
        if os.path.exists(candidate):
            return candidate
        return path

    @staticmethod
    def _brick_preflight(m, batch_size, lr):
        """CUDA-graph-capture pre-flight gate (all training entry).

        Profiles ONE short ``runEpoch`` and hard-aborts if the brick
        body issues any ``cudaMemcpyDtoH``: a host sync defeats
        CUDA-graph capture and silently wastes GPU on a non-capturable
        run, so fail fast *before* substantial training rather than
        after hours. CUDA-only -- on CPU/MPS ``torch.profiler`` records
        no device memcpy and the capture contract is CUDA-specific, so
        this is a no-op there (the MPS dev path is unaffected).

        Runs two short *bounded* epochs (warm-up + profiled) at the
        **real configured ``batchSize``**, ``max_batches`` each. The
        batch size must match training: a CUDA graph is captured for a
        specific shape, so a brick that is sync-free at ``bs=2`` says
        nothing about ``bs=64`` (the only shape that matters is the one
        training runs). Bounding the *number* of batches -- not their
        size -- keeps this cheap (a handful of real-shape steps), so the
        gate validates exactly what training will execute. These do NOT
        count against ``BASIC_MAX_BATCHES`` (the ``--batches`` budget):
        the pre-flight is diagnostic, so ``_preflight_active`` exempts
        it from the cumulative cap in ``runEpoch``. Without both the
        bound and the exemption, on a large corpus the warm-up consumes
        the whole ``--batches`` budget, leaving the profiled epoch (and
        the real training) with zero batches -- the gate then "passes"
        having profiled nothing, and no training happens.

        **MODEL_DEBUG-gated.** ``enable_compiled_step`` now compiles the
        forward with ``fullgraph=True`` -- a *static* no-graph-break /
        no-host-sync guarantee enforced at compile time (a regression
        *raises* during compile, not after hours of wasted GPU). That
        supersedes this runtime profiler-based DtoH gate, which costs an
        extra warm-up compile plus a Kineto-profiled compiled epoch on
        every production run. Keep it only as an opt-in cross-check
        under ``MODEL_DEBUG``; skip it (faster compiles, no double
        warm-up) otherwise.
        """
        if not _util.MODEL_DEBUG:
            return
        if not torch.cuda.is_available():
            return
        # Profile at the real training batch size (CUDA-graph capture is
        # shape-specialized -- validating a different shape is
        # meaningless). Cheapness comes from the max_batches bound, not
        # from shrinking the batch.
        bs = max(1, int(batch_size))
        # Bounded so a large corpus (MM_20M: 358k sentences) doesn't run
        # a full epoch here; enough to clear first-touch lazy-init
        # before the profiled pass.
        pf_warmup, pf_profile = 4, 2
        opt = m.getOptimizer(lr=lr)
        # O1: ModelFactory.run now calls m.enable_compiled_step() before
        # this, so runBatch routes through the torch.compiled callable.
        # This pre-flight therefore profiles the COMPILED step. (Prior
        # 58/430 cudaMemcpyDtoH figures were measured fully eager --
        # torch.compile was a no-op then -- and are moot. Re-measured
        # after the non-grammar break-elimination program.)
        m._preflight_active = True
        try:
            # Warm-up so first-touch lazy-init syncs aren't counted as
            # steady state (mirrors test_brick_no_sync).
            m.runEpoch(optimizer=opt, batchSize=bs, split="train",
                       max_batches=pf_warmup)
            with torch_profile(activities=[ProfilerActivity.CPU,
                                           ProfilerActivity.CUDA]) as prof:
                m.runEpoch(optimizer=opt, batchSize=bs, split="train",
                           max_batches=pf_profile)
        finally:
            m._preflight_active = False
        dtoh = [e for e in prof.events()
                if "memcpy" in e.name.lower() and "dtoh" in e.name.lower()]
        if dtoh:
            raise RuntimeError(
                f"Brick pre-flight FAILED: runEpoch issued {len(dtoh)} "
                f"cudaMemcpyDtoH event(s) -- the brick body is not "
                f"CUDA-graph-capture-ready. Substantial training is "
                f"aborted to avoid wasting GPU on a non-capturable run. "
                f"Example events: {[e.name for e in dtoh[:5]]}. Profile "
                f"and eliminate the host syncs (see "
                f"test/test_brick_no_sync.py and "
                f"doc/plans/2026-04-27-brick-vectorization-and-legacy-"
                f"removal-handoff.md §6), or train on CPU/MPS.")
        TheMessage("[brick] pre-flight OK: 0 cudaMemcpyDtoH in runEpoch")

    @staticmethod
    def run(config_path):
        """Main entry point -- create, train, and evaluate a model from XML config.

        Loads the dataset via ``TheData.load``, constructs the model
        through ``BaseModel.from_config``, compiles it, then runs
        training (optionally under cProfile). Returns
        ``[(name, rCorrect, model)]``. Honors a handful of ``BASIC_*``
        env vars for runtime overrides.
        """
        # Pre-read config for dataset loading (needed before create_from_config)
        defaults_path = os.path.join(ProjectPaths.DATA_DIR, "model.xml")
        init_config(path=config_path, defaults_path=defaults_path)
        cfg = TheXMLConfig.data
        arch = cfg.get("architecture", {})
        dat = arch.get("data", {})
        trn = arch.get("training", {})

        # Device hydration: env var wins (the MODEL_AMP/MODEL_COMPILE
        # precedent); XML <architecture><device> is a checked-in default
        # applied only when BASICMODEL_DEVICE is unset. The XOR_exact
        # gate fixtures pin <device>cpu</device>: MPS kernels are
        # nondeterministic, so a seeded gate is only reproducible on CPU.
        # The process-wide device is restored on exit so in-process
        # callers (tests, probes) are not left on the fixture's device.
        prev_device = None
        if not os.environ.get("BASICMODEL_DEVICE"):
            xml_device = arch.get("device")
            if xml_device:
                prev_device = str(TheDevice.get())
                init_device(str(xml_device).strip().lower())

        # Determinism: <training><seed> pins torch/python/numpy RNG for
        # the whole run (construction init + data order + training).
        # The XOR_exact gates are read as single CLI runs; unseeded,
        # their recon column is run-to-run flaky (predictions stable).
        seed = os.environ.get("BASIC_SEED", trn.get("seed"))
        if seed is not None:
            torch.manual_seed(int(seed))
            random.seed(int(seed))
            np.random.seed(int(seed))

        try:
            return ModelFactory._run_hydrated(config_path, arch, dat, trn)
        finally:
            if prev_device is not None:
                init_device(prev_device)

    @staticmethod
    def _run_hydrated(config_path, arch, dat, trn):
        """Post-hydration body of :meth:`run` (config parsed, device and
        seed applied). Split out so the device override restores in a
        ``finally`` regardless of how the run exits."""
        # AMP hydration: env var wins (matches MODEL_COMPILE precedent).
        # XML <architecture><amp> is a checked-in default applied only when
        # the env var is unset.
        if not os.environ.get("MODEL_AMP"):
            xml_amp = arch.get("amp")
            if xml_amp:
                os.environ["MODEL_AMP"] = str(xml_amp)
                init_model_amp()

        dataset = os.environ.get("BASIC_DATASET", dat.get("dataset"))
        # Environment overrides for num_shards/max_docs (set by train.py)
        num_shards = int(os.environ.get("BASIC_NUM_SHARDS", dat.get("numShards", 1)))
        max_docs = int(os.environ.get("BASIC_MAX_DOCS", dat.get("maxDocs", 10000)))
        max_tokens_env = os.environ.get("BASIC_MAX_TOKENS")
        max_tokens = int(max_tokens_env) if max_tokens_env else None
        max_sentence_words_env = os.environ.get(
            "BASIC_MAX_SENTENCE_WORDS")
        max_sentence_words = int(
            max_sentence_words_env
            if max_sentence_words_env is not None
            else dat.get("maxSentenceWords", 0) or 0) or None
        random_shards = os.environ.get("BASIC_RANDOM_SHARDS", "0") == "1"

        TheData.load(dataset,
                     num_shards=num_shards,
                     max_docs=max_docs,
                     shard_dir=dat.get("shardDir"),
                     dat=dat,
                     random_shards=random_shards,
                     max_tokens=max_tokens,
                     max_sentence_words=max_sentence_words)

        target_device = TheDevice.get()
        if target_device.type == "mps":
            # MPS construction can corrupt setup-time parameter tensors in
            # large radix/byte configs (finite CPU construction of the same
            # config is clean, and a subsequent module move to MPS is clean).
            # Build the module tree on CPU, then move registered parameters
            # and buffers to the requested MPS device before training. Runtime
            # forward/backward still executes on MPS because TheDevice is
            # restored immediately after construction.
            init_device("cpu")
            try:
                m, _ = BaseModel.from_config(config_path, data=TheData)
            finally:
                init_device(target_device)
            m.to(target_device)
        else:
            m, _ = BaseModel.from_config(config_path, data=TheData)
        TheMessage(f"Device: {TheDevice}")

        # O1: `compile(m)` on the module is a no-op here -- `m.run()`
        # delegates to the eager `_orig_mod`, so the compiled callable
        # never ran. Compile the per-batch forward callable and invoke
        # it from runBatch instead (eager streaming stays outside).
        m.enable_compiled_step()

        def _t(key, default=None):
            return trn.get(key, default)

        def _d(key, default=None):
            return dat.get(key, default)

        num_epochs = int(os.environ.get("BASIC_NUM_EPOCHS", _t("numEpochs", 3)))
        batch_size = int(os.environ.get(
            "BASIC_BATCH_SIZE", _t("batchSize", 10)))

        # CUDA-graph-capture pre-flight: gates ALL training entry (the
        # profiled path and the normal path) for every model run via
        # train.py. Hard-aborts before substantial training if the
        # brick body still issues host syncs. CUDA-only no-op elsewhere.
        ModelFactory._brick_preflight(
            m, batch_size, _t("learningRate", 0.01))

        do_profile = os.environ.get("BASIC_PROFILE", "").lower() in ("1", "true") or _t("profile", False)
        if do_profile:
            with torch_profile(
                activities=[ProfilerActivity.CPU],
                schedule=profiler_schedule(wait=1, warmup=1, active=3, repeat=1),
                record_shapes=True,
                profile_memory=True,
                with_stack=True,
            ) as prof:
                m.run(_t("numTrials", 1),
                            num_epochs,
                            batch_size,
                            lr=_t("learningRate", 0.01), profile=prof)

            # Print summary table
            TheMessage(prof.key_averages().table(sort_by="cpu_time_total", row_limit=30))

            # Export Chrome trace
            trace_path = ProjectPaths.output_path("profile_trace.json")
            prof.export_chrome_trace(trace_path)
            TheMessage(f"Chrome trace saved to {trace_path}")
            return [(m.name, m.rCorrect, m)]

        m.run(_t("numTrials", 1),
                    num_epochs,
                    batch_size,
                    lr=_t("learningRate", 0.01))

        _autosave_env = os.environ.get("BASIC_AUTOSAVE")
        _autosave = bool(_t("autosave", False))
        if _autosave_env is not None:
            _autosave = _autosave_env.strip().lower() in (
                "1", "true", "yes", "on")
        if _autosave:
            m.save_training_checkpoint(reason="final autosave")

        return [(m.name, m.rCorrect, m)]
BasicModelFactory = ModelFactory

def test():
    """Smoke test: verify encodings and run the XOR config end-to-end.

    Touches ``WhereEncoding`` / ``WhenEncoding`` self-tests, then runs
    the XOR XML config to exercise the full model factory path.
    """
    WhereEncoding.test()
    WhenEncoding.test()
    ModelFactory.run(os.path.join(ProjectPaths.PROJECT_DIR, "data", "xor.xml"))


# --- CLI entry point ---
# Usage: python BasicModel.py [config.xml]
#        python BasicModel.py --compare config1.xml config2.xml
if __name__ == "__main__":
    import sys
    import argparse

    parser = argparse.ArgumentParser(
        prog="BasicModel.py",
        description=(
            "Train and evaluate a BasicModel from an XML config file.\n\n"
            "Examples:\n"
            "  python BasicModel.py data/xor.xml\n"
            "  python BasicModel.py data/XOR_spaces.xml\n"
            "  python BasicModel.py --compare data/xor.xml data/XOR_exact.xml\n"
        ),
        formatter_class=argparse.RawDescriptionHelpFormatter,
    )
    parser.add_argument(
        "config",
        nargs="?",
        default=None,
        metavar="CONFIG",
        help=(
            "Path to the XML config file (relative to data/ or absolute). "
            "Defaults to data/xor.xml when omitted."
        ),
    )
    parser.add_argument(
        "--compare",
        nargs=2,
        metavar=("CONFIG1", "CONFIG2"),
        help=(
            "Run two configs side by side and plot per-digit accuracy, "
            "combined accuracy, and combined loss comparisons."
        ),
    )
    parser.add_argument(
        "--report",
        action="store_true",
        default=False,
        help="Generate figures and HTML report at the end of the run.",
    )
    parser.add_argument(
        "--compile",
        default=None,
        metavar="BACKEND",
        help=(
            "Compilation backend: none, inductor, eager, aot_eager. "
            "Overrides MODEL_COMPILE env var."
        ),
    )
    parser.add_argument(
        "--profile",
        action="store_true",
        default=False,
        help="Profile the model's training step using torch.profiler (overrides XML <training><profile>).",
    )
    args = parser.parse_args()

    if args.compile is not None:
        init_compile_backend(args.compile)

    if args.profile:
        os.environ["BASIC_PROFILE"] = "true"

    TheReport.enabled = args.report

    try:
        if args.compare:
            # Compare mode: run two XML configs and plot per-digit accuracy side by side
            xml1 = ModelFactory.resolve_xml(args.compare[0])
            xml2 = ModelFactory.resolve_xml(args.compare[1])
            TheReport.add_xml(xml1)
            TheReport.add_xml(xml2)
            results = ModelFactory.run(xml1) + ModelFactory.run(xml2)
            if len(results) >= 2:
                TheReport.plotComparison([(name, rc) for name, rc, _ in results])
                TheReport.plotCombinedAccuracy([(name, rc) for name, rc, _ in results])
                TheReport.plotCombinedLoss([m for _, _, m in results])
        else:
            # Single run mode
            xml = ModelFactory.resolve_xml(args.config) if args.config else os.path.join(ProjectPaths.PROJECT_DIR, "data", "xor.xml")
            TheReport.add_xml(xml)
            results = ModelFactory.run(xml)
    finally:
        import gc
        gc.collect()
        if torch.cuda.is_available():
            torch.cuda.empty_cache()

    TheReport.write_html()
